(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("appian-foreign-wars-1-e", [{"sp": "HDR", "t": "Ῥωμαϊκά"}, {"sp": "HDR", "t": "Ἐκ τῆς Βασιλικῆς", "st": "2"}, {"sp": "N", "t": "ἄρχεται τῆς ἱστορίας ἀπὸ Αἰνείου τοῦ Ἀγχίσου τοῦ Κάπυος, ὃς ἐν τῷ Τρωικῷ ἤκμαζε πολέμῳ, μετὰ δὲ τὴν ἅλωσιν τῆς Τροίας ἔφυγε, καὶ μετὰ μακρὰν πλάνην κατέπλει ἔς τινα τῆς Ἰταλίας αἰγιαλόν, Λώρεντον ἐπικαλούμενον, ἔνθα καὶ στρατόπεδον αὐτοῦ δείκνυται, καὶ τὴν ἀκτὴν ἀπ’ ἐκείνου Τροίαν καλοῦσιν. ἦρχε τότε Ἀβοριγίνων τῶν τῇδε Ἰταλῶν Φαῦνος ὁ τοῦ Ἄρεως, ὃς καὶ ζεύγνυσιν Αἰνείᾳ τὴν θυγατέρα αὑτοῦ Λαουινίαν, καὶ γῆν δίδωσιν ἐκ περιόδου σταδίων τετρακοσίων. ὁ δὲ πόλιν ἔκτισε καὶ ἀπὸ τῆς γυναικὸς Λαουίνιον ἐπωνόμασε. τρίτῳ δὲ ἔτει τοῦ Φαύνου τελευτήσαντος ἐκδέχεται τὴν ἀρχὴν ὁ Αἰνείας κατὰ τὸ κῆδος, καὶ τοὺς Ἀβοριγίνας ἀπὸ τοῦ κηδεστοῦ Λατίνου Φαύνου Λατίνους ἐπωνόμασε. τρίτῳ δὲ ἔτει πάλιν διὰ Λαουινίαν τὴν γυναῖκα ὑπὸ Ῥουτούλων τῶν Τυρρηνῶν, προμνηστευθεῖσαν αὐτῶν τῷ βασιλεῖ, ἀναιρεῖται πολέμου νόμῳ ὁ Αἰνείας, καὶ τὴν ἀρχὴν διεδέξατο Εὐρυλέων, Ἀσκάνιος μετονομασθείς, ὃς ἐγεννήθη τῷ Αἰνείᾳ ἐκ Κρεούσης τῆς Πριάμου, τῆς ἐν Ἰλίῳ γενομένης αὐτῷ γυναικός. οἱ δὲ ἐκ τῆς Λαουινίας Ἀσκάνιον αὐτῷ γεννηθῆναί φασι, τὸν διάδοχον τῆς ἀρχῆς.", "st": "2.1"}, {"sp": "N", "t": "Ἀσκανίου δὲ τελευτήσαντος ἔτει τετάρτῳ μετὰ τὴν Ἄλβης οἴκισιν (καὶ γὰρ οὗτος ἔκτισε πόλιν, Ἄλβην καλέσας, καὶ ἀπὸ Λαουινίου τὸν λαὸν μετῴκισεν) ἐκδέχεται τὴν ἀρχὴν Σίλουιος. καὶ Σιλουίου παῖδα Αἰνείαν Σίλουιόν φασιν, Αἰνείου δὲ Λατῖνον Σίλουιον, τοῦ δὲ Κάπυν, Κάπυος δὲ Κάπετον γενέσθαι, Καπέτου δὲ Τιβερῖνον, τοῦ δὲ Ἀγρίππαν, τοῦ δὲ Ῥωμύλον. καὶ τόνδε μὲν βληθῆναι κεραυνῷ· οὗ γενέσθαι παῖδα Ἀουεντῖνον, Ἀουεντίνου δὲ Πρόκαν γενέσθαι. καὶ πᾶσι δὲ τὸν Σίλουιον ἐπώνυμον εἶναι. τῷ δὲ Πρόκᾳ δύο ἐγενέσθην υἱοί, πρεσβύτερος μὲν Νεμέτωρ, νεώτερος δὲ Ἀμούλιος. λαβόντος δὲ τοῦ πρεσβυτέρου παρὰ τοῦ πατρὸς τελευτῶντος τὴν ἀρχήν, ὁ νεώτερος ὕβρει καὶ βίᾳ κατέσχεν ἀφελόμενος. καὶ τὸν μὲν παῖδα τοῦ ἀδελφοῦ Ἔγεστον κτείνει, τὴν θυγατέρα δὲ Ῥέαν Σιλουίαν ἱέρειαν, ἵνα ἄπαις διαμείνῃ, καθίστησι· τὸν μέντοι Νεμέτορα τῆς εἰς τὸ σῶμα ἐπιβουλῆς ἡ τῶν ἠθῶν ἐξεῖλε πραότης καὶ ἡ πολλὴ ἐπιείκεια. ἀλλ’ ἡ Σιλουία ἔκυε παρὰ τὸν νόμον. καὶ τὴν μὲν Ἀμούλιος ἐπὶ κολάσει συνελάμβανε, δύο δὲ παῖδας ἐκ τῆσδε γενομένους ποιμέσιν ἔδωκεν, εἰς τὸν πλησίον ποταμὸν ἐμβαλεῖν τὰ βρέφη· Θύβρις ἦν ὄνομα τῷ ποταμῷ, Ῥῶμος δὲ καὶ Ῥωμύλος οἱ παῖδες, ἐξ Αἰνείου ἕλκοντες μητρόθεν τὸ γένος· τὸ γὰρ τοῦ φύντος ἄδηλον.", "st": "2.1"}, {"sp": "N", "t": "ὁ μὲν πρῶτος τόμος τῶν ἑπτὰ βασιλέων, Ῥωμύλου, Νουμᾶ Πομπιλίου, Ἄγκου Ὁστιλίου καὶ Ἄγκου ἑτέρου τοῦ καὶ Μαρκίου, ἐπιγόνου Νουμᾶ, Ταρκυνίου, Σερουίου Τυλλίου, καὶ Ταρκυνίου Λευκίου τοῦ Ταρκυνίου, τούτων τῶν ἑπτὰ ἔργα τε καὶ πράξεις περιέχει. ὧν ὁ πρῶτος κτίστης τε Ῥώμης καὶ οἰκιστὴς γεγονώς, ἄρξας τε πατρικῶς μᾶλλον ἢ τυραννικῶς, ὅμως ἐσφάγη, ἢ ὡς ἄλλοι φασίν, ἠφανίσθη. ὁ δὲ δεύτερος οὐδὲν ἧττον βεβασιλευκώς, εἰ μὴ καὶ μᾶλλον, τὸν ἑαυτοῦ βίον ἐτελεύτησε ζήσας … ὁ δὲ τρίτος ἐκεραυνώθη. νόσῳ δὲ τὸν βίον ὁ τέταρτος ὑπεξῆλθεν. ὁ δὲ πέμπτος ὑπὸ ποιμένων ἐσφάγη, καὶ ὁ ἕκτος ὁμοίως σφαγῇ κατέστρεψε τὸν βίον. ὁ δὲ ἕβδομος καὶ τῆς πόλεως καὶ τῆς βασιλείας παρανομῶν ἐξηλάθη· ἐξ οὗ τῆς βασιλείας καταλυθείσης εἰς τοὺς ὑπάτους τὰ τῆς ἀρχῆς μετετέθη.", "st": "2.2"}, {"sp": "N", "t": "ἡ δὲ τὸν πατέρα φυλάξασα ἀποδημοῦντα ὑπισχνεῖται Τατίῳ προδώσειν τὸ φρούριον.", "st": "2.3"}, {"sp": "N", "t": "κελεύσαντος δὲ Τατίου τὸν χρυσὸν ἐς τὴν παῖδα ἐλίθαζον, ἔστε τιτρωσκομένη κατεχώσθη.", "st": "2.4"}, {"sp": "N", "t": "ὅτι τὸν πόλεμον τὸν πρὸς Ῥωμύλον Τατίου αἱ Ῥωμαίων γυναῖκες καὶ Σαβίνων θυγατέρες διῄ τησαν, αὐταὶ τῷ χάρακι τῶν γονέων προσελθοῦσαι, χεῖράς τε προτείνουσαι, καὶ βρέφη τὰ ἤδη σφίσιν ἐκ τῶν ἀνδρῶν γενόμενα ἐπιδεικνύουσαι, καὶ τοῖς ἀνδράσι μαρτυροῦσαι μηδὲν ὑβριστικὸν ἐς αὐτὰς ἁμαρτεῖν. ἐδέοντό τε λαβεῖν τινὰ οἶκτον τοὺς Σαβίνους σφῶν τε αὐτῶν καὶ κηδεστῶν καὶ ἐκγόνων καὶ θυγατέρων, καὶ φείσασθαι συγγενοῦς καὶ μιαροῦ πολέμου, ἢ πρώτας ἀνελεῖν αἳ τὴν αἰτίαν ἔχουσι τοῦ πολέμου. οἱ δὲ τῶν τε παρόντων ἀπορίᾳ καὶ οἴκτῳ τῶν γυναικῶν, συγγιγνώσκοντες ἤδη μὴ καθ’ ὕβριν εἰργάσθαι ταῦτα Ρωμαίους ἀλλ’ ὑπὸ χρείας, ἐς τὰς διαλλαγὰς ἐνεδίδουν. καὶ συνελθόντες Ῥωμύλος τε καὶ Τάτιος ἐς τὴν ἐξ ἐκείνου ἱερὰν γενομένην ὁδὸν ἐπὶ τοῖσδε συνέβησαν, βασιλεύειν μὲν ἄμφω, Τάτιόν τε καὶ Ῥωμύλον, Σαβίνους δὲ τοὺς τότε τῷ Τατίῳ συστρατεύσαντας, καὶ εἴ τινες ἄλλοι τῶν Σαβίνων ἐθέλοιεν, ἐς τὸ Ῥωμαίων μετοικίζεσθαι ἐπ’ ἴσῃ καὶ ὁμοίᾳ.", "st": "2.5"}, {"sp": "N", "t": "ὁ δὲ στρατηγὸς αἰσθόμενος παρ’ ἰδιοξένων ἐξήγγειλεν Ὁστιλίῳ.", "st": "2.6"}, {"sp": "N", "t": "οἱ δὲ ἐβλασφήμουν αὐτὸν ὡς κακῶς ἐπὶ τρισὶν ἀνδράσι τὰ πάντα θέμενον.", "st": "2.7"}, {"sp": "N", "t": "συμβάσεις ποιεῖν ἐφ’ οἷς ἂν Γάβιοι δικαιῶσιν.", "st": "2.8"}, {"sp": "N", "t": "ὠνεῖται τὰ τρία βιβλία τῆς τιμῆς τῶν ἐννέα.", "st": "2.9"}, {"sp": "N", "t": "ὁ δὲ Ὁράτιος λελωβημένος ἦν τὰ σκέλη, ὑπατείας τε οὐκ ἔτυχεν οὔτε ἐν πολέμῳ οὔτε ἐν εἰρήνῃ διὰ τὴν ἀχρηστίαν τῶν ποδῶν.", "st": "2.10"}, {"sp": "N", "t": "οἱ ὕπατοι τὰ ὅρκια προύτεινον, καὶ ἐς πάντα ἔφασαν ἐνδώσειν μᾶλλον ἢ Ταρκύνιον προσήσεσθαι.", "st": "2.11"}, {"sp": "N", "t": "ὅτι Ταρκύνιος Σαβίνους κατὰ Ῥωμαίων ἠρέθιζε. Κλαύδιος δέ, ἀνὴρ Σαβῖνος ἐκ Ῥηγίλλου πόλεως δυνατός, οὐκ εἴα τοὺς Σαβίνους παρασπονδεῖν, ἕως κρινόμενος ἐπὶ τῷδε ἔφυγεν ἐς Ῥώμην μετὰ συγγενῶν καὶ φίλων καὶ δούλων πεντακισχιλίων. οἷς πᾶσι Ῥωμαῖοι χώραν ἐς οἰκίας ἔδοσαν καὶ γῆν ἐς γεωργίαν, καὶ πολίτας ἔθεντο. τὸν δὲ Κλαύδιον καὶ ἐς τὸ βουλευτήριον κατέλεξαν, ἀποδεικνύμενον ἔργα λαμπρὰ κατὰ τῶν Σαβίνων· καὶ φυλὴν ἐπώνυμον αὐτοῦ κατέστησαν.", "st": "2.12"}, {"sp": "N", "t": "Λατῖνοι ἔνσπονδοι Ῥωμαίοις ὄντες ἐστράτευον ἐπ’ αὐτούς … οἱ δὲ Λατῖνοι ἐγκλήματα εἰς Ῥωμαίους ἐποιοῦντο τήν τε πάρεσιν αὐτῶν τὴν ἐπὶ σφᾶς ὄντας ἐνσπόνδους καὶ συγγενεῖς.", "st": "2.13"}, {"sp": "HDR", "t": "Ἐκ τῆς Ἰταλικῆς", "st": "3"}, {"sp": "N", "t": "Οὐολοῦσκοι δὲ τοῖς πταίσμασι τῶν γειτόνων οὐ καταπλαγέντες ἐστράτευον ἐπὶ Ῥωμαίους, καὶ ἐπολιόρκουν τοὺς αὐτῶν κληρούχους.", "st": "3.1"}, {"sp": "N", "t": "ὁ δὲ δῆμος τὸν Μάρκιον μετιόντα τὴν ὑπατείαν οὐκ ἐχειροτόνησεν, οὐ τὸν ἄνδρα ἀπαξιῶν, ἀλλὰ τὸ φρόνημα δεδιὼς αὐτοὺ.", "st": "3.2"}, {"sp": "N", "t": "ο Μάρκιος πιμπράμενος ἐπὶ Ῥωμαίοις, φυγὴν καταδικασθείς, καὶ μικρὸν ἐς αὐτοὺς οὐδὲν ἐπινοῶν ἐς Οὐολούσκους ἐτράπετο.", "st": "3.3"}, {"sp": "N", "t": "ὅτι πατρίδα καὶ γένος ἀλλαξάμενος ἥκοι, τὸ μηδὲν ἡγησάμενος, καὶ τὰ τῶν Οὐολούσκων ἀντὶ τῆς πατρίδος αἱρήσεσθαι βουληθείς.", "st": "3.4"}, {"sp": "N", "t": "ὅτι τοῦ Μαρκίου φυγαδευθέντος καὶ ἐς Οὐολούσκους καταφυγόντος καὶ κατὰ Ῥωμαίων ἐκστρατεύσαντος καὶ τεσσαράκοντα σταδίους ἀποσχόντος ἀπὸ τοῦ ἄστεος καὶ στρατοπεδεύσαντος, ὁ δῆμος ἠπείλει τῇ βουλῇ παραδώσειν τὰ τείχη τοῖς πολεμίοις, εἰ μὴ πρεσβεύσοιντο περὶ διαλλαγῶν πρὸς Μάρκιον. ἡ δὲ μόλις ἐξέπεμψεν αὐτοκράτορας εἰρήνης πέρι Ῥωμαίοις πρεπούσης, οἳ προελθόντες ἐς τὸ Οὐολούσκων στρατόπεδον Μαρκίῳ μετὰ Οὐολούσκων ἀκροωμένῳ προύτειναν ἀμνηστίαν καὶ κάθοδον, εἰ καταλύσει τὸν πόλεμον, τῆς τε βουλῆς αὐτὸν ὑπεμίμνησκον ὡς οὐχ ἁμαρτούσης ἐς αὐτόν. ὁ δὲ πολλὰ τοῦ δήμου κατηγορήσας περὶ ὧν ἐς αὐτὸν καὶ Οὐολούσκους ἐξημαρτήκεσαν, ἐπηγγέλλετο ὅμως Οὐολούσκους αὐτοῖς διαλλάξειν, ἂν ἥν τε γῆν ἔχουσι Οὐολούσκων καὶ τὰς πόλεις ἀποδῶσι, καὶ ποιήσωνται πολίτας ὥσπερ Λατίνους. ἕως δ’ ἂν ἔχωσι τὰ τῶν κρατούντων οἱ κρατούμενοι, οὐχ ὁρᾶν τίνες αὐτοῖς ἔσονται διαλύσεις. ταῦτα μετοίσοντας ἀπέλυε τοὺς πρέσβεις, καὶ τριάκοντα ἡμέρας ἐς τὴν σκέψιν ἐδίδου. τραπεὶς δ’ ἐπὶ τοὺς ἄλλους Λατίνους ἑπτὰ πόλεις αὐτῶν εἷλε ταῖς τριάκοντα ἡμέραις, καὶ ἧκεν ἐπὶ τὰς ἀποκρίσεις.", "st": "3.5"}, {"sp": "N", "t": "οἱ δὲ ἀπεκρίναντο, ἐὰν ἐκ τῆς Ῥωμαίων γῆς ἀπαγάγῃ τὸν στρατόν, πέμψειν τοὺς συνθησομένους αὐτῷ τὰ πρέποντα. πάλιν δ’ ἀντειπόντος ἔπεμπον ἑτέρους δέκα δεησομένους μηδὲν ἀνάξιον ποιεῖν τῆς πατρίδος, μηδ’ ἐξ ἐπιτάγματος ἀλλ’ ἑκουσίους ἐᾶν γίγνεσθαι τὰς συνθήκας, αἰδούμενόν τε τὴν πατρίδα, καὶ τὸ τῶν προγόνων ἀξίωμα τιμῶντα τῶν ἐς αὐτὸν οὐχ ἁμαρτόντων. ὁ δὲ τοσοῦτον αὐτοῖς ἀπεκρίνατο, τριῶν ἄλλων ἡμερῶν ἥκειν βουλευσαμένους τι κάλλιον. οἱ μὲν δὴ τοὺς ἱερέας ἔπεμπον, ταῖς ἱεραῖς ἐσθῆσιν ἐσταλμένους, ταὐτὰ τοῦ Μαρκίου δεησομένους· ὁ δὲ καὶ τούτοις ἔφη δεῖν ἢ τὰ κελευόμενα ποιεῖν, ἢ μηδ’ αὖ ἀφικνεῖσθαι πρὸς αὐτόν. ἐς οὖν πολιορκίαν καθίσταντο, καὶ τὸ τεῖχος ἐπλήρουν λίθων καὶ βελῶν ὡς ἄνωθεν ἀμυνούμενοι Μάρκιον.", "st": "3.5"}, {"sp": "N", "t": "Οὐαλερία δ’ ἡ Ποπλικόλα θυγάτηρ πολλὰς ἀγομένη γυναῖκας ἐπί τε τὴν μητέρα τοῦ Μαρκίου Οὐετουρίαν καὶ ἐπὶ τὴν γυναῖκα Οὐολουμνίαν, πένθιμα ἠμφιεσμέναι πᾶσαι, καὶ τὰ παιδία ταῖς ἱκεσίαις ἐπιφέρουσαι, συνεξελθεῖν αὑταῖς πρὸς Μάρκιον ἠξίουν αὐτάς, καὶ δεηθῆναι φείσασθαι σφῶν τε αὐτῶν καὶ τῆς πατρίδος. αἱ μὲν δὴ τῆς βουλῆς ἐπιτρεπούσης ἐξῄεσαν, μόναι γυναῖκες, ἐς ἐχθρῶν στρατόπεδον· ὁ δὲ Μάρκιος θαυμάζων τῆς εὐτολμίας τὴν πόλιν, οἷα Ῥωμαίων ἐστὶ καὶ τὰ γύναια, προσιούσαις ἀπήντα, καὶ τὰς ῥάβδους καθῄρει καὶ τοὺς πελέκεας διὰ τὴν μητέρα, προσδραμών τε ἠσπάζετο, καὶ ἦγεν ἐπὶ τὸ συνέδριον τῶν Οὐολούσκων, καὶ λέγειν ἐκέλευσεν ὅ τι χρῄζοι.", "st": "3.5"}, {"sp": "N", "t": "ἡ δὲ συνηδικῆσθαι μὲν ἐξελαυνομένῳ τῆς πόλεως, μήτηρ οὖσα, ἔφη, ὁρᾶν δ’ ὅτι Ῥωμαῖοι πολλὰ πρὸς αὐτοῦ πεπόνθασιν ἤδη καὶ τίσιν ἔτισαν ἱκανήν, ὧν χώρα τε τοσαύτη διέφθαρται καὶ πόλεις ἀπολώλασι πολλαί, καὶ τὸ Ῥωμαίοις ἔσχατον, παρακαλοῦσι καὶ πρέσβεις πέμπουσιν ὑπάτους καὶ ἱερέας καὶ μητέρα καὶ γυναῖκα, τό τε ἀδίκημα ἰῶνται ἀμνηστίᾳ καὶ καθόδῳ. “σὺ δὲ μὴ ἀνιάτῳ κακῷ τὸ κακὸν ἰῶ, μηδὲ συμφοραῖς ἐπιχείρει κοιναῖς αὐτοῦ τε σοῦ καὶ τῶν ἀδικούντων. ποῖ φέρων οἴσεις τὸ πῦρ; μετὰ τὴν χώραν ἐπὶ τὴν πόλιν; μετὰ τὴν πόλιν ἐπὶ τὴν ἑστίαν τὴν σήν; μετὰ τὴν ἑστίαν ἐπὶ τὰ ἱερά; δὸς χάριν, ὦ παῖ, κἀμοὶ καὶ τῇ πατρίδι παρακαλούσαις.” ἡ μὲν δὴ τοσαῦτα εἶπεν, ὁ δὲ Μάρκιος οὐκ εἴα πατρίδα καλεῖν τὴν ἐκβαλοῦσαν ἀλλὰ τὴν ὑποδεδεγμένην· οὐδὲν γὰρ εἶναι φίλιον, ἂν ἀδικῇ, οὐδὲ ἐχθρὸν εὖ ποιοῦν· καὶ τὸ τῶν παρόντων ἐκέλευεν ὁρᾶν, πίστιν τε δόντων αὐτῷ καὶ λαβόντων, καὶ πολίτην πεποιημένων καὶ στρατηγὸν ἀποφηνάντων καὶ τὰ ἴδια ἐπιτρεψάντων. τιμάς τε ὅσων ἠξίωτο, καὶ ὅρκους οὓς ὤμοσεν αὐτοῖς, ἐπεξῄει, καὶ παρεκάλει τὴν μητέρα τοὺς αὐτοὺς ἐκείνοις τίθεσθαι πολεμίους καὶ φίλους.", "st": "3.5"}, {"sp": "N", "t": "ἡ δὲ ἔτι λέγοντος ἀγανακτήσασα καὶ τὰς χεῖρας ἐς τὸν οὐρανὸν ἀνασχοῦσα, θεοὺς γενεθλίους ἐμαρτύρατο δύο μὲν ἤδη πρεσβείας γυναικῶν ἀπὸ Ῥώμης ἐν μεγάλοις ἐστάλθαι κακοῖς, ἐπὶ Τατίου βασιλέως καὶ Γαΐου Μαρκίου, τούτοιν δὲ Τάτιον μέν, ὄντα ξένον καὶ ἀληθῆ πολέμιον, ἐνδοῦναι ταῖς γυναιξὶν αἰδούμενον, Μάρκιον δ’ ὑπερορᾶν πρεσβείας γυναικῶν τοσῶνδε, καὶ τῆς γεγαμημένης καὶ μητρὸς ἐπὶ ταύταις. “ἄλλη μὲν οὖν,” ἔφη, “μηδεμία μήτηρ, ἀτυχοῦσα παιδός, ἐς ἀνάγκην ἀφίκοιτο προσπεσεῖν αὐτῷ· ἐγὼ δὲ καὶ τοῦτο ὑφίσταμαι· προκυλίσομαί σου.” καὶ λέγουσα ἐς τὸ ἔδαφος ἑαυτὴν ἐρρίπτει. ὁ δὲ ἐδάκρυσέ τε καὶ ἀνεπήδα καὶ ἀντείχετο αὐτῆς, ὑπό τε τοῦ πάθους ἐξεφώνησε, “νικᾷς, ὦ μῆτερ, ἀλλὰ νίκην ἐξ ἧς τὸν υἱὸν ἀπολεῖς.” ταῦτα εἰπὼν ἀπῆγε τῆν στρατιὰν ὡς λόγον ἀποδώσων Οὐολούσκοις καὶ τὰ ἔθνη συναλλάξων· ἐλπίς τε ἦν ὅτι καὶ ταῦτα πείσει Οὐολούσκους. κατελεύσθη δὲ φθονούμενος παρὰ τοῦ στρατηγοῦ Ἀττίου.", "st": "3.5"}, {"sp": "N", "t": "ὁ δὲ Μάρκιος ἀντιλέγειν μὲν πρὸς οὐδὲ ἓν αὐτῶν ἐδικαίου.", "st": "3.5b"}, {"sp": "N", "t": "ἐλεεινοὶ τοῦ πάθους, ἀξιέπαινοι τῆς ἀρετῆς γενόμενοι. μέγα γὰρ τοῦτο Ῥωμαίοις πάθος ἐγένετο καὶ πλήθους ἕνεκα καὶ ἀξιώματος εὐγενοῦς οἴκου καὶ πανωλεθρίας. καὶ τὴν ἡμέραν ἀποφράδα τίθενται.", "st": "3.6"}, {"sp": "N", "t": "τῷ δὲ στρατηγῷ στρατὸς ἦν δυσπειθὴς ὑπὸ μνησικακίας, ἐθελοκάκως τε ἠγωνίζοντο, καὶ ἔφευγον ἐπιδησάμενοι τὰ σώματα ὡς τετρωμένοι, καὶ τὰς σκηνὰς διέλυον, καὶ ἀναχωρεῖν ἐπεχείρουν, ἀπειρίαν ἐπικαλοῦντες τῷ στρατηγῷ.", "st": "3.7"}, {"sp": "N", "t": "ὅτι σημειων γενομενων ἐκ Διὸς ἀηδῶν μετὰ τὴν Οὐηιεντίας ἅλωσιν, οἱ μάντεις ἔλεγον ἐκλειφθῆναί τινα πρὸς εὐσέβειαν, καὶ ὁ Κάμιλλος ἀνήνεγκεν ὅτι τὴν δεκάτην τῆς λείας ἐκλάθοιτο τῷ θεῷ τῷ χρήσαντι περὶ τῆς λίμνης ἐξελέσθαι. ἡ μὲν οὖν βουλὴ τοὺς λαβόντας ὁτιοῦν ἐκ τῆς Οὐηιέντης ἐκέλευσεν ἀποτιμήσασθαι καθ’ αὑτοὺς καὶ σὺν ὅρκῳ τὸ δέκατον εἰσενεγκεῖν, ὑπὸ δὲ εὐσεβείας οὐκ ὤκνησε καὶ τῆς γῆς ἤδη πεπραμένης, ὡς λαφύρου, τὸ δέκατον ἀναθεῖναι. κρατήρ τε ἀπὸ τῶνδε τῶν χρημάτων ἐν Δελφοῖς ἔκειτο χρύσεος ἐπὶ χαλκῆς βάσεως ἐν τῷ Ῥωμαίων καὶ Μασσαλιητῶν θησαυρῷ, μέχρι τὸν μὲν χρυσὸν Ὀνόμαρχος ἐν τῷ Φωκικῷ πολέμῳ κατεχώνευσε, κεῖται δ’ ἡ βάσις.", "st": "3.8"}, {"sp": "N", "t": "αὐτὸν δὲ Κάμιλλον ἐν τῷ δήμῳ τις ἐδιωκεν ὡς αἴτιον γεγονότα τῇ πόλει φασμάτων καὶ τεράτων χαλεπῶν, καὶ ὁ δῆμος ἐκ πολλοῦ τὸν ἄνδρα ἀποστρεφόμενος ἐζημίωσε πεντήκοντα μυριάσιν, οὐκ ἐπικλασθεὶς οὐδ’ ὅτι πρὸ τῆς δίκης αὐτῷ παῖς ἐτεθνήκει. τὰ μὲν οὖν χρήματα οἱ φίλοι συνεισήνεγκαν, ἵνα μὴ ὑβρισθείη τὸ σῶμα τοῦ Καμίλλου· αὐτὸς δὲ βαρυθυμῶν ἐς τὴν Ἀρδεατῶν πόλιν μετῴκησεν, εὐξάμενος τὴν Ἀχίλλειον εὐχήν, ἐπιποθῆσαι Ῥωμαίους Κάμιλλον ἐν καιρῷ. καὶ ἀπήντησεν αὐτῷ καὶ τόδε οὐ πολὺ ὕστερον· Κελτῶν γὰρ τὴν πόλιν καταλαβόντων ὁ δῆμος ἐπὶ Κάμιλλον κατέφυγε καὶ δικτάτορα αὖθις εἵλετο, ὡς ἐν ταῖς Κελτικαῖς πράξεσι συγγέγραπται.", "st": "3.8"}, {"sp": "N", "t": "ὅτι Μάρκος Μάλλιος εὐπατρίδης, Κελτῶν ἐπελθόντων τῇ Ῥώμῃ, ταύτην περιέσωσε καὶ τιμῶν μεγίστων ἠξιώθη. ὕστερον δὲ πρεσβύτην πολλάκις ἐστρατευμένον ἀγόμενον ἐς δουλείαν ὑπὸ τοῦ δανειστοῦ γνωρίσας, ἀπέδωκε τὸ χρέος ὑπὲρ αὐτοῦ, καὶ ἐπὶ τῷδε εὐφημούμενος πᾶσιν ἠφίει τοῖς ἑαυτοῦ χρήσταις τὰ ὀφλήματα. προϊὼν δὲ τῇ δόξῃ καὶ ὑπὲρ ἄλλων ἀπεδίδου. καὶ ταῖς δημοκοπίαις ἐπαιρόμενος ἐβούλευσεν ἤδη χρεῶν ἀποκοπὰς κοινάς, ἢ τὸν δῆμον ἠξίου τοῖς δανείσασιν ἀποδοῦναι, τὴν γῆν ἐς τοῦτο ἀποδόμενον ἔτι οὖσαν ἀνέμητον.", "st": "3.9"}, {"sp": "HDR", "t": "Ἐκ τῆς Σαυνιτικῆς", "st": "4"}, {"sp": "N", "t": "ὅτι οἱ Ῥωμαίων στρατηγοὶ Κορνήλιος καὶ Κορουῖνος, καὶ Δέκιος δημότης, Σαυνίτας νικήσαντες ὑπέλιπον Καμπανοῖς φύλακας πρὸς τὰς Σαυνιτῶν ἐπιδρομάς. οἱ δὲ φύλακες οἵδε Καμπανοῖς ἁβροδιαίτοις καὶ πολυτελέσιν οὖσι κοινωνοῦντες ἐφθείροντο τὰς γνώμας, καὶ ἐφθόνουν ὧν ἔχουσιν ἀγαθῶν, αὐτοὶ πενόμενοι καὶ τὰ χρέα δεδιότες τὰ ἐν Ῥώμῃ. τέλος δὲ ἐπεβούλευον τοὺς ξένους ἑαυτῶν ἀνελόντες ἕκαστοι τὴν περιουσίαν κατασχεῖν καὶ τὰς γυναῖκας ἐς γάμον προσαγαγέσθαι. καὶ τάχα ἂν ἔπραξαν αἰσχρὸν οὕτω μύσος, εἰ μὴ Μάμερκος, ἕτερος Ῥωμαίων στρατηγός, ἐπὶ Σαυνίτας ὁδεύων ἔμαθε τὸ βούλευμα τῶν φυλάκων, καὶ ἐπικρύψας τοὺς μὲν αὐτῶν ἐξώπλισε καὶ ἀφῆκεν οἷα κεκμηκότας, τοὺς δὲ πονηροτέρους ἐκέλευσεν ἐς Ῥώμην ἐπί τινα χρείαν ἐπείγεσθαι, χιλίαρχόν τε αὐτοῖς συνέπεμψεν, ᾧ εἴρητο ἀφανῶς αὐτοὺς φυλάσσειν. ἑκάτεροι δ’ ὑπώπτευον μεμηνῦσθαι, καὶ περὶ Ταρρακίνην ἀφίστανταί τε τοῦ χιλιάρχου, καὶ τοὺς ἐπὶ τῶν ἔργων ἐν τοῖς ἀγροῖς δεδεμένους ἐκλύσαντες, καὶ ὁπλίσαντες ὡς ἐδύναντο, ἤλαυνον ἐς Ῥώμην ὁμοῦ δισμύριοι γεγονότες.", "st": "4.1"}, {"sp": "N", "t": "ἔτι δ’ αὐτῶν ὁδὸν ἡμέρας μιᾶς ἀπεχόντων ὑπήντα Κορουῖνος, καὶ παραστρατοπεδεύσας ἐν τοῖς ὄρεσι τοῖς Ἀλβανῶν ἠρεμεί, περισκοπῶν τε τὸ ἔργον ἔτι, καὶ μέγα ἡγούμενος ἀπεγνωκόσι μάχεσθαι. οἱ δὲ ἐπεμίγνυντο ἀλλήλοις κρύφα, καὶ ὀδυρμοὶ καὶ δάκρυα τῶν φυλάκων ἦν ὡς ἐν οἰκείοις καὶ φίλοις ἁμαρτεῖν μὲν ὁμολογούντων, τὴν δὲ αἰτίαν ἐς τὰ χρέα φερόντων τὰ ἐν Ῥώμῃ. ὧν ὁ Κορουῖνος αἰσθανόμενος, καὶ ὀκνῶν ἅψασθαι πολιτικοῦ καὶ τοσούτου φόνου, συνεβούλευσε τῇ βουλῇ τὰ χρέα τοῖς ἀνδράσι μεθεῖναι, τόν τε πόλεμον ἐξαίρων ἐπὶ μέγα, εἰ τοσῶνδε ἀνδρῶν δύναιτο κρατῆσαι μαχομένων ἐξ ἀπογνώσεως, καὶ τὰς συνόδους αὐτῶν καὶ ἐπιμιξίας ἐν ὑπονοίᾳ τιθέμενος, μὴ οὐδ’ ὁ ἴδιος αὐτῷ στρατὸς ἐς πάντα ᾖ πιστός, ἅτε συγγενεῖς ὄντες ἐκείνων, καὶ οὐχ ἧσσον αὐτῶν αἰτιώμενοι τὰ χρέα. σφαλέντα δὲ κινδυνεύσειν ἔφη περὶ μειζόνων· καὶ τὴν νίκην, εἰ κρατήσειεν, ἀτυχεστάτην ἔσεσθαι τῇ πόλει κατ’ οἰκείων τοσῶνδε. οἷς ἡ βουλὴ πεισθεῖσα τὰς μὲν τῶν χρεῶν ἀποκοπὰς ἐψηφίσατο πᾶσι Ῥωμαίοις, τοῖς δὲ τότε ἐχθροῖς καὶ ἄδειαν. οἱ μὲν δὴ τὰ ὅπλα ἀποθέμενοι κατῄεσαν ἐς τὴν πόλιν.", "st": "4.1"}, {"sp": "N", "t": "ὅτι Μάλλιος Τορκουάτος ὁ ὕπατος τοιοῦτος ἦν τὴν ἀρετήν. τούτῳ πατὴρ ἐγεγένητο μικρολόγος καὶ ἀμελὴς ἐς αὐτόν. καὶ ἐν ἀγροῖς αὐτὸν εἶχε, μετὰ τῶν θεραπόντων ἐργαζόμενόν τε καὶ τρεφόμενον. γραψαμένου δὲ αὐτὸν ἐπὶ πολλοῖς ἀδικήμασι Πομπωνίου δημάρχου, καὶ μέλλοντος ἐρεῖν τι καὶ περὶ τῆς ἐς τὸν παῖδα κακώσεως, ὁ παῖς ὅδε Μάλλιος ἧκεν, ἐπικρύπτων ξιφίδιον, ἐς τὴν οἰκίαν τοῦ δημάρχου, καὶ τυχεῖν ἠξίωσεν αὐτοῦ μόνου ὡς δή τι λέξων χρήσιμον ἐς τὴν δίκην. ὑποδεχθεὶς δὲ καὶ λέγειν ἀρχόμενος ἐπέκλεισε τὰς θύρας, καὶ τὸ ξίφος ἐπισπάσας ἠπείλει τῷ δημάρχῳ κτενεῖν αὐτόν, εἰ μὴ ὀμόσειεν ὅτι λύσει τῷ πατρὶ τὴν δίκην. καὶ ὁ μὲν ὤμοσε καὶ διέλυσεν, ἐκθέμενος τῷ δήμῳ τὸ συμβάν· ὁ δὲ Μάλλιος ἐξ ἐκείνου λαμπρὸς ἦν, ἐπαινούμενος ὅτι τοιόσδε ἐς τοιόνδε πατέρα ἐγεγένητο.", "st": "4.2"}, {"sp": "N", "t": "ὁ δὲ αὐτὸν εἰς μονομαχίαν προυκαλεῖτο, σκώπτων ἐς αὐτόν. ὁ δὲ τέως μὲν αὑτοῦ κατεῖχε, μετὰ δέ, οὐ φέρων ἔτι τὸ ἐρέθισμα, ἀντήλασε τὸν ἵππον.", "st": "4.3"}, {"sp": "N", "t": "ὅτι Σαυνῖται ἐς τὴν Φρεγελλανῶν ἐμβαλόντες ἐπόρθουν, Ῥωμαῖοι δὲ Σαυνιτῶν καὶ Δαυνίων ὀγδοήκοντα κώμας καὶ μίαν εἷλον, καὶ ἄνδρας ἐξ αὐτῶν χιλίους καὶ δισμυρίους ἀνελόντες ἀπανέστησαν αὐτοὺς ἀπὸ τῆς Φρεγέλλης. καὶ πάλιν ἐς Ῥώμην ἐπρέσβευον οἱ Σαυνῖται, νεκρὰ σώματα ἀνδρῶν φέροντες ὡς αἰτίους τοῦδε τοῦ πολέμου γεγονότας ἀνῃρηκότες, καὶ χρυσίον ὡς ἀπὸ τῆς ἐκείνων περιουσίας πεπορισμένον. ἐφ’ οἷς αὐτοὺς ἡ βουλὴ πάνυ νομίζουσα τετρῦσθαι, προσεδόκα κακοπαθοῦντας ἐνδώσειν περὶ τῆς ἡγεμονίας. οἱ δὲ τὰ μὲν ἄλλα ἐδέχοντο, καὶ εἴ τι καὶ ἀντέλεγον, ἢ παρῃτοῦντο καὶ παρεκάλουν ἢ ἐς τὰς πόλεις ἀνετίθεντο· περὶ δὲ τῆς ἡγεμονίας οὐκ ἀνασχόμενοι πάλιν οὐδ’ ἀκοῦσαι, οὐκ ἐκδωσόμενοι δὴ τὰς πόλεις ἔφασαν ἥκειν, ἀλλ’ ἐς φιλίαν συνάξοντες. λυσάμενοι δὴ τοῦ χρυσίου τοὺς αἰχμαλώτους ἀπῄεσαν ὀργῇ, καὶ τὴν πεῖραν ἔχοντες τὴν περὶ τῆς ἡγεμονίας.", "st": "4.4"}, {"sp": "N", "t": "καὶ Ῥωμαῖοι μὲν ἐψηφίζοντο μηδὲ πρεσβείας ἔτι παρὰ Σαυνιτῶν προσίεσθαι, ἀλλ’ ἄσπονδον καὶ ἀκήρυκτον πόλεμον αὐτοῖς πολεμεῖν ἕως κατὰ κράτος ἐξέλωσι, θεὸς δ’ ἐνεμέσησε τῆς μεγαληγορίας, καὶ ὕστερον ἡττήθησαν ὑπὸ Σαυνιτῶν καὶ ὑπὸ ζυγὸν ἤχθησαν οἱ Ῥωμαῖοι. ἐς γὰρ στενώτατον χῶρον τούτους συγκλείσαντες οἱ Σαυνῖται τοῦ Ποντίου σφῶν στρατηγοῦντος, καὶ λιμῷ πιεζομένων Ῥωμαίων, οἱ στρατηγοὶ σφῶν πρεσβευσάμενοι παρεκάλουν τὸν Πόντιον καταθέσθαι Ῥωμαίοις χάριν, ἣν οὐ πολλοὶ παρέχουσι καιροί. ὁ δὲ ἀπεκρίνατο μὴ δεῖν μηδὲ πρεσβεύειν ἔτι πρὸς αὐτόν, εἰ μὴ τὰ ὅπλα καὶ αὑτοὺς παραδοῖεν. θρῆνος οὖν ἦν οἷα πόλεως ἁλούσης. καὶ οἱ στρατηγοὶ διέτριψαν μὲν ἔτι ἄλλας ἡμέρας, ὀκνοῦντες ἀνάξιόν τι τῆς πόλεως ἐργάσασθαι· ὡς δ’ οὔτε μηχανὴ σωτηρίας ἐφαίνετο, ὅ τε λιμὸς ἐπίεζεν αὐτούς, καὶ νεότης ἦν πέντε μυριάδων, ἣν ὤκνουν φθειρομένην ὑπεριδεῖν, ἐπέτρεψαν ἑαυτοὺς τῷ Ποντίῳ, καὶ παρεκάλουν, εἴτε κτείνειν εἴτε πωλεῖν εἴτε φυλάσσειν ἐπὶ λύτροις ἕλοιτο, μηδὲν ἐς σώματα ἀνδρῶν ἀτυχούντων ὑβρίσαι.", "st": "4.4"}, {"sp": "N", "t": "ὁ δὲ τῷ πατρὶ συνεβουλεύετο, μεταπεμψάμενος αὐτὸν ἐκ τοῦ Καυδίου, φερόμενον ὑπὸ γήρως ἁμάξῃ. καὶ ὁ πρεσβύτης ἔφη, “ἓν ἔστιν, ὦ παῖ, μεγάλης ἔχθρας φάρμακον, εὐεργεσίας ἢ κολάσεως ὑπερβολή. αἱ μὲν οὖν κολάσεις καταπλήσσουσιν, αἱ δὲ εὐεργεσίαι προσάγονται. ἴσθι νίκην τήνδε πρώτην καὶ μεγίστην, θησαυρίζειν τὴν εὐτυχίαν· καὶ πάντας ἀπόλυσον ἀπαθεῖς, μήτ’ ἐνυβρίσας μήτ’ ἀφελόμενος μηδέν, ἵνα σῶον ᾖ σοι τὸ μέγεθος τῆς εὐεργεσίας. εἰσὶ δ’, ὡς ἀκούω, φιλοτιμότατοι. ἀλλὰ μόναις εὐεργεσίαις ἡττώμενοι διαγωνιοῦνταί σοι περὶ τῆσδε τῆς χάριτος. ἔχεις ἐνέχυρον τήνδε τὴν εὐεργεσίαν εἰρήνης ἀθανάτου λαβεῖν. ἢν δέ σε ταῦτα μὴ πείθῃ, κτεῖνον ἅπαντας ὁμαλῶς, μηδ’ ἄγγελον ὑπολιπών. λέγω δ’ ἐκεῖνα μὲν αἱρούμενος, ταῦτα δ’ ὡς ἀναγκαῖα. Ῥωμαῖοι γὰρ ὁτιοῦν ὑβρισθέντες ἀμυνοῦνταί σε πάντως· ἀμυνεῖσθαι δὲ μέλλοντας αὐτοὺς προκατάβλαπτε. μεῖζον δ’ οὐκ ἂν εὕροις βλάβος νέων ὁμοῦ πέντε μυριάδων.”", "st": "4.4"}, {"sp": "N", "t": "ὁ μὲν τοσαῦτα εἶπεν, ὁ δὲ παῖς ἀντέλεξεν· “ὅτι μέν, ὦ πάτερ, ἐναντιώτατα εἶπας ἀλλήλοις, οὐ θαυμάζω· προεῖπας γὰρ ἐρεῖν ὑπερβολὰς ἑκατέρων. ἐγὼ δὲ οὐ κτενῶ μὲν ἄνδρας τοσούτους, νέμεσίν τε θεοῦ φυλασσόμενος καὶ φθόνον ἀνθρώπων αἰδούμενος, καὶ τὰ ἔθνη τὰς ἐς ἀλλήλους ἐλπίδας οὐκ ἀφαιρήσομαι δι’ ἀνηκέστου κακοῦ. περὶ δὲ τῆς ἀφέσεως οὐδ’ αὐτῷ μέν μοι δοκεῖ, Ῥωμαίων πολλὰ καὶ δεινὰ δεδρακότων ἡμᾶς, καὶ χωρία καὶ πόλεις ἡμετέρας ἔτι νῦν ἐχόντων, τούσδε τοὺς εἰλημμένους ἀπολύειν παντὸς ἀπαθεῖς. οὐ ποιήσω· ἐμπληξία γὰρ ἡ ἄλογος φιλανθρωπία. ἐπισκόπει δέ, παρεὶς ἐμέ, καὶ τὸ τῶν Σαυνιτῶν· ὧν παῖδες καὶ πατέρες καὶ ἀδελφοὶ τεθνᾶσιν ὑπὸ Ῥωμαίων, καὶ κτήματα καὶ χρήματα ἀφῃρημένοι χρῄζουσι παραμυθίας· φύσει δὲ γαῦρον ὁ νενικηκώς, καὶ τὰ κέρδη περιβλέπονται. τίς οὖν ἀνέξεταί μου τούσδε μὴ κτείνειν μηδὲ πωλεῖν μηδὲ ζημιοῦν, ἀλλ’ ὡς εὐεργέτας ἀπαθεῖς προπέμπειν; διὰ μὲν δὴ ταῦτα παρῶμεν τὰς ὑπερβολάς, ἐπεὶ τῆς μὲν οὐ κύριος ἐγώ, τῆς δ’ ἀπανθρωποτέρας οὐκ ἀνέχομαι· ὡς δ’ ἂν καὶ Ῥωμαίων τι τοῦ φρονήματος περιέλοιμι καὶ τὰ πρὸς τοὺς ἄλλους ἀδιάβλητος εἴην, ὅπλα μὲν αὐτούς, οἷς ἐχρήσαντο ἀεὶ καθ’ ἡμῶν, ἀφαιρήσομαι καὶ χρήματα (καὶ γὰρ ταῦτα ἔχουσι παρ’ ἡμῶν), ἐκπέμψω δ’ ὑπὸ ζυγὸν σώους, ᾗ τινὶ αἰσχύνῃ καὶ αὐτοὶ κατ’ ἄλλων ἐχρήσαντο, καὶ εἰρήνην εἶναι τοῖς ἔθνεσι συνθήσομαι, τῶν τε ἱππέων ἐπιλέξομαι τοὺς ἐπιφανεστάτους ὅμηρα τῶνδε τῶν συνθηκῶν, ἕως ἅπας ὁ δῆμος ἐπιψηφίσῃ. καὶ τάδε ποιῶν ἡγοῦμαι νενικηκότος τε ἔργα ποιήσειν καὶ φιλανθρώπου, Ῥωμαίους τε ἀγαπήσειν ὅσα καὶ αὐτοί, φάσκοντες ἀρετῆς ἀντιποιεῖσθαι, πολλάκις ἐς ἄλλους ἔδρασαν.”", "st": "4.4"}, {"sp": "N", "t": "ταῦτα τοῦ Ποντίου λέγοντος ὁ πρεσβύτης ἐδάκρυσέ τε, καὶ ἐπιβὰς τῆς ἀπήνης ἐς τὸ Καύδιον ἀπήλαυνεν. ὁ δὲ Πόντιος τοὺς πρέσβεις καλέσας ἤρετο εἴ τις εἰρηνοδίκης αὐτοῖς παρείη. τοῖς δὲ παρῆν οὐδεὶς ὡς ἐπὶ ἄσπονδον καὶ ἀκήρυκτον πόλεμον ἐστρατευκόσι. τοῖς οὖν ὑπάτοις καὶ τοῖς ἄλλοις ἄρχουσι τῆς στρατιᾶς καὶ παντὶ τῷ πλήθει λέγειν ἐκέλευε τοὺς πρέσβεις, “ἡμεῖς ἀεὶ Ῥωμαίοις ἐσπενδόμεθα φιλίαν, ἣν αὐτοὶ διελύσατε, Σιδικηνοῖς τοῖς ἡμετέροις ἐχθροῖς συμμαχοῦντες. εἶτ’ αὖθις αὖ φιλίας ἡμῖν γενομένης, Νεαπολίταις ἐπολεμεῖτε τοῖς ἡμετέροις γείτοσιν. καὶ οὐκ ἠγνοοῦμεν ὅτι ταῦτ’ ἦν ὑμῖν παρασκευὴ πλεονεξίας ἐπὶ ὅλην τὴν Ἰταλίαν. ἔν τε ταῖς προτέραις μάχαις πολλὰ παρὰ τὴν ἀπειρίαν τῶν ἡμετέρων στρατηγῶν προλαβόντες οὐδὲν ἐπεδείξασθε μέτριον ἐς ἡμᾶς, οὐδ’ ἠρκεῖσθε τὴν χώραν πορθοῦντες καὶ χωρία καὶ πόλεις ἔχοντες ἀλλοτρίας, καὶ κληρούχους ἐς αὐτὰ πέμποντες, ἀλλὰ καὶ πρεσβευσαμένων ἡμῶν δὶς πρὸς ὑμᾶς, καὶ πολλὰ συγχωρούντων, ὑπερήφανα ἡμῖν ἄλλα ἐπετάσσετε, τὴν ἀρχὴν ὅλην ἀποθέσθαι καὶ ὑμῶν ὑπακούειν, ὥσπερ οὐ σπενδομένους ἀλλ’ ἑαλωκότας. καὶ ἐπὶ τοῖσδε τὸν πόλεμον τόνδε ἄσπονδον καὶ ἀκήρυκτον ἐψηφίσασθε, κατ’ ἀνδρῶν ποτὲ φίλων, κατὰ Σαβίνων ἐκγόνων τῶν ὑμῖν συνοικούντων. ἕνεκα μὲν οὖν τῆς ὑμετέρας πλεονεξίας ἔδει καὶ τὰ παρ’ ἡμῶν ὑμῖν ἄσπονδα εἶναι. ἐγὼ νέμεσίν τε θεῶν αἰδούμενος, ἣν ὑμεῖς ὑπερείδεσθε, καὶ συγγενείας καὶ φιλίας τῆς ποτὲ μνημονεύων, δίδωμι ἕκαστον ὑμῶν σὺν ἱματίῳ σῶον ὑπὸ ζυγὸν ἀπελθεῖν, ἢν ὀμόσητε τήν τε γῆν καὶ τὰ χωρία πάνθ’ ἡμῖν ἀποδώσειν, καὶ τοὺς κληρούχους ἀπὸ τῶν πόλεων ἀπάξειν, καὶ μηδέ ποτ’ ἐπὶ Σαυνίτας στρατεύσειν.”", "st": "4.4"}, {"sp": "N", "t": "ἀπαγγελθέντων δὲ τούτων ἐς τὸ στρατόπεδον ὀλοφυρμὸς ἦν καὶ θρῆνος ἐπὶ πλεῖστον· θανάτου γὰρ ἡγοῦντο εἶναι χείρονα τὴν ὕβριν τὴν ὑπὸ τῷ ζυγῷ. ὡς δὲ καὶ περὶ τῶν ἱππέων ἐπύθοντο, αὖθις ἐθρήνουν ἐπὶ πλεῖστον. ὑπὸ δὲ ἀπορίας αὐτὰ ἐδέχοντο, καὶ τοὺς ὅρκους ὤμνυον ὅ τε Πόντιος καὶ οἱ Ῥωμαίων ὕπατοι, δύο ὄντες Ποστούμιός τε καὶ Οὐετούριος, καὶ ταμιαι δύο καὶ ταξιάρχαι τέσσαρες καὶ χιλίαρχοι δώδεκα, σύμπαντες ὅσοι μετὰ τοὺς διεφθαρμένους ἦρχον. γενομένων δὲ τῶν ὅρκων ὁ μὲν Πόντιος παραλύσας τι τοῦ διατειχίσματος, καὶ δυσὶ δόρασιν ἐς τὴν γῆν ἐμπεπηγόσιν ἐπικάρσιον ἄλλο ἐπιθείς, ἐξέπεμπε Ῥωμαίων ἕκαστον ὑπὸ τούτῳ. καί τινα ὑποζύγια ἔδωκεν αὐτοῖς ἐς τοὺς ἀρρωστοῦντας, καὶ τροφήν, ἄχρι τῆς Ῥώμης φέρεσθαι. δύναται δ’, ἐμοὶ δοκεῖν, τὸ εἶδος τῆς ἀφέσεως, ὃ καλοῦσιν οἱ τῇδε ζυγόν, ὀνειδίζειν ὡς δοριαλώτοις.", "st": "4.4"}, {"sp": "N", "t": "ἀπαγγελθείσης δὲ τῆς συμφορᾶς ἐς τὴν πόλιν οἰμωγὴ καὶ θρῆνος ἦν ὡς ἐπὶ πένθει, καὶ αἱ γυναῖκες ἐκόπτοντο τοὺς αἰσχρῶς περισεσωσμένους ὡς ἀποφανόντας, ἥ τε βουλὴ τὴν ἐπιπόρφυρον ἐσθῆτα ἀπέθετο, καὶ θυσίαι καὶ γάμοι, καὶ ὅσα ἄλλα τοιουτότροπα, ἐπέσχετο ἐπὶ τὸ ἔτος ὅλον, ἕως τὴν συμφορὰν ἀνέλαβον. τῶν δὲ ἀφειμένων οἱ μὲν ἐς τοὺς ἀγροὺς διέφευγον ὑπὸ αἰδοῦς, οἱ δὲ νυκτὸς ἐς τὴν πόλιν ἐσῄεσαν· οἱ δὲ ἄρχοντες ἡμέρας μὲν ἐσῆλθον ὑπ’ ἀνάγκης, καὶ τὰ σημεῖα τῆς ἀρχῆς ἐπέκειτο αὐτοῖς, ἔπρασσον δὲ οὐδέν.", "st": "4.4"}, {"sp": "N", "t": "Δεντάτῳ κατὰ ζῆλον ἀρετῆς εἵπετο νεων λογάδων πλῆθος ὀκτακοσίων, ἐπὶ πάντα τὰ ἔργα ἕτοιμοι. καὶ βαρὺς ἦν τῇ βουλῇ παρὰ τὰς ἐκκλησίας.", "st": "4.5"}, {"sp": "N", "t": "ὅτι Κελτῶν Σενόνων πολὺ πλῆθος Τυρρηνοῖς συνεμάχουν κατὰ Ῥωμαίων. Ῥωμαῖοι δὲ ἐς τὰς Σενόνων πόλεις ἐπρέσβευον, καὶ ἐνεκάλουν ὅτι ὄντες ἔνσπονδοι μισθοφοροῦσι κατὰ Ῥωμαίων. τούσδε τοὺς πρέσβεις Βριτόμαρις μετὰ τῶν κηρυκείων καὶ τῆς ἱερᾶς στολῆς κατέτεμεν ἐς πολλὰ καὶ διέρριψεν, ἐγκαλῶν ὅτι αὐτοῦ ὁ πατὴρ ἐν Τυρρηνίᾳ πολεμῶν ἀνῄρητο ὑπὸ Ῥωμαίων. Κορνήλιος δὲ ὁ ὕπατος τοῦ μύσους ἐν ὁδῷ πυθόμενος τὰ μὲν Τυρρηνῶν εἴασεν, ἐς δὲ τὰς Σενόνων πόλεις συντόνῳ σπουδῇ διὰ Σαβίνων καὶ Πικεντίνων ἐσβαλὼν πάντα καθῄρει καὶ ἐνεπίμπρη, καὶ τὰς μὲν γυναῖκας καὶ τὰ παιδία ἠνδραποδίζετο, τοὺς δὲ ἡβῶντας πάντας ἔκτεινε, πλὴν Βριτομάριος, ὃν δεινῶς αἰκισάμενος ἦγεν ἐς τὸν θρίαμβον.", "st": "4.6"}, {"sp": "N", "t": "οἱ δὲ Σενόνων, ὅσοι ἦσαν ἐν Τυρρηνίᾳ, πυθόμενοι ἀνῃρῆσθαι, Τυρρηνοὺς ἦγον ἐπὶ Ῥώμης. καὶ πολλῶν μεταξὺ γενομένων οἱ Σένονες, οὔτε πατρίδας ἔχοντες ἐς ἃς διαφύγωσιν, ὀργιζόμενοί τε τῶν γεγονότων, ἐνέπιπτον τῷ Δομιτίῳ καὶ διεφθάρησαν πολλοί. τὸ δὲ λοιπὸν σφᾶς αὐτοὺς διεχρῶντο μανικῶς. καὶ δίκη μὲν ἥδε παρανομίας ἐς πρέσβεις ἐγένετο Σένοσιν.", "st": "4.6"}, {"sp": "N", "t": "ὅτι Κορνήλιος ἐπὶ καταφράκτων δεκα νεῶν ἐθεᾶτο τὴν μεγάλην Ἑλλάδα, καί τις ἐν Τάραντι δημαγωγὸς Φιλόχαρις, αἰσχρῶς τε βεβιωκὼς καὶ παρὰ τοῦτο καλούμενος Θαΐς, παλαιῶν τοὺς Ταραντίνους ἀνεμίμνησκε συνθηκῶν, μὴ πλεῖν Ῥωμαίους πρόσω Λακινίας ἄκρας, παροξύνας τε ἔπεισεν ἐπαναχθῆναι τῷ Κορνηλίῳ. καὶ τέσσαρας μὲν αὐτοῦ ναῦς κατέδυσαν οἱ Ταραντῖνοι, μίαν δὲ ἔλαβον αὐτοῖς ἀνδράσιν. ἔς τε Θουρίους ἐγκλήματα ποιούμενοι ὅτι Ἕλληνες ὄντες ἐπὶ Ῥωμαίους κατέφυγον ἀντὶ σφῶν, καὶ παρελθεῖν αὐτοὺς ἐπέκεινα αἴτιοι μάλιστα ἐγεγένηντο, τοὺς μὲν ἐπιφανεῖς αὐτῶν ἐξέβαλον, τὴν δὲ πόλιν διήρπασαν, καὶ τοὺς Ῥωμαίων φρουροὺς ὑποσπόνδους ἀφῆκαν.", "st": "4.7"}, {"sp": "N", "t": "Ῥωμαῖοι δὲ τούτων πυθόμενοι πρέσβεις ἐς Ταραντα πέμπουσι, τοὺς μὲν αἰχμαλώτους κελεύοντες, οὓς οὐ πολεμοῦντας ἀλλὰ θεωμένους ἔλαβον, ἀποδοῦναι, Θουρίων δ’ οὓς ἐξέβαλον, εἰς τὴν πόλιν καταγαγεῖν, ἅ τε διηρπάκεσαν αὐτούς, ἢ τὴν ζημίαν τῶν ἀπολομένων, ἀποτῖσαι, σφίσι δ’ ἐκδοῦναι τοὺς αἰτίους τῆς παρανομίας, εἰ Ῥωμαίων ἐθέλουσιν εἶναι φίλοι. οἱ δὲ τοὺς πρέσβεις μόλις ποτὲ ἐπὶ τὸ κοινὸν ἐπήγαγον, καὶ ἐπελθόντας ἐχλεύαζον εἴ τι μὴ καλῶς ἑλληνίσειαν· ἔσκωπτον δὲ καὶ τὴν στολὴν αὐτῶν καὶ τὸ ἐπιπόρφυρον. Φιλωνίδης δέ τις, ἀνὴρ γελοῖος καὶ φιλοσκώμμων, Ποστουμίῳ τῷ τῆς πρεσβείας ἡγουμένῳ προσελθὼν ἀπεστράφη τε, καὶ ἐπικύψας τὴν ἐσθῆτα ἀνεσύρατο τὴν ἑαυτοῦ, καὶ τοῦ πρεσβευτοῦ κατησχημόνησεν. καὶ τὸ μὲν θέατρον ἔπαιζεν ὡς ἐπὶ γελοίῳ, Ποστούμιος δὲ προτείνας τὸ μεμολυσμένον, “ἐκπλυνεῖτε,” ἔφη, “τοῦτο αἵματι πολλῷ, τοιούτοις ἀρεσκόμενοι γέλωσιν.” καὶ οὐδὲν τῶν Ταραντίνων ἀποκριναμένων ἀπῆλθον οἱ πρέσβεις. ὁ δὲ Ποστούμιος τὴν ὕβριν ἐκ τῆς ἐσθῆτος οὐκ ἀποπλύνας ἐπέδειξε Ῥωμαίοις, καὶ ὁ δῆμος ἀγανακτῶν Αἰμιλίῳ πολεμοῦντι Σαυνίταις ἐπέστειλε τὰ μὲν Σαυνιτῶν ἐν τῷ παρόντι ἐᾶν, εἰς δὲ τὴν Ταραντίνων εἰσβάλλειν, καὶ αὐτοὺς ἐφ’ οἷς ἠξίουν οἱ πρέσβεις ἐς διαλλαγὰς προκαλέσασθαι, ἂν δ’ ἀπειθῶσι, πολεμεῖν κατὰ κράτος. ὁ μὲν δὴ τάδε προύτεινε τοῖς Ταραντίνοις, οἱ δὲ οὐκ ἐγέλων ἔτι τὴν στρατιὰν ὁρῶντες, ἀλλ’ ἐγίγνοντο ταῖς γνώμαις ἀγχώμαλοι, μέχρι τις ἀποροῦσι καὶ βουλευομένοις ἔφη, τὸ μὲν ἐκδοῦναί τινας ἤδη δεδουλωμένων εἶναι, τὸ δὲ πολεμεῖν μόνους ἐπισφαλές. “εἰ δὲ καὶ τῆς ἐλεὺθερίας ἐγκρατῶς ἑξόμεθα καὶ πολεμήσομεν ἐξ ἴσου, Πύρρον ἐξ Ἠπείρου τὸν βασιλέα καλῶμεν, καὶ στρατηγὸν ἀποφήνωμεν τοῦδε τοῦ πολέμου.” ὃ καὶ γέγονεν.", "st": "4.7"}, {"sp": "N", "t": "Οτι μετὰ τὸ ναυάγιον ὁ Πύρρος ὁ βασιλεὺς τῆς Ἠπείρου ἐς τὸν Τάραντα κατήγετο, καὶ οἱ Ταραντῖνοι τότε μάλιστα τοὺς βασιλικοὺς ἐβαρύνοντο, ἐσοικιζομένους τε παρὰ σφᾶς βίᾳ, καὶ φανερῶς ἐνυβρίζοντας ταῖς αὐτῶν γυναιξὶ καὶ παισίν. ὡς δὲ καὶ τὰ συσσίτια σφῶν ὁ Πύρρος καὶ τὰς ἄλλας συνόδους καὶ διατριβὰς ὡς οὐ πρεπούσας πολέμῳ διέλυε, γυμνάσιά τε ἔνοπλα ἔτασσεν αὐτοῖς, καὶ θάνατον τοῖς ἀμελοῦσιν ὥριζε, τότε δὴ καὶ πάμπαν ἀήθεσιν ἔργοις καὶ ἐπιτάγμασι κάμνοντες οἱ Ταραντῖνοι τῆς πόλεως ὡς ἀλλοτρίας ἐς τοὺς ἀγροὺς ἀπεδίδρασκον. καὶ ὁ βασιλεὺς τὰς θύρας ἀπέκλειε, καὶ φρουρὰς ἐφίστη. καὶ οἱ Ταραντῖνοι τῆς ἀβουλίας σφῶν ᾐσθάνοντο σαφῶς.", "st": "4.8"}, {"sp": "N", "t": "ὅτι ὅσοι ἐν Ῥηγίῳ Ῥωμαίων ἐπὶ σωτηρίᾳ καὶ φυλακῇ τῆς πόλεως, μή τι πάθοιεν ὑπὸ τῶν ἐχθρῶν, παρέμενον, αὐτοί τε καὶ Δέκιος ὁ ἡγεμὼν αὐτῶν, τοῖς ἀγαθοῖς τῶν Ῥηγίνων φθονήσαντες, καὶ φυλάξαντες αὐτοὺς εὐωχουμένους ἐν ἑορτῇ διέφθειραν, καὶ ταῖς γυναιξὶν ἀκουσίαις συνῆσαν. πρόφασιν δὲ τῆς παρανομίας ἔφερον ὅτι Ῥηγῖνοι τὴν φρουρὰν προεδίδοσαν Πύρρῳ. καὶ Δέκιος μὲν ἀντὶ φρουράρχου τύραννος ἦν, καὶ φιλίαν ἔθετο Μαμερτίνοις τοῖς ἐπὶ τοῦ πορθμοῦ τοῦ Σικελικοῦ κατῳκημένοις, οὐ πρὸ πολλοῦ κἀκείνοις ἐς ἰδίους ξένους ὅμοια δεδρακόσιν.", "st": "4.9"}, {"sp": "N", "t": "ἀλγήσαντα δ’ αὐτὸν τοῖς ὀφθαλμοῖς, καὶ τοῖς ἐν Ῥηγίῳ ἰατροῖς ἀπιστοῦντα, μετάπεμπτος ἀπὸ Μεσσήνης ἐθεράπευε Ῥηγῖνος ἀνήρ, μετῳκηκὼς ἐς Μεσσήνην πρὸ πολλοῦ, ὅτι Ῥηγῖνος ἦν ἀγνοούμενος. οὗτος αὐτὸν ἔπεισεν ἐπὶ ἀπαλλαγῇ συντόμῳ φαρμάκων ἀνασχέσθαι θερμῶν, καὶ χρίσας τοῖς κατακαίουσι καὶ δαπανῶσιν ἐκέλευσεν ἀνασχέσθαι τοῦ πόνου μέχρι αὐτὸς ἐπανέλθοι, καὶ λαθὼν ἔπλευσεν ἐς Μεσσήνην. ὁ δ’ ἐς πολὺ τῆς ὀδύνης ἀνασχόμενος ἀπενίψατο, καὶ εὗρε τοὺς ὀφθαλμοὺς δεδαπανημένους.", "st": "4.9"}, {"sp": "N", "t": "Φαβρίκιος δὲ ὑπὸ Ῥωμαίων ἐπὶ διορθώσει τῶνδε πεμφθεὶς τήν τε πόλιν τοῖς ἔτι Ῥηγίνοις λοιποῖς ἀπεδίδου, καὶ τῶν φρουρῶν τοὺς αἰτίους τῆς ἀποστάσεως ἐς Ῥώμην ἔπεμψεν, οἳ μαστιγωθέντες ἐν ἀγορᾷ μέσῃ τὰς κεφαλὰς ἀπεκόπησαν καὶ ἐξερρίφησαν ἄταφοι. Δέκιος δὲ φυλασσόμενος ἀμελῶς, οἷα πηρός, ἑαυτὸν διεχρήσατο.", "st": "4.9"}, {"sp": "N", "t": "ὅτι ὁ Πύρρος ὁ βασιλεὺς τῆς Ἠπείρου, νικήσας τοὺς Ῥωμαίους καὶ ἀναλαβεῖν χρῄζων τὴν στρατιὰν ἐκ μάχης εὐτόνου, καὶ Ῥωμαίους ἐλπίζων ἐς διαλύσεις τότε μάλιστα ἐνδώσειν, ἔπεμπεν ἐς Ῥώμην Κινέαν τὸν Θεσσαλόν, δόξαν ἐπὶ λόγοις ἔχοντα μιμεῖσθαι τὴν Δημοσθένους ἀρετήν. καὶ παρελθὼν ὁ Κινέας ἐς τὸ βουλευτήριον ἄλλα τε πολλὰ περὶ τοῦ βασιλέως ἐσεμνολόγει, καὶ τὴν ἐπὶ τῷ ἀγῶνι μετριοπάθειαν κατελογίζετο, μήτ’ ἐπὶ τὴν πόλιν εὐθὺς ἐλάσαντος μήτ’ ἐπὶ τὸ ἡσσημένον στρατόπεδον· ἐδίδου δ’ αὐτοῖς εἰρήνην καὶ φιλίαν καὶ συμμαχίαν πρὸς Πύρρον, εἰ Ταραντίνους μὲν ἐς ταῦτα συμπεριλάβοιεν, τοὺς δ’ ἄλλους Ἕλληνας τοὺς ἐν Ἰταλίᾳ κατοικοῦντας ἐλευθέρους καὶ αὐτονόμους ἐῷεν, Λευκανοῖς δὲ καὶ Σαυνίταις καὶ Δαυνίοις καὶ Βρεττίοις ἀποδοῖεν ὅσα αὐτῶν ἔχουσι πολέμῳ λαβόντες. καὶ γιγνομένων ἔφη τούτων Πύρρον ἀποδώσειν αὐτοῖς τοὺς αἰχμαλώτους ἄνευ λύτρων.", "st": "4.10"}, {"sp": "N", "t": "οἱ δ’ ἐνεδοίαζον ἐπὶ πλεῖστον, τῇ τε δόξῃ τοῦ Πύρρου καὶ τῷ συμβεβηκότι πάθει καταπλαγέντες, ἕως Ἄππιος Κλαύδιος, ὁ Καῖκος ἐπίκλησιν, ἤδη τετυφλωμένος, ἐς τὸ βουλευτήριον τοῖς παισὶν αὑτὸν ἀγαγεῖν κελεύσας, “ἠχθόμην,” εἶπεν, “ὅτι μὴ βλέπω· νῦν δ’ ὅτι ἀκούω. τὰ γὰρ τοιαῦτα ὑμῶν βουλεύματα ἠξίουν μήθ’ ὁρᾶν μήτ’ ἀκούειν, οἳ δι’ ἓν ἀτύχημα ἀθρόως οὕτως ἑαυτῶν ἐκλέλησθε, καὶ τὸν τοῦτο δράσαντα αὐτόν τε καὶ τοὺς ἐπαγαγομένους αὐτὸν βουλεύεσθε φίλους ἀντὶ πολεμίων θέσθαι, καὶ τὰ τῶν προγόνων κτήματα Λευκανοῖς καὶ Βρεττίοις δοῦναι. τί τοῦτ’ ἐστὶν ἢ Ῥωμαίους ἐπὶ Μακεδόσι γενέσθαι; καὶ ταῦτά τινες εἰρήνην ἀντὶ δουλείας τολμῶσιν ὀνομάζειν.” ἄλλα τε πολλὰ ὅμοια τούτοις ὁ Ἄππιος εἰπὼν καὶ ἐρεθίσας, ἐσηγήσατο Πύρρον, εἰ δέοιτο τῆς Ῥωμαίων φιλίας καὶ συμμαχίας, ἐξ Ἰταλίας ἀπελθόντα πρεσβεύειν, παρόντα δὲ μήτε φίλον ἡγεῖσθαι μήτε σύμμαχον μήτε Ῥωμαίοις δικαστὴν ἢ διαιτητήν.", "st": "4.10"}, {"sp": "N", "t": "καὶ ἡ βουλὴ ταῦθ’ ἅπερ καὶ Ἄππιος εἶπεν ἀπεκρίνατο Κινέᾳ. Λαιουίνῳ δ’ ἄλλα δύο τέλη καταλέγοντες ἐκήρυξαν οὕτως, εἴ τις ἀντὶ τῶν ἀπολωλότων αὑτὸν ἐπιδίδωσιν, ἐς τὴν στρατιὰν ἀπογράφεσθαι. καὶ ὁ Κινέας ἔτι παρών, καὶ θεώμενος αὐτοὺς ὠθουμένους ἐς τὰς ἀπογραφάς, λέγεται πρὸς τὸν Πύρρον ἐπανελθὼν εἰπεῖν ὅτι πρὸς ὕδραν ἐστὶν αὐτοῖς ὁ πόλεμος. οἱ δὲ οὐ Κινέαν ἀλλὰ Πύρρον αὐτὸν εἰπεῖν τοῦτο τὸ ἔπος, ἰδόντα τὴν στρατιὰν τῶν Ῥωμαίων τῆς προτέρας πλείονα· καὶ γὰρ ὁ ἕτερος ὕπατος τῷ Λαιουίνῳ Κορουγκάνιος ἧκεν ἐκ Τυρρηνίας μεθ’ ἧς εἶχε παρασκευῆς. λέγεται δὲ καὶ τἆλλα περὶ τῆς Ῥώμης πυνθανομένῳ Πύρρῳ Κινέας εἰπεῖν ὅτι πόλις ἐστὶ στρατηγῶν ὅλη, καὶ τοῦ Πύρρου θαυμάσαντος μεταλαβὼν φάναι, “βασιλέων μᾶλλον ἢ στρατηγῶν.” Πύρρος δ’, ὡς οὐδὲν εἰρηναῖόν οἱ παρὰ τῆς βουλῆς ἀπήντησεν, ἐπὶ τὴν Ῥώμην ἠπείγετο, πάντα δῃῶν. καὶ φθάνει μὲν ἐς πόλιν Ἀναγνίαν, βαρεῖαν δ’ ἔχων ἤδη τὴν στρατιὰν ὑπὸ λείας καὶ πλήθους αἰχμαλώτων, ἀναθέμενος μάχην ἀνέστρεφεν ἐπὶ Καμπανίας, ἡγουμένων τῶν ἐλεφάντων, καὶ τὴν στρατιὰν ἐς χειμασίαν κατὰ πόλεις διῄρει.", "st": "4.10"}, {"sp": "N", "t": "Ῥωμαίων δὲ πρέσβεις αὐτὸν ἠξίουν λῦσαι τῇ πόλει τοὺς αἰχμαλώτους, ἢ ἀντιλαβεῖν ὅσους ἔχουσι Ταραντίνων καὶ τῶν ἄλλων συμμάχων αὐτοῦ. ὁ δὲ σπενδομένοις μὲν ἔφη, καθάπερ προεῖπε Κινέας, χαριεῖσθαι τοὺς αἰχμαλώτους, πολεμοῦσι δ’ οὐ δώσειν ἐφ’ ἑαυτὸν ἄνδρας τοιούτους καὶ τοσούτους. ἐξένιζε δ’ αὐτοὺς βασιλικῶς, καὶ τὸν τῆς πρεσβείας ἡγούμενον Φαβρίκιον πυνθανόμενος ἐν τῇ πόλει μέγα δύνασθαι καὶ δεινῶς πένεσθαι καθωμίλει, λέγων, εἰ πράξειεν αὐτῷ τὰς διαλύσεις, ὑποστράτηγον καὶ κοινωνὸν τῶν παρόντων ἀγαθῶν ἀπάξειν ἐς Ἤπειρον. χρήματά τε αὐτὸν λαβεῖν ἐντεῦθεν ἤδη παρεκάλει, πρόφασιν ὡς δώσοντα τοῖς τὴν εἰρήνην ἐργασαμένοις. ἐπιγελάσας δ’ ὁ Φαβρίκιος περὶ μὲν τῶν κοινῶν οὐδ’ ἀπεκρίνατο, “τὴν δ’ ἐμήν,” ἔφη, “παρρησίαν οὔτε τῶν σῶν φίλων οὐδεὶς οὔτε αὐτὸς οἴσεις σύ, ὦ βασιλεῦ· καὶ τὴν πενίαν τὴν ἐμαυτοῦ μακαρίζω μᾶλλον ἢ τὸν τῶν τυράννων πλοῦτον ὁμοῦ καὶ φόβον.” οἱ δὲ οὐχ οὕτω φασὶν αὐτόν, ἀλλ’ ὅτι μου τῆς φύσεως Ἠπειρῶται μεταλαβόντες ἐμὲ σοῦ προθήσουσιν.", "st": "4.10"}, {"sp": "N", "t": "ὁποτέρως δ’ οὖν ἀπεκρίνατο, θαυμάσας αὐτὸν τοῦ φρονήματος ὁ Πύρρος ἑτέραν ὁδὸν ἐς τὰς διαλλαγὰς ἐπενόει, καὶ τοὺς αἰχμαλώτους ἐς τῶν Κρονίων τὴν ἑορτὴν ἔπεμπεν ἄνευ φυλάκων, ἐφ’ ᾧ, δεχομένης μὲν τῆς πόλεως ἃ ὁ Πύρρος προτείνει, μένειν καὶ τῆς αἰχμαλωσίας ἀπολελύσθαι, μὴ δεχομένης δὲ ἑορτάσαντας ἐπανήκειν ἐς αὐτόν. τούτους ἡ βουλή, πάνυ παρακαλοῦντας καὶ ἐνάγοντας ἐς τὰς διαλύσεις, ἐκέλευσεν ἑορτάσαντας Πύρρῳ παραδοῦναι σφᾶς αὐτοὺς ἐν ἡμέρᾳ ῥητῇ, καὶ θάνατον ἐπέταξε τοῖς ἀπολειφθεῖσι τῆς ἡμέρας. οἱ δὲ καὶ αὐτὴν ἅπαντες ἐφύλαξαν, καὶ Πύρρῳ πολεμητέα πάντως αὖθις ἐδόκει.", "st": "4.10"}, {"sp": "N", "t": "ὅτι τὸν Πύρρον ἤδη μὲν τὰ Ῥωμαίων κατέπλησσεν, ἐτάρασσε δὲ καὶ τὰ ἐν Μολοσσοῖς θορυβούμενα. Ἀγαθοκλῆς τε, ἄρχων Σικελίαν ἄρτι ἐτεθνήκει, οὗ θυγατέρα Λάνασσαν ἔχων ο Πύρρος ἐν ταῖς γυναιξί, τὴν νῆσον οἰκείαν ἀντὶ τῆς Ἰταλίας περιεβλέπετο. ὤκνει δ’ ὅμως ἔτι τοὺς ἐπικαλέσαντας ἄνευ τινὸς εἰρήνης καταλιπεῖν. ἄσμενος οὖν τῆς προφάσεως τῆς περὶ τὸν αὐτόμολον ἐπιβὰς ἐμαρτύρει τοῖς ὑπάτοις, καὶ Κινέαν ἔπεμπεν ἐς Ῥώμην χάριν ὁμολογήσοντα τῆς σωτηρίας τοῦ βασιλέως, καὶ τοὺς αἰχμαλώτους ἀμοιβὴν ἄγοντα, εἰρήνην τε ὅτῃ δύναιτο πράξοντα. δῶρα δ’ ὁ Κινέας ἔφερε πολλὰ μὲν ἀνδράσι πολλὰ δὲ γυναιξί, φιλοχρήματον καὶ φιλόδωρον εἶναι τὴν πόλιν πυθόμενος, καὶ τὰς γυναῖκας ἰσχύειν παρὰ Ῥωμαίοις ἐκ παλαιοῦ.", "st": "4.11"}, {"sp": "N", "t": "οἱ δὲ περὶ μὲν τῶν δώρων ἐνεκελεύσαντο ἀλλήλοις· καί φασιν οὐδένα λαβεῖν οὐδέν, οὔτε ἄνδρα οὔτε γυναῖκα. ἀπεκρίναντο δ’ αὐτῷ, καθὰ καὶ πρότερον, ἀπελθόντα Πύρρον ἐξ Ἰταλίας πρεσβεύειν πρὸς αὐτοὺς ἄνευ δώρων· ἀπορήσειν γὰρ οὐδενὸς τῶν δικαίων. τοὺς δὲ πρέσβεις καὶ αὐτοὶ πολυτελῶς ἐξένιζον, καὶ Πύρρῳ τοὺς Ταραντίνων καὶ τῶν ἄλλων αὐτοῦ συμμάχων αἰχμαλώτους ἀντέπεμπον. ὁ μὲν δὴ Πύρρος ἐπὶ τούτοις ἐς Σικελίαν διέπλει μετά τε τῶν ἐλεφάντων … καὶ ὀκτακισχιλίων ἱππέων, ὑποσχόμενος τοῖς συμμάχοις ἐκ Σικελίας ἐπανήξειν ἐς τὴν Ἰταλίαν. καὶ ἐπανῆλθεν ἔτει τρίτῷ, Καρχηδονίων αὐτὸν ἐξελασάντων ἐκ Σικελίας.", "st": "4.11"}, {"sp": "N", "t": "ὅτι Πύρρος μετὰ τὴν μάχην καὶ τὰς πρὸς Ῥωμαίους συνθήκας ἐς Σικελίαν διέπλει, ὑποσχόμενος τοῖς συμμάχοις ἐκ Σικελίας ἐπανήξειν ἐς Ἰταλίαν. καὶ ἐπανῆλθεν ἔτει τρίτῳ, Καρχηδονίων αὐτὸν ἐξελασάντων ἐκ Σικελίας, ἤδη καὶ τοῖς Σικελιώταις βαρὺν ἐπί τε ξενίαις καὶ χορηγίαις καὶ φρουραῖς καὶ ἐσφοραῖς γενόμενον. ὁ μὲν δὴ πλούσιος ἐν τῶνδε γεγονὼς ἐς τὸ Ῥήγιον διέπλει ναυσὶ καταφράκτοις δέκα καὶ ἑκατόν, φορτίσι δὲ καὶ ὁλκάσι πολὺ πλείοσιν· οἱ δὲ Καρχηδόνιοι διαναυμαχήσαντες αὐτῷ κατέδυσαν ναῦς ἑβδομήκοντα, καὶ τὰς λοιπὰς ἄπλους ἐποίησαν, πλὴν δώδεκα μόνων, αἷς ὁ Πύρρος διαφυγὼν ἐτίνυτο Λοκροὺς τοὺς ἐπιζεφυρίους, ὅτι φρουρὰν αὐτοῦ καὶ τὸν φρούραρχον αὐτῆς, ὑβρίσαντας ἐς αὐτούς, ἀνῃρήκεσαν. ὠμῶς δ’ αὐτοὺς καὶ πικρῶς κτείνων τε καὶ συλῶν ὁ Πύρρος οὐδὲ τῶν ἀναθημάτων τῆς Περσεφόνης ἀπέσχετο, ἐπισκώψας τὴν ἄκαιρον θεοσέβειαν εἶναι δεισιδαιμονίαν, τὸ δὲ συλλέξαι πλοῦτον ἄπονον εὐβουλίαν.", "st": "4.12"}, {"sp": "N", "t": "ἀναχθέντα δ’ αὐτὸν μετὰ τῶν σύλων χειμὼν ὑπέλαβε, καὶ τῶν νεῶν τὰς μὲν κατέδυσε καὶ διέφθειρεν αὐτοῖς ἀνδράσι, τὰς δ’ ἐς τὴν γῆν ἐξέρριψεν. τὰ δὲ ἱερὰ πάντα σῶα ὁ κλύδων ἐς τοὺς Λοκρῶν λιμένας ἐπανήγαγεν, ὥστε καὶ Πύρρον ὀψὲ τῆς ἀσεβείας αἰσθόμενον ἀναθεῖναί τε αὐτὰ ἐς τὸ ἱερὸν τῇ Περσεφόνῃ, καὶ θυσίαις ἱλάσκεσθαι τὴν θεὸν πολλαῖς. τῶν δὲ ἱερῶν οὐκ ἀπαντώντων ἔτι μᾶλλον ἐξεμαίνετο, καὶ τοὺς περὶ τῆς ἱεροσυλίας αὐτῷ συμβουλεύσαντας ἢ λέγοντι συνθεμένους, ἢ διακονησαμένους τὸ ἔργον, ἔκτεινεν. ὁ μὲν δὴ Πύρρος οὕτως ἐπεπράχει κακῶς.", "st": "4.12"}, {"sp": "HDR", "t": "Ἐκ τῆς Κελτικῆς", "st": "5"}, {"sp": "N", "t": "Κελτοὶ Ῥωμαίοις ἐπεχείρησαν πρῶτοι, καὶ τὴν Ῥώμην εἷλον ἄνευ τοῦ Καπιτωλίου, καὶ ἐμπεπρήκασιν. Κάμιλλος δὲ αὐτοὺς ἐνίκησε καὶ ἐξήλασε, καὶ μετὰ χρόνον ἐπελθόντας αὖθις ἐνίκησε, καὶ ἐθριάμβευσεν ἀπ’ αὐτῶν ὀγδοήκοντα γεγονὼς ἔτη. καὶ τρίτη δὲ Κελτῶν στρατιὰ ἐμβέβληκεν ἐς τὴν Ἰταλίαν, ἣν καὶ αὐτὴν οἱ Ῥωμαῖοι διεφθάρκασιν ὑφ’ ἡγεμόνι Τίτῳ Κοϊντίῳ. μετὰ δὲ ταῦτα Βοιοί, Κελτικὸν ἔθνος θηριωδέστατον, ἐπῆλθε Ῥωμαίοις, καὶ αὐτοῖς Γάϊος Σουλπίκιος δικτάτωρ μετὰ στρατιᾶς ἀπήντα, ὅς τις καὶ στρατηγήματι τοιούτῳ χρήσασθαι λέγεται· ἐκέλευσε γὰρ τοὺς ἐπὶ τοῦ μετώπου τεταγμένους ἐξακοντίσαντας ὁμοῦ συγκαθίσαι τάχιστα, μέχρι βάλωσιν οἱ δεύτεροι καὶ τρίτοι καὶ τέταρτοι, τοὺς δ’ ἀφιέντας ἀεὶ συνίζειν, ἵνα μὴ κατ’ αὐτῶν ἐνεχθείη τὰ δόρατα· βαλόντων δὲ τῶν ὑστάτων ἀναπηδᾶν ἅπαντας ὁμοῦ, καὶ σὺν βοῇ τάχιστα ἐς χεῖρας ἰέναι· καταπλήξειν γὰρ ὧδε τοὺς πολεμίους τοσῶνδε δοράτων ἄφεσιν καὶ ἐπ’ αὐτῇ ταχεῖαν ἐπιχείρησιν. τὰ δὲ δόρατα ἦν οὐκ ἀπεοικότα ἀκοντίοις· ἃ Ῥωμαῖοι καλοῦσιν ὑσσούς, ξύλου τετραγώνου τὸ ἥμισυ, καὶ τὸ ἄλλο σιδήρου, τετραγώνου καὶ τοῦδε καὶ μαλακοῦ χωρίς γε τῆς αἰχμῆς. καὶ οἱ Βοιοὶ οὖν ὑπὸ Ῥωμαίων τότε ἐφθάρησαν πανστρατιᾷ.", "st": "5.1"}, {"sp": "N", "t": "ἄλλους δὲ πάλιν Κελτοὺς ἐνίκα Ποπίλλιος, καὶ μετ’ ἐκεῖνον τοὺς αὐτοὺς Κάμιλλος ὁ τοῦ Καμίλλου υἱός. ἔστησε δὲ κατὰ Κελτῶν καὶ Πάππος Αἰμίλιος τρόπαια. πρὸ δὲ τῶν τοῦ Μαρίου ὑπατειῶν πλεῖστόν τι καὶ μαχιμώτατον, τῇ τε ἡλικίᾳ μάλιστα φοβερώτατον χρῆμα Κελτῶν ἐς τὴν Ἰταλίαν τε καὶ Γαλατίαν ἐσέβαλε, καί τινας ὑπάτους Ῥωμαίων ἐνίκησε καὶ στρατόπεδα κατέκοψεν· ἐφ’ οὓς ὁ Μάριος ἀποσταλεὶς ἅπαντας διέφθειρε. τελευταῖα δὲ καὶ μέγιστα τῶν ἐς Γαλάτας Ῥωμαίοις πεπραγμένων ἐστὶ τὰ ὑπὸ Γαΐῳ Καίσαρι στρατηγοῦντι γενόμενα. μυριάσι τε γὰρ ἀνδρῶν ἀγρίων, ἐν τοῖς δέκα ἔτεσιν ἐν οἷς ἐστρατήγησεν, ἐς χεῖρας ἦλθον, εἴ τις ὑφ’ ἓν τὰ μέρη συναγάγοι, τετρακοσίων πλείοσι, καὶ τούτων ἑκατὸν μὲν ἐζώγρησαν, ἑκατὸν δ’ ἐν τῷ πόνῳ κατέκανον. ἔθνη δὲ τετρακόσια καὶ πόλεις ὑπὲρ ὀκτακοσίας, τὰ μὲν ἀφιστάμενα σφῶν, τὰ δὲ προσεπιλαμβάνοντες, ἐκρατύναντο. πρὸ δὲ τοῦ Μαρίου καὶ Φάβιος Μάξιμος ὁ Αἰμιλιανός, ὀλίγην κομιδῇ στρατιὰν ἔχων, ἐπολέμησε τοῖς Κελτοῖς, καὶ δώδεκα μυριάδας αὐτῶν ἐν μιᾷ μάχῃ κατέκανε, πεντεκαίδεκα μόνους τῶν ἰδίων ἀποβαλών. καὶ ταῦτα μέντοι ἔπραξε πιεζόμενος ὑπὸ τραύματος ὑπογυίου, καὶ τὰ τάγματα ἐπιὼν καὶ παραθαρρύνων, καὶ διδάσκων ὅπως τοῖς βαρβάροις πολεμητέον, τὰ μὲν ἐπ’ ἀπήνης φερόμενος, τὰ δὲ καὶ βάδην χειραγωγούμενος.", "st": "5.1"}, {"sp": "N", "t": "Καῖσαρ δὲ πολεμήσας αὐτοῖς πρῶτον μὲν Ἑλουητίους καὶ Τιγυρίους ἀμφὶ τὰς εἴκοσι μυριάδας ὄντας ἐνίκησεν. οἱ Τιγύριοι δ’ αὐτῶν χρόνῳ ἔμπροσθεν Πίσωνος καὶ Κασσίου τινὰ στρατὸν ἑλόντες ὑπὸ ζυγὸν ἐξεπεπόμφεσαν, ὡς ἐν χρονικαῖς συντάξεσι δοκεῖ Παύλῳ τῷ Κλαυδίῳ. τοὺς μὲν οὖν Τιγυρίους ὑποστράτηγος αὐτοῦ Λαβιηνὸς ἐνίκησε, τοὺς δὲ ἄλλους ὁ Καῖσαρ, καὶ Τρικούρους ἀμύνοντας σφίσιν, ἔπειτα τοὺς μετ’ Ἀριοουίστου Γερμανούς, οἳ καὶ τὰ μεγέθη μείζους τῶν μεγίστων ὑπῆρχον καὶ τὸ ἦθος ἄγριοι καὶ τὴν τόλμαν θρασύτατοι, καὶ θανάτου καταφρονηταὶ δι’ ἐλπίδα ἀναβιώσεως, καὶ κρύος ὁμοίως ἔφερον θάλπει, καὶ πόᾳ ἐχρῶντο παρὰ τὰς ἀπορίας τροφῇ, καὶ ὁ ἵππος ξύλοις. ἦσαν δέ, ὡς ἔοικεν, οὐ φερέπονοι ἐν ταῖς μάχαις, οὐδὲ λογισμῷ ἢ ἐπιστήμῃ τινὶ ἀλλὰ θυμῷ χρώμενοι καθάπερ θηρία, διὸ καὶ ὑπὸ τῆς Ῥωμαίων ἐπιστήμης καὶ φερεπονίας ἡσσῶντο. οἱ μὲν γὰρ μετὰ ὁρμῆς βαρυτάτης ἐπεπήδων αὐτοῖς, καὶ ὅλην ὁμοῦ τὴν φάλαγγα ἀνεώθουν· Ῥωμαῖοι δ’ ὑπέμενον ἐν τάξει, καὶ κατεστρατήγουν αὐτούς, καὶ ὀκτακισμυρίους αὐτῶν τελευτῶντες ἀπέκτειναν.", "st": "5.1"}, {"sp": "N", "t": "μετὰ τούτους ὁ Καῖσαρ τοῖς καλουμένοις Βέλγαις ἐπιπεσὼν ποταμόν τινα περῶσι, τοσούτους ἀπέκτεινεν ὡς τὸν ποταμὸν γεφυρωθέντα τοῖς σώμασι περᾶσαι. Νέρβιοι δὲ αὐτὸν ἐτρέψαντο, ἄρτι στρατόπεδον ἐξ ὁδοιπορίας κατασκευάζοντι αἰφνιδίως ἐπιπεσόντες, καὶ παμπόλλους ἐφόνευσαν, τοὺς δὲ ταξιάρχας καὶ λοχαγοὺς ἅπαντας· καὶ αὐτὸν ἐκεῖνον ἐς λόφον τινὰ μετὰ τῶν ὑπασπιστῶν πεφευγότα περιέσχον κύκλῳ. ὑπὸ δὲ τοῦ δεκάτου τάγματος αὐτοῖς ἐξόπισθεν ἐπιπεσόντος ἐφθάρησαν, ἑξακισμύριοι ὄντες. ἦσαν δὲ τῶν Κίμβρων καὶ Τευτόνων ἀπόγονοι. ἐκράτησε δὲ καὶ Ἀλλοβρίγων ὁ Καῖσαρ. Οὐσιπετῶν δὲ καὶ Ταγχαρέων τεσσαράκοντα μυριάδες, στρατεύσιμοί τε καὶ ἀστράτευτοι, συνεκόπησαν. Σούκαμβροι δὲ πεντακοσίοις ἱππεῦσι τοὺς πεντακισχιλίους ἱππεῖς τοῦ Καίσαρος ἔτρεψαν, ἐξαίφνης ἐπιπεσόντες, καὶ δίκην ἔδοσαν ἡττηθέντες μετὰ ταῦτα.", "st": "5.1"}, {"sp": "N", "t": "ἐπέρασε καὶ τὸν Ῥῆνον πρῶτος Ῥωμαίων ὁ Καῖσαρ, καὶ ἐς τὴν Βρεττανίδα νῆσον, ἠπείρου τε μείζονα οὖσαν μεγίστης καὶ τοῖς τῇδε ἀνθρώποις ἄγνωστον ἔτι. ἐπέρασε δὲ κατὰ τὸν καιρὸν τῆς ἀμπώτεως· ἄρτι γὰρ τὸ πάθος ἥπτετο τῆς θαλάσσης, καὶ ὁ στόλος ἐσαλεύετο, ἠρέμα πρῶτον, εἶτα ὀξύτερον, μέχρι σὺν βιαίῳ τάχει διέπλευσεν ὁ Καῖσαρ ἐς τὴν Βρεττανίαν.", "st": "5.1"}, {"sp": "N", "t": "ὅτι Ὀλυμπιάδων τοῖς Ἕλλησιν ἑπτὰ καὶ ἐνενήκοντα γεγενημένων, τῆς γῆς τῶν Κελτῶν οὐκ ἀρκούσης αὐτοῖς διὰ τὸ πλῆθος, ἀνίσταται μοῖρα Κελτῶν τῶν ἀμφὶ τὸν Ῥῆνον ἱκανὴ κατὰ ζήτησιν ἑτέρας γῆς· οἳ τό τε Ἄλπειον ὄρος ὑπερέβησαν, καὶ Κλουσίνοις, εὐδαίμονα γῆν ἔχουσι Τυρρηνῶν, ἐπολέμουν. οὐ πάλαι δὲ οἱ Κλουσῖνοι Ῥωμαίοις ἔνσπονδοι γεγονότες ἐπ’ αὐτοὺς κατέφυγον. καὶ οἱ Ῥωμαῖοι πρέσβεις συνέπεμψαν αὐτοῖς, Φαβίους τρεῖς, οἳ τοῖς Κελτοῖς ἔμελλον προαγορεύσειν ἀνίστασθαι τῆς γῆς ὡς Ῥωμαίων φίλης, καὶ ἀπειλήσειν ἀπειθοῦσιν. ἀποκριναμένων δὲ τῶν Κελτῶν ὅτι ἀνθρώπων οὐδένα δεδίασιν οὔτε ἀπειλοῦντα σφίσιν οὔτε πολεμοῦντα, χρῄζοντες δὲ γῆς οὔπω τὰ Ῥωμαίων πολυπραγμονοῦσιν, οἱ πρέσβεις οἱ Φάβιοι τοὺς Κλουσίνους ἐνῆγον ἐπιθέσθαι τοῖς Κελτοῖς τὴν χώραν λεηλατοῦσιν ἀπερισκέπτως. καὶ συνεκδημοῦντες αὐτοῖς ἀναιροῦσι τῶν Κελτῶν πολὺ πλῆθος ἐν προνομῇ, καὶ τὸν ἡγούμενον ἐκείνου τοῦ μέρους αὐτὸς ὁ Ῥωμαίων πρεσβευτὴς Κόιντος Φάβιος ἀνεῖλέ τε καὶ ἐσκύλευσε, καὶ τὰ ὅπλα φορῶν ἐπανῆλθεν ἐς Κλούσιον.", "st": "5.2"}, {"sp": "N", "t": "ὅτι ὁ τῶν Κελτῶν βασιλεὺς Βρέννος, τῶν Φαβίων τῶν Ῥωμαίων πολλοὺς ἀνελόντων Κελτῶν, μὴ δεξάμενος τοὺς Ῥωμαίων πρέσβεις, ἐπὶ τούτοις πρέσβεις ἐπιλεξάμενος ἐς κατάπληξιν, οἳ Κελτῶν ἁπάντων μεγάλων τὰ σώματα ὄντων ὑπερέβαλλον, ἐξέπεμπεν ἐς Ῥώμην, αἰτιώμενος τοὺς Φαβίους ὅτι πρεσβεύοντες παρὰ τοὺς κοινοὺς νόμους ἐπολέμησαν. ᾔτει τε τοὺς ἄνδρας ἐς δίκην ἐκδότους οἱ γενέσθαι, εἰ μὴ θέλουσι Ῥωμαῖοι κοινὸν αὐτῶν εἶναι τὸ ἔργον. οἱ δὲ Ῥωμαῖοι συνεγίγνωσκον μὲν τοὺς Φαβίους ἁμαρτεῖν, αἰδοῖ δὲ οἴκου διαφέροντος χρήματα τοὺς Κελτοὺς πράξασθαι παρὰ σφῶν παρεκάλουν. οὐ πειθομένων δὲ χειροτονοῦσι τοὺς Φαβίους ἐπὶ τὴν ἐτήσιον ἀρχὴν χιλιάρχους, καὶ τοῖς πρεσβεύουσι τῶν Κελτῶν ἔφασαν οὐ δύνασθαι νῦν οὐδὲν ἐς τοὺς Φαβίους ἄρχοντας ἤδη. τοῦ δ’ ἐπιόντος ἔτους ἥκειν αὐτούς, ἂν ἔτι μηνίωσιν, ἐκέλευον. Βρέννος δὲ καὶ ὅσοι Κελτῶν ἦσαν ὑπ’ ἐκείνῳ, νομίσαντες ὑβρίσθαι καὶ χαλεπῶς ἐνεγκόντες ἐς τοὺς ἄλλους Κελτοὺς περιέπεμπον, ἀξιοῦντες αὐτοὺς συνεφάψασθαι τοῦδε τοῦ πολέμου. καὶ πολλῶν ἀφικομένων ἄραντες ἤλαυνον ἐπὶ τὴν Ῥώμην.", "st": "5.3"}, {"sp": "N", "t": "ὁ δὲ ὑφίσταται γράμματα διοίσειν διὰ τῶν ἐχθρῶν ἐς τὸ Καπιτώλιον.", "st": "5.4"}, {"sp": "N", "t": "ὅτι Καιδίκιος γράμμα φέρων ἀπὸ τῆς βουλῆς περὶ τῆς ὑπάτου ἀρχῆς, παρεκάλει τὸν Κάμιλλον μηδὲν ἐν τῷ παρόντι μηνῖσαι τῇ πατρίδι τῆς ζημίας. ὁ δὲ ἐπισχὼν αὐτὸν ἔτι λέγοντα εἶπεν, “οὐκ ἂν ηὐξάμην ἐπιποθῆσαί με Ῥωμαίους, εἰ τοιαύτην ἤλπισα τὴν ἐπιπόθησιν αὐτοῖς ἔσεσθαι. νῦν δὲ δικαιοτέραν εὐχὴν εὔχομαι, γενέσθαι τῇ πατρίδι χρήσιμος ἐς τοσοῦτον ἀγαθοῦ ἐς ὅσον κακοῦ περιελήλυθεν.”", "st": "5.5"}, {"sp": "N", "t": "ὅτι Κελτοὶ μηδεμιᾷ μηχανῇ δυνηθέντες ἐπιβῆναι τῆς ἀκροπόλεως, ἠρέμουν ὡς λιμῷ τοὺς ἔνδον παραστησόμενοι. καί τις ἀπὸ τοῦ Καπιτωλίου κατέβαινεν ἱερεύς, ὄνομα Δόρσων, ἐπὶ ἐτήσιον δή τινα ἱερουργίαν ἐς τὸν τῆς Ἑστίας νεὼν στέλλων τὰ ἱερὰ διὰ τῶν πολεμίων, αἰδεσθέντων ἢ καταπλαγέντων αὐτοῦ τὴν τόλμαν ἢ τὴν εὐσέβειαν, ἢ τὴν ὄψιν ἱερὰν οὖσαν. ὁ μὲν δὴ κινδυνεύειν ὑπὲρ τῶν ἱερῶν ἑλόμενος ὑπ’ αὐτῶν ἐσώζετο τῶν ἱερῶν. καὶ τόδε φησὶν ὧδε γενέσθαι Κάσσιος ὁ Ῥωμαῖος.", "st": "5.6"}, {"sp": "N", "t": "τοῦ δὲ οἴνου καὶ τῶν ἄλλων ἄδην ἐνεπίμπλαντο οἱ Κελτοί, τήν τε φύσιν ὄντες ἀκρατεῖς, καὶ χώραν ἔχοντες, ὅτι μὴ πρὸς δημητριακοὺς καρπούς, τῶν ἄλλων ἄγονον καὶ ἀφυᾶ. τά τε σώματα αὐτοῖς μεγάλα ὄντα καὶ τρυφηλὰ καὶ σαρκῶν ὑγρῶν μεστὰ ὑπὸ τῆς ἀδηφαγίας καὶ μέθης ἐς ὄγκον καὶ βάρος ἐξεχεῖτο, καὶ πρὸς δρόμους καὶ πόνους ἀδύνατα πάμπαν ἐγίγνετο· ὑπό τε ἱδρῶτος καὶ ἄσθματος, ὅπου τι δέοι κάμνειν, ἐξελύοντο ταχέως.", "st": "5.7"}, {"sp": "N", "t": "οὓς γυμνοὺς ἐπεδείκνυε Ῥωμαίοις, “οὗτοί εἰσιν οἱ τὴν βοὴν βαρεῖαν ἱέντες ὑμῖν ἐν ταῖς μάχαις καὶ τὰ ὅπλα παταγοῦντες καὶ ξίφη μακρὰ καὶ κόμας αἰωροῦντες. ὧν τὸ ἄτολμον ὁρῶντες, καὶ τὸ σῶμα μαλακὸν καὶ ἄτονον, προσίεσθε τῷ ἔργῳ.”", "st": "5.8"}, {"sp": "N", "t": "τὸν δὲ δῆμον ἀπὸ τοῦ τείχους ὁρᾶν, καὶ τοῖς πονουμένοις ἑτέρους νεαλεῖς ἐπιπέμπειν ἀεί. οἱ δὲ Κελτοὶ κεκμηκότες ἀκμῆσι συμπλεκόμενοι ἔφευγον ἀτάκτως.", "st": "5.9"}, {"sp": "N", "t": "ὁ δὲ Κελτὸς ἀγανακτῶν καὶ λιφαιμῶν ἐδιωκε τὸν Οὐαλέριον, συγκαταπεσεῖν ἐπειγομενος· ὑπὸ δὲ τοὺς πόδας ἀναχωροῦντος ἀεὶ τοῦ Οὐαλερίου κατέπεσε πρηνὴς ὁ Κελτός. καὶ δεύτερον τοῦτο μονομάχιον ἐπὶ Κελτοῖς ἐμεγαλαύχουν οἱ Ῥωμαῖοι.", "st": "5.10"}, {"sp": "N", "t": "ὅτι τὸ τῶν Σενόνων ἔθνος ἔνσπονδον ἦν Ῥωμαίοις, καὶ ἐμισθοφόρουν κατὰ Ῥωμαίων. ἡ δὲ βουλὴ πρέσβεις ἔπεμψεν ἐγκαλέσοντας ὅτι ὄντες ἔνσπονδοι μισθοφοροῦσι κατὰ Ῥωμαίων. τούτους Βριτόμαρις ὁ Κελτός, ἀγανακτῶν ὑπὲρ τοῦ πατρὸς ὅτι συμμαχῶν Τυρρηνοῖς ὑπὸ Ῥωμαίων ἐν τῷδε τῷ πολέμῳ διέφθαρτο, τά τε κηρύκεια φέροντας καὶ τὴν ἄσυλον ἐσθῆτα περικειμένους κατέτεμεν ἐς πολλά, καὶ τὰ μέρη τῶν σωμάτων διέρριψεν ἐς τὰ πεδία. καὶ τοῦ μύσους ὁ Κορνήλιος ἐν ὁδῷ πυθόμενος, ἐς τὰς Σενόνων πόλεις συντόνῳ σπουδῇ διὰ Σαβίνων καὶ Πικεντίνων ἐσβαλὼν ἅπαντα καθῄρει καὶ ἐνεπίμπρη, τῶν τε ἀνθρώπων τὰς μὲν γυναῖκας καὶ τὰ παιδία ἠνδραποδίζετο, τοὺς δὲ ἐν ἥβῃ πάντας ἔκτεινεν ὁμαλῶς, καὶ τὴν χώραν ἐλυμαίνετο ποικίλως καὶ ἄοικον ἐς τὸ λοιπὸν ἐποίει. Βριτόμαριν δὲ μόνον ἦγεν αἰχμάλωτον ἐπὶ λύμῃ. ὕστερον δὲ Σένονες οὐκ ἔχοντες ἔτι πατρίδας ἐς ἃς διαφύγωσι, συνέπεσον ἐς χεῖρας ὑπὸ τόλμης τῷ Δομετίῳ, καὶ ἡττώμενοι σφᾶς αὐτοὺς ὑπ’ ὀργῆς διεχρῶντο μανικῶς. καὶ δίκη μὲν ἥδε παρανομίας ἐς πρέσβεις ἐγένετο Σένοσιν.", "st": "5.11"}, {"sp": "N", "t": "ὅτι οἱ Σαλύων δυνάσται, τοῦ ἔθνους ἡττηθέντος ὑπὸ Ῥωμαίων, ἐς Ἀλλόβριγας κατέφυγον. καὶ αὐτοὺς ἐξαιτοῦντες οἱ Ῥωμαῖοι στρατεύουσιν ἐπὶ τοὺς Ἀλλόβριγας οὐκ ἐκδιδόντας, ἡγουμένου σφῶν Γναίου Δομετίου. ᾧ παροδεύοντι τὴν τῶν Σαλύων ἐντυγχάνει πρεσβευτὴς Βιτοίτου βασιλέως τῶν Ἀλλοβρίγων, ἐσκευασμένος τε πολυτελῶς, καὶ δορυφόροι παρείποντο αὐτῷ κεκοσμημένοι καὶ κύνες· δορυφοροῦνται γὰρ δὴ καὶ πρὸς κυνῶν οἱ τῇδε βάρβαροι. μουσικός τε ἀνὴρ εἵπετο, βαρβάρῳ μουσικῇ τὸν βασιλέα Βιτοῖτον, εἶτ’ Ἀλλόβριγας, εἶτα τὸν πρεσβευτὴν αὐτὸν ἔς τε γένος καὶ ἀνδρείαν καὶ περιουσίαν ὑμνῶν· οὗ δὴ καὶ μάλιστα ἕνεκα αὐτοὺς οἱ τῶν πρεσβευτῶν ἐπιφανεῖς ἐπάγονται. ἀλλ’ ὁ μὲν συγγνώμην αἰτῶν τοῖς Σαλύων δυνάσταις ἀπέτυχεν.", "st": "5.12"}, {"sp": "N", "t": "ὅτι τῶν Τευτόνων μοῖρα λῃστεύουσα πολύανδρος ἐς τὴν γῆν τῶν Νωρικῶν ἐσέβαλε, καὶ ὁ Ῥωμαίων ὕπατος Παπίριος Κάρβων δείσας μὴ ἐς τὴν Ἰταλίαν ἐσβάλοιεν, ἐφήδρευε τοῖς Ἀλπείοις, ᾗ μάλιστά ἐστιν ἡ διάβασις στενωτάτη. οὐκ ἐπιχειρούντων δ’ ἐκείνων αὐτὸς ἐπέβαινεν αὐτοῖς, αἰτιώμενος ἐς Νωρικοὺς ἐσβαλεῖν, Ῥωμαίων ξένους ὄντας· ἐποιοῦντο δ’ οἱ Ῥωμαῖοι ξένους, οἷς ἐδίδοσαν μὲν εἶναι φίλοις, ἀνάγκη δ’ οὐκ ἐπῆν ὡς φίλοις ἐπαμύνειν. οἱ μὲν δὴ Τεύτονες πλησιάζοντι τῷ Κάρβωνι προσέπεμπον ἀγνοῆσαί τε τὴν ἐς Ῥωμαίους Νωρικῶν ξενίαν, καὶ αὐτῶν ἐς τὸ μέλλον ἀφέξεσθαι· ὁ δ’ ἐπαινέσας τοὺς πρέσβεις, καὶ δοὺς αὐτοῖς ὁδῶν ἡγεμόνας, κρύφα τοῖς ἡγουμένοις ἐνετείλατο μακροτέραν αὐτοὺς περιάγειν. τῇ βραχυτέρᾳ δὲ αὐτὸς διαδραμών, ἀδοκήτως ἀναπαυομένοις ἔτι τοῖς Τεύτοσιν ἐμπεσών, ἔδωκε δίκην ἀπιστίας, πολλοὺς ἀποβαλών. τάχα δ’ ἂν καὶ πάντας ἀπώλεσεν, εἰ μὴ ζόφος καὶ ὄμβρος καὶ βρονταὶ βαρεῖαι, τῆς μάχης ἔτι συνεστώσης ἐπιπεσοῦσαι, διέστησαν αὐτοὺς ἀπ’ ἀλλήλων, καὶ ὁ ἀγὼν ὑπὸ τῆς ἄνωθεν ἐκπλήξεως διελύθη. σποράδες δὲ καὶ ὣς ἐς ὕλας οἱ Ῥωμαῖοι διαφυγόντες, τρίτῃ μόλις ἡμέρᾳ συνῆλθον. καὶ Τεύτονες ἐς Γαλάτας ἐχώρουν.", "st": "5.13"}, {"sp": "N", "t": "ὁ δὲ τοῖς σώμασι τῶν Κίμβρων ἀψαυστεῖν ἐκέλευεν, ἕως ἡμέρα γένγται, πολύχρυσα εἶναι δοκῶν.", "st": "5.14"}, {"sp": "N", "t": "ὅτι ἔθνη δύο Τιγύριοι καὶ Ἑλουήτιοι ἐς τὴν Ῥωμαίων Κελτικὴν ἐσέβαλον, καὶ τούτων τὸν στόλον ὁ Καῖσαρ Γάϊος πυθόμενος διετείχισεν ὅσα περὶ Ῥοδανόν ἐστι ποταμὸν ἐς ἑκατὸν καὶ πεντήκοντα σταδίους μάλιστα. καὶ πρεσβευσαμένοις ἐπὶ διαπείρᾳ τοῖς πολεμίοις ὑπὲρ σπονδῶν ἐκέλευεν ὅμηρα δοῦναι καὶ χρήματα. ἀποκριναμένων δ’ εἰθίσθαι ταῦτα λαμβάνειν, οὐ διδόναι, βουλόμενος φθάσαι τὴν ὁμαιχμίαν αὐτῶν, ἐπὶ μὲν τοὺς Τιγυρίους ἐλάσσους ὄντας ἔπεμπε Λαβιηνόν, αὐτὸς δὲ ἐπὶ τοὺς Ἑλουητίους ἐχώρει, προσλαβὼν Γαλατῶν τῶν ὀρείων ἐς δισμυρίους. καὶ γίγνεται Λαβιηνῷ τὸ ἔργον εὐμαρές, ἀδοκήτοις Τιγυρίοις περὶ τὸν ποταμὸν ἐπιπεσόντι, καὶ τρεψαμένῳ καὶ σκεδάσαντι τοὺς πολλοὺς ἐν ἀσυνταξίᾳ.", "st": "5.15"}, {"sp": "N", "t": "ὅτι Ἀριόουιστος, Γερμανῶν βασιλεὺς τῶν ὑπὲρ Ῥῆνον, ἐπιβαίνων τῆς πέραν Αἰδούοις ἔτι πρὸ τοῦ Καίσαρος ἐπολέμει φίλοις οὖσι Ῥωμαίων. τότε μὲν δή, τοῖς Ῥωμαίοις κελεύουσι πεισθείς, ἀνέζευζεν ἀπὸ τῶν Αἰδούων, καὶ φίλος ἠξίωσε Ῥωμαίοις γενέσθαι. καὶ ἐγένετο, ὑπατεύοντος αὐτοῦ Καίσαρος καὶ ψηφισαμένου.", "st": "5.16"}, {"sp": "N", "t": "ὅτι Ἀριόουιστος ὁ Γερμανῶν βασιλεύς, φίλος γενόμενος Ῥωμαίων, ἐς λόγους ἦλθε τῷ Καίσαρι, καὶ διαχωρισθέντων ἀπ’ ἀλλήλων αὖθις συνελθεῖν ἐς λόγους ἠξίωσεν. τοῦ δὲ Καίσαρος οὐ συνελθόντος, ἀλλὰ τοὺς πρωτεύοντας Γαλατῶν ἀποστείλαντος, ἔδησε τοὺς πρέσβεις. καὶ ὁ Καῖσαρ ἐστράτευεν ἐπ’ αὐτὸν μετ’ ἀπειλῆς. δέος δ’ ἐμπίπτει τῷ στρατῷ κατὰ κλέος τῶν Γερμανῶν.", "st": "5.17"}, {"sp": "N", "t": "ὅτι Οὐσιπέται, ἔθνος Γερμανικόν, καὶ Ταγχρέαι δοκοῦσι πρότεροι σφετέροις ἱππεῦσιν ὀκτακοσίοις τρέψασθαι τῶν Καίσαρος ἱππέων ἐς πεντακισχιλίους, ὁ δὲ Καῖσαρ αὐτοῖς πρεσβευομένοις ἐς αὐτὸν ἐπιθέσθαι, τοὺς πρέσβεις κατασχών, καὶ τὸ πάθος ἐκείνοις ἐς τέλος αἰφνίδιον οὕτω συνενεχθῆναι ὡς τεσσαράκοντα μυριάδας τούτων συγκοπῆναι. Κάτωνά τε ἐν Ῥώμῃ τῶν τις συγγραφέων φησὶ γνώμην ἐσενεγκεῖν, ἐκδοῦναι τοῖς βαρβάροις τὸν Καίσαρα ὡς ἐναγὲς ἔργον ἐς διαπρεσβευσαμένους ἐργασάμενον. ὁ δὲ Καῖσαρ ἐν ταῖς ἰδίαις ἀναγραφαῖς τῶν ἐφημέρων ἔργων φησὶ τοὺς Οὐσιπέτας καὶ Ταγχρέας κελευομένους ἐκπηδᾶν ἐς τὰ ἀρχαῖα σφῶν, φάναι πρέσβεις ἐς τοὺς ἐκβαλόντας Σουήβους ἀπεσταλκέναι καὶ τὰς ἀποκρίσεις αὐτῶν ἀναμένειν, καὶ ἐν ταῖσδε ταῖς διαπρεσβεύσεσιν ἐπιθέσθαι τοῖς ὀκτακοσίοις, καὶ παρ’ αὐτὸ τρέψαι τοὺς Ῥωμαίων πεντακισχιλίους. ἐπιπρεσβευομένων δ’ αὐτῶν καὶ περὶ τοῦ παρασπονδήματος ἀπολογουμένων, ὑποτοπήσας ἐνέδραν ὁμοίαν, ἐπιθέσθαι πρὸ τῶν ἀποκρίσεων.", "st": "5.18"}, {"sp": "N", "t": "εὐθὺς ἠρέθιζον τοὺς Βρεττανοὺς παρορκῆσαι, ἔγκλημα ἔχοντας ὅτι σπονδῶν σφίσι γενομένων ἔτι παρῆν τὸ στρατόπεδον.", "st": "5.19"}, {"sp": "N", "t": "δείσας ὁ Καῖσαρ περὶ τῷ Κικέρωνι ὑπέστρεφεν εἰς τοὐπίσω.", "st": "5.20"}, {"sp": "N", "t": "ὅτι ὁ Βριτόρης διέφθειρεν Αἰδούους Ῥωμαίων ἀποστῆναι, καὶ τοῦ Καίσαρος ὀνειδίσαντος αὐτοῖς φιλίαν ἔφασαν παλαιὰν ἐφθακέναι.", "st": "5.21"}, {"sp": "HDR", "t": "Ἐκ τῆς Σικελικῆς καὶ Νησιωτικῆς", "st": "6"}, {"sp": "N", "t": "ὅτι ἀποροῦντες Ῥωμαῖοί τε καὶ Καρχηδόνιοι χρηματων, οἱ μὲν οὐκέτι ἐναυπήγουν, τετρυμένοι διὰ τὰς ἐσφοράς, ἀλλὰ πεζὴν στρατιὰν καταλέγοντες ἐξέπεμπον ἐς Λιβύην καὶ ἐς Σικελίαν ἀνὰ ἔτος ἕκαστον, Καρχηδόνιοι δ’ ἐς Πτολεμαῖον ἐπρεσβεύοντο, τὸν Πτολεμαίου τοῦ Λάγου, βασιλέα Αἰγύπτου, δισχίλια τάλαντα κιχρώμενοι. τῷ δ’ ἦν ἔς τε Ῥωμαίους καὶ Καρχηδονίους φιλία, καὶ συναλλάξαι σφᾶς ἐπεχείρησεν ἀλλήλοις. οὐ δυνηθεὶς δ’ ἔφη χρῆναι φίλοις κατ’ ἐχθρῶν συμμαχεῖν, οὐ κατὰ φίλων.", "st": "6.1"}, {"sp": "N", "t": "ὅτι οἱ Καρχηδόνιοι δὶς ἐν τῇ γῇ τοῦ αὐτοῦ χρόνου καὶ δὶς ἐν τῇ θαλάσσῃ παθόντες, ἐν ᾗ δὴ καὶ πάνυ προύχειν ἐνόμιζον, καὶ χρημάτων ἀποροῦντες ἤδη καὶ νεῶν καὶ ἀνδρῶν, ᾔτουν ἀνοχὰς παρὰ τοῦ Λουτατίου, καὶ λαβόντες ἐπρεσβεύοντὸ ἐς Ῥώμην περὶ διαλλαγῶν ἐπὶ βραχυτέροις, συνέπεμπόν τε τοῖς πρέσβεσιν Ἀτίλιον Ῥῆγλον τὸν ὕπατον, αἰχμάλωτον ὄντα σφῶν, δεησόμενον τῆς πατρίδος ἐπὶ τοῖσδε συνθέσθαι. ὁ δὲ ἧκε μὲν ὡς αἰχμάλωτος ἐσταλμένος φοινικικῶς, ὑπολειφθεὶς δὲ τῶν πρέσβεων ἐν τῷ βουλευτηρίῳ τετρῦσθαι τὰ Καρχηδονίων ἐδήλου, καὶ παρῄνεσεν ἢ πολεμεῖν ἐγκρατῶς ἢ ἐπὶ πλείοσι συνθέσθαι. καὶ τόνδε μὲν ἐς Καρχηδόνα ἑκόντα ἐπανελθόντα ἔκτειναν οἱ Καρχηδόνιοι, κέντρα σιδήρεα σανίσιν ἐνηρμοσμένα πάντοθεν ἑστῶτι περιθέντες, ἵνα μηδαμόσε δύναιτο ἐπικλίνεσθαι, αὐτοὶ δὲ τὴν εἰρήνην ἐπὶ πλείοσι συνέθεντο.", "st": "6.2"}, {"sp": "N", "t": "καὶ ἦν ἐφ’ οἷς συνέθεντο, τὰ μὲν αἰχμάλωτα Ῥωμαίων καὶ τοὺς αὐτομόλους, ὅσοι παρὰ Καρχηδονίοις εἰσί, Ῥωμαίοις εὐθὺς ἀποδοῦναι, καὶ Σικελίας Ῥωμαίοις ἀποστῆναι καὶ τῶν βραχυτέρων νήσων ὅσαι περὶ Σικελίαν, Συρακοσίοις δὲ ἢ Ἱέρωνι τῷ Συρακουσῶν τυράννῳ πολέμου Καρχηδονίους μὴ κατάρχειν, μηδὲ ἐκ τῆς Ἰταλίας ξενολογεῖν, ποινὴν δὲ τοῦ πολέμου Ῥωμαίοις ἐνεγκεῖν τάλαντα Εὐβοϊκὰ δισχίλια ἐν ἔτεσιν εἴκοσι, τὸ μέρος ἑκάστου ἔτους ἐς Ῥώμην ἀναφέροντας. ἔχει δὲ τὸ Εὐβοϊκὸν τάλαντον Ἀλεξανδρείους δραχμὰς ἑπτακισχιλίας. ὁ μὲν δὴ πρῶτος περὶ Σικελίας Ῥωμαίοις καὶ Καρχηδονίοις πόλεμος, ἔτεσιν εἴκοσι καὶ τέσσαρσιν αὐτοῖς γενόμενος, ἐς τοῦτο ἐτελεύτα. καὶ ἀπώλοντο νῆες ἐν αὐτῷ Ῥωμαίων ἑπτακόσιαι, Καρχηδονίων δὲ πεντακόσιαι. Σικελίας δὲ οὕτω τοῦ πλέονος Ῥωμαῖοι κατέσχον, ὅσου Καρχηδόνιοι κατεῖχον· φόρους τε αὐτοῖς ἐπέθεσαν, καὶ τέλη τὰ θαλάσσια ταῖς πόλεσι μερισάμενοι στρατηγὸν ἐτήσιον ἔπεμπον ἐς Σικελίαν. Ἱέρωνα δὲ τὸν Συρακοσίων τύραννον, ἀνθ’ ὧν αὐτοῖς ἐς τόνδε τὸν πόλεμον συνεπεπράχει, φίλον καὶ σύμμαχον ἔθεντο.", "st": "6.2"}, {"sp": "N", "t": "καταλυθέντος δὲ τοῦ πολέμου τοῦδε, Κελτοὶ Καρχηδονίους τόν τε μισθὸν ᾔτουν τὸν ἔτι ὀφειλόμενον σφίσιν ἐκ Σικελίας, καὶ δωρεὰς ὅσας ὑπέσχητο αὐτοῖς δώσειν Ἀμίλχας. ᾔτουν δὲ καὶ Λίβυες, ὑπήκοοι μὲν ὄντες οἵδε Καρχηδονίων, ἀπὸ δὲ τῆς ἐν Σικελίᾳ στρατείας ἐπὶ φρονήματος γεγονότες καὶ τοὺς Καρχηδονίους ἀσθενεῖς καὶ ταπεινοὺς ὁρῶντες· ἐχαλέπαινόν τε αὐτοῖς τῆς ἀναιρέσεως τῶν τρισχιλίων, οὓς ἐσταυρώκεσαν τῆς ἐς Ῥωμαίους μεταβολῆς οὕνεκα. διωθουμένων δὲ τῶν Καρχηδονίων ἑκατέρους, κατέλαβον ἄμφω Τύνητα πόλιν καὶ Ἰτύκην, ἣ μεγίστη Λιβύης ἐστὶ μετὰ Καρχηδόνα· ὅθεν ὁρμώμενοι τήν τε ἄλλην ἀφίστανον καὶ τῶν Νομάδων τινὰς ἔπειθον καὶ δούλων πολὺ πλῆθος ἀποδιδρασκόντων ὑπεδέχοντο, τά τε Καρχηδονίων πάντα ἐλεηλάτουν. οἱ δὲ πανταχόθεν πολεμούμενοι συμμάχους ἐπὶ τοὺς Λίβυας Ῥωμαίους ἐπεκαλοῦντο. καὶ Ῥωμαῖοι στρατιὰν μὲν αὐτοῖς οὐκ ἔπεμψαν, ἀγορὰν δ’ ἔκ τε Ἰταλίας καὶ Σικελίας ἐπάγεσθαι καὶ ξενολογεῖν ἐκ τῆς Ἰταλίας ἐς μόνον τόνδε τὸν πόλεμον ἐπέτρεψαν. ἔπεμψαν δὲ καὶ πρέσβεις ἐς Λιβύην, εἰ δύναιντο διαλῦσαι τὸν πόλεμον· οἳ ἐπανῆλθον ἄπρακτοι. καὶ Καρχηδόνιοι ἐγκρατῶς εἴχοντο τοῦ πολέμου.", "st": "6.2"}, {"sp": "N", "t": "ὅτι Ἱπποκράτης καὶ Ἐπικύδης, ἀδελφὼ μὲν ἀλλήλων, στρατηγὼ δὲ Συρακοσίων, Ῥωμαίοις ἐκ πολλοῦ δυσχεραίνοντες, ἐπεὶ τὰς Συρακούσας οὐκ ἴσχυον ἐκπολεμῶσαι, κατέφυγον ἐς Λεοντίνους διαφερομένους τοῖς Συρακοσίοις, καὶ κατηγόρουν τῆς πατρίδος ὅτι τὰς σπονδὰς Ἱέρωνος ἐφ’ ὅλῃ Σικελίᾳ πεποιημένου μόνοι Συρακόσιοι σφίσιν αὐτοῖς ἀνακαινίσειαν. οἱ δὲ ἠρεθίζοντο. καὶ Συρακόσιοι μὲν ἐπεκήρυσσον, εἴ τις Ἱπποκράτους ἢ Ἐπικύδους κομίσειε τὴν κεφαλήν, ἰσόσταθμον αὐτῷ χρυσίον ἀντιδώσειν, Λεοντῖνοι δὲ αὑτῶν Ἱπποκράτη στρατηγὸν ᾑροῦντο.", "st": "6.3"}, {"sp": "N", "t": "ὅτι Σικελοὶ καὶ τέως ἀγανακτοῦντες ἐπὶ τῇ ὠμότητι Μαρκέλλου τοῦ στρατηγοῦ, μᾶλλόν τι καὶ τῷδε τῷ ἔργῳ συνεταράσσοντο, ἐφ’ ᾧ κατὰ προδοσίαν ἐς Συρακούσας ἐσῆλθεν. καὶ πρὸς Ἱπποκράτη μετετίθεντο, καὶ συνώμνυντο μὴ διαλύσασθαι χωρὶς ἀλλήλων, ἀγοράν τε αὐτῷ καὶ στρατιὰν ἔπεμπον, ἐς δισμυρίους πεζοὺς καὶ ἱππέας πεντακισχιλίους.", "st": "6.4"}, {"sp": "N", "t": "ὅτι διαβεβλημένῳ τῷ Μαρκέλλῳ οὐκ ἐπίστευον χωρὶς ὅρκων. διὸ καὶ Ταυρομενίων προσχωρούντων οἱ, συνέθετο καὶ ὤμοσε μήτε φρουρήσειν τὴν πόλιν μήτε στρατολογήσειν ἀπ’ αὐτῆς.", "st": "6.5"}, {"sp": "N", "t": "ὅτι Κρήτη ἐξ ἀρχῆς εὐνοϊκῶς ἔχειν ἐδόκει Μιθριδάτῃ βασιλεύοντι Πόντου, καὶ αὐτῷ μισθοφορῆσαι πολεμοῦντι Ῥωμαίοις ἐλέγετο. ἔδοξε δὲ καὶ τοῖς πλεύσασι τότε λῃσταῖς ἐς χάριν τοῦ Μιθριδάτου συλλαβεῖν καὶ συμμαχῆσαι σαφῶς διωκομένοις ὑπὸ Μάρκου Ἀντωνίου. πρεσβευσαμένου δὲ τοῦ Ἀντωνίου πρὸς αὐτοὺς ὑπεριδεῖν καὶ ὑπερηφάνως ἀποκρίνασθαι. καὶ πολεμῆσαι μὲν αὐτοῖς εὐθὺς ἐπὶ τῷδε Ἀντώνιος, καὶ οὐ πρᾶξαι καλῶς, χρηματίσαι δ’ ὅμως διὰ τὴν πρᾶξιν Κρητικός. καὶ ἦν ὅδε πατὴρ Μάρκου Ἀντωνίου τοῦ πολεμήσαντος ὕστερον Καίσαρι τῷ κληθέντι Σεβαστῷ περὶ Ἄκτιον. ψηφισαμένων δὲ Ῥωμαίων Κρησὶ πολεμεῖν διὰ τάδε, οἱ Κρῆτες ἐπρέσβευσαν ἐς Ῥώμην περὶ διαλλαγῶν. οἱ δὲ αὐτοὺς ἐκέλευον ἐκδοῦναί τε αὐτοῖς Λασθένη τὸν πολεμήσαντα Ἀντωνίῳ, καὶ τὰ σκάφη τὰ λῃστικὰ πάντα παραδοῦναι, καὶ ὅσα Ῥωμαίων εἶχον αἰχμάλωτα, καὶ ὅμηρα τριακόσια καὶ ἀργυρίου τάλαντα τετρακισχίλια.", "st": "6.6"}, {"sp": "N", "t": "οὐ δεξαμένων δὲ ταῦτα Κρητῶν ᾑρέθη στρατηγὸς ἐπ’ αὐτοὺς Μέτελλος. καὶ νικᾷ μὲν ὁ Μέτελλος ἐν Κυδωνίᾳ Λασθένη, καὶ φυγόντος ἐς Κνωσσὸν Πανάρης Μετέλλῳ τὴν Κυδωνίαν παρέδωκεν ἐπὶ συνθήκῃ, μηδὲν παθεῖν αὐτός. Μετέλλου δὲ Κνωσσὸν περικαθημένου, ὁ Λασθένης τὴν οἰκίαν χρημάτων πλήσας κατέφλεξε, καὶ διέφυγεν ἀπὸ τῆς Κνωσσοῦ. καὶ οἱ Κρῆτες ἐς Πομπήιον Μάγνον, στρατηγοῦντα τοῦ λῃστικοῦ καὶ Μιθριδατείου πολέμου, πέμψαντες ἔφασαν ἑαυτοὺς ἐλθόντι ἐπιτρέψειν. ὁ δὲ ἀσχόλως τότε ἔχων ἐκέλευε τὸν Μέτελλον, ὡς οὐ δέον ἔτι πολεμεῖν τοῖς ἑαυτοὺς ἐπιτρέπουσιν, ἐξανίστασθαι τῆς νήσου· παραλήψεσθαι γὰρ αὐτὸς αὐτὴν ἐπελθών. ὁ δὲ οὐ φροντίσας ἐπέμεινε τῷ πολέμῳ, μέχρι ὑπηγάγετο αὐτήν, Λασθένει συνθέμενος ὅμοια Πανάρει. καὶ ἐθριάμβευσε, καὶ Κρητικὸς ἐκλήθη ὅδε δικαιότερον Ἀντωνίου, τὴν νῆσον ἐξεργασάμενος.", "st": "6.6"}, {"sp": "N", "t": "ὅτι Κλώδιος ὁ πατρίκιος, ὁ ποῦλχερ ἐπίκλην, τοῦτ’ ἔστιν εὐπρεπής, τῆς Γαΐου Καίσαρος γυναικὸς ἤρα. καὶ ἁρμόσασθαι αὑτὸν ἐς γυναῖκα ἐκ κεφαλῆς ἐς ἄκρους πόδας, ἔτι ὄντα ἀγένειον, καὶ ἐς τὴν οἰκίαν τοῦ Γαΐου παρελθεῖν οἷα γυναῖκα νυκτός, ὅτε μόναις γυναιξὶν ἐξῆν ἐσελθεῖν, μυστηρίων ἀγομένων. πλανηθέντα δὲ τῆς ὁδηγούσης, κατάφωρον ὑπ’ ἄλλων ἐκ τῆς φωνῆς γενόμενον ἐξελαθῆναι.", "st": "6.7"}, {"sp": "HDR", "t": "Ἰβηρική", "st": "7"}, {"sp": "N", "t": "Ορος ἐστὶ Πυρήνη διῆκον ἀπὸ τῆς Τυρρηνικῆς θαλάσσης ἐπὶ τὸν βόρειον ὠκεανόν, οἰκοῦσι δ’ αὐτοῦ πρὸς μὲν ἕω Κελτοί, ὅσοι Γαλάται τε καὶ Γάλλοι νῦν προσαγορεύονται, πρὸς δὲ δύσεων Ἴβηρές τε καὶ Κελτίβηρες, ἀρχόμενοι μὲν ἀπὸ τοῦ Τυρρηνικοῦ πελάγους, περιιόντες δ’ ἐν κύκλῳ διὰ τῶν Ἡρακλείων στηλῶν ἐπὶ τὸν βόρειον ὠκεανόν. οὕτως ἐστὶν ἡ Ἰβηρία περίκλυστος, ὅτι μὴ τῇ Πυρήνῃ μόνῃ, μεγίστῳ τῶν Εὐρωπαίων ὀρῶν καὶ ἰθυτάτῳ σχεδὸν ἁπάντων· τοῦ δὲ περίπλου τοῦδε τὸ μὲν Τυρρηνικὸν πέλαγος διαπλέουσιν ἐπὶ τὰς στήλας τὰς Ἡρακλείους, τὸν δ’ ἑσπέριον καὶ τὸν βόρειον ὠκεανὸν οὐ περῶσιν, ὅτι μὴ πορθμεύεσθαι μόνον ἐπὶ Βρεττανούς, καὶ τοῦτς ταῖς ἀμπώτεσι τοῦ πελάγους συμφερόμενοι· ἔστι δ’ αὐτοῖς ὁ διάπλους ἥμισυ ἡμέρας, καὶ τὰ λοιπὰ οὔτε Ῥωμαῖοι οὔτε τὰ ἔθνη τὰ ὑπὸ Ῥωμαίοις πειρῶνται τοῦδε τοῦ ὠκεανοῦ. μέγεθος δὲ τῆς Ἰβηρίας, τῆς Ἱσπανίας νῦν ὑπὸ τινῶν ἀντὶ Ἰβηρίας λεγομένης, ἐστὶ πολὺ καὶ ἄπιστον ὡς ἐν χώρᾳ μιᾷ, ὅπου τὸ πλάτος μυρίους σταδίους ἀριθμοῦσι, καὶ ἔστιν αὐτῇ τὸ πλάτος ἀντὶ μήκους. ἔθνη τε πολλὰ καὶ πολυώνυμα αὐτὴν οἰκεῖ, καὶ ποταμοὶ πολλοὶ ῥέουσι ναυσίποροι.", "st": "7.1"}, {"sp": "N", "t": "οἵ τινες δ’ αὐτὴν οἰκῆσαι πρῶτοι νομίζονται, καὶ οἳ μετ’ ἐκείνους κατέσχον, οὐ πάνυ μοι ταῦτα φροντίζειν ἀρέσκει, μόνα τὰ Ῥωμαίων συγγράφοντι, πλὴν ὅτι Κελτοί μοι δοκοῦσί ποτε, τὴν Πυρήνην ὑπερβάντες, αὐτοῖς συνοικῆσαι, ὅθεν ἄρα καὶ τὸ Κελτιβήρων ὄνομα ἐρρύη. δοκοῦσι δέ μοι καὶ Φοίνικες, ἐς Ἰβηρίαν ἐκ πολλοῦ θαμινὰ ἐπ’ ἐμπορίᾳ διαπλέοντες, οἰκῆσαί τινα τῆς Ἰβηρίας, Ἕλληνές τε ὁμοίως, ἐς Ταρτησσὸν καὶ Ἀργανθώνιον Ταρτησσοῦ βασιλέα πλέοντες, ἐμμεῖναι καὶ τῶνδέ τινες ἐν Ἰβηρίᾳ· ἡ γὰρ Ἀργανθωνίου βασιλεία ἐν Ἴβηρσιν ἦν. καὶ Ταρτησσός μοι δοκεῖ τότε εἶναι πόλις ἐπὶ θαλάσσης, ἣ νῦν Καρπησσὸς ὀνομάζεται. τό τε τοῦ Ἡρακλέους ἱερὸν τὸ ἐν στήλαις Φοίνικές μοι δοκοῦσιν ἱδρύσασθαι· καὶ θρησκεύεται νῦν ἔτι φοινικικῶς, ὅ τε θεὸς αὐτοῖς οὐχ ὁ Θηβαῖός ἐστιν ἀλλ’ ὁ Τυρίων. ταῦτα μὲν δὴ τοῖς παλαιολογοῦσι μεθείσθω.", "st": "7.2"}, {"sp": "N", "t": "τὴν δὲ γῆν τήνδε εὐδαίμονα οὖσαν καὶ μεγάλων ἀγαθῶν γέμουσαν Καρχηδόνιοι πρὸ Ῥωμαίων ἤρξαντο πολυπραγμονεῖν, καὶ μέρος αὐτῆς τὸ μὲν εἶχον ἤδη, τὸ δ’ ἐπόρθουν, μέχρι Ῥωμαῖοι σφᾶς ἐκβαλόντες, ἃ μὲν εἶχον οἱ Καρχηδόνιοι τῆς Ἰβηρίας, ἔσχον αὐτίκα, τὰ δὲ λοιπὰ σὺν χρόνῳ πολλῷ καὶ πόνῳ λαμβανόμενά τε ὑπὸ σφῶν καὶ πολλάκις ἀφιστάμενα χειρωσάμενοι διεῖλον ἐς τρία, καὶ στρατηγοὺς ἐς αὐτὰ πέμπουσι τρεῖς. ὅπως δ’ εἷλον ἕκαστα, καὶ ὅπως Καρχηδονίοις τε περὶ αὐτῶν καὶ μετὰ Καρχηδονίους Ἴβηρσι καὶ Κελτίβηρσιν ἐπολέμησαν, δηλώσει τόδε τὸ βιβλίον, μοῖραν μὲν ἐς Καρχηδονίους τὴν πρώτην ἔχον· ὅτι δὲ καὶ τοῦτο περὶ Ἰβηρίας ἦν, ἀνάγκη μοι συνενεγκεῖν ἐς τὴν Ἰβηρικὴν συγγραφὴν ἐγένετο, ᾧ λόγῳ καὶ τὰ περὶ Σικελίας Ῥωμαίοις καὶ Καρχηδονίοις ἐς ἀλλήλους γενόμενα, ἀρξάμενα Ῥωμαίοις τῆς ἐς Σικελίαν παρόδου τε καὶ ἀρχῆς ἐς τὴν Σικελικὴν συνενήνεκται γραφήν.", "st": "7.3"}, {"sp": "N", "t": "πρὸς γὰρ δὴ Καρχηδονίους Ῥωμαίοις πρῶτος ἐγένετο πόλεμος ἔκδημος περὶ Σικελίας ἐν αὐτῇ Σικελίᾳ, καὶ δεύτερος ὅδε περὶ Ἰβηρίας ἐν Ἰβηρίᾳ, ἐν ᾧ καὶ ἐς τὴν ἀλλήλων μεγάλοις στρατοῖς διαπλέοντες οἱ μὲν τὴν Ἰταλίαν, οἱ δὲ τὴν Λιβύην ἐπόρθουν. ἤρξαντο δὲ αὐτοῦ μεθ’ ἑκατὸν καὶ τεσσαράκοντα ὀλυμπιάδας μάλιστα, ὅτε τὰς σπονδὰς ἔλυσαν αἳ ἐπὶ τῷ Σικελικῷ πολέμῳ σφίσιν ἦσαν γενόμεναι. ἔλυσαν δ’ ἐκ τοιᾶσδε προφάσεως.", "st": "7.4"}, {"sp": "N", "t": "Ἀμίλχαρ ὁ Βάρκας ἐπίκλησιν, ὅτε περ ἐν Σικελίᾳ Καρχηδονίων ἐστρατήγει, Κελτοῖς τότε μισθοφοροῦσίν οἱ καὶ Λιβύων τοῖς συμμαχοῦσι πολλὰς δωρεὰς ὑπέσχητο δώσειν, ἅς, ἐπειδὴ ἐπανῆλθεν ἐς Λιβύην, ἀπαιτούντων ἐκείνων ὁ Λιβυκὸς Καρχηδονίοις ἐξῆπτο πόλεμος, ἐν ᾧ πολλὰ μὲν πρὸς αὐτῶν Λιβύων ἔπαθον οἱ Καρχηδόνιοι, Σαρδόνα δὲ Ῥωμαίοις ἔδοσαν ποινὴν ὧν ἐς τοὺς ἐμπόρους αὐτῶν ἡμαρτήκεσαν ἐν τῷδε τῷ Λιβυκῷ πολέμῳ. ὑπαγόντων οὖν ἐπὶ τοῖσδε τὸν Βάρκαν τῶν ἐχθρῶν ἐς κρίσιν ὡς αἴτιον τῇ πατρίδι τοσῶνδε συμφορῶν γενόμενον, θεραπεύσας ὁ Βάρκας τοὺς πολιτευομένους, ὧν ἦν δημοκοπικώτατος Ἀσδρούβας ὁ τὴν αὐτοῦ Βάρκα θυγατέρα ἔχων, τάς τε δίκας διεκρούετο, καὶ Νομάδων τινὸς κινήματος γενομένου στρατηγὸς ἔπραξεν ἐπ’ αὐτοὺς αἱρεθῆναι μετ’ Ἄννωνος τοῦ μεγάλου λεγομένου, ἔτι τὰς εὐθύνας τῆς προτέρας στρατηγίας ὀφείλων.", "st": "7.4"}, {"sp": "N", "t": "παυομένου δὲ τοῦ πολέμου, καὶ Ἄννωνος ἐπὶ διαβολαῖς ἐς Καρχηδόνα μεταπέμπτου γενομένου, μόνος ὢν ἐπὶ στρατῷ, καὶ τὸν κηδεστὴν Ἀσδρούβαν ἔχων οἱ συνόντα, διῆλθεν ἐπὶ Γάδειρα, καὶ τὸν πορθμὸν ἐς Ἰβηρίαν περάσας ἐλεηλάτει τὰ Ἰβήρων οὐδὲν ἀδικούντων, ἀφορμὴν αὑτῷ ποιούμενος ἀποδημίας τε καὶ ἔργων καὶ δημοκοπίας (ὅσα γὰρ λάβοι διῄρει, καὶ τὰ μὲν ἐς τὸν στρατὸν ἀνάλισκεν, ἵνα προθυμότερον αὐτῷ συναδικοῖεν, τὰ δ’ ἐς αὐτὴν ἔπεμπε Καρχηδόνα, τὰ δὲ τοῖς ὑπὲρ αὐτοῦ πολιτευομένοις διεδίδου), μέχρι Ἰβήρων αὐτὸν οἵ τε βασιλεῖς συστάντες οἱ κατὰ μέρος, καὶ ὅσοι ἄλλοι δυνατοί, κτείνουσιν ὧδε. ξύλων ἁμάξας ἄγοντες, αἷς βοῦς ὑπέζευξαν, εἵποντο ταῖς ἁμάξαις ὡπλισμένοι. τοῖς δὲ Λίβυσιν ἰδοῦσιν εὐθὺς μὲν ἐνέπιπτε γέλως, οὐ συνιεῖσι τοῦ στρατηγήματος· ὡς δ’ ἐν χερσὶν ἐγένοντο, οἱ μὲν Ἴβηρες αὐταῖς βουσὶν ἐξῆψαν τὰς ἁμάξας καὶ ἐξώτρυναν ἐς τοὺς πολεμίους, τὸ δὲ πῦρ σκιδναμένων τῶν βοῶν πάντῃ φερόμενον ἐτάρασσε τοὺς Λίβυας. καὶ τῆς τάξεως διαλυθείσης, οἱ Ἴβηρες αὐτοῖς ἐπιδραμόντες αὐτόν τε τὸν Βάρκαν καὶ πολὺ πλῆθος ἀμυνομένων ἐπ’ αὐτῷ διέφθειραν.", "st": "7.5"}, {"sp": "N", "t": "οἱ δὲ Καρχηδόνιοι τοῖς κέρδεσιν ἤδη τοῖς ἐξ Ἰβηρίας ἀρσσκόμενοι, στρατιὰν ἄλλην ἔπεμπον ἐς Ἰβηρίαν, καὶ στρατηγὸν ἁπάντων ἀπέφηναν Ἀσδρούβαν τὸν τοῦ Βάρκα κηδεστήν, ὄντα ἐν Ἰβηρίᾳ. ὁ δὲ Ἀννίβαν τὸν οὐ πολὺ ὕστερον ἀοίδιμον ἐπὶ στρατηγίαις, παῖδά τε ὄντα τοῦ Βάρκα καὶ τῆς γυναικός οἱ γιγνόμενον ἀδελφὸν ἔχων ἐν Ἰβηρίᾳ, νέον ὄντα καὶ φιλοπόλεμον καὶ ἀρέσκοντα τῷ στρατῷ ὑποστράτηγον ἀπέφηνεν. καὶ τῆς τε Ἰβηρίας τὰ πολλὰ πειθοῖ προσήγετο, πιθανὸς ὢν ὁμιλῆσαι, ἔς τε τὰ βίας δεόμενα τῷ μειρακίῳ χρώμενος προῆλθεν ἀπὸ τῆς ἑσπερίου θαλάσσης ἐς τὸ μεσόγειον ἐπὶ Ἴβηρα ποταμόν, ὃς μέσην που μάλιστα τέμνων τὴν Ἰβηρίαν, καὶ τῆς Πυρήνης ἀφεστὼς ὁδὸν ἡμερῶν πέντε, ἐξίησιν ἐς τὸν βόρειον ὠκεανόν.", "st": "7.6"}, {"sp": "N", "t": "Ζακανθαῖοι δέ, ἄποικοι Ζακυνθίων, ἐν μέσῳ τῆς τε Πυρήνης καὶ τοῦ ποταμοῦ τοῦ Ἴβηρού ὄντες, καὶ ὅσοι ἄλλοι Ἕλληνες περί τε τὸ καλούμενον Ἐμπόριον καὶ εἴ πῃ τῆς Ἰβηρίας ᾤκουν ἀλλαχοῦ, δείσαντες ὑπὲρ σφῶν ἐπρέσβευον ἐς Ῥώμην. καὶ ἡ σύγκλητος οὐκ ἐθέλουσα τὰ Καρχηδονίων ἐπαίρεσθαι, πρέσβεις ἐς Καρχηδόνα ἔπεμπεν. καὶ συνέβησαν ἀμφότεροι ὅρον εἶναι Καρχηδονίοις τῆς ἀρχῆς τῆς ἐν Ἰβηρίᾳ τὸν Ἴβηρα ποταμόν, καὶ μήτε Ῥωμαίους τοῖς πέραν τοῦδε τοῦ ποταμοῦ πόλεμον ἐκφέρειν, Καρχηδονίων ὑπηκόοις οὖσι, μήτε Καρχηδονίους ἐπὶ πολέμῳ τὸν Ἴβηρα διαβαίνειν, Ζακανθαίους δὲ καὶ τοὺς ἄλλους ἐν Ἰβηρίᾳ Ἕλληνας αὐτονόμους καὶ ἐλευθέρους εἶναι. καὶ τάδε ταῖς συνθήκαις ταῖς Ῥωμαίων καὶ Καρχηδονίων προσεγράφη.", "st": "7.7"}, {"sp": "N", "t": "Ἀσδρούβαν δὲ ἐπὶ τοῖσδε Ἰβηρίαν τὴν ὑπὸ Καρχηδονίοις καθιστάμενον ἀνὴρ δοῦλος, οὗ τὸν δεσπότην ὠμῶς διεφθάρκει, λαθὼν ἐν κυνηγεσίοις ἀναιρεῖ. καὶ τόνδε μὲν Ἀννίβας ἐλεγχθέντα δεινῶς αἰκισάμενος διέφθειρεν· ἡ στρατιὰ δὲ τὸν Ἀννίβαν, καίπερ ὄντα κομιδῇ νέον, ἀρέσκοντα δὲ ἰσχυρῶς, στρατηγὸν ἀπέδειξαν αὑτῶν· καὶ ἡ Καρχηδονίων βουλὴ συνέθετο. ὅσοι δὲ τοῦ Βάρκα διαπολῖται τὴν Βάρκα τε καὶ Ἀσδρούβα δύναμιν ἐδεδοίκεσαν, ὡς ἔμαθον αὐτοὺς τεθνεῶτας, Ἀννίβα κατεφρόνουν ὡς νέου, καὶ τοὺς ἐκείνων φίλους τε καὶ στασιώτας ἐδίωκον ἐπὶ τοῖς ἐκείνων ἐγκλήμασιν. ὅ τε δῆμος ἅμα τοῖς κατηγοροῦσιν ἐγίγνετο, μνησικακῶν τοῖς διωκομένοις τῆς βαρύτητος τῆς ἐπὶ Βάρκα τε καὶ Ἀσδρούβα· καὶ τὰς δωρεὰς ἐκέλευον αὐτούς, ὅσας μεγάλας Ἀσδρούβας τε καὶ Βάρκας αὐτοῖς ἐπεπόμφεσαν, ἐς τὸ κοινὸν ἐσενεγκεῖν ὡς ἐκ τῶν πολεμίων πεπορισμένας. οἱ δὲ ἐπέστελλον τῷ Ἀννίβᾳ, σφίσι τε ἐπικουρεῖν δεόμενοι, καὶ διδάσκοντες ὅτι καὶ αὐτὸς ἔσοιτο τοῖς πατρῴοις ἐχθροῖς εὐκαταφρόνητος, εἰ τοὺς ἐν τῇ πατρίδι συνεργεῖν αὐτῷ δυναμένους ὑπερίδοι.", "st": "7.8"}, {"sp": "N", "t": "ὁ δὲ καὶ ταῦτα προεώρα, καὶ τὰς ἐκείνων δίκας ἀρχὴν ἐφ’ ἑαυτὸν οὖσαν ἐπιβουλῆς· οὐδ’ ἠξίου τὴν ἔχθραν, ὥσπερ ὁ πατὴρ καὶ ὁ κηδεστής, ἐσαεὶ καὶ μετὰ φόβου διαφέρειν, οὐδ’ ἐπὶ τῷ Καρχηδονίων κουφόνῳ μέχρι παντὸς εἶναι, ῥᾳδίως ἐς εὐεργέτας πρὸς ἀχαριστίαν τρεπομένων. ἐλέγετο δὲ καὶ παῖς ὢν ἔτι ὑπὸ τοῦ πατρὸς ὁρκωθῆναι ἐπὶ ἐμπύρων ἄσπειστος ἐχθρὸς ἔσεσθαι Ῥωμαίοις, ὅτε ἐς πολιτείαν παρέλθοι. διὰ δὴ ταῦτ’ ἐπενόει μεγάλοις καὶ χρονίοις πράγμασι τὴν πατρίδα περιβαλών, καὶ καταστήσας ἐς ἀσχολίας καὶ φόβους, τὸ ἑαυτοῦ καὶ τὰ τῶν φίλων ἐν ἀδεεῖ θέσθαι. Λιβύην μὲν οὖν εὐσταθοῦσαν ἑώρα, καὶ Ἰβήρων ὅσα ὑπήκοα ἦν· εἰ δὲ πρὸς Ῥωμαίους πόλεμον αὖθις ἀναρριπίσειεν, οὗ μάλιστα ἐπεθύμει, ἐδόκει Καρχηδονίους μὲν ἐν φροντίσι καὶ φόβοις ἔσεσθαι μακροῖς, αὐτὸς δέ, εἴτε κατορθώσειεν, ἐπὶ κλέους ἀθανάτου γενήσεσθαι, τὴν πατρίδα τῆς οἰκουμένης γῆς ἄρχουσαν ἀποφήνας (οὐ γὰρ εἶναί τινας ἀντιμάχους αὐτοῖς ἐπὶ Ῥωμαίοις), εἴτε καὶ πταίσειε, μεγάλην καὶ ὣς τὸ ἐγχείρημα αὐτῷ δόξαν οἴσειν.", "st": "7.9"}, {"sp": "N", "t": "ἀρχὴν δὲ ὑπολαμβάνων ἔσεσθαι λαμπρὰν εἰ τὸν Ἴβηρα διαβαίη, Τορβολήτας, οἳ γείτονές εἰσι Ζακανθαίων, ἀνέπεισε τῶν Ζακανθαίων παρὰ οἷ καταβοᾶν ὡς τήν τε χώραν αὐτῶν ἐπιτρεχόντων καὶ πολλὰ σφᾶς ἄλλα ἀδικούντων. οἱ δὲ ἐπείθοντο. καὶ πρέσβεις αὐτῶν ὁ Ἀννίβας ἐς Καρχηδόνα ἔπεμπεν, αὐτός τε ἐν ἀπορρήτοις ἔγραφε Ῥωμαίους τὴν ὑπὸ Καρχηδονίοις Ἰβηρίαν ἀναπείθειν ἀπὸ Καρχηδονίων ἀφίστασθαι, καὶ Ζακανθαίους Ῥωμαίοις ταῦτα συμπράσσειν. ὅλως τε τῆς ἀπάτης οὐ μεθίει, πολλὰ τοιαῦτα ἐπιστέλλων, ἕως ἡ βουλὴ προσέταξεν αὐτῷ πράσσειν ἐς Ζακανθαίους ὅ τι δοκιμάσειεν. ὁ δὲ ἐπεὶ τῆς ἀφορμῆς ἐλάβετο, Τορβολήτας αὖθις ἔπραξεν ἐντυχεῖν οἱ κατὰ τῶν Ζακανθαίων, καὶ μετεπέμπετο πρέσβεις. οἱ δὲ ἀφίκοντο μέν, κελεύοντος δὲ τοῦ Ἀννίβου λέγειν ἑκατέρους ἐφ’ ἑαυτοῦ περὶ ὧν διαφέρονται, Ῥωμαίοις ἔφασαν ἐπιτρέψειν τὴν δίκην. ὁ μὲν δὴ ταῦτ’ εἰπόντας ἀπέπεμπεν ἀπὸ τοῦ στρατοπέδου, καὶ τῆς ἐπιούσης νυκτὸς παντὶ τῷ στρατῷ τὸν Ἴβηρα διαβὰς τὴν χώραν ἐπόρθει καὶ τῇ πόλει μηχανήματα ἐφίστη. ἑλεῖν δ’ οὐ δυνάμενος ἀπετάφρευε καὶ φρούρια πολλὰ περιθεὶς ἐκ διαστημάτων ἐπεφοίτα.", "st": "7.10"}, {"sp": "N", "t": "Ζακανθαῖοι δὲ αἰφνιδίῳ καὶ ἀκαταγγέλτῳ κακῷ συμπεσόντες ἐπρέσβευον ἐς Ῥώμην. καὶ ἡ σύγκλητος αὐτοῖς συνέπεμπε πρέσβεις, οἳ πρῶτον μὲν Ἀννίβαν ἔμελλον ὑπομνήσειν τῶν συγκει μένων, οὐ πειθομένου δὲ ἐς Καρχηδόνα πλευσεῖσθαι κατ’ αὐτοῦ· τούτοις τοῖς πρέσβεσι πλεύσασιν ἐς Ἰβηρίαν, καὶ ἐς τὸ στρατόπεδον ἀπὸ θαλάσσης ἀναβαίνουσιν, ὁ Ἀννίβας ἀπηγόρευσε μὴ προσιέναι. καὶ οἱ μὲν ἀπέπλευσαν ἐπὶ Καρχηδόνος σὺν τοῖς πρέσβεσι τοῖς Ζακανθαίων, καὶ τῶν συνθηκῶν ἀνεμίμνησκον αὐτούς. Καρχηδόνιοι δὲ ᾐτιῶντο τοὺς Ζακανθαίους πολλὰ τοὺς ὑπηκόους σφῶν ἀδικεῖν. καὶ Ζακανθαίων οἱ πρέσβεις ἐς δίκην αὐτοὺς προυκαλοῦντο ἐπὶ Ῥωμαίων κριτῶν· οἱ δ’ οὐκ ἔφασαν χρῄζειν δίκης, ἀμύνεσθαι δυνάμενοι. ὧν ἐς Ῥώμην ἀπαγγελθέντων, οἱ μὲν ἐκέλευον ἤδη συμμαχεῖν τοῖς Ζακανθαίοις, οἱ δ’ ἐπεῖχον ἔτι, λέγοντες οὐ συμμάχους αὐτοὺς ἐν ταῖς συνθήκαις σφῶν ἀλλ’ αὐτονόμους καὶ ἐλευθέρους ἀναγεγράφθαι, ἐλευθέρους δ’ ἔτι καὶ τοὺς πολιορκουμένους εἶναι. καὶ ἐκράτησεν ἡ γνώμη.", "st": "7.11"}, {"sp": "N", "t": "Ζακανθαῖοι δέ, ἐπειδὴ τὰ Ῥωμαίων ἀπέγνωσαν καὶ ὁ λιμὸς σφᾶς ἐπίεζε καὶ Ἀννίβας περιεκάθητο συνεχῶς (εὐδαίμονα γὰρ καὶ πολύχρυσον ἀκούων εἶναι τὴν πόλιν οὐκ ἀνίει τῆς πολιορκίας), τὸν μὲν χρυσὸν καὶ ἄργυρον, ὅσος ἦν δημόσιός τε καὶ ἰδιωτικός, ἀπὸ κηρύγματος ἐς τὴν ἀγορὰν συνήνεγκαν, καὶ μολύβδῳ καὶ χαλκῷ συνεχώνευσαν ὡς ἀχρεῖον Ἀννίβᾳ γενέσθαι, αὐτοὶ δὲ ἐν χερσὶν ἑλόμενοί τι παθεῖν μᾶλλον ἢ ὑπὸ τοῦ λιμοῦ, ἐξέδραμον ἔτι νυκτὸς ἐπὶ τὰ φρούρια τὰ τῶν Λιβύων, ἀναπαυομένων ἔτι καὶ οὐδέν τοιοῦτον ὑπονοούντων· ὅθεν αὐτοὺς ἀνισταμένους τε ἐξ εὐνῆς καὶ σὺν θορύβῳ μόλις ὁπλιζομένους, ἔστι δ’ οὓς ἤδη καὶ μαχομένους, διέφθειρον. μακροῦ δὲ τοῦ ἀγῶνος γενομένου, Λιβύων μὲν ἀπώλοντο πολλοί, Ζακανθαῖοι δὲ παντες. αἱ δὲ γυναῖκες ἀπὸ τοῦ τείχους ὁρῶσαι τὸ τέλος τῶν ἀνδρῶν, αἱ μὲν ἐρρίπτουν ἑαυτὰς κατὰ τῶν τεγῶν, αἱ δ’ ἀνήρτων, αἱ δὲ καὶ τὰ τέκνα προκατέσφαζον. καὶ τοῦτο τέλος ἦν Ζακανθαίοις, πόλει μεγάλῃ τε καὶ δυνατῇ γενομένῃ. Ἀννίβας δὲ ὡς ἔμαθε περὶ τοῦ χρυσοῦ, τοὺς μὲν ὑπολοίπους καὶ ἔτι ἡβῶντας αὐτῶν αἰκιζόμενος διέφθειρεν ὑπ’ ὀργῆς, τὴν δὲ πόλιν ὁρῶν ἐπιθάλασσόν τε καὶ Καρχηδόνος οὐ μακράν, καὶ χώρας ἄρχουσαν ἀγαθῆς, ᾤκιζεν αὖθις καὶ Καρχηδονίων ἄποικον ἀπέφαινεν· ἣν νῦν οἶμαι Καρχηδόνα καλεῖσθαι τὴν Σπαρταγενῆ.", "st": "7.12"}, {"sp": "N", "t": "Ῥωμαῖοι δὲ πρέσβεις ἐς Καρχηδόνα ἔπεμπον, οἷς εἴρητο ἐξαιτεῖν παρὰ Καρχηδονίων Ἀννίβαν ὡς ἐς τὰς συνθήκας ἁμαρτόντα, εἰ μὴ κοινὸν ἡγοῦνται τὸ ἔργον· ἢν δὲ μὴ διδῶσιν, εὐθέως αὐτοῖς πόλεμον προαγορεύειν. καὶ οἱ μὲν ἔπραξαν ὧδε, καὶ τὸν πόλεμον αὐτοῖς οὐκ ἐκδιδοῦσι τὸν Ἀννίβαν ἐπήγγειλαν· λέγεται δ’ οὕτω γενέσθαι. ὁ μὲν πρεσβευτὴς αὐτοῖς γελώμενος ἔφη, τὸν κόλπον ἐπιδεικνύς, “ἐνταῦθ’ ὑμῖν, ὦ Καρχηδόνιοι, καὶ τὴν εἰρήνην καὶ τὸν πόλεμον φέρω· ὑμεῖς δ’ ὁπότερα αἱρεῖσθε λάβετε.” οἱ δ’ ἔφασαν, “σὺ μὲν οὖν ἃ βούλει δίδου.” προτείναντος δὲ τὸν πόλεμον, ἐξεβόησαν ὁμοῦ πάντες, “δεχόμεθα.” καὶ εὐθὺς ἐπέστελλον τῷ Ἀννίβᾳ πᾶσαν ἤδη τὴν Ἰβηρίαν ἀδεῶς ἐπιτρέχειν ὡς τῶν σπονδῶν λελυμένων. ὁ μὲν δὴ τὰ ἔθνη τὰ ἀγχοῦ πάντα ἐπιὼν ὑπήγετο, ἢ πείθων ἢ δεδιττόμενος ἢ καταστρεφόμενος, καὶ στρατιὰν πολλὴν συνέλεγε, τὴν μὲν χρείαν οὐχ ὑποδεικνύς, ἐς δὲ τὴν Ἰταλίαν ἐπινοῶν ἐμβαλεῖν. Γαλάταις τε διεπρεσβεύετο, καὶ τὰς διόδους τῶν Ἀλπείων ὀρῶν κατεσκέπτετο. καὶ διῆλθεν, Ἀσδρούβαν τὸν ἀδελφὸν ἐν Ἰβηρίᾳ …", "st": "7.13"}, {"sp": "N", "t": "… ἐν Ἰβηρίᾳ σφίσι καὶ Λιβύῃ τὸν πόλεμον ἔσεσθαι (οὐ γὰρ δὴ μὴ Λίβυές ποτε ἐς τὴν Ἰταλίαν ἐσβάλωσιν, οὐδ’ ὑπενόουν), Τιβέριον μὲν Σεμπρώνιον Λόγγον ἐπὶ νεῶν ἑκατὸν ἑξήκοντα σὺν δύο στρατοῦ τέλεσιν ἐς Λιβύην ἐξέπεμπον (καὶ ὅσα Λόγγος τε καὶ οἱ λοιποὶ Ῥωμαίων στρατηγοὶ περὶ Λιβύην ἔπραξαν, ἐν τῇ Καρχηδονιακῇ βίβλῳ συγγέγραπται), Πόπλιον δὲ Κορνήλιον Σκιπίωνα ἔστελλον ἐς Ἰβηρίαν ἐπὶ νεῶν ἑξήκοντα μετὰ πεζῶν μυρίων καὶ ἱππέων ἑπτακοσίων, καὶ πρεσβευτὴν αὐτῷ συνέπεμπον Γναῖον Κορνήλιον Σκιπίωνα τὸν ἀδελφόν. τούτοιν ὁ μὲν Πόπλιος παρὰ Μασσαλιωτῶν ἐμπόρων πυθόμενος Ἀννίβαν διὰ τῶν Ἀλπείων ὀρῶν ἐς τὴν Ἰταλίαν ὑπερβάντα, δείσας μὴ ἀδοκήτως τοῖς Ἰταλιώταις ἐπιπέσοι, παραδοὺς Γναίῳ τῷ ἀδελφῷ τὴν ἐν Ἰβηρίᾳ στρατιὰν διέπλευσεν ἐπὶ πεντήρους ἐς Τυρρηνίαν. καὶ ὅσα ἔπραξεν ἐν τῇ Ἰταλίᾳ οὗτός τε καὶ ὅσοι μετ’ αὐτὸν ἄλλοι στρατηγοὶ τοῦδε τοῦ πολέμου ἐγένοντο, ἕως Ἀννίβαν ἑκκαιδεκάτῳ μόλις ἔτει τῆς Ἰταλίας ἐξήλασαν, ἡ ἑξῆς βίβλος ὑποδείκνυσιν, ἣ τὰ ἔργα Ἀννίβου τὰ ἐν Ἰταλίᾳ πάντα περιλαμβάνει, καὶ παρ’ αὐτὸ λέγεται Ῥωμαϊκῶν Ἀννιβαϊκή.", "st": "7.14"}, {"sp": "N", "t": "Γναῖος δὲ οὐδέν, ὅ τι καὶ εἰπεῖν, ἔπραξεν ἐν τοῖς Ἴβηρσι, πρὶν αὐτῷ Πόπλιον τὸν ἀδελφὸν ἐπανελθεῖν· Ῥωμαῖοι γάρ, ληγούσης τῆς ἀρχῆς τῷ Ποπλίῳ, πρὸς μὲν Ἀννίβαν ἐς τὴν Ἰταλίαν τοὺς μετὰ τὸν Πόπλιον ὑπάτους ἐξέπεμψαν, αὐτὸν δὲ ἀνθύπατον ἀποφήναντες ἐς Ἰβηρίαν αὖθις ἔστειλαν. καὶ ἀπὸ τοῦδε οἱ δύο Σκιπίωνες τὸν ἐν Ἰβηρίᾳ πόλεμον διέφερον, Ἀσδρούβου σφίσιν ἀντιστρατηγοῦντος, μέχρι Καρχηδόνιοι μὲν ὑπὸ Σύφακος τοῦ τῶν Νομάδων δυνάστου πολεμούμενοι τὸν Ἀσδρούβαν καὶ μέρος τῆς ὑπ· αὐτῷ στρατιᾶς μετεπέμψαντο, τῶν δὲ ὑπολοίπων οἱ Σκιπίωνες εὐμαρῶς ἐκράτουν. καὶ πολλαὶ τῶν πόλεων ἐς αὐτοὺς ἑκοῦσαι μετετίθεντο· καὶ γὰρ ἤστην πιθανωτάτω στρατηγῆσαί τε καὶ προσαγαγέσθαι.", "st": "7.15"}, {"sp": "N", "t": "θέμενοι δ’ οἱ Καρχηδόνιοι πρὸς Σύφακα εἰρήνην, αὖθις ἐξέπεμπον ἐς Ἰβηρίαν Ἀσδρούβαν μετὰ πλέονος στρατοῦ καὶ ἐλεφάντων τριάκοντα, καὶ σὺν αὐτῷ ἄλλους δύο στρατηγούς, Μάγωνά τε καὶ Ἀσδρούβαν ἕτερον, ὃς Γέσκωνος ἦν υἱός. καὶ χαλεπώτερος ἦν τοῖς Σκιπίωσιν ὁ πόλεμος ἀπὸ τοῦδε, ἐκράτουν δὲ καὶ ὥς. καὶ πολλοὶ μὲν τῶν Λιβύων, πολλοὶ δὲ τῶν ἐλεφάντων ἐφθάρησαν, μέχρι χειμῶνος ἐπιλαβόντος οἱ μὲν Λίβυες ἐχείμαζον ἐν Τυρδιτανίᾳ, τῶν δὲ Σκιπιώνων ὁ μὲν Γναῖος ἐν Ὄρσωνι, ὁ δὲ Πόπλιος ἐν Καστολῶνι. ἔνθα αὐτῷ προσιὼν ὁ Ἀσδρούβας ἀπηγγέλθη· καὶ προελθὼν τῆς πόλεως μετ’ ὀλίγων ἐς κατασκοπὴν στρατοπέδου, ἔλαθε πλησιάσας τῷ Ἀσδρούβᾳ, καὶ αὐτὸν ἐκεῖνος καὶ τοὺς σὺν αὐτῷ πάντας ἱππεῦσι περιδραμὼν ἀπέκτεινεν. ὁ δὲ Γναῖος οὐδέν τι προμαθὼν ἐς τὸν ἀδελφὸν ἐπὶ σῖτον ἔπεμπε στρατιώτας, οἷς ἕτεροι Λιβύων συντυχόντες ἐμάχοντο. καὶ πυθόμενος ὁ Γναῖος ἐξέδραμεν ὡς εἶχε μετὰ τῶν εὐζώνων ἐπ’ αὐτούς. οἱ δὲ τούς τε προτέρους ἀνῃρήκεσαν ἤδη, καὶ τὸν Γναῖον ἐδίωκον, ἕως ἐσέδραμεν ἔς τινα πύργον. καὶ τὸν πύργον ἐνέπρησαν οἱ Λίβυες, καὶ ὁ Σκιπίων κατεκαύθη μετὰ τῶν συνόντων.", "st": "7.16"}, {"sp": "N", "t": "οὕτω μὲν οἱ Σκιπίωνες ἀπέθανον ἄμφω, ἄνδρες ἐς πάντα ἀγαθοὶ γενόμενοι· καὶ αὐτοὺς ἐπεπόθησαν Ἴβηρες, ὅσοι δι’ αὐτοὺς ἐς Ῥωμαίους μετέθεντο. πυθόμενοι δ’ οἱ ἐν ἄστει βαρέως τε ἤνεγκαν, καὶ Μάρκελλον ἐκ Σικελίας ἄρτι ἀφιγμένον, καὶ σὺν αὐτῷ Κλαύδιον, ἐπὶ νεῶν … ἐξέπεμπον ἐς Ἰβηρίαν μετὰ χιλίων ἱππέων καὶ πεζῶν μυρίων καὶ χορηγίας ἱκανῆς. οὐδενὸς δὲ λαμπροῦ παρὰ τῶνδε γιγνομένου, τὰ Λιβύων ὑπερηύξετο, καὶ πᾶσαν σχεδὸν Ἰβηρίαν εἶχον, ἐς βραχὺ Ῥωμαίων ἐν τοῖς ὄρεσι τοῖς Πυρηναίοις κατακεκλεις μένων. πάλιν οὖν οἱ ἐν ἄστει πυνθανόμενοι μᾶλλον ἐταράσσοντο· καὶ φόβος ἦν μὴ Ἀννίβου πορθοῦντος τὰ πρόσω τῆς Ἰταλίας, καὶ οἵδε οἱ Λίβυες ἐς τὰ ἕτερα αὐτῆς ἐσβάλοιεν. ὅθεν οὐδὲ ἀποσχέσθαι τῆς Ἰβηρίας βουλομένοις αὐτοῖς δυνατὸν ἦν, δέει τοῦ μὴ καὶ τόνδε τὸν πόλεμον ἐς τὴν Ἰταλίαν ἐπαγαγέσθαι.", "st": "7.17"}, {"sp": "N", "t": "προύγραφον οὖν ἡμέραν ἐν ᾗ χειροτονήσουσι στρατηγὸν ἐς Ἰβηρίαν. καὶ οὐδενὸς παραγγέλλοντος ἔτι πλείων ἐγίγνετο φόβος, καὶ σιωπὴ σκυθρωπὸς ἐπεῖχε τὴν ἐκκλησίαν, ἐς οὗ Κορνήλιος Σκιπίων ὁ Ποπλίου Κορνηλίου τοῦ ἀναιρεθέντος ἐν Ἴβηρσιν υἱός, νέος μὲν ὢν κομιδῇ (τεσσάρων γὰρ καὶ εἴκοσιν ἐτῶν ἦν), σώφρων δὲ καὶ γενναῖος εἶναι νομιζόμενος, ἐς τὸ μέσον ἐλθὼν ἐσεμνολόγησεν ἀμφί τε τοῦ πατρὸς καὶ ἀμφὶ τοῦ θείου, καὶ τὸ πάθος αὐτῶν ὀδυράμενος ἐπεῖπεν οἰκεῖος εἶναι τιμωρὸς ἐκ πάντων πατρὶ καὶ θείῳ καὶ πατρίδι. ἄλλα τε πολλὰ ἀθρόως καὶ λάβρως, ὥσπερ ἔνθους, ἐπαγγειλάμενος, οὐκ Ἰβηρίαν λήψεσθαι μόνην ἀλλ’ ἐπ’ αὐτῇ καὶ Λιβύην καὶ Καρχηδόνα, τοῖς μὲν ἔδοξε κουφολογῆσαι νεανικῶς, τὸν δὲ δῆμον ἀνέλαβε κατεπτηχότα (χαίρουσι γὰρ ἐπαγγελίαις οἱ δεδιότες) καὶ ᾑρέθη στρατηγὸς ἐς Ἰβηρίαν ὡς πράξων τι τῆς εὐτολμίας ἄξιον. οἱ πρεσβύτεροι δὲ αὐτὴν οὐκ εὐτολμίαν ἀλλὰ προπέτειαν ἐκάλουν. καὶ ὁ Σκιπίων αἰσθόμενος ἐς ἐκκλησίαν αὖθις αὐτοὺς συνεκάλει τε καὶ ἐσεμνύνετο ὅμοια· καὶ τὴν ἡλικίαν εἰπὼν οὐδὲν ἐμποδών οἱ γενήσεσθαι, προυκαλεῖτο ὅμως, εἴ τις ἐθέλοι τῶν πρεσβυτέρων τὴν ἀρχὴν παραλαβεῖν ἑκόντος αὐτοῦ παραδιδόντος. οὐδενὸς δ’ ἑλομένου, μᾶλλον ἐπαινούμενός τε καὶ θαυμαζόμενος ἐξῄει μετὰ μυρίων πεζῶν καὶ ἱππέων πεντακοσίων· οὐ γὰρ ἐνεχώρει πλέονα στρατὸν ἐξάγειν, Ἀννίβου δῃοῦντος τὴν Ἰταλίαν. ἔλαβε δὲ καὶ χρήματα καὶ παρασκευὴν ἄλλην καὶ ναῦς μακρὰς ὀκτὼ καὶ εἴκοσι, μεθ’ ὧν ἐς Ἰβηρίαν διέπλευσεν.", "st": "7.18"}, {"sp": "N", "t": "παραλαβών τε τὴν ἐκεῖ στρατιάν, καὶ οὓς ἦγεν ἐς ἓν συναγαγών, ἐκάθηρε, καὶ διελέχθη καὶ τοῖσδε μεγαληγόρως. δόξα τε διέδραμεν ἐς ὅλην αὐτίκα τὴν Ἰβηρίαν, βαρυνομένην τε τοὺς Λίβυας καὶ τῶν Σκιπιώνων τὴν ἀρετὴν ἐπιποθοῦσαν, ὅτι στρατηγὸς αὐτοῖς ἥκοι Σκιπίων ὁ Σκιπίωνος κατὰ θεόν. οὗ δὴ καὶ αὐτὸς αἰσθανόμενος, ὑπεκρίνετο πάντα ποιεῖν πειθόμενος θεῷ. πυνθανόμενος δ’ ὅτι οἱ ἐχθροὶ σταθμεύουσι μὲν ἐν τέσσαρσι στρατοπέδοις, μακρὰν διεστηκότες ἀπ’ ἀλλήλων, ἀνὰ δισμυρίους καὶ πεντακισχιλίους πεζοὺς καὶ ἱππέας πεντακοσίους ἐπὶ δισχιλίοις, τὴν δὲ παρασκευὴν τῶν τε χρημάτων καὶ σίτου καὶ ὅπλων καὶ βελῶν καὶ νεῶν καὶ αἰχμαλώτων καὶ ὁμήρων τῶν ἐξ ὅλης Ἰβηρίας ἔχουσιν ἐν τῇ πρότερον μὲν Ζακάνθῃ τότε δὲ ἤδη Καρχηδόνι, καὶ φρουρὸς αὐτῶν ἐστὶ Μάγων μετὰ μυρίων Καρχηδονίων, ἔκρινε πρῶτον ἐς τούτους ἐπιδραμεῖν διά τε τὴν ὀλιγότητα τοῦ στρατοῦ τοῦ μετὰ Μάγωνος καὶ τὸ μέγεθος τῆς παρασκευῆς, καὶ ὡς ὁρμητήριον ἀσφαλὲς ἐκ γῆς καὶ θαλάσσης ἕξων ἐπὶ ὅλην τὴν Ἰβηρίαν πόλιν ἀργυρεῖα καὶ χώραν εὐδαίμονα καὶ πλοῦτον πολὺν ἔχουσαν καὶ τὸν διάπλουν ἐς Λιβύην βραχύτατον.", "st": "7.19"}, {"sp": "N", "t": "ὁ μὲν δὴ τοσοῖσδε λογισμοῖς ἐπαιρόμενος, οὐδενὶ προειπὼν ὅπῃ χωρήσειν ἔμελλεν, ἡλίου δύναντος ἦγε τὴν στρατιὰν δι’ ὅλης τῆς νυκτὸς ἐπὶ τὴν Καρχηδόνα. καὶ αὐτὴν ἅμα ἕῳ, τῶν Λιβύων καταπλαγέντων, περιταφρεύσας, ἐς τὴν ἐπιοῦσαν ἡμέραν ἡτοιμάζετο, κλίμακάς τε καὶ μηχανὰς πάντῃ περιτιθείς, χωρὶς ἑνὸς μέρους, ᾗ τὸ μὲν τεῖχος ἦν βραχύτατον, ἕλος δ’ αὐτῷ καὶ θάλασσα προσέκλυζε, καὶ δι’ αὐτὸ καὶ οἱ φύλακες ἀμελῶς εἶχον. νυκτὸς δὲ πάντα πληρώσας βελῶν καὶ λίθων, καὶ τοῖς λιμέσι τῆς πόλεως ναῦς ἐπιστήσας, ἵνα μὴ αἱ νῆες αὐτὸν αἱ τῶν πολεμίων διαφύγοιεν (ὑπὸ γὰρ δὴ μεγαλοψυχίας ἤλπιζε πάντως αἱρήσειν τὴν πόλιν), πρὸ ἕω τὴν στρατιὰν ἀνεβίβαζεν ἐπὶ τὰς μηχανάς, τοὺς μὲν ἄνωθεν ἐγχειρεῖν κελεύων τοῖς πολεμίοις, τοὺς δὲ κάτω τὰς μηχανὰς ὠθεῖν ἐς τὸ πρόσω. Μάγων δὲ τοὺς μὲν μυρίους ἐπέστησε ταῖς πύλαις ὡς ἐκπηδήσοντας, ὅτε καιρὸς εἴη, μετὰ μόνων ξιφῶν (οὐ γὰρ εἶναι δόρασιν ἐν στενῷ χρῆσθαι), τοὺς δὲ ἄλλους ἐς τὰς ἐπάλξεις ἀνῆγεν. καὶ πολλὰ καὶ ὅδε μηχανήματα καὶ λίθους καὶ βέλη καὶ καταπέλτας ἐπιστήσας εἴχετο τοῦ ἔργου προθύμως. γενομένης δὲ βοῆς καὶ παρακελεύσεως ἑκατέρωθεν, οὐδέτεροι μὲν ὁρμῆς καὶ προθυμίας ἐνέλειπον, καὶ λίθους τε καὶ βέλη καὶ ἀκόντια ἀφιέντες, οἱ μὲν ἀπὸ χειρῶν, οἱ δὲ ἀπὸ μηχανῶν, οἱ δὲ ἀπὸ σφενδόνης, εἴ τέ τις ἦν ἄλλη παρασκευὴ καὶ δύναμις, ἐχρῶντο προθύμως ἅπασιν.", "st": "7.20"}, {"sp": "N", "t": "ἐκακοπάθει δὲ τὰ τοῦ Σκιπίωνος, καὶ οἱ μύριοι Καρχηδονίων, οἳ περὶ τὰς πύλας ἦσαν, ἐκδραμόντες σὺν τοῖς ξίφεσι γυμνοῖς ἐνέπιπτον ἐς τοὺς τὰ μηχανήματα ὠθοῦντας, καὶ πολλὰ μὲν ἔδρων, οὐχ ἥσσω δ’ ἀντέπασχον, μέχρι τῷ φιλοπόνῳ καὶ ταλαιπώρῳ τὰ Ῥωμαίων ὑπανίστατο. καὶ μεταβολῆς γενομένης οἵ τε ἐπὶ τῶν τειχῶν ἔκαμνον ἤδη, καὶ αἱ κλίμακες αὐτοῖς προσεπέλαζον. οἱ δὲ ξιφήρεις τῶν Καρχηδονίων ἐς τὰς πύλας ἐσέτρεχον, καὶ ἀποκλείσαντες αὐτὰς ἀνεπήδων ἐπὶ τὰ τείχη. καὶ τοῖς Ῥωμαίοις αὖθις ἦν ὁ πόνος πολύς τε καὶ χαλεπός, ἐς οὗ Σκιπίων ὁ στρατηγὸς πάντῃ περιθέων τε καὶ βοῶν καὶ παρακαλῶν εἶδε περὶ μεσημβρίαν, ᾗ τὸ βραχὺ τεῖχος ἦν καὶ τὸ ἕλος προσέκλυζε, τὴν θάλασσαν ὑποχωροῦσαν· ἄμπωτις γὰρ ἐφήμερος ἔστιν. καὶ ὁ κλύδων ἐπῄει μὲν ἐς μαστούς, ὑπεχώρει δὲ ἐς μέσας κνήμας. ὅπερ ὁ Σκιπίων τότε ἰδών, καὶ περὶ τῆς φύσεως αὐτοῦ πυθόμενος, ὡς ἔχοι τὸ λοιπὸν τῆς ἡμέρας, πρὶν ἐπανελθεῖν τὸ πέλαγος, ἔθει πάντῃ βοῶν, “νῦν ὁ καιρός, ὦ ἄνδρες, νῦν ὁ σύμμαχός μοι θεὸς ἀφῖκται. πρόσιτε τῷ μέρει τῷδε τοῦ τείχους. ἡ θάλασσα ἡμῖν ὑποκεχώρηκεν φέρετε τὰς κλίμακας, ἐγὼ δ’ ἡγήσομαι.”", "st": "7.21"}, {"sp": "N", "t": "καὶ πρῶτος ἁρπάσας τινὰ τῶν κλιμάκων μετέφερέ τε καὶ ἀνέβαινεν, οὔπω τινὸς ἀναβάντος ἄλλου, μέχρι περισχόντες αὐτὸν οἵ τε ὑπασπισταὶ καὶ ἡ ἄλλη στρατιὰ τόνδε μὲν ἐπέσχον, αὐτοὶ δὲ πολλὰς ὁμοῦ κλίμακας προσετίθεσάν τε καὶ ἀνεπήδων. βοῆς δὲ καὶ ὁρμῆς ἑκατέρωθεν γενομένης, καὶ ποικίλων ἔργων καὶ παθῶν, ἐκράτησαν ὅμως οἱ Ῥωμαῖοι, καὶ πύργων τινῶν ἐπέβησαν ὀλίγων, οἷς ὁ Σκιπίων σαλπικτὰς καὶ βυκανιστὰς ἐπιστήσας ἐξοτρύνειν ἐκέλευσε καὶ θορυβεῖν ὡς τῆς πόλεως εἰλημμένης ἤδη. ἕτεροί τε περιθέοντες ὁμοίως διετάρασσον. καὶ καθαλόμενοί τινες ἀνέῳξαν τῷ Σκιπίωνι τὰς πύλας· ὁ δ’ ἐσεπήδησε μετὰ τῆς στρατιᾶς δρόμῳ. καὶ τῶν ἔνδον οἱ μὲν ἐς τὰς οἰκίας ἀπεδίδρασκον, ὁ δὲ Μάγων τοὺς μυρίους ἐς τὴν ἀγορὰν συνεκάλει. ταχὺ δὲ καὶ τούτων κατακοπέντων, ἐς τὴν ἄκραν σὺν ὀλίγοις ἀνεχώρει. τοῦ δὲ Σκιπίωνος καὶ ἐπὶ τὴν ἄκραν εὐθὺς ἐπιόντος, οὐδὲν ἔτι δρᾶν σὺν ἡττημένοις τε καὶ κατεπτηχόσιν ἔχων ἐνεχείρισεν ἑαυτὸν τῷ Σκιπίωνι.", "st": "7.22"}, {"sp": "N", "t": "ὁ δὲ τόλμῃ καὶ τύχῃ πόλιν εὐδαίμονα καὶ δυνατὴν ἑλὼν ἡμέρᾳ μιᾷ, τετάρτῃ τῆς ἐπ’ αὐτὴν ἀφίξεως, ἐπῇρτο μεγάλως, καὶ μᾶλλον ἐδόκει κατὰ θεὸν ἕκαστα δρᾶν, αὐτός τε οὕτως ἐφρόνει καὶ οὕτως ἐλογοποίει καὶ τότε καὶ ἐς τὸν ἔπειτα βίον, ἀρξάμενος ἐξ ἐκείνου. πολλάκις γοῦν ἐς τὸ Καπιτώλιον ἐσῄει μόνος, καὶ τὰς θύρας ἐπέκλειεν ὥσπερ τι παρὰ τοῦ θεοῦ μανθάνων. καὶ νῦν ἔτι τὴν εἰκόνα τὴν Σκιπίωνος ἐν ταῖς πομπαῖς μόνου προφέρουσιν ἐκ τοῦ Καπιτωλίου, τῶν δ’ ἄλλων ἐξ ἀγορᾶς φέρονται. τότε δ’ εἰρηνικὸν ὁμοῦ καὶ πολεμικὸν ταμιεῖον παραλαβών, ὅπλα τε πολλὰ ἐν αὐτῷ καὶ βέλη καὶ μηχανήματα καὶ νεωσοίκους καὶ ναῦς μακρὰς τρεῖς καὶ τριάκοντα, καὶ σῖτον καὶ ἀγορὰν ποικίλην, καὶ ἐλέφαντα καὶ χρυσὸν καὶ ἄργυρον, τὸν μὲν ἐν σκεύεσι πεποιημένον, τὸν δὲ ἐπίσημον, τὸν δὲ ἀσήμαντον, ὅμηρά τε Ἰβήρων καὶ αἰχμάλωτα, καὶ ὅσα Ῥωμαίων αὐτῶν προείληπτο, ἔθυε τῆς ἐπιούσης καὶ ἐθριάμβευε, καὶ τὴν στρατιὰν ἐπῄνει, καὶ τῇ πόλει μετὰ τὴν στρατιὰν ἐδημηγόρει, τῶν τε Σκιπιώνων αὐτοὺς ἀναμνήσας ἀπέλυε τοὺς αἰχμαλώτους ἐς τὰ ἴδια, θεραπεύων τὰς πόλεις. ἀριστεῖα δ’ ἐδίδου τῷ μὲν ἐς τὸ τεῖχος ἀναβάντι πρώτῳ μέγιστα, τῷ δ’ ἑξῆς τὰ ἡμίσεα τούτων, τῷ δὲ τρίτῳ τὰ τρίτα καὶ τοῖς ἄλλοις κατὰ λόγον. τὰ δὲ λοιπὰ ἐς Ῥώμην ἔπεμψεν ἐπὶ τῶν εἰλημμένων νεῶν, ὅσα χρυσὸς ἢ ἄργυρος ἦν ἢ ἐλέφας. ἡ μὲν δὴ πόλις ἔθυεν ἐπὶ πρεῖς ἡμέρας ὡς τῆς πατρῴας εὐπραξίας ἐκ πόνων πολλῶν αὖθις ἀνακυπτούσης, ἡ δὲ Ἰβηρία καὶ οἱ ἐν αὐτῇ Φοίνικες κατεπεπλήγεσαν τῷ μεγέθει καὶ τάχει τοῦ τολμήματος.", "st": "7.23"}, {"sp": "N", "t": "ὁ δὲ φρουρὰν μὲν Καρχηδόνι ἐπέστησε, καὶ τὸ τεῖχος ἐκέλευσε τὸ παρὰ τὴν ἄμπωτιν ἐς ὕψος ἐγεῖραι· τὴν δ’ ἄλλην Ἰβηρίαν αὐτός τε ἐπιὼν καὶ τοὺς φίλους ἐς ἕκαστα περιπέμπων ὑπήγετο, καὶ τἆλλα τὰ ἀντέχοντα ἐβιάζετο. Καρχηδονίων δ’ οἱ στρατηγοὶ δύο ὄντε λοιπὼ καὶ δύο Ἀσδρούβα, ὁ μὲν τοῦ Ἀμίλχαρος πορρωτάτω παρὰ Κελτίβηρσιν ἐξενολόγει, ὁ δὲ τοῦ Γέσκωνος ἐς μὲν τὰς πόλεις τὰς ἔτι βεβαίους περιέπεμπεν, ἀξιῶν Καρχηδονίοις ἐμμένειν ὡς στρατιᾶς ἐλευσομένης αὐτίκα ἀπείρου τὸ πλῆθος, Μάγωνα δ’ ἕτερον ἐς τὰ πλησίον περιέπεμπε ξενολογεῖν ὁπόθεν δυνηθείη, καὶ αὐτὸς ἐς τὴν Λέρσα γῆν τῶν ἀφισταμένων ἐνέβαλε, καί τινα αὐτῶν πόλιν ἔμελλε πολιορκήσειν. ἐπιφανέντος δὲ αὐτῷ τοῦ Σκιπίωνος ἐς Βαιτύκην ὑπεχώρει, καὶ πρὸ τῆς πόλεως ἐστρατοπέδευσεν· ἔνθα τῆς ἐπιούσης εὐθὺς ἡσσᾶτο, καὶ τὸν χάρακα αὐτοῦ καὶ τὴν Βαιτύκην ἔλαβεν ὁ Σκιπίων.", "st": "7.24"}, {"sp": "N", "t": "ὁ δὲ τὴν στρατιὰν τὴν Καρχηδονίων τὴν ἔτι οὖσαν ἐν Ἰβηρία συνέλεγεν ἐς Καρμώνην πόλιν, ὡς ὁμοῦ πᾶσιν ἀμυνούμενος τὸν Σκιπίωνα. καὶ αὐτῷ συνῆλθον πολλοὶ μὲν Ἰβήρων, οὓς Μάγων ἦγε, πολλοὶ δὲ Νομάδων, ὧν ἦρχε Μασσανάσσης. καὶ τούτων ὁ μὲν Ἀσδρούβας μετὰ τῶν πεζῶν ὑπὸ χάρακι ἐστρατοπέδευεν, ὁ δὲ Μασσανάσσης καὶ ὁ Μάγων ἱππαρχοῦντες αὐτῷ προηυλίζοντο τοῦ στρατοπέδου. ὧδε δὲ ἔχουσιν αὐτοῖς ὁ Σκιπίων τοὺς ἰδίους ἱππέας ἐπιδιῄρει, καὶ Λαίλιον μὲν ἐπὶ Μάγωνα ἔπεμπεν, αὐτὸς δ’ ἐπὶ Μασσανάσσην ἐτράπετο. μέχρι μὲν οὖν τινὸς ἦν ἐν ἀγῶνι καὶ πόνῳ δυσχερεῖ, τῶν Νομάδων αὐτὸν ἀκοντιζόντων τε καὶ ὑποχωρούντων, εἶτ’ αὖθις ἐπελαυνόντων· ὡς δὲ παρήγγειλεν ὁ Σκιπίων ἀμεταστρεπτὶ διώκειν αὐτούς, τὰ δόρατα προβαλόντας, οὐκ ἔχοντες ἀναστροφὴν οἱ Νομάδες κατέφυγον ἐς τὸ στρατόπεδον. καὶ ὁ Σκιπίων ἀποσχὼν δέκα σταδίους ἐστρατοπέδευσεν εὐσταθῶς ᾗπερ ἐβούλετο. ἦν δὲ ἡ μὲν τῶν ἐχθρῶν σύμπασα δύναμις ἑπτακισμύριοι πεζοὶ καὶ ἱππεῖς πεντακισχίλιοι καὶ ἐλέφαντες ἓξ καὶ τριάκοντα· Σκιπίωνι δὲ τούτων οὐδὲ τριτημόριον ἦν. διὸ καὶ μέχρι τινὸς ἐνεδοίαζε, καὶ μάχης οὐ κατῆρχεν, ἀλλ’ ἀκροβολισμοῖς ἐχρῆτο μόνοις.", "st": "7.25"}, {"sp": "N", "t": "ἐπεὶ δ’ ἐπέλειπεν αὐτὸν ἡ ἀγορὰ καὶ λιμὸς ἥπτετο τοῦ στρατοῦ, ἀναζεῦξαι μὲν οὐκ εὐπρεπὲς ἡγεῖτο εἶναι Σκιπίων· θυσάμενος δέ, καὶ εὐθὺς ἐπὶ ταῖς θυσίαις τὴν στρατιὰν ἐς ἐπήκοον ἐλάσας, καὶ τὸ βλέμμα καὶ τὸ σχῆμα διαθεὶς πάλιν ὥσπερ ἔνθους, ἔφη τὸ δαιμόνιον ἥκειν τὸ σύνηθες αὐτῷ, καὶ καλεῖν ἐπὶ τοὺς πολεμίους. χρῆναι δὲ θαρρεῖν θεῷ μᾶλλον ἢ πλήθει στρατοῦ· καὶ γὰρ τῶν πρότερον ἔργων κατὰ θεόν, οὐ κατὰ πλῆθος κρατῆσαι. ἔς τε πίστιν τῶν λεγομένων τὰ ἱερὰ παραφέρειν ἐς τὸ μέσον ἐκέλευε τοὺς μάντεις. καὶ λέγων ὁρᾷ τινὰς οἰωνοὺς πετομένους, οὓς μεθ’ ὁρμῆς καὶ βοῆς αὐτόθεν ἐπιστραφεὶς ἐδείκνυέ τε, καὶ ἔλεγεν ὅτι οἱ σύμβολα νίκης οἱ θεοὶ καὶ τάδε ἔπεμψαν. συνεκινεῖτο δὲ πρὸς αὐτὰ ἐνθέως ὁρῶν καὶ βοῶν. καὶ ἡ στρατιὰ πᾶσα ἐς τὰς ἐκείνου φαντασίας, περιφερομένου δεῦρο κἀκεῖσε, συνεπεστρέφετο, καὶ πάντες ὡς ἐπὶ νίκην ἕτοιμον ἠρεθίζοντο. ὁ δ’ ἐπεὶ πᾶν εἶχεν ὅσον τι καὶ ἐβούλετο, οὐκ ἀνέθετο, οὐδ’ εἴασε τὴν ὁρμὴν ἐκλυθῆναι, ἀλλ’ ὡς ἔτι ὢν θεόληπτος, ἔφη δεῖν ἐπὶ τοῖσδε τοῖς σημείοις εὐθὺς ἀγωνίσασθαι. καὶ φαγόντας ἐκέλευεν ὁπλίσασθαι, καὶ ἐπῆγεν ἀδοκήτως τοῖς πολεμίοις, τοὺς μὲν ἱππέας Σιλανῷ, τοὺς δὲ πεζοὺς Λαιλίῳ καὶ Μαρκίῳ παραδούς·", "st": "7.26"}, {"sp": "N", "t": "Ἀσδρούβας δὲ καὶ Μάγων καὶ Μασσανάσσης, ἐπιόντος αὐτοῖς τοῦ Σκιπίωνος ἄφνω σταδίων ὄντων ἐν μέσῳ δέκα μόνων, ἄσιτον οὖσαν ἔτι τὴν στρατιὰν ὥπλιζον μετὰ σπουδῆς καὶ θορύβου καὶ βοῆς. γενομένης δ’ ὁμοῦ πεζομαχίας τε καὶ ἱππομαχίας, οἱ μὲν ἱππεῖς οἱ τῶν Ῥωμαίων ἐκράτουν ὑπὸ τῆς αὐτῆς μηχανῆς, ἀμεταστρεπτὶ τοὺς Νομάδας διώκοντες, ὑποχωρεῖν εἰθισμένους καὶ ἐπελαύνειν· οἷς τὰ ἀκόντια διὰ τὴν ἐγγύτητα οὐδὲν ἦν ἔτι χρήσιμα· οἱ πεζοὶ δ’ ἐπονοῦντο ὑπὸ τοῦ πλήθους τῶν Λιβύων, καὶ ἡττῶντο δι’ ὅλης ἡμέρας. οὐδὲ τοῦ Σκιπίωνος αὐτοὺς ἐπιθέοντός τε καὶ παρακαλοῦντος μετετίθεντο, μέχρι τὸν ἵππον Σκιπίων τῷ παιδὶ παραδούς, καὶ παρά τινος ἀσπίδα λαβών, ἐξέδραμεν ὡς εἶχε μόνος ἐς τὸ μεταίχμιον, κεκραγώς, “ἐπικουρεῖτε, ὦ Ῥωμαῖοι, κινδυνεύοντι ὑμῶν τῷ Σκιπίωνι.” τότε γὰρ οἱ μὲν ἐγγὺς ὁρῶντες οἷ κινδύνου φέρεται, οἱ δὲ πόρρω πυνθανόμενοι, καὶ πάντες ὁμοίως αἰδούμενοί τε καὶ περὶ τῷ στρατηγῷ δεδιότες, ἐσέδραμον ἐς τοὺς πολεμίους μετ’ ἀλαλαγμοῦ καὶ βίας, ἣν οὐκ ἐνεγκόντες οἱ Λίβυες ἐνέδωκαν, ἐπιλειπούσης αὐτοὺς ἅμα τῆς δυνάμεως ὑπὸ τῆς ἀσιτίας περὶ ἑσπέραν· καὶ πολὺς αὐτῶν δι’ ὀλίγου τότε φόνος ἐγίγνετο. τοῦτο μὲν δὴ τέλος ἦν Σκιπίωνι τῆς περὶ Καρμώνην μάχης, ἐπισφαλοῦς ἐς πολὺ γενομένης. ἀπέθανον δ’ ἐν αὐτῇ Ῥωμαίων μὲν ὀκτακόσιοι, τῶν δὲ πολεμίων μύριοι καὶ πεντα· κισχίλιοι.", "st": "7.27"}, {"sp": "N", "t": "μετὰ δὲ τοῦθ’ οἱ μὲν Λίβυες ὑπεχώρουν ἀεὶ μετὰ σπουδῆς, ὁ δὲ Σκιπίων αὐτοῖς εἵπετο, βλάπτων τι καὶ λυπῶν ὁσάκις καταλάβοι. ὡς δ’ οἱ μὲν ὀχυρόν τι χωρίον προύλαβον, ἔνθα καὶ ὕδωρ ἦν ἄφθονον καὶ ἀγορά, καὶ οὐδὲν ἄλλο ἢ πολιορκεῖν αὐτοὺς ἔδει, Σκιπίωνα δ’ ἤπειγον ἕτεραι χρεῖαι, Σιλανὸν μὲν ἀπέλιπε τούσδε πολιορκεῖν, αὐτὸς δ’ ἐπῄει τὴν ἄλλην Ἰβηρίαν καὶ ὑπήγετο. Λιβύων δὲ τῶν ὑπὸ Σιλανοῦ πολιορκουμένων αὖθις ὑποχωρούντων, ἕως ἐπὶ τὸν πορθμὸν ἀφικόμενοι ἐς Γάδειρα ἐπέρασαν, ὁ Σιλανός, ὅσα δυνατὸν ἦν βλάψας, ἀνεζεύγνυεν ἐς Καρχηδόνα πρὸς Σκιπίωνα. Ἀσδρούβαν δὲ τὸν Ἀμίλχαρος, περὶ τὸν βόρειον ὠκεανὸν στρατιὰν ἔτι συλλέγοντα, ὁ ἀδελφὸς Ἀννίβας ἐκάλει κατὰ σπουδὴν ἐς τὴν Ἰταλίαν ἐσβαλεῖν. ὁ δὲ ἵνα λάθοι τὸν Σκιπίωνα, παρὰ τὸν βόρειον ὠκεανὸν τὴν Πυρήνην ἐς Γαλάτας ὑπερέβαινε, μεθ’ ὧν ἐξενολογήκει Κελτιβήρων. καὶ ὁ μὲν Ἀσδρούβας ὧδε ἐς τὴν Ἰταλίαν, τῶν Ἰταλῶν ἀγνοούντων, ἠπείγετο.", "st": "7.28"}, {"sp": "N", "t": "Λεύκιος δ’ ἀπὸ Ῥώμης ἐπανιὼν ἔφραζε τῷ Σκιπίωνι ὅτι αὐτὸν οἱ ἐν ἄστει Ῥωμαῖοι διανοοῦνται στρατηγὸν ἐς Λιβύην ἀποστέλλειν. ὁ δὲ τοῦδε αὐτοῦ μάλιστα ἐπιθυμῶν ἐκ πολλοῦ, καὶ ἐλπίζων ὧδε ἔσεσθαι, Λαίλιον ἐπὶ νεῶν πέντε προύπεμπεν ἐς Λιβύην πρὸς τὸν δυνάστην Σύφακα, δωρεάς τε φέροντα, καὶ τῶν Σκιπιώνων ὑπόμνησιν τῆς ἐς αὐτὸν Σύφακα φιλίας, καὶ δέησιν Ῥωμαίοις, ἂν ἐπίωσι, συλλαμβάνειν. ὁ δὲ ὑπέσχετό τε ποιήσειν, καὶ τὰ δῶρα ἔλαβε καὶ ἀντέπεμψεν ἕτερα. αἰσθόμενοι δὲ τούτων οἱ Καρχηδόνιοι, καὶ αὐτοὶ περὶ συμμαχίας ἐπρεσβεύοντο παρὰ τὸν Σύφακα. καὶ ὁ Σκιπίων πυνθανόμενός τε, καὶ μέγα ποιούμενος ἐπὶ Καρχηδονίοις προσλαβεῖν καὶ βεβαιώσασθαι Σύφακα, ᾔει πρὸς αὐτὸν ἐπὶ νεῶν δύο σὺν τῷ Λαιλίῳ.", "st": "7.29"}, {"sp": "N", "t": "καὶ αὐτῷ καταγομένῳ οἱ πρέσβεις τῶν Καρχηδονίων, ἔτι ὄντες παρὰ τῷ Σύφακι, ναυσὶν αἷς εἶχον μακραῖς ἐπανήγοντο, λαθόντες τὸν Σύφακα. ἀλλ’ ὁ μὲν ἱστίῳ χρώμενος παρέπλευσεν αὐτοὺς ἀδεῶς καὶ κατήχθη, ὁ δὲ Σύφαξ ἐξένιζεν ἀμφοτέρους, καὶ τῷ Σκιπίωνι συνθέμενος ἰδίᾳ καὶ πίστεις παρασχὼν ἀπέπεμπε, καὶ τοὺς Καρχηδονίους ἐφεδρεύοντας αὖθις αὐτῷ κατεῖχεν, ἕως ἐν βεβαίῳ τῆς θαλάσσης γένοιτο ὁ Σκιπίων. παρὰ μὲν δὴ τοσοῦτον ἦλθε κινδύνου Σκιπίων, καταγόμενός τε καὶ πλέων· λέγεται δ’ ἐν Σύφακος ἑστιώμενος συγκατακλιθῆναι τῷ Ἀσδρούβᾳ, καὶ αὐτὸν ὁ Ἀσδρούβας περὶ πολλῶν ἐρόμενος καταπλαγῆναι τῆς σεμνότητος, καὶ πρὸς τοὺς φίλους εἰπεῖν ὅτι μὴ μόνον πολεμῶν οὗτος ὁ ἀνὴρ ἀλλὰ καὶ ἑστιώμενος φοβερὸς εἴη.", "st": "7.30"}, {"sp": "N", "t": "τῷ δ’ αὐτῷ χρόνῳ Μάγωνί τινες Κελτιβήρων καὶ Ἰβήρων ἔτι ἐμισθοφόρουν, ὧν αἱ πόλεις ἐς Ῥωμαίους μετετέθειντο. καὶ ὁ Μάρκιος αὐτοῖς ἐπιθέμενος χιλίους μὲν καὶ πεντακοσίους διέφθειρεν, οἱ δὲ λοιποὶ διέφυγον αὐτὸν ἐς τὰς πόλεις. ἑτέρους δὲ ἑπτακοσίους ἱππέας καὶ πεζοὺς ἑξακιοχιλίους, Ἄννωνος αὐτῶν ἡγουμένου, συνήλασεν ἐς λόφον, ὅθεν ἀποροῦντες ἁπάντων ἐπρεσβεύοντο πρὸς τὸν Μάρκιον περὶ σπονδῶν. ὁ δ’ ἐκέλευεν αὐτοὺς Ἄννωνα καὶ τοὺς αὐτομόλους ἐκδόντας αὐτῷ, τότε πρεσβεύειν. οἱ μὲν δὴ καὶ τὸν Ἄννωνα στρατηγὸν ὄντα σφῶν συναρπάσαντες, ἔτι τῶν λεγομένων ἀκροώμενον, καὶ τοὺς αὐτομόλους παρέδοσαν· ὁ δὲ Μάρκιος ᾔτει καὶ τὰ αἰχμάλωτα. λαβὼν δὲ καὶ ταῦτα, ἐκέλευεν αὐτοὺς τακτὸν ἀργύριον κατενεγκεῖν ἅπαντας ἔς τι τοῦ πεδίου χωρίον· οὐ γὰρ ἁρμόζειν τὰ ὑψηλότερα τοῖς παρακαλοῦσιν. καταβάντων δὲ ἐς τὸ πεδίον ἔφη, “ἄξια μὲν θανάτου δεδράκατε, οἳ τὰς πατρίδας ἔχοντες ὑφ’ ἡμῖν, εἵλεσθε μετὰ τῶν ἐχθρῶν ἐπ’ αὐτὰς στρατεύειν· δίδωμι δ’ ὑμῖν, τὰ ὅπλα καταθεῖσιν, ἀπαθέσιν ἀπιέναι.” ἀγανακτησάντων δ’ εὐθὺς ὁμοῦ πάντων, καὶ ἀνακραγόντων οὐκ ἀποθήσεσθαι τὰ ὅπλα, μάχη γίγνεται καρτερά. καὶ τὸ μὲν ἥμισυ τῶν Κελτιβήρων, πολλὰ δρασάντων, κατεκόπη, τὸ δ’ ἥμισυ πρὸς Μάγωνα διεσώθη. ὁ δ’ ἄρτι μὲν ἐς τὸ στρατόπεδον τὸ Ἄννωνος κατεπεπλεύκει ναυσὶν ἑξήκοντα μακραῖς, μαθὼν δὲ τὴν Ἄννωνος συμφορὰν ἐς Γάδειρα διέπλει, καὶ λιμῷ κακοπαθῶν περιεσκόπει τὸ μέλλον.", "st": "7.31"}, {"sp": "N", "t": "καὶ Μάγων μὲν ἐπὶ ἀργίας ἦν, Σιλανὸς δ’ ἀπέσταλτο μὲν ὑπὸ τοῦ Σκιπίωνος Κάστακα πόλιν προσαγαγέσθαι, πολεμικῶς δ’ αὐτῷ τῶν Καστακαίων ἐχόντων παρεστρατοπέδευε, καὶ τοῦτο ἐμήνυε τῷ Σκιπίωνι. ὁ δὲ προπέμψας τινὰ παρασκευὴν πολιορκίας εἵπετο· καὶ παροδεύων ἐνέβαλεν ἐς Ἰλυργίαν πόλιν, ἣ Ῥωμαίων μὲν ἦν φίλη κατὰ τὸν πρότερον Σκιπίωνα, ἀναιρεθέντος δ’ ἐκείνου κρύφα μετετέθειτο, καὶ στρατιὰν ὑποδεξαμένη Ῥωμαίων ὡς ἔτι φίλη, Καρχηδονίοις ἐξεδεδώκει. ὧν χάριν ὁ Σκιπίων σὺν ὀργῇ τέσσαρσιν ὥραις ἐξεῖλεν αὐτήν, τρωθεὶς μὲν τὸν αὐχένα, τῆς δὲ μάχης οὐκ ἀνασχὼν ἕως ἐκράτησεν. καὶ ἡ στρατιὰ δι’ αὐτὸν, οὐδενὸς ἐπικελεύσαντος, ὑπεριδοῦσα τῆς ἁρπαγῆς, ἔκτεινον ὁμαλῶς καὶ παιδία καὶ γυναῖκας, μέχρι καὶ τὴν πόλιν αὐτοῖς ἐπικατέσκαψαν. ἀφικόμενος δ’ ἐς τὴν Κάστακα ὁ Σκιπίων τὸν μὲν στρατὸν ἐς τρία διεῖλε καὶ τὴν πόλιν ἐφρούρει, μάχης δὲ οὐκ ἦρχε, διδοὺς ἔτι τοῖς Καστακαίοις μεταγνῶναι. καὶ γὰρ ἤκουεν αὐτοὺς οὕτω φρονεῖν. οἱ δὲ τοῖς φρουροῦσι σφᾶς ἐμποδὼν οὖσιν ἐπιθέμενοι καὶ κρατήσαντες, ἐνεχείρισαν τὴν πόλιν τῷ Σκιπίωνι. καὶ τοῖσδε μὲν φρουρὰν ὁ Σκιπίων ἐπέστησε, καὶ τὴν πόλιν ἐπέτρεψεν ἑνὶ τῶν Καστακαίων ἐπὶ δόξης ὄντι ἀγαθῆς· αὐτὸς δ’ ἐς Καρχηδόνα ἀνεζεύγνυε, Σιλανὸν καὶ Μάρκιον περιπέμψας ἐπὶ τὸν πορθμόν, δῃοῦν ὅσα δύναιντο.", "st": "7.32"}, {"sp": "N", "t": "Ἀσταπὰ δ’ ἦν πόλις Καρχηδονίοις ἀεὶ ἐμμείνασα ὁμαλῶς· οἳ τότε τοῦ Μαρκίου σφᾶς περικαθημένου, συγγιγνώσκοντες ὅτι Ῥωμαῖοι λαβόντες αὐτοὺς ἀνδραποδιοῦνται, τὴν περιουσίαν σφῶν ἐς τὴν ἀγορὰν συνήνεγκαν, καὶ ξύλα περιθέντες αὐτῇ τὰ τέκνα καὶ τὰ γύναια ἐπέβησαν ἐπὶ τὴν ὕλην. πεντήκοντα δὲ σφῶν ὥρκωσαν τοὺς ἀρίστους, ὅταν ἡ πόλις ἁλίσκηται, τὰ γύναια καὶ τοὺς παῖδας ἀνελεῖν καὶ τὸ πῦρ ἅψαι καὶ ἑαυτοὺς ἐπικατασφάξαι. οἱ μὲν δὴ μάρτυρας τῶνδε ποιησάμενοι τοὺς θεούς, ἐξέδραμον ἐπὶ τὸν Μάρκιον οὐχ ὑφορώμενον οὐδέν, ὅθεν αὐτοῦ τοὺς ψιλοὺς καὶ τοὺς ἱππέας ἐτρέψαντο. ὁπλισαμένης δὲ τῆς φάλαγγος, τὰ μὲν τῶν Ἀσταπαίων ἦν ἄριστα, ἐξ ἀπογνώσεως μαχομένων, Ῥωμαῖοι δ’ ὅμως ἐκράτουν αὐτῶν διὰ τὸ πλῆθος· οὐ γὰρ δὴ τῇ γε ἀρετῇ χείρους ἦσαν οἱ Ἀσταπαῖοι. πεσόντων δὲ ἁπάντων, οἱ πεντήκοντα τὰς γυναῖκας καὶ τὰ παιδία κατέσφαξαν, καὶ τὸ πῦρ ἐγείραντες ἑαυτοὺς ἐπέρριψαν, ἀκερδῆ τοῖς πολεμίοις τὴν νίκην ἐργασάμενοι. ὁ δὲ Μάρκιος τὴν ἀρετὴν τῶν Ἀσταπαίων καταπλαγεὶς οὐκ ἐνύβρισεν ἐς τὰ οἰκόπεδα αὐτῶν.", "st": "7.33"}, {"sp": "N", "t": "μετὰ δὲ τοῦθ’ ὁ μὲν Σκιπίων ἐς ἀρρωστίαν ἐνέπεσε, καὶ ὁ Μάρκιος αὐτῷ διῴκει τὸ στρατόπεδον· ὅσοι δὲ τῶν στρατιωτῶν ὑπ’ ἀσωτίας ἀναλώκεσαν τὰ πεπορισμένα, ἡγούμενοι τῶν μὲν πόνων οὐδὲν ἄξιον ηὑρῆσθαι παρὰ τὸ μηδὲν ἔχειν, σφετερίζεσθαι δ’ αὐτῶν τὰ ἔργα καὶ τὴν δόξαν Σκιπίωνα, ἀφίσταντο ἀπὸ τοῦ Μαρκίου καὶ ἐφ’ ἑαυτῶν ἐστρατοπέδευον. ἔκ τε τῶν φρουρίων αὐτοῖς πολλοὶ συνέτρεχον, καὶ παρὰ Μάγωνός τινες ἀργύριον φέροντες ἔπειθον αὐτοὺς ἐς τὸν Μάγωνα μεταθέσθαι. οἱ δὲ τὸ μὲν ἀργύριον ἔλαβον, στρατηγοὺς δ’ ἀπὸ σφῶν ἑλόμενοι καὶ ταξιάρχους, καὶ τἆλλα διακοσμηθέντες, ἐφ’ ἑαυτῶν ἐτάσσοντο καὶ συνώμνυον ἀλλήλοις. πυθόμενος δ’ ὁ Σκιπίων ἐπέστελλεν ἐν μέρει μὲν τοῖς ἀφεστηκόσιν ὅτι διὰ τὴν νόσον αὐτοὺς οὐκ ἀμείψαιτό πω, ἐν μέρει δὲ τοῖς ἄλλοις, ἵνα μεταπείθωσιν αὐτοὺς πλανωμένους, κοινῇ δ’ ἅπασιν ἐπιστολὴν ἄλλην ὡς ἤδη συνηλλαγμένοις, ὅτι αὐτοὺς αὐτίκα ἀμείψεται. καὶ ἐκέλευεν εὐθὺς ἥκειν ἐπὶ σῖτον ἐς Καρχηδόνα.", "st": "7.34"}, {"sp": "N", "t": "ἀναγιγνωσκομένων δὲ τούτων, οἱ μὲν ὑπώπτευον, οἱ δὲ πιστεύειν ἠξίουν καὶ συνετίθεντο, καὶ πάντες ὥδευον ἐς τὴν Καρχηδόνα ὁμοῦ. προσιόντων δὲ αὐτῶν, ὁ Σκιπίων προσέταξε τοῖς συνοῦσίν οἱ βουλευταῖς ἕκαστον τῶν ἐξάρχων τινὰ τῆς στάσεως προσεταιρίσασθαι προσιόντα, καὶ ὡς ἀπ’ εὐνοίας διορθοῦντα ὑποδέξασθαί τε καὶ δῆσαι λαθόντα. προσέταξε δὲ καὶ τοῖς χιλιάρχοις τοὺς πιστοτάτους ἕκαστον ἀφανῶς ἅμα ἕῳ ξιφήρεις ἔχειν, καὶ τὰ εὔκαιρα τῆς ἐκκλησίας ἐκ διαστημάτων καταλαβόντας, ἤν τις ἐπανίστηται, κατακεντεῖν καὶ κατακαίνειν αὐτίκα ἄνευ παραγγέλματος. αὐτὸς δ’ ἄρτι φαινομένης ἡμέρας ἐπὶ τὸ βῆμα ἐκομίζετο, καὶ τοὺς κήρυκας ἐς ἐκκλησίαν ἐποτρύνειν περιέπεμπεν. οἱ δὲ αἰφνιδίου μὲν αὐτοῖς τοῦ κηρύγματος γενομένου, αἰδούμενοι δὲ ἔτι νοσοῦντα τὸν στρατηγὸν σφῶν παρακρατεῖν, καὶ νομίζοντες ἐπὶ τὰς ἀμοιβὰς καλεῖσθαι, συνέθεον ὁμοῦ πάντοθεν, οἱ μὲν ἄζωστοι τὰ ξίφη, οἱ δὲ καὶ ἐν χιτῶσι μόνοις, οὐ φθάσαντες οὐδὲ τὴν ἐσθῆτα πᾶσαν ἐπιθέσθαι.", "st": "7.35"}, {"sp": "N", "t": "Σκιπίων δὲ φρουρὰν ἔχων ἀμφ’ αὑτὸν ἀφανῆ, πρῶτα μὲν αὐτοῖς ἐπεμέμφετο τῶν γεγονότων, εἶτ’ ἔφη τὴν αἰτίαν ἀναθήσειν μόνοις τοῖς ἄρξασιν, “οὓς ἐγὼ κολάσω δι’ ὑμῶν.” καὶ λέγων ἔτι προσέταξε τοῖς ὑπηρέταις διαστῆσαι τὸ πλῆθος. οἱ μὲν δὴ διίστανον, οἱ δὲ βουλευταὶ τοὺς αἰτίους παρῆγον ἐς τὸ μέσον. ἀναβοησάντων δὲ αὐτῶν, καὶ τοὺς συστρατιώτας βοηθῆσαι σφίσι παρακαλούντων, τοὺς ἐπιφθεγγομένους εὐθὺς ἔκτεινον οἱ χιλίαρχοι. καὶ τὸ μὲν πλῆθος ἐπειδὴ τὴν ἐκκλησίαν φρουρουμένην εἶδεν, ἐφ’ ἡσυχίας ἦν σκυθρωποῦ· ὁ δὲ Σκιπίων τοὺς ἐς τὸ μέσον παραχθέντας αἰκισάμενος, καὶ μᾶλλον αὐτῶν τοὺς ἐκβοήσαντας, ἐκέλευσε τοὺς αὐχένας ἁπάντων ἐς τοὔδαφος παττάλοις προσδεθέντας ἀποτμηθῆναι, καὶ τοῖς ἄλλοις ἀμνηστίαν ἐκήρυξε διδόναι.", "st": "7.36"}, {"sp": "N", "t": "ὧδε μὲν τὸ στρατόπεδον καθίστατο τῷ Σκιπίωνι·", "st": "7.36"}, {"sp": "N", "t": "Ἰνδίβιλις δέ, τῶν συνθεμένων τις αὐτῷ δυναστῶν, στασιαζούσης ἔτι τῆς Ῥωμαϊκῆς στρατιᾶς κατέδραμέ τι τῆς ὑπὸ τῷ Σκιπίωνι γῆς. καὶ αὐτῷ τοῦ Σκιπίωνος ἐπελάσαντος, ὑπέστη μὲν τὸν ἀγῶνα γενναίως, καὶ χιλίους καὶ διακοσίους Ῥωμαίων διέφθειρεν, ἀπολομένων δ’ αὐτῷ δισμυρίων ἐδεῖτο προσπέμψας. καὶ ὁ Σκιπίων αὐτὸν χρήμασι ζημιώσας συνηλλάσσετο. λαθὼν δὲ καὶ Μασσανάσσης Ἀσδρούβαν ἐπέρασε τὸν πορθμόν, καὶ φιλίαν τῷ Σκιπίωνι συνθέμενος ὤμοσε συμμαχήσειν, ἂν ἐς Λιβύην στρατεύη. ἔπραξε δὲ τοῦτο ἀνὴρ ἐς πάντα βέβαιος διὰ τοιάνδε αἰτίαν. Ἀσδρούβου τοῦ τότε οἱ συνόντος στρατηγοῦ θυγάτηρ ἐς γάμον ἠγγύητο Μασσανάσσῃ· Σύφακα δ’ ἄρα τὸν δυνάστην ἔρως ἔκνιζε τῆς παιδός, καὶ οἱ Καρχηδόνιοι μέγα ποιούμενοι Σύφακα ἐπὶ Ῥωμαίους προσλαβεῖν, ἔδωκαν αὐτῷ τὴν παῖδα, οὐδὲν τοῦ Ἀσδρούβου πυθόμενοι, καὶ τῶνδε πραχθέντων ὁ μὲν Ἀσδρούβας αὐτὰ ἐπέκρυπτε, τὸν Μασσανάσσην αἰδούμενος, ὁ δὲ αἰσθόμενος συνέθετο τῷ Σκιπίωνι. Μάγων δὲ ὁ ναύαρχος ἀπογνοὺς ἀπὸ τῶν παρόντων τὰ ἐν Ἰβηρίᾳ, πλεύσας ἐς Λίγυας καὶ Κελτοὺς ἐξενολόγει. καὶ ὁ μὲν περὶ ταῦτα ἦν, καὶ τὰ Γάδειρα ἐκλειφθέντα ὑπὸ τοῦ Μάγωνος οἱ Ῥωμαῖοι παρέλαβον.", "st": "7.37"}, {"sp": "N", "t": "στρατηγοὺς δὲ Ἰβηρίας ἐτησίους ἐς τὰ ἔθνη τὰ εἰλημμένα ἔπεμπον ἀπὸ τοῦδε ἀρξάμενοι, μικρὸν πρὸ τῆς τετάρτης καὶ τεσσαρακοστῆς καὶ ἑκατοστῆς ὀλυμπιάδος, ἁρμοστὰς ἢ ἐπιστάτας αὐτοῖς τῆς εἰρήνης ἐσομένους. καὶ αὐτοῖς ὁ Σκιπίων ὀλίγην στρατιὰν ὡς ἐπὶ εἰρήνῃ καταλιπών, συνῴκισε τοὺς τραυματίας ἐς πόλιν, ἣν ἀπὸ τῆς Ἰταλίας Ἰταλικὴν ἐκάλεσε· καὶ πατρίς ἐστι Τραϊανοῦ τε καὶ Ἀδριανοῦ τῶν ὕστερον Ῥωμαίοις ἀρξάντων τὴν αὐτοκράτορα ἀρχήν. αὐτὸς δὲ ἐς Ῥώμην ἐπὶ στόλου πολλοῦ διέπλει, λαμπρῶς τε κεκοσμημένου καὶ καταγέμοντος αἰχμαλώτων ὁμοῦ καὶ χρημάτων καὶ ὅπλων καὶ λαφύρων ποικίλων. καὶ ἡ πόλις αὐτὸν ἐπιφανῶς ἐξεδέχετο μετὰ δόξης ἀοιδίμου τε καὶ παραλόγου διά τε νεότητα καὶ ταχυεργίαν καὶ μέγεθος εὐπραξίας. οἵ τε φθονοῦντες αὐτῷ τὴν πάλαι κουφολογίαν ὡμολόγουν ἐς ἔργον ἀποβῆναι. καὶ Σκιπίων μὲν θαυμαζόμενος ἐθριάμβευεν, Ἰνδίβιλις δὲ οἰχομένου τοῦ Σκιπίωνος αὖθις ἀφίστατο. καὶ αὐτὸν οἱ στρατηγοὶ τῆς Ἰβηρίας, τὸν στρατὸν ἀγείραντες ὅσος αὐτοῖς ἦν περὶ τὰ φρούρια, καὶ δύναμιν ἄλλην ἀπὸ τῶν ὑπηκόων συναγαγόντες, ἔκτειναν. τοὺς δ’ αἰτίους τῆς ἀποστάσεως ἐς κρίσιν παραγαγόντες θανάτῳ μετῆλθον, καὶ τὰ ὄντα αὐτοῖς ἐδήμευσαν. τά τε ἔθνη τὰ συναράμενα αὐτῷ χρήμασιν ἐζημίωσαν, καὶ τὰ ὅπλα αὐτῶν παρείλοντο, καὶ ὅμηρα ᾔτησαν, καὶ φρουρὰς δυνατωτέρας αὐτοῖς ἐπέστησαν. καὶ τάδε μὲν ἦν εὐθὺς μετὰ Σκιπίωνα, καὶ ἡ πρώτη Ῥωμαίων ἐς Ἰβηρίαν πεῖρα ἐς τοῦτο ἔληγε.", "st": "7.38"}, {"sp": "N", "t": "χρόνῳ δ’ ὕστερον, ὅτε Ῥωμαῖοι Κελτοῖς τε τοῖς περὶ Πάδον ἐπολέμουν καὶ Φιλίππῳ τῷ Μακεδόνι, ἐνεωτέρισαν αὖθις ἐς τὴν ἀσχολίαν αὐτῶν οἱ Ἴβηρες. καὶ αὐτοῖς ἐπέμφθησαν ἐκ Ῥώμης στρατηγοὶ τοῦδε τοῦ πολέμου Σεμπρώνιός τε Τουδιτανὸς καὶ Μᾶρκος Ἕλουιος, μετὰ δ’ ἐκείνους Μινούκιος. καὶ ἐπὶ τούτῳ, μείζονος ἔτι τῆς κινήσεως γιγνομένης, μετὰ πλέονος δυνάμεως ἐπέμφθη Κάτων, νέος μὲν ὢν ἔτι πάμπαν, αὐστηρὸς δὲ καὶ φιλόπονος, συνέσει τε γνώμης καὶ δεινότητι λόγων ἀριπρεπής, ὥστε αὐτὸν ἐπὶ τοῖς λόγοις ἐκάλουν οἱ Ῥωμαῖοι Δημοσθένη, πυνθανόμενοι τὸν ἄριστον ἐν τοῖς Ἕλλησι ῥήτορα γεγενῆσθαι Δημοσθένη.", "st": "7.39"}, {"sp": "N", "t": "ὡς δὲ κατέπλευσε τῆς Ἰβηρίας ἐς τὸ καλούμενον Ἐμπόριον ὁ Κάτων, οἱ μὲν πολέμιοι πάντοθεν ἐπ’ αὐτὸν ἐς τετρακισμυρίους ἀγηγέρατο, ὁ δ’ ἐπὶ μέν τι τὴν στρατιὰν ἐγύμναζεν, ὡς δ’ ἔμελλε συνενεχθήσεσθαι μάχῃ, τὰς ναῦς ἃς εἶχεν ἐς Μασσαλίαν ἀπέπεμψε, καὶ τὸν στρατὸν ἐδίδασκεν οὐ τοῦτο εἶναι φοβερόν, ὅτι πλήθει προύχουσιν οἱ πολέμιοι (τὴν γὰρ εὐψυχίαν ἀεὶ τοῦ πλέονος ἐπικρατεῖν), ἀλλ’ ὅτι νεῶν ἀποροῦμεν, ὡς οὐκ ἔχειν, εἰ μὴ κρατοῖμεν, οὐδὲ σωτηρίαν. ταῦτ’ εἰπὼν αὐτίκα συνέβαλεν, οὐκ ἐπελπίσας, ὥσπερ ἕτεροι, τὸν στρατόν, ἀλλὰ φοβήσας. γενομένης δ’ ἐν χερσὶ τῆς μάχης, ἐς πάντα μετεπήδα παρακαλῶν καὶ παροξύνων. ἀκρίτου δ’ αὐτῆς ἐς δείλην ἑσπέραν ἔτι οὔσης, καὶ πολλῶν πιπτόντων ἑκατέρωθεν, ἔς τινα λόφον ὑψηλὸν μετὰ τριῶν τάξεων ἐφέδρων ἀνέδραμε, τὸ ἔργον ὁμοῦ πᾶν ἐποψόμενος. ὡς δὲ εἶδε τοὺς μέσους τῶν ἰδίων μάλιστα ἐνοχλουμένους, ὥρμησεν ἐς αὐτοὺς προκινδυνεύων, ἔργῳ τε καὶ βοῇ συνετάραξε τοὺς ἐχθρούς, καὶ πρῶτος κατῆρξε τῆς νίκης. διώξας τε νυκτὸς ὅλης ἐκράτησεν αὐτῶν τοῦ στρατοπέδου, καὶ πολλοὺς ἀπέκτεινεν. ἐπανιόντι δ’ ὡς ἡγεμόνι τῆς νίκης συνήδοντο συμπλεκόμενοι. καὶ μετὰ τοῦτο ἀνέπαυε τὴν στρατιάν, καὶ τὰ λάφυρα ἐπίπρασκεν.", "st": "7.40"}, {"sp": "N", "t": "πρεσβευόντων δ’ ἐς αὐτὸν ἁπάντων ὅμηρά τε ᾔτησεν ἄλλα, καὶ βιβλία ἐσφραγισμένα ἐς ἑκάστους περιέπεμπε, καὶ τοὺς φέροντας ἐκέλευεν ἡμέρᾳ μιᾷ πάντας ἀποδοῦναι· καὶ ὥριζε τὴν ἡμέραν, τεκμηράμενος ὅτε μάλιστα ἐς τὴν πορρωτάτω πόλιν ἀφίξονται. ἐκέλευε δ’ ἡ γραφὴ ταῖς ἀρχαῖς τῶν πόλεων ἁπάσαις καθαιρεῖν τὰ τείχη σφῶν, αὐτῆς ἡμέρας ᾗ τὰ γράμματα λάβοιεν· εἰ δὲ ἀνάθοιντο τὴν ἡμέραν, ἀνδραποδισμὸν ἠπείλει. οἱ δὲ ἄρτι μὲν ἡττημένοι μεγάλῃ μάχῃ, ὑπὸ δὲ ἀγνοίας εἴτε μόνοις εἴθ’ ἅπασι ταῦτα προσετάχθη, φοβούμενοι μόνοι μὲν ὡς εὐκαταφρόνητοι, μετὰ δὲ τῶν ἄλλων μὴ μόνοι βραδύνωσι, καιρόν τε οὐκ ἔχοντες περιπέμψαι πρὸς ἀλλήλους, καὶ τοὺς στρατιώτας τοὺς ἐληλυθότας μετὰ τῶν γραμμάτων ἐφεστῶτας σφίσιν εὐλαβούμενοι, τὸ σφέτερον ἀσφαλὲς ἕκαστοι προύργου τιθέμενοι, τὰ τείχη καθῄρουν μετὰ σπουδῆς. ἐν ᾧ γὰρ ἅπαξ ὑπακούειν ἐδόκει, καὶ τὸ ταχέως εἰργάσθαι προσλαβεῖν ἐφιλοτιμοῦντο. οὕτω μὲν αἱ πόλεις αἱ περὶ Ἴβηρα ποταμὸν μιᾶς ἡμέρας, ὑφ’ ἑνὸς στρατηγήματος, αὐταὶ τὰ τείχη τὰ ἑαυτῶν καθῄρουν, καὶ Ῥωμαίοις ἐς τὸ μέλλον εὐέφοδοι γενόμεναι διέμειναν ἐς πλεῖστον ἐπὶ εἰρήνης.", "st": "7.41"}, {"sp": "N", "t": "Ὀλυμπιάσι δ’ ὕστερον τέσσαρσιν, ἀμφὶ τὰς πεντήκοντα καὶ ἑκατόν, πολλοὶ τῶν Ἰβήρων γῆς ἀποροῦντες ἀπέστησαν ἀπὸ Ῥωμαίων, ἄλλοι τε καὶ Λούσονες, οἳ περὶ τὸν Ἴβηρα ᾤκηνται. στρατεύσας οὖν ἐπ’ αὐτοὺς ὕπατος Φούλουιος Φλάκκος ἐνίκα μάχῃ. καὶ πολλοὶ μὲν αὐτῶν κατὰ πόλεις διελύθησαν· ὅσοι δὲ μάλιστα γῆς ἠπόρουν καὶ ἐξ ἄλης ἐβιότευον, ἐς Κομπλέγαν πόλιν συνέφυγον, ἣ νεόκτιστός τε ἦν καὶ ὀχυρά, καὶ ηὔξετο ταχέως. ὅθεν ὁρμώμενοι τὸν Φλάκκον ἐκέλευον, καταθέντα σφίσιν ὑπὲρ τῶν ἀνῃρημένων ἑκάστου σάγον τε καὶ ἵππον καὶ ξίφος, ἀποτρέχειν ἐξ Ἰβηρίας πρίν τι κακὸν παθεῖν. ὁ δὲ πολλοὺς αὐτοῖς ἔφη σάγους οἴσειν, καὶ τοῖς πρέσβεσιν αὐτῶν ἑπόμενος τῇ πόλει παρεστρατοπέδευσεν. οἱ δ’ ἀνομοίως ταῖς ἀπειλαῖς σφῶν αὐτίκα ἀπεδίδρασκον, καὶ τὰ τῶν ἐγγὺς βαρβάρων ἐλῄζοντο. χρῶνται δὲ διπλοῖς ἱματίοις παχέσιν, ἀντὶ χλαμύδων αὐτὰ περιπορπώμενοι, καὶ τοῦτο σάγον ἡγοῦνται.", "st": "7.42"}, {"sp": "N", "t": "Φλάκκῳ μὲν οὖν διάδοχος ἦλθεν ἐπὶ τὴν στρατηγίαν Τιβέριος Σεμπρώνιος Γράκχος. Κάραουιν δὲ πόλιν, ἣ Ῥωμαίων ἦν φίλη, δισμύριοι Κελτιβήρων ἐπολιόρκουν· καὶ ἐπίδοξος ἦν ἁλώσεσθαι, Γράκχου σφόδρα μὲν ἐπειγομένου βοηθῆσαι τῇ πόλει, περιιόντος δ’ ἐν κύκλῳ τοὺς πολεμίους, καὶ οὐκ ἔχοντος οὐδὲ μηνῦσαι τῇ πόλει περὶ ἑαυτοῦ. τῶν οὖν τις ἰλάρχων, Κομίνιος, ἐνθυμηθεὶς πρὸς ἑαυτὸν καὶ Γράκχῳ τὸ τόλμημα ἀνενεγκών, ἐνεπορπήσατο σάγον Ἰβηρικῶς, καὶ λαθὼν ἀνεμίχθη τοῖς χορτολογοῦσι τῶν πολεμίων, συνεσῆλθέ τε αὐτοῖς ὡς Ἴβηρ ἐς τὸ στρατόπεδον, καὶ ἐς τὴν Κάραουιν διαδραμὼν ἐμήνυσεν ὅτι Γράκχος ἐπίοι. οἱ μὲν δὴ διεσώθησαν, ἐγκαρτερήσαντες τῇ πολιορκίᾳ μέχρι Γράκχος αὐτοῖς ἐπῆλθε μετὰ τρίτην ἡμέραν, καὶ οἱ πολιορκοῦντες ἀπανέστησαν· δισμύριοι δ’ ἐκ τῆς Κομπλέγας διέτρεχον ἐς τὸ Γράκχου στρατόπεδον σὺν ἱκετηρίαις, καὶ πλησιάσαντες ἀδοκήτως ἐπέθεντο αὐτῷ, καὶ συνετάραξαν. ὁ δ’ εὐμηχάνως ἐξέλιπεν αὐτοῖς τὸ στρατόπεδον, καὶ ὑπεκρίνατο φεύγειν· εἶτα διαρπάζουσιν ἐπιστραφεὶς ἐπέπεσέ τε καὶ πλείστους ἔκτεινε, καὶ τῆς Κομπλέγας κατέσχε καὶ τῶν περιοίκων. τοὺς δὲ ἀπόρους συνῴκιζε, καὶ γῆν αὐτοῖς διεμέτρει. καὶ πᾶσιν ἔθετο τοῖς τῇδε συνθήκας ἀκριβεῖς, καθ’ ἃ Ῥωμαίων ἔσονται φίλοι· ὅρκους τε ὤμοσεν αὐτοῖς καὶ ἔλαβεν, ἐπιποθήτους ἐν τοῖς ὕστερον πολέμοις πολλάκις γενομένους. δι’ ἃ καὶ ἐν Ἰβηρίᾳ καὶ ἐν Ῥώμῃ διώνυμος ἐγένετο ὁ Γράκχος, καὶ ἐθριάμβευσε λαμπρῶς.", "st": "7.43"}, {"sp": "N", "t": "ἔτεσι δ’ οὐ πολλοῖς ὕστερον πόλεμος ἄλλος ἠγέρθη περὶ Ἰβηρίαν χαλεπὸς ἐκ τοιᾶσδε προφάσεως. Σεγήδη πόλις ἐστὶ Κελτιβήρων τῶν Βελλῶν λεγομένων μεγάλη τε καὶ δυνατή, καὶ ἐς τὰς Σεμπρωνίου Γράκχου συνθήκας ἐνεγέγραπτο. αὕτη τὰς βραχυτέρας πόλεις ἀνῴκιζεν ἐς αὑτήν, καὶ τεῖχος ἐς τεσσαράκοντα σταδίους κύκλῳ περιεβάλετο, Τίτθους τε ὅμορον γένος ἄλλο συνηνάγκαζεν ἐς ταῦτα. ἡ δὲ σύγκλητος πυθομένη τό τε τεῖχος ἀπηγόρευε τειχίζειν, καὶ φόρους ᾔτει τοὺς ὁρισθέντας ἐπὶ Γράκχου, στρατεύεσθαί τε Ῥωμαίοις προσέτασσε· καὶ γὰρ τοῦθ’ αἱ Γράκχου συνθῆκαι ἐκέλευον. οἱ δὲ περὶ μὲν τοῦ τείχους ἔλεγον ἀπηγορεῦσθαι Κελτίβηρσιν ὑπὸ Γράκχου μὴ κτίζειν πόλεις, οὐ τειχίζειν τὰς ὑπαρχούσας· τῶν δὲ φόρων καὶ τῆς ξεναγίας ὑπ’ αὐτῶν ἔφασαν Ῥωμαίων ἀφεῖσθαι μετὰ Γράκχον. καὶ τῷ ὄντι ἦσαν ἀφειμένοι, δίδωσι δ’ ἡ βουλὴ τὰς τοιάσδε δωρεὰς ἀεὶ προστιθεῖσα κυρίας ἔσεσθαι μέχρι ἂν αὐτῇ καὶ τῷ δήμῳ δοκῇ.", "st": "7.44"}, {"sp": "N", "t": "στρατηγὸς οὖν ἐπ’ αὐτοὺς Νωβελίων ἐπέμπετο μετὰ στρατιᾶς οὐ πολὺ τρισμυρίων ἀνδρῶν ἀποδεούσης· ὃν ἐπειδὴ σφίσιν οἱ Σεγηδαῖοι προσιόντα ἔγνωσαν, οὔπω τὸ τεῖχος ἐκτελέσαντες ἔφευγον ἐς Ἀρουακοὺς μετὰ παίδων καὶ γυναικῶν, καὶ σφᾶς ὑποδέχεσθαι τοὺς Ἀρουακοὺς παρεκάλουν. οἱ δὲ ὑποδέχονταί τε, καὶ Κάρον αὑτῶν Σεγηδαῖον, πολεμικὸν εἶναι νομιζόμενον, αἱροῦνται στρατηγόν. ὁ δὲ τρίτῃ μετὰ τὴν χειροτονίαν ἡμέρᾳ δισμυρίους πεζοὺς καὶ ἱππέας πεντακισχιλίους ἔς τινα λόχμην ἐνεδρεύσας παροδεύουσι τοῖς Ῥωμαίοις ἐπέθετο, καὶ τῆς μάχης ἐπὶ πολὺ ἀγχωμάλου γενομένης ἐκράτει τε λαμπρῶς, καὶ Ῥωμαίων τῶν ἐξ ἄστεος ἔκτεινεν ἐς ἑξακισχιλίους, ὡς μέγα τῇ πόλει γενέσθαι τὸ ἀτύχημα. ἀτάκτου δὲ αὐτῷ τῆς διώξεως ἐπὶ τῇ νίκῃ γενομένης, οἱ τὰ σκευοφόρα Ῥωμαίων φυλάσσοντες ἱππεῖς ἐπέδραμον, καὶ Κάρον τε αὐτὸν ἀριστεύοντα ἔκτειναν καὶ ἑτέρους ἀμφ’ αὐτόν, οὐκ ἐλάσσους καὶ οἵδε τῶν ἑξακισχιλίων, μέχρι νὺξ ἐπελθοῦσα διέλυσεν. ἐγίγνετο δὲ ταῦθ’ ὅτε Ῥωμαῖοι τῷ Ἡφαίστῳ τὴν ἑορτὴν ἄγουσιν· ὅθεν οὐδεὶς ἂν ἑκὼν ἄρξειεν ἐξ ἐκείνου μάχης παρὰ τήνδε τὴν ἡμέραν.", "st": "7.45"}, {"sp": "N", "t": "Ἀρουακοὶ μὲν οὖν εὐθὺς αὐτῆς νυκτὸς ἐς Νομαντίαν, ἣ δυνατωτάτη πόλις ἦν, συνελέγοντο, καὶ στρατηγοὺς Ἄμβωνα καὶ Λεύκωνα ᾑροῦντο· Νωβελίων δ’ αὐτοῖς τρισὶν ἡμέραις ὕστερον ἐπελθὼν παρεστρατοπέδευσεν ἀπὸ σταδίων τεσσάρων καὶ εἴκοσιν. παραγενομένων δέ οἱ Νομάδων ἱππέων τριακοσίων, οὓς Μασσανάσσης ἐπεπόμφει, καὶ ἐλεφάντων δέκα, τὴν στρατιὰν ἐπῆγε τοῖς πολεμίοις, ἄγων ὀπίσω τὰ θηρία λανθάνοντα. καὶ γενομένης ἐν χερσὶ τῆς μάχης οἱ μὲν ἄνδρες διέστησαν, τὰ δὲ θηρία ἐξεφαίνετο· καὶ οἱ Κελτίβηρες αὐτοί τε καὶ οἱ ἵπποι σφῶν οὐ πρὶν ἑωρακότες ἐλέφαντας ἐν πολέμοις ἐθορυβοῦντο καὶ κατέφευγον ἐς τὴν πόλιν. ὁ δὲ καὶ τοῖς τείχεσιν αὐτοὺς ἐπῆγε, καὶ ἐμάχετο γενναίως, μέχρι τῶν ἐλεφάντων τις ἐς τὴν κεφαλὴν λίθῳ μεγάλῳ καταπίπτοντι πληγεὶς ἠγριώθη τε, καὶ ἐκβοήσας μέγιστον ἐς τοὺς φίλους ἐπεστρέφετο, καὶ ἀνῄρει τὸν ἐν ποσίν, οὐ διακρίνων ἔτι φίλιον ἢ πολέμιον. οἵ τε ἄλλοι ἐλέφαντες πρὸς τὴν ἐκείνου βοὴν διαταραχθέντες ὅμοια πάντες ἔδρων, καὶ τοὺς Ῥωμαίους συνεπάτουν τε καὶ ἀνέτεμνον καὶ ἀνερρίπτουν. ὅπερ ἀεὶ θορυβηθέντες οἱ ἐλέφαντες εἰώθασι πάσχειν, καὶ πάντας ἡγεῖσθαι πολεμίους· καί τινες διὰ τήνδε τὴν ἀπιστίαν αὐτοὺς καλοῦσι κοινοὺς πολεμίους. φυγὴ οὖν τῶν Ῥωμαίων ἐγίγνετο ἄτακτος· ἣν οἱ Νομαντῖνοι κατιδόντες ἀπὸ τῶν τειχῶν ἐξέθορον, καὶ διώκοντες ἔκτειναν ἄνδρας μὲν ἐς τετρακισχιλίους ἐλέφαντας δὲ τρεῖς, ὅπλα τε πολλὰ καὶ σημεῖα ἔλαβον. Κελτιβήρων δὲ ἀπέθανον ἐς δισχιλίους.", "st": "7.46"}, {"sp": "N", "t": "καὶ ὁ Νωβελίων μικρὸν ἐκ τοῦ πταίσματος ἀναλαβών, ἀγορᾷ μέν τινι τῶν πολεμίων ἐπεχείρει περὶ Ἀξείνιον πόλιν σεσωρευμένῃ, οὐδὲν δὲ ἀνύσας, ἀλλὰ κἀνταῦθα πολλοὺς ἀποβαλών, ἐπανῆλθε νυκτὸς ἐς τὸ στρατόπεδον. ὅθεν Βιήσιον ἵππαρχον ἐπὶ συμμαχίαν ἔς τι γειτονεῦον ἔθνος ἔπεμπεν, ἱππέων δεόμενος. οἱ δὲ συνέπεμψαν αὐτῷ τινὰς ἱππέας, οὓς ἐρχομένους ἐλόχων οἱ Κελτίβηρες. καὶ τῆς ἐνέδρας ἐκφανείσης οἱ μὲν σύμμαχοι διεδίδρασκον, ὁ δὲ Βιήσιος μαχόμενος αὐτός τε καὶ σὺν αὐτῷ πολλοὶ Ῥωμαίων ἀπέθανον. συνεχῶν δὲ τοιῶνδε πταισμάτων αὐτοῖς ἐπιγιγνομένων, πόλις Ὄκιλις, ἔνθα ἡ ἀγορὰ καὶ τὰ χρήματα ἦν τὰ Ῥωμαίων, μετέθετο ἐς τοὺς Κελτίβηρας. καὶ ὁ Νωβελίων ἀπιστῶν ἅπασιν ἐν τῷ στρατοπέδῳ διεχείμαζε, στεγάσας ὡς ἐδύνατο, καὶ τὴν ἀγορὰν ἔχων ἔνδον, καὶ κακοπαθῶν αὐτῆς τε τῆς ἀγορᾶς τῇ ὀλιγότητι καὶ νιφετοῦ πυκνότητι καὶ κρύους χαλεπότητι, ὥστε πολλοὶ τῶν στρατιωτῶν οἱ μὲν ἐν τοῖς φρυγανισμοῖς, οἱ δὲ καὶ ἔνδον ὑπὸ στενοχωρίας καὶ κρύους ἀπώλλυντο.", "st": "7.47"}, {"sp": "N", "t": "τοῦ δ’ ἐπιόντος ἔτους Νωβελίωνι μὲν ἐπὶ τὴν στρατηγίαν ἀφικνεῖται διάδοχος Κλαύδιος Μάρκελλος, ἄγων πεζοὺς ὀκτακισχιλίους καὶ ἱππέας πεντακοσίους· λοχώντων δὲ καὶ τόνδε τῶν πολεμίων διῆλθε πεφυλαγμένως, καὶ σύμπαντι τῷ στρατῷ παρὰ τὴν Ὄκιλιν ἐστρατοπέδευσεν. ἐπιτυχὴς δὲ τὰ πολέμια ὢν τὴν πόλιν αὐτίκα παρεστήσατο, καὶ συγγνώμην ἔδωκεν, ὅμηρά τινα καὶ ἀργυρίου τάλαντα τριάκοντα λαβών. Νεργόβριγες δὲ αὐτοῦ περὶ τῆσδε τῆς μετριοπαθείας πυθόμενοι, πέμψαντες ἠρώτων τί ἂν πράξαντες εἰρήνης ἐπιτύχοιεν. ὡς δὲ αὐτοὺς ἐκέλευεν ἑκατὸν ἱππέας δοῦναι συστρατεύσοντας, οἱ μὲν ὑπισχνοῦντο δώσειν, κατὰ δ’ ἄλλο μέρος τοῖς οὐραγοῦσιν ἐπετίθεντο καὶ τῶν σκευοφόρων τι περιέσπων. εἶτ’ ἀφίκοντο τοὺς ἑκατὸν ἱππέας ἄγοντες ὡς δὴ κατὰ τὸ συγκείμενον, περί τε τῶν ἐπὶ τῆς οὐραγίας γενομένων ἔλεγον τινὰς ἀγνοοῦντας τὰ ὡμολογημένα ἁμαρτεῖν. ὁ δὲ τοὺς μὲν ἑκατὸν ἱππέας ἔδησε, τοὺς δ’ ἵππους αὐτῶν ἀποδόμενος καὶ τὸ πεδίον καταδραμὼν τὴν λείαν διεῖλε τῷ στρατῷ, καὶ τῇ πόλει παρεστρατοπέδευσεν. Νεργόβριγες δέ, προσαγομένων αὐτοῖς μηχανημάτων ἅμα μαὶ χωμάτων, κήρυκα πέμψαντες λυκῆν ἀντὶ κηρυκείου περικείμενον, ᾔτουν συγγνώμην. ὁ δὲ οὐκ ἔφη δώσειν, εἰ μὴ πάντες Ἀρουακοὶ καὶ Βελλοὶ καὶ Τίτθοι δεηθεῖεν ὁμοῦ. ὧν τὰ μὲν ἔθνη πυθόμενα προθύμως ἐπρεσβεύετο, καὶ τὸν Μάρκελλον ἠξίουν, ποινὴν αὐτοῖς ἐπιθέντα μετρίαν, ἐς τὰς Γράκχου συνθήκας ἀναγαγεῖν· ἀντέλεγον δ’ αὐτοῖς ἐπιχώριοί τινες ὑπ’ ἐκείνων πεπολεμημένοι.", "st": "7.48"}, {"sp": "N", "t": "καὶ ὁ Μάρκελλος ἐξ ἑκατέρων πρέσβεις ἐς Ῥώμην ἔπεμπεν ἀντιλέξοντας ἀλλήλοις, ἰδίᾳ δ’ ἐπέστελλε τῇ βουλῇ προτρέπων ἐς τὰς διαλύσεις· ἐβούλετο γὰρ ἐφ’ ἑαυτοῦ τὸν πόλεμον ἐκλυθῆναι, δόξαν οἱ χρηστὴν καὶ ἀπὸ τοῦδε νομίζων ἔσεσθαι. τῶν δὲ πρέσβεων οἱ μὲν ἐκ τῆς φιλίας ἐς τὴν πόλιν ἐσελθόντες ἐξενίζοντο, οἱ δὲ ἐκ τῶν πολεμίων, ὡς ἔθος ἐστίν, ἔξω τειχῶν ἐστάθμευον. ἀποδοκιμάζουσα δ’ ἡ βουλὴ τὴν εἰρήνην, καὶ χαλεπῶς φέρουσα ὅτι μή, καθάπερ αὐτοὺς ἠξίου Νωβελίων ὁ πρὸ Μαρκέλλου, Ῥωμαίοις αὑτοὺς ἐπετετρόφεσαν, Μάρκελλον αὐτοῖς ἐξοίσειν ἔφη τὰ δόξαντα. καὶ στρατιὰν εὐθὺς ἐκλήρουν ἐς Ἰβηρίαν τότε πρῶτον ἀντὶ καταλέξεως· πολλῶν γὰρ αἰτιωμένων τοὺς ὑπάτους ἀδίκους ποιεῖσθαι τὰς καταγραφὰς καί τινας ἐς τὰς κουφοτέρας στρατείας καταλέγειν, ἔδοξεν ἀπὸ κλήρου τότε συναγαγεῖν. ὧν ἐστρατήγει Λικίνιος Λεύκολλος ὕπατος, πρεσβευτῇ χρώμενος Κορνηλίῳ Σκιπίωνι τῷ Καρχηδόνα μετ’ οὐ πολὺ ἑλόντι, καὶ Νομαντίαν ὕστερον.", "st": "7.49"}, {"sp": "N", "t": "ὁ μὲν δὴ Λεύκολλος ὥδευεν, ὁ δὲ Μάρκελλος τόν τε πόλεμον προεῖπε τοῖς Κελτίβηρσι, καὶ τὰ ὅμηρα αἰτοῦσιν ἀπέδωκεν. τὸν δ’ ἐν Ῥώμῃ τοὺς λόγους διαθέμενον ὑπὲρ τῶν Κελτιβήρων ἰδίᾳ πρὸς αὑτὸν ἀνακαλέσας ἐπὶ πολὺ διέτριβεν· ὑπὲρ ὅτου δὴ καὶ ὑπωπτεύετο μὲν καὶ τότε, μᾶλλον δ’ ἐπιστώθη τοῖς ὕστερον γενομένοις, ὅτι αὐτοὺς ἀνέπειθεν ἑαυτῷ τὰ κατὰ σφᾶς ἐπιτρέψαι, ἐπειγόμενος ἄρα πρὸ τοῦ Λευκόλλου τὸν πόλεμον καταλυθῆναι. μετὰ γὰρ τὴν συνουσίαν Νεργόβριγα μὲν Ἀρουακῶν πεντακισχίλιοι κατέλαβον, Μάρκελλος δ’ ἐπὶ Νομαντίαν ἐχώρει, καὶ πέντε σταδίους ἀποσχὼν παρεστρατοπέδευεν αὐτοῖς καὶ συνεδίωκεν ἐς τὴν πόλιν, ἕως ὁ τῶν Νομαντίνων στρατηγὸς Λιτέννων ὑποστὰς ἐβόα βούλεσθαι Μαρκέλλῳ συνελθεῖν ἐς λόγους, καὶ συνελθὼν ἔφη Βελλοὺς καὶ Τίτθους καὶ Ἀρουακοὺς ἑαυτοὺς ἐπιτρέπειν Μαρκέλλῳ. ὁ δὲ ἄσμενος ἀκούσας ὅμηρά τε καὶ χρήματα πάντας ᾔτησε, καὶ λαβὼν ἀφῆκεν ἐλευθέρους. ὁ μὲν δὴ πόλεμος ὁ Βελλῶν τε καὶ Τίτθων καὶ Ἀρουακῶν ἔληγεν οὕτω πρὸ Λευκόλλου.", "st": "7.50"}, {"sp": "N", "t": "ὁ δὲ Λεύκολλος δόξης τε ἐπιθυμῶν, καὶ ἐκ πενίας χρῄζων χρηματισμοῦ, ἐς Οὐακκαίους. ἕτερον γένος Κελτιβήρων, ἐνέβαλεν, οἳ γείτονες τῶν Ἀρουακῶν εἰσίν, οὔτε τινὸς αὐτῷ ψηφίσματος γεγονότος, οὔτε Οὐακκαίων Ῥωμαίοις πεπολεμηκότων, οὐδὲ ἐς αὐτόν τι Λεύκολλον ἁμαρτόντων. περάσας δὲ τὸν ποταμὸν τὸν καλούμενον Τάγον, ἀφίκετο πρὸς Καύκαν πόλιν καὶ παρεστρατοπέδευσεν. οἱ δ’ ἐπύθοντο μὲν αὐτοῦ τίνος ἥκοι δεόμενος ἢ τί πολέμου χρῄζων, φήσαντος δὲ ὅτι Καρπητανοῖς ὑπὸ Οὐακκαίων ἀδικουμένοις βοηθοίη, τότε μὲν ἀνεχώρουν ἐς τὴν πόλιν, ξυλευομένῳ δὲ αὐτῷ καὶ χορτολογοῦντι ἐπέκειντο. καὶ κτείνουσι πολλούς, καὶ τοὺς λοιποὺς διώκουσιν ἐς τὸ στρατόπεδον. γενομένης δὲ καὶ παρατάξεως, οἱ Καυκαῖοι ψιλοῖς ἐοικότες ἐκράτουν ἐπὶ πολὺ τοῦ Λευκόλλου, μέχρι σφῶν τὰ ἀκόντια πάντα ἐξαναλώθη· καὶ τότε ἔφευγον οὐκ ὄντες μενεμάχοι, περί τε τὰς πύλας αὐτῶν ὠθουμένων ἀνῃρέθησαν ἀμφὶ τοὺς τρισχιλίους.", "st": "7.51"}, {"sp": "N", "t": "τῆς δ’ ἐπιούσης οἱ πρεσβύτατοι, στεφανωσάμενοί τε καὶ φέροντες ἱκετηρίας, τὸν Λεύκολλον αὖθις ἠρώτων τί ποιοῦντες ἂν εἶεν φίλοι. ὁ δὲ αὐτοὺς ὅμηρά τε ᾔτει καὶ ἀργυρίου τάλαντα ἑκατόν, καὶ τοὺς ἱππέας αὐτῶν ἐκέλευέν οἱ συστρατεύειν. ὡς δὲ πάντα ἔλαβεν, ἠξίου φρουρὰν ἐς τὴν πόλιν ἐσαγαγεῖν. δεξαμένων δὲ καὶ τοῦτο τῶν Καυκαίων, ἐσήγαγε δισχιλίους ἀριστίνδην ἐξειλεγμένους, οἷς ἐσελθοῦσιν εἴρητο γίγνεσθαι περὶ τὰ τείχη. καταλαβόντων δὲ αὐτὰ τῶν δισχιλίων, ἐσήγαγε τὴν ἄλλην στρατιὰν ὁ Λεύκολλος, καὶ τῇ σάλπιγγι ὑπεσήμαινε κτείνειν Καυκαίους ἅπαντας ἡβηδόν. οἱ μὲν δὴ πίστεις τε καὶ θεοὺς ὁρκίους ἐπικαλούμενοι, καὶ Ῥωμαίους ἐς ἀπιστίαν λοιδοροῦντες, διεφθείροντο ὠμῶς, ἐκ δισμυρίων ἀνδρῶν κατὰ πύλας ἀποκρήμνους διαφυγόντων ὀλίγων· ὁ δὲ Λεύκολλος τὴν πόλιν διήρπαζε, καὶ δόξης Ῥωμαίους ἐνεπίμπλη κακῆς. οἱ δ’ ἄλλοι βάρβαροι συνέθεον ἐκ τῶν πεδίων, οἱ μὲν ἐς τὰ ἀπόκρημνα, οἱ δὲ ἐς τὰς ὀχυρωτέρας πόλεις, συμφέροντες ἃ δύναιντο καὶ ἐμπιπράντες ὅσα λείποιεν, τοῦ μηδὲν ἔτι Λεύκολλον εὑρεῖν.", "st": "7.52"}, {"sp": "N", "t": "ὁ δὲ πολλὴν γῆν ἔρημον ὁδεύσας, ἔς τινα πόλιν Ἰντερκατίαν ἀφίκετο, ἔνθα πεζοὶ μὲν ὑπὲρ δισμυρίους συνεπεφεύγεσαν, ἱππεῖς δὲ δισχίλιοι. καὶ αὐτοὺς ὁ Λεύκολλος ἐς συνθήκας ὑπ’ ἀνοίας προυκαλεῖτο· οἱ δ’ ἐπ’ ὀνείδει τὰ Καυκαίων αὐτῷ προύφερον, καὶ ἐπυνθάνοντο εἰ ἐπὶ τὰς ἐκείνων πίστεις αὐτοὺς καλοίη. ὁ δ’, οἷον ἅπαντες οἱ ἁμαρτόντες, ἀνθ’ ἑαυτοῦ τοῖς ὀνειδίζουσι χαλεπαίνων, ἔκειρεν αὐτῶν τὰ πεδία, καὶ περικαθίσας κύκλῳ τὴν πόλιν χώματα ἤγειρε πολλά, καὶ συνεχῶς ἐξέτασσε προκαλούμενος ἐς μάχην. οἱ δ’ οὔτω μὲν ἀντεξέτασσον, ἀλλ’ ἦσαν ἀκροβολισμοὶ μόνοι, θαμινὰ δέ τις τῶν βαρβάρων ἐξίππευεν ἐς τὸ μεταίχμιον, κεκοσμημένος ὅπλοις περιφανῶς, καὶ προυκαλεῖτο Ῥωμαίων ἐς μονομαχίαν τὸν ἐθέλοντα, οὐδενὸς δ’ ὑπακούοντος ἐπιτωθάσας καὶ τῷ σχήματι κατορχησάμενος ἀπεχώρει. γιγνομένου δὲ τούτου πολλάκις, ὁ Σκιπίων ἔτι νέος ὢν ὑπερήλγησέ τε καὶ προπηδήσας ὑπέστη τὸ μονομάχιον, εὐτυχῶς δ’ ἐκράτησεν ἀνδρὸς μεγάλου μικρὸς ὤν.", "st": "7.53"}, {"sp": "N", "t": "καὶ τόδε μὲν ἐπῇρε Ῥωμαίους, νυκτὸς δὲ φόβοι πολλοὶ κατεῖχον· οἱ γὰρ ἱππεῖς, ὅσοι τῶν βαρβάρων, πρὶν ἀφικέσθαι Λεύκολλον, ἐπὶ χορτολογίαν προεληλύθεσαν, οὐκ ἔχοντες ἐσελθεῖν ἐς τὴν πόλιν Λευκόλλου περικαθημένου, περιθέοντες ἐβόων καὶ συνετάρασσον· καὶ συνεπήχουν οἱ ἔνδον αὐτοῖς. ὅθεν ὁ φόβος ἦν τοῖς Ῥωμαίοις ποικίλος. ἔκαμνον δὲ καὶ τῇ φυλακῇ δι’ ἀγρυπνίαν καὶ ἀήθειαν τροφῶν ἐπιχωρίων· οἴνου γὰρ οὐκ ὄντος οὐδ’ ἁλῶν οὐδ’ ὄξους οὐδ’ ἐλαίου, πυροὺς καὶ κριθὰς καὶ ἐλάφων κρέα πολλὰ καὶ λαγωῶν χωρὶς ἁλῶν ἑψόμενα σιτούμενοι κατερρήγνυντο τὰς γαστέρας, καὶ πολλοὶ καὶ ἀπώλλυντο, μέχρι ποτὲ τὸ χῶμα ἠγέρθη, καὶ τὰ τείχη τῶν πολεμίων τύπτοντες μηχαναῖς μέρος μέν τι κατέβαλον, καὶ ἐσέδραμον ἐς τὴν πόλιν· μετὰ δ’ οὐ πολὺ βιασθέντες τε καὶ ἀναχωροῦντες ἐσπίπτουσιν ἔς τινα δεξαμενὴν ὕδατος ὑπ’ ἀγνωσίας, ἔνθα οἱ πλείους ἀπώλοντο. καὶ νυκτὸς οἱ βάρβαροι τὰ πεσόντα ἀνῳκοδόμουν. πάνυ δ’ ἑκατέρων κακοπαθούντων (ὁ γὰρ λιμὸς ἀμφοῖν ἥπτετο) Σκιπίων ἀνεδέχετο τοῖς βαρβάροις οὐδὲν ἔσεσθαι παράσπονδον, καὶ πιστευθεὶς κατὰ κλέος ἀρετῆς διέλυσε τὸν πόλεμον ἐπὶ τοῖσδε, Λευκόλλῳ δοθῆναι παρὰ τῶν Ἰντερκατίων σάγους μυρίους καὶ θρεμμάτων τι πλῆθος ὡρισμένον, καὶ πεντήκοντα ἄνδρας ἐς ὅμηρα. χρυσὸν δὲ καὶ ἄργυρον Λεύκολλος αἰτῶν, οὗ δὴ χάριν, ἡγούμενος ὅλην Ἰβηρίαν πολύχρυσον εἶναι καὶ πολυάργυρον, ἐπολέμει, οὐκ ἔλαβεν· οὐ γὰρ εἶχον, οὐδ’ ἐν δόξῃ ταῦτ’ ἐκεῖνοι Κελτιβήρων τίθενται.", "st": "7.54"}, {"sp": "N", "t": "ἐπὶ δὲ Παλλαντίαν ᾔει πόλιν, ἣ δόξαν τε ἀρετῆς εἶχε μείζω, καὶ πολλοὶ συνεπεφεύγεσαν ἐς αὐτήν· ὅθεν αὐτῷ συνεβούλευόν τινες ἀποχωρεῖν πρὸ πείρας. ὁ δὲ πολυχρήματον εἶναι πυνθανόμενος οὐκ ἀνεχώρει, μέχρι σιτολογοῦντα αὐτὸν οἱ Παλλάντιοι συνεχῶς ἱππεῦσιν ἠνώχλουν τε καὶ σιτολογεῖν ἐκώλυον. ἀπορῶν δὲ τροφῶν ὁ Λεύκολλος ἀνεζεύγνυ, τετράγωνον ἐν πλινθίῳ τὸν στρατὸν ἄγων, ἑπομένων αὐτῷ καὶ τότε τῶν Παλλαντίων μέχρι Δορίου ποταμοῦ, ὅθεν οἱ μὲν Παλλάντιοι νυκτὸς ἀνεχώρουν, ὁ δ’ ἐς τὴν Τυρδιτανῶν χώραν διελθὼν ἐχείμαζεν. καὶ τοῦτο τέλος ἦν τοῦ Οὐακκαίων πολέμου, παρὰ ψήφισμα Ῥωμαίων ὑπὸ Λευκόλλου γενομένου. καὶ ὁ Λεύκολλος ἐπὶ τῷδε οὐδὲ ἐκρίθη.", "st": "7.55"}, {"sp": "N", "t": "τοῦ δ’ αὐτοῦ χρόνου μέρος ἄλλο Ἰβήρων αὐτονόμων, οἳ Λυσιτανοὶ καλοῦνται, Πουνίκου σφῶν ἡγουμένου τὰ Ῥωμαίων ὑπήκοα ἐλῄζοντο, καὶ τοὺς στρατηγοῦντας αὐτῶν, Μανίλιόν τε καὶ Καλπούρνιον Πίσωνα, τρεψάμενοι κτείνουσιν ἑξακισχιλίους, καὶ ἐπ’ αὐτοῖς Τερέντιον Οὐάρρωνα ταμίαν. οἷς ἐπαρθεὶς ὁ Πούνικος τὰ μέχρι ὠκεανοῦ κατέδραμε, καὶ Οὐέττωνας ἐς τὴν στρατείαν προσλαβὼν ἐπολιόρκει Ῥωμαίων ὑπηκόους τοὺς λεγομένους Βλαστοφοίνικας, οἷς φασὶν Ἀννίβαν τὸν Καρχηδόνιον ἐποικίσαι τινὰς ἐκ Λιβύης, καὶ παρὰ τοῦτο κληθῆναι Βλαστοφοίνικας. Πούνικος μὲν οὖν λίθῳ πληγεὶς ἐς τὴν κεφαλὴν ἀπέθανε, διαδέχεται δ’ αὐτὸν ἀνὴρ ᾧ ὄνομα ἦν Καίσαρος. οὗτος ὁ Καίσαρος Μουμμίῳ, μετὰ στρατιᾶς ἄλλης ἐπελθόντι ἀπὸ Ῥώμης, ἐς μάχην συνηνέχθη καὶ ἡττώμενος ἔφυγεν. Μουμμίου δ’ αὐτὸν ἀτάκτως διώκοντος ἐπιστραφεὶς ἔκτεινεν ἐς ἐννακισχιλίους, καὶ τήν τε λείαν τὴν ἡρπασμένην καὶ τὸ οἰκεῖον στρατόπεδον ἀνεσώσατο, καὶ τὸ Ῥωμαίων προσέλαβέ τε, καὶ διήρπασεν ὅπλα καὶ σημεῖα πολλά, ἅπερ οἱ βάρβαροι κατὰ τὴν Κελτιβηρίαν ὅλην περιφέροντες ἐπετώθαζον.", "st": "7.56"}, {"sp": "N", "t": "Μούμμιος δ’ ὑπολοίπους ἔχων πεντακισχιλίους ἐγύμναζεν ἔνδον ἐν τῷ στρατοπέδῳ, δεδιὼς ἄρα προελθεῖν ἐς τὸ πεδίον πρὶν τοὺς ἄνδρας ἀναθαρρῆσαι. φυλάξας δὲ εἴ τι μέρος οἱ βάρβαροι τῆς ἀφῃρημένης λείας παρέφερον, ἀδοκήτως αὐτοῖς ἐπέθετο, καὶ πολλοὺς διαφθείρας ἔλαβε τὴν λείαν καὶ τὰ σημεῖα. Λυσιτανῶν δ’ οἱ ἐπὶ θάτερα τοῦ Τάγου ποταμοῦ, κἀκεῖνοι Ῥωμαίοις πεπολεμωμένοι, Καυκαίνου σφῶν ἡγουμένου Κουνέους ἐπόρθουν, οἳ Ῥωμαίοις ἦσαν ὑπήκοοι, καὶ πόλιν αὐτῶν μεγάλην εἷλον Κονίστοργιν. παρά τε τὰς στήλας τὰς Ἡρακλείους τὸν ὠκεανὸν ἐπέρων, καὶ οἱ μὲν τὴν ἄλλην Λιβύην κατέτρεχον, οἱ δ’ Ὀκίλην πόλιν ἐπολιόρκουν. Μούμμιος δ’ ἑπόμενος ἐννακισχιλίοις πεζοῖς καὶ ἱππεῦσι πεντακοσίοις ἔκτεινε τῶν μὲν δῃούντων ἐς μυρίους καὶ πεντακισχιλίους, τῶν δ’ ἑτέρων τινάς, καὶ τὴν πολιορκίαν διέλυσε τὴν Ὀκίλης. ἐντυχὼν δὲ καὶ τοῖς φέρουσιν ἃ ἐσεσυλήκεσαν, ἔκτεινε καὶ τούσδε πάντας, ὡς μηδ’ ἄγγελον ἀπὸ τοῦ κακοῦ διαφυγεῖν. τὴν δὲ λείαν διαδοὺς τῷ στρατῷ τὴν δυνατὴν φέρεσθαι, τὰ λοιπὰ τοῖς θεοῖς τοῖς ἐνυαλίοις ἔκαυσεν.", "st": "7.57"}, {"sp": "N", "t": "καὶ Μούμμιος μὲν τάδε πράξας ἐπανῆλθεν ἐς Ῥώμην καὶ ἐθριάμβευσεν,", "st": "7.57"}, {"sp": "N", "t": "ἐκδέχεται δ’ αὐτὸν Μάρκος Ἀτίλιος, ὃς Λυσιτανῶν μὲν ἐς ἑπτακοσίους ἐπιδραμὼν ἀπέκτεινε, καὶ τὴν μεγίστην πόλιν ἐξεῖλεν, ᾗ ὄνομα Ὀξθράκαι, τὰ δ’ ἐγγὺς καταπληξάμενος ἅπαντα ἐπὶ συνθήκαις παρέλαβεν. καὶ τούτων ἦν ἔνια τοῦ Οὐεττώνων ἔθνους, ὁμόρου τοῖς Λυσιτανοῖς. ὡς δ’ ἀνεζεύγνυε χειμάσων ὁ Ἀτίλιος, αὐτίκα πάντες μετετίθεντο καί τινας Ῥωμαίοις ὑπηκόους ἐπολιόρκουν· οὓς ἐπειγόμενος ἐξελεῖν τῆς πολιορκίας Σέρουιος Γάλβας ὁ Ἀτιλίου διάδοχος, ἡμέρᾳ μιᾷ καὶ νυκτὶ πεντακοσίους σταδίους διελθὼν ἐπιφαίνεται τοῖς Λυσιτανοῖς, καὶ εὐθὺς ἐς μάχην ἐξέτασσε, κατάκοπον τὸν στρατὸν ἔχων. τρεψάμενος δ’ εὐτυχῶς τοὺς πολεμίους, ἐπέκειτο φεύγουσιν ἀπειροπολέμως. ὅθεν ἀσθενοῦς αὐτῷ καὶ ἀσυντάκτου τῆς διώξεως οὔσης διὰ κόπον, οἱ βάρβαροι κατιδόντες αὐτοὺς διεσπασμένους τε καὶ ἀναπαυομένους κατὰ μέρη συνελθόντες ἐπέθεντο, καὶ κτείνουσιν ἐς ἑπτακισχιλίους. ὁ δὲ Γάλβας μετὰ τῶν ἀμφ’ αὐτὸν ἱππέων κατέφυγεν ἐς Καρμώνην πόλιν, ἔνθα τοὺς διαφυγόντας ἀνελάμβανε, καὶ συμμάχους ἀθροίσας ἐς δισμυρίους διῆλθεν ἐς Κουνέους, καὶ παρεχείμαζεν ἐν Κονιστόργει.", "st": "7.58"}, {"sp": "N", "t": "Λεύκολλος δὲ ὁ τοῖς Οὐακκαίοις ἄνευ ψηφίσματος πολεμήσας ἐν Τυρδιτανίᾳ τότε χειμάζων ᾔσθετο Λυσιτανῶν ἐς τὰ πλησίον ἐμβαλόντων, καὶ περιπέμψας τοὺς ἀρίστους τῶν ἡγεμόνων, ἔκτεινε τῶν Λυσιτανῶν ἐς τετρακισχιλίους. περί τε Γάδειρα τὸν πορθμὸν ἑτέρων περώντων ἔκτεινεν ἐς χιλίους καὶ πεντακοσίους, καὶ τοὺς λοιποὺς συμφυγόντας ἔς τινα λόφον ἀπετάφρευσε, πλῆθός τε ἔλαβεν ἀνδρῶν ἄπειρον. καὶ τὴν Λυσιτανίαν ἐπιὼν κατὰ μέρος ἐπόρθει. ἐπόρθει δὲ καὶ Γάλβας ἐπὶ θάτερα. καὶ τινῶν πρεσβευομένων ἐς αὐτόν, καὶ θελόντων βεβαιοῦν καὶ ὅσα Ἀτιλίῳ τῷ πρὸ αὐτοῦ στρατηγῷ συνθέμενοι παρεβεβήκεσαν, ἐδέχετο καὶ ἐσπένδετο, καὶ ὑπεκρίνετο αὐτοῖς καὶ συνάχθεσθαι ὡς δι’ ἀπορίαν λῃστεύουσί τε καὶ πολεμοῦσι καὶ παρεσπονδηκόσιν. “τὸ γὰρ λυπρόγαιον,” ἔφη, “καὶ πενιχρὸν ὑμᾶς ἐς ταῦτα ἀναγκάζει· δώσω δ’ ἐγὼ πενομένοις φίλοις γῆν ἀγαθήν, καὶ ἐν ἀφθόνοις συνοικιῶ, διελὼν ἐς τρία.”", "st": "7.59"}, {"sp": "N", "t": "οἱ μὲν δὴ τάδε προσδοκῶντες ἀπὸ τῶν ἰδίων ἀνίσταντο, καὶ συνῄεσαν οἷ προσέτασσεν ὁ Γάλβας· ὁ δὲ αὐτοὺς ἐς τρία διῄρει, καὶ πεδίον ἑκάστοις τι ὑποδείξας ἐκέλευεν ἐν τῷ πεδίῳ περιμένειν, μέχρι πολίσειεν αὐτοὺς ἐπελθών. ὡς δ’ ἧκεν ἐπὶ τοὺς πρώτους, ἐκέλευεν ὡς φίλους θέσθαι τὰ ὅπλα, θεμένους δ’ ἀπετάφρευέ τε, καὶ μετὰ ξιφῶν τινας ἐσπέμψας ἀνεῖλεν ἅπαντας, ὀδυρομένους τε καὶ θεῶν ὀνόματα καὶ πίστεις ἀνακαλοῦντας. τῷ δ’ αὐτῷ τρόπῳ καὶ τοὺς δευτέρους καὶ τρίτους ἐπειχθεὶς ἀνεῖλεν, ἀγνοοῦντας ἔτι τὰ πάθη τὰ τῶν προτέρων, ἀπιστίᾳ μὲν ἄρα ἀπιστίαν μετιών, οὐκ ἀξίως δὲ Ῥωμαίων μιμούμενος βαρβάρους. ὀλίγοι δ’ αὐτῶν διέφυγον, ὧν ἦν Οὐρίατθος, ὃς μετ’ οὐ πολὺ ἡγήσατο Λυσιτανῶν καὶ ἔκτεινε πολλοὺς Ῥωμαίων καὶ ἔργα μέγιστα ἐπεδείξατο. ἀλλὰ τάδε μὲν ὕστερον γενόμενα ὕστερον λέξω. τότε δὲ ὁ Γάλβας, Λευκόλλου φιλοχρηματώτερος ὤν, ὀλίγα μέν τινα τῆς λείας τῇ στρατιᾷ διεδίδου, καὶ ὀλίγα τοῖς φίλοις, τὰ λοιπὰ δὲ ἐσφετερίζετο, καίτοι πλουσιώτατος ὢν ὁμοῦ τι Ῥωμαίων· ἀλλ’ οὐδ’ ἐν τῇ εἰρήνῃ φασὶν αὐτὸν διαλιπεῖν ψευδόμενόν τε καὶ ἐπιορκοῦντα διὰ κέρδη. μισούμενος δὲ καὶ κατηγορούμενος διέφευγε διὰ τὸν πλοῦτον,", "st": "7.60"}, {"sp": "N", "t": "οὐ πολὺ δὲ ὕστερον, ὅσοι διέφυγον ἐκ τῆς Λευκόλλου καὶ Γάλβα παρανομήσεως, ἁλισθέντες ἐς μυρίους τὴν Τυρδιτανίαν κατέτρεχον. καὶ αὐτοῖς ἀπὸ Ῥώμης ἐπελθὼν Γάιος Οὐετίλιος, ἄγων τέ τινα στρατὸν ἄλλον καὶ τοὺς ἐν Ἰβηρίᾳ προσλαβών, ἅπαντας ἔχων ἐς μυρίους, ἐπέπεσε προνομεύουσι, καὶ πολλοὺς ἀνελὼν συνέωσε τοὺς λοιποὺς ἔς τι χωρίον, οἷ κινδυνεύειν τε μένοντας ἐχρῆν ὑπὸ λιμοῦ καὶ ἀπιόντας ὑπὸ Ῥωμαίων· ὧδε γὰρ εἶχε δυσχωρίας. καὶ διὰ τοῦτο πρέσβεις ἐς τὸν Οὐετίλιον ἔπεμπον σὺν ἱκετηρίαις, γῆν ἐς συνοικισμὸν αἰτοῦντες ὡς ἀπὸ τοῦδε ἐσόμενοι Ῥωμαίων ἐς πάντα κατήκοοι. ὁ δὲ ὑπισχνεῖτο δώσειν, καὶ συνετίθετο ἤδη. Οὐρίατθος δ’ ὁ ἐκ τῆς Γάλβα παρανομίας ἐκφυγών, τότε συνὼν αὐτοῖς, ὑπεμίμνησκε τῆς Ῥωμαίων ἀπιστίας, ὁσάκις τε αὐτοῖς ὀμόσαντες ἐπιθοῖντο, καὶ ὡς ὅδε πᾶς ὁ στρατὸς ἐκ τοιῶνδε ἐπιορκιῶν Γάλβα καὶ Λευκόλλου διαφύγοιμεν. οὐδ’ ἀπορεῖν ἔφη σωτηρίας ἀπὸ τοῦδε τοῦ χωρίου, ἂν ἐθέλωσι πείθεσθαι.", "st": "7.61"}, {"sp": "N", "t": "Ἐρεθισθέντων δ’ αὐτῶν καὶ ἐν ἐλπίσι γενομένων, ᾑρέθη τε στρατηγός, καὶ πάντας ἐκτάξας ἐς μέτωπον ὡς ἐπὶ μάχῃ, τοὺς μὲν ἄλλους ἐκέλευσεν, ὅταν αὐτὸς ἐπιβῇ τοῦ ἵππου, διαιρεθέντας ἐς μέρη πολλὰ φεύγειν, ὡς δύνανται, κατ’ ἄλλας καὶ ἄλλας ὁδοὺς ἐς Τριβόλαν πόλιν, ἔνθα αὐτὸν περιμένειν, χιλίους δὲ μόνους ἐπιλεξάμενος ἐκέλευσεν αὑτῷ συνίστασθαι. καὶ γιγνομένων τούτων οἱ μὲν εὐθὺς ἔφυγον, ἐπειδὴ ὁ Οὐρίατθος τὸν ἵππον ἀνέβη, ὁ δὲ Οὐετίλιος αὐτοὺς δείσας διώκειν ἐς πολλὰ διῃρημένους, ἐπὶ τὸν Οὐρίατθον ἑστῶτα καὶ ἐφεδρεύοντα τῷ γενησομένῳ τραπεὶς ἐμάχετο. ὁ δ’ ὠκυτάτοις ἵπποις αὐτὸν ἐνοχλῶν, καὶ ὑποφεύγων καὶ πάλιν ἱστάμενος καὶ ἐπιών, ἐκείνην τε τὴν ἡμέραν ἐν τῷ αὐτῷ πεδίῳ καὶ τὴν ἐπιοῦσαν ὅλην διέτριψε περιθέων. ὡς δ’ εἴκασεν ἀσφαλῶς ἔχειν τῆς φυγῆς τοὺς ἑτέρους, τότε νυκτὸς ὁρμήσας δι’ ὁδῶν ἀτριβῶν κουφοτάτοις ἵπποις ἀπέδραμεν ἐς Τριβόλαν, Ῥωμαίων αὐτὸν διώκειν ὁμοίως οὐ δυναμένων διά τε βάρος ὅπλων καὶ ἀπειρίαν ὁδῶν καὶ ἵππων ἀνομοιότητα. ὧδε μὲν ἐξ ἀέλπτου στρατὸν ἀπογιγνώσκοντα αὑτοῦ περιέσωσε, καὶ τὸ στρατήγημα τόδε περιφερόμενον ἐς τοὺς τῇδε βαρβάρους ἐξῇρεν αὐτόν, καὶ πολλοὶ πανταχόθεν αὐτῷ προσεχώρουν. ὁ δὲ ἐς ὀκτὼ ἔτη Ῥωμαίοις ἐπολέμει.", "st": "7.62"}, {"sp": "N", "t": "καί μοι δοκεῖ τὸν Οὐριάτθου πόλεμον, σφόδρα τε ἐνοχλήσαντα Ῥωμαίοις καὶ δυσεργότατον αὐτοῖς γενόμενον, συναγαγεῖν, ἀναθέμενον εἴ τι τοῦ αὐτοῦ χρόνου περὶ Ἰβηρίαν ἄλλο ἐγίγνετο.", "st": "7.63"}, {"sp": "N", "t": "Οὐετίλιος μὲν δὴ αὐτὸν διώκων ἦλθεν ἐπὶ τὴν Τριβόλαν, ὁ δ’ Οὐρίατθος ἐν λόχμαις ἐνέδραν ἐπικρύψας ἔφυγε, μέχρι τὰς λόχμας ὑπερελθόντος τοῦ Οὐετιλίου αὐτός τε ἐπεστρέφετο καὶ οἱ ἐκ τῆς ἐνέδρας ἀνεπήδων, καὶ Ῥωμαίους ἑκατέρωθεν ἔκτεινόν τε καὶ ἐζώγρουν καὶ ἐς τὰς φάραγγας ἐώθουν. ἐζωγρήθη δὲ καὶ ὁ Οὐετίλιος· καὶ αὐτὸν ὁ λαβὼν ἀγνοῶν, γέροντα ὑπέρπαχυν ὁρῶν, ἔκτεινεν ὡς οὐδενὸς ἄξιον. Ῥωμαίων δὲ μόλις ἐκ μυρίων ἑξακισχίλιοι διέδρασαν ἐς Καρπησσόν, ἐπὶ θαλάσσῃ πόλιν, ἣν ἐγὼ νομίζω πρὸς Ἑλλήνων πάλαι Ταρτησσὸν ὀνομάζεσθαι, καὶ Ἀργανθώνιον αὐτῆς βασιλεῦσαι, ὃν ἐς πεντήκοντα καὶ ἑκατὸν ἔτη ἀφικέσθαι φασίν. τοὺς μὲν οὖν ἐς τὴν Καρπησσὸν διαφυγόντας ὁ ταμίας, ὃς εἵπετο τῷ Οὐετιλίῳ, συνέτασσεν ἐπὶ τειχῶν δεδιότας· παρὰ δὲ Βελλῶν καὶ Τίτθων αἰτήσας πεντακισχιλίους συμμάχους, καὶ λαβών, προύπεμψεν ἐπὶ τὸν Οὐρίατθον. ὁ δὲ πάντας ἔκτεινεν, ὡς μηδ’ ἄγγελον διαφυγεῖν. καὶ ὁ ταμίας ἡσύχαζεν ἐν τῇ πόλει, περιμένων τινὰ βοήθειαν ἀπὸ Ῥώμης.", "st": "7.63"}, {"sp": "N", "t": "Οὐρίατθος δὲ τὴν Καρπητανιαν, εὐδαίμονα χώραν, ἐπιὼν ἀδεῶς ἐλεηλάτει, ἕως ἧκεν ἐκ Ῥώμης Γάιος Πλαύτιος ἄγων πεζοὺς μυρίους καὶ ἱππέας χιλίους ἐπὶ τριακοσίοις. τότε δ’ αὖθις ὑπεκρίνατο φεύγειν ὁ Οὐρίατθος, καὶ ὁ Πλαύτιος αὐτὸν ἔπεμψε διώκειν ἐς τετρακισχιλίους, οὓς ἐπιστραφεὶς ὁ Οὐρίατθος ἔκτεινε χωρὶς ὀλίγων. καὶ τὸν Τάγον ποταμὸν διαβὰς ἐστρατοπέδευεν ἐν ὄρει περιφύτῳ μὲν ἐλάαις, Ἀφροδίτης δ’ ἐπωνύμῳ, ἔνθα ὁ Πλαύτιος καταλαβών, καὶ τὸ πταῖσμα ἀναλαβεῖν ἐπειγόμενος, συνέβαλεν. ἡττηθεὶς δὲ φόνου πολλοῦ γενομένου διέφυγεν ἀκόσμως ἐς τὰς πόλεις, καὶ ἐκ μέσου θέρους ἐχείμαζεν, οὐ θαρρῶν οὐδαμοῖ προϊέναι. ὁ δ’ Οὐρίατθος τὴν χώραν ἀδεῶς περιιών ᾔτει τοὺς κεκτημένους τιμὴν τοῦ ἐπικειμένου καρποῦ, καὶ παρ’ ὧν μὴ λάβοι διέφθειρεν.", "st": "7.64"}, {"sp": "N", "t": "ὧν οἱ ἐν ἄστει Ῥωμαῖοι πυνθανόμενοι Φάβιον Μάξιμον Αἰμιλιανόν, Αἰμιλίου Παύλου τοῦ Περσέα τὸν Μακεδόνων βασιλέα ἀνελόντος υἱόν, ἔπεμπον ἐς Ἰβηρίαν, καὶ στρατιὰν ἑαυτῷ καταγράφειν ἐπέτρεπον. ὁ δέ, Ῥωμαίων ἄρτι Καρχηδόνα καὶ τὴν Ἑλλάδα ἑλόντων καὶ τὸν τρίτον ἐν Μακεδονία πόλεμον κατωρθωκοτων, φειδοῖ τῶν ἀνδρῶν τῶν ἐκεῖθεν ἐληλυθότων κατέλεγε πρωθήβας, οὐ πρὶν πολέμου πεπειραμένους, ἐς δύο τέλη. καὶ παρὰ τῶν συμμάχων στρατὸν ἄλλον αἰτήσας ἧκεν ἐς Ὄρσωνα τῆς Ἰβηρίας σύμπαντας ἔχων πεζοὺς μυρίους καὶ πεντακισχιλίους καὶ ἱππέας ἐς δισχιλίους. ὅθεν οὔπω μάχης ἄρχων, μέχρι τὴν στρατιὰν γυμνάσειεν, ἐς Γάδειρα διέπλευσε τὸν πορθμόν, Ἡρακλεῖ θύσων. ὁ δὲ Οὐρίατθος αὐτοῦ τῶν ξυλευομένων τισὶν ἐπιπεσὼν ἔκτεινε πολλοὺς καὶ ἐφόβησε τοὺς λοιπούς. τοῦ δ’ ὑποστρατήγου συντάξαντος αὐτοὺς αὖθις ὁ Οὐρίατθος ἐκράτει καὶ πολλὴν λείαν περιεσύρατο. ἀφικομένου τε τοῦ Μαξίμου συνεχῶς ἐξέτασσε προκαλούμενος. ὁ δὲ ὅλῳ μὲν οὐ συνεμίσγετο τῷ στρατῷ, γυμνάζων αὐτοὺς ἔτι, κατὰ δὲ μέρη πολλάκις ἠκροβολίζετο, πεῖράν τε ποιούμενος τῶν πολεμίων καὶ τοῖς ἰδίοις ἐντιθεὶς θάρσος. χορτολογῶν τε ἐνόπλους ἀεὶ τοῖς γυμνοῖς περιίστη, καὶ περιέτρεχε μεθ’ ἱππέων αὐτός, οἷα Παύλῳ τῷ πατρὶ συστρατευόμενος ἐν Μακεδόσιν ἑώρα. μετὰ δὲ χειμῶνα γεγυμνασμένῳ τῷ στρατῷ τρέπεται δεύτερος ὅδε τὸν Οὐρίατθον καλῶς ἀγωνισάμενον καὶ πόλεις αὐτοῦ δύο τὴν μὲν διήρπασε τὴν δὲ ἐπέπρησεν, αὐτόν τε, φεύγοντα ἐς χωρίον ᾧ ὄνομα ἦν Βαικόρ, διώκων ἔκτεινε πολλούς. καὶ ἐχείμαζεν ἐν Κορδύβῃ, δεύτερον ἔτος ἤδη στρατηγῶν τοῦδε τοῦ πολέμου. καὶ τάδε μὲν ὁ Αἰμιλιανὸς ἐργασάμενος ἐς Ῥώμην ἀπῇρε, διαδεξαμένου τὴν ἀρχὴν Κοΐντου Πομπηίου τοῦ Αὔλου.", "st": "7.65"}, {"sp": "N", "t": "ἐφ’ οἷς ὁ Οὐρίατθος οὐχ ὁμοίως ἔτι καταφρονῶν, Ἀρουακοὺς καὶ Τίτθους καὶ Βελλούς, ἔθνη μαχιμώτατα, ἀπέστησεν ἀπὸ Ῥωμαίων. καὶ πολέμον ἄλλον οἵδε ἐφ’ ἑαυτῶν ἐπολέμουν, ὃν ἐκ πόλεως αὐτῶν μιᾶς Νομαντῖνον ἡγοῦνται, μακρόν τε καὶ ἐπίπονον Ῥωμαίοις γενόμενον. καὶ συνάξω καὶ τόνδε ἐς ἓν μετ’ Οὐρίατθον. Οὐρίατθος ὲν ἐπὶ θάτερα τῆς Ἰβηρίας ἑτέρῳ στρατηγῷ Ῥωμαιων Κοϊντίῳ συνεπλέκετο, καὶ ἡσσώμενος ἐς τὸ Ἀφροδίσιον ὄρος ἀνέστρεφεν. ὅθεν ἐπιστραφεὶς ἔκτεινε τῶν Κοϊντίου ἐς χιλίους, καὶ σημεῖά τινα ἥρπασε· τοὺς δὲ λοιποὺς ἐς τὸ στρατόπεδον αὐτῶν συνεδίωξε, καὶ τὴν ἐν Ἰτύκκῃ φρουρὰν ἐξέβαλε, καὶ τὴν Βαστιτανῶν χώραν ἐλῄζετο, Κοϊντίου διὰ δειλίαν καὶ ἀπειρίαν οὐκ ἐπιβοηθοῦντος, ἀλλ’ ἐν Κορδύβῃ χειμάζοντος ἐκ μέσου μετοπώρου, καὶ Γάιον Μάρκιον θαμινὰ ἐπιπέμποντος αὐτῷ, ἄνδρα Ἴβηρα ἐκ πόλεως Ἰταλικῆς.", "st": "7.66"}, {"sp": "N", "t": "τοῦ δ’ ἐπιόντος ἔτους Κοϊντίῳ μὲν ὁ ἀδελφὸς Αἰμιλιανοῦ, Φάβιος Μάξιμος Σερουιλιανός, ἦλθεν ἐπὶ τὴν στρατηγίαν διάδοχος, δύο ἄλλα τέλη Ῥωμαίων ἄγων καὶ συμμάχους τινάς, ἅπαντας ἐς μυρίους καὶ ὀκτακισχιλίους πεζοὺς καὶ ἱππέας ἑξακοσίους ἐπὶ χιλίοις. ἐπιστείλας δὲ καὶ Μικίψῃ τῷ Νομάδων βασιλεῖ πέμψαι οἱ τάχιστα ἐλέφαντας, ἐς Ἰτύκκην ἠπείγετο, τὴν στρατιὰν ἄγων κατὰ μέρος· καὶ τὸν Οὐρίατθον ἑξακισχιλίοις ἀνδράσιν ἐπιόντα οἱ μετά τε κραυγῆς καὶ θορύβου βαρβαρικοῦ καὶ κόμης μακρᾶς, ἣν ἐν τοῖς πολέμοις ἐπισείουσι τοῖς ἐχθροῖς, οὐδὲν ὑποπτήξας ὑπέστη τε γενναίως καὶ ἀπεώσατο ἄπρακτον. ὡς δέ οἱ καὶ τὸ ἄλλο πλῆθος ἀφῖκτο, καὶ ἐκ Λιβύης ἐλέφαντες δέκα σὺν ἱππεῦσι τριακοσίοις, στρατόπεδον ὠχύρου μέγα, καὶ προεπεχείρει τῷ Οὐριάτθῳ, καὶ τρεψάμενος αὐτὸν ἐδίωκεν. ἀτάκτου δὲ τῆς διώξεως γενομένης, ἰδὼν ἐν τῇ φυγῇ τοῦτο ὁ Οὐρίατθος ἐπανῆλθε, καὶ κτείνας ἐς τρισχιλίους τοὺς λοιποὺς συνήλασεν ἐς τὸ στρατοπεδον, καὶ προσέβαλε καὶ τῷδε, ὀλίγων μόλις αὐτὸν ὑφισταμένων περὶ τὰς πύλας, τῶν δὲ πλεόνων ἐς τὰς σκηνὰς καταδύντων ὑπὸ δέους καὶ μόλις ὑπὸ τοῦ στρατηγοῦ καὶ τῶν χιλιάρχων ἐξαγομένων. τότε μὲν οὖν Φάνιός τε, ὁ Λαιλίου κηδεστής, λαμπρῶς ἠρίστευε, καὶ νὺξ ἐπελθοῦσα Ῥωμαίους περιέσωσεν· ὁ δὲ Οὐρίατθος ἢ νυκτὸς ἢ καύματος ὥρᾳ θαμινὰ ἐπιών, καὶ οὔ τινα καιρὸν ἀδόκητον ἐκλείπων, ψιλοῖς ἀνδράσι καὶ ἵπποις ταχυτάτοις ἠνώχλει τοῖς πολεμίοις μέχρι τὸν Σερουιλιανὸν ἐς Ἰτύκκην ἀναστῆσαι.", "st": "7.67"}, {"sp": "N", "t": "τότε δὲ ἤδη τροφῶν τε ἀπορῶν ὁ Οὐρίατθος καὶ τὸν στρατὸν ἔχων ἐλάττω, νυκτὸς ἐμπρήσας τὸ στρατόπεδον ἐς Λυσιτανίαν ἀνεχώρει. καὶ αὐτὸν ὁ Σερουιλιανὸς οὐ καταλαβὼν ἐς Βαιτουρίαν ἐνέβαλε, καὶ πέντε πόλεις διήρπαζεν, αἳ τῷ Οὐριάτθῳ συνεπεπράχεσαν. μετὰ δὲ τοῦτο ἐστράτευεν ἐς Κουνέους, ὅθεν ἐς Λυσιτανοὺς ἐπὶ τὸν Οὐρίατθον αὖθις ἠπείγετο. καὶ αὐτῷ παροδεύοντι δύο λῄσταρχοι μετὰ μυρίων ἀνδρῶν ἐπιθέμενοι, Κούριός τε καὶ Ἀπουλήιος, ἐθορύβησαν καὶ τὴν λείαν ἀφείλοντο. καὶ Κούριος μὲν ἐν τῷ ἀγῶνι ἔπεσεν, ὁ δὲ Σερουιλιανὸς τήν τε λείαν μετ’ οὐ πολὺ ἀνέλαβε, καὶ πόλεις εἷλεν Εἰσκαδίαν τε καὶ Γέμελλαν καὶ Ὀβόλκολαν, φρουρουμένας ὑπὸ τῶν Οὐριάτθου, καὶ διήρπαζεν ἑτέρας, καὶ συνεγίγνωσκεν ἄλλαις· αἰχμάλωτα δ’ ἔχων ἀμφὶ τὰ μύρια, πεντακοσίων μὲν ἀπέτεμε τὰς κεφαλάς, τοὺς δὲ λοιποὺς ἀπέδοτο. καὶ Κοννόβαν μέν τινα λῄσταρχον ἑαυτὸν ἐγχειρίσαντα λαβών, καὶ φεισάμενος αὐτοῦ μόνου,", "st": "7.68"}, {"sp": "N", "t": "τοὺς σὺν αὐτῷ πάντας ἐχειροκόπησεν, Οὐρίατθον δὲ διώκων Ἐρισάνην αὐτοῦ πόλιν ἀπετάφρευεν, ἐς ἣν ὁ Οὐρίατθος ἐσδραμὼν νυκτὸς ἅμα ἕῳ τοῖς ἐργαζομένοις ἐπέκειτο, μέχρι τὰ σκαφεῖα ῥίψαντες ἔφευγον. τήν τε ἄλλην στρατιάν, ἐκταχθεῖσαν ὑπὸ τοῦ Σερουιλιανοῦ, τρεψάμενος ὁμοίως Οὐρίατθος ἐδίωκε, καὶ συνήλασεν ἐς κρημνούς, ὅθεν οὐκ ἦν τοῖς Ῥωμαίοις διαφυγεῖν. Οὐρίατθος δὲ ἐς τὴν εὐτυχίαν οὐχ ὕβρισεν, ἀλλὰ νομίσας ἐν καλῷ θήσεσθαι τὸν πόλεμον ἐπὶ χάριτι λαμπρᾷ, συνετίθετο Ῥωμαίοις, καὶ τὰς συνθήκας ὁ δῆμος ἐπεκύρωσεν· Οὐρίατθον εἶναι Ῥωμαίων φίλον, καὶ τοὺς ὑπ’ αὐτῷ πάντας ἧς ἔχουσι γῆς ἄρχειν. ὧδε μὲν ὁ Οὐριάτθου πόλεμος ἐδόκει πεπαῦσθαι, χαλεπώτατός τε Ῥωμαίοις γενόμενος καὶ ἐπὶ εὐεργεσίᾳ καταλυθείς.", "st": "7.69"}, {"sp": "N", "t": "οὐ μὴν ἐπέμεινεν οὐδ’ ἐς βραχὺ τὰ συγ κείμενα· ὁ γαρ ἀδελφὸς Σερουιλιανοῦ τοῦ ταῦτα συνθεμένου, Καιπίων, διάδοχος αὐτῷ τῆς στρατηγίας γενόμενος διέβαλλε τὰς συνθήκας, καὶ ἐπέστελλε Ῥωμαίοις ἀπρεπεστάτας εἶναι. καὶ ἡ βουλὴ τὸ μὲν πρῶτον αὐτῷ συνεχώρει κρύφα λυπεῖν τὸν Οὐρίατθον ὅ τι δοκιμάσειεν· ὡς δ’ αὖθις ἠνώχλει καὶ συνεχῶς ἐπέστελλεν, ἔκρινε λῦσαί τε τὰς σπονδὰς καὶ φανερῶς πολεμεῖν αὖθις Οὐριάτθῳ. ἐψηφισμένου δὴ σαφῶς, ὁ Καιπίων Ἄρσαν τε πόλιν ἐκλιπόντος Οὐριάτθου παρέλαβε, καὶ αὐτὸν Οὐρίατθον φεύγοντά τε καὶ τὰ ἐν παρόδῳ φθείροντα περὶ Καρπητανίαν κατέλαβε, πολὺ πλείονας ἔχων. ὅθεν ὁ Οὐρίατθος οὐ δοκιμάζων αὐτῷ συμπλέκεσθαι διὰ τὴν ὀλιγότητα, κατὰ μέν τινα φάραγγα ἀφανῆ τὸ πλέον τοῦ στρατοῦ περιέπεμψεν ἀπιέναι, τὸ δὲ λοιπὸν αὐτὸς ἐκτάξας ἐπὶ λοφου δόξαν παρεῖχε πολεμήσοντος. ὡς δ’ ᾔσθετο τῶν προαπεσταλμένων ἐν ἀσφαλεῖ γεγονότων, ἐξίππευσεν ἐς αὐτοὺς μετὰ καταφρονήσεως, ὀξέως οὕτως ὡς μηδ’ αἰσθέσθαι τοὺς διώκοντας ὅποι διέδραμεν. ὁ δὲ Καιπίων ἐς Οὐέττωνας καὶ Καλλαϊκοὺς τραπεὶς τὰ ἐκείνων ἐδῄου.", "st": "7.70"}, {"sp": "N", "t": "καὶ ζήλῳ τῶν ἔργων Οὐριάτθου τὴν Λυσιτανίαν λῃστήρια πολλὰ ἄλλα ἐπιτρέχοντα ἐπόρθει. Σέξτος δὲ Ἰούνιος Βροῦτος ἐπὶ ταῦτα πεμφθεὶς ἀπέγνω μὲν αὐτὰ διώκειν διὰ χώρας μακρᾶς, ὅσην ὁ Τάγος τε καὶ Λήθης καὶ Δόριος καὶ Βαίτις ποταμοὶ ναυσίποροι περιέχουσιν, ὀξέως, οἷα δὴ λῃστήρια, μεθισταμένους δυσεργὲς ἡγούμενος εἶναι καταλαβεῖν, καὶ αἰσχρὸν οὐ καταλαβόντι, καὶ νικήσαντι τὸ ἔργον οὐ λαμπρόν· ἐς δὲ τὰς πόλεις αὐτῶν ἐτράπετο, δίκην τε λήψεσθαι προσδοκῶν, καὶ τῇ στρατιᾷ πολὺ κέρδος περιέσεσθαι, καὶ τοὺς λῃστὰς ἐς ἑκάστην ὡς πατρίδα κινδυνεύουσαν διαλυθήσεσθαι. ὁ μὲν δὴ ταῦτ’ ἐνθυμούμενος ἐδῄου τὰ ἐν ποσὶν ἅπαντα, συμμαχομένων τοῖς ἀνδράσι τῶν γυναικῶν καὶ συναναιρουμένων, καὶ οὔ τινα φωνὴν οὐδ’ ἐν ταῖς σφαγαῖς ἀφιεισῶν. εἰσὶ δ’ οἳ καὶ ἐς τὰ ὄρη μεθ’ ὧν ἐδύναντο ἀνεπήδων· καὶ αὐτοῖς δεομένοις συνεγίγνωσκεν ὁ Βροῦτος, καὶ τὰ ὄντα ἐμερίζετο.", "st": "7.71"}, {"sp": "N", "t": "καὶ τὸν Δόριον περάσας πολλὰ μὲν πολέμῳ κατέδραμε, πολλὰ δὲ παρὰ τῶν αὑτοὺς ἐνδιδόντων ὅμηρα αἰτήσας ἐπὶ Λήθην μετῄει, πρῶτος ὅδε Ῥωμαίων ἐπινοῶν τὸν ποταμὸν τόνδε διαβῆναι. περάσας δὲ καὶ τόνδε, καὶ μέχρι Νίμιος ἑτέρου ποταμοῦ προελθών, Βρακάρων αὐτῷ φερομένην ἀγορὰν ἁρπασάντων ἐστράτευεν ἐπὶ τοὺς Βρακάρους, οἵ εἰσιν ἔθνος μαχιμώτατον, καὶ ἅμα ταῖς γυναιξὶν ὡπλισμέναις καὶ οἵδε ἐμάχοντο, καὶ προθύμως ἔθνησκον, οὐκ ἐπιστρεφόμενος αὐτῶν οὐδείς, οὐδὲ τὰ νῶτα δεικνύς, οὐδὲ φωνὴν ἀφιέντες. ὅσαι δὲ κατήγοντο τῶν γυναικῶν, αἱ μὲν αὑτὰς διεχρῶντο, αἱ δὲ καὶ τῶν τέκνων αὐτόχειρες ἐγίνοντο, χαίρουσαι τῷ θανάτῳ μᾶλλον τῆς αἰχμαλωσίας. εἰσὶ δέ τινες τῶν πόλεων αἳ τότε μὲν τῷ Βρούτῳ προσετίθεντο, οὐ πολὺ δ’ ὕστερον ἀφίσταντο. καὶ αὐτὰς ὁ Βροῦτος κατεστρέφετο αὖθις.", "st": "7.72"}, {"sp": "N", "t": "ἐπὶ δὲ Ταλάβριγα πόλιν ἐλθών, ἣ πολλάκις μὲν αὐτῷ συνετέθειτο, πολλάκις δὲ ἀποστᾶσα ἠνώχλει, παρακαλούντων αὐτὸν καὶ τότε τῶν Ταλαβρίγων καὶ διδόντων αὑτοὺς ἐς ὅ τι χρῄζοι, πρῶτα μὲν τοὺς αὐτομόλους Ῥωμαίων ᾔτει καὶ τὰ αἰχμάλωτα, καὶ ὅπλα ὅσα εἶχον, καὶ ὅμηρα ἐπὶ τούτοις, εἶτ’ αὐτοὺς ἐκέλευσε σὺν παισὶ καὶ γυναιξὶν ἐκλιπεῖν τὴν πόλιν. ὡς δὲ καὶ τοῦθ’ ὑπέστησαν, τὴν στρατιὰν αὐτοῖς περιστήσας ἐδημηγόρει, καταλέγων ὁσάκις ἀποσταῖεν καὶ ὅσους πολέμους πολεμήσειαν αὐτῷ. φόβον δὲ καὶ δόξαν ἐμφήνας ἐργασομένου τι δεινόν, ἐπὶ τῶν ὀνειδῶν ἔληξε, καὶ τοὺς μὲν ἵππους αὐτῶν καὶ τὸν σῖτον καὶ χρήματα ὅσα κοινὰ ἦν, ἢ εἴ τις ἄλλη δημοσία παρασκευή, πάντα περιεῖλε, τὴν δὲ πόλιν αὖθις οἰκεῖν ἔδωκεν ἐξ ἀέλπτου. τοσάδε μὲν δὴ Βροῦτος ἐργασάμενος ἐς Ῥώμην ἀπῄει. καὶ αὐτὰ ἐς τὴν Οὐριάτθου γραφὴν συνήγαγον, ἐν τῷ αὐτῷ χρόνῳ διὰ τὸν ἐκείνου ζῆλον ὑπὸ λῃστηρίων ἄλλων ἀρξάμενα γίγνεσθαι.", "st": "7.73"}, {"sp": "N", "t": "Οὐρίατθος δὲ Καιπίωνι περὶ συμβάσεων τοὺς πιστοτάτους αὑτῷ φίλους ἐπέπεμπεν, Αὔδακα καὶ Διτάλκωνα καὶ Μίνουρον, οἳ διαφθαρέντες ὑπὸ τοῦ Καιπίωνος δώροις τε μεγάλοις καὶ ὑποσχέσεσι πολλαῖς ὑπέστησαν αὐτῷ κτενεῖν τὸν Οὐρίατθον. καὶ ἔκτειναν ὧδε. ὀλιγοϋπνότατος ἦν διὰ φροντίδα καὶ πόνους ὁ Οὐρίατθος, καὶ τὰ πολλὰ ἔνοπλος ἀνεπαύετο, ἵνα ἐξεγρόμενος εὐθὺς ἐς πάντα ἕτοιμος εἴη. τοῖς οὖν φίλοις ἐξῆν καὶ νυκτερεύοντι ἐντυγχάνειν. ᾧ δὴ καὶ τότε ἔθει οἱ περὶ τὸν Αὔδακα φυλάξαντες αὐτόν, ἀρχομένου ὕπνου παρῆλθον ἐς τὴν σκηνὴν ὡς δή τινος ἐπείγοντος, καὶ κεντοῦσιν ὡπλισμένον ἐς τὴν σφαγήν· οὐ γὰρ ἦν ἄλλοθι. οὐδεμιᾶς δ’ αἰσθήσεως γενομένης διὰ τὴν τῆς πληγῆς εὐκαιρίαν, διέδρασαν ἐς Καιπίωνα καὶ τὰς δωρεὰς ᾔτουν. ὁ δ’ αὐτίκα μὲν αὐτοῖς ἔδωκεν ἀδεῶς ἔχειν ὅσα ἔχουσι, περὶ δὲ ὧν ᾔτουν, ἐς Ῥώμην αὐτοὺς ἔπεμπεν. οἱ δὲ θεραπευτῆρες Οὐριάτθου καὶ ἡ ἄλλη στρατιά, γενομένης ἡμέρας, ἀναπαύεσθαι νομίζοντες αὐτὸν ἐθαύμαζον διὰ τὴν ἀήθειαν, μέχρι τινὲς ἔμαθον ὅτι νεκρὸς κέοιτο ἔνοπλος. καὶ εὐθὺς ἦν οἰμωγή τε καὶ πένθος ἀνὰ τὸ στρατόπεδον, ἀλγούντων τε ἐπ’ ἐκείνῳ καὶ περὶ σφῶν δεδιότων, καὶ ἐνθυμουμένων ἐν οἵοις εἰσὶ κινδύνοις καὶ οἵου στρατηγοῦ στεροῦνται. μάλιστα δὲ αὐτούς, ὅτι τοὺς δράσαντας οὐχ ηὕρισκον, ὑπερήλγυνεν.", "st": "7.74"}, {"sp": "N", "t": "Οὐρίατθον μὲν δὴ λαμπρότατα κοσμήσαντες ἐπὶ ὑψηλοτάτης πυρᾶς ἔκαιον, ἱερεῖά τε πολλὰ ἐπέσφαττον αὐτῷ, καὶ κατὰ ἴλας οἵ τε πεζοὶ καὶ οἱ ἱππεῖς ἐν κύκλῳ περιθέοντες αὐτὸν ἔνοπλοι βαρβαρικῶς ἐπῄνουν, μέχρι τε σβεσθῆναι τὸ πῦρ παρεκάθηντο πάντες ἀμφ’ αὐτό. καὶ τῆς ταφῆς ἐκτελεσθείσης, ἀγῶνα μονομάχων ἀνδρῶν ἤγαγον ἐπὶ τοῦ τάφου. τοσοῦτον αὑτοῦ πόθον κατέλιπεν Οὐρίατθος, ἀρχικώτατος μὲν ὡς ἐν βαρβάροις γενόμενος, φιλοκινδυνότατος δ’ ἐς ἅπαντα πρὸ ἁπάντων, καὶ ἰσομοιρότατος ἐν τοῖς κέρδεσιν. οὐ γάρ ποτε πλέον ὑπέστη λαβεῖν, ἀεὶ παρακαλούντων· ὃ δὲ καὶ λάβοι, τοῖς ἀριστεύσασιν ἐδίδου. ὅθεν αὐτῷ, δυσχερέστατον ἔργον καὶ οὐδενί πω στρατηγῶν εὐμαρῶς ἐγγενόμενον, ἔτεσιν ὀκτὼ τοῦδε τοῦ πολέμου παμμιγὴς στρατὸς ἀστασίαστος ἦν καὶ κατήκοος ἀεὶ καὶ ἐς τοὺς κινδύνους ὀξύτατος. τότε δὲ σφῶν Τάνταλον ἑλόμενοι στρατηγεῖν, ἐπὶ Ζάκανθαν ἐφέροντο, ἣν Ἀννίβας καθελὼν ἔκτισε καὶ ἀπὸ τῆς αὑτοῦ πατρίδος Καρχηδόνα προσεῖπεν. ἀποκρουσθεῖσι δ’ αὐτοῖς ἐκεῖθεν, καὶ τὸν Βαῖτιν ποταμὸν περῶσιν, ὁ Καιπίων ἐπέκειτο, μέχρι κάμνων ὁ Τάνταλος αὑτόν τε καὶ τὴν στρατιὰν τῷ Καιπίωνι παρέδωκεν ὡς ὑπηκόοις χρῆσθαι. ὁ δὲ ὅπλα τε αὐτοὺς ἀφείλετο ἅπαντα, καὶ γῆν ἔδωκεν ἱκανήν, ἵνα μὴ λῃστεύοιεν ἐξ ἀπορίας.", "st": "7.75"}, {"sp": "N", "t": "ἐπάνεισι δ’ ἐς τὸν Ἀρουακῶν καὶ Νομαντίνων πόλεμον ἡ γραφή, οὓς Οὐρίατθος μὲν ἠρέθισεν ἐς ἀπόστασιν, Καικίλιος δ’ αὐτοῖς Μέτελλος ἀπὸ Ῥώμης ἐπιπεμφθεὶς μετὰ πλέονος στρατοῦ Ἀρουακοὺς μὲν ἐχειρώσατο, σὺν ἐκπλήξει καὶ τάχει θερίζουσιν ἐμπίπτων, Τερμεντία δ’ αὐτῷ καὶ Νομαντία ἔτι ἔλειπον. ἦν δ’ ἡ Νομαντία ποταμοῖς δύο καὶ φάραγξιν ἀπόκρημνος, ὗλαί τε αὐτῇ πυκναὶ περιέκειντο, καὶ μία κάθοδος ἦν ἐς τὸ πεδίον, ἣ τάφρων ἐπεπλήρωτο καὶ στηλῶν. αὐτοὶ δ’ ἦσαν ἄριστοι μὲν ἱππεῖς τε καὶ πεζοί, πάντες δ’ ἀμφὶ τοὺς ὀκτακισχιλίους. καὶ τοσοίδε ὄντες ὅμως ὑπ’ ἀρετῆς ἐς μέγα ἠνώχλησαν τὰ Ῥωμαίων. Μέτελλος μὲν δὴ μετὰ χειμῶνα τὴν στρατιὰν Κοΐντῳ Πομπηίῳ [Αὔλῳ] διαδόχῳ τῆς στρατηγίας οἱ γενομένῳ παρέδωκε, τρισμυρίους πεζοὺς καὶ δισχιλίους ἱππέας ἄριστα γεγυμνασμένους, ὁ δὲ Πομπήιος τῇ Νομαντίᾳ παραστρατοπεδεύων ᾤχετό ποι, καὶ ἱππέας αὐτοῦ μεταθέοντας αὐτὸν οἱ Νομαντῖνοι καταβάντες ἔκτειναν. ἐπανελθὼν οὖν παρέτασσεν ἐς τὸ πεδίον, καὶ οἱ Νομαντῖνοι καταβάντες ὑπεχώρουν κατ’ ὀλίγον οἷα φεύγοντες, μέχρι ταῖς στήλαις καὶ φάραγξιν ὁ Πομπήιος …", "st": "7.76"}, {"sp": "N", "t": "καὶ καθ’ ἡμέραν ἐν ταῖς ἀκροβολίαις ἐλασσούμενος ὑπ’ ἀνδρῶν πολὺ ἐλασσόνων, μετέβαινεν ἐπὶ Τερμεντίαν ὡς εὐχερέστερον ἔργον. ὡς δὲ καὶ τῇδε συμβαλὼν ἑπτακοσίους τε ἀπώλεσε, καὶ τὸν τὴν ἀγορὰν αὐτῷ φέροντα χιλίαρχον οἱ Τερμεντεῖς ἐτρέψαντο, καὶ τρίτῃ πείρᾳ κατὰ τὴν αὐτὴν ἡμέραν ἐς ἀπόκρημνα τοὺς Ῥωμαίους συνελάσαντες πολλοὺς αὐτῶν πεζούς τε καὶ ἱππέας αὐτοῖς ἵπποις κατέωσαν ἐς τὰ ἀπόκρημνα, περιφόβως ἔχοντες οἱ λοιποὶ διενυκτέρευον ἔνοπλοι, καὶ ἅμα ἕῳ προσιόντων τῶν πολεμίων ἐκταξάμενοι τὴν ἡμέραν ὅλην ἠγωνίζοντο ἀγχωμάλως, καὶ διεκρίθησαν ὑπὸ νυκτός. ὅθεν ὁ Πομπήιος ἐπὶ πολίχνης Μαλίας ἤλασεν, ἣν ἐφρούρουν οἱ Νομαντῖνοι. καὶ οἱ Μαλιεῖς τοὺς φρουροὺς ἀνελόντες ἐξ ἐνέδρας, παρέδοσαν τὸ πολίχνιον τῷ Πομπηίῳ. ὁ δὲ τά τε ὅπλα αὐτοὺς καὶ ὅμηρα αἰτήσας, μετῆλθεν ἐπὶ Σηδητανίαν, ἣν ἐδῄου λῄσταρχος ὄνομα Ταγγῖνος· καὶ αὐτὸν ὁ Πομπήιος ἐνίκα, καὶ πολλοὺς ἔλαβεν αἰχμαλώτους. τοσοῦτον δ’ ἦν φρονήματος ἐν τοῖς λῃσταῖς ὥστε τῶν αἰχμαλώτων οὐδεὶς ὑπέμεινε δουλεύειν, ἀλλ’ οἱ μὲν αὑτοὺς οἱ δὲ τοὺς πριαμένους ἀνῄρουν, οἱ δὲ τὰς ναῦς ἐν τῷ διάπλῳ διετίτρων.", "st": "7.77"}, {"sp": "N", "t": "ὁ δὲ Πομπήιος αὖθις ἐλάσας ἐπὶ Νομαντίαν, ποταμόν τινα μετωχέτευεν ἐς τὸ πεδίον ὡς λιμῷ πιέσων τὴν πόλιν. οἱ δὲ ἐργαζομένῳ τε ἐπέκειντο, καὶ σαλπικτῶν χωρὶς ἐκτρέχοντες ἀθρόοι τοὺς ὀχετεύοντας ἠνώχλουν. ἔβαλλον δὲ καὶ τοὺς ἀπὸ τοῦ χάρακος ἐπιβοηθοῦντας, ἕως κατέκλεισαν ἐς τὸ στρατόπεδον. καὶ σιτολογοῦσιν ἑτέροις ἐπιδραμόντες καὶ τῶνδε πολλοὺς διέφθειραν, Ὄππιόν τε χιλίαρχον ἐπ’ αὐτοῖς ἀνεῖλον. καὶ κατ’ ἄλλο μέρος τάφρον ὀρύσσουσι Ῥωμαίοις ἐπιδραμόντες ἔκτειναν ἐς τετρακοσίους, καὶ τὸν ἡγούμενον αὐτῶν. ἐφ’ οἷς τῷ τε Πομπηίῳ σύμβουλοι παρῆσαν ἐκ Ῥώμης, καὶ τοῖς στρατιώταις (ἓξ γὰρ ἔτη διεληλύθει στρατευομένοις) διάδοχοι νεοκατάγραφοί τε καὶ ἔτι ἀγύμναστοι καὶ ἀπειροπόλεμοι. μεθ’ ὧν ὁ Πομπήιος αἰδούμενός τε τὰ ἐπταισμένα, καὶ ἐπειγόμενος τὴν αἰσχύνην ἀναλαβεῖν, ἐπέμενε χειμῶνος ἐν τῷ στρατοπέδῳ. καὶ οἱ στρατιῶται κρύους τε ὄντος ἐν ἀστέγῳ σταθμεύοντες, καὶ πρῶτον ἄρτι πειρώμενοι τοῦ περὶ τὴν χώραν ὕδατός τε καὶ ἀέρος, κατὰ γαστέρα ἔκαμνον, καὶ διεφθείροντο ἔνιοι. μέρους δὲ ἐπὶ σῖτον οἰχομένου, κρύψαντες ἐνέδραν οἱ Νομαντῖνοι παρ’ αὐτὸ τὸ Ῥωμαίων στρατόπεδον ἠκροβολίζοντο ἐρεθίζοντες, ἕως οἱ μὲν οὐ φέροντες ἐπεξῄεσαν, οἱ δ’ ἐκ τῆς ἐνέδρας ἀνίσταντο· καὶ Ῥωμαῖοι πολλοὶ μὲν ἐκ τοῦ πλήθους, πολλοὶ δὲ τῶν ἐπιφανῶν ἀπέθανον· οἱ δὲ Νομαντῖνοι καὶ τοῖς τὸν σῖτον φέρουσιν ἀπαντήσαντες ἔκτειναν καὶ τῶνδε πολλούς.", "st": "7.78"}, {"sp": "N", "t": "καὶ ὁ Πομπήιος τοσοῖσδε συνενεχθεὶς κακοῖς ἐς τὰς πόλεις μετὰ τῶν συμβούλων ἀνεζεύγνυ, χειμάσων τὸ ἐπίλοιπον, τοῦ ἦρος προσδοκῶν ἥξειν οἱ διάδοχον. καὶ δεδιὼς κατηγορίαν, ἔπρασσεν ἐς τοὺς Νομαντίνους κρύφα τοῦ πολέμου διαλύσεις. οἱ δὲ καὶ αὐτοὶ κάμνοντες ἤδη φόνῳ τε πολλῷ ἀρίστων καὶ γῆς ἀργίᾳ καὶ τροφῶν ἀπορίᾳ καὶ μήκει τοῦ πολέμου, μακροῦ παρὰ προσδοκίαν γεγονότος, ἐπρέσβευον ἐς Πομπήιον. ὁ δὲ ἐς μὲν τὸ φανερὸν ἐκέλευεν αὑτοὺς Ῥωμαίοις ἐπιτρέπειν (οὐ γὰρ εἰδέναι σύνθήκας ἑτέρας Ῥωμαίων ἀξίας), λάθρᾳ δ’ ὑπισχνεῖτο ἃ ἔμελλε ποιήσειν. καὶ συνθεμένων ἐκείνων καὶ ἐπιτρεψάντων ἑαυτούς, ὅμηρά τε καὶ αἰχμάλωτα ᾔτησε καὶ τοὺς αὐτομόλους, καὶ πάντα ἔλαβεν. ᾔτησε δὲ καὶ ἀργυρίου τάλαντα τριάκοντα· ὧν μέρος αὐτίκα ἔδοσαν οἱ Νομαντῖνοι, καὶ τὰ λοιπὰ ὁ Πομτήιος ἀνέμενεν, παραγενομένου δ’ αὐτῷ διαδόχου Μάρκου Ποπιλίου Λαίνα, οἱ μὲν ἔφερον τὰ λοιπὰ τῶν χρημάτων, ὁ δ’ ἀπηλλαγμένος μὲν τοῦ περὶ τοῦ πολέμου δέους τῷ παρεῖναι τὸν διάδοχον, τὰς δὲ συνθήκας εἰδὼς αἰσχράς τε καὶ ἄνευ Ῥωμαίων γενομένας, ἠρνεῖτο μὴ συνθέσθαι τοῖς Νομαντίνοις. καὶ οἱ μὲν αὐτὸν ἤλεγχον ἐπὶ μάρτυσι τοῖς τότε παρατυχοῦσιν ἀπό τε βουλῆς καὶ ἱππάρχοις καὶ χιλιάρχοις αὐτοῦ Πομπηίου, ὁ δὲ Ποπίλιος αὐτοὺς ἐς Ῥώμην ἔπεμπε δικασομένους τῷ Πομπηίῳ. κρίσεως δ’ ἐν τῇ βουλῇ γενομένης, Νομαντῖνοι μὲν καὶ Πομπήιος ἐς ἀντιλογίαν ἦλθον, τῇ βουλῇ δ’ ἔδοξε πολεμεῖν Νομαντίνοις. καὶ ὁ Ποπίλιος ἐνέβαλεν ἐς τοὺς γείτονας αὐτῶν Λούσονας, οὐδὲν δ’ ἐργασάμενος (ἧκε γὰρ αὐτῷ διάδοχος ἐπὶ τὴν στρατηγίαν Ὁστίλιος Μαγκῖνος) ἀνέζευξεν ἐς Ῥώμην.", "st": "7.79"}, {"sp": "N", "t": "ὁ δὲ Μαγκῖνος τοῖς Νομαντίνοις συμβαλὼν ἡττᾶτό τε πολλάκις, καὶ τέλος ἀναιρουμένων πολλῶν ἐς τὸ στρατόπεδον ἔφυγεν. λόγου δὲ ψευδοῦς ἐμπεσόντος ὅτι Νομαντίνοις ἔρχονται βοηθοῦντες Κάνταβροί τε καὶ Οὐακκαῖοι, δείσας ἄπυρον τὴν νύκτα διήγαγεν ὅλην ἐν σκότῳ, φεύγων ἐς ἔρημον τὸ Νωβελίωνός ποτε χαράκωμα. καὶ μεθ’ ἡμέραν ἐς αὐτὸ συγκλεισθεὶς οὔτε κατεσκευασμένον οὔτε ὠχυρωμένον, περισχόντων αὐτὸν τῶν Νομαντίνων, καὶ πάντας ἀποκτενεῖν ἀπειλούντων εἰ μὴ συνθοῖτο εἰρήνην, συνέθετο ἐπὶ ἴσῃ καὶ ὁμοίᾳ Ῥωμαίοις καὶ Νομαντίνοις. καὶ ὁ μὲν ἐπὶ τούτοις ὤμνυε τοῖς Νομαντίνοις, οἱ δ’ ἐν ἄστει πυθόμενοι χαλεπῶς ἔφερον ὡς ἐπὶ αἰσχίσταις πάνυ σπονδαῖς, καὶ τὸν ἕτερον τῶν ὑπάτων Αἰμίλιον Λέπιδον ἐς Ἰβηρίαν ἐξέπεμπον, Μαγκῖνον δ’ ἀνεκάλουν ἐς κρίσιν. καὶ τῷδε μὲν ἕσποντο πρέσβεις Νομαντίνων· ὁ δὲ Αἰμίλιος, ἀναμένων καὶ ὅδε τὰς ἐκ Ῥώμης ἀποκρίσεις, καὶ τὴν ἀργίαν οὐ φέρων (ὡς γὰρ ἐπὶ δόξαν ἢ κέρδος ἢ θριάμβου φιλοτιμίαν ἐξῄεσάν τινες ἐς τὰς στρατηγίας, οὐκ ἐπὶ τὸ τῇ πόλει συμφέρον), Οὐακκαίων κατεψεύδετο ὡς ἀγορὰν ἐν τῷδε τῷ πολέμῳ Νομαντίνοις παρασχόντων, καὶ τὴν γῆν αὐτῶν κατέτρεχε, Παλλαντίαν τε πόλιν, ἣ μεγίστη Οὐακκαίων ἐστίν, οὐδὲν ἐξαμαρτοῦσαν ἐς τὰ συγκείμενα ἐπολιόρκει, καὶ Βροῦτον ἐφ’ ἕτερα τῆς Ἰβηρίας ἀπεσταλμένον, ὥς μοι προείρηται, κηδεστὴν ὄντα οἱ τοῦδε τοῦ ἔργου μετασχεῖν ἔπεισεν.", "st": "7.80"}, {"sp": "N", "t": "κατέλαβον δ’ αὐτοὺς ἀπὸ Ῥώμης πρέσβεις Κίννας τε καὶ Καικίλιος, οἳ τὴν βουλὴν ἔφασαν ἀπορεῖν εἰ τοσῶνδε πταισμάτων σφίσιν ἐν Ἰβηρίᾳ γενομένων ὁ Αἰμίλιος πόλεμον ἕτερον ἀρεῖται, καὶ ψήφισμα ἐπέδοσαν αὐτῷ προαγορεῦον Αἰμίλιον Οὐακκαίοις μὴ πολεμεῖν. ὁ δὲ ἀρξάμενός τε ἤδη τοῦ πολέμου, καὶ τὴν βουλὴν τοῦτ’ ἀγνοεῖν ἡγούμενος, ἀγνοεῖν δ’ ὅτι καὶ Βροῦτος αὐτῷ συνεπιλαμβάνει καὶ σῖτον καὶ χρήματα καὶ στρατιὰν Οὐακκαῖοι τοῖς Νομαντίνοις παρέσχον, ἔσεσθαι δὲ καὶ τὴν ἀνάζευξιν τοῦ πολέμου φοβερὰν ὑπολαβών, καὶ σχεδὸν Ἰβηρίας ὅλης διάλυσιν, εἰ καταφρονήσειαν ὡς δεδιότων, τοὺς μὲν ἀμφὶ τὸν Κίνναν ἀπράκτους ἀπέλυσε, καὶ τάδε αὐτὰ ἐπέστειλε τῇ βουλῇ, αὐτὸς δὲ ὀχυρωσάμενος φρούριον, μηχανὰς ἐν αὐτῷ συνεπήγνυτο καὶ σῖτον συνέφερεν. Φλάκκος δ’ αὐτῷ σιτολογῶν, ἐνέδρας ἐκφανείσης, εὐμηχάνως διέδωκεν ὅτι Παλλαντίαν ἐξεῖλεν Αἰμίλιος· καὶ τοῦ στρατοῦ συναλαλάξαντος ὡς ἐπὶ νίκῃ, πυθόμενοι τούτων οἱ βάρβαροι καὶ ἀληθῆ νομίσαντες ἀπεχώρουν. Φλάκκος μὲν δὴ τὴν ἀγορὰν κινδυνεύουσαν ὧδε περιέσωζε.", "st": "7.81"}, {"sp": "N", "t": "μακρᾶς δὲ τῆς ἐπὶ τῇ Παλλαντίᾳ πολιορκίας οὔσης αἱ τροφαὶ Ῥωμαίους ἐπέλειπον, καὶ λιμὸς ἥπτετο αὐτῶν, καὶ τὰ ὑποζύγια πάντα ἔφθαρτο, καὶ πολλοὶ τῶν ἀνθρώπων ἐξ ἀπορίας ἀπέθνησκον. οἱ στρατηγοὶ δέ, Αἰμίλιός τε καὶ Βροῦτος, ἐς μὲν πολὺ διεκαρτέρουν, ἡσσώμενοι δ’ ὑπὸ τοῦ κακοῦ νυκτὸς ἄφνω περὶ ἐσχάτην φυλακὴν ἐκέλευον ἀναζευγνύναι· χιλίαρχοί τε καὶ λοχαγοὶ περιθεοντες ἐπέσπευδον ἅπαντας ἐς τοῦτο πρὸ ἕω. οἱ δὲ σὺν θορύβῳ τά τε ἄλλα πάντα καὶ τοὺς τραυματίας καὶ τοὺς νοσοῦντας ἀπέλιπον, συμπλεκομένους τε σφίσι καὶ δεομένους. καὶ αὐτοῖς ἀτάκτου καὶ θορυβώδους τῆς ἀναχωρήσεως γιγνομένης καὶ φυγῇ μάλιστα ὁμοίας, οἱ Παλλάντιοι πανταχόθεν ἐπικείμενοι πολλὰ ἔβλαπτον ἐξ ἠοῦς ἐπὶ ἑσπέραν. νυκτὸς δὲ ἐπιλαβούσης Ῥωμαῖοι μὲν ἐς τὰ πεδία ἑαυτοὺς ἐρρίπτουν ἀνὰ μέρος, ὡς τύχοιεν, ἄσιτοι τε και κατάκοποι, οἱ δὲ Παλλάντιοι θεοῦ σφᾶς ἀποτρέποντος ἀνεχώρουν. καὶ τάδε μὲν ἦν περὶ Αἰμίλιον.", "st": "7.82"}, {"sp": "N", "t": "Ῥωμαῖοι δ’ αὐτὰ πυθόμενοι τὸν μὲν Αἰμίλιον. παρέλυσαν τῆς στρατηγίας τε καὶ ὑπατείας, καὶ ἰδιώτης ἐς Ῥώμην ὑπέστρεφε, καὶ χρήμασιν ἐπεζημιοῦτο· Μαγκίνῳ δ’ ἐδίκαζον καὶ τοῖς πρέσβεσι τοῖς Νομαντίνων. οἱ μὲν δὴ τὰς συνθήκας, ἃς ἐπεποίηντο πρὸς Μαγκῖνον, ἐπεδείκνυον· ὁ δὲ τὴν αἰτίαν αὐτῶν ἐς Πομπήιον ἀνέφερε τὸν πρὸ αὐτοῦ γενόμενον στρατηγόν, ὡς ἀργὸν καὶ ἄπορον τὸν στρατὸν ἐγχειρίσαντά οἱ, καὶ δι’ αὐτὸ κἀκεῖνον ἡσσημένον τε πολλάκις καὶ συνθήκας ὁμοίας αὐτῷ θέμενον πρὸς τοὺς Νομαντίνους· ὅθεν ἔφη καὶ τὸν πόλεμον τόνδε, παρὰ τὰς συνθήκας ἐκείνας ὑπὸ Ῥωμαίων ἐψηφισμένον, ἀπαίσιον αὐτοῖς γεγονέναι. οἱ δ’ ἐχαλέπαινον μὲν ἀμφοτέροις ὁμοίως, ἀπέφυγε δ’ ὅμως Πομπήιος ὡς περὶ τῶνδε κριθεὶς καὶ πάλαι. Μαγκῖνον δ’ ἔγνωσαν ἐκδοῦναι τοῖς Νομαντίνοις, ἄνευ σφῶν αἰσχρὰς συνθήκας πεποιημένον, ᾧ λόγῳ καὶ Σαυνίταις οἱ πατέρες, ὅμοια χωρὶς αὐτῶν συνθεμένους, ἡγεμόνας εἴκοσιν ἐξεδεδώκεσαν. Μαγκῖνον μὲν δὴ Φούριος ἀγαγὼν ἐς Ἰβηρίαν γυμνὸν παρεδίδου τοῖς Νομαντίνοις· οἱ δὲ οὐκ ἐδέξαντο. στρατηγὸς δὲ ἐπ’ αὐτοὺς αἱρεθεὶς Καλπούρνιος Πίσων οὐδ’ ἤλασεν ἐπὶ Νομαντίαν, ἀλλ’ ἐς τὴν Παλλαντίων γῆν ἐσβαλών, καὶ μικρὰ δῃώσας, ἐχείμαζεν ἐν Καρπητανίᾳ τὸ ἐπίλοιπον τῆς ἀρχῆς.", "st": "7.83"}, {"sp": "N", "t": "ἐν δὲ Ῥώμῃ κάμνων ὁ δῆμος ἐπὶ τοῖς Νομαντίνοις, μακροῦ καὶ δυσχεροῦς τοῦ πολέμου σφίσι παρὰ προσδοκίαν γεγονότος, ᾑροῦντο Κορνήλιον Σκιπίωνα τὸν Καρχηδόνα ἑλόντα αὖθις ὑπατεύειν, ὡς μόνον ἐπικρατῆσαι τῶν Νομαντίνων δυνάμενον. ὁ δὲ καὶ τότε ἦν ἔτι νεώτερος τῆς νενομισμένης τοῖς ὑπατεύουσιν ἡλικίας· ἡ οὖν βουλὴ πάλιν, ὥσπερ ἐπὶ Καρχηδονίοις αὐτοῦ χειροτονουμένου Σκιπίωνος, ἐψηφίσατο τοὺς δημάρχους λῦσαι τὸν περὶ τῆς ἡλικίας νόμον, καὶ τοῦ ἐπιόντος ἔτους αὖθις θέσθαι. οὕτω μὲν ὁ Σκιπίων αὖθις ὑπατεύων ἐς Νομαντίαν ἠπείγετο, στρατιὰν δ’ ἐκ καταλόγου μὲν οὐκ ἔλαβε πολλῶν τε πολέμων ὄντων καὶ πολλῶν ἀνδρῶν ἐν Ἰβηρίᾳ, ἐθελοντὰς δέ τινας, ἔκ τε πόλεων καὶ βασιλέων ἐς χάριν ἰδίαν πεμφθέντας αὐτῷ, συγχωρούσης τῆς βουλῆς ἐπηγάγετο, καὶ πελάτας ἐκ Ῥώμης καὶ φίλους πεντακοσίους, οὓς ἐς ἴλην καταλέξας ἐκάλει φίλων ἴλην. πάντας δὲ ἐς τετρακισχιλίους γενομένους παραδοὺς ἄγειν ἀδελφιδῷ Βουτέωνι, σὺν ὀλίγοις αὐτὸς προεξώρμησεν ἐς Ἰβηρίαν ἐπὶ τὸ στρατόπεδον, πυνθανόμενος αὐτὸ γέμειν ἀργίας καὶ στάσεων καὶ τρυφῆς, εὖ εἰδὼς ὅτι μὴ κρατήσει πολεμίων πρὶν κατασχεῖν τῶν ἰδίων ἐγκρατῶς.", "st": "7.84"}, {"sp": "N", "t": "ἐλθὼν δὲ ἐμπόρους τε πάντας ἐξήλαυνε καὶ ἑταίρας καὶ μάντεις καὶ θύτας, οἷς διὰ τὰς δυσπραξίας οἱ στρατιῶται περιδεεῖς γεγονότες ἐχρῶντο συνεχῶς· ἔς τε τὸ μέλλον ἀπεῖπε μηδὲν ἐσφέρεσθαι τῶν περισσῶν, μηδὲ ἱερεῖον ἐς μαντείαν πεποιημένον. ἐκέλευσε δὲ καὶ τὰς ἁμάξας καὶ τὰ περισσὰ τῶν ἐς αὐτὰς τιθεμένων καὶ τὰ ὑποζύγια, χωρὶς ὧν αὐτὸς ὑπελείπετο, πραθῆναι. καὶ σκεῦος οὐκ ἐξῆν ἐς δίαιταν ἔχειν οὐδενὶ πλὴν ὀβελοῦ καὶ χύτρας χαλκῆς καὶ ἐκπώματός ἑνός. τά τε σιτία αὐτοῖς ὥριστο κρέα ζεστὰ καὶ ὀπτὰ εἶναι. κλίνας τε ἀπεῖπεν ἔχειν, καὶ πρῶτος ἐπὶ στιβάδων ἀνεπαύετο. ἀπεῖπε δὲ καὶ ὁδεύοντας ἡμιόνοις ἐπικαθέζεσθαι· τί γὰρ ἐν πολέμῳ προσδοκᾶν ἔφη παρ’ ἀνδρὸς οὐδὲ βαδίζειν δυναμένου; κἀν τοῖς ἀλείμμασι καὶ λουτροῖς ἑαυτοὺς ἤλειφον, ἐπισκώπτοντος τοῦ Σκιπίωνος ὡς αἱ ἡμίονοι χεῖρας οὐκ ἔχουσαι χρῄζουσι τριβόντων. οὕτω μὲν αὐτοὺς ἐς σωφροσύνην μετέβαλλεν ἀθρόως, εἴθιζε δὲ καὶ ἐς αἰδῶ καὶ φόβον, δυσπρόσιτος ὢν καὶ δυσχερὴς ἐς τὰς χάριτας, καὶ μάλιστα τὰς παρανόμους. ἔλεγέ τε πολλάκις τοὺς μὲν αὐστηροὺς καὶ ἐννόμους τῶν στρατηγῶν τοῖς οἰκείοις, τοὺς δὲ εὐχερεῖς καὶ φιλοδώρους τοῖς πολεμίοις εἶναι χρησίμους· τὰ γὰρ στρατόπεδα τοῖς μὲν εἶναι κεχαρισμένα τε καὶ καταφρονητικά, τοῖς δὲ σκυθρωπὰ μὲν εὐπειθῆ δὲ καὶ πᾶσιν ἕτοιμα.", "st": "7.85"}, {"sp": "N", "t": "οὐ μὴν οὐδ’ ὣς ἐτόλμα πολεμεῖν πρὶν αὐτοὺς γυμνάσαι πόνοις πολλοῖς. τὰ οὖν ἀγχοτάτω πεδία πάντα περιιών, ἑκάστης ἡμέρας, ἄλλο μετ’ ἄλλο στρατόπεδον ἤγειρέ τε καὶ καθῄρει, καὶ τάφρους ὤρυσσε βαθυτάτας καὶ ἐνεπίμπλη, τείχη τε μεγάλα ᾠκοδόμει καὶ κατέφερεν, αὐτὸς ἐξ ἠοῦς ἐς ἑσπέραν ἅπαντα ἐφορῶν. τὰς δὲ ὁδοιπορίας, ἵνα μή τις ὡς πάλαι διασκιδνῷτο, ἦγεν ἐν πλινθίοις ἀεί, καὶ τὴν δεδομένην ἑκάστῳ τάξιν οὐκ ἦν ἐναλλάξαι. περιιών τε τὴν ὁδοιπορίαν, καὶ τὰ πολλὰ οὐραγῶν, τοὺς μὲν ἀρρωστοῦντας ἐπὶ τοὺς ἵππους ἀνεβίβαζεν ἀντὶ τῶν ἱππέων, τὰ δὲ βαροῦντα τὰς ἡμιόνους ἐς τοὺς πεζοὺς διεμέριζεν. εἰ δὲ σταθμεύοι, τοὺς μὲν προφύλακας τῆς ἡμέρας ἐκ τῆς ὁδοιπορίας ἔδει περὶ τὸν χάρακα ἵστασθαι, καὶ ἱππέων ἑτέραν ἴλην περιτρέχειν· οἱ δ’ ἄλλοι τὰ ἔργα διῄρηντο, καὶ τοῖς μὲν ταφρεύειν ἐτέτακτο, τοῖς δὲ τειχίζειν, τοῖς δὲ σκηνοποιεῖν, χρόνου τε μῆκος ὡρίζετο αὐτοῖς καὶ διεμετρεῖτο.", "st": "7.86"}, {"sp": "N", "t": "ὅτε δ’ εἴκασεν ὀξὺ καὶ εὐπειθὲς αὐτῷ καὶ φερέπονον γεγονέναι τὸ στράτευμα, μετέβαινεν ἀγχοῦ τῶν Νομαντίνων. προφυλακὰς δέ, ὥσπερ τινές, ἐπὶ φρουρίων οὐκ ἐποιεῖτο· οὐδὲ διῄρει ποι τὸν στρατὸν ὅλως, τοῦ μὴ τινὸς ἐν ἀρχῇ γενομένου πταίσματος εὐκαταφρόνητον τοῖς πολεμίοις αὐτὸν γενέσθαι, καὶ τέως καταφρονοῦσιν. οὐδ’ ἐπεχείρει τοῖς ἐχθροῖς, ἔτι περισκοπῶν αὐτόν τε τὸν πόλεμον καὶ τὸν καιρὸν αὐτοῦ καὶ τὴν τῶν Νομαντίνων ὁρμήν, ἐς ὅ τι τρέψοιντο. τὰ δὲ ὀπίσω τοῦ στρατοπέδου πάντα ἐχορτολόγει, καὶ τὸν σῖτον ἔκειρεν ἔτι χλωρόν. ὡς δ’ αὐτῷ ταῦτα ἐξετεθέριστο καὶ ἐς τὸ πρόσθεν ἔδει βαδίζειν, ὁδὸς μὲν ἦν παρὰ τὴν Νομαντίαν ἐπὶ τὰ πεδία σύντομος, καὶ πολλοὶ συνεβούλευον ἐς αὐτὴν τραπέσθαι. ὁ δ’ ἔφη τὴν ἐπάνοδον δεδιέναι, κούφων μὲν τότε τῶν πολεμίων ὄντων, καὶ ἐκ πόλεως ὁρμωμένων καὶ ἐς πόλιν ἀφορμώντων· “οἱ δ’ ἡμέτεροι βαρεῖς ἐπανίασιν ὡς ἀπὸ σιτολογίας καὶ κατάκοποι, καὶ κτήνη καὶ ἁμάξας καὶ φορτία ἄγουσιν. δυσχερής τε ὅλως καὶ ἀνόμοιος ὁ ἀγών· ἡσσωμένοις μὲν γὰρ πολὺς ὁ κίνδυνος, νικῶσι δὲ οὐ μέγα τὸ ἔργον, οὐδ’ ἐπικερδές.” εἶναι δ’ ἄλογον κινδυνεύειν ἐπὶ ὀλίγοις, καὶ στρατηγὸν ἀμελῆ τὸν ἀγωνιζόμενον πρὸ τῆς χρείας, ἀγαθὸν δὲ τὸν ἐν μόναις παρακινδυνεύοντα ταῖς ἀνάγκαις. συγκρίνων δ’ ἔφη καὶ τοὺς ἰατροὺς μὴ χρῆσθαι τομαῖς μηδὲ καύσεσι πρὸ φαρμάκων. ταῦτ’ εἰπὼν ἐκέλευε τοῖς ἡγεμόσι τὴν μακροτέραν περιάγειν. καὶ συνεξῄει τότε μὲν ἐς τὸ πέραν τοῦ στρατοπέδου, ὕστερον δὲ ἐς τὰ Οὐακκαίων, ὅθεν οἱ Νομαντῖνοι τὰς τροφὰς ἐωνοῦντο, κείρων ἅπαντα, καὶ τὰ χρήσιμα ἐς τὰς ἑαυτοῦ τροφὰς συλλέγων, τὰ δὲ περιττὰ σωρεύων τε καὶ κατακαίων.", "st": "7.87"}, {"sp": "N", "t": "ἐν δέ τινι πεδίῳ τῆς Παλλαντιας, ὄνομα Κοπλανίῳ, πολλοὺς ἐπὶ τῶν ὀρῶν ὑπὸ λόφοις ἔκρυψαν οἱ Παλλάντιοι, καὶ ἑτέροις ἐς τὸ φανερὸν τοὺς σιτολογοῦντας ἠνώχλουν. ὁ δὲ Ῥουτίλιον Ῥοῦφον, συγγραφέα τῶνδε τῶν ἔργων, τότε χιλιαρχοῦντα, ἐκέλευσε τέσσαρας ἱππέων ἴλας λαβόντα ἀναστεῖλαι τοὺς ἐνοχλοῦντας. Ῥοῦφος μὲν οὖν ὑποχωροῦσιν αὐτοῖς ἀμέτρως εἵπετο, καὶ φεύγουσιν ἐς τὸν λόφον συνανεπήδα, ἔνθα τῆς ἐνέδρας ἐκφανείσης ἐκέλευε τοὺς ἱππέας μήτε διώκειν μήτε ἐπιχειρεῖν ἔτι, ἀλλ’ ἐν προβολῇ τὰ δόρατα θεμένους ἑστάναι καὶ ἐπιόντας ἀμύνεσθαι μόνον. ὁ δὲ Σκιπίων εὐθὺ ἀνατρέχοντος αὐτοῦ παρὰ τὸ πρόσταγμα δείσας εἵπετο κατὰ σπουδήν, καὶ ὡς ηὗρε τὴν ἐνέδραν, ἐς δύο διεῖλε τοὺς ἱππέας, καὶ προσέταξεν αὐτῶν ἑκατέροις παρὰ μέρος ἐμπηδᾶν τοῖς πολεμίοις, καὶ ἀκοντίσαντας ὁμοῦ πάντας εὐθὺς ἀναχωρεῖν, οὐκ ἐς τὸν αὐτὸν τόπον, ἀλλ’ ἀεὶ κατ’ ὀλίγον προστιθέντας ὀπίσω καὶ ὑποχωροῦντας. οὕτω μὲν τοὺς ἱππέας ἐς τὸ πεδίον περιέσωσεν· ἀναζευγνύοντι δ’ αὐτῷ καὶ ἀναχωροῦντι ποταμὸς ἦν ἐν μέσῳ δύσπορός τε καὶ ἰλυώδης, καὶ παρ’ αὐτὸν ἐνήδρευον οἱ πολέμιοι. ὁ δὲ μαθὼν ἐξέκλινε τῆς ὁδοῦ, καὶ μακροτέραν ἦγε καὶ δυσενέδρευτον, νυκτός τε ὁδεύων διὰ τὸ δίψος καὶ φρέατα ὀρύσσων, ὧν τὰ πλέονα πικρὰ ηὑρίσκετο. τοὺς μὲν οὖν ἄνδρας ἐπιμόχθως περιέσωσεν, ἵπποι δέ τινες αὐτοῦ καὶ ὑποζύγια ὑπὸ τῆς δίψης ἀπώλοντο.", "st": "7.88"}, {"sp": "N", "t": "καὶ Καυκαίους δὲ παροδεύων, ἐς οὓς παρεσπόνδησε Λεύκολλος, ἐκήρυξε Καυκαίους ἐπὶ τὰ ἑαυτῶν ἀκινδύνως κατέρχεσθαι. καὶ παρῆλθεν ἐς τὴν Νομαντίνην χειμάσων, ἔνθα αὐτῷ καὶ Ἰογόρθας ἐκ Λιβύης ἀφίκετο, ὁ Μασσανάσσου υἱωνός, ἄγων ἐλέφαντας δυοκαίδεκα καὶ τοὺς συντασσομένους αὐτοῖς τοξότας τε καὶ σφενδονήτας. ἀεὶ δέ τι δῃῶν, καὶ τὰ περικείμενα πορθῶν, ἔλαθε περὶ κώμην ἐνεδρευθείς, ἣν ἐκ τοῦ πλέονος τέλμα πηλοῦ περιεῖχεν, ἐπὶ δὲ θάτερα φάραγξ ἦν, καὶ ἀφανὴς ἐν ἐκείνῃ λόχος ὑπεκρύπτετο. τῆς οὖν στρατιᾶς τῷ Σκιπίωνι διῃρημένης, οἱ μὲν τὴν κώμην ἐπόρθουν ἐσελθόντες, τὰ σημεῖα ἔξω καταλιπόντες, οἱ δὲ περιίππευον οὐ πολλοί. τούτοις οὖν ἐμπίπτουσιν οἱ λοχῶντες. καὶ οἱ μὲν αὐτοὺς ἀπεμάχοντο, ὁ δὲ Σκιπίων (ἔτυχε γὰρ πρὸ τῆς κώμης παρὰ τὰ σημεῖα ἑστώς) ἀνεκάλει τῇ σάλπιγγι τοὺς ἔνδον, καὶ πρὶν αὐτῷ γενέσθαι χιλίους, τοῖς ἱππεῦσιν ἐνοχλουμένοις ἐπεβοήθει. τοῦ δὲ στρατοῦ τοῦ πλέονος ἐκ τῆς κώμης ἐκδραμόντος, ἐτρέψατο μὲν ἐς φυγὴν τοὺς πολεμίους, οὐ μὴν ἐδίωκε φεύγοντας, ἀλλ’ ἐς τὸν χάρακα ἀνεχώρει πεσόντων ἑκατέρωθεν ὀλίγων.", "st": "7.89"}, {"sp": "N", "t": "μετ’ οὐ πολὺ δὲ ἀγχοτάτω τῆς Νομαντίας δύο στρατόπεδα θέμενος, τῷ μὲν ἐπέστησε τὸν ἀδελφὸν Μάξιμον, τοῦ δὲ αὐτὸς ἡγεῖτο. Νομαντίνων δὲ θαμινὰ ἐκτασσόντων καὶ προκαλουμένων αὐτὸν ἐς μάχην ὑπερεώρα, οὐ δοκιμάζων ἀνδράσιν ἐξ ἀπογνώσεως μαχομένοις συμπλέκεσθαι μᾶλλον ἢ συγκλείσας αὐτοὺς ἑλεῖν λιμῷ. φρούρια δ’ ἑπτὰ περιθείς, πολιορκίαν … ἐπιγράψας ἑκάστοις οὓς ἔδει πέμπειν. ὡς δὲ ἦλθον, ἐς μέρη πολλὰ διεῖλεν αὐτούς, καὶ τὴν ἑαυτοῦ στρατιὰν ἐπιδιεῖλεν· εἶθ’ ἡγεμόνας ἐπιστήσας ἑκάστῳ μέρει προσέταξε περιταφρεύειν καὶ περιχαρακοῦν τὴν πόλιν. ἦν δὲ ἡ περίοδος ἡ μὲν αὐτῆς Νομαντίας τέσσαρες καὶ εἴκοσι στάδιοι, ἡ δὲ τοῦ χαρακώματος ὑπὲρ τὸ διπλάσιον. καὶ τοῦτο διῄρητο πᾶν οἱ κατὰ μέρος ἕκαστον. καὶ προείρητο, εἴ τι ἐνοχλοῖεν οἱ πολέμιοι, σημεῖον ἐξαίρειν, ἡμέρας μὲν φοινικίδα ἐπὶ δόρατος ἱψηλοῦ, νυκτὸς δὲ πῦρ, ἵνα τοῖς δεομένοις ἐπιθέοντες αὐτός τε καὶ Μάξιμος ἀμύνοιεν. ὡς δ’ ἐξείργαστο πάντα αὐτῷ, καὶ τοὺς κωλύοντας εἶχεν ἱκανῶς ἀπομάχεσθαι, ἑτέραν τάφρον ὤρυσσεν οὐ μακρὰν ὑπὲρ ἐκείνην, καὶ σταυροὺς αὐτῇ περιεπήγνυ, καὶ τεῖχος ᾠκοδόμει, οὗ τὸ μὲν πάχος ἦν πόδες ὀκτώ, τὸ δὲ ὕψος δέκα χωρὶς τῶν ἐπάλξεων. πύργοι τε πανταχόθεν αὐτῷ διὰ πλέθρου περιέκειντο. καὶ λίμνην συνάπτουσαν οὐκ ἐνὸν περιτειχίσαι, χῶμα αὐτῇ περιέθηκεν ἴσον τῷ τείχει καὶ τὸ βάθος καὶ τὸ ὕψος, ὡς ἂν εἴη καὶ τόδε ἀντὶ τείχους.", "st": "7.90"}, {"sp": "N", "t": "οὕτω μὲν ὁ Σκιπίων ὅδε πρῶτος, ὡς ἐμοὶ δοκεῖ, περιετείχισε πόλιν οὐ φυγομαχοῦσαν· τόν τε Δόριον ποταμόν, συμφερόμενον τῷ περιτειχίσματι καὶ πολλὰ τοῖς Νομαντίνοις χρήσιμον ἔς τε ἀγορᾶς κομιδὴν καὶ διαπομπὴν ἀνδρῶν, ὅσοι κατ’ αὐτὸν κολυμβηταί τε καὶ σκάφεσι μικροῖς ἐλάνθανον, ἢ ἱστίοις, ὅτε λάβρον εἴη τὸ πνεῦμα, ἐβιάζοντο, ἢ κώπαις κατὰ τὸ ῥεῦμα, ζεῦξαι μὲν οὐκ ἐδύνατο πλατὺν ὄντα καὶ πάνυ ῥοώδη, φρούρια δὲ ἀντὶ γεφύρας αὐτῷ δύο περιθεὶς ἀπήρτησε καλῳδίοις δοκοὺς μακρὰς ἐξ ἑκατέρου φρουρίου, καὶ ἐς τὸ πλάτος τοῦ ποταμοῦ μεθῆκεν, ἐχούσας ἐμπεπηγότα πυκνὰ ξίφη τε καὶ ἀκόντια. αἱ δ’ ὑπὸ τοῦ ῥοῦ, τοῖς ξίφεσι καὶ τοῖς ἀκοντίοις ἐμπίπτοντος, ἀεὶ περιστρεφόμεναι οὔτε διανηχομένους οὔτ’ ἐπιπλέοντας οὔτε ὑποδύνοντας εἴων λαθεῖν. τοῦτο δ’ ἦν οὗ μάλιστα ὁ Σκιπίων ἐπεθύμει, μηδενὸς αὐτοῖς ἐπιμιγνυμένου μηδ’ ἐσιόντος ἀγνοεῖν αὐτοὺς ὅ τι γίγνοιτο ἔξω· οὕτω γὰρ ἀπορήσειν ἀγορᾶς τε καὶ μηχανῆς πάσης.", "st": "7.91"}, {"sp": "N", "t": "ὡς δ’ ἡτοίμαστο πάντα, καὶ καταπέλται μὲν ἐπέκειντο τοῖς πύργοις ὀξυβελεῖς τε καὶ λιθοβόλοι, ταῖς δ’ ἐπάλξεσι παρέκειντο λίθοι καὶ βέλη καὶ ἀκόντια, τὰ δὲ φρούρια τοξόται καὶ σφενδονῆται κατεῖχον, ἀγγέλους μὲν ἐπέστησε πυκνοὺς κατὰ τὸ ἐπιτείχισμα πᾶν, οἳ νυκτός τε καὶ ἡμέρας ἔμελλον ἄλλοι παρ’ ἄλλων τὸν λόγον ἐκδεχόμενοι μηνύσειν αὐτῷ τὰ γιγνόμενα, κατὰ δὲ πύργον ἐκέλευσεν, εἴ τι γίγνοιτο, σημεῖον ἐκ πρώτου τοῦ πονοῦντος αἴρεσθαι, καὶ τὸ αὐτὸ πάντας ἐπαίρειν ὅταν τὸν ἀρξάμενον θεάσωνται, ἵνα τὸ μὲν κίνημα παρὰ τοῦ σημείου θᾶσσον ἐπιγιγνώσκοι, τὸ δὲ ἀκριβὲς παρὰ τῶν ἀγγέλων. τῆς δὲ στρατιᾶς οὔσης σὺν τοῖς ἐπιχωρίοις ἐς ἑξακισμυρίους, τὸ μὲν ἥμισυ διετέτακτο αὐτῷ τειχοφυλακεῖν, καὶ ἐς τὰ ἀναγκαῖα, εἴ πῃ δεήσειε, μεταχωρεῖν, δισμύριοι δὲ τειχομαχήσειν ἔμελλον, ὅτε χρεία γένοιτο, καὶ τούτοις ἐφεδρεύειν ἕτεροι μύριοι. χωρίον δὲ καὶ τούτων ἑκάστοις διετέτακτο· καὶ μεταπηδᾶν, εἰ μὴ κελεύσειεν, οὐκ ἐξῆν. ἐς δὲ τὸ τεταγμένον εὐθὺς ἀνεπήδων, ὅτε τι σημεῖον ἐπιχειρήσεως ἐπαρθείη.", "st": "7.92"}, {"sp": "N", "t": "οὕτω μὲν τῷ Σκιπίωνι πάντα ἀκριβῶς διετέτακτο·", "st": "7.92"}, {"sp": "N", "t": "οἱ δὲ Νομαντῖνοι πολλάκις μὲν τοῖς φυλάσσουσιν ἐπεχείρουν, ἄλλοτε ἄλλῃ κατὰ μέρη, ταχεῖα δ’ αὐτίκα καὶ καταπληκτικὴ τῶν ἀμυνομένων ἡ ὄψις ἦν, σημείων τε ὑψηλῶν πανταχόθεν αἰρομένων καὶ ἀγγέλων διαθεόντων, καὶ τῶν τειχομάχων ἀθρόως ἀναπηδώντων ἐς τὰ τείχη, σαλπικτῶν τε κατὰ πάντα πύργον ἐξοτρυνόντων, ὥστε τὸν κύκλον ὅλον εὐθὺς ἅπασιν εἶναι φοβερώτατον, ἐς πεντήκοντα σταδίους ἐπέχοντα ἐν περιόδῳ. καὶ τόνδε τὸν κύκλον ὁ Σκιπίων ἑκάστης ἡμέρας τε καὶ νυκτὸς ἐπισκοπῶν περιῄει.", "st": "7.93"}, {"sp": "N", "t": "ὁ μὲν δὴ τοὺς πολεμίους ὧδε συγκλείσας οὐκ ἐς πολὺ ἀρκέσειν ἐνόμιζεν, οὔτε τροφῆς ἔτι προσιούσης σφίσιν οὔτε ὅπλων οὔτ’ ἐπικουρίας·", "st": "7.93"}, {"sp": "N", "t": "Ῥητογένης δέ, ἀνὴρ Νομαντῖνος, ᾧ Καραύνιος ἐπίκλησις ἦν, ἄριστος ἐς ἀρετὴν Νομαντίνων, πέντε πείσας φίλους, σὺν παισὶν ἄλλοις τοσοῖσδε καὶ ἵπποις τοσοῖσδε ἐν νυκτὶ συννεφεῖ διῆλθε λαθὼν τὸ μεταίχμιον, κλίμακα φέρων πτυκτήν, καὶ φθάσας ἐς τὸ περιτείχισμα ἀνεπήδησεν αὐτός τε καὶ οἱ φίλοι, καὶ τοὺς ἑκατέρωθεν φύλακας ἀνελόντες τοὺς μὲν θεράποντας ἀπέπεμψαν ὀπίσω, τοὺς δ’ ἵππους διὰ τῆς κλίμακος ἀναγαγόντες ἐξίππευσαν ἐς τὰς Ἀρουακῶν πόλεις σὺν ἱκετηρίαις, δεόμενοι Νομαντίνοις συγγενέσιν οὖσιν ἐπικουρεῖν. τῶν δ’ Ἀρουακῶν οἱ μὲν οὐδ’ ὑπήκουον αὐτῶν, ἀλλ’ εὐθὺς ἀπέπεμπον δεδιότες. Λουτία δὲ πόλις ἦν εὐδαίμων, τριακοσίους σταδίους ἀφεστῶσα ἀπὸ Νομαντίνων, ἧς οἱ μὲν νέοι περὶ τοὺς Νομαντινους ἐσπουδάκεσαν καὶ τὴν πόλιν ἐς συμμαχίαν ἐνῆγον, οἱ πρεσβύτεροι δ’ ἐμήνυσαν κρύφα τῷ Σκιπίωνι. καὶ ὁ Σκιπίων ὀγδόης ὥρας πυθόμενος ἐξήλαυνεν αὐτίκα σὺν εὐζώνοις ὅτι πλείστοις, καὶ ἅμα ἕῳ τὴν Λουτίαν φρουρᾷ περιλαβὼν ᾔτει τοὺς ἐξάρχους τῶν νέων. ἐπεὶ δ’ ἐξωρμηκέναι τῆς πόλεως αὐτοὺς ἔλεγον, ἐκήρυξε διαρπάσειν τὴν πόλιν, εἰ μὴ τοὺς ἄνδρας παραλάβοι. οἱ μὲν δὴ δείσαντες προσῆγον αὐτούς, ἐς τετρακοσίους γενομένους· ὁ δὲ τὰς χεῖρας αὐτῶν ἐκτεμὼν ἀνέστησε τὴν φρουράν, καὶ διαδραμὼν αὖθις ἅμ’ ἕῳ τῆς ἐπιούσης παρῆν ἐς τὸ στρατόπεδον.", "st": "7.94"}, {"sp": "N", "t": "Νομαντῖνοι δὲ κάμνοντες ὑπὸ λιμοῦ πέντε ἄνδρας ἔπεμπον ἐς τὸν Σκιπίωνα, οἷς εἴρητο μαθεῖν εἰ μετριοπαθῶς σφίσι χρήσεται παραδοῦσιν αὑτούς. Αὔαρος δ’ αὐτῶν ἡγούμενος πολλὰ μὲν περὶ τῆς προαιρέσεως καὶ ἀνδρείας τῶν Νομαντίνων ἐσεμνολόγησε, καὶ ἐπεῖπεν ὡς οὐδὲ νῦν ἁμάρτοιεν, ὑπὲρ παίδων καὶ γυναικῶν καὶ ἐλευθερίας πατρίου κακοπαθοῦντες ἐς τοσόνδε κακοῦ. “διὸ καὶ μάλιστα,” εἶπεν, “ὦ Σκιπίων, ἄξιόν ἐστι σέ, τοσῆσδε ἀρετῆς γέμοντα, φείσασθαι γένους εὐψύχου τε καὶ ἀνδρικοῦ, καὶ προτεῖναι τὰ φιλανθρωπότερα τῶν κακῶν ἡμῖν, ἃ καὶ δυνησόμεθα ἐνεγκεῖν, ἄρτι πειρώμενοι μεταβολῆς. ὡς οὐκ ἐφ’ ἡμῖν ἔτι ἐστίν, ἀλλ’ ἐπὶ σοί, τὴν πόλιν ἢ παραλαβεῖν, εἰ τὰ μέτρια κελεύοις, ἢ μαχομένην ὑπεριδεῖν ἀπολέσθαι.” ὁ μὲν Αὔαρος ὧδε εἶπεν, ὁ δὲ Σκιπίων (ᾔσθετο γὰρ παρὰ τῶν αἰχμαλώτων τὰ ἔνδον) ἔφη δεῖν αὐτοὺς ἐγχειρίσαι τὰ κατὰ σφᾶς καὶ σὺν ὅπλοις παραδοῦναι τὴν πόλιν. ὧν ἀπαγγελθέντων οἱ Νομαντῖνοι, χαλεποὶ καὶ τέως ὄντες ὀργὴν ὑπ’ ἐλευθερίας ἀκράτου καὶ ἀηθείας ἐπιταγμάτων, τότε καὶ μᾶλλον ὑπὸ τῶν συμφορῶν ἠγριωμένοι τε καὶ ἀλλόκοτοι γεγονότες τὸν Αὔαρον καὶ τοὺς σὺν αὐτῷ πέντε πρέσβεις ἀπέκτειναν ὡς κακῶν ἀγγέλους καὶ τὸ σφέτερον ἀσφαλὲς ἴσως διῳκημένους παρὰ τῷ Σκιπίωνι.", "st": "7.95"}, {"sp": "N", "t": "μετὰ δ’ οὐ πολὺ πάντων αὐτοὺς τῶν ἐδεστῶν ἐπιλιπόντων, οὐ καρπὸν ἔχοντες, οὐ πρόβατον, οὐ πόαν, πρῶτα μέν, ὥσπερ τινὲς ἐν πολέμων ἀνάγκαις, δέρματα ἕψοντες ἐλιχμῶντο, ἐπιλιπόντων δ’ αὐτοὺς καὶ τῶν δερμάτων ἐσαρκοφάγουν ἕψοντες τὰ ἀνθρώπεια, πρῶτα μὲν τὰ τῶν ἀποθνησκόντων κοπτόμενα ἐν μαγειρείοις, ἐπὶ δ’ ἐκείνοις τῶν νοσούντων κατεφρόνουν, καὶ τοὺς ἀσθενεστέρους ἐβιάζοντο οἱ δυνατώτεροι. κακῶν τε οὐδὲν αὐτοῖς ἀπῆν, ἠγριωμένοις μὲν τὰς ψυχὰς ὑπὸ τῶν τροφῶν, τεθηριωμένοις δὲ τὰ σώματα ὑπὸ λιμοῦ καὶ λοιμοῦ καὶ κόμης καὶ χρόνου. οὕτω δ’ ἔχοντες αὑτοὺς ἐπέτρεπον τῷ Σκιπίωνι. ὁ δ’ ἐκέλευεν αὐτοὺς τῆς μὲν ἡμέρας ἐκείνης συνενεγκεῖν τὰ ὅπλα ἔνθα συνέταξε, τῆς δ’ ἐπιούσης προσελθεῖν ἐς ἕτερον χωρίον. οἱ δ’ ὑπερεβάλοντο τὴν ἡμέραν, ομολογήσαντες ὅτι πολλοὶ τῆς ἐλευθερίας ἔτι ἔχονται καὶ ἐθέλουσιν αὑτοὺς ἐξαγαγεῖν τοῦ βίου. τὴν οὖν ἡμέραν ᾔτουν ἐς τοῦ θανάτου τὴν διάθεσιν.", "st": "7.96"}, {"sp": "N", "t": "τοσόσδε ἔρως ἐλευθερίας καὶ ἀνδραγαθίας ἦν ἐν πόλει βαρβάρῳ τε καὶ σμικρᾷ. ἐς γὰρ ὀκτακισχιλίους ἐπ’ εἰρήνης γενόμενοι οἷα μὲν καὶ ὅσα Ῥωμαίους ἔδρασαν, οἵας δὲ συνθήκας αὐτοῖς ἔθεντο ἐπὶ ἴσῃ καὶ ὁμοίᾳ, οὐδέσι ταῦτα συνθέσθαι Ῥωμαίων ὑποστάντων, οἷον δ’ ὄντα τὸν τελευταῖον στρατηγόν, ἓξ μυριάσιν αὐτοὺς περικαθήμενον, προυκαλέσαντο πολλάκις ἐς μάχην. ὁ δὲ ἦν ἄρα στρατηγικώτερος αὐτῶν, ἐς χεῖρας οὐκ ἰὼν θηρίοις, ἀλλὰ τῷ λιμῷ σφᾶς κατεργαζόμενος, ἀμάχῳ κακῷ, ᾧ δὴ καὶ μόνῳ ληφθῆναί τε δυνατὸν ἦν ἄρα Νομαντίνους, καὶ ἐλήφθησαν μόνῳ.", "st": "7.97"}, {"sp": "N", "t": "ἐμοὶ μὲν δὴ ταῦτα περὶ Νομαντίνων εἰπεῖν ἐπῆλθεν, ἐς τὴν ὀλιγότητα αὐτῶν καὶ φερεπονίαν ἀφορῶντι, καὶ ἔργα πολλά, καὶ χρόνον ὅσον διεκαρτέρησαν· οἱ δὲ πρῶτα μὲν αὑτούς, οἱ βουλόμενοι, διεχρῶντο, ἕτερος ἑτέρως· οἱ λοιποὶ δ’ ἐξῄεσαν τρίτης ἡμέρας ἐς τὸ δεδομένον χωρίον, δυσόρατοί τε καὶ ἀλλόκοτοι πάμπαν ὀφθῆναι, οἷς τὰ μὲν σώματα ἦν ἀκάθαρτα καὶ τριχῶν καὶ ὀνύχων καὶ ῥύπου μεστά, ὠδώδεσαν δὲ χαλεπώτατον, καὶ ἐσθὴς αὐτοῖς ἐπέκειτο πιναρὰ καὶ ἥδε καὶ οὐχ ἧσσον δυσώδης. ἐφαίνοντο δὲ τοῖς πολεμίοις ἐλεεινοὶ μὲν ἀπὸ τῶνδε, φοβεροὶ δ’ ἀπὸ τῶν βλεμμάτων· ἔτι γὰρ αὐτοὺς ἐνεώρων ἔκ τε ὀργῆς καὶ λύπης καὶ πόνου καὶ συνειδότος ἀλληλοφαγίας.", "st": "7.97"}, {"sp": "N", "t": "ἐπιλεξάμενος δ’ αὐτῶν πεντήκοντα ὁ Σκιπίων ἐς θρίαμβον, τοὺς λοιποὺς ἀπέδοτο, καὶ τὴν πόλιν κατέσκαψε, δύο μὲν τάσδε πόλεις δυσμαχωτάτας ἑλὼν στρατηγὸς ὅδε Ῥωμαίων, Καρχηδόνα μὲν αὐτῶν Ῥωμαίων ψηφισαμένων διὰ μέγεθος πόλεως τε καὶ ἀρχῆς καὶ εὐκαιρίαν γῆς καὶ θαλάσσης, Νομαντίαν δὲ σμικράν τε καὶ ὀλιγάνθρωπον, οὔπω τι Ῥωμαίων περὶ αὐτῆς ἐγνωκότων, αὐτός, εἴτε συμφέρειν Ῥωμαίοις ἡγούμενος, εἴτε ἄκρος ὢν ὀργὴν καὶ φιλόνεικος ἐς τὰ λαμβανόμενα, εἴθ’ ὡς ἔνιοι νομίζουσι, τὴν δόξαν ἡγούμενος διώνυμον ἐπὶ τοῖς μεγάλοις γίγνεσθαι κακοῖς· καλοῦσι γοῦν αὐτὸν οἱ Ῥωμαῖοι μέχρι νῦν, ἀπὸ τῶν συμφορῶν ἃς ἐπέθηκε ταῖς πόλεσιν, Ἀφρικανόν τε καὶ Νομαντῖνον. τότε δὲ τὴν γῆν τὴν Νομαντίνων τοῖς ἐγγὺς οἰκοῦσι διελών, καὶ ταῖς ἄλλαις πόλεσι χρηματίσας, καὶ εἴ τι ἦν ὕποπτον, ἐπιπλήξας τε καὶ ζημιώσας χρήμασιν, ἀπέπλευσεν ἐπ’ οἴκου.", "st": "7.98"}, {"sp": "N", "t": "Ῥωμαῖοι δέ, ὡς ἔθος, ἐς τὰ προσειλημμένα τῆς Ἰβηρίας ἔπεμψαν ἀπὸ τῆς βουλῆς ἄνδρας δέκα τοὺς καταστησομένους αὐτὰ ἐς εἰρήνην, ὅσα Σκιπίων τε ἔλαβε καὶ Βροῦτος πρὸ τοῦ Σκιπίωνος ὑπηγάγετο ἢ ἐχειρώσατο. χρόνῳ δ’ ὕστερον, ἀποστάσεων ἄλλων ἐν Ἰβηρίᾳ γενομένων, Καλπούρνιος Πίσων στρατηγὸς ᾑρέθη. καὶ αὐτὸν διεδέξατο μὲν Σέρουιος Γάλβας, Κίμβρων δ’ ἐπιστρατευόντων τῇ Ἰταλίᾳ, καὶ Σικελίας πολεμουμένης τὸν δεύτερον δουλικὸν πόλεμον, στρατιὰν μὲν ἐς Ἰβηρίαν οὐκ ἔπεμπον ὑπ’ ἀσχολίας, πρέσβεις δὲ ἀπεστέλλον, οἳ τὸν πόλεμον ἔμελλον ὅπῃ δύναιντο καταθήσεσθαι. Κίμβρων δὲ ἐξελαθέντων, Τίτος Δείδιος ἐπελθὼν Ἀρουακῶν μὲν ἔκτεινεν ἐς δισμυρίους, Τερμησὸν δέ, μεγάλην πόλιν ἀεὶ δυσπειθῆ Ῥωμαίοις γενομένην, ἐξ ἐρυμνοῦ κατήγαγεν ἐς τὸ πεδίον, καὶ ἐκέλευσεν οἰκεῖν ἀτειχίστους. Κολένδαν δὲ προσκαθίσας ἐνάτῳ μηνὶ παρέλαβεν ἐγχειρίσασαν ἑαυτήν, καὶ τοὺς Κολενδέας ἅπαντας μετὰ παίδων καὶ γυναικῶν ἀπέδοτο.", "st": "7.99"}, {"sp": "N", "t": "πόλιν δ’ ἑτέραν τῆς Κολένδης πλησίον ᾤκουν μιγάδες Κελτιβήρων, οὓς Μᾶρκος Μάριος συμμαχήσαντας αὐτῷ κατὰ Λυσιτανῶν, τῆς βουλῆς ἐπιτρεπούσης, ᾠκίκει πρὸ πέντε ἐνιαυτῶν. ἐλῄστευον δ’ ἐξ ἀπορίας οὗτοι· καὶ κρίνας αὐτοὺς ὁ Δείδιος ἀνελεῖν, συνθεμένων αὐτῷ τῶν δέκα πρέσβεων ἔτι παρόντων, ἔφη τοῖς ἐπιφανέσιν αὐτῶν ἐθέλειν τὴν Κολενδέων χώραν αὐτοῖς προσορίσαι πενομένοις. ἀσπαζομένους δὲ ὁρῶν ἐκέλευε, τῷ δήμῳ ταῦτα μετενεγκόντας, ἥκειν μετὰ γυναικῶν καὶ παίδων τὴν χώραν μεριουμένους. ἐπεὶ δ’ ἀφίκοντο, προσέταξε τοὺς στρατιώτας ἐκ τοῦ χάρακος ἐξελθεῖν καὶ τοὺς ἐνεδρευομένους ἔσω παρελθεῖν ὡς ἀπογραψόμενος αὐτῶν ἔνδον τὸ πλῆθος, ἐν μέρει μὲν ἀνδρῶν ἐν μέρει δὲ παίδων καὶ γυναικῶν, ἵνα ἐπιγνοίη πόσην χώραν αὐτοῖς δέοι διελεῖν. ὡς δὲ παρῆλθον ἐς τὴν τάφρον καὶ τὸ χαράκωμα, περιστήσας αὐτοῖς τὸν στρατὸν ὁ Δείδιος ἔκτεινε πάντας. καὶ ἐπὶ τοῖσδε Δείδιος μὲν καὶ ἐθριάμβευσε, πάλιν δὲ τῶν Κελτιβήρων ἀποστάντων Φλάκκος ἐπιπεμφθεὶς ἔκτεινε δισμυρίους. ἐν δὲ Βελγήδῃ πόλει ὁ μὲν δῆμος ἐς ἀπόστασιν ὁρμῶν τὴν βουλὴν ὀκνοῦσαν ἐνέπρησεν αὐτῷ βουλευτηρίῳ, ὁ δὲ Φλάκκος ἐπελθὼν ἔκτεινε τοὺς αἰτίους.", "st": "7.100"}, {"sp": "N", "t": "τοσάδε μὲν ηὗρον ἄξια λόγου Ῥωμαίοις ἐς τότε πρὸς Ἴβηρας αὐτοὺς γενόμενα· χρόνῳ δ’ ὕστερον στασιαζόντων ἐν Ῥώμῃ Σύλλα τε καὶ Κίννα, καὶ ἐς ἐμφυλίους πολέμους καὶ στρατόπεδα κατὰ τῆς πατρίδος διῃρημένων, Κόιντος Σερτώριος, ἐκ τῆς Κίννα στάσεως αἱρεθεὶς τῆς Ἰβηρίας ἄρχειν, Ἰβηρίαν τε αὐτὴν ἐπανέστησε Ῥωμαίοις, καὶ πολὺν στρατὸν ἀγείρας, καὶ βουλὴν τῶν ἰδίων φίλων ἐς μίμημα τῆς συγκλήτου καταλέξας, ἤλαυνεν ἐς Ῥώμην ἐπὶ τόλμης καὶ φρονήματος λαμπροῦ, καὶ τἄλλα ὢν ἐς θρασύτητα περιώνυμος, ὥστε τὴν βουλὴν δείσασαν ἑλέσθαι τοὺς παρὰ σφίσιν ἐπὶ μεγίστης τότε δόξης στρατηγούς, Καικίλιόν τε Μέτελλον μετὰ πολλοῦ στρατοῦ καὶ Γναῖον Πομπήιον ἐπ’ ἐκείνῳ μεθ’ ἑτέρου στρατοῦ, ἵνα τὸν πόλεμον, ὅπῃ δύναιντο, ἐξωθοῖεν ἐκ τῆς Ἰταλίας ἐν διχοστασίᾳ τότε μάλιστα οὔσης. ἀλλὰ Σερτώριον μὲν τῶν στασιωτῶν τις αὐτοῦ Περπέρνας ἀνελὼν ἑαυτὸν ἐπὶ Σερτωρίῳ στρατηγὸν ἀπέφηνε τῆς ἀποστάσεως, Περπέρναν δ’ ἔκτεινε μάχῃ Πομπήιος, καὶ ὁ πόλεμος ὅδε, θορυβήσας δὴ τῷ φόβῳ μάλιστα Ῥωμαίους, διελύθη. τὸ δὲ ἀκριβὲς αὐτοῦ δηλώσει τὰ περὶ Σύλλαν ἐμφύλια.", "st": "7.101"}, {"sp": "N", "t": "μετὰ δὲ τὸν Σύλλα θάνατον Γάιος Καῖσαρ αἱρεθεὶς Ἰβηρίας στρατηγεῖν, ὥστε καὶ πολεμεῖν οἷς δεήσειεν, ὅσα τῶν Ἰβήρων ἐσαλεύετο ἢ Ῥωμαίοις ἔτι ἔλειπε, πολέμῳ συνηνάγκασε πάντα ὑπακούειν. καί τινα αὖθις ἀφιστάμενα Ὀκταούιος Καῖσαρ ὁ τοῦ Γάιου παῖς, ὁ Σεβαστὸς ἐπίκλην, ἐχειρώσατο. καὶ ἐξ ἐκείνου μοι δοκοῦσι Ῥωμαῖοι τὴν Ἰβηρίαν, ἣν δὴ νῦν Ἱσπανίαν καλοῦσιν, ἐς τρία διαιρεῖν καὶ στρατηγοὺς ἐπιπέμπειν, ἐτησίους μὲν ἐς τὰ δύο ἡ βουλή, τὸν δὲ τρίτον βασιλεὺς ἐφ’ ὅσον δοκιμάσειεν.", "st": "7.102"}, {"sp": "HDR", "t": "Ἀννιβαϊκή", "st": "8"}, {"sp": "N", "t": "ὅσα δὲ Ἀννίβας ὁ Καρχηδόνιος ἐξ Ἰβηρίας ἐς Ἰταλίαν ἐσβαλών, ἑκκαίδεκα ἔτεσιν οἷς ἐπέμεινε πολεμῶν, ἔδρασέ τε καὶ ἔπαθεν ὑπὸ Ῥωμαίων, ἕως αὐτὸν Καρχηδόνιοί τε κινδυνεύοντες περὶ τῇ πόλει ἐπὶ τὰ σφέτερα μετεπέμψαντο καὶ Ῥωμαῖοι τῆς Ἰταλίας ἐξήλασαν, ἥδε ἡ γραφὴ δηλοῖ. ἥ τις δὲ τῷ Ἀννίβᾳ γέγονε τῆς ἐσβολῆς αἰτία τε ἀληθὴς καὶ πρόφασις ἐς τὸ φανερόν, ἀκριβέστατα μὲν ἐν τῇ Ἰβηρικῇ συγγραφῇ δεδήλωται, συγγράψω δὲ καὶ νῦν ὅσον ἐς ἀνάμνησιν.", "st": "8.1"}, {"sp": "N", "t": "Ἀμίλχαρ ᾧ Βάρκας ἐπικλησις ἦν, Ἀννίβου τοῦδε πατήρ, ἐστρατήγει Καρχηδονίων ἐν Σικελίᾳ, ὅτε Ῥωμαῖοι καὶ Καρχηδόνιοι περὶ αὐτῆς ἀλλήλοις ἐπολέμουν. δόξας δὲ πρᾶξαι κακῶς ὑπὸ τῶν ἐχθρῶν ἐδιώκετο, καὶ δεδιὼς ἔπραξεν ἐς τοὺς Νομάδας αἱρεθῆναι στρατηγὸς πρὸ τῶν εὐθυνῶν. γενόμενος δὲ χρήσιμος ἐν τῷδε, καὶ τὴν στρατιὰν θεραπεύσας ἁρπαγαῖς καὶ δωρεαῖς, ἤγαγεν ἄνευ τοῦ κοινοῦ Καρχηδονίων ἐπὶ Γάδειρα, καὶ ἐπέρασε τὸν πορθμὸν ἐς Ἰβηρίαν, ὅθεν λάφυρα πολλὰ διέπεμπεν ἐς Καρχηδόνα, θεραπεύων τὸ πλῆθος, εἰ δύναιτο μὴ χαλεπαίνειν αὐτῷ τῆς στρατηγίας τῆς ἐν Σικελίᾳ, χώραν δ’ αὐτοῦ κατακτωμένου πολλὴν κλέος τε μέγα ἦν, καὶ Καρχηδονίοις ἐπιθυμία πάσης Ἰβηρίας ὡς εὐμαροῦς ἔργου. Ζακανθαῖοι δέ, καὶ ὅσοι ἄλλοι Ἕλληνες ἐν Ἰβηρίᾳ, καταφεύγουσιν ἐπὶ Ῥωμαίους, καὶ γίγνεται Καρχηδονίοις ὅρος Ἰβηρίας, μὴ διαβαίνειν τὸν Ἴβηρα ποταμόν· καὶ τόδε ταῖς Ῥωμαίων καὶ Καρχηδονίων σπονδαῖς ἐνεγράφη. ἐπὶ δὲ τούτῳ Βάρκας μὲν τὴν ὑπὸ Καρχηδονίοις Ἰβηρίαν καθιστάμενος ἔν τινι μάχῃ πεσὼν ἀποθνήσκει, καὶ στρατηγὸς Ἀσδρούβας ἐπ’ αὐτῷ γίγνεται, ὃς ἐκήδευε τῷ Βάρκᾳ. καὶ τόνδε μὲν κτείνει θεράπων ἐν κυνηγεσίοις, οὗ τὸν δεσπότην ἀνῃρήκει.", "st": "8.2"}, {"sp": "N", "t": "τρίτος δὲ ἐπὶ τοῖσδε στρατηγὸς Ἰβήρων ὑπὸ τῆς στρατιᾶς ἀποδείκνυται, φιλοπόλεμος καὶ συνετὸς εἶναι δοκῶν, Ἀννίβας ὅδε, Βάρκα μὲν υἱὸς ὤν, Ἀσδρούβου δὲ τῆς γυναικὸς ἀδελφός, νέος δὲ κομιδῇ, καὶ ὡς μειράκιον ἔτι τῷ πατρὶ καὶ τῷ κηδεστῇ συνών. καὶ ὁ δῆμος ὁ Καρχηδονίων αὐτῷ τὴν στρατηγίαν ἐπεψήφισεν. οὕτω μὲν Ἀννίβας, περὶ οὗ τάδε συγγράφω, γίγνεται στρατηγὸς Καρχηδονίων ἐπ’ Ἴβηρσι· τῶν δ’ ἐχθρῶν τῶν Βάρκα τε καὶ Ἀσδρούβου τοὺς φίλους τοὺς ἐκείνων διωκόντων, καὶ Ἀννίβου τοῦδε καταφρονούντων ὡς ἔτι νέου, ἀρχὴν εἶναι τοῦθ’ ὁ Ἀννίβας ἐφ’ ἑαυτὸν ἡγούμενος, καὶ νομίζων οἱ τὸ ἀσφαλὲς ἐκ τῶν τῆς πατρίδος φόβων περιέσεσθαι, ἐς πόλεμον αὐτοὺς μέγαν ἐμβαλεῖν ἐπενόει. ὑπολαβὼν δ’, ὥσπερ ἦν, τὸ Ῥωμαίοις ἐπιχειρῆσαι χρόνιόν τε Καρχηδονίοις ἔσεσθαι, καὶ μεγάλην αὐτῷ δόξαν, εἰ καὶ τύχοι πταίσας, τό γε ἐγχείρημα οἴσειν, λεγόμενος δὲ καὶ ὑπὸ τοῦ πατρὸς ἐπὶ βωμῶν ἔτι παῖς ὁρκωθῆναι Ῥωμαίοις ἐπιβουλεύων οὔ ποτ’ ἐκλείψειν, ἐπενόει παρὰ τὰς σπονδὰς τὸν Ἴβηρα διαβῆναι, καὶ παρεσκεύαζέ τινας ἐς πρόφασιν κατηγορεῖν Ζακανθαίων. γράφων τε ταῦτα συνεχῶς ἐς Καρχηδόνα, καὶ προστιθεὶς ὅτι Ῥωμαῖοι κρύφα τὴν Ἰβηρίαν αὐτῶν ἀφιστᾶσιν, ἔτυχε παρὰ Καρχηδονίων πράσσειν ὅ τι δοκιμάσειεν. ὁ μὲν δὴ τὸν Ἴβηρα διαβὰς τὴν Ζακανθαίων πόλιν ἡβηδὸν διέφθειρε, Ῥωμαίοις δὲ καὶ Καρχηδονίοις ἐπὶ τῷδε ἐλέλυντο αἱ σπονδαὶ αἱ γενόμεναι αὐτοῖς μετὰ τὸν πόλεμον τὸν ἐν Σικελίᾳ.", "st": "8.3"}, {"sp": "N", "t": "Ἀννίβας δὲ ὅσα μὲν αὐτὸς καὶ οἱ μετ’ αὐτὸν ἄλλοι Καρχηδονίων τε καὶ Ῥωμαίων στρατηγοὶ περὶ Ἰβηρίαν ἔπραξαν, ἡ Ἰβηρικὴ γραφὴ δηλοῖ· ἐπιλεξάμενος δὲ Κελτιβήρων τε καὶ Λιβύων καὶ ἑτέρων ἐθνῶν ὅτι πλείστους, καὶ τὰ ἐν Ἰβηρίᾳ παραδοὺς Ἀσδρούβᾳ τῷ ἀδελφῷ, τὰ Πυρηναῖα ὄρη διέβαινεν ἐς τὴν Κελτικὴν τὴν νῦν λεγομένην Γαλατίαν, ἄγων πεζοὺς ἐνακισμυρίους καὶ ἱππέας ἐς δισχιλίους ἐπὶ μυρίοις καὶ ἐλέφαντας ἑπτὰ καὶ τριάκοντα. Γαλατῶν δὲ τοὺς μὲν ὠνούμενος, τοὺς δὲ πείθων, τοὺς δὲ καὶ βιαζόμενος, διώδευε τὴν χώραν. ἐλθὼν δὲ ἐπὶ τὰ Ἄλπεια ὄρη, καὶ μηδεμίαν μήτε δίοδον μήτε ἄνοδον εὑρών (ἀπόκρημνα γάρ ἐστιν ἰσχυρῶς), ἐπέβαινε κἀκείνοις ὑπὸ τόλμης, κακοπαθῶν χιονος τε πολλῆς οὔσης καὶ κρύους, τὴν μὲν ὕλην τέμνων τε καὶ κατακαίων, τὴν δὲ τέφραν σβεννὺς ὕδατι καὶ ὄξει, καὶ τὴν πέτραν ἐκ τοῦδε ψαφαρὰν γιγνομένην σφύραις σιδηραῖς θραύων, καὶ ὁδὸν ποιῶν ἣ καὶ νῦν ἐστιν ἐπὶ τῶν ὀρῶν ἐντριβὴς καὶ καλεῖται δίοδος Ἀννίβου. τῶν δὲ τροφῶν αὐτὸν ἐπιλειπουσῶν ἠπείγετο μέν, ἔτι λανθάνων ὅτι καὶ πάρεστιν ἐς τὴν Ἰταλίαν, ἕκτῳ δὲ μόλις ἀπὸ τῆς ἐξ Ἰβήρων ἀναστάσεως μηνί, πλείστους ἀποβαλών, ἐς τὸ πεδίον ἐκ τῶν ὀρῶν κατέβαινε.", "st": "8.4"}, {"sp": "N", "t": "καὶ μικρὸν ἀναπαύσας προσέβαλε Ταυρασίᾳ, πόλει Κελτικῇ. κατὰ κράτος δὲ αὐτὴν ἐξελών, τοὺς μὲν αἰχμαλώτους ἔσφαξεν ἐς κατάπληξιν τῆς ἄλλης Κελτικῆς, ἐπὶ δὲ ποταμὸν Ἠριδανὸν τὸν νῦν Πάδον λεγόμενον ἐλθών, ἔνθα Ῥωμαῖοι Κελτοῖς τοῖς καλουμένοις Βοιοῖς ἐπολέμουν, ἐστρατοπέδευσεν. ὁ δ’ ὕπατος ὁ Ῥωμαίων Πόπλιος Κορνήλιος Σκιπίων, Καρχηδονίοις ἐν Ἰβηρίᾳ πολεμῶν, ἐπεὶ τῆς ἐσβολῆς Ἀννίβου τῆς ἐς τὴν Ἰταλίαν ἐπύθετο, τὸν ἀδελφὸν καὶ ὅδε Γναῖον Κορνήλιον Σκιπίωνα ἐπὶ τοῖς ἐν Ἰβηρίᾳ πράγμασι καταλιπὼν διέπλευσεν ἐς Τυρρηνίαν, ὅθεν ὁδεύων τε καὶ συμμάχους ὅσους δύναιτο ἀγείρων ἔφθασεν ἐπὶ τὸν Πάδον Ἀννίβαν. καὶ Μάλλιον μὲν καὶ Ἀτίλιον, οἳ τοῖς Βοιοῖς ἐπολέμουν, ἐς Ῥώμην ἔπεμψεν ὡς οὐ δέον αὐτοὺς ἔτι στρατηγεῖ ὑπάτου παρόντος, αὐτὸς δὲ τὸν στρατὸν παραλαβὼν ἐς μάχην ἐξέτασσε πρὸς Ἀννίβαν. καὶ γενομένης ἀκροβολίας τε καὶ ἱππομαχίας, οἱ Ῥωμαῖοι κυκλωθέντες ὑπὸ τῶν Λιβύων ἔφευγον ἐς τὸ στρατόπεδον, καὶ νυκτὸς ἐπιγενομένης ἐς Πλακεντίαν ἀνεχώρουν ἀσφαλῶς τετειχισμένην, τὸν Πάδον ἐπὶ γεφυρῶν περάσαντές τε καὶ λύσαντες τὰς γεφύρας. τὸν μὲν οὖν ποταμὸν καὶ ὁ Ἀννίβας ζεύξας ἐπέρα,", "st": "8.5"}, {"sp": "N", "t": "τὸ δ’ ἔργον εὐθὺς τόδε, πρῶτον ἢ δεύτερον ἐπὶ τῇ τῶν Ἀλπείων ὀρῶν διαβάσει, παρὰ τοῖς ἐπέκεινα Κελτοῖς ἐξῇρε τὸν Ἀννίβαν ὡς ἄμαχον στρατηγὸν καὶ τύχῃ λαμπρᾷ χρώμενον. ὁ δέ, ὡς ἐν βαρβάροις τε καὶ τεθηπόσιν αὐτόν, καὶ δι’ ἄμφω δυναμένοις ἀπατᾶσθαι, τὴν ἐσθῆτα καὶ τὴν κόμην ἐνήλασσε συνεχῶς ἐσκευασμέναις ἐπινοίαις· καὶ αὐτὸν οἱ Κελτοὶ περιιόντα τὰ ἔθνη πρεσβύτην ὁρῶντες, εἶτα νέον, εἶτα μεσαιπόλιον, καὶ συνεχῶς ἕτερον ἐξ ἑτέρου, θαυμάζοντες ἐδόκουν θειοτέρας φύσεως λαχεῖν.", "st": "8.6"}, {"sp": "N", "t": "Σεμπρώνιος δ’ ὁ ἕτερος ὕπατος, ἐν Σικελίᾳ τότε ὢν καὶ πυθόμενος, διέπλευσε πρὸς τὸν Σκιπίωνα, καὶ τεσσαράκοντα σταδίους αὐτοῦ διασχὼν ἐστρατοπέδευσεν. καὶ τῆς ἐπιούσης ἔμελλον ἅπαντες ἐς μάχην ἥξειν. ποταμὸς δ’ ἦν ἐν μέσῳ Τρεβίας, ὃν Ῥωμαῖοι πρὸ ἕω, χειμερίου τε τῆς τροπῆς οὔσης καὶ ὑετοῦ καὶ κρύους, ἐπέρων βρεχόμενοι μέχρι τῶν μαστῶν. Ἀννίβας δὲ καὶ ἐς δευτέραν ὥραν ἀνέπαυσε τὴν στρατιάν, καὶ τότε ἐξῆγεν.", "st": "8.6"}, {"sp": "N", "t": "παράταξις δ’ ἦν ἑκατέρων … τὰ κέρατα κατεῖχον, ἀμφὶ τὴν φάλαγγα τῶν πεζῶν. Ἀννίβας δὲ τοῖς μὲν ἱππεῦσιν ἀντέταξε τοὺς ἐλέφαντας, τῇ δὲ φάλαγγι τοὺς πεζούς· τοὺς δὲ ἱππέας ἐκέλευσεν ὀπίσω τῶν ἐλεφάντων ἀτρεμεῖν ἕως αὐτός τι σημήνῃ. γενομένων δ’ ἐν χερσὶ πάντων, οἱ μὲν Ῥωμαίων ἵπποι τοὺς ἐλέφαντας, οὐ φέροντες αὐτῶν οὔτε τὴν ὄψιν οὔτε τὴν ὀδμήν, ἔφευγον· οἱ δὲ πεζοί, καίπερ ὑπὸ τοῦ κρύους καὶ τοῦ ποταμοῦ καὶ τῆς ἀγρυπνίας τετρυμένοι τε καὶ μαλακοὶ ὄντες, ὅμως ὑπὸ τόλμης τοῖς θηρίοις ἐπεπήδων καὶ ἐτίτρωσκον αὐτά, καὶ τινῶν καὶ τὰ νεῦρα ὑπέκοπτον, καὶ τοὺς πεζοὺς ἐνέκλινον ἤδη. θεασάμενος δ’ ὁ Ἀννίβας ἐσήμηνε τὴν ἵππον κυκλοῦσθαι τοὺς πολεμίους. ἐσκεδασμένων δ’ ἄρτι τῶν Ῥωμαϊκῶν ἱππέων διὰ τὰ θηρία καὶ τῶν πεζῶν μόνων τε ὄντων καὶ κακοπαθούντων καὶ δεδιότων τὴν περικύκλωσιν, φυγὴ πανταχόθεν ἦν ἐς τὰ στρατόπεδα. καὶ ἀπώλλυντο οἱ μὲν ὑπὸ τῶν ἱππέων καταλαμβανόντων ἅτε πεζούς, οἱ δὲ ὑπὸ τοῦ ποταμοῦ παραφέροντος· τοῦ γὰρ ἡλίου τὴν χιόνα τήξαντος ὁ ποταμὸς ἐρρύη μέγας, καὶ οὔτε στῆναι διὰ τὸ βάθος οὔτε νεῖν διὰ τὰ ὅπλα ἐδύναντο. Σκιπίων δὲ αὐτοῖς ἑπόμενος καὶ παρακαλῶν ὀλίγου μὲν ἐδέησε τρωθεὶς διαφθαρῆναι, μόλις δ’ ἐς Κρεμῶνα διεσώθη φερόμενος. ἐπίνειον δὲ ἦν τι βραχὺ Πλακεντίας, ᾧ προσβαλὼν ὁ Ἀννίβας ἀπώλεσε τετρακοσίους καὶ αὐτὸς ἐτρώθη. καὶ ἀπὸ τοῦδε πάντες ἐχείμαζον, Σκιπίων μὲν ἐν Κρεμῶνι καὶ Πλακεντίᾳ, Αννίβας δὲ περὶ Πάδον.", "st": "8.7"}, {"sp": "N", "t": "οἱ δ’ ἐν ἄστει Ῥωμαῖοι πυθόμενοι, καὶ τρίτον ἤδη πταίοντες περὶ Πάδον ἥττηντο γὰρ δὴ καὶ ὑπὸ Βοιῶν πρὸ Ἀννίβου), στρατιάν τε παρ’ αὑτῶν ἄλλην κατέλεγον, σὺν τοῖς οὖσι περὶ τὸν Πάδον ὡς εἶναι τρισκαίδεκα τέλη, καὶ τοῖς συμμάχοις ἑτέραν διπλασίονα ταύτης ἐπήγγελλον. ἤδη δὲ αὐτοῖς τὸ τέλος εἶχε πεζοὺς πεντακισχιλίους καὶ ἱππέας τριακοσίους. καὶ τούτων τοὺς μὲν ἐς Ἰβηρίαν ἔπεμπον, τοὺς δ’ ἐς Σαρδόνα κἀκείνην πολεμουμένην, τοὺς δ’ ἐς Σικελίαν. τὰ πλέονα δ’ ἦγον ἐπὶ τὸν Ἀννίβαν οἱ μετὰ Σκιπίωνα καὶ Σεμπρώνιον αἱρεθέντες ὕπατοι, Σερουίλιός τε Γναῖος καὶ Γάιος Φλαμίνιος. ὧν ὁ μὲν Σερουίλιος ἐπὶ τὸν Πάδον ἐπειχθεὶς τὴν στρατηγίαν ἐκδέχεται παρὰ τοῦ Σκιπίωνος (ὁ δὲ Σκιπίων ἀνθύπατος αἱρεθεὶς ἐς Ἰβηρίαν διέπλευσε), Φλαμίνιος δὲ τρισμυρίοις τε πεζοῖς καὶ τρισχιλίοις ἱππεῦσι τὴν ἐντὸς Ἀπεννίνων ὀρῶν Ἰταλίαν ἐφύλασσεν, ἣν καὶ μόνην ἄν τις εἴποι κυρίως Ἰταλίαν. τὰ γὰρ Ἀπεννῖνα κατέρχεται μὲν ἐκ μέσων τῶν Ἀλπείων ἐπὶ θάλασσαν, ἔστι δ’ αὐτῶν τὰ μὲν ἐπὶ δεξιὰ πάντα καθαρῶς Ἰταλία, τὰ δὲ ἐπὶ θάτερα ἐς τὸν Ἰόνιον φθάνοντα νῦν μέν ἐστι καὶ ταῦτα Ἰταλία, ὅτι καὶ Τυρρηνία νῦν Ἰταλία, οἰκοῦσι δ’ αὐτῶν τὰ μὲν Ἕλληνες, ἀμφὶ τὴν Ἰόνιον ἀκτήν, τὰ δὲ λοιπὰ Κελτοί, ὅσοι τῇ Ῥώμῃ τὸ πρῶτον ἐπιθέμενοι τὴν πόλιν ἐνέπρησαν. ὅτε γὰρ αὐτοὺς ἐξελαύνων Κάμιλλος ἐδίωκε μέχρι τῶν Ἀπεννίνων ὀρῶν, ἐμοὶ δοκοῦσιν ὑπερβάντες αὐτά, ἀντὶ ἠθῶν τῶν ἰδίων, παρὰ τὸν Ἰόνιον οἰκῆσαι· καὶ τὸ μέρος τῆς χώρας ἔτι νῦν οὕτω καλοῦσιν, Ἰταλίαν Γαλατικήν.", "st": "8.8"}, {"sp": "N", "t": "Ῥωμαῖοι μὲν δὴ μεγάλοις στρατοῖς ἐς πολλὰ ὁμοῦ διῄρηντο· Ἀννίβας δὲ τούτων αἰσθόμενος, ἅμα τῷ ἦρι, τοὺς ἄλλους λαθὼν ἐδῄου τὴν Τυρρηνίαν καὶ προύβαινεν ἐς τὸ μέρος τὸ ἐπὶ Ῥώμης. οἱ δὲ πλησιάζοντος αὐτοῦ πάνυ ἔδεισαν, οὐ παρούσης σφίσιν ἀξιομάχου δυνάμεως. ἐστράτευον δὲ ὅμως ἐκ τῶν ὑπολοίπων ὀκτακισχιλίους, καὶ Κεντήνιον αὐτοῖς τινὰ τῶν ἐπιφανῶν ἰδιωτῶν, οὐδεμιᾶς ἀρχῆς παρούσης, ἐπέστησάν τε καὶ ἐξέπεμπον ἐς Ὀμβρικοὺς ἐς τὴν Πλειστινην λίμνην, τὰ στενὰ προληψόμενον, ᾗ συντομώτατόν ἐστιν ἐπὶ τὴν Ῥώμην. ἐν δὲ τούτῳ καὶ Φλαμίνιος ὁ τοῖς τρισμυρίοις τὴν ἐντὸς Ἰταλίαν φυλάσσων, αἰσθόμενος τῆς σπουδῆς Ἀννίβου, μετέβαινεν ὀξέως, οὐ διαναπαύων τὴν στρατιάν. δέει τε περὶ τῆς πόλεως, καὶ αὐτὸς ὢν ἀπειροπόλεμός τε καὶ ἐς τὴν ἀρχὴν ἀπὸ δημοκοπίας ᾑρημένος, ἠπείγετο Ἀννίβᾳ συμπλεκῆναι.", "st": "8.9"}, {"sp": "N", "t": "ὁ δὲ αἰσθόμενος αὐτοῦ τῆς τε ὁρμῆς καὶ ἀπειρίας, ὄρος μέν τι καὶ λίμνην προυβάλετο πρὸ ἑαυτοῦ, ψιλοὺς δὲ καὶ ἱππέας ἐς φάραγγα ἀποκρύψας ἐστρατοπέδευεν. καὶ αὐτὸν ὁ Φλαμίνιος κατιδὼν ἅμα ἕῳ σμικρὸν μέν τι διέτριψε, τὸν στρατὸν ἀναπαύων ἐξ ὁδοιπορίας καὶ χαρακοποιούμενος, μετὰ δὲ τοῦτο ἐξῆγεν εὐθὺς ἐπὶ τὴν μάχην αὔους ὄντας ὑπ’ ἀγρυπνίας καὶ κόπου. τῆς δ’ ἐνέδρας ἐκφανείσης ἐν μέσῳ ληφθεὶς τοῦ τε ὄρους καὶ τῆς λίμνης καὶ τῶν ἐχθρῶν αὐτός τε ἀνῃρέθη καὶ σὺν αὐτῷ δισμύριοι. τοὺς δὲ λοιποὺς ἔτι μυρίους, ἔς τινα κώμην ὀχυρὰν συμφυγόντας, Μαάρβαλ ὁ ὑποστράτηγος Ἀννίβου, μεγίστην καὶ ὅδε ἐπὶ στρατηγίᾳ δόξαν ἔχων, οὐ δυνάμενος ἑλεῖν εὐχερῶς, οὐδὲ ἀξιῶν ἀπεγνωκόσι μάχεσθαι, ἔπεισε τὰ ὅπλα ἀποθέσθαι, συνθέμενος ἀπολύσειν ὅπῃ θέλοιεν. ὡς δὲ ἀπέθεντο, λαβὼν ἦγεν αὐτοὺς πρὸς τὸν Ἀννίβαν γυμνούς. ὁ δ’ οὐ φάμενος εἶναι κύριον χωρὶς αὑτοῦ ταῦτα συνθέσθαι τὸν Μαάρβαλ, τοὺς μὲν ἐκ τῶν συμμάχων φιλανθρωπευσάμενος ἀπέλυσεν ἐς τὰ ἑαυτῶν, θηρεύων τῇ φιλανθρωπίᾳ τὰς πόλεις, ὅσοι δὲ Ῥωμαίων ἦσαν, εἶχε δήσας. τὴν δὲ λείαν τοῖς συστρατεύουσι Κελτοῖς ἀποδόμενος, ἵνα καὶ τούσδε θεραπεύσειε τῷ κέρδει, προύβαινεν ἐς τὸ πρόσθεν, αἰσθομένου μὲν ἤδη τῶν γιγνομένων τοῦ περὶ Πάδον στρατηγοῦ Σερουιλίου, καὶ τετρακισμυρίοις ἐπὶ Τυρρηνίας ἐπειγομένου, Κεντηνίου δὲ ἤδη τοῖς ὀκτακισχιλίοις τὰ στενὰ προειληφότος.", "st": "8.10"}, {"sp": "N", "t": "Ἀννίβας δὲ ἐπειδὴ τήν τε λίμνην εἶδε τὴν Πλειστίνην καὶ τὸ ὄρος τὸ ὑπὲρ αὐτήν, καὶ τὸν Κεντήνιον ἐν μέσῳ κρατοῦντα τῆς διόδου, τοὺς ἡγεμόνας τῶν ὁδῶν ἐξήταζεν εἴ τις εἴη περίοδος. οὐδεμίαν δὲ φαμένων εἶναι τρίβον, ἀλλ’ ἀπόκρημνα πάντα καὶ φαραγγώδη, δι’ αὐτῶν ὅμως ἔπεμπε τοὺς ψιλοὺς νύκτωρ τὸ ὄρος περιιέναι, καὶ Μαάρβαλ μετ’ αὐτῶν. τεκμηράμενος δ’ ὅτε δύναιντο περιελθεῖν, προσέβαλε τῷ Κεντηνίῳ κατὰ μέτωπον. καὶ συνεστώτων ἑκατέρων, πάνυ προθύμως ὁ Μαάρβαλ ἐκ κορυφῆς ἄνωθεν ὤφθη τε καὶ ἠλάλαξεν. Ῥωμαίων δ’ εὐθὺς ἦν φυγὴ καὶ φόνος κεκυκλωμένων, καὶ τρισχίλιοι μὲν ἔπεσον ὀκτακόσιοι δ’ ἐλήφθησαν· οἱ δὲ λοιποὶ μόλις διέφυγον. πυθόμενοι δὲ οἱ ἐν ἄστει, καὶ δείσαντες μὴ εὐθὺς ἐπὶ τὴν πόλιν ὁ Ἀννίβας ἔλθοι, τό τε τεῖχος ἐπλήρουν λίθων καὶ τοὺς γέροντας ὥπλιζον, ὅπλων μὲν ἀποροῦντες, τὰ δὲ λάφυρα ἐκ τῶν ἱερῶν καταφέροντες, ἃ ἐκ πολέμων ἄλλων κόσμος αὐτοῖς περιέκειτο· δικτάτορά τε, ὡς ἐν κινδύνῳ, Φάβιον εἵλοντο Μάξιμον.", "st": "8.11"}, {"sp": "N", "t": "Ἀννίβας δέ, θεοῦ παράγοντος αὐτόν, ἐπὶ τὸν Ἰόνιον αὖθις ἐτράπη, καὶ τὴν παράλιον ὁδεύων ἐπόρθει, λείαν τε περιήλαυνε πολλήν. Σερουίλιος δ’ ὕπατος ἀντιπαριὼν αὐτῷ κατῇρεν ἐς Ἀρίμινον, ἀπέχων Ἀννίβου μίαν ἡμέραν· ἔνθα τὴν στρατιὰν συνεῖχε καὶ τοὺς ἔτι φίλους Κελτῶν ἀπεθάρρυνεν, ἕως ἀφικόμενος Φάβιος Μάξιμος ὁ δικτάτωρ Σερουίλιον μὲν ἐς Ῥώμην ἔπεμπεν ὡς οὔτε ὕπατον οὔτε στρατηγὸν ἔτι ὄντα δικτάτορος ᾑρημένου, αὐτὸς δὲ τῷ Ἀννίβᾳ παρακολουθῶν ἐς μὲν χεῖρας οὐκ ᾔει, πολλάκις ἐκείνου προκαλουμένου, πολιορκεῖν δ’ οὐδένα εἴα, παραφυλάσσων καὶ ἐπικείμενος. ὁ δέ, τῆς χώρας ἐξαναλωμένης, τροφῶν ἠπόρει, καὶ αὐτὴν αὖθις περιιὼν ἑκάστης ἡμέρας ἐξέτασσε, προκαλούμενος ἐς μάχην. Φάβιος δ’ οὐ συνεπλέκετο, καταγιγνώσκοντος αὐτοῦ Μινουκίου Ῥούφου, ὃς ἵππαρχος μὲν ἦν αὐτῷ, ἔγραφε δ’ ἐς Ῥώμην τοῖς φίλοις ὡς ὀκνοίη Φάβιος ὑπὸ δειλίας. διαδραμόντος δ’ ἐς Ῥώμην ἐπὶ θυσίας τινὰς τοῦ Φαβίου, ὁ Μινούκιος ἡγούμενος τοῦ στρατοῦ συνεπλέκη τινὰ μάχην τῷ Ἀννίβᾳ, καὶ δόξας πλέον ἔχειν θρασύτερον ἐς Ῥώμην ἐπέστελλε τῇ βουλῇ, τὸν Φάβιον αἰτιώμενος οὐκ ἐθέλοντα νικῆσαι. καὶ ἡ βουλή, ἐπανεληλυθότος ἐς τὸ στρατόπεδον ἤδη τοῦ Φαβίου, ἴσον ἰσχύειν αὐτῷ τὸν ἵππαρχον ἀπέφηνεν.", "st": "8.12"}, {"sp": "N", "t": "οἱ μὲν δὴ μερισάμενοι τὴν στρατιὰν πλησίον ἀλλήλων ἐστρατοπέδευον, καὶ τῆς γνώμης ἑκάτερος εἴχοντο τῆς ἑαυτοῦ, Φάβιος μὲν ἐκτρύχειν Ἀννίβαν τῷ χρόνῳ καὶ πειρᾶσθαι μηδὲν ὑπ’ αὐτοῦ παθεῖν, ὁ δὲ Μινούκιος μάχῃ διακριθῆναι. συνιόντος δὲ ἐς μάχην τοῦ Μινουκίου, Φάβιος τὸ μέλλον ἔσεσθαι προορῶν ἐν μέσῳ τὴν στρατιὰν ἀτρεμοῦσαν ἔστησε τὴν ἑαυτοῦ, καὶ τοὺς τοῦ Μινουκίου τραπέντας ἀνελάμβανε, τοὺς δ’ Ἀννίβου διώκοντας ἀπεκρούετο. καὶ Φάβιος μὲν ὧδε τὴν συμφορὰν ἐπεκούφισε τῷ Μινουκίῳ, οὐδὲν ἐπιμηνίσας τῆς διαβολῆς· ὁ δὲ Μινούκιος αὑτοῦ καταγνους ἀπειρίαν ἀπέθετο τὴν ἀρχήν, καὶ τὸ μέρος τοῦ στρατοῦ παρέδωκε τῷ Φαβίῳ, ἡγουμένῳ πρὸς ἄνδρα τεχνίτην μάχης ἕνα καιρὸν εἶναι τὴν ἀνάγκην. οὗ δὴ καὶ ὁ Σεβαστὸς ὕστερον πολλάκις ἐμέμνητο, οὐκ ὢν εὐχερὴς οὐδ’ οὗτος ἐς μάχας μᾶλλον τόλμῃ ἢ τέχνῃ χρῆσθαι. Φάβιος μὲν οὖν αὖθις ὁμοίως ἐφύλασσε τὸν Ἀννίβαν, καὶ τὴν χώραν πορθεῖν ἐκώλυεν, οὐ συμπλεκόμενος αὐτοῦ τῷ στρατῷ παντί, τοῖς δ’ ἀποσκιδναμένοις μόνοις ἐπιτιθέμενος, καὶ σαφῶς εἰδὼς ἀπορήσοντα τροφῶν αὐτίκα τὸν Ἀννίβαν.", "st": "8.13"}, {"sp": "N", "t": "στενῆς δὲ διόδου πλησιαζούσης, ὁ μὲν Ἀννίβας αὐτὴν οὐ προείδετο, Φάβιος δὲ προπέμψας τετρακισχιλίους κατέλαβε, καὶ τοῖς λοιποῖς αὐτὸς ἐπὶ θάτερα ἐστρατοπέδευεν ἐπὶ λόφου καρτεροῦ. ὁ δὲ Ἀννίβας ὡς ᾔσθετο ληφθεὶς ἐν μέσῳ Φαβίου τε καὶ τῶν στενῶν φυλασσομένων, ἔδεισε μὲν ὡς οὔ ποτε πρότερον· οὐ γὰρ εἶχε διέξοδον, ἀλλὰ πάντα ἦν ἀπόκρημνα καὶ δύσβατα, οὐδ’ ἤλπιζε Φάβιον ἢ τοὺς ἐπὶ τῶν στενῶν βιάσεσθαι διὰ τὴν τῶν χωρίων ὀχυρότητα. ὧδε δ’ ἔχων ἀπορίας τοὺς μὲν αἰχμαλώτους ἐς πεντακισχιλίους ὄντας κατέσφαξεν, ἵνα μὴ ἐν τῷ κινδύνῳ νεωτερίσειαν, βοῦς δὲ ὅσας εἶχεν ἐν τῷ στρατοπέδῳ (πολὺ δὲ πλῆθος ἦν), τοῖς κέρασιν αὐτῶν δᾷδας περιέθηκε, καὶ νυκτὸς ἐπιγενομένης τὰς δᾷδας ἐξάψας τὸ λοιπὸν ἐν τῷ στρατοπέδῳ πῦρ ἔσβεσε, καὶ σιγὴν βαθεῖαν ἔχειν παρήγγειλε, τοῖς δ’ εὐτολμοτάτοις τῶν νέων ἐκέλευσε τὰς βοῦς ἐλαύνειν μετὰ σπουδῆς ἄνω πρὸς τὰ ἀπόκρημνα, ἃ ἦν ἐν μέσῳ τοῦ τε Φαβίου καὶ τῶν στενῶν. αἱ δ’ ὑπό τε τῶν ἐλαυνόντων ἐπειγόμεναι, καὶ τοῦ πυρὸς ἐκκαίοντος αὐτάς, ἀνεπήδων ἐπὶ τοὺς κρημνοὺς ἀφειδῶς καὶ βιαίως, εἶτα κατέπιπτον καὶ αὖθις ἀνεπήδων.", "st": "8.14"}, {"sp": "N", "t": "Ῥωμαῖοι δὲ οἱ ἑκατέρωθεν, ὁρῶντες ἐν μὲν τῷ Ἀννίβου στρατοπέδῳ σιγὴν καὶ σκότον, ἐν δὲ τοῖς ὄρεσι πῦρ πολὺ καὶ ποικίλον, οὐκ ἔχοντες ὡς ἐν νυκτὶ τὸ γιγνόμενον ἀκριβῶς ἐπινοῆσαι, ὁ μὲν Φάβιος εἴκαζεν εἶναί τι στρατήγημα τοῦτο Ἀννίβου, καὶ συνεῖναι μὴ δυνάμενος ἀτρέμα συνεῖχε τὴν στρατιάν, τὴν νύκτα ὑφορώμενος· οἱ δ’ ἐν τοῖς στενοῖς ὑπέλαβον, ἅπερ ἤθελεν ὁ Ἀννίβας, φεύγειν αὐτὸν ὡς ἐν ἀπόροις, ἄνω διὰ τῶν κρημνῶν βιαζόμενον, καὶ μετεπήδων ἐπὶ τὴν φαντασίαν τοῦ πυρὸς καταθέοντες ὡς ἐκεῖ ληψόμενοι τὸν Ἀννίβαν κακοπαθοῦντα. ὁ δὲ ὡς εἶδε καταβάντας αὐτοὺς ἐκ τῶν στενῶν, διέδραμεν ἐς αὐτὰ τοῖς ταχυτάτοις ἄνευ φωτὸς μετὰ σιωπῆς, ἵνα διαλάθοι, καταλαβὼν δὲ αὐτὰ καὶ κρατυνάμενος ἐσήμηνε τῇ σάλπιγγι· καὶ τὸ στρατόπεδον ἀντεβόησεν αὐτῷ, καὶ πῦρ αἰφνίδιον ἐξέφηναν. Ῥωμαῖοι μὲν δὴ τότε ᾔσθοντο τῆς ἀπάτης, ὁ δὲ στρατὸς ὁ ἄλλος Ἀννίβου καὶ οἱ τὰς βοῦς ἐλαύνοντες ἐπὶ τὰ στενὰ ἀδεῶς διέδραμον. καὶ αὐτοὺς συναγαγὼν ἀπῇρεν ἐς τὸ πρόσω. οὕτω μὲν ἐξ ἀέλπτου τότε ὁ Ἀννίβας αὐτός τε περιῆν καὶ τὸν στρατὸν περιέσωζε, καὶ ἐς Γερωνίαν τῆς Ἰαπυγίας ἐπειχθείς, ἣ σίτου πλήρης ἦν, ἐξεῖλεν αὐτήν, καὶ ἐν ἀφθόνοις ἀδεῶς ἐχείμαζεν.", "st": "8.15"}, {"sp": "N", "t": "ὁ δὲ Φάβιος καὶ τότε τῆς αὐτῆς γνώμης ἐχόμενος εἵπετο, καὶ τῆς Γερωνίας ἀποσχὼν δέκα σταδίους ἐστρατοπέδευε, λαβὼν ἐν μέσῳ ποταμὸν Αὔφιδον. ληγόντων δὲ αὐτῷ τῶν ἓξ μηνῶν ἐφ’ οὓς αἱροῦνται Ῥωμαῖοι τοῦς δικτάτορας, οἱ μὲν ὕπατοι Σερουίλιός τε καὶ Ἀτίλιος ἐπὶ τὰς ἑαυτῶν ἀρχὰς ἐπανῄεσαν, καὶ ἦλθον ἐπὶ τὸ στρατόπεδον, καὶ ὁ Φάβιος ἐς Ῥώμην ἀπῄει, γίγνονται δέ τινες ἐν τῷδε τῷ χειμῶνι Ἀννίβᾳ καὶ Ῥωμαίοις ἀκροβολισμοὶ συνεχεῖς ἐς ἀλλήλους· καὶ τὰ Ῥωμαίων ἐπικυδέστερα καὶ εὐθαρσέστερα ἦν. ὁ δ’ Ἀννίβας ἐπέστελλε μὲν ἀεὶ τὰ γιγνόμενα Καρχηδονίοις ὑπερεπαίρων, τότε δὲ ἀπολωλότων αὐτῷ πολλῶν ἠπόρει, καὶ στρατιὰν ᾔτει καὶ χρήματα. οἱ δὲ ἐχθροὶ πάντα ἐπισκώπτοντες τὰ Ἀννίβου, καὶ τότε ὑπεκρίνοντο ἀπορεῖν ὅτι, τῶν νικώντων οὐκ αἰτούντων χρήματα ἀλλὰ πεμπόντων ἐς τὰς πατρίδας, ὁ Ἀννίβας αἰτοίη, λέγων νικᾶν. οἷς οἱ Καρχηδόνιοι πεισθέντες οὔτε στρατιὰν ἔπεμπον οὔτε χρήματα. καὶ ὁ Ἀννίβας ταῦτ’ ὀδυρόμενος ἔγραφεν ἐς Ἰβηρίαν Ἀσδρούβᾳ τῷ ἀδελφῷ, παρακαλῶν αὐτὸν ἀρχομένου θέρους μεθ’ ὅσης δύναιτο στρατιᾶς καὶ χρημάτων ἐσβαλεῖν ἐς τὴν Ἰταλίαν, καὶ πορθεῖν αὐτῆς τὰ ἐπέκεινα, ἵνα δῃῷτο πᾶσα καὶ Ῥωμαῖοι κάμνοιεν ὑπ’ αὐτῶν ἑκατέρωθεν.", "st": "8.16"}, {"sp": "N", "t": "καὶ τάδε μὲν ἦν περὶ Ἀννίβαν, Ῥωμαῖοι δὲ τῷ τε μεγέθει τῆς ἥττης τῆς Φλαμινίου καὶ Κεντηνίου περιαλγοῦντες ὡς ἀνάξια σφῶν καὶ παράλογα καὶ ἀθρόα παθόντες, καὶ τὸν πόλεμον ὅλως οὐ φέροντες ἔνδον ὄντα παρ’ ἑαυτοῖς, ἄλλα τε κατέλεγον ἐκ Ῥώμης τέλη στρατιωτῶν τέσσαρα μετ’ ὀργῆς ἐπὶ τὸν Ἀννίβαν, καὶ τοὺς συμμάχους πανταχόθεν ἤγειρον ἐς Ἰαπυγίαν. ὑπάτους τε αἱροῦνται ἐκ μὲν δόξης πολεμικῆς Λεύκιον Αἰμίλιον τὸν Ἰλλυριοῖς πολεμήσαντα, ἐκ δὲ δημοκοπίας Τερέντιον Οὐάρρωνα, πολλὰ αὐτοῖς ἐκ τῆς συνήθους δοξοκοπίας ὑπισχνούμενον. καὶ αὐτοὺς παραπέμποντες ἐξιόντας ἐδέοντο κρῖναι τὸν πόλεμον μάχῃ, καὶ μὴ τὴν πόλιν ἐκτρύχειν χρόνῳ τε καὶ στρατείαις συνεχέσι καὶ ἐσφοραῖς καὶ λιμῷ καὶ ἀργίᾳ τῆς γῆς δῃουμένης. οἱ δὲ τὴν στρατιὰν τὴν ἐν Ἰαπυγίᾳ προσλαβόντες, καὶ τὸ σύμπαν ἔχοντες πεζοὺς μὲν ἑπτακισμυρίους ἱππέας δ’ ἑξακισχιλίους, ἐστρατοπέδευον ἀμφὶ κώμῃ τινὶ καλουμένῃ Κάνναις. καὶ ὁ Ἀννίβας αὐτοῖς ἀντεστρατοπέδευεν. φύσει δὲ ὢν φιλοπόλεμος ὁ Ἀννίβας καὶ οὔ ποτε φέρων ἀργίαν, τότε μάλιστα τῆς ἀπορίας αὐτὸν ἐνοχλούσης ἐξέτασσε συνεχῶς ἐς μάχην, δεδιὼς μὴ οἱ μισθοφόροι μετάθοιντο διὰ τὴν ἀμισθίαν ἢ σκεδασθεῖεν ἐπὶ συλλογὴν ἀγορᾶς. καὶ ὁ μὲν οὕτω προὐκαλεῖτο τοὺς πολεμίους.", "st": "8.17"}, {"sp": "N", "t": "γνώμη δὲ τῶν ὑπάτων ἦν, Αἰμιλίου μὲν ὑπομένειν ἐκτρύχοντας Ἀννίβαν οὐ δυνησόμενον ἀντέχειν ἐπὶ πολὺ διὰ τὴν ἀπορίαν, μηδὲ διὰ χειρὸς ἔρχεσθαι γεγυμνασμένῳ πολέμοις καὶ εὐτυχίαις ἀνδρὶ καὶ στρατῷ, Τερεντίου δ’, οἷα δημοκόπου, μνημονεύειν ὧν ὁ δῆμος ἐξιοῦσιν ἐνετέλλετο, καὶ κρῖναι τὴν μάχην ὀξέως. τούτοιν Αἰμιλίῳ μὲν προσετίθετο Σερουίλιος ὁ πέρυσιν ὕπατος ἔτι παρών, Τερεντίῳ δὲ ὅσοι τε ἀπὸ βουλῆς καὶ τῶν καλουμένων ἱππέων ἡγοῦντο τῆς στρατιᾶς. ἀντεχόντων δ’ ἔτι τῶν ἑτέρων, ὁ Ἀννίβας τοῖς χορτολογοῦσιν αὐτῶν ἢ ξυλευομένοις ἐπιτιθέμενος ὑπεκρίνετο ἡττᾶσθαι, καὶ περὶ ἐσχάτην ποτὲ φυλακὴν ἐκίνει τὸ πλῆθος ὡς ἀναζευγνύς. ὁ δὲ Τερέντιος ἰδὼν ἐξῆγε τὴν στρατιὰν ὡς ἐπὶ φεύγοντα τὸν Ἀννίβαν, ἀπαγορεύοντος αὐτῷ καὶ τότε τοῦ Αἰμιλίου. ὡς δὲ οὐκ ἔπειθεν, οἰωνίζετο ὁ Αἰμίλιος ἐφ’ ἑαυτοῦ, καθάπερ εἰώθασι, καὶ πέμψας ὁδεύοντι ἤδη τῷ Τερεντίῳ τὴν ἡμέραν ἀπαίσιον ἔλεγεν εἶναι. ὁ δ’ ἐπανῄει μέν, αἰδούμενος οἰωνοῖς ἀπειθῆσαι, τὰς δὲ κόμας ἐν ὄψει τῆς στρατιᾶς ἐτίλλετο καὶ χαλεπῶς ἔφερεν ὡς τὴν νίκην ἀφῃρνμένος ὑπὸ ζηλοτυπίας τοῦ συνάρχου. καὶ τὸ πλῆθος αὐτῷ συνηγανάκτει.", "st": "8.18"}, {"sp": "N", "t": "Αννίβου δ’, ἐπεὶ τῆς πείρας ἐξέπιπτεν, αὐτίκα ἐς τὸ στρατόπεδον ἐπανελθόντος καὶ τὴν ὑπόκρισιν ἐκφήναντος, οὐδὲ τοῦτ’ ἐδίδασκε τὸν Τερέντιον πάνθ’ ὑπονοεῖν τὰ Ἀννίβου, ἀλλ’ ὡς εἶχεν, ἐν τοῖς ὅπλοις ἐς τὸ στρατήγιον ἐσδραμών, παρόντων ἔτι τῶν τε ἀπὸ βουλῆς καὶ ταξιάρχων καὶ χιλιάρχων, ᾐτιᾶτο περὶ τῶν οἰωνῶν τὸν Αἰμίλιον προφασίσασθαι καὶ νίκην φανερὰν ἀφελέσθαι τὴν πόλιν, ὀκνοῦντα ὑπὸ δειλίας, ἢ οἱ φθονοῦντα διὰ ζηλοτυπίαν. οὕτω δ’ αὐτοῦ βοῶντος ὑπ’ ὀργῆς ἡ στρατιὰ περιεστῶσα τὴν σκηνὴν ἐπήκουε, καὶ τὸν Αἰμίλιον ἐβλασφήμουν. ὁ δὲ πολλὰ μὲν εἶπε τοῖς ἔνδον συμφέροντα μάτην, Τερεντίῳ δέ, πλὴν Σερουιλίου, τῶν ἄλλων συντιθεμένων εἶξεν. καὶ τῆς ἐπιούσης ἐξέτασσεν αὐτὸς ἡγούμενος· παρεχώρει γὰρ ὁ Τερέντιος. Ἀννίβας δ’ ᾔσθετο, καὶ τότε μὲν οὐκ ἐπεξῆλθεν (οὐ γάρ πω πρὸς μάχην διετέτακτο), τῇ δ’ ἐπιούσῃ κατέβαινον ἐς τὸ πεδίον ἑκάτεροι, Ῥωμαῖοι μὲν ἐς τρία τεταγμένοι, μικρὸν ἀπ’ ἀλλήλων διεστῶτες, καὶ μέρος ἕκαστον αὐτῶν εἶχε τοὺς πεζοὺς ἐν μέσῳ, τοὺς δὲ ψιλοὺς καὶ ἱππέας ἑκατέρωθεν. στρατηγοὶ δ’ ἐφειστήκεσαν τῷ μέσῳ μὲν Αἰμίλιος, τῷ δὲ λαιῷ Σερουίλιος, Τερέντιος δὲ τοῖς ἐπὶ δεξιά, χιλίους ἀμφ’ αὑτὸν ἕκαστος ἔχων ἱππέας ἐπειλεγμένους, ἐπικουρεῖν ὅπῃ τι πονοίη. οὕτω μὲν ἐτάξαντο Ῥωμαῖοι·", "st": "8.19"}, {"sp": "N", "t": "ὁ δ’ Ἀννίβας πρῶτα μέν, εἰδὼς περὶ μεσημβρίαν εὖρον ζοφώδη τὸν χῶρον ἐξ ἔθους ἐπιπνέοντα, προύλαβεν ὅπῃ κατὰ νώτου τὸ πνεῦμα ἔμελλεν ἕξειν· ἔπειτα ἐς ὄρος περίφυτον καὶ φαραγγῶδες ἱππέας προενήδρευσε καὶ ψιλούς, οἷς εἴρητο, ὅταν αἱ φάλαγγες ἔργων ἔχωνται καὶ τὸ πνεῦμα ἐπίῃ, κατόπιν γίγνεσθαι τῶν πολεμίων. ἄνδρας τε πεντακοσίους Κελτίβηρας ἐπὶ τοῖς μακροῖς ξίφεσιν ὑπὸ τοῖς χιτῶσιν ἄλλα ξίφη βραχύτερα περιέζωσεν, οἷς ἔμελλεν αὐτὸς ὅτε δέοι χρῆσθαι σημανεῖν. σύμπασαν δὲ τὴν στρατιὰν κἀκεῖνος ἐς τρία διῄρει, καὶ τοὺς ἱππέας τοῖς κέρασιν ἐπέτασσεν ἐκ μεγάλων διαστημάτων, εἰ δύναιντο κυκλώσασθαι τοὺς πολεμίους. ἐπέστησε δὲ τῷ μὲν δεξιῷ Μάγωνα τὸν ἀδελφόν, τῷ δὲ ἑτέρῳ τὸν ἀδελφιδοῦν Ἄννωνα· τὸ δὲ μέσον αὐτὸς εἶχε κατὰ δόξαν Αἰμιλίου τῆς ἐμπειρίας. δισχίλιοί τε ἱππεῖς ἐπίλεκτοι παρέθεον αὐτῷ, καὶ Μαάρβαλ ἑτέρους ἔχων χιλίους ἐφήδρευεν ὅπῃ τι πονούμενον ἴδοι. καὶ τάδε πράσσων ἐς δευτέραν παρέτεινεν ὥραν, ἵνα τὸ πνεῦμα θᾶσσον ἐπέλθοι.", "st": "8.20"}, {"sp": "N", "t": "γενομένων δὲ πάντων εὐτρεπῶν ἑκατέροις, οἱ στρατηγοὶ διέθεον παρακαλοῦντες αὐτούς, καὶ ὑπεμίμνησκον οἱ μὲν γονέων τε καὶ παίδων καὶ γυναικῶν καὶ τῆς προγεγενημένης ἥττης, ὡς ἐν τῇδε τῇ μάχῃ περὶ σωτηρίας κριθησομένους, ὁ δ’ Ἀννίβας τῶν τε προγεγονότων ἐπὶ τοῖσδε τοῖς ἀνδράσι κατορθωμάτων, καὶ ὡς αἰσχρὸν ἡττᾶσθαι τῶν ἡττημένων. ἐπεὶ δ’ αἵ τε σάλπιγγες ἤχησαν καὶ αἱ φαλάγγες ἐβόησαν, πρῶτον μὲν αὐτῶν οἱ τοξόται καὶ σφενδονῆται καὶ λιθοβόλοι προδραμόντες ἐς τὸ μέσον ἀλλήλων κατῆρχον, μετὰ δὲ τούτους αἱ φάλαγγες ἐχώρουν ἐπὶ τὸ ἔργον, φόνος τε καὶ πόνος ἦν πολὺς ἐκθύμως ἀγωνιζομένων ἑκατέρων. ἐν ᾧ σημαίνει μὲν ὁ Ἀννίβας τοῖς ἱππεῦσι κυκλοῦσθαι τὰ κέρατα τῶν ἐχθρῶν, οἱ δὲ τῶν Ῥωμαίων ἱππεῖς ὀλιγώτεροι τῶν πολεμίων ὄντες ἀντιπαρῆγον αὐτοῖς, καὶ τὴν τάξιν ἐκτείναντες ἐπὶ λεπτὸν ἠγωνίζοντο ὅμως ὑπὸ προθυμίας, καὶ μάλισθ’ οἱ τὸ λαιὸν ἔχοντες ἐπὶ τῇ θαλάσσῃ. Ἀννίβας δὲ καὶ Μαάρβαλ ὁμοῦ τοὺς περὶ σφᾶς ἐπῆγον κραυγῇ ἀπλέτῳ καὶ βαρβαρικῇ, νομίσαντες ἐκπλήξειν τοὺς ἐναντίους. οἱ δὲ καὶ τούτους εὐσταθῶς καὶ ἀκαταπλήκτως ὑπέμενον.", "st": "8.21"}, {"sp": "N", "t": "Διαπιπτούσης δὲ καὶ τῆσδε τῆς πείρας, ὁ Ἀννίβας τὸ σημεῖον ἐπῆρε τοῖς Κελτίβηρσι τοῖς πεντακοσίοις. οἱ δὲ τῆς τάξεως ἐκδραμόντες ἐς τοὺς Ῥωμαίους μετετίθεντο, καὶ τὰς ἀσπίδας αὐτοῖς καὶ τὰ δόρατα καὶ τὰ ξίφη τὰ φανερὰ ὤρεγον ὥσπερ αὐτομολοῦντες. καὶ ὁ Σερουίλιος αὐτοὺς ἐπαινέσας τὰ μὲν ὅπλα αὐτῶν αὐτίκα παρεῖλεν, ἐν δὲ μόνοις, ὡς ᾤετο, τοῖς χιτῶσιν ἔστησεν ὀπίσω· οὐ γὰρ ἐδοκίμαζε καταδεῖν αὐτομόλους ἐν ὄψει πολεμίων, οὐδὲ ὑπώπτευεν ἐν χιτῶσι μόνοις ὁρῶν, οὐδὲ καιρὸς ἦν ἐν τοσῷδε πόνῳ. σπεῖραι δ’ ἕτεραι Λιβύων προσεποιήσαντο φεύγειν ἄχρι τῶν ὀρῶν, συναλαλάξασαι μέγα. σύμβολον δ’ ἦν ἡ βοὴ τοῖς ἐν ταῖς φάραγξι κεκρυμμένοις ἀναστρέφειν ἐς τοὺς διώκοντας. καὶ εὐθὺς οἵ τε ψιλοὶ καὶ ἱππεῖς ἐκ τῆς ἐνέδρας ἐξεφαίνοντο, καὶ τὸ πνεῦμα κατέβαινε πολὺ καὶ ζοφῶδες, ἐς τὰς Ῥωμαίων ὄψεις μετὰ κονιορτοῦ φερόμενον· ὃ καὶ μάλιστα αὐτοὺς ἐκώλυε προορᾶν τοὺς πολεμίους. τά τε βέλη Ῥωμαίοις μὲν πάντα ἀμβλύτερα διὰ τὴν ἀντιπνοιαν ἦν, τοῖς δὲ ἐχθροῖς ἐπιτυχῆ, τοῦ πνεύματος τὴν βολὴν συνωθοῦντος. οἱ δὲ οὔτε ἐκκλίνειν αὐτὰ προορῶντες οὔτ’ ἀφιέναι καλῶς δυνάμενοι, σφίσι τε αὐτοῖς περιπταίοντες, ἤδη ποικίλως ἐθορυβοῦντο.", "st": "8.22"}, {"sp": "N", "t": "τότε δὴ τὸν καιρὸν ὁρῶντες τὸν ἐπηγγελμένον σφίσιν οἱ πεντακόσιοι, τὰ ξίφη τὰ βραχύτερα ἐκ τῶν κόλπων ἐπισπάσαντες πρώτους ἀνῄρουν ὧν ἦσαν ὀπίσω, μετὰ δ’ ἐκείνους, ἁρπάσαντες αὐτῶν τὰ ξίφη τὰ μείζω καὶ τὰς ἀσπίδας καὶ τὰ δόρατα, πᾶσιν ἐνέπιπτον καὶ μετεπήδων ἀφειδῶς· καὶ φόνον εἰργάζοντο πλεῖστον οὗτοι μάλιστα, ἅτε πάντων ὄντες ὀπίσω. τό τε κακὸν ἤδη πολὺ τοῖς Ῥωμαίοις καὶ ποικίλον ἦν, πονουμένοις μὲν ὑπὸ τῶν ἐναντίων, κεκυκλωμένοις δ’ ὑπὸ τῆς ἐνέδρας, ἀναιρουμένοις δ’ ὑπὸ τῶν ἀναμεμιγμένων. οὐδ’ ἐπιστρέψαι πρὸς αὐτοὺς ἐδύναντο διὰ τοὺς ἐπικειμένους σφίσιν ἐκ μετώπου· οὐδ’ ἐπεγίγνωσκον ἔτι αὐτοὺς εὐμαρῶς, Ῥωμαϊκὰς ἀσπίδας ἔχοντας. ὑπὲρ ἅπαντα δ’ αὐτοὺς ὁ κονιορτὸς ἠνώχλει, καὶ οὐκ εἶχον οὐδ’ εἰκάσαι τὸ συμβαῖνον, ἀλλ’ οἷον ἐν θορύβῳ καὶ φόβῳ, πάντα πλείω νομίζοντες εἶναι, καὶ τὰς ἐνέδρας οὐ τοσαύτας, οὐδὲ τοὺς πεντακοσίους εἰδότες ὅτι ἦσαν πεντακόσιοι, ἀλλ’ ὅλον σφῶν τὸ στρατόπεδον ὑπὸ ἱππέων καὶ αὐτομόλων ἡγούμενοι κεκυκλῶσθαι, τραπέντες ἔφευγον ἀκόσμως, πρῶτοι μὲν οἱ ἐπὶ τοῦ δεξιοῦ, καὶ ὁ Τερέντιος αὐτοῖς ἐξῆρχε τῆς φυγῆς, μετὰ δ’ ἐκείνους οἱ τὸ λαιὸν ἔχοντες, ὧν ὁ Σερουίλιος ἡγούμενος πρὸς τὸν Αἰμίλιον διέδραμε· καὶ περὶ αὐτοὺς ἦν ὅσον ἄριστον ἱππέων τε καὶ πεζῶν, ἀμφὶ τοὺς μυρίους.", "st": "8.23"}, {"sp": "N", "t": "καταθορόντες δ’ ἀπὸ τῶν ἵππων οἱ στρατηγοί, καὶ μετ’ αὐτοὺς ὅσοι ἄλλοι ἦσαν ἐπὶ ἵππων, ἐπεζομάχουν τοῖς ἱππεῦσι τοῖς Ἀννίβου κεκυκλωμένοι. καὶ πολλὰ μὲν ἐξ ἐμπειρίας σὺν εὐψυχίᾳ καὶ ἀπονοίᾳ λαμπρὰ ἔδρασαν, ἐμπίπτοντες σὺν ὀργῇ τοῖς πολεμίοις, πανταχόθεν δὲ ἀνῃροῦντο, περιτρέχοντος αὐτοὺς τοῦ Ἀννίβου, καὶ τοὺς ἰδίους ὁτὲ μὲν ἐξοτρύνοντος καὶ παρακαλοῦντος τὸ λείψανον τῆς νίκης ἐκπονῆσαι, ὁτὲ δ’ ἐπιπλήσσοντός τε καὶ ὀνειδίζοντος, εἰ τὸ πλῆθος νενικηκότες ὀλίγων οὐ περιέσονται. Ῥωμαῖοι δ’, ἕως μὲν αὐτοῖς ὁ Αἰμίλιος καὶ ὁ Σερουίλιος περιῆσαν, πολλὰ δρῶντές τε καὶ πάσχοντες ὅμως ὑπέμενον ἐν τάξει· ἐπεὶ δ’ ἔπεσον αὐτῶν οἱ στρατηγοί, διὰ μέσων βιαζόμενοι τῶν ἐχθρῶν μάλα καρτερῶς κατὰ μέρη διέφευγον, οἱ μέν, ἔνθαπερ οἱ πρὸ αὐτῶν ἐπεφεύγεσαν, ἐς τὰ στρατόπεδα δύο ὄντα· καὶ σύμπαντες οἵδε ἐγένοντο ἀμφὶ τοὺς μυρίους καὶ πεντακισχιλίους, οἷς ὁ Ἀννίβας φυλακὴν ἐπέστησεν· οἱ δ’ ἐς Κάννας, περὶ δισχιλίους, καὶ παρέδωκαν ἑαυτοὺς οἵδε οἱ δισχίλιοι τῷ Ἀννίβᾳ. ὀλίγοι δ’ ἐς Κανύσιον διέδρασαν, καὶ οἱ λοιποὶ κατὰ μέρος ἐσκεδάσθησαν ἀνὰ τὰς ὕλας.", "st": "8.24"}, {"sp": "N", "t": "τοῦτο τέλος ἦν τῆς ἐπὶ Κάνναις Ἀννίβου τε καὶ Ῥωμαίων μάχης, ἀρξαμένης μὲν ὑπὲρ ὥραν δευτέραν, ληξάσης δὲ πρὸ δύο τῆς νυκτὸς ὡρῶν, οὔσης δ’ ἔτι νῦν ἀοιδίμου Ῥωμαίοις ἐπὶ συμφορᾷ· ἀπέθανον γὰρ αὐτῶν ἐν ταῖσδε ταῖς ὥραις πεντακισμύριοι, καὶ ζώντων ἐλήφθη πολὺ πλῆθος ἀπό τε τῆς βουλῆς πολλοὶ παρόντες ἐτελεύτησαν, καὶ ἐπ’ αὐτοῖς ταξίαρχοί τε ν άντες καὶ λοχαγοὶ καὶ τῶν στρατηγῶν αὐτῶν οἱ ἄριστοι δύο. ὁ δὲ φαυλότατός τε καὶ τῶν συμφορῶν αἴτιος ἀρχομένης τῆς τροπῆς ἐπεφεύγει. καὶ Ῥωμαῖοι δύο ἔτεσιν ἤδη περὶ τὴν Ἰταλίαν Ἀννίβᾳ πολεμοῦντες ἀπωλωλέκεσαν ἀνδρῶν ἰδίων τε καὶ συμμάχων ἐς δέκα μυριάδας.", "st": "8.25"}, {"sp": "N", "t": "Ἀννίβας δὲ νίκην ἀρίστην τε καὶ σπάνιον ἐξενεγκάμενος ἡμέρας μιᾶς στρατηγήμασι τέσσαρσι, τοῦ τε πνεύματος τῇ φορᾷ καὶ τοῖς ὑποκριθεῖσιν αὐτομολεῖν καὶ τοῖς προσποιηθεῖσι φεύγειν καὶ τοῖς ἐν μέσαις ταῖς φάραγξι κεκρυμμένοις, εὐθὺς ἀπὸ τοῦ ἔργου τοὺς πεσόντας ἐπῄει, θεώμενος δὲ τῶν φίλων τοὺς ἀρίστους ἀνῃρημένους ᾤμωξε, καὶ δακρύσας εἶπεν οὐ χρῄζειν ἑτέρας τοιᾶσδε νίκης. ὃ καὶ Πύρρον φασὶν εἰπεῖν πρὸ αὐτοῦ, τὸν Ἠπείρου βασιλέα, Ῥωμαίων κἀκεῖνον ἐν Ἰταλίᾳ κρατοῦντα σὺν ὁμοίᾳ ζημίᾳ. τῶν δὲ φυγόντων ἐκ τῆς μάχης οἱ μὲν ἐν τῷ μείζονι στρατοπέδῳ στρατηγὸν αὑτῶν ἑσπέρας ἑλόμενοι Πόπλιον Σεμπρώνιον, ἐβιάσαντο τοὺς Ἀννίβου φύλακας ὕπνου καὶ κόπου πλήρεις ὄντας, καὶ διέδραμον ἐς Κανύσιον περὶ μέσας νύκτας, ἀμφὶ τοὺς μυρίους, οἱ δ’ ἐν τῷ βραχυτέρῳ πεντακισχίλιοι τῆς ἐπιούσης ἡμέρας ἐλήφθησαν ὑπὸ τοῦ Ἀννίβου. Τερέντιος δὲ στρατὸν ἀγείρας τοὺς διερριμμένους ἐπειρᾶτο παραθαρρύνειν, καὶ στρατηγὸν αὐτοῖς ἐπιστήσας τῶν χιλιάρχων τινὰ Σκιπίωνα ἐς Ῥώμην διέδραμεν.", "st": "8.26"}, {"sp": "N", "t": "ἡ δὲ πόλις, ἀπαγγελθεισης τῆς συμφορᾶς, οἱ μὲν ἐν ταῖς ὁδοῖς ἐθρήνουν τε τοὺς οἰκείους ἀνακαλοῦντες, καὶ σφᾶς ὡς αὐτικα ἁλωσομένους ὠλοφύροντο, αἱ δὲ γυναῖκες ἱκέτευον ἐν τοῖς ἱεροῖς μετὰ τῶν τέκνων λῆξαί ποτε τὰς συμφορὰς τῇ πόλει, οἱ δ’ ἄρχοντες θυσίαις τε καὶ εὐχαῖς ἱλάσκοντο τοὺς θεούς, εἴ τι μήνιμα ἐνοχλεῖ, κορεσθῆναι τοῖς γεγονόσιν. ἡ δὲ βουλὴ Κόιντον μὲν Φάβιον, τὸν συγγραφέα τῶνδε τῶν ἔργων, ἐς Δελφοὺς ἔπεμπε χρησόμενον περὶ τῶν παρόντων, δούλους δὲ ἐς ὀκτακισχιλίους τῶν δεσποτῶν ἐπιδόντων ἠλευθέρου, ὅπλα τε καὶ τόξα τοὺς ἐν ἄστει πάντας ἐργάζεσθαι παρεσκεύαζε, καὶ συμμάχους, καὶ ὥς, τινὰς συνέλεγεν. Κλαύδιόν τε Μάρκελλον μέλλοντα πλεῖν ἐς Σικελίαν, ἐς τὸν Ἀννίβου πόλεμον μετέφερεν. ὁ δὲ τὸν μὲν στόλον ἐμερίσατο τῷ συνάρχῳ Φουρίῳ, καὶ τὸ μέρος ἔπεμψεν ἐς τὴν Σικελίαν, αὐτὸς δὲ τοὺς δούλους ἄγων καὶ ὅσους ἄλλους ἐδύνατο τῶν πολιτῶν ἢ συμμάχων, γενομένους ἅπαντας ἐς μυρίους πεζοὺς καὶ δισχιλίους ἱππέας, ἐς τὸ Τεανὸν παρῆλθε, καὶ ὅ τι πράξειν ὁ Ἀννίβας μέλλοι παρεφύλασσεν.", "st": "8.27"}, {"sp": "N", "t": "Ἀννιβου δὲ δόντος τοῖς αἰχμαλώτοις ἐς Ῥώμην πρεσβεύσασθαι περὶ σφῶν, εἰ θέλοιεν αὐτοὺς οἱ ἐν ἄστει λύσασθαι χρημάτων, καὶ τοὺς αἱρεθέντας ὑπ’ αὐτῶν τρεῖς, ὧν ἡγεῖτο Γναῖος Σεμπρώνιος, ὁρκώσαντος ἐς αὐτὸν ἐπανήξειν, οἱ μὲν οἰκεῖοι τῶν ἁλόντων, περιστάντες τὸ βουλευτήριον, ἐπηγγέλλοντο λύσεσθαι τοὺς οἰκείους ἕκαστος ἰδίοις χρήμασι, καὶ παρεκάλουν τὴν βουλὴν τοῦτο σφίσιν ἐπιτρέψαι, καὶ ὁ δῆμος αὐτοῖς συνεδάκρυε καὶ συνεδεῖτο· τῶν δὲ βουλευτῶν οἱ μὲν οὐκ ἠξίουν ἐπὶ τοσαῖσδε συμφοραῖς ἄλλους τοσούσδε βλαβῆναι τὴν πόλιν, οὐδὲ δούλους μὲν ἐλευθεροῦν τοὺς δὲ ἐλευθέρους ὑπερορᾶν, οἱ δ’ οὐκ ᾤοντο δεῖν αὐτοὺς ἐθίζειν τῷδε τῷ ἐλέῳ φεύγειν, ἀλλ’ ἢ νικᾶν μαχομένους ἢ ἀποθνήσκειν ὡς οὐκ ὂν οὐδ’ ὑπὸ τῶν οἰκείων ἐλεεῖσθαι τὸν φυγόντα. πολλῶν δὲ παραδειγμάτων ἐς ἑκάτερα λεχθέντων, οὐκ ἐπέτρεψεν ἡ βουλὴ τοῖς συγγενέσι λύσασθαι τοὺς αἰχμαλώτους, ἡγουμένη, πολλῶν σφίσιν ἔτι κινδύνων ἐπόντων, οὐ συνοίσειν ἐς τὸ μέλλον τὴν ἐν τῷ παρόντι φιλανθρωπίαν, τὸ δ’ ἀπάνθρωπον, εἰ καὶ σκυθρωπὸν εἴη, πρός τε τὰ μέλλοντα χρήσιμον ἔσεσθαι καὶ ἐν τῷ παρόντι καταπλήξειν Ἀννίβαν τῷ τολμήματι. Σεμπρώνιος οὖν καὶ οι σὺν αὐτῷ δύο τῶν αἰχμαλώτων πρὸς Ἀννίβαν ἐπανῄεσαν. ὁ δ’ ἔστι μὲν οὓς ἀπέδοτο τῶν αἰχμαλώτων, ἔστι δ’ οὓς ὑπ’ ὀργῆς ἀνῄρει, καὶ τοῖς σώμασι τὸν ποταμὸν ἐγεφύρου καὶ ἐπέρα. ὅσοι δ’ ἦσαν ἀπὸ τῆς βουλῆς ἢ ἄλλως ἐπιφανεῖς, μονομαχεῖν αὐτοὺς ὑπὸ θεαταῖς τοῖς Λίβυσιν ἠνάγκασε, πατέρας τε υἱοῖς καὶ ἀδελφοὺς ἀδελφοῖς, οὐδὲν ἐκλείπων ὑπεροψίας ὠμῆς.", "st": "8.28"}, {"sp": "N", "t": "μετὰ δὲ τοῦτ’ ἐπιὼν τὰ ὑπὸ Ῥωμαίοις ἐλυμαίνετο, καὶ Πετηλίνοις μηχανήματα προσῆγεν. οἱ δ’ ὀλίγοι μὲν ἦσαν, ὑπὸ δὲ τόλμης μετὰ τῶν γυναικῶν ἐπεξέθεον αὐτῷ, καὶ πολλὰ καὶ γενναῖα ἔδρων, τάς τε μηχανὰς αὐτοῦ συνεχῶς ἐνεπίμπρασαν, οὐχ ἧσσον αὐτοῖς τῶν γυναικῶν ἀνδριζομένων. ὀλιγώτεροι δε γιγνόμενοι καθ’ ἕκαστον ἔργον ἐκακοπάθουν μάλιστα ὑπὸ λιμοῦ· καὶ ὁ Ἀννίβας αἰσθανόμενος περιετείχισεν αὐτούς, καὶ Ἄννωνα ἐπέστησε τῇ πολιορκίᾳ. οἱ δ’, ἐπιτείνοντος αὐτοῖς τοῦ κακοῦ, πρῶτα μὲν τοῦς ἀχρείους σφῶν ἐς μάχας ἐξέβαλον ἐς τὸ μεσοτείχιον, καὶ κτιννυμένους ὑπὸ τοῦ Ἄννωνος ἐφεώρων ἀλύπως ὡς εὐμοιρότερον ἀποθνήσκοντας. τῷ δ’ αὐτῷ λόγῳ καὶ οἱ λοιποὶ πάμπαν ἀποροῦντες ἐξέδραμον ἐπὶ τοὺς πολεμίους, καὶ πολλὰ μὲν καὶ γενναῖα καὶ τότε ἔδρασαν, ὑπὸ δὲ ἀτροφίας καὶ ἀσθενείας σωμάτων οὐδ’ ὑποστρέψαι δυνάμενοι διεφθάρησαν ἅπαντες ὑπὸ τῶν Λιβύων. καὶ τὴν πόλιν εἷλεν ὁ Ἄννων, ἐκφυγόντων καὶ ὣς ἀπ’ αὐτῆς ὀλίγων τῶν δραμεῖν δυνηθέντων. τούτους διερριμμένους οἱ Ῥωμαῖοι σπουδῇ συνῆγον, καὶ γενομένους ἐς ὀκτακοσίους κατήγαγόν τε καὶ συνῴκισαν μετὰ τόνδε τὸν πόλεμον αὖθις ἐς τὴν πατρίδα, ἀγάμενοι τῆς τε περὶ σφᾶς εὐνοίας καὶ τοῦ παραδόξου τῆς προθυμίας.", "st": "8.29"}, {"sp": "N", "t": "τῶν δὲ Κελτιβήρων ἱππέων, οἳ ἐμισθοφόρουν Ἀννίβᾳ, λαμπρῶς ἀγωνιζομένων, ὅσοι Ῥωμαίων ἐστρατήγουν ἐν Ἰβηρίᾳ, τοσούσδε ἑτέρους τὰς πόλεις τὰς ὑπὸ σφίσιν αἰτήσαντες ἐς ἀντίπαλον ἐκείνων ἔπεμψαν ἐς τὴν Ἰταλίαν, οἳ τοῖς ὁμοεθνέσιν, ὅτε πλησίον Ἀννίβου στρατοπεδεύοιεν, ἀναμιγνύμενοι μετέμειθον αὐτούς. καὶ πολλῶν μετατιθεμένων τε καὶ αὐτομολούντων ἢ ἀποδιδρασκόντων οὐδὲ τὸ λοιπὸν ἦν ἔτι τῷ Ἀννίβᾳ πιστόν, ὑποπτευόμενόν τε ὑπ’ ἐκείνου καὶ ὑποπτεύοντες αὐτόν. κάκιον οὖν ἔπρασσεν ὁ Ἀννίβας τὸ ἀπὸ τοῦδε.", "st": "8.30"}, {"sp": "N", "t": "Ἀργύριππα δ’ ἐστὶ πόλις ἐν τῇ Δαυνίᾳ, ἣν Διομήδης ὁ Ἀργεῖος λέγεται κτίσαι. καί τις ἔκγονος εἶναι τοῦ Διομήδους νομιζόμενος, Δάσιος, ἀνὴρ εὐμετάβολός τε τὸ φρόνημα καὶ οὐ Διομήδους ἄξιος, Ῥωμαίων περὶ Κάννας τὴν μεγάλην ἧτταν ἡττημένων ἀπέστησε τὴν πατρίδα πρὸς τοὺς Λίβυας ἀπὸ Ῥωμαίων. τότε δ’ αὖ δυσπραγοῦντος Ἀννίβου ἔλαθεν ἐς Ῥώμην διιππεύσας, καὶ ἐπὶ τὴν βουλὴν ἐπαχθεὶς ἔφη δύνασθαι τὸ ἁμάρτημα ἰάσασθαι καὶ μεταβαλεῖν αὖθις ἐς Ῥωμαίους τὴν πόλιν. οἱ δ’ ὀλίγου μὲν αὐτὸν καὶ διέφθειραν, ἐξέβαλον δ’ εὐθὺς ἐκ τῆς πόλεως. ὁ δὲ καὶ τούσδε καὶ τὸν Ἀννίβαν δεδιὼς ἠλᾶτο ἀνὰ τὴν χώραν, καὶ ὁ μὲν Ἀννίβας αὐτοῦ τὴν γυναῖκα καὶ τὰ τέκνα ζῶντας ἔκαυσε, τὰ δὲ Ἀργύριππα ἑτέρων ἐνδόντων εἷλε Φάβιος Μάξιμος νυκτός, καὶ κτείνας ὅσους ηὗρε Λιβύων, φρουρὰν ἐπέστησε τῇ πόλει.", "st": "8.31"}, {"sp": "N", "t": "Τάραντα δὲ φρουρουμένην ὑπὸ Ῥωμαιων Κονωνεὺς ὧδε προύδωκεν. κυνηγετεῖν εἴθιστο ὁ Κονωνεύς, καὶ φέρων ἀεί τι τῷ φρουράρχῳ Λιουίῳ συνήθης ἐκ τοῦδε ἐγεγένητο. ὡς δὲ ἐν πολεμουμένῃ χώρᾳ, νυκτὸς ἔφη δεῖν κυνηγετεῖν καὶ νυκτὸς φέρειν τὰ λαμβανόμενα. νυκτὸς οὖν αὐτῷ τῶν πυλῶν ἀνοιγομένων, συνθέμενος Ἀννίβᾳ καὶ στρατιώτας λαβών, τοὺς μὲν ἔκρυψεν ἐν λόχμῃ τινὶ πλησίον, τοὺς δ’ ἐπακολουθεῖν ἐκέλευσεν ἑαυτῷ δι’ ὀλίγου, τοὺς δὲ σὺν αὐτῷ προσιέναι, θώρακας ἔνδοθεν ὑπεζωσμένους καὶ ξίφη, τὰ δ’ ἐκτὸς ὡς ἂν ἐς κυνηγέτας ἐσκευασμένους. κάπρον τε αὐτοῖς ἐπὶ ξύλων ἐπιθεὶς ἧκε νυκτὸς ἐπὶ τὰς πύλας. καὶ τῶν φυλάκων, ὥσπερ ἔθος ἦν, ἀνοιξάντων, οἱ μὲν συνεσελθόντες αὐτῷ τοὺς ἀνοίξαντας αὐτίκα διεχρῶντο, οἱ δ’ ἑπόμενοι κατὰ σπουδὴν συνεσέπιπτον ἐκείνοις, καὶ τοὺς ἀπὸ τῆς λόχμης ἐδέχοντο, καὶ τὰς πύλας ἀνεῴγνυον τῷ Ἀννίβᾳ. ὁ δὲ ἔσω παρελθὼν τῆς μὲν ἄλλης πόλεως εὐθὺς ἐκράτει, καὶ τοὺς Ταραντίνους ἑταιρισάμενος τὴν ἄκραν ἔτι φρουρουμένην ἐπολιόρκει.", "st": "8.32"}, {"sp": "N", "t": "ὧδε μὲν Κονωνεὺς Τάραντα προύδωκε· Ῥωμαῖοι δ’ ὅσοι τὴν ἀκρόπολιν εἶχον, ε͂ς μὲν πεντακισχιλίους ἦσαν, καὶ αὐτοῖς Ταραντίνων τέ τινες προσεχώρουν, καὶ ὁ τῆς ἐν Μεταποντίῳ φρουρᾶς ἡγεμὼν τὸ ἥμισυ τῆς φρουρᾶς ἔχων ἦλθε, βελῶν τε καὶ ὀργάνων πολλῶν ηὐπόρουν, ὡς ἀπὸ τείχους εὐμαρῶς ἀμύνεσθαι τὸν Ἀννίβαν. ηὐπόρει δὲ καὶ ὁ Ἀννίβας. πύργους τε οὖν καὶ καταπέλτας ἐπάγων καὶ χελώνας ἔνια διέσειε, καὶ δρεπάνοις ἀπὸ κάλων ἐπάλξεις τε κατέσυρε καὶ τὸ τεῖχος ἀπεγύμνου. οἱ δὲ λίθους μὲν ἐπὶ τὰς μηχανὰς ἀφιέντες πολλὰ συνέτριβον, βρόχοις δὲ τὰ δρέπανα περιέσπων, καὶ πολλάκις ἐκθέοντες ἄφνω συνετάρασσον ἀεί τι καὶ κτείναντες ἐπανῄεσαν. ὡς δὲ καὶ πνεῦμά ποτε λάβρον ἐθεάσαντο, οἱ μὲν ἀπὸ τοῦ τείχους δᾷδας ἡμμένας καὶ στύππιον καὶ πίσσαν αὐτοῦ τοῖς μηχανήμασιν ἐπερρίπτουν, οἱ δὲ καὶ ἐκδραμόντες ὑπέθηκαν. ἀπογνοὺς οὖν ὁ Ἀννίβας τῆσδε τῆς πείρας περιετείχισε τὴν πόλιν, χωρίς γε τοῦ πρὸς θαλάσσῃ μέρους· οὐ γὰρ ἦν καὶ τοῦτο δυνατόν. καὶ παραδοὺς Ἄννωνι τὴν πολιορκίαν, ἐς Ἰάπυγας ἀνεχώρει.", "st": "8.33"}, {"sp": "N", "t": "λιμένες δ’ εἰσὶ τοῖς Ταραντινοις πρὸς βορρᾶν ἄνεμον ἐκ πελάγους ἐσπλέοντι διὰ ἰσθμοῦ, καὶ τὸν ἰσθμὸν ἀπέκλειον γεφύραις, ὧν τότε κρατοῦντες οἱ Ῥωμαίων φρουροὶ σφίσι μὲν ἐδέχοντο τὴν ἀγορὰν ἐκ θαλάσσης, Ταραντίνοις δ’ ἐκώλυον ἐσκομίζεσθαι. ὅθεν ἠπόρουν ἀγορᾶς οἱ Ταραντῖνοι, ἕως ἐπελθὼν αὐτοῖς ὁ Ἀννίβας ἐδίδαξε λεωφόρον ὁδόν, ἣ διὰ μέσης τῆς πόλεως ἔφερεν ἀπὸ τῶν λιμένων ἐπὶ τὴν νοτιον θαλασσαν, ὀρύξαντας, ἰσθμὸν ἕτερον ποιήσασθαι. καὶ οἱ μὲν οὕτω πράξαντες εἶχόν τε ἀγοράν, καὶ τριήρεσι τοὺς Ῥωμαίων φρουροὺς ναῦς οὐκ ἔχοντας ὑπὸ τὸ τεῖχος ἔβλαπτον, ὅτε μὴ χειμὼν εἴη μάλιστα, καὶ τὴν ἀγορὰν τὴν καταπλέουσαν ἐκείνοις ἀφῃροῦντο· οἱ δ’ ἠπόρουν. καὶ νυκτὸς αὐτοὶς Θουρίων σῖτόν τε ναυσὶ πεμπόντων καὶ τριήρεις ἐς φυλακὴν τῶν νεῶν, οἱ Ταραντῖνοι καὶ οἱ σὺν αὐτοῖς Λίβυες πυθόμενοι καὶ λοχήσαντες ἔλαβον αὐτῷ τε σίτῳ καὶ αὐτοῖς ἀνδράσιν ἁπάσας. πρεσβευομένων δὲ θαμινὰ τῶν Θουρίων, καὶ ἀξιούντων λύσασθαι τοὺς εἰλημμένους, οἱ Ταραντῖνοι τοὺς φοιτῶντας αὐτῶν μετέπειθον ἐς Ἀννίβαν. καὶ ὁ Ἀννίβας ὅσους εἶχε Θουρίων αἰχμαλώτους, εὐθὺς ἀπέλυεν. οἱ δὲ τοὺς οἰκείους σφῶν βιασάμενοι, τὰς πύλας Ἄννωνι ἀνέῳξαν. καὶ Θούριοι μὲν Ῥωμαίοις Τάραντα περιποιούμενοι ἔλαθον οὕτως ὑπὸ Καρχηδονίοις αὐτοὶ γενόμενοι· ἡ δ’ ἐν τῇ πόλει φρουρὰ Ῥωμαίων ἐς Βρεντέσιον λαθοῦσα διεπλευσεν.", "st": "8.34"}, {"sp": "N", "t": "Μεταποντῖνοι δ’, ἐξ οὗ σφῶν ὁ φρούραρχος τὸ ἥμισυ τῆς φρουρᾶς ἄγων ἐς Τάραντα ᾤχετο, τοὺς λοιποὺς ὀλίγους γενομένους ἀπέκτειναν καὶ Ἀννίβᾳ προσέθεντο. προσέθετο δὲ καὶ ἡ μεταξὺ Μεταποντίνων τε καὶ Θουρίων Ἡράκλεια, δέει μᾶλλον ἢ γνώμῃ. καὶ πάλιν ἦν ἐπικυδέστερα τὰ Ἀννίβου. τοῦ δ’ ἑξῆς ἔτους καὶ Λευκανῶν τινες ἀπέστησαν ἀπὸ Ῥωμαίων· οἷς Σεμπρώνιος Γράκχος ἀνθύπατος ἐπελθὼν ἐπολέμει. Λευκανὸς δέ τις ἐκ τῶν ἔτι Ῥωμαίοις ἐμμενόντων Φλάουιος, φίλος ὢν καὶ ξένος Γράκχου, προδιδοὺς αὐτὸν ἔπεισεν ἔς τι χωρίον ἐλθόντα συνθέσθαι Λευκανῶν τοῖς στρατηγοῖς ὡς μετανοοῦσι, καὶ δοῦναι καὶ λαβεῖν πίστεις. ὁ δ’ οὐδὲν ὑποτοπήσας εἵπετο μεθ’ ἱππέων τριάκοντα. Νομάδων δὲ πολλῶν αὐτὸν ἐξ ἐνέδρας κυκλωσαμένων, ὁ μὲν Φλάουιος ἐξίππευσεν ἐς ἐκείνους, ὁ δὲ Γράκχος συνεὶς τῆς προδοσίας καθήλατο μετὰ τῶν ἱππέων, καὶ πολλὰ καὶ γενναῖα δρῶν κατεκόπη μετὰ πάντων πλὴν τριῶν, οὓς μόνους εἷλεν ὁ Ἀννίβας, πολλὴν ποιησάμενος σπουδὴν λαβεῖν ζῶντα Ῥωμαίων τὸν ἀνθύπατον. αἰσχρῶς δ’ αὐτὸν ἐνηδρευμένον ἀγάμενος ὅμως τῆς τελευταίας ἀρετῆς ἔθαψε, καὶ τὰ ὀστᾶ Ῥωμαίοις ἔπεμψεν.", "st": "8.35"}, {"sp": "N", "t": "καὶ ἀπὸ τοῦδε αὐτὸς μὲν ἐν Ἰάπυξιν ἐθέριζε καὶ σῖτον πολὺν ἐσώρευε,", "st": "8.35"}, {"sp": "N", "t": "Ῥωμαίων δ’ ἐπιθέσθαι Καπυαιοις ἐγνωκότων ἔπεμπεν Ἄννωνα μετὰ χιλίων πεζῶν καὶ χιλίων ἱππέων ἐσδραμεῖν νυκτὸς ἐς Καπύην. καὶ ὁ μὲν ἐσέδραμε Ῥωμαίους λαθών, οἱ δ’ ἡμέρας γενομένης, ὡς πλέονας εἶδον ἐπὶ τῶν τειχῶν, τὸ συμβὰν ἔγνωσαν, καὶ τῆς μὲν πόλεως εὐθὺς ἀνεχώρουν, τὰ δὲ θέρη τὰ Καπυαίων καὶ τῶν ἄλλων Καμπανῶν προκατελάμβανον. ὀδυρομένοις δὲ περὶ τοῦδε τοῖς Καμπανοῖς ὁ Ἀννίβας ἔφη πολὺν ἔχειν σῖτον ἐν Ἰαπυγίᾳ, καὶ πέμποντας ἐκέλευε λαμβάνειν ὁσάκις θέλοιεν. οἱ δ’ οὐκ ὑποζύγια μόνον οὐδ’ ἄνδρας, ἀλλὰ καὶ γύναια καὶ παιδία ἔπεμπον ἀχθοφορήσοντα τοῦ σίτου· καὶ γὰρ ἐθάρρουν τῇ διόδῳ, μετελθόντος ἐς αὐτὴν ἐξ Ἰαπύγων Ἀννίβου, καὶ παρὰ τὸν Κάλωρα ποταμὸν στρατοπεδεύοντος, πλησίον Βενεβενδέων, οὓς μόνους ἐδεδοίκεσαν Ῥωμαίοις ἔτι συμμάχους ὄντας. τότε δὲ Ἀννίβου παρόντος ἁπάντων κατεφρόνουν.", "st": "8.36"}, {"sp": "N", "t": "συνέβη δὲ Ἀννίβαν μέν, καλοῦντος αὐτὸν Ἄννωνος, ἐς Λευκανοὺς διελθεῖν, τὰ πολλὰ τῆς κατασκευῆς ἐν τῷ περὶ Βενεβεντὸν στρατοπέδῳ μετ’ ὀλίγης φρουρᾶς καταλιπόντα, δυοῖν δὲ Ῥωμαίοις στρατηγούντοιν ὑπάτοιν, Φουλουίου τε Φλάκκου καὶ Κλαυδίου Ἀππίου, τὸν ἕτερον αὐτοῖν πυθόμενον ἐπιδραμεῖν τοῖς Καμπανοῖς διαφέρουσι τὰ θέρη, καὶ πολλοὺς μὲν οἷα ἀπαρασκεύους διαφθεῖραι, καὶ τὸν σῖτον Βενεβενδεῦσι δοῦναι, λαβεῖν δὲ καὶ τὸ στρατόπεδον Ἀννίβου, καὶ τὴν ἐν αὐτῷ παρασκευὴν ἁρπάσαι, καὶ Καπύην ἔτι ὄντος ἐν Λευκανοῖς Ἀννίβου περιταφρεῦσαί τε καὶ ἐπὶ τῇ τάφρῳ περιτειχίσαι πᾶσαν ἐν κύκλῳ. καὶ τοῦδε τοῦ περιτειχίσματος ἐκτὸς ἄλλο ποιήσαντες οἱ στρατηγοὶ τὸ μεσον εἶχον ἀντὶ στρατοπέδου. ἐπάλξεις δ’ ἦσαν αὐτοῖς αἱ μὲν ἐς Καπυαίους πολιορκουμένους αἱ δ’ ἐς τοὺς ἔξωθεν ἐπιόντας ἐπεστραμμέναι, ἥ τε ὄψις ἦν πόλεως μεγάλης σμικροτέραν ἐχούσης ἐν μέσῳ. τὸ δὲ ἀπὸ τοῦ περιτειχίσματος ἐς τὴν Καπύην διάστημα διστάδιον ἦν μάλιστα· ἐν ᾧ πολλαὶ ἐγίγνοντο πεῖραι καὶ συμβολαὶ καθ’ ἑκάστην ἡμέραν, πολλὰ δ’ ὡς ἐν θεάτρῳ μεσοτειχίῳ μονομάχια, προκαλουμένων ἀλλήλους τῶν ἀρίστων. καί τις Καπυαῖος, Ταυρέας, Ῥωμαίων ἐν μονομαχίῳ Κλαύδιον Ἄσελλον περιφεύγων ὑπεχώρει, μέχρι τοῖς Καπυαίων τείχεσιν ὁ Ἄσελλος ἐγκύρσας καὶ τὸν ἵππον οὐ δυνάμενος ἐκ τῆς ῥύμης ἐπιστρέψαι διὰ τῶν πολεμίων πυλῶν ἐς τὴν Καπύην ἐσήλατο σὺν ὁρμῇ, καὶ διιππεύσας τὴν πόλιν ὅλην κατὰ τὰς ἑτέρας ἐξέδραμεν ἐς τοὺς ἐπὶ θάτερα Ῥωμαίους.", "st": "8.37"}, {"sp": "N", "t": "καὶ ὁ μὲν οὕτω παραβόλως διεσώζετο, Ἀννίβας δὲ τῆς χρείας ψευσθεὶς ἐφ’ ἣν ἐς Λευκανοὺς μετεκέκλητο, ἀνέστρεφεν ἐς Καπύην, μέγα ποιούμενος μὴ περιιδεῖν πόλιν μεγάλην καὶ εὔκαιρον ὑπὸ Ῥωμαίοις γενομένην. προσβαλὼν δὲ τῷ περιτειχίσματι καὶ μηδὲν δυνηθείς, μηδ’ ἐπινοῶν ὅπως ἂν ἐς τὴν πόλιν ἐσπέμψειεν ἢ σῖτον ἢ στρατιάν, οὐδενὸς οὐδ’ ἀπ’ ἐκείνων αὐτῷ συμβαλεῖν δυναμένου διὰ τὴν ἐπιτείχισιν πάντῃ περιλαμβάνουσαν, ἐπὶ τὴν Ῥώμην ἠπείγετο παντὶ τῷ στρατῷ, πυνθανόμενος μὲν κἀκείνους ὑπὸ λιμοῦ πιέζεσθαι, ἐλπίζων δὲ τοὺς στρατηγοὺς αὐτῶν ἀπὸ Καπύης ἀναστήσειν, ἢ αὐτός τι Καπύης μεῖζον ἐργάσεσθαι. συντόνῳ δὲ σπουδῇ διελθὼν ἔθνη πολλὰ καὶ πολέμια, τῶν μὲν οὐ δυνηθέντων αὐτὸν ἐπισχεῖν, τῶν δὲ οὐδὲ ἐς πεῖραν ἐλθεῖν ὑποστάντων, ἀπὸ δύο καὶ τριάκοντα σραδίων τῆς Ῥώμης ἐστρατοπέδευσεν ἐπὶ τοῦ Ἀνιῆνος ποταμοῦ.", "st": "8.38"}, {"sp": "N", "t": "καὶ ἡ πόλις ἐθορυβήθη θόρυβον οἷον οὐ πρότερον, οἰκεῖον μὲν οὐδὲν ἔχοντες ἱκανόν (ὃ γὰρ εἶχον, ἐν Καμπανίᾳ τότε ἦν), πολεμίου δὲ στρατοῦ τοσοῦδε σφίσιν ἐπιστάντος ἄφνω, καὶ στρατηγοῦ δι’ ἀρετὴν καὶ εὐτυχίαν ἀμάχου. ὅμως δὲ ἐκ τῶν παρόντων οἱ μὲν δυνάμενοι φέρειν ὅπλα τὰς πύλας ἐφύλασσον, οἱ δὲ γέροντες ἐς τὸ τεῖχος ἀνεπήδων, γύναια δὲ καὶ παιδία λίθους καὶ βέλη παρέφερον. οἱ δὲ ἐκ τῶν ἀγρῶν συνέθεον ἐς τὸ ἄστυ δρόμῳ. βοῆς δὲ παμμιγοῦς καὶ θρήνων καὶ εὐχῶν καὶ παρακελεύσεων πρὸς ἀλλήλους πάντα μεστὰ ἦν. εἰσὶ δ’ αὐτῶν οἳ τὴν γέφυραν τὴν ἐπὶ τοῦ Ἀνιῆνος ἐκδραμόντες ἔκοπτον. μικρὸν δέ τι πολίχνιον Ῥωμαῖοί ποτε ἐπιτειχίζοντες Αἰκανοῖς Ἄλβην ἀπὸ τῆς αὑτῶν μητροπόλεως ἐκάλεσαν· σὺν χρόνῳ δ’ ἐπισύροντες ἢ διαφθείροντες, ἢ ἐς τὴν Ἀλβανῶν σύγκρισιν, Ἀλβησέας αὐτοὺς καλοῦσιν. τούτων τότε τῶν Ἀλβησέων ἐς Ῥώμην δισχίλιοι δρόμῳ διέθεον, τοῦ κινδύνου μετασχεῖν, καὶ ἅμα ἀφικνοῦντο καὶ ὡπλίζοντο καὶ τὰς πύλας ἐφρούρουν. τοσῇδε προθυμίᾳ βραχὺ πολίχνιον ἐκ τοσῶνδε ἀποικιῶν ἐχρήσατο μόνη, οἷόν τι καὶ Ἀθηναίοις ἐς Μαραθῶνα μικρὰ πόλις ἡ Πλαταιέων ἔδραμε τοῦ τότε κινδύνου μετασχεῖν.", "st": "8.39"}, {"sp": "N", "t": "τῶν δὲ στρατηγῶν Ἄππιος μὲν Καπύῃ παρέμενε, κἀκεῖνος ἡγούμενος ἑλεῖν Καπύην, Φούλουιος δὲ Φλάκκος ἑτέραις ὁδοῖς ἐπειχθεὶς ἀλήκτῳ τάχει ἀντεστρατοπέδευσε τῷ Ἀννίβᾳ, μέσον ἔχων τὸν Ἀνιῆνα. τῷ δ’ Ἀννίβᾳ τῆν γέφυραν εὑρόντι λελυμένην καὶ τὸν Φούλουιον ἀντικαθήμενον, ἔδοξε τὰς πηγὰς τοῦ ποταμοῦ περιοδεῦσαι. καὶ ὁ μὲν Φούλουιος ἀντιπαρώδευεν, ὁ δὲ καὶ ὣς ἐνήδρευε, Νομάδας ἱππέας ὑπολιπών, οἱ τῶν στρατῶν ἀναστάντων τὸν Ἀνιῆνα ἐπέρασαν καὶ τὰ Ῥωμαίων ἐδῄουν, μέχρι παρὰ τὴν πόλιν αὐτὴν γενόμενοι καὶ φοβήσαντες ἐπέστρεψαν ἐς Ἀννίβαν· οὕτω γὰρ αὐτοῖς παρήγγελτο. αὐτὸς δὲ ἐπεὶ τάς τε πηγὰς τοῦ ποταμοῦ περιῆλθε, καὶ ὁδὸς ἦν ἐς τὸ ἄστυ οὐ πολλή, λέγεται μὲν νυκτὸς σὺν τρισὶν ὑπασπισταῖς λαθὼν κατασκέψασθαι τὸ ἄστυ, καὶ τὴν τῆς δυνάμεως ἐρημίαν καὶ θόρυβον τὸν ἐπέχοντα ἰδεῖν, ἀναστρέψαι δ’ ἐς Καπύην, εἴτε θεοῦ παράγοντος αὐτὸν ἀεὶ ὡς καὶ τότε, εἴτε τὴν τῆς πόλεως ἀρετὴν καὶ τύχην δείσας, εἴτε, ὡς αὐτὸς τοῖς ἐσβαλεῖν προτρέπουσιν ἔλεγεν, οὐκ ἐθέλων τὸν πόλεμον ἐκλῦσαι δέει Καρχηδονίων, ἵνα μὴ καὶ τὴν στρατηγίαν αὐτὸς ἀποθοῖτο· οὐ γὰρ ὅ γε σὺν Φουλουίῳ στρατὸς ἦν αὐτῷ πάμπαν ἀξιόμαχος. ὁ δὲ Φούλουιος ἀναστρέφοντι παρείπετο, κωλύων τε προνομεύειν καὶ φυλασσόμενος μηδὲν ἐξ ἐνέδρας παθεῖν.", "st": "8.40"}, {"sp": "N", "t": "ὁ δ’ ἐπιτηρήσας νύκτα ἀσέληνον, καὶ χωρίον ἐν ᾧ Φούλουιος ἑσπερας τεῖχος μὲν οὐκ ἔφθανεν ἐγεῖραι, τάφρον δ’ ὀρυξάμενος καὶ διαστήματα ἀντὶ πυλῶν καταλιπὼν καὶ τὸ χῶμα προβαλὼν ἀντὶ τείχους ἡσύχαζεν, ἔς τε λόφον ὑπερκείμενον αὐτοῦ καρτερὸν ἔπεμψε λαθὼν ἱππέας, οἷς εἶρητο ἡσυχάζειν ἕως οἱ Ῥωμαῖοι τὸν λόφον ὡς ἔρημον ἀνδρῶν καταλαμβάνωσι, τοῖς δ’ ἐλέφασι τοὺς Ἰνδοὺς ἐπιβήσας ἐκέλευσεν ἐς τὸ τοῦ Φουλουίου στρατόπεδον ἐσβιάζεσθαι διά τε τῶν διαστημάτων καὶ διὰ τῶν χωμάτων, ὡς δύναιντο. σαλπικτὰς δὲ αὐτοῖς καὶ βυκανητάς τινας ἐξ ὀλίγου διαστήματος ἕπεσθαι κελεύσας, προσέταξεν, ὅταν ἔνδον γένωνται, τοὺς μὲν θόρυβον πολὺν ἐγείρειν περιθέοντας, ἵνα πολλοὶ δόξωσιν εἶναι, τοὺς δε ῥωμαΐζοντας βοᾶν ὅτι Φούλουιος ὁ Ῥωμαίων στρατηγὸς κελεύει, τὸ στρατόπεδον ἐκλιπόντας, ἐπὶ τὸν ἐγγὺς λόφον ἀναπηδᾶν. τόδε μὲν ἦν τὸ στρατήγημα τοῦ Ἀννίβου, καὶ τούτων τὰ μὲν πρῶτα πάντα κατὰ νοῦν ἀπήντησεν· οἵτε γὰρ ἐλέφαντες ἐσῆλθον τοὺς φύλακας καταπατήσαντες, καὶ οἱ σαλπικταὶ τὸ αὑτῶν ἐποίουν, καὶ ὁ θόρυβος Ῥωμαίοις ἐξ εὐνῆς ἀνισταμένοις ἐν μελαίνῃ νυκτὶ ἀδόκητος ἐμπεσὼν ἐπιφοβώτατος ἦν, τῶν τε ῥωμαϊζόντων ἀκούοντες ὅτι παρήγγελται φεύγειν ἐς τὸν λόφον, περὶ τοῦτ’ ἐγίγνοντο.", "st": "8.41"}, {"sp": "N", "t": "Φούλουιος δὲ ἀεί τινα προσδοκῶν ἐνέδραν, καὶ τοῦτο ὑποπτεύων ἐν ἅπασι τοῖς Ἀννίβου, εἴθ’ ὑπ’ οἰκείας τότε συνέσεως, εἴτε θεολήπτῳ γνώμῃ προσπεσών, εἴτε παρ’ αἰχμαλώτου τὰ ἀκριβέστατα μαθών, τοὺς χιλιάρχους ὀξέως ἐπέστησε ταῖς ἐς τὸ λόφον ἀγούσαις ὁδοῖς, κωλύειν τοὺς δι’ αὐτῶν φερομένους, καὶ μεταδιδάσκειν ὅτι τοῦτ’ οὐχ ὁ στρατηγὸς Ῥωμαίων ἀλλ’ Ἀννίβας ἐκήρυξεν ἐνεδρεύων. αὐτὸς δὲ τοῖς χώμασι φυλακὰς ἀκριβεῖς ἐπιστήσας, μή τις ἔφοδος ἔξωθεν ἄλλη γένοιτο, ἐβοηδρόμει μεθ’ ἑτέρων ἀνὰ τὸ στρατόπεδον ἅπαντα ἔχειν ἀσφαλῶς, καὶ ὀλίγους τοὺς μετὰ τῶν ἐλεφάντων ἐσελθόντας εἶναι. δᾷδάς τε ἧπτε καὶ πῦρ πανταχόθεν ἤγειρε, καὶ καταφανὴς ἦν ἡ τῶν ἐσελθόντων ὀλιγότης, ὥστε αὐτῶν πάνυ καταφρονήσαντες οἱ Ῥωμαῖοι, ἐς ὀργὴν ἐκ τοῦ πρὶν δέους μεταβαλόντες, εὐμαρῶς οἷα ψιλοὺς καὶ ὀλίγους διέφθειραν. οἱ δὲ ἐλέφαντες οὐκ ἔχοντες εὐρύχωρον οὐδὲν ἐς ἀναστροφήν, εἰλούμενοι περὶ σκηνὰς καὶ φάτνας, ἐβάλλοντο πρὸς ἁπάντων ἐπιτυχῶς διὰ τὴν στενότητα τοῦ χωρίου καὶ τὸ μέγεθος τῶν σωμάτων, μέχρι περιαλγοῦντές τε καὶ ἀγανακτοῦντες, καὶ ἐπιδραμεῖν ἐς τοὺς πολεμίους οὐκ ἔχοντες, τοὺς ἐπιβάτας σφῶν ἀπεσείοντο καὶ κατεπάτουν σὺν ὀργῇ καὶ βοῇ πάνυ ἠγριωμένοι, καὶ ἐξεπήδων ἐκ τοῦ στρατοπέδου. Φούλουιος μὲν δὴ Φλάκκος εὐσταθῶς καὶ εὐμηχάνως αἰφνιδίῳ συνενεχθεὶς ἐνέδρᾳ περιῆν τοῦ Ἀννίβου, καὶ τὸν στρατὸν περιέσωζεν ἀεὶ πεφρικότα τὰς Ἀννίβου μηχανάς·", "st": "8.42"}, {"sp": "N", "t": "ὁ δ’ Ἀννίβας ἐπεὶ τῆς πείρας ἀπέτυχεν, ἐς Λευκανοὺς διελθὼν ἐχείμαζε, καὶ ἐπὶ τρυφῆς ἦν οὐ συνήθους, ἐρωμένην τε εἶχεν ἄγριος ἀνήρ. καὶ εὐθὺς αὐτῷ κατ’ ὀλίγον ἐτρέπετο πάντα. Φούλουιος δ’ ἐς Καπύην πρὸς τὸν συστράτηγον ἐπανῄει, καὶ τοῖς Καπυαίοις προσέβαλλον ἄμφω καρτερῶς, ἐπειγόμενοι χειμῶνος ἑλεῖν τὴν πόλιν, ἕως Ἀννίβας ἠρεμεῖ. Καπυαῖοι δέ, τῶν τροφῶν σφᾶς ἐπιλειπουσῶν καὶ οὐδαμόθεν ἄλλων ἐπεισαγομένων, ἐνεχείρισαν ἑαυτοὺς τοῖς στρατηγοῖς· ἐνεχείρισαν δὲ καὶ ὅσοι Λιβύων αὐτοὺς ἐφρούρουν, αὐτοῖς στρατηγοῖς, Ἄννωνι ἑτέρῳ καὶ Βώσταρι. Ῥωμαῖοι δὲ τῇ μὲν πόλει φρουρὰν ἐπέστησαν, καὶ ὅσους ηὗρον αὐτομολοῦντας, χεῖρας αὐτῶν ἀπέτεμον· Λιβύων δὲ τοὺς μὲν ἐπιφανεῖς ἐς Ῥώμην ἔπεμψαν, τοὺς δὲ λοιποὺς ἀπέδοντο. καὶ Καπυαίων αὐτῶν τοὺς μὲν αἰτίους μάλιστα τῆς ἀποστάσεως ἀπέκτειναν, τῶν δ’ ἄλλων τὴν γῆν ἀφείλοντο μόνον. εὔφορος δ’ ἐστὶν ἐς σῖτον ἡ περὶ τὴν Καπύην πᾶσα· πεδιὰς γάρ ἐστιν. Καπύη μὲν δὴ πάλιν ἐς Ῥωμαίους ἐπανῆκτο, καὶ μέγα τοῦτο Λιβύων ἐς τὴν Ἰταλίαν πλεονέκτημα περιῄρητο.", "st": "8.43"}, {"sp": "N", "t": "ἐν δὲ Βρεττίοις, οἳ μέρος εἰσὶ τῆς Ἰταλίας, ἀνὴρ ἐκ πόλεως Τισίας φρουρουμένης ὑπὸ τῶν Λιβύων, ἐθίσας ἀεί τι λῄζεσθαι καὶ φέρειν τῷ φρουράρχῳ, καὶ παρὰ τοῦτο αὐτῷ συνήθης ἐς πάντα γεγονὼς καὶ σχεδὸν συστράτηγος, ἤλγει τῶν φρουρῶν ἐς τὴν πατρίδα ὑβριζόντων συνθέμενος οὖν τῷ Ῥωμαίων στρατηγῷ, καὶ πιστὰ δοὺς καὶ λαβών, ἑκάστοτέ τινας ὡς αἰχμαλώτους ἐσῆγεν ἐς τὴν ἄκραν, καὶ τὰ ὅπλα αὐτῶν ἐσέφερεν ὡς σκῦλα. ἐπεὶ δὲ πλέονες ἐγένοντο, ἐξέλυσεν αὐτοὺς καὶ ὥπλισε, καὶ τὴν Λιβύων φρουρὰν ἀνεῖλε, καὶ παρὰ Ῥωμαίων ἄλλην ἐσηγάγετο. Ἀννίβου δὲ οὐ πολὺ ὕστερον παροδεύοντος αὐτούς, οἱ μὲν φρουροὶ καταπλαγέντες ὑπὸ τοῦ δέους ἐξέφυγον ἐς Ῥήγιον, οἱ δὲ Τισιᾶται παρέδωκαν αὑτοὺς τῷ Ἀννίβᾳ. καὶ ὁ Ἀννίβας τοὺς μὲν αἰτίους τῆς ἀποστάσεως ἔκαυσε, τῇ δὲ πόλει φρουρὰν ἐπέστησεν ἄλλην.", "st": "8.44"}, {"sp": "N", "t": "Ἰαπύγων δ’ ἐν πόλει Σαλαπίᾳ, Λιβύων ὑπηκόῳ, δύο ἤστην ἄνδρε τῶν μὲν ἄλλων γένει καὶ πλούτῳ καὶ δυνάμει διαφέροντε, ἀλλήλοιν δ’ ἐκ πολλοῦ διαφόρω. τούτοιν Δάσιος μὲν τὰ Λιβύων ᾑρεῖτο, Βλάτιος δὲ τὰ Ῥωμαίων. ἕως μὲν οὖν ἤκμαζε τὰ Ἀννίβου, ἐφ’ ἡσυχίας ἦν ὁ Βλάτιος· ἐπεὶ δὲ ἠγείρετο τὸ Ῥωμαίων καὶ τὰ πολλὰ τῆς ἐσφετερισμένης ἀρχῆς ἀνελάμβανον, ἔπειθεν ὁ Βλάτιος τὸν ἐχθρὸν ὑπὲρ τῆς πατρίδος αὑτῷ συμφρονῆσαι μόνης, μή τι πάθοι, Ῥωμαίων αὐτὴν βίᾳ λαβόντων, ἀνήκεστον. ὁ δ’ ὑποκρινάμενος συντίθεσθαι, κατεμήνυσε τοῦτο Ἀννίβᾳ. καὶ ἐδίκαζεν αὐτοῖς ὁ Ἀννίβας, Δασίου μὲν κατηγοροῦντος, Βλατίου δ’ ἀπολογουμένου καὶ συκοφαντεῖσθαι διὰ τὴν ἔχθραν λέγοντος· ὃ καὶ τέως ἄρα προορῶν ἐτόλμησεν ἐχθρῷ προσενεγκεῖν λόγον τοιόνδε, ὡς ἀπίστῳ κατηγόρῳ διὰ τὴν ἔχθραν ἐσομένῳ. Ἀννίβας δ’ οὔτε ἀπορρῖψαι τὸ ἔργον οὔτε τῷ παρ’ ἐχθροῦ πιστεῦσαι ῥᾳδίως ἀξιῶν, μεθίστατο αὐτοὺς ὡς σκεψόμενος ἐφ’ ἑαυτοῦ. στενῆς δὲ τῆς ἐξόδου πάμπαν οὔσης, ὁ Βλάτιος ἔφη τῷ Δασίῳ, τοὺς ἄλλους λαθών, “οὐ σώσεις, ὦ ἀγαθέ, τὴν πατρίδα;” ὁ δὲ καὶ τοῦτ’ εὐθὺς ἐκβοήσας ἐμήνυεν.", "st": "8.45"}, {"sp": "N", "t": "καὶ ὁ Βλάτιος οἰκτισάμενος τότε μάλιστα ἀξιοπίστως εἶπεν ὡς ἐπιβουλεύοιτο ὑπ’ ἐχθροῦ τεχνίτου. “τοῦτο δ’,” ἔφη, “τὸ νῦν ἐπιβούλευμα καὶ τῆς πρότερον ἀμφιλογίας, εἴ τις ἦν, ῥύσεταί με. τίς γὰρ ἂν ἢ πρότερον ἐχθρῷ περὶ τοιῶνδε διεπίστευσεν, ἢ νῦν, εἰ καὶ τέως ἐπεπλάνητο, ἀπίστῳ καὶ κατηγόρῳ περὶ ἐκεῖνα γεγενημένῳ, κινδυνεύων ἔτι καὶ κρινόμενος καὶ ἀρνούμενος, αὖθις ἂν τὰ δεύτερα ταῦτ’ ἐθάρρησεν εἰπεῖν, καὶ μάλιστ’ ἐν τῷ δικαστηρίῳ, πολλῶν μὲν ἀκοῦσαι δυναμένων, τοῦ δὲ κατηγόρου καὶ τόδε μέλλοντος εὐθὺς ὁμοίως ἐρεῖν; εἰ δὲ δὴ καὶ ἐγεγένητο,” ἔφη, “χρηστὸς ἐξαίφνης καὶ φίλος, τί μοι συλλαβεῖν ὑπὲρ τῆς πατρίδος ἔτι δυνατὸς ἦν; τί δ’ ἂν ἐδεόμην ἐγὼ μηδὲν ἐπικουρεῖν δυναμένου;” ἅ μοι δοκεῖ προϊδὼν πάλιν ὁ Βλάτιος ψιθύρως ἐντυχεῖν τῷ Δασίῳ, καὶ ἐς ἀπιστίαν αὐτὸν ἐμβαλεῖν μείζονα, ἐπαγαγέσθαι δ’ ἐκ τοῦδε καὶ Ἀννίβαν ἐς ἀπιστίαν τῶν πρότερον εἰρημένων. οὐ μὴν οὐδὲ ἐκφυγὼν τὴν δίκην ὁ Βλάτιος ἀφίστατο μὴ μεταπείθειν τὸν ἐχθρόν, καταφρονῶν ἄρα ὡς ἐς πάντα γεγονότος ἀπίστου. ὁ δὲ αὖθις ὑπεκρίνετο συντίθεσθαι, καὶ τὴν ἐπίνοιαν τῆς ἀποστάσεως ᾔτει μαθεῖν. ὁ δὲ οὐδὲν ὀκνήσας ἔφη, “διαδραμοῦμαι μὲν ἐπί τι τῶν στρατοπέδων ἐγὼ τῶν Ῥωμαϊκῶν (μηνύσας αὐτῷ τὸ πάνυ πορρωτάτω) καὶ στρατιὰν ἄξω λαβών· ἔστι γάρ μοι φίλος ὁ στρατηγὸς ἐκείνου τοῦ στρατοῦ· σὺ δ’ ὑπομένειν μοι δεῦρο, καὶ τὰ ἔνδον ἐπιτηρεῖν.”", "st": "8.46"}, {"sp": "N", "t": "ὁ μὲν εἶπεν οὕτω, καὶ εὐθὺς ἐξέδραμε, λαθὼν Δάσιον, οὐκ ἐς ἐκεῖνο τὸ στρατόπεδον ἀλλ’ ἐς Ῥώμην, ὁδὸν ἐλάσσονα. καὶ δοὺς τῇ βουλῇ τὸν υἱὸν ὅμηρον, ἱππέας ᾔτει χιλίους, μεθ’ ὧν ἠπείγετο κατὰ σπουδήν, τὸ μέλλον ἔσεσθαι προορώμενος. ὁ δὲ Δάσιος ταῖς ἐπιούσαις ἡμέραις τὸν ἐχθρὸν οὐχ ὁρῶν, εἴκασεν αὐτὸν ἐγχειρεῖν τοῖς ἐγνωσμένοις ὡς ἤδη πιστεύοντα αὐτῷ. νομίσας οὖν ἐς ἐκεῖνο τῷ ὄντι τὸ πορρωτέρω στρατόπεδον αὐτὸν οἴχεσθαι, διέδραμε πρὸς Ἀννίβαν, καταφρονῶν ὅτι φθάσει ἐκεῖνον ἐπανελθών, καὶ “νῦν μέν,” ἔφη, “παραδώσω σοι τὸν Βλάτιον ἐπ’ αὐτοφώρῳ στρατιὰν ἐπάγοντα τῇ πόλει.” καὶ τὸ γεγονὸς ἐκθέμενος, καὶ λαβών τινας, ἐπανῆγεν ἐς τὴν πατρίδα μετὰ σπουδῆς ὡς οὔπω τοῦ Βλατίου πλησιάζοντος. ὁ δ’ ἔνδον τε ἦν ἄρτι, καὶ τὴν φρουρὰν τὴν Λιβύων ὀλίγην οὖσαν ἀνελὼν ἐφύλασσε μηδένα παρελθεῖν, καὶ πύλας τὰς μὲν ἄλλας ἐκεκλείκει, τὰς δ’ ἐς τὴν ἐπάνοδον Δασίου μόνας εἴασεν ἀνεῷχθαι. καὶ τὸ κατ’ ἐκείνας μέρος ἅπαν εἶχεν ἀνυπόπτως· τὰ δ’ ἐντὸς ἐξετετάφρευτο καὶ διείληπτο, ὡς μὴ δύνασθαι τοὺς ἐμπεσόντας ἐς ὅλην διαδραμεῖν. Δάσιος δὲ ἐπεὶ τὰς πύλας εἶδεν ἀνεῳγμένας, ἥσθη νομίσας προλαβεῖν τὸν ἐχθρόν, καὶ ἐσήλατο γεγηθώς. ὁ δ’ ἐπικλείσας διέφθειρεν αὐτόν τε καὶ τοὺς ἐσδραμόντας, ὠθουμένους ἐν στενῷ καὶ διαδρομὴν διὰ τὰς τάφρους οὐκ ἔχοντας. ὀλίγοι δ’ αὐτῶν διὰ τοῦ τείχους ἐξαλόμενοι διέφυγον.", "st": "8.47"}, {"sp": "N", "t": "καὶ Βλάτιος μὲν οὕτω περιῆν Δασίου, τρὶς ἀντενεδρεύων, Φούλουιος δὲ Ῥωμαίων ὕπατος Ἐρδονίαν ἐπολιόρκει· καὶ αὐτὸν Ἀννίβας ἔλαθεν ἑσπέρας ἐγγὺς γενόμενος, καὶ ἀπεῖπε πυρὰ μὴ καίειν, καὶ σιωπὴν παρήγγειλεν. περὶ δὲ ἕω, γενομένης ὁμοῦ τι καὶ ὁμίχλης, τοὺς μὲν ἱππέας ἔπεμψεν ἐπιχειρεῖν τῷ Ῥωμαίων στρατοπέδῳ, καὶ αὐτοὺς ἠμύνοντο ἐκεῖνοι, σὺν θορύβῳ μὲν ὡς ἀπ’ εὐνῆς, σὺν θάρσει δὲ οἷα ὀλίγους ποθὲν αὑτοῖς ἐπιφανέντας. ὁ δ’ Ἀννίβας ἐπὶ θάτερα τῷ πεζῷ τὴν πόλιν περιῄει, κατασκεπτόμενος ἅμα καὶ τοὺς ἔνδον ἐπελπίζων, ἕως ἐπῆλθε τοῖς Ῥωμαίοις ἐν τῇ περιόδῳ, εἴτε προιδόμενος εἴτε κατὰ συντυχίαν, κυκλούμενος αὐτούς. οἱ δ’ ἔπιπτον ἤδη λάβρως καὶ ἀθρόως, ἀμφίβολοι γεγονότες· καὶ ἀπέθανον αὐτῶν ἐς ὀκτακισχιλίους, καὶ ὁ ὕπατος αὐτὸς ὁ Φούλουιος. οἱ λοιποὶ δ’ ἔς τι χῶμα πρὸ τοῦ στρατοπέδου ἀναθορόντες αὐτό τε διέσωσαν, γενναίως ἀμυνόμενοι, καὶ τὸν Ἀννίβαν ἐκώλυσαν λαβεῖν τὸ στρατόπεδον.", "st": "8.48"}, {"sp": "N", "t": "μετὰ δὲ τοῦτο Ῥωμαῖοι μὲν τὴν Ἰαπύγων ἀποστάντων ἐδῄουν, Ἀννίβας δὲ τὴν Καμπανῶν, ἐς Ῥωμαίους μεταθεμένων χωρὶς Ἀτέλλης μόνης. καὶ Ἀτελλαίους μετῴκιζεν ἐς Θουρίους, ἵνα μὴ τῷ Βρεττίων καὶ Λευκανῶν καὶ Ἰαπύγων ἐνοχλοῖντο πολέμῳ. καὶ Ῥωμαῖοι τοὺς ἐκ Νουκερίας ἐκπεσόντας ἐν Ἀτέλλῃ μετῴκιζον· ἔς τε τὴν Ἀννίβου ἔτι ὑπήκοον ἐσβαλόντες, Αὐλωνίαν τε εἷλον καὶ τὴν Βρεττίων γῆν ἐπέτρεχον, καὶ Τάραντα φρουρουμένην ὑπὸ Καρθάλωνος ἐκ γῆς καὶ θαλάσσης ἐπολιόρκουν. ὁ δὲ Καρθάλων, ὀλίγων Καρχηδονίων παρόντων, Βρεττίους ἐς τὴν φρουρὰν προσέλαβεν. τῶν δὲ Βρεττίων ὁ φρούραρχος ἤρα γυναικός, ἧς ἀδελφὸς ὑπὸ Ῥωμαίοις στρατευόμενος ἔπραξε διὰ τῆς ἀδελφῆς τὸν φρούραρχον ἐνδοῦναι Ῥωμαίοις, ἐπάγουσι τὰς μηχανὰς ᾗ τοῦ τείχους αὐτὸς ἐφρούρει. Τάραντα μὲν δὴ Ῥωμαῖοι τόνδε τὸν τρόπον ἀνέλαβον, εὔκαιρον ἐς πολέμους χωρίον καὶ κατὰ γῆν καὶ κατὰ θάλασσαν.", "st": "8.49"}, {"sp": "N", "t": "Ἀννίβας δὲ ἐπειγόμενος ἐς αὐτήν, ὡς ἔμαθεν εἰλημμένην, παρῆλθεν ἀχθόμενος ἐς Θουρίους κἀκεῖθεν ἐς Οὐενουσίαν, ἔνθα αὐτῷ Κλαύδιός τε Μάρκελλος ὁ Σικελίαν ἑλών, πέμπτον ὑπατεύων τότε, καὶ Τίτος Κρισπῖνος ἀντιστρατοπεδεύοντες οὐκ ἐτόλμων ἄρχειν μάχης. λείαν δέ τινα ὑπὸ Νομάδων ἀγομένην Μάρκελλος ἰδών, καὶ δόξας ὀλίγους εἶναι τοὺς ἄγοντας, ἐπέδραμεν αὐτοῖς μετὰ τριακοσίων ἱππέων σὺν καταφρονήσει, καὶ πρῶτος ἡγεῖτο, θυμικὸς ὢν ἐς μάχας καὶ παρακινδυνευτικὸς ἀεί. ἄφνω δὲ πολλῶν τῶν Λιβύων φανέντων καὶ πανταχόθεν αὐτῷ προσπεσόντων, οἱ μὲν οὐραγοῦντες Ῥωμαίων πρῶτοι φυγῆς ἦρχον, ὁ δὲ Μάρκελλος, ὡς ἑπομένων αὐτῶν, ἐμάχετο γενναίως, μέχρι κατακοντισθεὶς ἀπέθανεν. καὶ αὐτοῦ τῷ σώματι ὁ Ἀννίβας ἐπιστάς, ὡς εἶδε τὰ τραύματα πάντα ἐπὶ τῶν στέρνων, ἐπῄνεσε μὲν ὡς στρατιώτην, ἐπέσκωψε δὲ ὡς στρατηγόν. καὶ τὸν δακτύλιον αὐτοῦ περιελών, τὸ μὲν σῶμα ἔκαυσε λαμπρῶς, καὶ τὰ ὀστᾶ τῷ παιδὶ προσέπεμψεν ἐς τὸ Ῥωμαίων στρατόπεδον·", "st": "8.50"}, {"sp": "N", "t": "Σαλαπίνοις δὲ μηνίων εὐθὺς ἐτύπωσεν ἐπιστολὴν τῇ σφραγῖδι Μαρκέλλου, πρὶν αἰσθέσθαι πολλοὺς περὶ τοῦ θανάτου, καὶ αὐτόμολον ἄνδρα Ῥωμαῖον ἔπεμψε φέρειν, δηλοῦντα ὅτι στρατιὰ Μαρκέλλου κατόπιν ἔρχοιτο, καὶ ὁ Μάρκελλος αὐτὴν ὑποδέξασθαι κελεύοι. ἄρτι δ’ εἰλήφεσαν Κρισπίνου γράμματα, περιπέμψαντος ἐς ἅπαντας ὅτι τῆς Μαρκέλλου σφραγῖδος Ἀννίβας κεκρατήκοι. τὸν οὖν ἄγγελον, ἵνα μὴ παραμένων ἐπιγνοίη τὰ γιγνόμενα, ἀπέπεμψαν ὑποσχόμενοι τὰ προστασσόμενα ποιήσειν, αὐτοὶ δ’ ὁπλισάμενοι τὴν ἐνέδραν ἐπὶ τῶν τειχῶν ἀνέμενον. καὶ προσιόντος τοῦ Ἀννίβου μετὰ Νομάδων, οὓς Ῥωμαϊκοῖς ὅπλοις ἐσκεύασε, τὰς μὲν πύλας ἐκ μηχανήματος ἀνέσπασαν ὡς δὴ Μαρκέλλου προσιόντος ἀσμενίζοντες, ἐσδεξάμενοι δὲ ὅσων εὐμαρῶς κρατήσειν ἔμελλον, αὖθις ἐκ τοῦ μηχανήματος αὐτὰς ἐπικαθῆκαν, καὶ τοὺς μὲν ἐσελθόντας ἔκτειναν, τοὺς δ’ ἔξω τῶν τειχῶν ἔτι περιεστῶτας ἄνωθεν ἔβαλλόν τε καὶ κατετίτρωσκον. καὶ δευτέρας τῆσδε πείρας ὁ Ἀννίβας ἐπὶ τῇ πόλει σφαλεὶς ἀπεχώρει.", "st": "8.51"}, {"sp": "N", "t": "ἐν τούτῳ δὲ καὶ Ἀσδρούβας ὁ ἀδελφὸς Ἀννίβου, τὴν στρατιὰν ἣν ἐξενάγησεν ἐν τοῖς Κελτίβηρσιν ἔχων, διέβαινεν ἐς τὴν Ἰταλίαν, καὶ Κελτῶν φιλίως αὐτὸν δεχομένων τὰ Ἄλπεια ὄρη, ὡδοποιημένα πρότερον ὑπὸ Ἀννίβου, διώδευε δύο μησίν, ὅσα τέως Ἀννίβας ἓξ διῆλθεν. ἐσέβαλέ τε ἐς Τυρρηνίαν ἄγων πεζοὺς μὲν τετρακισμυρίους ἐπὶ ὀκτακισχιλίοις, ἱππέας δὲ ὀκτακισχιλίους καὶ ἐλέφαντας πεντεκαίδεκα. καὶ γράμματα πρὸς τὸν ἀδελφὸν ἔπεμπε, δηλῶν ὅτι παρείη. τούτων τῶν γραμμάτων ὑπὸ Ῥωμαίων ἁλόντων, οἱ ὕπατοι Σαλινάτωρ καὶ Νέρων μαθόντες αὐτοῦ τὸ πλῆθος τῆς στρατιᾶς ἀπὸ τῶν γραμμάτων, συνῆλθον ἐς τὸ αὐτὸ πάσαις ταῖς δυνάμεσι, καὶ ἀντεστρατοπέδευσαν αὐτῷ περὶ πόλιν Σήνας. ὁ δ’ οὔπω μάχεσθαι κεκρικώς, ἀλλὰ τῷ ἀδελφῷ συνελθεῖν ἐπειγόμενος, ὑπεχώρει. καὶ νυκτὸς ἀναζεύξας περὶ ἕλη καὶ τέλματα καὶ ποταμὸν οὐκ εὔπορον ἠλᾶτο, μέχρι φανείσης ἡμέρας οἱ Ῥωμαῖοι καταλαβόντες αὐτοὺς διερριμμένους τε καὶ κεκμηκότας ὑπ’ ἀγρυπνίας καὶ κόπου, πλείστους μὲν αὐτῶν ἅμα τοῖς ταξιάρχοις συντασσομένους ἔτι καὶ συνιόντας διέφθειραν, καὶ αὐτὸν ἐπ’ ἐκείνοις Ἀσδρούβαν, πλείστους δ’ αἰχμαλώτους ἔλαβον, καὶ μεγάλου δέους ἀπήλλαξαν τὴν Ἰταλίαν, ἀμάχου ἂν σφίσι του Ἀννίβου γενομένου, εἰ καὶ τήνδε τὴν στρατιὰν προσέλαβεν.", "st": "8.52"}, {"sp": "N", "t": "θεὸς δέ μοι δοκεῖ τόδε Ῥωμαίοις ἀντιδοῦναι τῆς ἐπὶ Κάνναις ἀτυχίας, οὐ πόρρω τε ἐπ’ ἐκείνῃ καὶ ἰσοστάσιόν πως ἐκείνῃ γενόμενον· στρατηγοί τε γὰρ οἱ ἑκατέρων ἀπώλοντο, καὶ στρατοῦ πλῆθος ἐγγυτάτω μάλιστα ἐπ’ ἴσης, καὶ τὰ αἰχμάλωτα πολλὰ γενέσθαι καὶ τοῖσδε κἀκείνοις συνηνέχθη, στρατοπέδων τε καὶ παρασκευῆς τῆς ἀλλήλων δαψιλοῦς ἐκράτουν ἑκάτεροι. οὕτω παραλλὰξ ἡ πόλις εὐτυχιῶν καὶ συμφορῶν ἐπειρᾶτο. Κελτιβήρων δ’ ὅσοι διέφυγον ἐκ τοῦ κακοῦ, οἱ μὲν ἐς τὰ οἰκεῖα οἱ δ’ ἐς Ἀννίβαν ἐχώρουν.", "st": "8.53"}, {"sp": "N", "t": "ὁ δ’ ἐπί τε τῷ ἀδελφῷ καὶ στρατιᾷ τοσῇδε δι’ ἀπειρίαν ὁδῶν αἰφνίδιον ἀπολωλυίᾳ δυσφορῶν, καὶ τεσσαρεσκαιδέκατον ἔτος ἔχων ἐν πονοις ἀτρύτοις ἐξ οὗ Ῥωμαίοις ἐν Ἰταλίᾳ διεπολέμει, πάντων τε ὧν εἰλήφει πρότερον ἐκπεπτωκώς, ἐς Βρεττίους, ὅπερ αὐτῷ λοιπὸν ἔθνος ὑπήκοον ἦν, ἀνεχώρει, καὶ ἡσύχαζεν ὡς ἑτέρας δυνάμεως ἀφιξομένης ἀπὸ Καρχηδόνος. οἱ δ’ ἔπεμψαν μὲν αὐτῷ ναῦς ἑκατὸν στρογγύλας, ἐφ’ ὧν σῖτός τε ἦν καὶ στρατιὰ καὶ χρήματα, οὐδενὸς δ’ ἐρετικοῦ παραπέμποντος αὐτὰς ἄνεμος ἐς Σαρδόνα κατήνεγκε, καὶ ὁ τῆς Σαρδόνος στρατηγὸς ἐπιπλεύσας μακραῖς ναυσὶ κατέδυσε μὲν αὐτῶν εἴκοσιν, ἑξήκοντα δ’ ἔλαβεν· αἱ δὲ λοιπαὶ διέφυγον ἐς Καρχηδόνα. καὶ ὁ Ἀννίβας ἔτι μᾶλλον ἀπορούμενός τε καὶ τὰ παρὰ Καρχηδονίων ἀπεγνωκώς, οὐδὲ Μάγωνος αὐτῷ τι, τοῦ ξενολογοῦντος ἐν Κελτοῖς καὶ Λίγυσιν, ἐπιπέμποντος, ἀλλὰ τὸ μέλλον ἔσεσθαι περιορωμένου, συνιδὼν ὅτι μένειν ἐπὶ πλεῖον οὐ δυνήσεται, αὐτῶν ἤδη Βρεττίων ὡς ἀλλοτρίων ὅσον οὔπω γενησομένων κατεφρόνει, καὶ ἐσφορὰς ἐπέβαλλεν αὐτοῖς πάνυ πολλάς, τάς τε ὀχυρὰς τῶν πόλεων μετῴκιζεν ἐς τὰ πεδινὰ ὡς βουλευούσας ἀπόστασιν, πολλούς τε τῶν ἀνδρῶν αἰτιώμενος διέφθειρεν, ἵνα τὰς περιουσίας αὐτῶν σφετερίζοιτο.", "st": "8.54"}, {"sp": "N", "t": "καὶ ὁ μὲν ἐν τούτοις ἦν, ἐν δὲ Ῥώμη γίγνονται μὲν ὕπατοι Λικίνιός τε Κράσσος καὶ Πόπλιος Σκιπίων ὁ λαβὼν Ἰβηρίαν, τούτων δὲ Κράσσος μὲν ἀντεστρατοπέδευσεν Ἀννιβᾳ περὶ Ἰαπυγίαν, Σκιπίων δὲ τὸν δῆμον ἐδίδασκεν οὔ ποτε Καρχηδονίους οὐδ’ Ἀννίβαν ἀποστήσεσθαι σφίσιν ἐνοχλοῦντας ἀμφὶ τὴν Ἰταλίαν, εἰ μὴ Ῥωμαίων στρατὸς ἐς Λιβύην διέλθοι καὶ κίνδυνον αὐτοῖς ἐπιστήσειεν οἰκεῖον. λιπαρήσας τε πάνυ καρτερῶς, καὶ πείσας ὀκνοῦντας, ᾑρέθη στρατηγὸς αὐτὸς ἐς Λιβύην, καὶ διέπλευσεν εὐθὺς ἐς Σικελίαν. ἔνθα στρατὸν ἀγείρας τε καὶ γυμνάσας ἐπέπλευσε Λοκροῖς ἄφνω τοῖς ἐν Ἰταλίᾳ, φρουρουμένοις ὑπὸ Ἀννίβου· καὶ τὴν φρουρὰν κατασφάξας τε, καὶ παραδοὺς Πλημινίῳ τὴν πόλιν, αὐτὸς ἐς Λιβύην διέπλευσεν. Πλημίνιος δὲ οὐδεμίαν ὕβριν ἢ ἀσέλγειαν ἢ ὠμότητα ἐς τοὺς Λοκροὺς ἐκλιπών, ἐσύλησε λήγων καὶ τὸ τῆς Φερσεφόνης ἱερόν. καὶ τόνδε μὲν Ῥωμαῖοι μετὰ τῶν συναμαρτόντων αὐτῷ φίλων διέφθειραν ἐν τῷ δεσμωτηρίῳ, καὶ τὰς περιουσίας αὐτῶν ἔδοσαν Λοκροῖς ἐς τὸν θησαυρὸν τῆς θεοῦ φέρειν· ὅσα τε ἄλλα ἐδύναντο τῶν ἀπολωλότων ἀνευρόντες, τὸ λεῖπον ἐκ τοῦ κοινοῦ σφῶν ταμιείου τῇ θεῷ προσέθεσαν.", "st": "8.55"}, {"sp": "N", "t": "τοῦ δὲ αὐτοῦ χρόνου Κωνσεντίαν τε, μεγάλην πόλιν Βρεττίων, καὶ ἄλλας ἓξ ἐπ’ αὐτῇ περιέσπασεν ἀπὸ Ἀννίβου Κράσσος. καὶ γιγνομένων ἐν Ῥώμῃ σημείων ἐκ Διὸς φοβερῶν, οἱ μὲν τὰ Σιβύλλεια ἐπισκεπτόμενοι δέκα ἄνδρες ἔφασαν ἐξ οὐρανοῦ τι ἐς Πεσινοῦντα τῆς Φρυγίας, ἔνθα σέβουσιν οἱ Φρύγες θεῶν μητέρα, πεσεῖσθαι τῶνδε τῶν ἡμερῶν, καὶ δεῖν αὐτὸ ἐς τὴν Ῥώμην ἐνεχθῆναι. μετ’ οὐ πολὺ δὲ πεσεῖν τε προσηγγέλθη καὶ ἐς Ῥώμην ἐκομίσθη τὸ βρέτας. καὶ τὴν ἡμέραν ἑορτάζουσι καὶ νῦν μητρὶ θεῶν, ᾗ τότε ἐκομίσθη. λέγεται δὲ τὴν ναῦν, ἣ ἔφερεν αὐτό, ἰλύι τοῦ ποταμοῦ τοῦ Τιβέριος ἐνσχεθεῖσαν οὐδεμιᾷ μηχανῇ σαλεύεσθαι, μέχρι, τῶν μάντεων προειπόντων ἕψεσθαι μόνως εἰ γυνὴ καθαρεύουσα ξένων ἀνδρῶν ἑλκύσειε, Κλαυδίαν Κόινταν, μοιχείας ἔγκλημα ἔχουσαν ἔτι ἄκριτον, καὶ δι’ ἀσωτίαν ἐς αὐτὸ πιθανωτάτην οὖσαν, ἐπιθειάσαι τε πολλὰ περὶ τῆς ἀναμαρτησίας, καὶ ἀναδήσασθαι τῇ μίτρᾳ τὸ σκάφος. καὶ ἡ θεὸς ἕσπετο. Κλαυδία μὲν δὴ ἐξ αἰσχίστης δόξης ἐς ἀρίστην μετέβαλε, Ῥωμαίοις δὲ καὶ πρὸ τῆς Κλαυδίας ἐκέλευε τὰ Σιβύλλεια διὰ τοῦ παρὰ σφίσιν ἀρίστου τὸ βρέτας ἐκ Φρυγίας μεταγαγεῖν, καὶ τὸν ἄριστον ἐν τῷ τότε σφίσι δοκοῦντα εἶναι, Σκιπίωνα τὸν Νασικᾶν ἐπίκλην, ἐπεπόμφεσαν, υἱὸν μὲν ὄντα Γναίου Σκιπίωνος τοῦ στρατηγήσαντος ἐν Ἰβηρίᾳ καὶ ἐν αὐτῇ πεσόντος, ἀνεψιὸν δὲ Σκιπίωνος τοῦ Καρχηδονίους ἀφελομένου τὴν ἡγεμονίαν καὶ πρώτου κληθέντος Ἀφρικανοῦ. ὧδε μὲν ἡ θεὸς ἐς Ῥώμην δι’ ἀνδρῶν καὶ γυναικῶν ἀρίστων ἀφικνεῖτο.", "st": "8.56"}, {"sp": "N", "t": "ἐν δὲ Λιβύῃ Καρχηδονίων συνεχῶς ὑπὸ τοῦδε τοῦ Σκιπίωνος ἡττωμένων, ὅσοι Βρεττίων ταῦτ’ ἐγίγνωσκον, ἀφίσταντο ἀπὸ τοῦ Ἀννίβου, καὶ τὰς φρουρὰς οἱ μὲν ἔκτεινον, οἱ δ’ ἐξέβαλλον. οἱ δὲ οὐδέτερα τούτων δυνάμενοι λάθρᾳ πρὸς τὴν σύγκλητον ἐπρέσβευον, τὴν μὲν ἀνάγκην αὑτῶν καὶ τὴν προαίρεσιν ὑποδεικνύοντες. Ἀννίβας δὲ ἐς μὲν Πετηλίαν ἔνοπλος παρῆλθεν, οὐκέτι Πετηλίνων ἐχόντων αὐτήν· ἐκβαλὼν γὰρ αὐτοὺς ἐδεδώκει Βρεττίοις. ᾐτιᾶτο δ’ ὅτι ἐπρέσβευσαν ἐς Ῥώμην, ἀρνουμένων δ’ ἐκείνων ὑπεκρίνετο πιστεύειν. “ἵνα δ’,” ἔφη, “μηδ’ ὑπονοῆσθε,” τοὺς μὲν δυνατοὺς παρέδωκε τοῖς Νομάσι, κεχωρισμένως τηρεῖν αὐτῶν ἕκαστον, τοῦ δὲ πλήθους τὰ ὅπλα παρείλετο, τοὺς δὲ δούλους καθοπλίσας ἐπέστησε τῇ πόλει φύλακας. καὶ τούτοις ὅμοια τὰς ἄλλας πόλεις ἐπιὼν ἐποίει. Θουρίων δὲ τρισχιλίους Καρχηδονίοις μάλιστα εὔνους ἐξελόμενος, καὶ πεντακοσίους ἄλλους ἀπὸ τῶν ἀγρῶν, τὰ λοιπὰ τῇ στρατιᾷ διαρπάζειν ἔδωκεν. καὶ τῆς πόλεως ἐγκρατῆ φρουρὰν καταλιπών, ἐς Κρότωνα τοὺς τρισχιλίους καὶ πεντακοσίους μετῴκιζε, τὴν πόλιν εὔκαιρον ἡγούμενος εἶναι, καὶ ταμιεῖον αὐτὴν ἑαυτῷ καὶ ὁρμητήριον ἐπὶ τὰς ἄλλας τιθεμενος.", "st": "8.57"}, {"sp": "N", "t": "Καρχηδονίων δ’ αὐτὸν μετακαλούντων κατὰ σπουδὴν ἐπικουρεῖν κινδυνευούσῃ τῇ πατρίδι ὑπὸ Σκιπίωνος, καὶ τὸν ναύαρχον Ἀσδρούβαν ἐπ’ αὐτόν, ἵνα μὴ βραδύνειε, πεμψάντων, ἤχθετο μὲν τῆς Καρχηδονίων ἐς τοὺς ἄρχοντας ἀπιστίας τε καὶ ἀχαριστίας ἐς πεῖραν ἐρχόμενος διὰ μακροῦ, καὶ τὴν αἰτίαν ἐδεδοίκει τοῦ τοσοῦδε πολέμου πρῶτος ἐμβαλὼν ἐν Ἰβηρίᾳ, ἐγνώκει δ’ ὑπ’ ἀνάγκης ὅμως ἕπεσθαι, καὶ ναῦς εἰργάζετο πολλάς, εὐξύλου τῆς Ἰταλίας οὔσης. τῶν δ’ ἔτι ὑπηκόων οἱ πόλεων ὡς ἀλλοτρίων καταφρονῶν, ἔγνω διαρπάσαι πάσας, καὶ τὴν στρατιὰν πλουτίσας, εὔνουν ἐς τὰς ἐν Καρχηδόνι συκοφαντίας ἐπαγαγέσθαι. αἰδούμενός τε αὐτὸς παρασπονδεῖν, Ἀσδρούβαν τὸν ναύαρχον ἐπὶ προφάσει περιέπεμπε, τοὺς φρουροῦντας ὀψόμενον. ὁ δὲ ἐς ἑκάστην πόλιν ἐσιὼν ἐκέλευσε τοῖς ἐνοικοῦσιν, αὐτούς τε καὶ δούλους αὐτῶν, ὅσα δύναιντο λαβόντας, ἐκ τῶν πόλεων μεθίστασθαι, καὶ τὰ λοιπὰ διήρπαζεν. τούτων ἔνιοι πυνθανόμενοι, πρὶν τὸν Ἀσδρούβαν ἥκειν, τοῖς φρουροῖς ἐπετίθεντο, καὶ συνέβαινεν ὅπου μὲν κρατεῖν τὰς πόλεις ὅπου δὲ τοὺς φρουρούς, σφαγή τε ποικίλη καὶ γυναικῶν ὕβρις καὶ παρθένων ἀπαγωγαί, καὶ πάντα ὅσα ἐν πόλεσιν ἑαλωκυίαις, ἐγίγνοντο.", "st": "8.58"}, {"sp": "N", "t": "αὐτὸς δὲ ὁ Ἀννίβας τοὺς συστρατευομένους οἱ τῶν Ἰταλῶν εἰδὼς εὖ γεγυμνασμένους, ἔπειθε πολλαῖς ὑποσχέσεσιν ἐς τὴν Λιβύην αὑτῷ συστρατεῦσαι. καὶ τούτων οἱ μὲν τὰ ἡμαρτημένα σφίσιν ἐς τὰς πατρίδας δεδιότες εἵποντο, φεύγοντες τὴν οἰκείαν ἑκόντες, οἱ δὲ οὐδὲν ἁμαρτόντες ὤκνουν. ἀθροίσας οὖν τούσδε τοὺς ὑπομένειν ἀξιοῦντας ὡς δή τι λέξων αὐτοῖς ἢ χαριούμενος τῶν γεγονότων ἢ περὶ τοῦ μέλλοντος ἐπισκήψων, περιέστησε τὴν στρατιὰν ὡπλισμένην ἄφνω, καὶ προσέταξε τοῖς ἰδίοις ἀνδράποδα ἐξ αὐτῶν ὅσα θέλουσιν ἐπιλέξασθαι. ὡς δὲ οἱ μὲν ἐπελέξαντο, οἱ δὲ ᾐδοῦντο συστρατιώτας πολλὰ συνειργασμένους σφίσιν ἀνδραποδίσασθαι, τοὺς λοιποὺς κατηκόντισεν ἅπαντας, τοῦ μὴ τοιούσδε ἄνδρας ποτὲ Ῥωμαίοις γενέσθαι χρησίμους. ἐπικατέσφαξε δ’ αὐτοῖς καὶ ἵππους ἐς τετρακισχιλίους καὶ πλῆθος ὑποζυγίων, οὐ δυνάμενος ἐς Λιβύην ἐπάγεσθαι.", "st": "8.59"}, {"sp": "N", "t": "μετὰ δὲ τοῦτο ἐς τὰς ναῦς τὸ πλῆθος ἐμβιβάσας τὸ πνεῦμα ἀνέμενεν, ὀλίγους ἐς φυλακὴν ἐπὶ τῆς γῆς καταλιπών. οἱ δὲ Πετηλῖνοι καὶ σὺν αὐτοῖς ἕτεροι Ἰταλοὶ ἐπέθεντο, καί τινας αὐτῶν κατασφάξαντες ἀπέδρασαν. Ἀννίβας δ’ ἐπὶ Λιβύης ἀνήγετο, ἑκκαίδεκα ἔτεσιν ὁμαλῶς πορθήσας τε τὴν Ἰταλίαν, καὶ τοὺς ἄνδρας ἐμπλήσας κακῶν μυρίων καὶ ἐς κίνδυνον ἔσχατον πολλάκις συναγαγών, τοῖς τε ὑπηκόοις αὑτοῦ καὶ συμμάχοις ἐνυβρίσας ὡς πολεμίοις· ἅτε γὰρ καὶ τέως αὐτοῖς οὐκ ἐπ’ εὐνοίᾳ μᾶλλον ἢ χρείᾳ χρώμενος, οὐδὲν ἔχων ἔτι πρὸς αὐτῶν ὠφελεῖσθαι κατεφρόνησεν ὡς πολεμίων.", "st": "8.60"}, {"sp": "N", "t": "Ἀννίβου δ’ ἀποπλεύσαντος ἡ βουλὴ τοῖς μὲν ἄλλοις ἔθνεσι τῆς Ἰταλίας, ὅσοι μετέθεντο πρὸς ἐκεῖνον, συνέγνω τῶν γεγονότων καὶ ἀμνηστίαν ἐψηφίσατο, Βρεττίων δὲ μόνων, οἳ μέχρι τέλους αὐτῷ προθυμότατοι ἐγεγένηντο, χώραν τε πολλὴν ἀφείλετο καὶ ὅπλα, εἴ τινα ἦν ἔτι χωρὶς ὧν Ἀννίβας ἀφῄρητο· ἔς τε τὸ μέλλον ἀπεῖπεν αὐτοῖς μὴ στρατεύεσθαι ὡς οὐδ’ ἐλευθέροις οὖσιν, ὑπηρέτας δὲ τοῖς τε ὑπάτοις καὶ στρατηγοῖς τοῖς ἐς τὰς τῶν ἐθνῶν ἡγεμονίας ἀπιοῦσιν ἐς τὰς δημοσίας ὑπηρεσίας, οἷα θεράποντας, ἀκολουθεῖν. τοῦτο τὸ τέλος ἦν Ἀννίβου τῆς ἐς τὴν Ἰταλίαν γενομένης ἐσβολῆς.", "st": "8.61"}, {"sp": "HDR", "t": "Λιβυκή", "st": "9"}, {"sp": "N", "t": "Καρχηδόνα τὴν ἐν Λιβύῃ Φοίνικες ᾤκισαν ἔτεσι πεντήκοντα πρὸ ἁλώσεως Ἰλίου, οἰκισταὶ δ’ αὐτῆς ἐγένοντο Ζῶρός τε καὶ Καρχηδών, ὡς δὲ Ῥωμαῖοι καὶ αὐτοὶ Καρχηδόνιοι νομίζουσι, Διδὼ γυνὴ Τυρία, ἧς τὸν ἄνδρα κατακαίνει Πυγμαλίων Τύρου τυραννεύων, καὶ τὸ ἔργον ἐπέκρυπτεν. ἡ δὲ ἐξ ἐνυπνίου τὸν φόνον ἐπέγνω, καὶ μετὰ χρημάτων πολλῶν καὶ ἀνδρῶν, ὅσοι Πυγμαλίωνος τυραννίδα ἔφευγον, ἀφικνεῖται πλέουσα Λιβύης ἔνθα νῦν ἔστι Καρχηδών. ἐξωθούμενοι δ’ ὑπὸ τῶν Λιβύων ἐδέοντο χωρίον ἐς συνοικισμὸν λαβεῖν, ὅσον ἂν βύρσα ταύρου περιλάβοι. τοῖς δὲ ἐνέπιπτε μέν τι καὶ γέλωτος ἐπὶ τῇ τῶν Φοινίκων μικρολογίᾳ, καὶ ᾐδοῦντο ἀντειπεῖν περὶ οὕτω βραχυτάτου· μάλιστα δ’ ἠπόρουν ὅπως ἂν πόλις ἐν τηλικούτῳ διαστήματι γένοιτο, καὶ ποθοῦντες ἰδεῖν ὅ τι ἔστιν αὐτοῖς τοῦτο τὸ σοφόν, συνέθεντο δώσειν καὶ ἐπώμοσαν. οἱ δὲ τὸ δέρμα περιτεμόντες ἐς ἱμάντα ἕνα στενώτατον, περιέθηκαν ἔνθα νῦν ἔστιν ἡ Καρχηδονίων ἀκρόπολις· καὶ ἀπὸ τοῦδε Βύρσα ὀνομάζεται.", "st": "9.1"}, {"sp": "N", "t": "χρόνῳ δ’, ἐντεῦθεν ὁρμώμενοι καὶ τῶν περιοίκων ἀμείνους ὄντες ἐς χεῖρας ἐλθεῖν, ναυσί τε χρώμενοι καὶ τὴν θάλασσαν οἷα Φοίνικες ἐργαζόμενοι, τὴν πόλιν τὴν ἔξω τῇ Βύρσῃ περιέθηκαν. καὶ δυναστεύοντες ἤδη Λιβύης ἐκράτουν καὶ πολλῆς θαλάσσης, ἐκδήμους τε πολέμους ἐστράτευον ἐς Σικελίαν καὶ Σαρδὼ καὶ νήσους ἄλλας ὅσαι τῆσδε τῆς θαλάσσης εἰσί, καὶ ἐς Ἰβηρίαν. πολλαχῇ δὲ καὶ ἀποικίας ἐξέπεμπον. ἥ τε ἀρχὴ αὐτοῖς ἐγένετο δυνάμει μὲν ἀξιόμαχος τῇ Ἑλληνικῇ, περιουσίᾳ δὲ μετὰ τὴν Περσικήν. ἑπτακοσίοις δ’ αὐτοὺς ἔτεσιν ἀπὸ τοῦ συνοικισμοῦ Ῥωμαῖοι Σικελίαν ἀφείλοντο, καὶ Σαρδὼ μετὰ Σικελίαν, δευτέρῳ δὲ πολέμῳ καὶ Ἰβηρίαν. ἔς τε τὴν ἀλλήλων ἐμβαλόντες μεγάλοις στρατοῖς, οἱ μὲν Ἀννίβου σφῶν ἡγουμένου τὴν Ἰταλίαν ἐπόρθουν ἑκκαίδεκα ἔτεσιν ἑξῆς, οἱ δὲ Λιβύην Κορνηλίου Σκιπίωνος τοῦ πρεσβυτέρου σφῶν στρατηγοῦντος, μέχρι τὴν ἡγεμονίαν Καρχηδονίους ἀφείλοντο καὶ ναῦς καὶ ἐλέφαντας, καὶ χρήματα σφίσιν ἐπέταξαν ἐσενεγκεῖν ἐν χρόνῳ. δεύτεραί τε σπονδαὶ Ῥωμαίοις καὶ Καρχηδονίοις αἵδε διέμειναν ἐς ἔτη πεντήκοντα, μέχρι λύσαντες αὐτὰς τρίτον πόλεμον καὶ τελευταῖον ἀλλήλοις ἐπολέμησαν, ἐν ᾧ Καρχηδόνα Ῥωμαῖοι κατέσκαψαν Σκιπίωνος τοῦ νεωτέρου σφῶν στρατηγοῦντος, καὶ ἐπάρατον ἔγνωσαν. αὖθις δ’ ᾤκισαν ἰδίοις ἀνδράσιν, ἀγχοτάτω μάλιστα τῆς προτέρας, ὡς εὔκαιρον ἐπὶ Λιβύῃ χωρίον. τούτων τὰ μὲν ἀμφὶ Σικελίαν ἡ Σικελικὴ γραφὴ δηλοῖ, τὰ δ’ ἐν Ἰβηρίᾳ γενόμενα ἡ Ἰβηρική, καὶ ὅσα Ἀννίβας ἐς Ἰταλίαν ἐσβαλὼν ἔπραξεν, ἡ Ἀννιβαϊκὴ· τὰ δ’ ἐν Λιβύῃ γενόμενα ἀπ’ ἀρχῆς ἥδε συνάγει.", "st": "9.2"}, {"sp": "N", "t": "ἤρξαντο δ’ αὐτῶν ἀμφὶ τὸν Σικελικὸν πόλεμον οἱ Ῥωμαῖοι, ναυσὶ πεντήκοντα καὶ τριακοσίαις ἐπιπλεύσαντες ἐς Λιβύην, καὶ πόλεις τινὰς ἑλόντες, καὶ στρατηγὸν ἐπὶ τῇ δυνάμει καταλιπόντες Ἀτίλιον Ῥῆγλον, ὃς ἄλλας τε πόλεις διακοσίας προσέλαβεν, αἳ Καρχηδονίων ἔχθει πρὸς αὐτὸν μετετίθεντο, καὶ τὴν χώραν ἐπιὼν ἐπόρθει. Καρχηδόνιοι δὲ Λακεδαιμονίους στρατηγὸν ἤτουν, οἰόμενοι δι’ ἀναρχίαν κακοπραγεῖν. οἱ μὲν δὴ Ξάνθιππον αὐτοῖς ἔπεμπον, ὁ δὲ Ἀτίλιος ἀμφὶ λίμνῃ στρατοπεδεύων ὥρᾳ καύματος περιώδευε τὴν λίμνην ἐπὶ τοὺς πολεμίους, ὅπλων τε βάρει καὶ πνίγει καὶ δίψει καὶ ὁδοιπορίᾳ κακοπαθῶν, καὶ βαλλόμενος ἀπὸ κρημνῶν ἄνωθεν. ὡς δ’ ἐπλησίασε περὶ ἑσπέραν καὶ ποταμὸς αὐτοὺς διεῖργεν, ὁ μὲν εὐθὺς ἐπέρα τὸν ποταμὸν ὡς καὶ τῷδε τὸν Ξάνθιππον ἐκπλήξων, ὁ δὲ συντεταγμένην τὴν στρατιὰν ἐπαφίησι διὰ τῶν πυλῶν, ἐλπίσας κεκμηκότος καὶ κακοπαθοῦντος περιέσεσθαι, καὶ τὴν νύκτα πρὸς τῶν νικώντων ἔσεσθαι. τῆσδε μὲν οὖν τῆς ἐλπίδος ὁ Ξάνθιππος οὐκ ἀπέτυχεν· ἀπὸ γὰρ τρισμυρίων ἀνδρῶν οὓς ὁ Ἀτίλιος ἦγεν, ὀλίγοι μόλις αὐτῶν ἐς Ἀσπίδα πόλιν διέδρασαν, οἱ δὲ λοιποὶ πάντες οἱ μὲν ἀπώλοντο οἱ δ’ ἐζωγρήθησαν. καὶ μετ’ αὐτῶν ὁ στρατηγὸς Ἀτίλιος, ὕπατος γεγονώς, αἰχμάλωτος ἦν.", "st": "9.3"}, {"sp": "N", "t": "τόνδε μὲν δὴ μετ’ οὐ πολὺ κάμνοντες οἱ Καρχηδόνιοι σὺν οἰκείοις πρέσβεσιν ἔπεμψαν ἐς Ῥώμην, ἐργασόμενον σφίσι διαλλαγὰς ἢ ἐπανήξοντα· καὶ ὁ Ἀτίλιος Ῥῆγλος ἐν ἀπορρήτῳ τοῖς τέλεσι Ῥωμαίων ἐπισκήψας ἐγκρατῶς ἔχεσθαι τοῦ πολέμου, ἐπανῆλθεν ἐς λύμην ἕτοιμον, καὶ αὐτὸν οἱ Καρχηδόνιοι καθείρξαντες ἐν γαλεάγρᾳ κέντρα πάντοθεν ἐχούσῃ διέφθειραν. Ξανθίππῳ δὲ τὸ εὐτύχημα συμφορῶν ἦρξε· Καρχηδόνιοι γὰρ αὐτόν, ἵνα μὴ δοκοίη Λακεδαιμονίων ἔργον εἶναι τοσοῦτον, ὑποκρινάμενοι τιμᾶν δωρεαῖς πολλαῖς καὶ προπέμπειν ἐπὶ τριήρων ἐς Λακεδαίμονα, τοῖς τριηράρχοις ἐνετείλαντο μετὰ τῶν συμπλεόντων Λακώνων καταποντίσαι. ὁ μὲν δὴ δίκην ἔδωκε τήνδε εὐπραξίας, καὶ τάδε ἦν τοῦ πρώτου πολέμου Ῥωμαίοις περὶ Λιβύην εὐπραγήματά τε καὶ ἀτυχήματα, μέχρι Καρχηδόνιοι Σικελίας Ῥωμαίοις ἀπέστησαν. ὅπως δὲ ἀπέστησαν, ἐν τῇ Σικελικῇ γραφῇ δεδήλωται.", "st": "9.4"}, {"sp": "N", "t": "μετὰ δὲ τοῦτο Ῥωμαίοις μὲν καὶ Καρχηδονίοις εἰρηναῖα ἦν ἐς ἀλλήλους, Λίβυες, δ’ ὅσοι Καρχηδονίων ὄντες ὑπήκοοι συνεμεμαχήκεσαν αὐτοῖς ἐπὶ Σικελίαν, καὶ Κελτῶν ὅσοι ἐμεμισθοφορήκεσαν, ἐγκλήματά τινα μισθῶν καὶ ὑποσχέσεων ἐς τοὺς Καρχηδονίους ἔχοντες ἐπολέμουν αὐτοῖς μάλα καρτερῶς. οἱ δὲ Ῥωμαίους ἐς συμμαχίαν ὡς φίλους ἐκάλουν, καὶ αὐτοὺς οἱ Ῥωμαῖοι ξενολογεῖν ἐς μόνον τόνδε τὸν πόλεμον ἀπὸ τῆς Ἰταλίας ἐφῆκαν· ἀπείρητο γὰρ ἐν ταῖς σπονδαῖς καὶ τόδε. ἔπεμψαν δὲ καὶ διαλλακτῆρας, οἷς οἱ Λίβυες οὐχ ὑπήκουον, ἀλλὰ τὰς πόλεις ἐδήλωσαν ὑπηκόους εἶναι Ῥωμαίων, εἰ θέλοιεν· οἱ δ’ οὐκ ἐδέξαντο. Καρχηδόνιοι δὲ ναυτικῷ πολλῷ ταῖς πόλεσιν ἐφεδρεύοντες τὴν ἀγορὰν αὐτῶν ἀφῃροῦντο τὴν ἐκ τῆς θαλάσσης, ἀσπόρου δὲ καὶ τῆς γῆς ὡς ἐν πολέμῳ γενομένης, Λιβύων μὲν διὰ τὸν λιμὸν ἐκράτουν, ἐμπόρους δ’, ὅσοι παρέπλεον, ἐλῄστευον ἐξ ἀπορίας· τοὺς δὲ Ῥωμαίων καὶ κτείνοντες ἔβαλλον ἐς τὸ πέλαγος, ἵνα λανθάνοιεν. καὶ διέλαθον ἐπὶ πολύ. γνωσθέντος δὲ τοῦ γιγνομένου, ποινὴν αἰτούμενοι διωθοῦντο, μέχρι Ῥωμαίων ἐπιστρατεύειν αὐτοῖς ψηφισαμένων Σαρδὼ ποινὴν ἔδωκαν. καὶ τόδε ταῖς προτέραις συνθήκαις ἐνεγράφη.", "st": "9.5"}, {"sp": "N", "t": "οὐ πολὺ δὲ ὕστερον οἱ Καρχηδόνιοι στρατεύουσιν ἐς Ἰβηρίαν, καὶ αὐτὴν κατὰ μέρος ὑπήγοντο, μέχρι Ζακανθαίων ἐπὶ Ῥωμαίους καταφυγόντων Καρχηδονίοις ὅρος ἐν Ἰβηρίᾳ γίγνεται, μὴ διαβαίνειν τὸν Ἴβηρα ποταμόν. καὶ τάσδε αὖ τὰς σπονδὰς ἔλυσαν Καρχηδόνιοι, περάσαντες Ἀννίβου σφῶν ἡγουμένου. διαβάντες δέ, ὁ μὲν Ἀννίβας διαστρατηγεῖν ἑτέροις τὰ ἐν Ἰβηρία καταλιπὼν ἐς τὴν Ἰταλίαν ἐσέβαλε· στρατηγοὶ δὲ Ῥωμαίων ἐν Ἰβηρίᾳ, Πόπλιός τε Κορνήλιος Σκιπίων καὶ Γναῖος Κορνήλιος Σκιπίων, ἀλλήλοιν ἀδελφώ, λαμπρὰ ἔργα ἀποδεικνυμένω θνήσκετον ἄμφω πρὸς τῶν πολεμίων. καὶ οἱ μετ’ αὐτοὺς στρατηγοὶ κακῶς ἔπραττον, μέχρι Σκιπίων ὁ Ποπλίου Σκιπίωνος τοῦδε τοῦ περὶ Ἰβηρίαν ἀναιρεθέντος υἱὸς ἐπιπλεύσας, καὶ δόξαν ἅπασιν ἐμβαλὼν ὡς ἥκοι κατὰ θεὸν καὶ δαιμονίῳ χρῷτο συμβούλῳ περὶ ἁπάντων, ἐκράτει τε λαμπρῶς, καὶ ἐπὶ δόξης ἐκ τοῦδε πολλῆς γενόμενος τὴν μὲν στρατηγίαν τοῖς ἐς διαδοχὴν ἐπιπεμφθεῖσι παρέδωκεν, ἐς δὲ Ῥώμην ἐπανελθῶν ἠξίου πεμφθῆναι στρατηγὸς ἐς Λιβύην ὡς ἀναστήσων Ἀννίβαν ἐξ Ἰταλίας καὶ Καρχηδονίοις δίκην ἐπιθήσων ἐν τῇ πατρίδι.", "st": "9.6"}, {"sp": "N", "t": "τῶν δὲ πολιτευομένων οἱ μὲν ἀντέλεγον οὐ χρῆναι, κεκενωμένης ἄρτι τῆς Ἰταλίας τοσοῖσδε πολέμοις καὶ πορθουμένης ἔτι πρὸς Ἀννίβου, καὶ Μάγωνος ἐν πλευραῖς ἐπ’ αὐτὴν Λίγυάς τε καὶ Κελτοὺς ξενολογοῦντος, ἐς Λιβύην στρατεύειν, οὐδὲ τὴν ἀλλοτρίαν χειροῦσθαι πρὶν τὴν οἰκείαν ἀπαλλάξαι τῶν παρόντων· οἱ δὲ ᾤοντο Καρχηδονίους νῦν μὲν ἀδεεῖς ὄντας ἐφεδρεύειν τῇ Ἰταλίᾳ, οὐδὲν ἐνοχλουμένους οἴκοι, πολέμου δὲ οἰκείου σφίσι γενομένου καὶ Ἀννίβαν μεταπέμψεσθαι. οὕτω μὲν ἐκράτησε πέμπειν ἐς Λιβύην Σκιπίωνα, οὐ μὴν συνεχώρησαν αὐτῷ καταλέγειν στρατὸν ἐξ Ἰταλίας πονουμένης ἔτι πρὸς Ἀννίβου· ἐθελοντὰς δέ, εἴ τινες εἶεν, ἐπέτρεψαν ἐπάγεσθαι, καὶ τοῖς ἀμφὶ τὴν Σικελίαν ἔτι οὖσι χρῆσθαι. τριήρεις τε ἔδοσαν αὐτῷ κατασκευάσασθαι δέκα, καὶ πληρώματα αὐταῖς λαβεῖν, ἐπισκευάσαι δὲ καὶ τὰς ἐν Σικελία. καὶ χρήματα οὐκ ἔδωκαν, πλὴν εἴ τις ἐθέλοι τῷ Σκιπίωνι κατὰ φιλίαν συμφέρειν. οὕτως ἀμελῶς ἥπτοντο τοῦδε τοῦ πολέμου τὰ πρῶτα, μεγίστου σφίσι καὶ ἀξιοτιμοτάτου μετ’ ὀλίγον γενομένου.", "st": "9.7"}, {"sp": "N", "t": "ὁ δὲ Σκιπίων ἔνθους ὢν ἐπὶ Καρχηδόνι ἐκ πολλοῦ, καί τινας ἱππέας τε καὶ πεζούς, ἐς ἑπτακισχιλίους μάλιστα. ἀθροίσας, διέπλευσεν ἐς Σικελίαν ἔχων ἀμφ’ αὑτὸν ἀρτιγενείους ἐπιλέκτους τριακοσίους, οἷς εἴρητο χωρὶς ὅπλων ἕπεσθαι. Σικελῶν δ’ αὖ τριακοσίους καταγράψας εὐδαίμονας ἐκέλευσεν ἥκειν ἐς ἡμέραν ῥητήν, ἐσκευασμένους ὅπλοις τε καὶ ἵπποις ὅτι δύναιντο καλλίστοις. ὡς δὲ ἀφίκοντο, προύθηκεν εἴ τις ἑαυτοῦ θέλοι τὸν στρατευσόμενον ἀντιδοῦναι. δεξαμένων δὲ πάντων, ἤγαγεν ἐς μέσον τοὺς τριακοσίους τοὺς ὅπλων ἐρήμους, καὶ ἐς τούσδε ἐκείνοις προσέταξε μετασκευάσασθαι. οἱ δ’ ἑκόντες παρεδίδοσαν ὅπλα καὶ ἵππους. καὶ περιῆν τῷ Σκιπίωνι τριακοσίους νέους Ἰταλιώτας ἔχειν ἀντὶ Σικελιωτῶν, κάλλιστα ἵπποις καὶ ὅπλοις ἀλλοτρίοις ἐσκευασμένους, καὶ χάριν εὐθὺς ἐπὶ τῷδε εἰδότας· οἷς δὴ καὶ προθυμοτάτοις ἐς πάντα χρώμενος διετέλει.", "st": "9.8"}, {"sp": "N", "t": "Καρχηδόνιοι δὲ ταῦτα πυνθανόμενοι Ἀσδρούβαν μὲν τὸν Γέσκωνος ἐπὶ θήραν ἐλεφάντων ἐξέπεμπον, Μάγωνι δ’ ἀμφὶ τὴν Λιγυστίνην ξεναγοῦντι πεζοὺς ἀπέστελλον ἐς ἑξακισχιλίους καὶ ἱππέας ὀκτακοσίους καὶ ἐλέφαντας ἑπτά, καὶ προσέτασσον αὐτῷ μεθ’ ὅσων δύναιτο ἄλλων ἐσβαλεῖν ἐς Τυρρηνίαν, ἵνα τὸν Σκιπίωνα περισπάσειεν ἐκ Λιβύης. Μάγων μὲν δὴ καὶ τότε ἐβράδυνεν, Ἀννίβᾳ τε συνελθεῖν οὐ δυνάμενος πολὺ διεστῶτι, καὶ τὸ μέλλον ἀεὶ περιορώμενος. Ἀσδρούβας δ’ ἀπὸ τῆς θήρας ἐπανελθὼν κατέλεγε Καρχηδονίων τε καὶ Λιβύων ἐς ἑξακισχιλίους πεζοὺς ἑκατέρων καὶ ἱππέας ἑξακοσίους, δούλους τε ἠγόραζε πεντακισχιλίους, τὸ ναυτικὸν ἐρέσσειν, καὶ παρὰ τῶν Νομάδων ἔλαβε δισχιλίους ἱππέας, καὶ ξένους ἐμισθοῦτο, καὶ πάντας ἐγύμναζε, διακοσίους σταδίους ἀποσχὼν ἀπὸ Καρχηδόνος.", "st": "9.9"}, {"sp": "N", "t": "Νομάδων δὲ τῶν ἐν Λιβύῃ δυνάσται μὲν ἦσαν κατὰ μέρη πολλοί, Σύφαξ δ’ ὑπὲρ ἅπαντας, καὶ τιμὴν εἶχε πρὸς τῶν ἄλλων ἐπιφανῆ. Μασσυλίων δ’ αὖ, γένους ἀλκίμου, παῖς ἦν τοῦ βασιλέως Μασσανάσσης, ὃς ἐτέθραπτο μὲν ἐν Καρχηδόνι καὶ ἐπεπαίδευτο, ὄντι δ’ αὐτῷ καὶ τὸ σῶμα καλῷ καὶ τὸν τρόπον ἀρίστῳ Ἀσδρούβας ὁ Γέσκωνος, οὐδενὸς Καρχηδονίων δεύτερος, ἠγγύησε τὴν θυγατέρα, καίπερ ὄντι Νομάδι, Καρχηδόνιος ὤν. ὡς δ’ ἠλλύησεν, ἐπήγετο ἐς Ἰβηρίαν στρατηγῶν τὸ μειράκιον. Σύφαξ δὲ κνιζό μενος ὑπ’ ἔρωτος ἐπὶ τῇ παιδὶ τὰ Καρχηδονίων ἐλεηλάτει, καὶ Σκιπίωνι διαπλεύσαντι πρὸς αὐτὸν ἐξ Ἰβηρίας συνέθετο συμμαχήσειν ἐπὶ Καρχηδονίους ἰόντι. αἰσθόμενοι δ’ οἱ Καρχηδόνιοι καὶ μέγα ποιούμενοι ἐς τὸν πρὸς Ῥωμαίους πόλεμον Σύφακα προσλαβεῖν, ἐξέδοσαν αὐτῷ τὴν παρθένον ἀγνοούντων καὶ ὄντων ἐν Ἰβηρίᾳ Ασδρούβου τε καὶ Μασσανάσσου. ἐφ’ οἷς ὁ Μασσανάσσης ὑπεραλγῶν συνετίθετο καὶ ὅδε ἐν Ἰβηρίᾳ τῷ Σκιπίωνι, λανθάνων, ὡς ᾤετο, Ἀσδρούβαν. ὁ δ’ αἰσθόμενος βαρέως μὲν ἔφερεν ὑπὲρ τοῦ μειρακίου καὶ τῆς θυγατρός, ὑβρισμένοιν ἀμφοῖν, ἡγεῖτο δ’ ὅμως τῇ πατρίδι συμφέρειν ἐκποδὼν Μασσανάσσην ποιήσασθαι, καὶ ἐπανιόντι ἐς Λιβύην ἐξ Ἰβηρίας ἐπὶ θανάτῳ τοῦ πατρὸς συνέπεμπε προπομποὺς ἱππέας, οἷς εἴρητο ἀφανῶς ἐπιβουλεύειν αὐτῷ καὶ κτείνειν ὅπῃ δύναιντο.", "st": "9.10"}, {"sp": "N", "t": "ὁ δ’ αἰσθόμενος ἐξέφυγέ τε, καὶ τὴν πάτρῴαν ἀρχὴν ἐκρατύνετο, ἱππέας ἀθροίζων, οἷς ἡμέρας τε καὶ νυκτὸς ἦν ἔργον ἀκοντίοις πολλοῖς χρωμένους ἐπελαύνειν ἀεὶ καὶ ἀναχωρεῖν καὶ αὖθις ἐπελαύνειν. καὶ ὅλως ἐστὶν αὐτοῖς ἡ μάχη φυγὴ καὶ δίωξις. ἴσασι δὲ καὶ λιμὸν φέρειν οἱ Νομάδες οἵδε, καὶ πόᾳ χρῆσθαι πολλάκις ἀντὶ σίτου· καὶ τὸ πάμπαν ὑδροποτοῦσιν. ὅ τε ἵππος αὐτοῖς κριθῆς μὲν οὐδ’ ὅλως γεύεται, ποηφαγῶν ἀεί, πίνει δὲ διὰ πολλοῦ. τοιούτους ὁ Μασσανάσσης ἐς δισμυρίους συναγαγὼν ἐξῆγεν ἐπὶ θήρας ἢ λεηλασίας ἑτέρων ἐθνῶν· ἅπερ ᾤετο καὶ ἔργα καὶ γυμνάσια εἶναι. Καρχηδόνιοι δὲ καὶ Σύφαξ νομίζοντες ἐπὶ σφᾶς εἶναι τὴν παρασκευὴν τοῦ μειρακίου (οὐ γὰρ ἠγνόουν ἃ ἐλελυπήκεσαν αὐτόν), ἔκριναν προτέρῳ τῷδε πολεμεῖν ἔστε καθέλωσι, καὶ τότε Ῥωμαίοις ἀπαντᾶν.", "st": "9.11"}, {"sp": "N", "t": "Σύφαξ μὲν οὖν καὶ Καρχηδόνιοι πλείους ἦσαν παρὰ πολύ, μετὰ δὲ ἁμαξῶν καὶ παρασκευῆς βαρείας καὶ τρυφῆς ἐστρατεύοντο· Μασσανάσσης δὲ πόνων τε πᾶσιν ἐξῆρχε, καὶ ἱππικὸν μόνον εἶχε καὶ ὑποζύγιον οὐδέν, οὐδὲ ἀγοράν. ὅθεν ῥᾳδίως ὑπέφευγέ τε καὶ ἐπεχείρει καὶ ἐς τὰ ὀχυρὰ ἀνεπήδα. πολλάκις τε καὶ καταλαμβανόμενος διεσκίδνη τὸ στράτευμα, ὅπῃ δυνηθεῖεν ἀποφεύγειν κατὰ μέρη. καὶ σὺν ὀλίγοις αὐτὸς ὑπεκρύπτετό ποι, μέχρι συνέλθοιεν αὐτῷ νυκτὸς ἢ μεθ’ ἡμέραν ἐς τὸ συγκείμενον. τρίτος δέ ποτε ἐν σπηλαίῳ κρυπτόμενος ἔλαθε, τῶν πολεμίων περὶ τὸ σπήλαιον στρατοπεδευόντων. οὐδ’ ἔστιν ὅτε ἐστάθμευεν ἐν στρατοπέδῳ, ἀλλὰ καὶ μάλιστ’ ἐστρατήγει λανθάνειν ὅποι ποτε εἴη. ὅθεν οὐκ εἶχον αὐτῷ συνεχῶς προεπιχειρεῖν οἱ πολέμιοι, ἀλλ’ ἠμύνοντο ἐπιόντα. ἀγορὰ δ’ ἦν αὐτῷ καθ’ ἑκάστην ἡμέραν, ὅ τι περὶ ἑσπέραν καταλάβοι χωρίον ἢ κώμην ἢ πόλιν, λῃζομένῳ τε πάντα καὶ διαρπάζοντι καὶ μεριζομένῳ τοῖς συνοῦσιν. ὅθεν αὐτῷ πολλοὶ τῶν Νομάδων ἐπεφοίτων, μισθοὺς μὲν οὐ διδόντι τεταγμένους, τὰς δ’ ὠφελείας πολὺ πλείονας ἔχοντες.", "st": "9.12"}, {"sp": "N", "t": "καὶ Μασσανάσσης μὲν Καρχηδονιοις οὕτως ἐπολέμει, ὁ δὲ Σκιπίων, ἐπεί οἱ πάντα εὐτρεπῆ ἐγεγένητο ἐν Σικελίᾳ, ἔθυε Διὶ καὶ Ποσειδῶνι, καὶ ἐς Λιβύην ἀνήγετο ἐπὶ νεῶν μακρῶν μὲν δύο καὶ πεντήκοντα φορτίδων δὲ τετρακοσίων· κέλητές τε καὶ λέμβοι πολλοὶ συνείποντο αὐτῷ. καὶ στρατιὰν ἦγε πεζοὺς μὲν ἑξακισχιλίους ἐπὶ μυρίοις, ἱππέας δὲ χιλίους καὶ ἑξακοσίους. ἐπήγετο δὲ καὶ βέλη καὶ ὅπλα καὶ μηχανήματα ποικίλα καὶ ἀλορὰν πολλήν. καὶ Σκιπίων μὲν ὧδε διέπλει, Καρχηδόνιοι δὲ καὶ Σύφαξ πυνθανόμενοι ἔγνωσαν ἐν τῷ παρόντι ὑποκρίνασθαί τε Μασσανάσσην καὶ ἐς φιλίαν ὑπαγαγέσθαι, μέχρι ὅτου Σκιπίωνος ἐπικρατήσαιεν. ὁ δ’ οὐκ ἠγνόει μὲν ἐξαπατώμενος, ἀντενεδρεύων δέ, καὶ μηνύων πάντα τῷ Σκιπίωνι, ἧκε πρὸς τὸν Ἀσδρούβαν ὡς συνηλλαγμένος μετὰ τῶν ἰδίων ἱππέων. καὶ ἐστρατοπέδευον οὐ μακρὰν ἀπ’ ἀλλήλων Ἀσδρούβας τε καὶ Σύφαξ καὶ Μασσανάσσης περὶ Ἰτύκην πόλιν, ἐς ἣν ὁ Σκιπίων καταχθεὶς ὑπ’ ἀνέμων καὶ αὐτὸς ἐστρατοπέδευσε περὶ αὐτήν. οὐ πολὺ δ’ ἀπεῖχεν ὁ Ἀσδρούβας αὐτοῦ, στρατιὰν ἔχων ἐς δισμυρίους πεζοὺς καὶ ἱππέας ἑπτακισχιλίους καὶ ἐλέφαντας ἑκατὸν ἐπὶ τεσσαράκοντα.", "st": "9.13"}, {"sp": "N", "t": "Σύφαξ μὲν οὖν, εἴτε δείσας εἴτε ἄπιστος ἐς ἑκατέρους γιγνόμενος παρὰ μέρος, ἐσκήψατό τι λυπεῖν τὴν ἀρχὴν αὐτοῦ τοὺς ὁμόρους βαρβάρους, καὶ ἀνεζεύγνυεν ἐς τὰ οἰκεῖα· Σκιπίων δὲ κατ’ ὀλίγους ἔπεμπεν ἐπιχειρεῖν τῷ Ἀσδρούβᾳ, καί τινες αὐτῷ καὶ τῶν πόλεων προσεχώρουν. νυκτὸς δὲ λαθὼν ὁ Μασσανάσσης ἧκεν ἐπὶ τὸ στρατόπεδον τοῦ Σκιπίωνος, καὶ δεξιωσάμενος αὐτὸν ἐδίδασκε τῆς ἐπιούσης ἔς τι χωρίον ἀπὸ τριάκοντα σταδίων Ἰτύκης, ἔνθα πύργος ἔστιν Ἀγαθοκλέους ἔργον τοῦ Συρακοσίων τυράννου, μὴ πλείους πεντακισχιλίων ἐνεδρεῦσαι. ἅμα δ’ ἡμέρᾳ τὸν Ἀσδρούβαν ἔπειθε τὸν ἵππαρχον Ἄννωνα πέμψαι τό τε πλῆθος τῶν ἐχθρῶν ἐπισκεψόμενον καὶ ἐς Ἰτύκην ἐσδραμούμενον, μή τι πλησιαζόντων πολεμίων νεωτερίσειαν· καὶ αὐτὸς ὑπισχνεῖτο, εἰ κελεύοιτο, ἕψεσθαι. Ἄννων μὲν δὴ χιλίους ἦγεν ἐπιλέκτους ἱππέας Καρχηδονίους καὶ Λιβύων τι πλῆθος, Μασσανάσσης δὲ Νομάδας τοὺς ἑαυτοῦ· ὡς δ’ ἐπὶ τὸν πύργον ἀφίκοντο καὶ ὁ Ἄννων ἐξίππευσεν ἐς τὴν Ἰτύκην σὺν ὀλίγοις, μέρος τι τῆς ἐνέδρας ἐξεφαίνετο, καὶ ὁ Μασσανάσσης ἐκέλευσε τὸν τεταγμένον ἐπὶ τοῖς ἱππεῦσι τῶν Καρχηδονίων ἐπιδραμεῖν αὐτοῖς ὡς οὖσιν ὀλίγοις. καὶ αὐτὸς ἐκ βραχέος εἵπετο ὡς ἐπιβοηθήσων. ἐν μέσῳ δὲ τῶν Λιβύων γενομένων, ἥ τε πλείων ἐνέδρα κατεφαίνετο, καὶ συνηκόντισαν αὐτοὺς ἑκατέρωθεν οἵ τε Ῥωμαῖοι καὶ ὁ Μασσανάσσης, πλὴν τετρακοσίων, οἳ ἐλήφθησαν αἰχμάλωτοι. Μασσανάσσης δ’, ἐπεὶ τοῦτο ἐξετετέλεστο, ἀπήντα τῷ Ἄννωνι κατὰ σπουδὴν ὡς φίλος ἐπανιόντι, καὶ συλλαβὼν αὐτὸν ἀπῆγεν ἐς τὸ τοῦ Σκιπίωνος στρατόπεδον, καὶ ἀντέδωκεν Ἀσδρούβᾳ τῆς μητρὸς τῆς ἑαυτοῦ.", "st": "9.14"}, {"sp": "N", "t": "Σκιπίων δὲ καὶ Μασσανάσσης τὴν χώραν ἐπόρθουν, καὶ Ῥωμαίων ἐξέλυον ὅσοι δεθέντες ἔσκαπτον ἐν τοῖς ἀγροῖς, ἐξ Ἰβηρίας ἢ Σικελίας ἢ ἀπ’ αὐτῆς τῆς Ἰταλίας πεμφθέντες ὑπὸ Ἀννίβου. πολιορκοῦσι δ’ αὐτοῖς πόλιν μεγάλην ᾗ ὄνομα ἦν Λόχα, καὶ πολλὰ δεινὰ πάσχουσιν, οἱ μὲν Λοχαῖοι προστιθεμένων τῶν κλιμάκων ἐπεκηρυκεύοντο ἐκλείψειν τὴν πόλιν ὑπόσπονδοι, καὶ ὁ Σκιπίων ἀνεκάλει τῇ σάλπιγγι τὴν στρατιάν· ἡ δ’ οὐχ ὑπήκουεν ὑπ’ ὀργῆς ὧν ἐπεπόνθεσαν, ἀλλ’ ἐπιβάντες τοῖς τείχεσι καὶ γύναια καὶ παιδία κατέσφαττον· ὁ δὲ τοὺς μὲν ἔτι ὄντας Λοχαίων ἀφῆκεν ἀπαθεῖς, τὴν δὲ στρατιὰν τὴν λείαν ἀφείλετο, καὶ τοὺς λοχαγούς, ὅσοι συνεξήμαρτον, ἐκλήρωσεν ἐν τῷ μέσῳ, καὶ τρεῖς τοὺς λαχόντας ἐκόλασε θανάτῳ. καὶ τάδε πράξας αὖθις ἐλεηλάτει. Ἀσδρούβας δ’ αὐτοὺς ἐνήδρευε, Μάγωνα μὲν τὸν ἵππαρχον ἐπιπέμψας ἐκ μετώπου, αὐτὸς δὲ ὄπισθεν ἐπιών. οἱ δ’ ἐν μέσῳ γενόμενοι τὸ ἔργον ἐμερίσαντο, καὶ ἐς ἑκατέρους αὐτῶν ἑκάτερος ἐπιστραφεὶς πεντακισχιλίους τῶν Λιβύων ἀπέκτειναν, καὶ χιλίους καὶ ὀκτακοσίους ἔλαβον αἰχμαλώτους, τοὺς δὲ λοιποὺς ἐς τὰς πέτρας κατήραξαν.", "st": "9.15"}, {"sp": "N", "t": "καὶ ὁ Σκιπίων εὐθὺς ἐπὶ τοῖσδε προσέβαλεν Ἰτύκῃ κατὰ γῆν καὶ κατὰ θάλασσαν, δύο μὲν πεντήρεσιν ἐζευγμέναις πύργον ἐπιθείς, ὅθεν τριπήχη βέλη καὶ λίθους μεγάλους ἐς τοὺς πολεμίους ἠφίει, καὶ πολλὰ μὲν ἐλύπει πολλὰ δ’ ἀντέπασχε θραυομένων τῶν νεῶν, χώματα δ’ ἐπαίρων μέγιστα, καὶ κριοῖς τὸ τεῖχος, ὅτε προσπελάσειε, τύπτων, δρεπάνοις τε περισπῶν ὅσαι βύρσαι περὶ αὐτὸ καὶ ἄλλα σκεπαστήρια ἦν. οἱ δὲ τὰ μὲν χώματα ὑπετάφρευον, καὶ τὰ δρέπανα βρόχοις παρῆγον, καὶ τοὺς κριοὺς τῆς ὁρμῆς ἐξέλυον, ἐπιβάλλοντες ἐπικαρσίας δοκούς· ἐς δὲ τὰς μηχανὰς ἐξεπήδων μετὰ πυρός, ὅτε πνεῦμα φυλάξειαν ἐς αὐτὰς ἐπίφορον. ὅθεν ὁ Σκιπίων ἀπογνοὺς οὕτως αἱρήσειν τὴν πόλιν, ἐς πολιορκίαν αὐτῆς καθίστατο.", "st": "9.16"}, {"sp": "N", "t": "Σύφαξ δὲ τῶν γιγνομένων πυνθανόμενος ἧκε μετὰ τοῦ στρατοῦ, καὶ οὐ μακρὰν ἐστάθμευεν ἀπὸ Ἀσδρούβου. ἔτι δ’ ὑποκρινόμενος εἶναι φίλος ἑκατέροις, καὶ τρίβειν τὸν πόλεμον ἐγνωκὼς μέχρι νῆές τε ἕτεραι ναυπηγούμεναι πρὸς τῶν Καρχηδονίων ἐπιγένοιντο καὶ μισθοφόροι τινὲς Κελτῶν καὶ Λιγύων ἐπέλθοιεν, ἐπεχείρει διαιτᾶν διαλύσεις, καὶ ἐδικαίου μήτε Ῥωμαίους Λιβύης μήτε Καρχηδονίους Ἰταλίας ἐπιβαίνειν ἐπὶ πολέυῳ, ἔχειν δὲ Ῥωμαίους Σικελίαν καὶ Σαρδὼ καὶ εἴ τινας ἄλλας νήσους ἔχουσι, καὶ Ἰβηρίαν. ἢν δέ τις ἀπειθῇ, τοῖς πειθομένοις ἔφη συμμαχήσειν. ἅμα δὲ ταῦτ’ ἔπρασσε, καὶ Μασσανάσσην ἐπείρα μεταθέσθαι πρὸς αὑτόν, τήν τε Μασσυλίων ἀρχὴν αὐτῷ βεβαιώσειν ὑπισχνούμενος, καὶ τῶν θυγατέρων τριῶν οὐσῶν δώσειν ἐς γάμον ἣν ἂν ἐθέλῃ. ἔφερε δ’ ὁ ταῦτα λέγων χρυσίον, ἵνα, εἰ μὴ πείσειε, δοίη τῶν θεραπευτήρων αὐτοῦ τῷ κτείνειν Μασσανάσσην ὑπισχνουμένῳ. ὁ μὲν δὴ μὴ πείθων ἔδωκέ τινι τὸ χρυσίον ἐπὶ τῷ φόνῳ· ὁ δὲ λαβὼν ἔδειξε τῷ Μασσανάσσῃ, καὶ τὸν δόντα ἤλεγξεν.", "st": "9.17"}, {"sp": "N", "t": "Σύφαξ δ’ οὐ προσδοκῶν ἔτι λήσειν, φανερῶς τοῖς Καρχηδονίοις συνεμάχει, πόλιν τε ἐν μεσογείῳ Θολοῦντα, Ῥωμαίων παρασκευὴν καὶ σῖτον πολὺν ἔχουσαν, ἐκ προδοσίας εἷλε, καὶ τοὺς φρουροῦντας αὐτὴν ἔκτεινεν οὐκ ἐθελήσαντας ἀπελθεῖν ὑποσπόνδους, συμμαχίαν τε ἄλλην πολλὴν Νομάδων μετεπέμπετο. καὶ οἱ μισθοφόροι παρῆσαν αὐτοῖς ἤδη, καὶ νῆες εὐτρεπῶς εἶχον, ὥστε ἔγνωστο πολεμεῖν Σύφακα μὲν ὁρμώμενον ἐπὶ τοὺς πολιορκοῦντας Ἰτύκην, Ἀσδρούβαν δ’ ἐπὶ τὸ Σκιπίωνος στρατόπεδον. τὰς δὲ ναῦς ἔδει ταῖς ναυσὶν ἐπιπλεῖν, καὶ γίγνεσθαι ταῦτα τῆς ἐπιούσης ἡμέρας ἅπαντα ὁμοῦ, ἵνα μὴ διαρκέσειαν αὐτοῖς οἱ Ῥωμαῖοι διὰ τὴν ὀλιγότητα.", "st": "9.18"}, {"sp": "N", "t": "Ὧνἤδη νυκτὸς οὔσης ὁ Μασσανάσσης παρὰ τινῶν Νομάδων πυθόμενος μετέδωκε τῷ Σκιπίωνι. ὁ δὲ ἔδεισε, καὶ ἠπόρει μὴ ἐς πολλὰ αὐτῷ διαιρούμενος ὁ στρατὸς ἀσθενέστερος ἐς πάντα γίγνηται. τοὺς οὖν ἡγεμόνας αὐτίκα νυκτὸς ἐπὶ τὴν σκέψιν ἐκάλει, καὶ ἀπορούντων ἁπάντων ἐπὶ πολὺ σύννους γενόμενος εἶπε· “τόλμης καὶ ταχυτῆτος ἡμῖν, ὦ φίλοι, δεῖ, καὶ μάχης ἐξ ἀπογνώσεως. φθάσωμεν ἐπελθόντες τοῖς πολεμίοις. ὅσα δ’ ἐν τῷδε πλεονεκτήσομεν, μάθετε ἤδη. ἐκείνους μὲν ἐκπλήξει τὸ ἀδόκητον τῆς ἐφόδου καὶ τὸ παράδοξον τοῦ ἔργου, τῶν ὀλιγωτέρων προεπιχειρούντων· ἡμεῖς δ’ οὐκ ἐς πολλὰ διῃρημένῃ τῇ στρατιᾷ χρησόμεθα ἀλλ’ ἀθρόᾳ, οὐδ’ ἐπάξομεν αὐτὴν ἅπασι τοῖς ἐχθροῖς ἀλλ’ οἷς ἂν ἐπιλεξώμεθα πρώτοις. σταθμεύουσι δ’ ἐφ’ ἑαυτῶν ἕκαστοι, καὶ ἐσμὲν αὐτοῖς κατὰ μέρος ἰσόμαχοι, τόλμῃ δὲ καὶ εὐτυχίᾳ προύχομεν. καὶ ἢν ὁ θεὸς δῷ τῶν πρώτων ἐπικρατῆσαι, τῶν ἄλλων καταφρονήσομεν. οἷς δ’ ἐπιχειρητέον ἐστὶ πρώτοις, καὶ τίς ὁ καιρὸς ἢ τρόπος ἔσται τῆς ἐπιχειρήσεως, ἢν ἀρέσκῃ, τὰ τῆς γνώμης ἐρῶ.”", "st": "9.19"}, {"sp": "N", "t": "συνθεμένων δὲ πάντων, “ὁ μὲν καιρός,” εἶπεν, “εὐθὺς ἐπιχειρεῖν ἀπὸ τοῦδε τοῦ συλλόγου, νυκτὸς ἔτι οὔσης, ὅτε καὶ τὸ ἔργον ἐστὶ φοβερώτερον καὶ ἀνέτοιμα τὰ ἐκείνων, καὶ οὐδεὶς τῶν συμμάχων αὐτοῖς δύναται βοηθεῖν ἐν σκότῳ. φθάσομέν τε οὕτως αὐτῶν τὰ βουλεύματα μόνως, ἐγνωκότων ἡμῖν τῆς ἐπιούσης ἡμέρας ἐπιθέσθαι. τριῶν δ’ αὐτοῖς ὄντων στρατοπέδων, αἱ μὲν νῆές εἰσι πόρρω, καὶ οὐκ ἔστι ναυσὶ νυκτὸς ἐπιχειρεῖν, Ἀσδρούβας δὲ καὶ Σύφαξ οὐ μακρὰν ἀπ’ ἀλλήλων. καὶ τούτοιν Ἀσδρούβας μέν ἐστι τὸ τοῦ πολέμου κεφάλαιον, Σύφαξ δὲ οὐκ ἂν νυκτὸς ἐπιτολμήσειε τῷ πόνῳ, βάρβαρος ἀνὴρ καὶ τρυφῆς γέμων καὶ δέους. φέρε οὖν, ἡμεῖς μὲν ἐπὶ Ἀσδρούβαν μετὰ παντὸς ἴωμεν τοῦ στρατοῦ, Μασσανάσσην δὲ τόνδε ἐπιτάξωμεν ἐφεδρεύειν τῷ Σύφακι, ἢν ἄρα καὶ παρὰ δόξαν ἐξίῃ τοῦ στρατοπέδου. πεζοὶ δὲ χωρῶμεν ἐπὶ τὸν χάρακα τοῦ Ἀσδρούβου, καὶ περιστάντες ἐπιχειρῶμεν ἐκ παντὸς μέρους σὺν ἐλπίδι τε χρηστῇ καὶ τόλμῃ θρασυτάτῃ· τούτων γὰρ τὰ παρόντα δεῖται μάλιστα. τοὺς δ’ ἱππέας (οὐ γὰρ ἔστιν αὐτοῖς χρῆσθαι νυκτὸς ἔτι οὔσης) προπέμψω πορρωτέρω κυκλοῦσθαι τὸ στρατόπεδον τῶν πολεμίων, ἵνα εἰ μὲν βιασθείημεν, ὑποδέχοιντο ἡμᾶς καὶ ἐς φιλίους καταφεύγοιμεν, εἰ δ’ ἐπικρατοίημεν, ἐκφεύγοντας ἐκείνους διώκοιεν καὶ διαχρῷντο.”", "st": "9.20"}, {"sp": "N", "t": "ταῦτ’ εἰπών, καὶ τοὺς ἡγεμόνας ἐκπέμψας ὁπλίσαι τὸν στρατόν, αὐτὸς ἐθύετο Τόλμῃ καὶ Φόβῳ, μηδὲν ὡς ἐν νυκτὶ πανικόν οἱ γενέσθαι, ἀλλὰ τὸν στρατὸν αὐτῷ θρασύτατον μάλιστα ὀφθῆναι. τρίτης δὲ ἤδη φυλακῆς ἠρέμα τῇ σάλπιγγι ὑπεσήμαινε, καὶ μετὰ σιγῆς βαθυτάτης στρατὸς τοσοῦτος ἐβάδιζεν, ἕως οἱ μὲν ἱππεῖς περιέστησαν ἐν κύκλῳ τοὺς πολεμίους, οἱ πεζοὶ δ’ ἐπὶ τὴν τάφρον αὐτῶν ἀφίκοντο. βοῇ δὲ τότε παμμιγεῖ καὶ σάλπιγξιν ἀθρόαις καὶ βυκανήμασιν ἐς κατάπληξιν χρώμενοι τοὺς μὲν φύλακας ἐξέωσαν ἐκ τῶν φυλακτηρίων, τὴν δὲ τάφρον ἔχουν καὶ τὰ σταυρώματα διέσπων. οἱ δ’ εὐτολμότατοι προδραμόντες ἐνέπρησάν τινας σκηνάς. καὶ οἱ Λίβυες μετ’ ἐκπλήξεως ἀνεπήδων τε ἐξ ὕπνου, καὶ τὰ ὅπλα μετελάμβανον, καὶ ἐς τὰς τάξεις ἀτάκτως ἐφέροντο, καὶ τῶν παραγγελλομένων διὰ τὸν θόρυβον οὐ κατήκουον, οὐδ’ αὐτοῦ τοῦ στρατηγοῦ τὸ ἀκριβὲς τῶν γιγνομένων εἰδότος. ἀναπηδῶντας οὖν αὐτοὺς οἱ Ῥωμαῖοι καὶ ὁπλιζομένους ἔτι καὶ ταρασσομένους κατελάμβανον, καὶ σκηνὰς πλέονας ἐνεπίμπρασαν, καὶ τοὺς ἐν ποσὶν ἀνῄρουν. τοῖς δ’ ἦν ἥ τε βοὴ τῶν ἐχθρῶν καὶ ἡ ὄψις καὶ τὰ ἔργα φοβερώτατα ὡς ἐν νυκτὶ καὶ ἀγνωσίᾳ τοῦ γιγνομένου κακοῦ. ἡγούμενοί τε εἰλῆφθαι τὸ στρατόπεδον, καὶ τὸ πῦρ τῶν ἐμπεπρησμένων σκηνῶν δεδιότες, ἐξέπιπτον ἑκόντες ἐξ αὐτῶν, καὶ ἐς τὸ πεδίον ὡς ἀσφαλέστερον ἐωθοῦντο· ὅθεν κατὰ μέρος, ὅπῃ τύχοιεν, ἀκόσμως διεδίδρασκον, καὶ ἐς τοὺς Ῥωμαίων ἱππέας, οἳ κύκλῳ περιεστήκεσαν, ἐμπίπτοντες ἀπέθνησκον.", "st": "9.21"}, {"sp": "N", "t": "Σύφαξ δὲ νυκτὸς μὲν ἔτι, τῆς βοῆς αἰσθόμενος καὶ τὸ πῦρ ὁρῶν, οὐκ ἐπεξῆλθεν, ἀλλὰ τῶν ἱππέων τινὰς ἐπικουρεῖν ἔπεμψεν Ἀσδρούβᾳ, οἷς ὁ Μασσανάσσης ἐπιπεσὼν ἄφνω πολὺν ἐργά ζεται φόνον. ἅμα δ’ ἡμέρᾳ μαθὼν ὁ Σύφαξ Ἀσδρούβαν μὲν ἤδη φυγόντα, τῆς δὲ στρατιᾶς αὐτοῦ τοὺς μὲν ἀπολωλότας, τοὺς δ’ εἰλημμένους ὑπὸ τῶν πολεμίων, τοὺς δὲ διερριμμένους, καὶ τὸ στρατόπεδον αὐτῇ παρασκευῇ Ῥωμαίους ἔχοντας, ἀνεζεύγνυε φεύγων ἐς τὰ μεσόγεια μετὰ θορύβου, πάντα καταλιπών, οἰόμενος εὐθὺς ἀπὸ τῆς Καρχηδονίων διώξεως αὑτῷ τὸν Σκιπίωνα ἐπανίοντα ἐπιστήσεσθαι. ὅθεν καὶ τοῦδε τὸν χάρακα καὶ τὴν ἐν αὐτῷ παρασκευὴν εἷλε Μασσανάσσης.", "st": "9.22"}, {"sp": "N", "t": "καὶ Ῥωμαῖοι διὰ τόλμης μιᾶς, ἐν ὀλίγῳ μέρει νυκτός, δύο στρατοπέδων καὶ δύο στρατῶν πολὺ μειζόνων ἐκράτησαν ὁμοῦ. ἀπέθανον δὲ Ῥωμαίων μὲν ἀμφὶ τοὺς ἑκατὸν ἄνδρας, τῶν δ’ ἐχθρῶν ὀλίγῳ δέοντες τρισμύριοι· καὶ αἰχμάλωτοι ἐγένοντο δισχίλιοι καὶ τετρακόσιοι. τῶν δὲ ἱππέων ἑξακόσιοι ἐπανιόντι τῷ Σκιπίωνι ἑαυτοὺς παρέδοσαν. καὶ τῶν ἐλεφάντων οἱ μὲν ἀνῄρηντο, οἱ δὲ ἐτέτρωντο. Σκιπίων δὲ ὅπλων τε καὶ χρυσοῦ καὶ ἀργύρου καὶ ἐλέφαντος πολλοῦ καὶ ἵππων ἄλλων τε καὶ Νομαδικῶν κεκρατηκώς, καὶ διὰ μιᾶς τῆσδε νίκης, λαμπροτάτης δὴ γενομένης, ἐς γόνυ τὰ Καρχηδονίων καταβαλὼν ἅπαντα, ἀριστεῖα τῷ στρατῷ διεδίδου, καὶ τῶν λαφύρων τὰ ἀξιολογώτατα ἐς Ῥώμην ἔπεμπεν. καὶ τὸν στρατὸν ἐγύμναζε φιλοπόνως, προσδοκῶν Ἀννίβαν τε αὐτίκα ἀπὸ τῆς Ἰταλίας καὶ Μάγωνα ἀπὸ Λιγυστίνων ἐπελεύσεσθαι.", "st": "9.23"}, {"sp": "N", "t": "καὶ Σκιπίων μὲν περὶ ταῦτα ἦν, Ἀσδρούβας δέ, ὁ στρατηγὸς ὁ Καρχηδονίων, ἐν μὲν τῇ νυκτομαχίᾳ μεθ’ ἱππέων πεντακοσίων, τετρωμένος, ἐς Ἀνδὰν κατέφυγεν, ἔνθα μισθοφόρους τέ τινας ἐκ τῆς μάχης ἐκπεσόντας καὶ Νομάδας συνέλεγε, καὶ δούλους ἐς ἐλευθερίαν συνεκάλει· πυθόμενος δ’ ὅτι Καρχηδόνιοι θάνατον αὐτοῦ κατέγνωσαν ὡς κακῶς ἐστρατηγηκότος, καὶ Ἄννωνα τὸν Βουμίλχαρος εἵλοντο στρατηγεῖν, ἴδιον αὑτοῦ τὸν στρατὸν ἐποίει, καὶ κακούργους προσελάμβανε, καὶ ἐλῄζετο ἐς τὰς τροφάς, καὶ ἐγύμναζεν οὓς εἶχεν, ἀμφὶ τρισχιλίους ἱππέας, πεζοὺς δὲ ὀκτακισχιλίους, ὡς ἐν μόνῳ τῷ μάχεσθαι τὰς ἐλπίδας ἔχων. ὁ μὲν δὴ ταῦτα ποιῶν Ῥωμαίους ὁμοῦ καὶ Καρχηδονίους ἐπὶ πολὺ ἐλάνθανε, Σκιπίων δ’ ἐπῆγεν αὐτῇ Καρχηδόνι τὸν στρατὸν ὡπλισμένον, καὶ σοβαρῶς ἐς μάχην προυκαλεῖτο, οὐδενὸς ἐξιόντος. Ἀμίλχαρ δὲ ὁ ναύαρχος ναυσὶν ἑκατὸν ἐσπευσμένως ἐς τὸν ναύσταθμον ἀνήγετο τοῦ Σκιπίωνος, ἐλπίσας αὐτόν τε φθάσειν ἐπανιόντα, καὶ τὰς οὔσας ἐκεῖ Ῥωμαίων εἴκοσι τριήρεις ῥᾳδίως ταῖς ἑκατὸν αἱρήσειν.", "st": "9.24"}, {"sp": "N", "t": "καὶ ὁ Σκιπίων ἰδὼν αὐτοῦ τὸν ἀπόπλουν, προύπεμπέ τινας τὸν ἔσπλουν τοῦ λιμένος ἐμφράξαι στρογγύλοις πλοίοις ἐπ’ ἀγκυρῶν ἐκ διαστήματος, ἵνα ὡς διὰ πυλῶν αἱ τριήρεις ἐκθέοιεν ὅτε καιρὸς εἴη, καὶ τὰ πλοῖα τοῖς κέρασι συνδῆσαί τε καὶ ἁρμόσαι πρὸς ἄλληλα, ἵνα ἀντὶ τείχους ἦ. καταλαβὼν δὲ τὸ ἔργον, ἥπτετο τοῦ πόνου. καὶ βαλλομένων τῶν Καρχηδονίων ἀπό τε τῶν πλοίων καὶ ἀπὸ τῆς γῆς καὶ ἀπὸ τοῦ τείχους, αἱ νῆες ἐθραύοντο, καὶ καμοῦσαι περὶ ἑσπέραν ἀπέπλεον. ἀπιούσαις δ’ αὐταῖς αἱ Ῥωμαίων ἐπέκειντο, ἐκθέουσαί τε διὰ τῶν διαστημάτων, καὶ ὅτε βιάζοιντο, ὑποχωροῶσαι. μίαν δὲ καὶ ἀνεδήσαντο κενὴν ἀνδρῶν, καὶ πρὸς τὸν Σκιπίωνα ἀνήγαγον. μετὰ δὲ τοῦτο ἐχείμαζον ἄμφω. καὶ Ῥωμαίοις μὲν ἦν ἐκ θαλάσσης ἀγορὰ δαψιλής, Ἰτυκαῖοι δὲ καὶ Καρχηδόνιοι λιμώττοντες ἐλῄστευον τοὺς ἐμπόρους, μέχρι Ῥωμαίων νῆες ἄλλαι, πεμφθεῖσαι τῷ Σκιπίωνι, ἐφώρμουν τοῖς πολεμίοις καὶ τὰς λῃστρικὰς ἐκώλυον. οἱ δ’ ἔκαμνον ἤδη σφόδρα τῷ λιμῷ.", "st": "9.25"}, {"sp": "N", "t": "τοῦ δ’ αὐτοῦ χειμῶνος, ἐγγὺς ὄντος Σύφακος, Μασσανάσσης ᾔτησεν ἐπὶ τῇ ἰδίᾳ στρατιᾷ τὸ τρίτον τῆς Ῥωμαικῆς παρὰ Σκιπίωνος, καὶ λαβὼν ἡγουμένου τῶν Ῥωμαίων Λαιλίου, τὸν Σύφακα ἐδίωκεν. ὁ δὲ ὑπέφευγε, μέχρι καθορώμενος περί τινι ποταμῷ συνετάσσετο ἐς μάχην. οἱ μὲν οὖν Νομάδες ἑκατέρωθεν, ὥσπερ ἔθος αὐτοῖς, πολλὰ καὶ ἀθρόα ἠφίεσαν ἐπ’ ἀλλήλοις, οἱ δὲ Ῥωμαῖοι προβαλλόμενοι τὰς ἀσπίδας ἐπῄεσαν. Σύφαξ δὲ Μασσανάσσην ἰδών, ἵετο ἐπ’ αὐτὸν ὑπ’ ὀργῆς· ὁ δ’ ἀντεπήλασε γεγηθώς. καὶ ἀγῶνος πολλοῦ περὶ ἄμφω γενομένου, τραπέντες οἱ τοῦ Σύφακος ἐς φυγὴν τὸν ποταμὸν ἐπέρων, ἔνθα τις αὐτοῦ Σύφακος τὸν ἵππον ἔβαλεν· ὁ δ’ ἀπεσείσατο τὸν δεσπότην, καὶ ὁ Μασσανάσσης ἐπιδραμὼν εἷλεν αὐτόν τε Σύφακα καὶ τὸν ἕτερον αὐτοῦ τῶν υἱῶν. καὶ τούσδε μὲν εὐθὺς ἔπεμπε Σκιπίωνι, ἀπέθανον δ’ ἐν τῇ μάχῃ Σύφακος μὲν ἐς μυρίους ἄνδρας, Ῥωμαίων δὲ πέντε καὶ ἑβδομήκοντα, Μασσανάσσου δὲ τριακόσιοι. καὶ αἰχμάλωτοι Σύφακος ἐγένοντο τετρακισχίλιοι. τούτων ἦσαν Μασσύλιοι δισχίλιοι καὶ πεντακόσιοι, τῶν ἐς Σύφακα ἀπὸ Μασσανάσσου μεταστάντων· καὶ αὐτοὺς ὁ Μασσανάσσης ἐπὶ τῷδε ᾔτησε παρὰ Λαιλίου, καὶ λαβὼν κατέσφαξεν.", "st": "9.26"}, {"sp": "N", "t": "μετὰ δὲ τοῦτο Μασσυλίους καὶ τὴν χώραν τὴν Σύφακος ἐπῄεσαν, τοὺς μὲν αὖθις ἐς τὴν ἀρχὴν τὴν Μασσανάσσου καθιστάμενοι, τοὺς δὲ προσποιούμενοί τε καὶ τοὺς ἀπειθοῦντας αὐτῶν καταστρεφόμενοι. ἀφίκοντο δ’ αὐτοῖς καὶ ἐκ Κίρτης πρέσβεις, τὰ βασίλεια τοῦ Σύφακος παραδιδόντες, ἰδίᾳ δὲ πρὸς Μασσανάσσην ἕτεροι παρὰ Σοφωνίβας τῆς Σύφακος γυναικός, τὴν ἀνάγκην τοῦ γάμου διηγούμενοι. Σοφωνίβαν μὲν οὖν ἄσμενος εἶχε λαβὼν ὁ Μασσανάσσης· καὶ αὐτήν, ἐπανιὼν πρὸς Σκιπίωνα αὐτός, ἐν Κίρτῃ κατέλιπε, προορώμενος ἄρα τὸ μέλλον. Σκιπίων δὲ ἤρετο Σύφακα· “τίς σε δαίμων ἔβλαψε, φίλον ὄντα μοι καὶ ἐπὶ Λιβύην ἐλθεῖν προτρέψαντα, ψεύσασθαι μὲν θεοὺς οὓς ὤμοσας, ψεύσασθαι δὲ μετὰ τῶν θεῶν Ῥωμαίους, καὶ μετὰ Καρχηδονίων ἀντὶ Ῥωμαίων ἑλέσθαι πολεμεῖν, τῶν ἐπὶ Καρχηδονίους οὐ πρὸ πολλοῦ σοι βεβοηθηκότων;” ὁ δ’ εἶπε, “Σοφωνίβα Ἀσδρούβα θυγάτηρ, ἧς ἐγὼ ἤρων ἐπ’ ἐμῷ κακῷ. φιλόπατρις δ’ ἐστὶν ἰσχυρῶς, καὶ ἱκανὴ ἅπαντά τινα πεῖσαι πρὸς ἃ βούλεται. αὕτη με καὶ ἐκ τῆς ὑμετέρας φιλίας ἐς τὴν ἑαυτῆς μετέθηκε πατρίδα, καὶ ἐς τόδε συμφορᾶς ἐκ τοσῆσδε εὐδαιμονίας κατέβαλεν. σοὶ δὲ παραινῶ (χρὴ γάρ, ὑμέτερον γενόμενον καὶ Σοφωνίβας ἀπηλλαγμένον, νῦν γε ὑμῖν εἶναι βέβαιον)· φύλασσε Σοφωνίβαν, μὴ Μασσανάσσην ἐς ἃ βούλεται μεταγάγῃ. οὐ γὰρ δή, μὴ τὸ γύναιόν ποτε ἕληται τὰ Ῥωμαίων ἐλπίζειν ἄξιον· οὕτως ἐστὶν ἰσχυρῶς φιλόπολις.”", "st": "9.27"}, {"sp": "N", "t": "ταῦθ’ ὁ μὲν ἔλεγεν, εἴτ’ ἀληθεύων εἴτε ζηλοτυπούμενος καὶ Μασσανάσσην ἐς τὰ μέγιστα βλάπτων· ὁ δὲ Σκιπίων Σύφακα μέν, συνετόν τε φαινόμενον καὶ τῆς χώρας ἔμπειρον, ἐπὶ τὰ κοινὰ ἐπήγετο, καὶ γνώμης καὶ συμβουλῆς μετεδίδου, οἷόν τι καὶ Κροίσῳ τῷ Λυδῷ Κῦρος ἐχρῆτο, Λαιλίου δ’ ἀφικομένου, καὶ ταὐτὰ περὶ τῆς Σοφωνίβας πυθέσθαι παρὰ πολλῶν λέγοντος, ἐκέλευσε τὸν Μασσανάσσην τὴν Σύφακος γυναῖκα παραδοῦναι. παραιτουμένου δ’ ἐκείνου, καὶ τὰ περὶ αὐτῆς ἄνωθεν ὡς ἐγένετο διηγουμένου, τραχύτερον ὁ Σκιπίων ἐκέλευεν αὐτὸν μηδὲν ἀφαιρεῖσθαι βίᾳ των Ῥωμαικῶν λαφύρων, ἀλλ’ ἐς τὸ μέσον καταθέντα αἰτεῖν, καὶ πείθειν, εἰ δύναιτο. ᾤχετο οὖν ὁ Μασσανάσσης μετὰ τινῶν Ῥωμαίων, παραδώσων αὐτοῖς τὴν Σοφωνίβαν. κρύφα δὲ αὐτῇ φέρων φάρμακον πρῶτος ἐνέτυχε, καὶ τὰ παρόντα προύθηκεν, ἢ πιεῖν ἢ Ῥωμαίοις δουλεύειν ἑκοῦσαν. οὐδέν τε εἰπὼν ἔτι ἐξήλασε τὸν ἵππον. ἡ δὲ τῇ τροφῷ δείξασα τὴν κύλικα, καὶ δεηθεῖσα μηδὲν ὀδύρασθαι καλῶς ἀποθανοῦσαν, ἔπιε τοῦ φαρμάκου. καὶ αὐτὴν ὁ Μασσανάσσης τοῖς ἥκουσι Ῥωμαίων ἐπιδείξας, καὶ θάψας βασιλικῶς, ὑπέστρεφε πρὸς Σκιπίωνα. ὁ δὲ αὐτὸν ἐπαινέσας τε, καὶ παρηγορήσας ὅτι πονηρᾶς γυναικὸς ἀπηλλάγη, ἐστεφάνωσε τῆς ἐφόδου τῆς ἐπὶ Σύφακα καὶ ἐδωρήσατο πολλοῖς. ἀχθέντος δ’ ἐς Ῥώμην τοῦ Σύφακος, οἱ μὲν ἠξίουν περισώζειν ἄνδρα ἐν Ἰβηρίᾳ φίλον καὶ σύμμαχον αὐτοῖς γενόμενον, οἱ δὲ κολάζειν, ὅτι τοῖς φίλοις ἐπολέμησεν. ὁ δὲ ὑπὸ λύπης νοσῶν ἀπέθανεν.", "st": "9.28"}, {"sp": "N", "t": "Ἀσδρούβας δὲ ἐπειδὴ καλῶς τοὺς συνόντας ἐγύμνασεν, ἔπεμπέ τινα πρὸς Ἄννωνα τὸν στρατηγὸν τῶν Καρχηδονίων, ἀξιῶν αὑτῷ τὸν Ἄννωνα κοινωνῆσαι τὴν στρατηγίαν, καὶ ὑποδεικνὺς ὅτι πολλοὶ Σκιπίωνι σύνεισιν Ἴβηρες ἄκοντες, οὓς ἐάν τις χρυσίῳ καὶ ὑποσχέσεσι διαφθείρῃ, τὸ στρατόπεδον ἐμπρήσουσι τὸ Σκιπίωνος. ἔφη δὲ καὶ αὐτός, εἰ προμάθοι τὸν καιρόν, ἥξειν ἐπὶ τὸ ἔργον. ταῦτα μὲν Ἀσδρούβας, ὁ δὲ Ἄννων ἐς μὲν τὸν Ἀσδρούβαν ἐπανούργει, τοῦ δ’ ἐγχειρήματος οὐκ ἀπήλπισεν, ἀλλ’ ἄνδρα πιστὸν μετὰ χρυσίου, καθάπερ αὐτόμολον, ἐς τὸ Σκιπίωνος στρατόπεδον κατέπεμψεν, ὃς πιθανὸς ὢν ἐντυχεῖν ἑκάστῳ διέφθειρε πολλούς, ἡμέραν τε συνθέμενος αὐτοῖς ἐπανῆλθεν. καὶ τὴν ἡμέραν ὁ Ἄννων τῷ Ἀσδρούβᾳ μετέφερεν. Σκιπίωνι δὲ θυομένῳ κίνδυνον τὰ ἱερὰ ἐδήλου ἐμπρησμοῦ· καὶ περιπέμψας ἐς ἅπαν τὸ στρατόπεδον, εἴ πού τι λάβρον ηὕρισκε πῦρ, κατέπαυεν. καὶ αὖθις ἐπὶ πολλὰς ἡμέρας ἐθύετο. ὡς δ’ οὐκ ἀνίει τὰ ἱερὰ τὸν ἐμπρησμὸν ὑποδεικνύοντα, ὁ μὲν ἐβαρυθύμει καὶ μεταστρατοπεδεῦσαι διεγνώκει,", "st": "9.29"}, {"sp": "N", "t": "ἱππέως δὲ Ῥωμαίου θεράπων Ἴβηρ, ὑπονοήσας τι περὶ τῶν συνθεμένων, ὑπεκρίνατο συνειδέναι, ἕως τὸ πᾶν ἔμαθε, καὶ ἐμήνυσε τῷ δεσπότῃ, ὁ δὲ αὐτὸν ἐς τὸν Σκιπίωνα ἤγαγε, καὶ τὸ πλῆθος ἠλέγχετο. καὶ πάντας ὁ Σκιπίων ἔκτεινε καὶ ἐξέρριψε πρὸ τοῦ στρατοπέδου. αἴσθησις δ’ ἦν Ἄννωνι μὲν ὀξεῖα πλησίον ὄντι, καὶ οὐκ ἦλθεν ἐπὶ τὸ συγκείμενον, Ἀσδρούβας δὲ ἀγνοῶν ἀφίκετο. ὡς δὲ τὸ πλῆθος εἶδε τῶν νεκρῶν, εἴκασε τὸ συμβὰν καὶ ἀνεχώρει. καὶ αὐτὸν ὁ Ἄννων ἐς τὸ πλῆθος διέβαλλεν, ὡς ἀφίκοιτο Σκιπίωνι διδοὺς ἑαυτόν, ὁ δὲ οὐ λάβοι. Ἀσδρούβας μὲν δὴ καὶ ἐκ τοῦδε τοῖς Καρχηδονίοις ἦν μᾶλλον διὰ μίσους· ὑπὸ δὲ τὸν αὐτὸν καιρὸν Ἀμίλχαρ μὲν ἄφνω ταῖς Ῥωμαίων να υσὶν ἐπιπλεύσας μίαν ἔλαβε τριήρη καὶ φορτίδας ἕξ, Ἄννων δ’ ἐπιθέμενος τοῖς πολιορκοῦσιν Ἰτύκην ἀπεκρούσθη. Σκιπίων δέ, χρονίου τῆς πολιορκίας οὔσης, ταύτην μὲν διέλυσεν οὐδὲν ἀνύων, τὰς δὲ μηχανὰς ἐς Ἱππῶνα πόλιν μετετίθει. καὶ οὐδενὸς οὐδ’ ἐνταῦθα προκόπτοντος αὐτῷ, κατακαύσας ὡς ἄχρηστα τὰ μηχανήματα τὴν χώραν ἐπέτρεχε, τοὺς μὲν ἐς φιλίαν ἐπαγόμενος, τοὺς δὲ λῃζόμενος.", "st": "9.30"}, {"sp": "N", "t": "Καρχηδόνιοι δ’ ἐπὶ ταῖς κακοπραγίαις δυσφοροῦντες αἱροῦνται στρατηγὸν αὐτοκράτορα Ἀννίβαν, τὸν δὲ ναύαρχον ἔπεμπον ἐπὶ νεῶν, ἐπισπέρχειν αὐτὸν ἐπὶ τὴν διάβασιν. ἅμα δὲ ταῦτ’ ἔπρασσον, καὶ ἐς τὸν Σκιπίωνα περὶ εἰρήνης ἐπρεσβεύοντο, ἡγούμενοι τούτοιν πάντως ἂν ἑνὸς τυχεῖν, ἢ τὴν εἰρήνην ἕξειν, ἢ χρόνον διατρίψειν ἕως ἀφίκοιτο ὁ Ἀννίβας. Σκιπίων μὲν οὖν αὐτοῖς ἀνοχάς τε ἔδωκε, καὶ τὴν δαπάνην τοῦ στρατοῦ λαβὼν πρεσβεύειν ἐφῆκεν ἐς Ῥώμην· οἱ δὲ ἐπρέσβευον, καὶ τειχῶν ἐκτὸς ἐστάθμευον ὡς ἔτι πολέμιοι, ἀχθέντες τε ἐπὶ τὴν βουλὴν ἐδέοντο συγγνώμης τυχεῖν. τῶν δὲ βουλευτῶν οἱ μὲν τῆς Καρχηδονίων ἀπιστίας ὑπεμίμνησκον, ὁσάκις συνθοῖντο καὶ παραβαῖεν, ὅσα τε Ἀννίβας δράσειε δεινὰ Ῥωμαίους καὶ τοὺς Ῥωμαίων συμμάχους ἔν τε Ἰβηρίᾳ καὶ Ἰταλίᾳ· οἱ δὲ τὸ τῆς εἰρήνης χρήσιμον οὐ Καρχηδονίοις μᾶλλον ἢ σφίσιν ὑπεδείκνυον ἔσεσθαι, τῆς Ἰταλίας τοσοῖσδε πολέμοις ἐκτετρυχωμένης, τό τε τοῦ μέλλοντος περιδεὲς ἐπεξῄεσαν, ἐπιπλευσουμένων ἐπὶ τὸν Σκιπίωνα αὐτίκα σὺν μεγάλοις στρατοῖς Ἀννίβου τε ἐξ Ἰταλίας καὶ Μάγωνος ἐκ Λιγύων καὶ Ἄννωνος ἀπὸ Καρχηδόνος.", "st": "9.31"}, {"sp": "N", "t": "ἐφ’ οἷς ἀποροῦσα ἡ βουλὴ συμβούλους ἔπεμψε τῷ Σκιπίωνι, μεθ’ ὧν ἔμελλε κρινεῖν τε καὶ πράξειν ὅ τι δοκιμάσειε συνοίσειν. ὁ δὲ ἐς τὴν εἰρήνην τοῖς Καρχηδονίοις ἐπὶ τοῖσδε συνέβη, Μάγωνα μὲν ἀποπλεῖν ἐκ Λιγύων αὐτίκα, καὶ τοῦ λοιποῦ Καρχηδονίους μὴ ξενολογεῖν, μηδὲ ναῦς ἔχειν μακρὰς πλείους τριάκοντα, μηδὲ πολυπραγμονεῖν τι πέρα ὧν ἔχουσιν ἐντὸς τῶν λεγομένων Φοινικίδων τάφρων, ἀποδοῦναι δὲ Ῥωμαίοις ὅσους αἰχμαλώτους αὐτῶν ἔχουσι καὶ αὐτομόλους, ἀργυρίου τε αὐτοῖς τάλαντα χίλια καὶ ἑξακόσια ἐσενεγκεῖν ἐν χρόνῳ, ἔχειν δὲ Μασσανάσσην Μασσυλίους τε καὶ τῆς Σύφακος ἀρχῆς ὅσα δύναιτο. τάδε μὲν συνέθεντο ἀλλήλοις. καὶ πρέσβεις διέπλεον, οἱ μὲν ἐς Ῥώμην, τοὺς ὑπάτους ὁρκιοῦντες, οἱ δ’ ἀπὸ Ῥώμης ἐς Καρχηδόνα, καὶ τὰ τέλη τῶν Καρχηδονίων αὐτοῖς ὤμνυεν. Μασσανάσσῃ δὲ Ῥωμαῖοι χαριστήρια τῆς συμμαχίας στέφανόν τε ἀπὸ χρυσοῦ καὶ σφραγῖδα χρυσῆν ἔπεμπον, καὶ ἐλεφάντινον δίφρον καὶ πορφύραν καὶ στολὴν Ῥωμαϊκὴν καὶ ἵππον χρυσοφάλαρον καὶ πανοπλίαν.", "st": "9.32"}, {"sp": "N", "t": "γιγνομένων δ’ ἔτι τούτων ὁ Ἀννίβας ἄκων ἐς Καρχηδόνα ἔπλει, τὴν ἐς τοὺς ἄρχοντας ἀπιστίαν τοῦ δήμου καὶ ταχυεργίαν ὑφορώμενος. ἀπιστῶν δ’ ἔτι τὰς σπονδὰς ἔσεσθαι, καὶ εἰ γένοιντο, εὖ εἰδὼς οὐκ ἐς πολὺ βεβαίους ἐσομένας, ἐς Ἀδρυμητὸν Λιβύης κατήγετο πόλιν, καὶ σῖτον συνέλεγεν, ἐπί τε ὠνὴν ἵππων περιέπεμπε, καὶ τὸν δυνάστην τῶν Νομάδων τῶν καλουμένων Ἀρεακιδῶν ἐς φιλίαν ὑπήγετο. καὶ τετρακισχιλίους ἱππέας αὐτομόλους αὐτῷ προσφυγόντας, οἳ Σύφακος ὄντες τότε ἐγίγνοντο Μασσανάσσου, κατηκόντισεν ὑποπτεύσας· τοὺς δ’ ἵππους διέδωκε τῷ στρατῷ. ἦλθε δε και Μεσοτυλος αὐτῷ δυνάστης ἕτερος μετὰ χιλίων ἱππέων, καὶ Οὐερμινᾶς Σύφακος υἱὸς ἕτερος, ἔτι τῶν πλεόνων τῆς πατρῴας ἀρχῆς ἐπικρατῶν. πόλεις τε Μασσανάσσου τὰς μὲν ὑπήγετο, τὰς δ’ ἐβιάζετο. νάρκην δ’ ἐνήδρευσεν ὧδε. ἀγορᾷ χρώμενος ἐσέπεμπεν ὡς ἐς φίλους. ὅτε δ’ ἔδοξεν ἐπιθέσθαι, πλείους ἔπεμπε ξιφίδια ἐπικρύπτοντας, οἷς εἴρητο τὰ δίκαια ποιεῖν ἐς τοὺς πιπράσκοντας μέχρι σαλπίγγων ἀκούσειαν, τότε δ’ ἐπιχειρεῖν τοῖς ἐντυχοῦσι καὶ τὰς πύλας οἱ φυλάσσειν.", "st": "9.33"}, {"sp": "N", "t": "οὕτω μὲν ἑάλω Νάρκη, Καρχηδονίων δε ὁ δῆμος ἄρτι τὰς συνθήκας πεποιημένοι, καὶ Σκιπίωνος αὐτοῖς ἔτι παρόντος, οὔπω τῶν ἰδίων πρέσβεων ἀπὸ Ῥώμης ἀνεστροφότων, ἀγορὰν Σκιπίωνος ὑπ’ ἀνέμων κατενεχθεῖσαν ἐς Καρχηδόνα διήρπασαν, καὶ τοὺς παραπέμποντας αὐτὴν ἔδησαν, πολλὰ τῆς βουλῆς ἀπειλούσης, καὶ παραινούσης μὴ λύειν συνθήκας ἄρτι γεγενημένας· οἱ δὲ καὶ ταῖς συνθήκαις ἐπεμέμφοντο ὡς ἀδίκως γενομέναις, καὶ τὸν λιμὸν ἔφασαν ἐνοχλεῖν ὑπὲρ τὰς παραβάσεις. Σκιπίων μὲν οὖν οὐκ ἠξίου πολέμου κατάρχειν μετὰ σπονδάς, ἀλλ’ ᾔτει δίκας ὡς φίλους ἁμαρτόντας· οἱ δὲ καὶ τοὺς πρέσβεις αὐτοῦ κρατεῖν ἐπενόουν, ἕως ἀφίκοιντο αὑτοῖς οἱ ἀπὸ Ῥώμης. ἀλλὰ τούσδε μὲν Ἄννων τε ὁ μέγας καὶ Ἀσδρούβας ὁ ἔριφος ἐξείλοντο τοῦ πλήθους καὶ προύπεμπον δύο τριήρεσιν· ἕτεροι δὲ Ἀσδρούβαν τὸν ναύαρχον ἔπεισαν, ὁρμοῦντα περὶ τὴν Ἀπόλλωνος ἄκραν, ὅταν ἀποστῶσιν αἱ προπομποὶ τριήρεις, ἐπιθέσθαι τοῖς τοῦ Σκιπίωνος. καὶ ὁ μὲν ἐπέθετο, καὶ τῶν πρέσβεών τινες ἐκ τοξευμάτων ἀπέθανον· οἱ δὲ λοιποὶ τιτρωσκόμενοί τε καὶ ἐρέσσοντες ἔφθασαν ἐς τὸν λιμένα τοῦ σφετέρου στρατοπέδου, καὶ ἐξήλαντο τῆς νεὼς ἤδη λαμβανομένης. παρὰ τοσοῦτον ἦλθον αἰχμάλωτοι γενέσθαι.", "st": "9.34"}, {"sp": "N", "t": "ὧν οἱ ἐν ἄστει Ῥωμαῖοι πυθόμενοι τοὺς πρέσβεις τοὺς Καρχηδονίων, οἳ περὶ τῆς εἰρήνης ἔτι παρῆσαν, ἐκέλευον ἀποπλεῖν αὐτίκα ὡς πολεμίους. καὶ οἱ μὲν ἐξέπλεον, καὶ ὑπὸ τοῦ χειμῶνος ἐς τὸ τοῦ Σκιπίωνος στρατόπεδον κατήγοντο· Σκιπίων δὲ τῷ ναυάρχῳ, πυθομένῳ περὶ αὐτῶν ὅ τι δέοι ποιεῖν, “οὐδὲν ὅμοιον,” ἔφη, “ταῖς Καρχηδονίων ἀπιστίαις, ἀλλ’ ἀπόπεμπε ἀπαθεῖς.” μαθοῦσα δ’ ἡ γερουσία τὸν δῆμον ὠνείδιζε τῇ συγκρίσει, καὶ συνεβούλευε καὶ νῦν δεηθῆναι Σκιπίωνος τὰ μὲν συγκείμενα φυλάσσειν, δίκας δὲ τῶν ἡμαρτημένων παρὰ Καρχηδονίων λαβεῖν. οἱ δὲ καὶ αὐτῇ τῇ γερουσίᾳ δυσχεραίνοντες ἐκ πολλοῦ διὰ τὴν κακοπραγίαν, ὡς οὐκ εὖ τὰ συμφέροντα προορωμένῃ, καὶ ὑπ’ ἀνδρῶν δημοκόπων ἐρεθιζόμενοί τε καὶ ἐς ἀλόγους ἐλπίδας ἐπαιρόμενοι, τὸν Ἀννίβαν ἐκάλουν υεθ’ ἧς ἔχει στρατιᾶς.", "st": "9.35"}, {"sp": "N", "t": "ὁ δὲ ὁρῶν τὸ μέγεθος τοῦ πολεμου, Ἀσδρούβαν αὐτοὺς ἐκέλευε σὺν τῇ παρούσῃ δυνάμει καλεῖν. Ἀσδρούβας μὲν δὴ τῆς καταδίκης αὐτῷ λυθείσης παρεδίδου τὸν στρατὸν Ἀννίβᾳ, καὶ οὐδ’ ὣς ἐπιφαίνεσθαι τοῖς Καρχηδονίοις ἐθάρρει, ἀλλ’ ἐκρύπτετο ἐν τῇ πόλει· Σκιπίων δὲ ναῦς τῇ Καρχηδόνι ἐπιστήσας εἶργεν αὐτοὺς ἀγορᾶς ἀπὸ θαλάσσης, οὐκ εὐποροῦντας οὐδ’ ἀπὸ τῆς γῆς ἀσπόρου διὰ τὸν πόλεμον γενομένης. τῶν δ’ αὐτῶν ἡμερῶν Ἀννίβου καὶ Σκιπίωνος ἱππομαχία γίγνεται περὶ Ζάμαν, ἐν ᾗ Σκιπίων ἐπλεονέκτει· καὶ ταῖς ἐπιούσαις ἀκροβολίσματα ἦν ἐς ἀλλήλους, ἕως αἰσθόμενος ὁ Σκιπίων Ἀννίβαν ἰσχυρῶς τε ἀπορούμενον καὶ περιμένοντα ἀγορὰν φερομένην, νυκτὸς ἔπεμψε Θέρμον χιλίαρχον ἐπὶ τοὺς ἄγοντας αὐτήν. καὶ λόφον ὁ Θέρμος ἐν στενῇ διόδῳ καταλαβών, ἔκτεινε τῶν Λιβύων ἐς τετρακισχιλίους καὶ ἐζώγρησεν ἑτέρους τοσούσδε, καὶ τὴν ἀγορὰν ἧκε φέρων τῷ Σκιπίωνι.", "st": "9.36"}, {"sp": "N", "t": "ὁ δ’ Ἀννίβας ἐς ἔσχατον ἀφιγμένος ἀποριας, καὶ τὸ παρὸν ἐπινοῶν ὅπως δύναιτο διαθέσθαι, πρέσβεις ἐς Μασσανάσσην ἔπεμπεν, ὑπομιμνήσκων τε τῆς ἐν Καρχηδόνι διατριβῆς καὶ παιδεύσεως, καὶ παρακαλῶν ἔτι οἱ συναγαγεῖν ἐς συνθήκας Σκιπίωνα· τὰ γὰρ πρότερα τοῦ δήμου καὶ τῶν ἀνοητοτέρων τοῦ δήμου ἁμαρτήματα γενέσθαι. ὁ δὲ τῷ ὄντι τεθραμμένος τε καὶ πεπαιδευμένος ἐν Καρχηδόνι, καὶ τὸ ἀξίωμα τῆς πόλεως αἰδούμενός τε καὶ φίλος ὢν ἔτι πολλοῖς ἐκεῖθεν, ἐδεήθη τοῦ Σκιπίωνος, καὶ συνήγαγεν αὐτοὺς αὖθις ἐς τοιάσδε συνθήκας ὥστε Καρχηδονίους τάς τε ναῦς καὶ τοὺς ἄνδρας, οὓς ἔλαβον Ῥωμαίοις ἀγορὰν φέροντας, ἀποδοῦναι, καὶ τὰ ἡρπασμένα ἅπαντα, ἢ τῶν ἀπολωλότων τιμὴν ἣν ἂν ὁρίσῃ Σκιπίων, ποινήν τε τοῦ ἀδικήματος χίλια τάλαντα ἐσενεγκεῖν, τάδε μὲν ἦν τὰ συγκείμενα, καὶ γενομένων ἀνοχῶν μέχρι αὐτὰ μάθωσι Καρχηδόνιοι, ὁ μὲν Ἀννίβας ἐξ ἀέλπτου περιεσώζετο,", "st": "9.37"}, {"sp": "N", "t": "Καρχηδονίων δ’ ἡ μὲν βουλὴ τὰ συμβάντα ὑπερησπάζετο, καὶ παρεκάλει τὸν δῆμον ἐμμεῖναι τοῖς ἐγνωσμένοις, τήν τε κακοπραγίαν σφῶν τὴν ἐς ἅπαντα διηγουμένη καὶ τὴν παροῦσαν ἀπορίαν στρατοῦ τε καὶ χρημάτων καὶ ἀγορᾶς. οἱ δέ, οἷον ὄχλος, ἀφρόνως ἡγοῦντο τοὺς στρατηγοὺς σφῶν δι’ ἑαυτοὺς ταῦτα Ῥωμαίοις συντίθεσθαι, ἵνα δι’ ἐκείνων δυναστεύσωσι τῆς πατρίδος· ὃ καὶ Ἀννίβαν νῦν καὶ Ἀσδρούβαν οὐ πρὸ πολλοῦ ποιῆσαί τε, καὶ τὸ στρατόπεδον νυκτὸς ἐγχειρίσαντα τοῖς πολεμίοις, μετ’ ὀλίγον καὶ ἑαυτὸν ἐθελῆσαι τῷ Σκιπίωνι ἐνδοῦναι ἐπὶ τῷδε προσπελάσαντα, κρύπτεσθαί τε νῦν ἐν τῇ πόλει. βοῆς δ’ ἐπὶ τούτῳ καὶ θορύβου γενομένου. τὴν ἐκκλησίαν τινὲς καταλιπόντες ἐζήτουν Ἀσδρούβαν περιιόντες. ὁ δ’ ἔφθασε μὲν ἐς τὸν τοῦ πατρὸς τάφον καταφυγὼν καὶ φαρμάκῳ διαχρησάμενος αὑτόν· οἱ δὲ κἀκεῖθεν αὐτοῦ τὸν νέκυν ἐξελόντες, καὶ τὴν κεφαλὴν αὐτοῦ ἀποτεμόντες περιέφερον ἐπὶ δόρατος ἀνὰ τὴν πόλιν. Ἀσδρούβας μὲν δὴ καὶ τὸ πρῶτον ἀδίκως ἐξεπεπτώκει, καὶ τὸ δεύτερον ψευδῶς διεβέβλητο ὑπὸ Ἄννωνος, καὶ τότε πρὸς Καρχηδονίων οὕτως ἀνῄρητο καὶ οὕτως ἀποθανὼν ὑβρίζετο.", "st": "9.38"}, {"sp": "N", "t": "Καρχηδόνιοι δ’ ἐπέστελλον Ἀννίβᾳ λῦσαι τὰς ἀνοχὰς καὶ πολεμεῖν Σκιπίωνι, κρῖναι δ’ ὅτι τάχιστα τὸν πόλεμον μάχῃ διὰ τὴν ἀπορίαν. ὁ μὲν δὴ πέμψας ἔλυσε τὰς ἀνοχάς, καὶ Σκιπίων Πάρθον τε, μεγάλην πόλιν, αὐτίκα προσπεσὼν εἷλε, καὶ πλησίον Ἀννίβου μετεστρατοπέδευεν. ο δὲ ἀνεζεύγνυε, τρεῖς τοῖς Ῥωμαιοις κατασκοπους ἐπιπέμψας, οὓς ὁ Σκιπίων ἔλαβέ τε καὶ οὐκ ἔκτεινεν, ὥσπερ ἔθος τοὺς κατασκόπους κτείνειν, ἀλλ’ ἐς τὸ στρατόπεδον καὶ τὰς ὁπλοθήκας καὶ τὰ μηχανήματα περιαχθῆναι κελεύσας, καὶ τὴν στρατιὰν γυμναζομένην ἰδεῖν, ἀπέλυσε φράζειν Αννίβᾳ περὶ ἑκάστων. ὁ δὲ ἠξίωσεν ἔτι συνελθεῖν ἐς λόγους Σκιπίωνι, καὶ συνελθὼν ἔλεγε Καρχηδονίους ἀγανακτῆσαι τῇ πρότερον εἰρήνῃ διὰ τὰ χρήματα, καὶ εἰ τοῦτο ἐκλυθείη, Σικελίας δὲ μόνον ἀξιοῖεν οἱ Ῥωμαῖοι καὶ Ἰβηρίας καὶ νήσων ὅσων ἄρχουσι κρατεῖν, ἔσεσθαι τὰς συνθήκας βεβαίους. ὁ δὲ “πολύ,” ἔφη, “κέρδος Ἀννίβᾳ τῆς φυγῆς ἔσται τῆς ἐξ Ἰταλίας, εἰ ταῦτα προσλάβοι παρὰ Σκιπιωνος.” καὶ ἀπηγόρευε πέμπειν ἔτι πρὸς αὐτόν. διαπειλησάμενοί τε ἀλλήλοις ἀνεζεύγνυον ἑκάτερος ἐς τὸ αὑτοῦ στρατόπεδον.", "st": "9.39"}, {"sp": "N", "t": "πόλις δ’ ἐγγὺς ἦν Κίλλα, καὶ παρ’ αὐτὴν λόφος εὐφυὴς ἐς στρατοπεδείαν, ὃν ἐπινοῶν ὁ Αννίβας προλαβεῖν, ἔπεμπέ τινας διαγράφειν τὸ στρατόπεδον, καὶ εὐθὺς ἀναστήσας ἐβάδιζεν ὡς ἔχων τὸν λόφον. Σκιπίωνος δ’ αὐτὸν φθάσαντός τε καὶ προλαβόντος, ἀποληφθεὶς ἐν πεδίῳ μέσῳ καὶ ἀνύδρῳ διετέλει τὴν νύκτα πᾶσαν ὀρύσσων φρέατα, καὶ ὁ στρατὸς αὐτῷ διαμώμενος τὴν ψάμμον ὀλιγον καὶ θολερὸν ἔπινον ἐπιμόχθως. ἀθεράπευτοί τε καὶ ἄσιτοι, καὶ ἐν τοῖς ὅπλοις ἔνιοι, διενυκτέρευσαν. ὧν ὁ Σκιπίων αἰσθανόμενος προσέβαλεν ἅμα ἕῳ κεκμηκόσιν ἐξ ὁδοῦ καὶ ἀγρυπνίας καὶ ἀνυδρίας. Ἀννίβας δ’ ἤχθετο μέν, οὐχ ὅτε βούλοιτο συνιὼν ἐς μάχην, ἑώρα δὲ ὡς εἴτε μένοι κατὰ χώραν, κακοπαθήσων ὑπὸ τῆς ἀνυδρίας, εἴτε φεύγοι, τὰ φρονήματα τῶν ἐχθρῶν ἀναστήσων καὶ πολλὰ πεισόμενος ὑπ’ αὐτῶν ἐπικειμένων. ὅθεν ἀναγκαῖον ἦν αὐτῷ μάχεσθαι. καὶ παρετασσεν αὐτίκα ἄνδρας μὲν ἐς πεντακισμυρίους, ἐλέφαντας δὲ ὀγδοήκοντα. ἵστη δὲ πρώτους μὲν τοὺς ἐλέφαντας, ἐκ διαστημάτων, ἐφ’ ὅλου τοῦ μετώπου, φοβερώτατα σκευασας. καὶ ὑπ’ αὐτοῖς ἦν τὸ τρίτον τῆς στρατιᾶς, Κελτοὶ καὶ Λίγυες· τοξόται τε αὐτοῖς ἀνεμεμίχατο πάντῃ καὶ σφενδονῆται Μαυρούσιοί τε καὶ Γυμνήσιοι. τούτων δ’ ὄπισθεν ἡ δευτέρα τάξις ἦν, Καρχηδόνιοί τε καὶ Λίβυες. τρίτοι δ’ ὅσοι ἐξ Ἰταλίας εἵποντο αὐτῷ. οἷς δὴ καὶ μάλιστα, ὡς πλέον δεδιόσιν, ἐθάρρει. ἡ δ’ ἵππος περὶ τὰ κέρατα ἦν.", "st": "9.40"}, {"sp": "N", "t": "οὕτω μὲν Ἀννίβας ἐξέτασσε, Σκιπίωνι δ’ ἦσαν ἀμφὶ τοὺς δισμυρίους καὶ τρισχιλίους, ἱππεῖς δ’ Ἰταλῶν καὶ Ῥωμαίων χίλιοι καὶ πεντακόσιοι. συνεμάχει δὲ Μασσανάσσης ἱππεῦσι Νομάσι πολλοῖς, καὶ Δακάμας ἕτερος δυνάστης ἱππεῦσιν ἑξακοσίοις. τὸ μὲν οὖν πεζὸν ἐς τρεῖς καὶ ὅδε τάξεις ἐπέταττεν ὁμοίως Ἀννίβᾳ, λόχους δ’ ὀρθίους ἐποιεῖτο πάντας, ἵνα δι’ αὐτῶν οἱ ἱππεῖς εὐχερῶς διαθέοιεν. ἐφίστη δ’ ἑκάστῳ λόχῳ προμάχους κατὰ μέτωπον, οἳ ξύλα παχέα διπήχη μάλιστα, πυκνὰ καὶ τὰ πολλὰ αὐτῶν σεσιδηρωμένα, ἔμελλον ὡς καταπέλτας ἐκ χειρὸς ἐς τοὺς ἐλέφαντας ἐπιόντας ἀφήσειν. παρήγγελτο δ’ αὐτοῖς τε καὶ τοῖς ἄλλοις πεζοῖς ἐκκλίνειν τὴν ὁρμὴν τῶν θηρίων, καὶ περιθέοντας ἀκοντίζειν ἐς αὐτὰ συνεχῶς, καὶ προσπελάζοντας, ὅτε δύναιντο, ὑποτέμνειν τὰ νεῦρα. οὕτω μὲν οἱ πεζοὶ διετετάχατο τῷ Σκιπίωνι· τοὺς δ’ ἱππέας τοὺς μὲν Νομαδικοὺς ἐπέστησε τοῖς κερασιν, εἰθισμένους τὴν τῶν ἐλεφάντων ὄψιν καὶ ὀδμὴν φέρειν, τοὺς δὲ Ἰταλικοὺς διὰ τὸ ἄηθες ὀπίσω πάντων, ἑτοίμους ἐπελθεῖν διὰ τῶν διαστημάτων, ὅτε τὴν πρώτην τῶν ἐλεφάντων ὁρμὴν ὑπομείνειαν οἱ πεζοί. παρ’ ἕκαστον δὲ τῶν ἱππέων τῶνδε ὑπηρέτης ἦν πολλὰ ἀκόντια φέρων, οἷς ἐπενόει τὰ θηρία ἀμύνεσθαι. οὕτω μὲν αὐτῷ καὶ ἡ ἵππος εἶχε, παρεδίδου δὲ τὸ μὲν δεξιὸν Λαιλίῳ, τὸ δὲ λαιὸν Ὀκταουιῳ. ἐν δὲ τοῖς μέσοις ἤστην αὐτός τε καὶ Ἀννίβας, κατὰ δόξαν ἀλλήλων, ἔχοντες ἀμφ’ αὑτοὺς ἱππέας, ἐπικουρεῖν ὅπῃ τι πονούμενον ἴδοιεν, ὁ μὲν Ἀννίβας τετρακισχιλίους, ὁ δὲ Σκιπίων δισχιλίους, καὶ τοὺς τριακοσίους Ἰταλοὺς οὓς αὐτὸς ὥπλισεν ἐν Σικελίᾳ.", "st": "9.41"}, {"sp": "N", "t": "ἐπεὶ δὲ ἕτοιμα ἦν αὐτοῖς, ἐπέτρεχε τοὺς ἰδίους ἐπισπέρχων ἑκάτερος, ὁ μὲν Σκιπίων τοὺς θεοὺς κατακαλῶν ἐν ὄψει τῶν στρατευομένων, ἐς οὓς οἱ Καρχηδόνιοι παρεσπονδήκεσαν ὁσάκις ἔλυον τὰ συγκείμενα, καὶ τὴν στρατιὰν ἀξιῶν μὴ ἐς τὸ πλῆθος τῶν πολεμίων ἀφορᾶν, ἀλλ’ ἐς τὴν ἀρετὴν αὑτῶν, ᾗ καὶ πρότερον τῶνδε τῶν ἐχθρῶν πλειόνων ὄντων ἐπεκράτησαν ἐν τῇδε τῇ γῇ. εἰ δ’ ἔστι καὶ τοῖς νικήσασιν ἐπὶ τῷ μέλλοντι φόβος ἢ δέος ἢ ἀμφιβολία, πόσῳ ταῦτα τοῖς νενικημένοις πλεονάζειν ἀνάγκη. οὕτω μὲν ὁ Σκιπίων ἠρέθιζέ τε καὶ παρηγόρει τῆς ὀλιγότητος· ὁ δ’ Ἀννίβας τῶν τε ἐν Ἰταλίᾳ γεγονότων ἔργων ὑπεμίμνησκεν αὐτούς, ὡς λαμπρὰ καὶ μεγάλα πράξειαν, οὐκ ἐπὶ Νομάσιν ἀλλ’ ἐπὶ πᾶσιν Ἰταλοῖς κατὰ τὴν Ἰταλίαν, καὶ τὴν ὀλιγότητα τῶν ἐχθρῶν αὐτόθεν ἑστὼς ἐπεδείκνυε, καὶ παρεκάλει μὴ χείρους ὀλιγωτέρων ἐν οἰκείᾳ γῇ πλέονας ὄντας ὀφθῆναι. τὸν δὲ κίνδυνον τοῦ παρόντος ἀγῶνος καὶ τὸ μέγεθος ἑκάτερος τοῖς ἰδίοις ὑπερεπῆρεν, Ἀννίβας μὲν ὅτι Καρχηδόνα καὶ Λιβύην ἅπασαν ὁ ἀγὼν ὅδε κρινεῖ, ἢ δούλην εὐθὺς ἡσσωμένων εἶναι, ἢ ἐς τὸ ἔπειτα ἄρχειν ἁπάντων ὧν ἐπεκράτουν, Σκιπίων δ’ ὅτι νικωμένοις μὲν οὐδ’ ἀναχώρησις ἔστιν ἀσφαλής, ἐπικρατοῦσι δὲ ἀρχὴ μεγάλη προσγίγνεται καὶ ἀνάπαυλα πόνων τῶν παρόντων καὶ ἐς τὰ οἰκεῖα ἀπόπλους καὶ ἐς τὸ μέλλον εὔκλεια.", "st": "9.42"}, {"sp": "N", "t": "οὕτω παροξύνας τοὺς ἰδίους ἑκάτερος ἐς τὸν ἀγῶνα συνῄεσαν, Ἀννίβας μὲν σαλπίγγων κατάρξας, Σκιπίων δ’ ἀντηχεῖν κελεύσας. συνιόντων δ’ αὐτῶν οἱ μὲν ἐλέφαντες κατῆρχον τῆς μάχης, ἐς τὸ φοβερώτατον ἐσκευασμένοι καὶ τοῖς κέντροις ἐξοτρυνόμενοι πρὸς τῶν ἐπικαθημένων· περιθέοντες δ’ αὐτοὺς οἱ Νομάδες ἱππεῖς ἐσηκόντιζον ἀθρόως, μέχρι τρωθέντας τε καὶ φεύγοντας καὶ δυσπειθῶς ἤδη ἔχοντας ἀπήγαγον ἐκ τῆς μάχης οἱ ἐπιβάται. καὶ τάδε μὲν ἦν περὶ τοὺς ἀμφὶ τὰ κέρατα ἐλέφαντας· οἱ δ’ ἐν μέσῃ τῇ φάλαγγι τοὺς Ῥωμαίων πεζοὺς κατεπάτουν, ἀπείρους τε μάχης τοιᾶσδε ὄντας καὶ βαρεῖς ὑπὸ τῆς ὁπλίσεως, καὶ παρ’ αὐτὸ φεύγειν εὐκόλως ἢ διώκειν οὐ δυναμένους, ἕως ὁ Σκιπίων τοὺς ἱππέας τοὺς Ἰταλικούς, ὀπίσω τεταγμένους καὶ κουφότερον ἐσκευασμένους, ἐπαγαγὼν ἀποβῆναι τῶν ἵππων ταρασσομένων ἐκέλευσε, καὶ τοὺς ἐλέφαντας περιθέοντας ἐσακοντίζειν. πρῶτός τε αὐτὸς ἀποβὰς ἔτρωσε τὸν προπηδῶντα τῶν ἐλεφάντων. θαρρησάντων δὲ τῶν ἄλλων, καὶ τιτρωσκόντων ἤδη πανταχόθεν αὐτούς, καὶ οἵδε ὑπεχώρουν.", "st": "9.43"}, {"sp": "N", "t": "καὶ γενομένης τῆς μάχης καθαρᾶς θηριων, ὁ ἀγὼν ἐγίγνετο μόνων ἀνδρῶν τε καὶ ἵππων. τὸ μὲν οὖν δεξιὸν τὸ Ῥωμαίων, οὗ Λαίλιος ἐπεστάτει, τρέπεται τοὺς ἐναντίους Νομάδας, Μασσανάσσου βαλόντος αὐτῶν τὸν δυνάστην Μασσάθην· ὀξέως δ’ αὐτοὺς ὁ Ἀννίβας ἐπιδραμὼν συνέτασσε τὴν μάχην. τὸ δὲ λαιόν, ἔνθα Ῥωμαίων μὲν Ὀκτάουιος ἐπεστάτει, τῶν δὲ πολεμίων Κελτοὶ καὶ Λίγυες ἦσαν, ἐπόνει μάλα καρτερῶς ἑκατέροις. καὶ Σκιπίων μὲν ἔπεμπε Θέρμον τὸν χιλίαρχον ἐπικουρεῖν μετ’ ἐπιλέκτων· Ἀννίβας δ’ ἐπεὶ τὸ λαιὸν συνέστησεν, ἐς τοὺς Λίγυας καὶ Κελτοὺς μεθίππευεν, ἐπάγων ἅμα τὴν δευτέραν τάξιν Καρχηδονίων τε καὶ Λιβύων. κατιδὼν δ’ αὐτὸν ὁ Σκιπίων ἀντιπαρῆγε μεθ’ ἑτέρου στίφους. δύο δὲ στρατηγῶν ἀρίστων ἐς ἀγῶνα συνιόντων, ἔρις ἦν τῶν ὑφ’ ἑκατέρῳ λαμπρὰ καὶ δέος, καὶ προθυμίας οὐδετέροις τι ἐνέλιπε, σφοδροῦ καὶ ὀξέος ὄντος πόνου τε καὶ παρακελεύσεως.", "st": "9.44"}, {"sp": "N", "t": "μακρᾶς δὲ καὶ ἀκρίτου τῆς μάχης οὔσης, οἱ στρατηγοὶ τοὺς κάμνοντας ἐλεοῦντες ὥρμων ἐπ’ ἀλλήλους ὡς ἐν σφίσι τῆς κρίσεως ταχυτέρας ἐσομένης. καὶ ἠκόντισαν ὁμοῦ, Σκιπίων μὲν Ἀννίβου τὴν ἀσπίδα, ὁ δ’ Ἀννίβας ἔτυχε τοῦ ἵππου. καὶ ὁ ἵππος ὑπὸ τῆς πληγῆς ἐξέφερεν ὀπίσω τὸν Σκιπίωνα, μέχρι περιβὰς ἕτερον ἵππον αὖθις ἐς τὸν Ἀννίβαν ἠκόντισεν. ἀλλ’ ἀπέτυχεν αὐτοῦ καὶ τότε, τὸν δὲ ἱππέα τὸν ἐγγὺς ἔβαλεν. ἧκε δ’ ἐν τούτῳ καὶ Μασσανάσσης πυθόμενος. καὶ οἱ Ῥωμαῖοι τὸν στρατηγὸν ὁρῶντες στρατιωτικῶς σφῶν ὑπερμαχόμενον, καρτερώτερεν τοῖς πολεμίοις ἐνέπεσον καὶ ἐτρέψαντο καὶ φεύγοντας ἐδίωκον· οὐδὲ παριππεύοντος αὐτοῖς τοῦ Ἀννίβου καὶ δεομένου στῆναι καὶ τῆς μάχης αὖθις ἐς πεῖραν ἐλθεῖν ἔτι ἐπείθοντο. ἀπογνοὺς οὖν αὐτῶν ὁ Ἀννίβας τοὺς ἐξ Ἰταλιας οἱ συνελθόντας, ἐφεδρεύοντας ἔτι καὶ ἀτρεμοῦντας, ἦγεν ἐπὶ τὴν μάχην, ἐλπίσας Ῥωμαίοις ἅτε διώκουσιν ἀσυντακτοτέροις ἐπιπεσεῖσθαι. οἱ δὲ τὸ ἐνθύμημα αὐτοῦ θεασάμενοι, μετὰ σπουδῆς ἀλλήλους ἐκ τῆς διώξεως ἀνεκάλουν, καὶ συνετάσσοντο αὖθις ἐς μάχην. οὔτε δὲ ἵππων σφίσι παρόντων οὔτε ἀκοντίων ἔτι ὄντων, ξίφεσιν ἐς ἀλλήλους ἐχρῶντο καὶ συνεπλέκοντο. φόνος τε ἦν πολὺς ἐνθάδε μάλιστα καὶ τραύματα μέγιστα, καὶ πιπτόντων στόνος καὶ ἀναιρούντων μεγαλαυχία, μέχρι ποτὲ καὶ τούσδε ἐτρέψαντο οἱ Ἰταλοὶ καὶ φεύγουσιν εἵποντο, κρίσις τε ἦν λαμπρὰ τοῦ πολέμου.", "st": "9.45"}, {"sp": "N", "t": "καὶ ὁ Ἀννίβας ἐν τῇ φυγῇ θεασάμενος ἱππέων Νομάδων πλῆθος συνεστώς, προσδραμὼν ἠξίου μὴ προλιπεῖν αὐτόν, καὶ πείσας ἐπῆγε τοῖς διώκουσιν, ἐλπίσας ἐργάσεσθαί τινα παλινδίωξιν. πρώτοις δὲ Μασσυλίοις ἐντυχὼν ἐμάχετο, καὶ μόνος ἦν ἔτι οὗτος ὁ ἀγὼν Μασσανάσσου καὶ Ἀννίβου συνεστώτων. φερομένων δὲ καὶ τῶνδε ἐπ’ ἀλλήλους ὑπὸ προθυμίας, ἐς μὲν τὴν ἀσπίδα ὁ Μασσανάσσης ἠκόντισε βαλών, ὁ δὲ Ἀννίβας καὶ τότε ἔτυχε τοῦ ἵππου. καὶ ὁ Μασσανάσσης ἐκπεσὼν πεζὸς ἐπὶ τὸν Ἀννίβαν ὥρμα, τόν τε ἐπελαύνοντά οἱ πρὸ τῶν ἄλλων ἱππέα βαλὼν ἀπέκτεινεν. καὶ τῶν λοιπῶν τὰ ἀκόντια ἐς τὸν ἐλεφαντιστὴν ἐκδεχόμενος, ἓν τῶν ἐμπεπηγότων ἐξεῖλε, καὶ ἀκοντίσας ἐς τὸν Ἀννίβαν αὖθις οὐδ’ ὣς ἐπετύγχανεν, ἀλλὰ τὸν ἐγγὺς ἱππέα καὶ ὅδε ἀπέκτεινεν. ἕτερον δ’ ἐξέλκων ἐς τὸν βραχίονα ἐτρώθη, καὶ ὑπεχώρησεν ἐκ τῆς μάχης ἐπ’ ὀλίγον. Σκιπίων δὲ πυθόμενος ἔδεισε περὶ τῷ Μασσανάσσῃ, καὶ ἐς τὸ ἔργον ἠπείγετο· καὶ ηὗρε τὸν Μασσανάσσην ἐς τὴν μάχην αὖθις ἐπὶ ἵππου φερόμενον ἑτέρου, τὸ τραῦμα ἐπιδήσαντα. ὅ τε ἀγὼν ἦν ἴσος αὖθις αὐτοῖς καὶ πάνυ καρτερός, αἰδουμένων τοὺς στρατηγοὺς ἑκατέρων, ἕως ὁ Ἀννίβας ἐπί τινος λόφου θεασάμενος Ἴβηρας καὶ Κελτοὺς συνεστῶτας ἐξίππευσεν ὡς κἀκείνους ἐπάξων. τότε γὰρ οἱ μαχόμενοι, τῆς μὲν αἰτίας οὐ συνιέντες, τὴν δ’ ἀποχώρησιν αὐτοῦ φυγὴν ὑπολαβόντες εἶναι, τὸν ἀγῶνα μεθῆκαν ἑκόντες καὶ ἔφυγον ἀκόσμως, οὐχ ᾗπερ ἑώρων Ἀννίβαν, ἀλλ’ ὅπῃ τύχοιεν ἕκαστοι. καὶ οἱ μὲν οὕτω διελύθησαν, Ῥωμαῖοι δ’ αὐτούς, ὡς τετελεσμένης τῆς μάχης, ἐδίωκον ἀτάκτως, οὐδ’ αὐτοὶ τῆς Ἀννίβου προαιρέσεως συνιέντες.", "st": "9.46"}, {"sp": "N", "t": "ὁ δ’ ἐπανῄει πεφραγμένος Ἴβηρσι καὶ Κελτοῖς ἀπὸ του λόφου. καὶ ὁ Σκιπίων αὖθις ἐκ τῆς διώξεως τοὺς Ῥωμαίους ἀνεκάλει μετὰ σπουδῆς, καὶ παρέτασσε πολὺ πλείονας τῶν ἀπὸ τοῦ λόφου καταβεβηκότων· ὅθεν αὐτῶν οὐ δυσχερῶς περιεγίγνετο. Ἀννίβας δὲ καὶ τῆσδε τῆς πείρας τελευταίας γενομένης ἀποτυχών, ἔφευγεν ἤδη σαφῶς ἀπογνοὺς ἅπαντα. καὶ αὐτὸν ἐδίωκον ἱππεῖς ἄλλοι τε πολλοὶ καὶ Μασσανάσσης, περιώδυνος ὢν ἐκ τοῦ τραύματος, ἀεί τε πλησιάζων, καὶ μέγα ποιούμενος αἰχμάλωτον Ἀννίβαν ἀγαγεῖν Σκιπίωνι. τὸν δὲ νὺξ ἐρρύσατο, καὶ σκότιος μετ’ εἴκοσιν ἱππέων, τῶν δυνηθέντων σὺν αὐτῷ συνανύσαι τὸν δρόμον, ἐς πόλιν κατέφυγεν ᾗ ὄνομα Θῶν, ἔνθα Βρεττίων ἔγνω καὶ Ἰβήρων ἱππέας πολλοὺς ἀπὸ τῆς ἥττης συμπεφευγότας. δείσας οὖν περὶ μὲν τῶν Ἰβήρων ὡς βαρβάρων ταχυέργων, περὶ δὲ Βρεττίων ὡς Ἰταλῶν ὁμοεθνῶν Σκιπίωνι, μὴ ἐς συγγνώμην ὧν ἐξήμαρτον ἐς τὴν Ἰταλίαν, προσαγάγωσιν αὐτὸν τῷ Σκιπίωνι, λαθὼν ἐξέφυγε μεθ’ ἑνὸς ἱππέως, ᾧ μάλιστ’ ἐπίστευεν. σταδίους δ’ ἀνύσας ἐς τρισχιλίους δύο νυξί τε καὶ ἡμέραις, ἧκεν ἐς πόλιν ἐπὶ θαλάσσης Ἀδρυμητόν, ἔνθα τι μέρος ἦν αὐτῷ στρατιᾶς σιτοφυλακοῦν. περιπέμπων δ’ ἐς τὰ πλησίον, καὶ τοὺς ἐκ τῆς μάχης διαφυγόντας ἀναλαμβάνων, ὅπλα καὶ μηχανήματα εἰργάζετο.", "st": "9.47"}, {"sp": "N", "t": "Σκιπιων δε νίκην ἀριστην νενικηκως, τὰ μὲν ἄχρηστα τῆς λείας ἐνεπιμπρη διαζωσάμενος αὐτός, ὥσπερ εἰώθασι Ῥωμαίων οἱ στρατηγοι, χρυσίου δ’ ἐς Ῥώμην τάλαντα δέκα καὶ ἀργυριου δισχίλια καὶ πεντακόσια καὶ ἐλέφαντα εἰργασμένον καὶ τοὺς ἐπιφανεῖς τῶν αἰχμαλώτων ἔπεμπε, καὶ Λαίλιον ἐξαγγελοῦντα περὶ τῆς νίκης, ἐπὶ νεῶν . ., τὰ δὲ λοιπὰ ἀποδόμενος τὴν τιμὴν ἐπιδιεῖλε τῷ στρατῷ, καὶ δῶρα τοῖς ἀριστεύσασιν ἐδίδου, καὶ Μασσανάσσην ἐστεφάνου καὶ τότε. καὶ τὰς πόλεις ἐπιὼν ἐχειροῦτο. τὸ μὲν δὴ τέλος τῆς Ἀννίβου τε καὶ Σκιπίωνος ἐν Λιβύῃ μάχης, τότε πρῶτον ἀλλήλοις ἐς χεῖρας ἐλθόντων, τοῦτ’ ἦν, ἀπέθανον δὲ Ῥωμαίων μὲν δισχίλιοι καὶ πεντακόσιοι, Μασσανάσσου δ’ ἔτι πλείονες, καὶ τῶν πολεμίων δισμύριοι καὶ πεντακισχίλιοι. αἰχμάλωτοι δ’ ἐλήφθησαν ὀκτακισχίλιοι καὶ πεντακόσιοι. καὶ Ἴβηρες ηὐτομόλησαν πρὸς Σκιπίωνα τριακόσιοι, καὶ Νομάδες πρὸς Μασσανάσσην ὀκτακόσιοι.", "st": "9.48"}, {"sp": "N", "t": "οὔπω δὲ οὔτε Καρχηδόνιοι τῶνδε οὔτε Ῥωμαῖοι πυθόμενοι, οἱ μὲν ἐπέστελλον Μάγωνι, ξενολογοῦντι ἔτι Κελτούς, ἐσβαλεῖν ἐς τὴν Ἰταλίαν, εἰ δύναιτο, ἢ ἐς Λιβύην μετὰ τῶν μισθοφόρων καταπλεῦσαι, οἱ δέ, τῶνδε τῶν γραμμάτων ἁλόντων καὶ ἐς Ῥώμην κομισθέντων, στρατιὰν ἄλλην καὶ ἵππους καὶ ναῦς καὶ χρήματα ἔπεμπον τῷ Σκιπίωνι. ὁ δὲ ἤδη τῇ Καρχηδόνι κατὰ μὲν τὴν γῆν ἐπέπεμπεν Ὀκτάουιον, ταῖς δὲ ναυσὶν αὐτὸς ἐπέπλει. καὶ οἱ Καρχηδόνιοι τὴν ἧσσαν Ἀννίβου πυθόμενοι, πρέσβεις ἐπὶ κελητίου προσέπεμπον τῷ Σκιπίωνι, ὧν ἡγοῦντο Ἄννων τε ὁ μέγας λεγόμενος καὶ Ἀσδρούβας ὁ ἔριφος· οἳ τὸ κηρύκειον ὑψηλὸν ἔστησαν ἐπὶ τῆς πρᾴρας, καὶ τὰς χεῖρας ὤρεγον ἐς τὸν Σκιπίωνα ἱκετῶν τρόπον. ὁ δὲ αὐτοὺς ἐκέλευσεν ἥκειν ἐς τὸ στρατόπεδον καὶ ἐλθοῦσιν ἐφ’ ὑψηλοῦ προκαθήμενος ἐχρημάτιζεν. οἱ δὲ μετ’ οἰμωγῆς ἑαυτοὺς ἐρρίπτουν ἐς τὸ ἔδαφος, καὶ τῶν ὑπηρετῶν ἀνιστάντων καὶ λέγειν κελευόντων ὅ τι θέλοιεν, Ἀσδρούβας ὁ ἔριφος εἶπεν·", "st": "9.49"}, {"sp": "N", "t": "“ἐμοὶ μὲν ἔστιν, ὦ Ῥωμαῖοι, καὶ Ἄννωνι τῷδε, καὶ ὅσοι Καρχηδονίων ἔμφρονες, καθαρεύειν ἁμαρτημάτων ὧν ἡμῖν ἐπικαλεῖτε· τοὺς γὰρ πρέσβεις ὑμῶν, ἐς οὓς ἐξήμαρτεν ἡ πατρὶς ἄκουσα ὑπὸ λιμοῦ, περιεσώζομεν καὶ πρὸς ὑμᾶς ἐπέμπομεν. χρὴ δ’ ὑμᾶς μηδὲ Καρχηδονίων καταγιγνώσκειν ἁπάντων, οἵ γε τὴν εἰρήνην καὶ πρότερον ᾔτησαν καὶ λαβόντες προθύμως ὤμνυον. εἰσὶ δ’ αἱ πόλεις ἐπὶ τὸ χεῖρον εὐεπίστρεπτοι, καὶ τὸ πρὸς χάριν ἀεὶ παρὰ τοῖς πλήθεσιν ἐπικρατεῖ. ἃ καὶ ἡμεῖς ἐπάθομεν, οὔτε πεῖσαι δυνηθέντες τὸ πλῆθος οὔτ’ ἐπισχεῖν διὰ τοὺς ἐκεῖ μὲν διαβάλλοντας ἡμᾶς, παρὰ δὲ ὑμῖν τὴν παρρησίαν ἀφῃρημένους. μὴ δὴ ἀπὸ τῆς ὑμετέρας εὐπειθείας ἢ εὐβουλίας, ὦ Ῥωμαῖοι, τὰ παρ’ ἡμῖν κρίνετε, ἀλλ’ εἴ τῳ καὶ τὸ πεισθῆναι τοι?͂ς ἐπιτρίβουσιν ἀδίκημα εἶναι δοκεῖ, τὸν λιμὸν ἐπίδεσθε, καὶ τὴν ἀνάγκην ἣ γέγονεν ἡμῖν ὑπὸ τοῦ πάθους. οὐ γὰρ δὴ τῶν αὐτῶν ἔργον ἑκούσιον ἦν ἄρτι μὲν περὶ εἰρήνης παρακαλεῖν, καὶ χρήματα τοσαῦτα διδόναι, καὶ τῶν νεῶν τῶν μακρῶν πλὴν ὀλίγων ἀφίστασθαι, καὶ τὸ πολὺ τῆς ἀρχῆς ὑμῖν παριέναι, καὶ περὶ τῶνδε ὀμνύναι τε καὶ ὁρκοῦν πέμψαντας ἐς Ῥωμην, ἔτι δ’ ὄντων τῶν ἡμετέρων πρέσβεων παρ’ ὑμῖν ἑκόντας ἁμαρτεῖν. ἀλλὰ μάλιστα μὲν θεῶν τις ἔβλαψε, καὶ ὁ χειμὼν ὁ τὴν ἀγορὰν ὑμῶν ἐς Καρχηδόνα καταγαγών· ἐπὶ δὲ τῷ χειμῶνι ὁ λιμὸς ἡμᾶς ἀφείλετο μὴ καλῶς ὑπὲρ τῶν ἀλλοτρίων φρονῆσαι, πάντων ἐνδεεῖς ὄντας. οὐδὲ λογισμὸν αἰτεῖν ἄξιον παρὰ πλήθους ἀσυντάκτου καὶ ἀτυχοῦντος.", "st": "9.50"}, {"sp": "N", "t": "“εἰ δὲ καὶ ὣς ἀδικεῖν ὑμῖν δοκοῦμεν, οὐκ ἀτυχεῖν, ὁμολογοῦμεν, καὶ δι’ αὐτὸ καὶ παρακαλοῦμεν. ἔστι δὲ τῶν μὲν οὐδὲν ἁμαρτόντων δικαιολογία, τῶν δ’ ἁμαρτόντων παράκλησις. ἐφ’ ᾗ ταχύτερός ἐστιν ὁ τῶν εὐτυχούντων ἔλεος, τὰ ἀνθρώπεια ὑφορωμένων, ὅταν αἴσθωνται διὰ τὰς αἰφνιδίους μεταβολὰς παρακαλοῦντας τοὺς ἐχθὲς ἀδικεῖν δυναμένους. οἷα καὶ ἡ Καρχηδονίων πόλις, ἡ τῆς Λιβύης μεγίστη καὶ δυνατωτάτη ναυσὶ καὶ χρήμασιν ὁμοῦ καὶ ἐλέφασι καὶ στρατῷ πεζῷ τε καὶ ἱππικῷ, καὶ ὑπηκόοις πολλοῖς, ἑπτακοσίοις ἔτεσιν ἀνθήσασα, καὶ Λιβύης πάσης καὶ ἄλλων ἐθνῶν καὶ νήσων καὶ θαλάσσης τοσῆσδε ἄρξασα, καὶ ὑμῖν αὐτοῖς ἐς ἀμφήριστον ἐπὶ πλεῖστον ἐλθοῦσα, νῦν οὐκ ἐν τῇ θαλάσσῃ καὶ ταῖς ναυσίν, οὐδ’ ἐν τοῖς ἐλέφασι καὶ ἵπποις, οὐδ’ ἐν τοῖς ὑπηκόοις, ὧν πάντων ὑμῖν ἀφίσταται, τὴν ἐλπίδα τῆς σωτηρίας, ἀλλ’ ἐν αὐτοῖς ὑμῖν ἔχει τοῖς προπεπονθόσι κακῶς. ἃ χρὴ θεωροῦντας ὑμᾶς, καὶ τὴν ἐπ’ αὐτοῖς νέμεσιν φυλασσομένους, μετριοπαθῶς χρῆσθαι ταῖς εὐπραξίαις, καὶ τῆς σφετέρας αὐτῶν, ὦ Ῥωμαῖοι, μεγαλοφροσύνης καὶ τῆς Καρχηδονίων ποτὲ τύχης ἄξια πράσσειν, τάς τε τοῦ δαιμονίου μεταβολὰς ἀνεπιφθόνως ἐν ταῖς ἡμετέραις συμφοραῖς διατίθεσθαι, ἵνα καὶ πρὸς τοὺς θεοὺς ἀναμάρτητα ᾖ τὰ ὑμέτερα ὑμῖν, καὶ πρὸς ἀνθρώπους ἀξιέπαινα πάντας.", "st": "9.51"}, {"sp": "N", "t": "“οὐ γὰρ δὴ μὴ μετάθωνται γε καὶ νῦν οἱ Καρχηδόνιοι δέος ἔστιν, οἳ τοσήνδε μετάνοιαν καὶ δίκην τῆς πρὶν ἀγνωμοσύνης ὑφίστανται. ἔστι δ’ ἀναμαρτησίας τοῖς μὲν σώφροσιν ἡ εὐβουλία φυλακή, τοῖς δ’ ἁμαρτοῦσι τὸ προπαθεῖν καὶ μεταγνῶναι. βεβαιοτέρους τε εἰκός ἐστι τοὺς νενουθετημένους εἶναι τῶν ἀπειράτων. οὐδ’ ἄξιον Καρχηδονίοις ὑμᾶς ὠμότητα καὶ ἁμαρτίαν ἐπικαλοῦντας ταῦτα μιμεῖσθαι· τοῖς μὲν γὰρ ἀτυχοῦσιν ἑτέρων ἁμαρτημάτων ἄρχουσιν ὑπὸ τῆς ἀπορίας αἱ συμφοραί, τοῖς δ’ εὖ πράσσουσιν ἐν ἐξουσίᾳ τὸ φιλάνθρωπόν ἐστιν. οὐδ’ εὐκλεές, οὐδὲ συμφέρον ἐς τὴν ἀρχὴν ὑμῖν ἐστὶ πόλιν τοσήνδε καθαιρεῖν μᾶλλον ἢ περισώζειν. ἐστὲ δὲ ἀμείνονες μὲν ὑμεῖς τῶν ὑμετέρων συμφερόντων κριταί, ἡμεῖς δ’ ὑμῖν ἐς τὴν ἑαυτῶν σωτηρίαν δύο ταῦτα μάλιστα φέρομεν ἐκ πάντων, τὸ τῆς Καρχηδονίων ποτὲ ἀξίωμα ἀρχῆς, καὶ τὴν ὑμετέραν αὐτῶν ἐς πάντα μετριοπάθειαν, ἣ μετὰ τῶν ὅπλων ἐς τοσοῦτον ὑμᾶς ἐπῇρεν ἀρχῆς καὶ δυνάμεως. τίσι δὲ συνθήκαις, ἂν ἄρα διδῶτε τὴν εἰρήνην, χρησόμεθα περὶ αὐτῆς, περισσὸν λέγειν τοὺς ἐφ’ ὑμῖν τὰ ἑαυτῶν τιθεμένους.”", "st": "9.52"}, {"sp": "N", "t": "τοσαῦτ’ εἰπὼν ὁ ἔριφος ἐπέκλαυσεν. ὁ δὲ Σκιπίων μεταστησάμενος αὐτοὺς ἐβουλεύετο μετὰ τῶν ἀρίστων ἐπὶ πολύ. ὡς δ’ ἔκρινεν, ἐσκαλέσας αὐτοὺς ἔλεγεν ὧδε· “ἐστὲ μὲν οὐδεμιᾶς συγγνώμης ἄξιοι, πολλάκις ἐς σπονδὰς ἡμῶν ὑβρίσαντες, καὶ τὰ τελευταῖα νῦν καὶ ἐς πρεσβείας ἁμαρτόντες οὕτω φανερῶς καὶ ἀθεμίτως ὡς μήτε ἐξαρνεῖσθαι μήτε ἀντιλέγειν ὅτι μὴ τῆς ἐσχάτης ἐστὲ τιμωρίας ἄξιοι. τί δὲ δεῖ κατηγορεῖν τῶν ὁμολογούντων; ἐς ἱκεσίας καταφεύγετε οἱ μηδ’ ὄνομα Ῥωμαίων ὑπολιπόντες ἄν, εἰ ὑμεῖς ἐκρατήσατε. ἀλλ’ ἡμεῖς μὲν οὐδέ ποθ’ ὑμῖν ὅμοια ποιήσομεν, ἐπεὶ καὶ τοὺς πρέσβεις ὑμῶν, ἔτι ὄντας ἐν Ῥώμῃ, παρεσπονδηκότων ὑμῶν καὶ ἐς πρέσβεις ἁμαρτόντων, ἥ τε πόλις ἀπέλυσε, κἀγὼ καταχθέντας ἐς τὸ στρατόπεδον πρὸς ὑμᾶς ἤδη πολεμοῦντας ἀπέπεμψα ἀπαθεῖς. χρὴ δ’ ὑμᾶς καταγιγνώσκοντας αὑτῶν, ὅ τι ἂν λάβητε, κέρδος ἡγεῖσθαι. λέξω δ’ ἅ μοι δοκεῖ, καὶ ἡ σύγκλητος ἐπιψηφιεῖ ἃ ἂν δοκιμάσῃ.", "st": "9.53"}, {"sp": "N", "t": "“δίδομεν ὑμῖν καὶ ἔτι τὴν εἰρήνην, ὦ Καρχηδόνιοι, ἢν τάς τε ναῦς τὰς μακρὰς παραδιδῶτε Ῥωμαίοις χωρὶς δέκα μόνων, καὶ τοὺς ἐλέφαντας ὅσους ἔχετε, καὶ ὅσα ἡρπάσατε πρῴην, ἢ τῶν ἀπολωλότων τιμήν, ἐμοῦ τὰ ἀμφίβολα κρίνοντος, καὶ αἰχμάλωτα πάντα καὶ αὐτομόλους, καὶ ὅσους Ἀννίβας ἐξ Ἰταλίας ἤγαγεν. ταῦτα μὲν ἐν τριάκοντα ἡμέραις ἀφ’ οὗ ἂν ἡ εἰρήνη κριθῇ· ἐν δ’ ἑξήκοντα ἡμέραις Μάγωνα χρὴ Λιγύων ἀποστῆναι, καὶ τὰς φρουρὰς ὑμᾶς ἐξαγαγεῖν ἐκ τῶν πόλεων ὅσαι τῶν Φοινικίδων τάφρων ἐκτός εἰσι, καὶ ὅσα αὐτῶν ἔχετε ὅμηρα, ἀποδοῦναι, καὶ ἐς Ῥώμην ἑκάστου ἔτους ἀναφέρειν Εὐβοϊκὰ τάλαντα διακόσια ἐπὶ πεντήκοντα ἐνιαυτούς. καὶ μήτε ξενολογεῖν ἀπὸ Κελτῶν ἢ Λιγύων ἔτι, μήτε Μασσανάσσῃ μηδὲ ἄλλῳ Ῥωμαίων φίλῳ πολεμεῖν, μηδὲ στρατεύειν τινὰ Καρχηδονίων ἐπ’ ἐκείνους ἀπό γε τοῦ κοινοῦ. τὴν δὲ πόλιν ὑμᾶς ἔχειν, καὶ τὴν χώραν ὅσην ἐντὸς τῶν Φοινικίδων τάφρων εἴχετε ἐμοῦ διαπλέοντος ἐς Λιβύην. Ῥωμαίων τε εἶναι φίλους καὶ συμμάχους κατὰ γῆν καὶ κατὰ θάλασσαν, ἢν ἀρέσκῃ ταῦτα τῇ βουλῇ. ἀρεσάντων δέ, Ῥωμαίους ἀναχωρεῖν ἐκ Λιβύης πεντήκοντα καὶ ἑκατὸν ἡμέραις. ἀνοχὰς δὲ ἢν ἐθέλητε λαβεῖν ἔστε πρεσβεύσητε ἐς Ῥώμην, δώσετε μὲν ἡμῖν αὐτίκα ὅμηρα πεντήκοντα καὶ ἑκατὸν παῖδας, οὓς ἂν αὐτὸς ἐπιλέξωμαι, δώσετε δὲ ἐς δαπάνην τῇ στρατιᾷ ἄλλα τάλαντα χίλια καὶ ἀγοράν. καὶ γενομένων τῶν σπονδῶν ἀπολήψεσθε τὰ ὅμηρα.”", "st": "9.54"}, {"sp": "N", "t": "ταῦτα τοῦ Σκιπίωνος εἰπόντος οἱ μὲν πρέσβεις ἔφερον ἐς Καρχηδόνα τοὺς λόγους, συνιόντος δὲ τοῦ πλήθους ἐς ἐκκλησίαν ἐπὶ πολλὰς ἡμέρας, τοῖς μὲν ἀρίστοις ἐδόκει τὰ προτεινόμενα δέξασθαι καὶ μὴ περὶ τινῶν ἀπειθοῦντας κινδυνεύειν περὶ ἁπάντων, τὸ δ’ ἀγοραῖον πλῆθος οὐ τὸ παρὸν δεινὸν ἐκλογιζόμενοι μᾶλλον ἢ τὴν ἀφαίρεσιν ὧν ἔχουσι, τοσήνδε οὖσαν, ἠπείθουν, καὶ ἠγανάκτουν εἰ ἐν λιμῷ τὸν σῖτον οἱ ἄρχοντες αἱροῦνται Ῥωμαίοις ἀντὶ τῶν πολιτῶν ἐς τὰς ἀνοχὰς παρασχεῖν, ἐφ’ ἕκαστόν τε αὐτῶν συνιστάμενοι πᾶσιν ἠπείλουν τὰς οἰκίας αὐτῶν διαρπάσειν καὶ καταπρήσειν. τέλος δ’ ἔγνωσαν Ἀννίβαν, ἔχοντα μὲν ἤδη πεζοὺς ἑξακισχιλίους ἱππέας δὲ πεντακοσίους, σταθμεύοντα δ’ ἐν πόλει Μαρθαμά, σύμβουλον ἐπὶ τοῖς παροῦσι καλεῖν. ὁ δ’ ἧκε, καὶ τῶν μετρίων δεδιότων μὴ φιλοπόλεμος ἀνὴρ ἐπιτρίψῃ τὸ πλῆθος, πάνυ σεμνῶς ἐκέλευε τὴν εἰρήνην δέχεσθαι. ὁ δὲ δῆμος καὶ τόνδε ὑπ’ ὀργῆς μανιώδους ἐβλασφήμει καὶ πᾶσιν ἠπείλει, μέχρι τῶν γνωρίμων τοὺς μὲν ἐς Μασσανάσσην καταφυγεῖν, τοὺς δὲ ἐς αὐτοὺς Ῥωμαίους αὐτομολῆσαι, τῆς πόλεως ἀπογνόντας.", "st": "9.55"}, {"sp": "N", "t": "οἱ δὲ Καρχηδόνιοι πυθόμενοι σῖτον πολὺν ἐς ἐμπόριόν τι ὑπὸ Ἀννίβου σεσωρεῦσθαι, ὁλκάδας ἐπ’ αὐτὸν ἐξέπεμπον καὶ ναῦς μακράς, ἐγνωκότες, εἰ τὸν σῖτον λάβοιεν, ἐκστρατεῦσαι καὶ ὑπομεῖναι πᾶν ὅ τι ἂν ἡ τύχη κρίνῃ, μᾶλλον ἢ Ῥωμαίοις δουλεύειν ἑκόντες. ἐπεὶ δὲ ἄνεμός τε καὶ χειμὼν τὰς ναῦς συνέτριψαν, ἀπογνόντες ἁπάντων ἐμέμφοντο τοῖς θεοῖς ὡς ἐπιβουλεύουσι, καὶ συνετίθεντο τῷ Σκιπίωνι, καὶ ἐπρεσβεύοντο ἐς Ῥώμην. καὶ ὁ Σκιπίων ἔπεμπε τοὺς συμβουλεύσοντας κυροῦν τὰ συγκείμενα. λέγεται δὲ τοῦτο ἐσηγήσασθαι τῇ τε πόλει συμφέρειν ὑπολαβών, καὶ πυθόμενος Γναῖον Κορνήλιον Λέντλον τὸν ὕπατον ἐφεδρεύειν αὑτοῦ τῇ στρατηγίᾳ, τὴν δόξαν οὐκ ἐθέλων ἑτέρου γενέσθαι. προσέταξε γοῦν λέγειν ἀπιοῦσιν ὅτι βραδυνόντων Ῥωμαίων αὐτὸς ἐφ’ ἑαυτοῦ συνθήσεται.", "st": "9.56"}, {"sp": "N", "t": "οἱ δὲ πάνυ μὲν ἥδοντο κεκρατηκότες πόλεως τοσαύτης, ἣ πολλὰ καὶ δεινὰ πρότερον αὐτοὺς ἐδεδράκει, καὶ τῶν ἐπὶ τῆς γῆς δευτέραν ἢ τρίτην εἶχεν ἡγεμονίαν· οἱ σύμβουλοι δ’ ἐστασίαζον, οἱ μὲν ἔτι σὺν ὀργῇ χαλεπαίνοντες τοῖς Καρχηδονίοις, οἱ δὲ ἐλεοῦντες αὐτοὺς ἤδη, καὶ ἀξιοῦντες ἐν ταῖς ἀλλοτρίαις συμφοραῖς τὸ σφέτερον εὐπρεπῶς διατίθεσθαι. ὑπαναστὰς δέ τις τῶν Σκιπίωνος φίλων εἶπεν· “οὐ περὶ τῆς Καρχηδονίων σωτηρίας ἐστὶν ἡμῖν ἡ φροντίς, ὦ ἄνδρες, ἀλλὰ περὶ τῆς Ῥωμαίων ἔς τε θεοὺς πίστεως καὶ πρὸς ἀνδρῶν εὐφημίας, μὴ Καρχηδονίων αὐτῶν ὠμότερα πράξωμεν, οἳ Καρχηδονίοις ὠμότητα ἐπικαλοῦμεν, καὶ μετριοπαθείας ἀεὶ φροντίσαντες ἐπὶ τῶν βραχυτέρων, ἀμελήσωμεν ἐν τοῖς μείζοσιν· ἃ μηδὲ λαθεῖν ἔνεστι διὰ τὸ μέγεθος, ἀλλ’ ἐς ἅπασαν γῆν περιελεύσεται καὶ νῦν καὶ ὕστερον, ἢν πόλιν περιώνυμον καὶ θαλασσοκράτορα ἀνέλωμεν, ἣ καὶ νήσων ἦρξε πολλῶν καὶ θαλάσσης ὅλης καὶ Λιβύης ὑπὲρ ἥμισυ, ἔν τε τοῖς πρὸς ἡμᾶς αὐτοὺς ἀγῶσι πολλὰ καὶ τύχης καὶ δυνάμεως ἔργα ἐπεδείξατο, οἷς ἔτι μὲν φιλονεικοῦσιν ἐρίζειν ἔδει, πεσόντων δὲ φείδεσθαι, καθὰ καὶ τῶν ἀθλητῶν οὐδεὶς τὸν πεσόντα ἔτι τύπτει, καὶ τῶν θηρίων τὰ πολλὰ φείδεται τῶν καταπεσόντων. καλὸν δ’ ἐν τοῖς εὐτυχήμασι νέμεσιν θεῶν φυλάσσεσθαι καὶ ἀνθρώπων φθόνον. εἰ δέ τις, ὅσα ἔδρασαν ἡμᾶς, ἀκριβῶς ἐκλογίζεται, αὐτὸ μάλιστά ἐστι τοῦτο τῆς τύχης τὸ φοβερώτατον, εἰ περὶ μόνης ἄρτι σωτηρίας παρακαλοῦσιν οἱ πόσα καὶ πηλίκα δεδυνημένοι δρᾶσαι καὶ οὐ πρὸ πολλοῦ περί τε Σικελίας καὶ Ἰβηρίας καλῶς ἀγωνισάμενοι. ἀλλ’ ἐκείνων μὲν δίκας ἔδοσαν, τῶν δὲ τελευταίων παραβάσεων λιμὸν αἰτιῶνται, κακὸν ἀνθρώποις ἐπιπονώτατον, ὃ πάντας ἐξαιρεῖν δύναται λογισμούς.", "st": "9.57"}, {"sp": "N", "t": "“ἐγὼ δ’ οὐκ ἐρῶ μὲν οὐδὲν ὑπὲρ Καρχηδονίων (οὐ γὰρ ἄξιον), οὐδ’ ἀγνοῶ καὶ πρότερον αὐτοὺς ἄλλας συνθήκας πρὸ τῶνδε παραβῆναι· ἃ δ’ ἐπὶ τοῖς τοιούτοις ποιοῦντες οἱ πατέρες ἡμῶν ἐς τόδε τύχης προῆλθον, εἰδότας ὑμᾶς ἀναμνήσω. τῶν γὰρ γειτόνων ἡμῖν τωνδε πάντων ἐν κύκλῳ πολλάκις ἀποστάντων καὶ σπονδὰς συνεχῶς λυσάντων οὐ κατεφρόνησαν, οὐ Λατίνων, οὐ Τυρρηνῶν, οὐ Σαβίνων. τούς τε αὖ μετ’ ἐκείνους περιοικοῦντας ἡμῖν Αἰκανοὺς καὶ Οὐολούσκους καὶ Καμπανούς, καὶ ὅσα ἄλλα τῆς Ἰταλίας ἐς σπονδὰς ὕβρισεν, εὐσταθῶς ἔφερον. καὶ τὸ Σαυνιτῶν γένος τρὶς μὲν φιλίας καὶ συνθηκῶν καταφρονῆσαν, ἔτεσι δ’ ὀγδοήκοντα μεγίστους ἡμῖν πολέμους πεπολεμηκὸς οὐκ ἀνέστησαν, οὐδὲ τοὺς ἄλλους ὅσοι Πύρρον προσηγάγοντο κατὰ τῆς Ἰταλίας. οὐδ’ ἡμεῖς, τὰ ἔναγχος ταῦτα, τοὺς Ἰταλῶν Ἀννίβᾳ προσθεμένους διεφθείραμεν, οὐδὲ Βρεττίους, οἳ μέχρι τέλους αὐτῷ συνηγωνίσαντο, ἀλλὰ γῇ μόνῃ ζημιώσαντες εἰάσαμεν ἔχειν τὰ ὑπόλοιπα, ὡς εὐσεβὲς ὁμοῦ καὶ ἐς εὐτυχίαν ἡμῖν χρήσιμον, μὴ ἀφανίζειν ἀνθρώπων γένη μᾶλλον ἢ νουθετεῖν.", "st": "9.58"}, {"sp": "N", "t": "“τί οὖν παθόντες ἐπὶ Καρχηδονίων ἀλλάξωμεν τὴν φύσιν, ᾗ χρώμενοι μέχρι νῦν εὐτυχοῦμεν; ὅτι μείζων ἐστὶν ἡ πόλις αὕτη; δι’ αὐτὸ μέντοι καὶ τοῦτο μᾶλλον ἔτι φειδοῦς ἀξία. ἀλλ’ ὅτι πολλάκις παρεσπόνδησεν ἐς ἡμᾶς; καὶ γὰρ ἕτεροι, καὶ σχεδὸν ἅπαντες. ἀλλ’ ὅτι μικρὰν νῦν ὑφίστανται τιμωρίαν; ὧν νῆές τε πᾶσαι χωρὶς δέκα παραιροῦνται, καὶ τοὺς ἐλέφαντας, οἷς ἰσχύουσι, παραδιδόασι, καὶ τάλαντα Εὐβοϊκὰ μύρια τελοῦσι, καὶ πόλεων ἁπασῶν ἀφίστανται καὶ χώρας ὅσης ἄρχουσιν ἐκτὸς τῶν Φοινικίδων τάφρων, καὶ στρατολογεῖν αὐτοῖς ἀπηγόρευται, καὶ ὅσα λιμώττοντες ἥρπασαν ἀποδιδόασιν ἔτι λιμώττοντες, καὶ τῶν ἀμφιλόγων ἐστὶν αὐτοῖς Σκιπίων ὁ πολεμήσας κριτής. ἐγὼ μὲν καὶ τοῦ μεγέθους τῶνδε καὶ τοῦ πλήθους ἐπαινῶ τὸν Σκιπίωνα, καὶ ὑμᾶς ἀξιῶ φείσασθαι διὰ τὸν φθόνον καὶ τὴν τῶν ἀνθρωπείων μεταβολήν, οἷς εἰσὶν ἔτι νῆες, πρὶν συνθώμεθα, πολλαὶ καὶ πλῆθος ἐλεφάντων, καὶ Ἀννίβας στρατηγικώτατος ἀνὴρ ἤδη στρατιὰν ἔχει, καὶ Μάγων ἐκ Κελτῶν καὶ Λιγύων ἑτέρους ἄγει πολλούς, καὶ Οὐερμινᾶς ὁ Σύφακος αὐτοῖς συμμαχεῖ καὶ ἄλλα Νομάδων ἔθνη, δούλους τε ἔχουσι πολλούς. καὶ ἢν ἀπογνῶσι τὰ παρ’ ἡμῶν, ἀφειδῶς ἅπασι χρήσονται. χαλεπώτερον δ’ οὐδὲν ἀφειδίας ἐν μάχαις, ἐν αἷς καὶ τὸ δαιμόνιον ἀνώμαλον καὶ ἐπίφθονόν ἐστιν.", "st": "9.59"}, {"sp": "N", "t": "“ἃ καὶ Σκιπίων ἔοικεν ὑφορώμενος ἐπιστεῖλαι μὲν ἡμῖν τὴν ἑαυτοῦ γνώμην, ἐπειπεῖν δ’ ὅτι καὶ βραδυνόντων συνθήσεται. εἰκὸς δ’ ἐκεῖνον καὶ τάδε ἄμεινον ἡμῶν ἐκλογίζεσθαι καὶ πλέον τι συνορᾶν, ὄντα ἐπὶ τῶν ἔργων. λυπήσομέν τε, ἀκυροῦντες αὐτοῦ τὴν παραίνεσιν, ἄνδρα φιλόπολιν καὶ στρατηγὸν ἐξαίρετον, ὃς οὐδ’ ἐς Λιβύην ἡμᾶς ὁρμωμένους παρώξυνέ τε, καὶ στρατιὰν οὐ λαβὼν αὑτῷ συνεστήσατο, καὶ τὰ ἐκεῖ προήγαγεν ἡμῖν ἐς ὅσον οὐκ ἠλπίζομεν. ὃ καὶ θαυμάζειν ἄξιον, ὅτι ῥᾳθύμως ἔχοντες ἐν ἀρχῇ τοῦδε τοῦ πολέμου νῦν ἔχετε φιλονείκως καὶ ἀμέτρως. εἰ δέ τις ταῦτα μὲν ἡγεῖται καλῶς ἔχειν, δέδιε δὲ μὴ καὶ νῦν τὰς σπονδὰς παραβῶσιν οἱ Καρχηδόνιοι, μάλιστα μὲν εἰκὸς αὐτοὺς ἤδη σπονδῶν φυλακῆς αἰσθάνεσθαι, πολλὰ ἐκ τῶν παραβάσεων παθόντας, καὶ τὴν εὐσέβειαν ἐς τὸ μέλλον ποιήσεσθαι περὶ πολλοῦ, ἐξ ἀσεβείας ἐς γόνυ πεσόντας· οὐκ ἔστι δὲ τῶν αὐτῶν συμβούλων ἄρτι μὲν καταφρονεῖν τῶν Καρχηδονίων ὡς οὐδὲν ἔτι ἰσχυόντων, δεδιέναι δ’ αὖθις ὡς ἀποστῆναι δυναμένους. ἡμῖν δὲ τὸ φυλάσσειν αὐτοὺς ἐς τὸ μὴ πάλιν αὔξεσθαι τοῦ νῦν ἀνελεῖν εὐχερέστερόν ἐστι· νῦν μὲν γὰρ ἐξ ἀπογνώσεως μαχοῦνται, ὕστερον δ’ ἀεὶ δεδιότας τηρήσομεν. ἅλις δὲ κακῶν ἕξουσι καὶ χωρὶς ἡμῶν, οἷς οἵ τε περίοικοι πάντες ἐπικείσονται δυσμεναίνοντες τῆς ποτὲ βίας, καὶ Μασσανάσσης, ἀνὴρ πιστότατος ἡμῖν, ἐφεδρεύσει παρὼν ἀεί.", "st": "9.60"}, {"sp": "N", "t": "“εἰ δ’ ἄρα τις καὶ τῶνδε πάντων καταφρονεῖ, ὅπως δ’ αὐτὸς ἐκδέξεται τὴν Σκιπίωνος ἀρχήν, τὸ ἑαυτοῦ μόνον σκοπεῖ, καὶ πιστεύει καὶ τὰ τῆς τύχης αὐτῷ ἐς τέλος ἀπαντήσειν, τί καὶ χρησόμεθα τῇ πόλει λαβόντες αὐτήν, ἢν καὶ λάβωμεν; ἀνελοῦμεν ἄρδην, ὅτι σῖτον ἡμῶν καὶ ναῦς ἥρπασαν; ἃ μετὰ πολλῶν ἄλλων ἀξιοῦσιν ἀποδοῦναι. ἢ τοῦτο μὲν οὐ πράξομεν, νέμεσίν τε θεῶν φυλασσόμενοι καὶ ψόγον ἀνθρώπων, Μασσανάσσῃ δ’ ἔχειν δώσομεν; ἀλλ’ εἰ καὶ φίλος ἐστίν, οὐ χρὴ στερροποιεῖν οὐδ’ ἐκεῖνον ἀμέτρως, ἡγεῖσθαι δὲ τὴν ἔριν αὐτῶν τὴν ἐς ἀλλήλους τῷ Ῥωμαίων κοινῷ συμφέρειν. ἀλλ’ ἐς προσόδους τὴν χώραν ἀνήσομεν; ἀλλ’ ἡ φυλάξουσα στρατιὰ τὴν πρόσοδον ἀναλώσει· πολλῆς γάρ, ὡς ἐν πολλοῖς περιοίκοις καὶ πᾶσι βαρβάροις, δεησόμεθα. ἀλλ’ ἀποίκους πέμψομεν ἐς μέσους τοσούσδε Νομάδας; οἳ τῶν μὲν βαρβάρων ἰσχυόντων ἀεὶ δεινὰ πείσονται, ἢν δ’ ἐπικρατήσωσιν αὐτῶν, ἐς τὸ μέλλον ἡμῖν ἔσονται φοβεροὶ καὶ ἐπίφθονοι, χώραν τοσήνδε καὶ πολὺ κρείττονα τῆς ἡμετέρας ἔχοντες. ἃ καὶ αὐτά μοι δοκεῖ συνιδὼν ὁ Σκιπίων κελεύειν ἡμῖν δέχεσθαι τὰς Καρχηδονίων παρακλήσεις. πειθώμεθα οὖν καὶ τοῖς δεομένοις καὶ τῷ στρατηγῷ.”", "st": "9.61"}, {"sp": "N", "t": "ὁ μὲν οὕτως εἶπε, Πόπλιος δὲ Κορνήλιος, Κορνηλίου Λέντλου συγγενὴς τοῦ τότε ὄντος ὑπάτου καὶ τὸν Σκιπίωνα διαδέξεσθαι προσδοκῶντος, ἀντέλεγεν οὕτως· “τὸ μὲν συμφέρον ἐστὶ μόνον ἐν τοῖς πολέμοις, ὦ ἄνδρες, χρήσιμον· καὶ ὅσῳ δυνατὴν ἔτι καὶ νῦν ἀποφαίνουσιν οὗτοι τὴν πόλιν, φυλάξασθαι χρὴ τὴν ἀπιστίαν αὐτῆς μετὰ τῆς δυνάμεως, καὶ τὴν ἰσχὺν προανελεῖν, ἐπεὶ μὴ τὴν ἀπιστίαν δυνάμεθα. οὐδεὶς δ’ ἡμῖν καιρὸς ἐς τὸ λῦσαι τὸν ἀπὸ Κάρχηδονίων φόβον ἐπιτηδειότερός ἐστι τοῦ παρόντος, ἐν ᾧ πάντων εἰσὶν ἀσθενεῖς καὶ ἄποροι, πρὶν αὖθις αὐτῶν ἐς ἑκάτερον αὐξηθῆναι. οὐ μέντοι καὶ τὸν τοῦ δικαίου λογισμὸν ἂν περιφύγοιμι, οὐδ’ ἀμετρίας μοι δοκῶ δόξαν οἴσεσθαι τὴν πόλιν ἐπὶ Καρχηδονίοις, οἳ παρὰ μὲν τὰς εὐπραξίας ἀδικοῦσι καὶ ἐνυβρίζουσιν ἐς ἅπαντας, ἐν δὲ ταῖς συμφοραῖς παρακαλοῦσιν, ἂν δὲ τύχωσιν, εὐθὺς ἐπὶ ταῖς συνθήκαις μετατίθενται. καὶ οὔτε σπονδῶν ἐστὶν αὐτοῖς αἰδὼς οὔτε λόγος ὅρκων· οὓς οὗτος ἀξιοῖ περισώζειν διὰ νέμεσιν θεῶν καὶ ἀνθρώπων φθόνον. ἐγὼ δ’ αὐτοὺς ἡγοῦμαι τοὺς θεοὺς ἐς τόδε τὴν Καρχηδόνα περιενεγκεῖν, ἵνα δῶσί ποτε δίκην τῆς ἀσεβείας οἳ καὶ περὶ Σικελίαν καὶ Ἰβηρίαν καὶ Ἰταλίαν καὶ ἐν αὐτῇ τῇ Λιβύῃ, καὶ πρὸς ἡμᾶς καὶ πρὸς τοὺς ἄλλους ἅπαντας, ἀεὶ συνετίθεντο καὶ παρώρκουν καὶ δεινὰ καὶ σχέτλια ἔδρων. ὧν τὰ ἀλλότρια ὑμῖν πρὸ τῶν ἡμετέρων διέξειμι, ἵνα εἰδῆτε πάντας ἐφησθησομένους Καρχηδονίοις, εἰ δίκην δοῖεν.", "st": "9.62"}, {"sp": "N", "t": "“οὗτοι Ζακανθαίους, πόλιν Ἰβηριας ἐπιφανῆ, σφίσι τε αὐτοῖς ἔνσπονδον καὶ φίλην ἡμῖν, ἡβηδὸν ἔκτειναν οὐδὲν ἀδικοῦντας. οὗτοι Νουκερίαν ὑπήκοον ἡμῶν ἐπὶ συνθήκῃ λαβόντες, καὶ ὀμόσαντες σὺν δύο ἱματίοις ἕκαστον ἀπολύσειν, τὴν μὲν βουλὴν αὐτῶν ἐς τὰ βαλανεῖα συνέκλεισαν καὶ ὑποκαίοντες τὰ βαλανεῖα ἀπέπνιξαν, τὸν δὲ δῆμον ἀπιόντα κατηκόντισαν. Ἀχερρανῶν δὲ τὴν βουλὴν ἐν σπονδαῖς ἐς τὰ φρέατα ἐνέβαλον, καὶ τὰ φρέατα ἐπέχωσαν. Μᾶρκόν τε Κορνήλιον ὕπατον ἡμέτερον ὅρκοις ἀπατήσαντες ἤγαγον μὲν ὡς ἐπισκεψόμενον αὐτῶν τὸν στρατηγὸν ἀρρωστοῦντα, συναρπάσαντες δὲ ἀπήγαγον ἐς Λιβύην ἐκ Σικελίας αἰχμάλωτον μετὰ δύο καὶ εἴκοσι νεῶν. ἔκτειναν δὲ καὶ Ῥῆγλον αἰκισάμενοι, στρατηγὸν ἕτερον ἡμῶν, ὑπ’ εὐορκίας ἐπανελθόντα πρὸς αὐτούς. ὅσα δ’ Ἀννίβας ἢ πολεμῶν ἢ ἐνεδρεύων ἢ παρορκῶν ἔς τε πόλεις καὶ στρατόπεδα ἡμῶν καὶ λήγων ἐς τοὺς συμμάχους ἔδρασε τοὺς αὑτοῦ, τάς τε πόλεις πορθῶν καὶ τοὺς αὐτῷ συστρατευσαμένους κατακαίνων, μακρὸν ἂν εἴη καταλέγειν. πλὴν ὅτι τετρακόσια ἡμῶν ἀνέστησεν ἄστη. τοὺς δ’ αἰχμαλώτους ἡμῶν τοὺς μὲν ἐς τάφρους καὶ ποταμοὺς ἐμβαλόντες ὡς γεφύραις ἐπέβαινον, τοὺς δὲ τοῖς ἐλέφασιν ὑπέβαλλον, τοὺς δ’ ἀλλήλοις μονομαχεῖν ἐκέλευον, ἀδελφοὺς ἀδελφοῖς συνιστάντες καὶ πατέρας υἱοῖς. τὰ δ’ ἔναγχος ταῦτα, περὶ εἰρήνης ἐπρέσβευον ἐνταῦθα καὶ παρεκάλουν καὶ ὤμνυον, καὶ οἱ πρέσβεις αὐτῶν ἔτι παρῆσαν, ἐν δὲ Λιβύῃ τὰς ναῦς ἡμῶν διήρπαζον καὶ τοὺς στρατιώτας κατέδεον. τοσοῦτον αὐτοῖς καὶ ἀνοίας διὰ τὴν ὠμότητα περίεστιν.", "st": "9.63"}, {"sp": "N", "t": "“τούτοις οὖν τίς ἐστῖν ἔλεος ἢ μετριοπάθεια παρ’ ἑτέρων, τοῖς οὐδὲν μέτριον οὐδ’ ἥμερον ἐς οὐδένας εἰργασμένοις; τοῖς, ὥσπερ ἔφη Σκιπίων, εἰ ἐλάβοντο ἡμῶν, οὐδ’ ἂν ὄνομα Ῥωμαίων ὑπολιποῦσιν; ἀλλὰ πίστις ἐστὶ βέβαιος ἡ δεξιά. ποία; τίς σπονδή, τίς ὅρκος ὃν οὐκ ἐπάτησαν; τίς δὲ συνθήκη καὶ χάρις ἐς ἣν οὐχ ὕβρισαν; μὴ μιμησώμεθα, φησίν, αὐτούς. τίνα γὰρ συνθήκην ἡμεῖς λύομεν οἱ μήπω τι συνθέμενοι; ἀλλὰ τὴν ὠμοτητα, φησίν, αὐτῶν μὴ μιμησώμεθα. φίλους οὖν καὶ συμμάχους ποιησόμεθα τοὺς ὠμοτάτους; οὐδέτερα τούτων ἄξια. ἀλλ’ ἐπιτρεψάτωσαν ἡμῖν αὑτοὺς νόμῳ νενικημένων, ὡς πολλοὶ σφᾶς ἐπέτρεψαν, σκεψόμεθα δ’ ἡμεῖς. και ὅ τι ἂν δῶμεν, εἴσονται χάριν, οὐχὶ συνθήκην νομίζοντες εἶναι. διαφέρει δὲ τούτοιν ἑκάτερον ὧδε. μέχρι μὲν συντίθενται, παραβήσονται καθάπερ καὶ πάλαι, πρόφασιν ἀεί τινα τῶν συνθηκῶν φέροντες ὡς ἐν αὐταῖς ἠλαττωμένοι· τὰ δ’ ἀμφίλογα εὐπροφάσιστα. ὅταν δὲ παραδῶσιν αὑτούς, καὶ τὰ ὅπλα παρελώμεθα, καὶ τὰ σώματα ἐφ’ ἡμῖν γένηται, καὶ πεισθῶσιν ὅτι μηδὲν αὐτοῖς ἐστὶν ἴδιον, τὰ μὲν φρονήματα αὐτῶν καταβήσεται, ἀγαπήσουσι δ’ ὅ τι ἂν παρ’ ἡμῶν λάβωσιν ὡς ἀλλότριον. εἰ μὲν οὖν Σκιπίων ἑτέρως δοκεῖ, τὰς γνώμας ἔχετε συγκρίνειν· εἰ δὲ συνθήσεται Καρχηδονίοις χωρὶς ὑμῶν, τί καὶ ἐπέστελλεν ὑμῖν; ἐγὼ μὲν γάρ, ὡς ὑμῖν κυρίοις οὖσι περὶ τῶνδε κρῖναι, τὴν γνώμην εἶπον, ἣν νομίζω συνοίσειν τῇ πόλει.”", "st": "9.64"}, {"sp": "N", "t": "τοιαῦτα μὲν κὰ ὁ Πόπλιος εἶπεν· ἡ δὲ βουλὴ κατ’ ἄνδρα παρ’ ἑκάστου ψῆφον ᾔτει, καὶ ἐς τὴν Σκιπίωνος γνώμην αἱ πλείους συνέδραμον. ἐγίγνοντο οὖν αἱ συνθῆκαι, τρίται αἵδε, Ῥωμαίοις καὶ Καρχηδονίοις πρὸς ἀλλήλους. καὶ ὁ Σκιπίων ἐς αὐτὰς ἐδόκει μάλιστα τοὺς Ῥωμαίους ἐναγαγέσθαι, εἴτε τῶν εἰρημένων οὕνεκα λογισμῶν, εἴτε ὡς ἀρκοῦν Ῥωμαίοις ἐς εὐτυχίαν τὸ μόνην ἀφελέσθαι Καρχηδονίους τὴν ἡγεμονίαν· εἰσὶ γὰρ οἳ καὶ τόδε νομίζουσιν, αὐτὸν ἐς Ῥωμαίων σωφρονισμὸν ἐθελῆσαι γείτονα καὶ ἀντίπαλον αὐτοῖς φόβον ἐς ἀεὶ καταλιπεῖν, ἵνα μή ποτε ἐξυβρίσειαν ἐν μεγέθει τύχης καὶ ἀμεριμνία. καὶ τόδε οὕτω φρονῆσαι τὸν Σκιπίωνα οὐ πολὺ ὕστερον ἐξεῖπε τοῖς Ῥωμαίοις Κάτων, ἐπιπλήττων παρωξυμμένοις κατὰ Ῥόδου. ὁ δὲ Σκιπίων ταῦτα συνθέμενος ἐκ Λιβύης ἐς τὴν Ἰταλίαν παντὶ τῷ στρατῷ διέπλει, καὶ ἐς τὴν Ῥώμην ἐσήλαυνε θριαμβεύων, ἐπιφανέστατα δὴ τῶν πρὸ αὐτοῦ.", "st": "9.65"}, {"sp": "N", "t": "καὶ ὁ τρόπος, ᾧ καὶ νῦν ἔτι χρώμενοι διατελοῦσιν, ἐστὶ τοιόσδε. ἐστεφάνωνται μὲν ἅπαντες, ἡγοῦνται δὲ σαλπικταί τε καὶ λαφύρων ἅμαξαι, πύργοι τε παραφέρονται μιμήματα τῶν εἰλημμένων πόλεων, καὶ γραφαὶ καὶ σχήματα τῶν γεγονότων, εἶτα χρυσὸς καὶ ἄργυρος ἀσήμαντός τε καὶ σεσημας μένος καὶ εἴ τι τοιουτότροπον ἄλλο, καὶ στέφανοι ὅσοις τὸν στρατηγὸν ἀρετῆς ἕνεκα ἀναδοῦσιν ἢ πόλεις ἢ σύμμαχοι ἢ τὰ ὑπ’ αὐτῷ στρατόπεδα. βόες δ’ ἐπὶ τοῖσδε λευκοί, καὶ ἐλέφαντες ἦσαν ἐπὶ τοῖς βουσί, καὶ Καρχηδονίων αὐτῶν καὶ Νομάδων ὅσοι τῶν ἡγεμόνων ἐλήφθησαν. αὐτοῦ δ’ ἡγοῦνται τοῦ στρατηγοῦ ῥαβδοῦχοι φοινικοῦς χιτῶνας ἐνδεδυκότες, καὶ χορὸς κιθαριστῶν τε καὶ τιτυριστῶν, ἐς μίμημα Τυρρηνικῆς πομπῆς, περιεζωσμένοι τε καὶ στεφάνην χρυσῆν ἐπικείμενοι· ἴσα τε βαίνουσιν ἐν τάξει μετὰ ᾠδῆς καὶ μετ’ ὀρχήσεως. Λυδοὺς αὐτοὺς καλοῦσιν, ὅτι (οἶμαι) Τυρρηνοὶ Λυδῶν ἄποικοι. τούτων δέ τις ἐν μέσῷ, πορφύραν ποδήρη περικείμενος καὶ ψέλια καὶ στρεπτὰ ἀπὸ χρυσοῦ, σχηματίζεται ποικίλως ἐς γέλωτα ὡς ἐπορχούμενος τοῖς πολεμίοις. ἐπὶ δ’ αὐτῷ θυμιατηρίων πλῆθος, καὶ ὁ στρατηγὸς ἐπὶ τοῖς θυμιάμασιν, ἐφ’ ἅρματος καταγεγραμμένου ποικίλως, ἔστεπται μὲν ἀπὸ χρυσοῦ καὶ λίθων πολυτίμων, ἔσταλται δ’ ἐς τὸν πάτριον τρόπον πορφύραν, ἀστέρων χρυσῶν ἐνυφασμένων, καὶ σκῆπτρον ἐξ ἐλέφαντος φέρει, καὶ δάφνην, ἣν ἀεὶ Ῥωμαῖοι νομίζουσι νίκης σύμβολον. ἐπιβαίνουσι δ’ αὐτῷ ἐπὶ τὸ ἅρμα παῖδές τε καὶ παρθένοι, καὶ ἐπὶ τῶν παρηόρων ἑκατέρωθεν ᾔθεοι συγγενεῖς. καὶ παρέπονται ὅσοι παρὰ τὸν πόλεμον ἦσαν αὐτῷ γραμματεῖς τε καὶ ὑπηρέται καὶ ὑπασπισταί. καὶ μετ’ ἐκείνους ἡ στρατιὰ κατά τε ἴλας καὶ τάξεις, ἐστεφανωμένη πᾶσα καὶ δαφνηφοροῦσα· οἱ δὲ ἀριστεῖς καὶ τὰ ἀριστεῖα ἐπίκεινται. καὶ τῶν ἀρχόντων οὓς μ ὲν ἐπαινοῦσιν, οὓς δὲ σκώπτουσιν, οὓς δὲ ψέγουσιν· ἀφελὴς γὰρ ὁ θρίαμβος, καὶ ἐν ἐξουσίᾳ λέγειν ὅ τι θέλοιεν. ἀφικόμενος δὲ ἐς τὸ Καπιτώλιον ὁ Σκιπίων τὴν μὲν πομπὴν κατέπαυσεν, εἱστία δὲ τοὺς φίλους, ὥσπερ ἔθος ἐστίν, ἐς τὸ ἱερόν.", "st": "9.66"}, {"sp": "N", "t": "καὶ τέλος εἶχε Ῥωμαίοις ὁ δεύτερος πρὸς Καρχηδονίους πόλεμος, ἀρξάμενος ἀπὸ Ἰβηρίας, λήξας δ’ ἐν Λιβύῃ ἐς τάσδε τὰς περὶ αὐτῆς Καρχηδόνος σπονδάς. καὶ ὀλυμπιάδες ἐν τοῖς Ἕλλησιν ἦσαν ἀμφὶ τὰς ἑκατὸν καὶ τεσσαράκοντα καὶ τέσσαρας. Μασσανάσσης δὲ Καρχηδονίοις τε μηνίων καὶ Ῥωμαίοις θαρρῶν ἐπέβαινε γῇ πολλῇ τῶν Καρχηδονίων ὡς γενομένῃ ποτὲ ἑαυτοῦ. καὶ οἱ Καρχηδόνιοι Ῥωμαίους παρεκάλουν σφίσι Μασσανάσσην συναλλάξαι. οἱ δ’ ἔπεμπον διαλλακτάς, οἷς εἴρητο συμπράσσειν ὅσα δύναιντο Μασσανάσσῃ. οὕτω μὲν τὴν γῆν ἀπετέμετο Καρχηδονιων ὁ Μασσανάσσης, καὶ συνθῆκαι Καρχηδονίοις καὶ πρὸς τόνδε ἐγένοντο, αἳ διέμειναν ἐς ἔτη πεντήκοντα, ἐν οἷς μάλιστα ἡ Καρχηδὼν εἰρηνεύουσα ὁμαλῶς ἐς μέγα δυνάμεως καὶ εὐανδρίας ἦλθεν ἔκ τε πεδίων εὐκαρπίας καὶ θαλάσσης εὐκαιρίας.", "st": "9.67"}, {"sp": "N", "t": "καὶ εὐθύς, οἷον ἐν ταῖς εὐτυχίαις γίγνεται, οἱ μὲν ἐρρωζμάιον, οἱ δὲ ἐδημοκράτιζον, οἷς δ’ ἤρεσκε Μασσανάσσης. ἡγοῦντο δ’ ἑκάστων οἱ καὶ δόξῃ καὶ ἀρετῇ προύχοντες, τῶν μὲν ῥωμαϊζόντων ὁ μέγας Ἄννων, τῶν δ’ αἱρουμένων τὰ Μασσανάσσου Ἀννίβας ὁ ψὰρ ἐπικαλούμενος, τῶν δὲ δημοκρατιζόντων Ἀμίλχαρ, ᾧ Σαυνίτης ἐπώνυμον ἦν, καὶ Καρθάλων· οἳ φυλάξαντες Ῥωμαίους τε Κελτίβηρσι πολεμοῦντας καὶ Μασσανάσσην ἐπικουροῦντα υἱῷ πρὸς ἑτέρων Ἰβήρων συγκεκλεισμένῳ, πείθουσι τὸν Καρθάλωνα βοήθαρχον ὄντα, καὶ ἐπὶ τῇδε τῇ ἀρχῇ τὴν χώραν περιιόντα, ἐπιθέσθαι τοῖς Μασσανάσσου σκηνουμένοις ἐν ἀμφιλόγῳ γῇ. ὁ δὲ καὶ ἔκτεινέ τινας αὐτῶν καὶ λείαν περιήλασε, καὶ τοὺς ἐν τοῖς ἀγροῖς Λίβυας ἐπὶ τοὺς Νομάδας ἤγειρεν. ἄλλα τε πολλὰ αὐτοῖς ἔργα πολέμων ἐς ἀλλήλους γίγνεται, μέχρι Ῥωμαίων ἕτεροι πρέσβεις ἐπῆλθον ἐς διαλύσεις, οἷς ὁμοίως εἴρητο Μασσανάσσῃ βοηθεῖν ἀδήλως. καὶ ἐβεβαίωσαν οἵδε τῷ Μασσανάσσῃ ὅσα προειλήφει, μετὰ τέχνης, ὧδε. εἶπον μὲν οὐδὲν οὐδὲ ἤκουσαν, ἵνα μή τι ὡς ἐν δίκῃ Μασσανάσσης ἐλαττοῖτο, ἐν μέσῳ δ’ ἀμφοῖν γενόμενοι τὰς χεῖρας διέστησαν· καὶ τοῦτο ἦν αὐτοῖς κέλευσμα πρὸς ἀμφοτέρους ἐς διαλύσεις. οὐ πολὺ δ’ ὕστερον ὁ Μασσανάσσης ἠμφισβήτει καὶ τῶν λεγομένων μεγάλων πεδίων καὶ χώρας πεντήκοντα πόλεων, ἣν Τύσκαν προσαγορεύουσιν. ἐφ’ οἷς πάλιν οἱ Καρχηδόνιοι κατέφυγον ἐπὶ Ῥωμαίους. οἱ δ’ ὑπέσχοντο μὲν αὐτοῖς καὶ τότε πρέσβεις πέμψειν ἐς δίαιταν, διέτριψαν δὲ ἕως εἴκασαν πολλὰ τῶν Καρχηδονίων διεφθάρθαι.", "st": "9.68"}, {"sp": "N", "t": "καὶ τότε πρέσβεις ἔπεμπον ἑτερους τε καὶ Κάτωνα, οἳ ἐς τὴν ἀμφίλογον γῆν ἀφικόμενοι ἠξίουν σφίσιν ἀμφοτέρους περὶ ἁπάντων ἐπιτρέπειν. Μασσανάσσης μὲν οὖν, οἷα πλεονεκτῶν καὶ Ῥωμαίοις ἀεὶ θαρρῶν, ἐπέτρεπεν, οἱ Καρχηδόνιοι δ’ ὑπώπτευον, ἐπεὶ καὶ τοὺς πρότερον ᾔδεσαν οὐκ εὖ δικάσαντας. ἔφασαν οὖν τὰς συνθήκας τὰς ἐπὶ Σκιπίωνος οὐδὲν χρῄζειν δικῶν οὐδὲ διορθώσεως, ὅσα μὴ ἐξ αὐτῶν παραβαίνεται μόνα. οἱ δ’ οὐκ ἀνασχόμενοι περὶ μέρους δικάζειν ἐπανῄεσαν, καὶ τὴν χώραν περιεσκόπουν, ἀκριβῶς τε εἰργασμένην καὶ κατασκευὰς μεγάλας ἔχουσαν. εἶδον δὲ καὶ τὴν πόλιν ἐσελθόντες, ὅση τε τὴν δύναμιν ἦν, καὶ πλῆθος ὅσον ηὔξητο ἐκ τῆς οὐ πρὸ πολλοῦ κατὰ Σκιπίωνα διαφθορᾶς. ἐπανελθόντες τε ἐς Ῥώμην, ἔφραζον οὐ ζήλου μᾶλλον ἢ φόβου γέμειν αὐτοῖς τὰ Καρχηδονίων, πόλεως δυσμενοῦς τοσῆσδε καὶ γείτονος εὐχερῶς οὕτως αὐξανομένης. καὶ ὁ Κάτων μάλιστα ἔλεγεν οὔ ποτε Ῥωμαίοις βέβαιον οὐδὲ τὴν ἐλευθερίαν ἔσεσθαι πρὶν ἐξελεῖν Καρχηδόνα. ὧν ἡ βουλὴ πυνθανομένη ἔκρινε μὲν πολεμεῖν, ἔτι δ’ ἔχρῃζε προφάσεων, καὶ τὴν κρίσιν ἀπόρρητον εἶχον. Κάτωνα δ’ ἐξ ἐκείνου φασὶν ἐν τῇ βουλῇ συνεχεῖ γνώμῃ λέγειν, Καρχηδόνα μὴ εἶναι, Σκιπίωνα δὲ τὸν Νασικᾶν τὰ ἐναντία ἀξιοῦν, Καρχηδόνα ἐᾶν, ἐς φόβον ἄρα καὶ τόνδε· Ῥωμαίων ἐκδιαιτωμένων ἤδη.", "st": "9.69"}, {"sp": "N", "t": "Καρχηδονιων δ’ οἱ δημοκρατίζοντες τοὺς τὰ Μασσανάσσου φρονοῦντας ἐξέβαλον, ἐς τεσσαράκοντα μάλιστα ὄντας, καὶ ψῆφον ἐπήνεγκαν φυγῆς, καὶ τὸν δῆμον ὥρκωσαν μήτε καταδέξεσθαί ποτε μήτε ἀνέξεσθαι τῶν λεγόντων καταδέχεσθαι. οἱ δ’ ἐξελαθέντες ἐπὶ τὸν Μασσανάσσην κατέφυγον, καὶ ἐξώτρυνον ἐς πόλεμον. ὁ δὲ καὶ αὐτὸς οὕτως ἔχων ἔπεμπε τῶν παίδων ἐς Καρχηδόνα Γολόσσην τε καὶ Μικίψαν, ἀξιῶν καταδέχεσθαι τοὺς δι’ αὑτὸν ἐξεληλαμένους. τούτοις προσιοῦσι τὰς πύλας ὁ βοήθαρχος ἀπέκλεισε, δείσας μὴ τὸν δῆμον οἱ συγγενεῖς τῶν φευγόντων καταδακρύσειαν. Γολόσσῃ δὲ καὶ ἐπανιόντι Ἀμίλχαρ ὁ Σαυνίτης ἐπέθετο, καὶ τινὰς μὲν ἔκτεινεν, αὐτὸν δὲ ἐθορύβησεν, ἐφ’ οἷς ὁ Μασσανάσσης προφάσεις τάσδε ποιούμενος ἐπολιόρκει πόλιν Ὁρόσκοπα. καὶ τῆσδε παρὰ τὰς συνθήκας ἐφιέμενος. οἱ δὲ Καρχηδόνιοι πεζοῖς μὲν δισμυρίοις καὶ πεντακισχιλίοις, ἱππεῦσι δὲ πολιτικοῖς τετρακοσίοις, Ἀσδρούβα τοῦ τότε σφῶν βοηθάρχου στρατηγοῦντος, ἐπὶ τὸν Μασσανάσσην ἐστράτευον. καὶ πλησιάσασιν αὐτοῖς Ἅσασίς τε καὶ Σούβας ταξίαρχοι τοῦ Μασσανάσσου, διενεχθέντες τι τοῖς παισὶ Μασσανάσσου, προσέδραμον ἐς αὐτομολίαν ἱππέας ἄγοντες ἑξακισχιλίους, οἷς ἐπαρθεὶς ὁ Ἀσδρούβας μετεστρατοπέδευεν ἐγγυτέρω τοῦ βασιλέως, καὶ ἐν ταῖς ἀκροβολίαις ἐπὶ κρεισσόνων ἦν. ὁ δὲ Μασσανάσσης ἐνεδρεύων αὐτὸν ὑπεχώρει κατ’ ὀλίγον οἷα φεύγων, ἕως προσήγαγεν ἐς πεδίον μέγα καὶ ἔρημον, οὗ πανταχόθεν ἦσαν λόφοι καὶ ἀπόκρημνα καὶ ἀγορᾶς ἀπορία. τότε δ’ ἐπιστρέψας ἐστρατοπέδευεν ἐν τοῖς πεδινοῖς· ὁ δὲ Ἀσδρούβας ἐς τοὺς λόφους ὡς ὀχυρωτέρους ἀνέδραμεν.", "st": "9.70"}, {"sp": "N", "t": "καὶ οἱ μὲν τῆς ἐπιούσης ἔμελλον ἐς χεῖρας ἥξειν, Σκιπίων δ’ ὁ νεώτερος, ὁ τὴν Καρχηδόνα ὕστερον ἑλών, ὑποστρατευόμενος τότε Λευκόλλῳ Κελτίβηρσι πολεμοῦντι, ἐς τὸν Μασσανάσσην ἀφικνεῖτο πεμφθεὶς ἐλέφαντας αἰτῆσαι. καὶ αὐτῷ Μασσανάσσης, τοῦ σώματος ὡς ἐς μάχην ἐπιμελούμενος, ἱππέας ἀπαντᾶν ἔπεμψε, καὶ τῶν παίδων τισὶν ἐκέλευεν ἐλθόντα ὑποδέξασθαι. αὐτὸς δ’ ἅμ’ ἕῳ τὸν στρατὸν ἐξέτασσεν, ὀγδοήκοντα μὲν καὶ ὀκτὼ γεγονὼς ἔτη, ἱππεύων δ’ ἔτι καρτερῶς καὶ γυμνὸν τὸν ἵππον ἀναβαίνων, ὡς ἔθος ἐστὶ Νομάσι, καὶ στρατηγῶν καὶ μαχόμενος, εἰσὶ γὰρ Λιβύων οἱ Νομάδες εὐρωστότατοι, καὶ μακροβίων ὄντων μακροβιώτατοι. αἴτιον δ’ ἴσως ὅ τε χειμὼν οὐ πολὺ κρύος ἔχων, [ὑφ’ οὗ φθείρεται πάντα,] καὶ τὸ θέρος οὐ κατακαῖον ὥσπερ Αἰθίοπάς τε καὶ Ἰνδούς. διὸ καὶ τῶν θηρίων τὰ δυνατώτατα ἥδε ἡ γῆ φέρει, καὶ οἱ ἄνδρες ἐν ὑπαίθρῳ καὶ πόνοις εἰσὶν ἀεί. ὁλίγος τε ὁ οἶνος αὐτοῖς, καὶ ἡ τροφὴ πἇσιν ἁπλῆ τε καὶ εὐτελής. ὁ μὲν δὴ Μασσανάσσης ἐπιβὰς ἵππου διεκόσμει τὸν στρατόν, καὶ Ἀσδρούβας ἀντεξῆγε τὸν ἴδιον αὐτῷ, πολὺ πλῆθος· ἤδη γὰρ καὶ τῷδε πολλοὶ προσεληλύθεσαν ἐκ τῆς χώρας. ὁ δὲ Σκιπίων ἐθεᾶτο τὴν μάχην ἀφ’ ὑψηλοῦ καθάπερ ἐκ θεάτρου. ἔλεγε τε πολλάκις ὕστερον, ἀγῶσι συνενεχθεὶς ποικίλοις, οὔποτε ὧδε ἡσθῆναι· μόνον γὰρ ἔφη τόνδε τὸν πόνον ἄφροντις ἰδεῖν, μυριάδας ἀνδρῶν συνιούσας ἐς μάχην ἕνδεκα. ἔλεγέ τε σεμνύνων δύο πρὸ αὑτοῦ τὴν τοιάνδε θέαν ἰδεῖν ἐν τῷ Τρωικῷ πολέμῳ, τὸν Δία ἀπὸ τῆς Ἴδης καὶ τὸν Ποσειδῶνα ἐκ Σαμοθρᾴκης.", "st": "9.71"}, {"sp": "N", "t": "γενομένης δὲ τῆς μάχης ἐς νύκτα ἀπ’ ἠοῦς, καὶ πολλῶν πεσόντων ἑκατέρωθεν, ἔδοξεν ἐπὶ κρεισσόνων ὁ Μασσανάσσης γενέσθαι. καὶ αὐτῷ ὑποστρέφοντι ἀπὸ τοῦ ἔργου ὁ Σκιπίων ὤφθη. ὁ δὲ αὐτὸν οἷα φίλον ἐκ πάππου περιεῖπε θεραπεύων. ὅπερ οἱ Καρχηδόνιοι μαθόντες, ἐδέοντο τοῦ Σκιπίωνος πρὸς Μασσανάσσην σφᾶς συναλλάξαι. ὁ δὲ συνήγαγε μὲν αὐτούς, γιγνομένων δὲ προκλήσεων οἱ Καρχηδόνιοι τῷ Μασσανάσσῃ τὴν μὲν περὶ τὸ Ἐμπόριον γῆν ἔλεγον μεθήσειν, καὶ ἀργυρίου τάλαντα δώσειν διακόσια αὐτίκα καὶ ὀκτακόσια σὺν χρόνῳ, τοὺς δ’ αὐτομόλους αἰτοῦντος οὐχ ὑπέστησαν οὐδ’ ἀκοῦσαι, ἀλλ’ ἄπρακτοι διεκρίθησαν. καὶ Σκιπίων μὲν ἐς Ἰβηρίαν ἔχων τοὺς ἐλέφαντας ἐπανῄει, Μασσανάσσης δὲ τὸν λόφον τῶν πολεμίων περιταφρεύσας, ἐφύλασσε μηδεμίαν αὐτοῖς ἀγορὰν ἐσφέρεσθαι. οὐδ’ ἄλλως ἐγγὺς ἦν οὐδέν, ἐπεὶ καὶ αὐτῷ μόλις ἐκ μακροῦ σφόδρα ἐπιμόχθως ἐφέρετο ὀλίγη. Ἀσδρούβας δ’ εὐθὺς μὲν ἐδόκει δύνασθαι διεκπαῖσαι τοὺς πολεμίους ἐρρωμένῳ ἔτι καὶ ἀπαθεῖ τῷ στρατῷ, ἀγορὰν δ’ ἔχων Μασσανάσσου πλείονα προκαλεῖσθαι τὸν Μασσανάσσην ἐνόμιζε, καὶ παρέμενε, πυνθανόμενος ἅμα καὶ Ῥωμαίων ἐπιέναι πρέσβεις ἐς διαλύσεις. οἱ δ’ ἦλθον μέν, εἴρητο δ’ αὐτοῖς, εἰ Μασσανάσσης ἐλασσοῖτο, λῦσαι τὴν διαφοράν, εἰ δ’ ἐπὶ κρεισσόνων εἴη, καὶ παροξῦναι.", "st": "9.72"}, {"sp": "N", "t": "οἱ μὲν δὴ τὸ ἑαυτῶν ἔπραξαν, ὁ δὲ λιμὸς τὸν Ἀσδρούβαν καὶ τοὺς Καρχηδονίους ἐξέτριβε· καὶ τοῖς σώμασι πάντα ἔχοντες ἀσθενῶς, βιάσασθαι μὲν οὐκέτι τοὺς πολεμίους ἐδύναντο, τὰ δ’ ὑποζύγια πρῶτον, εἶτα τοὺς ἵππους ἐπὶ τοῖς ὑποζυγίοις ἔθυον, καὶ ἱμάντας ἑψοῦντες ἤσθιον. καὶ νόσων αὐτοὺς ἰδέαι πᾶσαι κατελάμβανον ἔκ τε πονηρίας τροφῶν καὶ ἀκινησίας ἔργων καὶ ὥρας ἔτους· συνεκέκλειστο γὰρ ἐς ἓν χωρίον καὶ στενὸν στρατόπεδον ὄχλος ἀνθρώπων ἐν Λιβύῃ θέρους. τῶν τε ξύλων αὐτοὺς ἐς τὴν ἕψησιν ἐπιλιπόντων τὰ ὅπλα κατέκαιον. καὶ τῶν ἀποθνησκόντων οὐδεὶς οὔτ’ ἐξεφέρετο, Μασσανάσσου τὴν φυλακὴν οὐκ ἀνιέντος, οὔτ’ ἐξεκαίετο ξύλων ἀπορίᾳ. ὁ οὖν φθόρος αὐτοῖς ἦν πολύς τε καὶ περιώδυνος, συνοῦσιν ὀδωδόσι καὶ σηπομένοις σώμασιν. τό τε πλεῖστον ἤδη τοῦ στρατοῦ διέφθαρτο· καὶ τὸ ὑπόλοιπον οὐδεμίαν σφίσιν ἐλπίδα σωτηρίας ὁρῶντες, τοὺς αὐτομόλους ὑπέστησαν ἐκδοῦναι τῷ Μασσανάσσῃ, καὶ πεντακισχίλια ἀργυρίου τάλαντα πεντήκοντα ἔτεσιν ἐσενεγκεῖν, τούς τε φυγάδας σφῶν καταδέξασθαι παρὰ τὸ ὅρκιον, καὶ αὐτοὶ διὰ μιᾶς πύλης τοὺς ἐχθροὺς καθ’ ἕνα διεξελθεῖν σὺν χιτωνίσκῳ μόνῳ. Γολόσσης δ’ αὐτοῖς ἀπιοῦσι, χαλεπαίνων τῆς οὐ πρὸ πολλοῦ διώξεως, εἴτε συνειδότος τοῦ πατρὸς εἴτε δι’ ἑαυτοῦ, Νομάδας ἱππέας ἐπέπεμψεν, οἳ οὐκ ἀμυνομένους, οὔτε ὅπλον ἔχοντας ἐς ἄμυναν οὔτε φυγεῖν ὑπ’ ἀσθενείας δυναμένους ἔκτειναν. ἔκ τε μυριάδων πέντε στρατοῦ καὶ ὀκτακισχιλίων ἀνδρῶν ὀλίγοι πάμπαν ἐς Καρχηδόνα περιεσώθησαν, καὶ σὺν αὐτοῖς Ἀσδρουβας τε ὁ στρατηγὸς καὶ ἕτεροι τῶν ἐπιφανῶν.", "st": "9.73"}, {"sp": "N", "t": "τοιόσδε μὲν ὁ Μασσανάσσου καὶ Καρχηδονίων πόλεμος ἦν, ἐκδέχεται δ’ αὐτὸν ὁ τρίτος ἐν Λιβύῃ καὶ τελευταῖος Ῥωμαίων. καὶ Καρχηδόνιοι τῷ Μασσανάσσου πταίσματι συμπεσόντες, ἀσθενεστάτης ὑπ’ αὐτοῦ τῆς πόλεως γενομένης, αὐτόν τε Μασσανάσσην ἐδεδοίκεσαν ἐγγὺς ἔτι ὄντα μετὰ πολλοῦ στρατοῦ, καὶ Ῥωμαίους δυσμεναίνοντας ἀεὶ σφίσι καὶ πρόφασιν θησομένους τὰ ἐς τὸν Μασσανάσσην γενόμενα. ὧν οὐδέτερον κακῶς ὑπενόουν· αὐτίκα γὰρ οἱ Ῥωμαῖοι πυθόμενοι στρατὸν ἐπήγγελλον ἐς ὅλην τὴν Ἰταλίαν, τὴν μὲν χρείαν οὐ λέγοντες, ὡς δ’ ἂν ὀξέως ἔχοιεν ἐς τὰ παραγγελλόμενα χρῆσθαι. καὶ οἱ Καρχηδόνιοι νομίζοντες ἐκλύσειν τὴν πρόφασιν, ἐπεκήρυσσον Ἀσδρούβᾳ τε τῷ στρατηγήσαντι τοῦδε τοῦ πρὸς Μασσανάσσην πολέμου καὶ Καρθάλωνι τῷ βοηθάρχῳ, καὶ εἴ τις ἄλλος ἐφῆπτο τοῦ ἔργου, θάνατον, ἐς ἐκείνους τὴν αἰτίαν τοῦ πολέμου περιφέροντες. ἔς τε Ῥώμην πρέσβεις ἔπεμπον, οἳ κατηγόρουν μὲν αὐτοῦ Μασσανάσσου, κατηγόρουν δὲ καὶ τῶνδε τῶν ἀνδρῶν ὡς ἀμυναμένων αὐτὸν ὀξέως τε καὶ προπετῶς καὶ τὴν πόλιν ἐς πρόφασιν ἔχθρας ἐμβαλόντων. ὡς δέ τις τῶν βουλευτῶν τοὺς πρέσβεις ἤρετο ὅπως οὐκ ἐν ἀρχῇ τοῦ πολέμου τοὺς αἰτίους, ἀλλὰ μετὰ τὴν ἧσσαν ἐξεκήρυξαν, καὶ πρὸς ἡμᾶς οὐ πρότερον ἀλλὰ νῦν πρεσβεύεσθε, οἱ μὲν ἀποκρίσεως ἠπόρουν, ἡ δὲ βουλὴ πάλαι διεγνωκυῖα πολεμῆσαι καὶ προφάσεις ἐρεσχηλοῦσα ὧδε ἀπεκρίνατο, Καρχηδονίους οὔπω Ῥωμαίοις ἱκανῶς ἀπολογήσασθαι. πάλιν οὖν ἀγωνιῶντες ἠρώτων, εἰ δοκοῦσιν ἁμαρτεῖν, τί παθόντες ἀπολύσονται τὸ ἔγκλημα. οἱ δὲ οὕτως ἔφασαν τῷ ῥήματι, “εἰ τὸ ἱκανὸν ποιήσετε Ῥωμαίοις.” ζητούντων δ’ ἐκείνων ὅ τι εἴη τὸ ἱκανόν, οἱ μὲν ᾤοντο Ῥωμαίους ἐθέλειν τοῖς χρήμασι προσεπιθεῖναι τοῖς ἐπὶ Σκιπίωνος ὡρισμένοις, οἱ δὲ Μασσανάσσῃ τῆς ἀμφιλόγου γ ῆς μεταστῆναι. ἀποροῦντες οὖν πάλιν ἐς Ῥώμην ἔπεμπον, καὶ παρεκάλουν γνῶναι σαφῶς ὅ τι ἐστὶν αὐτοῖς τὸ ἱκανόν. οἱ δὲ αὖθις ἔφασαν εἰδέναι Καρχηδονίους καλῶς, καὶ εἰπόντες ἀπέπεμψαν.", "st": "9.74"}, {"sp": "N", "t": "οἱ μὲν δὴ φόβου καὶ ἀπορίας ἦσαν ἐν τούτῳ, Ἰτύκη δέ, ἡ Λιβύης μεγίστη μετὰ Καρχηδόνα πόλις, λιμένας τε ἔχουσα εὐόρμους καὶ στρατοπέδων καταγωγὰς δαψιλεῖς, ἑξήκοντα σταδίους ἀπὸ Καρχηδόνος ἀφεστῶσα καὶ καλῶς ἐς πόλεμον αὐτοῖς ἐπικειμένη, τὰ Καρχηδονίων ἄρα καὶ αὕτη τότε ἀπογνοῦσα καὶ τὸ πάλαι μῖσος ἐς αὐτοὺς ἐκφέρουσα ἐν καιρῷ, πρέσβεις ἐς Ῥώμην ἔπεμψεν, οἳ τὴν Ἰτύκην Π̔ωμαίοις ἐπέτρεπον. ἡ δὲ βουλὴ καὶ τέως ἐς τὸν πολεμον ὁρμῶσά τε καὶ παρασκευαζομένη, πόλεως ὀχυρᾶς οὕτω καὶ ἐπικαίρου προσγενομένης ἐξέφηνέ τε τὴν γνώμην, καὶ ἐς τὸ Καπιτώλιον, οὗπερ εἰώθασι περὶ πολέμου σκοπεῖν, συνελθοῦσα ἐψηφίσατο Καρχηδονίοις πολεμεῖν. στρατηγούς τε τοὺς ὑπάτους αὐτίκα ἐξέπεμπον, ἐπὶ μὲν τοῦ πεζοῦ Μάνιον Μανίλιον, ἐπὶ δὲ τοῦ στόλου Λεύκιον Μάρκιον Κηνσωρῖνον, οἷς ἐν ἀπορρήτῳ ἐλέλεκτο μὴ ἀνασχεῖν τοῦ πολέμου πρὶν Καρχηδόνα κατασκάψαι. οἱ μὲν δὴ θύσαντες ἐς Σικελίαν ἔπλεον ὡς ἐκεῖθεν ἐς τὴν Ἰτύκην διαβαλοῦντες, ναυσὶ δ’ ἐφέροντο πεντήκοντα μὲν πεντήρεσιν, ἑκατὸν δ’ ἡμιολίαις, ἀφράκτοις δὲ καὶ κερκούροις καὶ στρογγύλοις πολλοῖς. καὶ στρατὸν ἦγον ὀκτακισμυρίους πεζοὺς καὶ ἱππέας ἐς τετρακισχιλίους, ἀρίστους ἅπαντας· ὡς γὰρ ἐς ἐπιφανῆ στρατείαν καὶ προῦπτον ἐλπίδα πᾶς τις ἀστῶν καὶ συμμάχων ὥρμα, καὶ πολλοὶ καὶ ἐθελονταὶ παρήγγελλον ἐς τὸν κατάλογον.", "st": "9.75"}, {"sp": "N", "t": "Καρχηδονίοις δὲ προσέπεσεν ἥ τε κρίσις τοῦ πολέμου καὶ τὸ ἔργον ὁμοῦ δι’ ἑνὸς ἀγγέλου· ὁ γὰρ αὐτὸς ἔφερέ τε τὸ ψήφισμα τοῦ πολέμου, καὶ τὰς ναῦς ἐδήλου πλεῖν ἐπὶ σφᾶς. ἐκπλαγέντες οὖν ἀπεγίγνωσκον αὑτῶν ἀπορίᾳ τε νεῶν καὶ ἀπωλείᾳ προσφάτῳ τοσῆσδε νεότητος, οὐ συμμάχους ἔχοντες, οὐ μισθοφόρους ἑτοίμους, οὐ σῖτον ἐς πολιορκίαν συνενηνεγμένον, οὐκ ἄλλο οὐδέν, ὡς ἐν ἀκηρύκτῳ καὶ ταχεῖ πολέμῳ, οὐδ’ αὐτοὶ διαρκεῖν δυνάμενοι Ῥωμαίοις τε καὶ Μασσανάσσῃ. πρέσβεις οὖν ἑτέρους ἐς Ῥώμην ἔπεμπον αὐτοκράτορας, ὅπῃ δύναιντο, τὰ παρόντα διαθέσθαι. οἷς ἡ σύγκλητος εἶπεν, ἐὰν τοῖς ὑπάτοις ἔτι οὖσιν ἐν Σικελίᾳ, τριάκοντα ἡμερῶν τῶνδε, οἱ Καρχηδόνιοι τριακοσίους τοὺς ἐνδοξοτάτους σφῶν παῖδας ἐς ὁμηρείαν παράσχωσι καὶ τἄλλα κατακούσωσιν αὐτῶν, ἕξειν Καρχηδόνα ἐλευθέραν τε καὶ αὐτόνομον, καὶ γῆν ὅσην ἔχουσιν ἐν Λιβύῃ. ταῦτα μὲν ἐς τὸ φανερὸν ἐψηφίσαντο, καὶ τοῖς πρέσβεσιν ἔδωκαν ἐς Καρχηδόνα φέρειν τὸ δόγμα· ἐν ἀπορρήτῳ δὲ τοῖς ὑπάτοις ἐπέστειλαν ἔχεσθαι τῶν ἰδίᾳ σφίσιν ἐντεταλμένων.", "st": "9.76"}, {"sp": "N", "t": "οἱ δὲ Καρχηδόνιοι τὴν μὲν γνώμην ὑπώπτευον, οὐκ ἐπὶ συνθήκῃ βεβαίᾳ τὰ ὅμηρα παρέχοντες· οἷα δ’ ἐν κινδύνῳ τοσῷδε, τὰς ἐλπίδας ἐν ᾧ μηδὲν ἐκλείψουσι τιθέμενοι, σπουδῇ προλαβόντες τὴν προθεσμίαν, τοὺς παῖδας ἦγον ἐς Σικελίαν, γονέων τε αὐτοῖς ἐπικλαιόντων καὶ οἰκείων, καὶ μάλιστα τῶν μητέρων, αἳ σὺν ὀλολυγῇ μανιώδει τῶν τέκνων ἐξήπτοντο καὶ νεῶν τῶν φερουσῶν αὐτὰ καὶ στρατηγῶν τῶν ἀγόντων, ἀγκυρῶν τε ἐπελαμβάνοντο καὶ καλῴδια διέσπων καὶ ναύταις συνεπλέκοντο καὶ τὸν πλοῦν ἐκώλυον. εἰσὶ δ’ αἳ καὶ μέχρι πολλοῦ τῆς θαλάσσης παρένεον, δεδακρυμέναι τε καὶ ἐς τὰ τέκνα ἀφορῶσαι. αἱ δ’ ἐπὶ τῆς γῆς τὰς κόμας ἐτίλλοντο καὶ τὰ στέρνα ἔκοπτον ὡς ἐπὶ πένθει· ἐδόκουν γὰρ ὄνομα μὲν ἐς εὐπρέπειαν εἶναι τὴν ὁμηρείαν, ἔργῳ δὲ τῆς πόλεως ἔκδοσιν, ἐπ’ οὐδεμιᾷ συνθήκῃ τῶνδε τῶν παίδων διδομένων. καὶ πολλαὶ καὶ τοῦτο ἐν ταῖς οἰμωγαῖς κατεμαντεύοντο τῇ πόλει, μηδὲν αὐτὴν ὀνήσειν τοὺς παῖδας ἐκδιδομένους· ἐν μὲν δὴ τῇ Καρχηδόνι τῶν ὁμήρων ἡ ἀναγωγὴ τοιάδε τις ἦν, ἐν δὲ τῇ Σικελίᾳ παραλαβόντες αὐτὰ οἱ ὕπατοι διέπεμπον ἐς Ῥώμην, καὶ τοῖς Καρχηδονίοις ἔφασαν ἐς τὸ τέλος τοῦ πολέμου τὰ λοιπὰ ἐρεῖν ἐν Ἰτύκῃ.", "st": "9.77"}, {"sp": "N", "t": "διαπλεύσαντές τε ἐς αὐτὴν ἐστρατοπέδευον, ὁ μὲν πεζὸς ἔνθα πάλαι τὸ Σκιπίωνος ἦν στρατόπεδον, αἱ δὲ νῆες ἐν τοῖς λιμέσι τοῖς Ἰτυκαίων. ἀφικομένων δὲ κἀκεῖ πρέσβεων ἐκ Καρχηδόνος, οἱ μὲν ὕπατοι προυκάθηντο ἐπὶ βήματος ὑψηλοῦ, ἡγεμόνων τε σφίσι καὶ χιλιάρχων παρεστώτων, ἡ στρατιὰ δ’ ἑκατέρωθεν ἐπὶ μῆκος πολὺ ὅπλοις τε ἐπισήμοις ἐσκεύαστο, καὶ τὰ σημεῖα ἔφερον ὀρθά, ἵνα οἱ πρέσβεις τὸ πλῆθος ἐκ τούτων συμβάλοιεν. ἐπεὶ δ’ οἱ μὲν ὕπατοι τῷ σαλπικτῇ προσέταξαν ὑποσημῆναι σιωπήν, ὁ δὲ κήρυξ ἀνεῖπε τοὺς Καρχηδονίων πρέσβεις προσιέναι, οἱ μὲν ἐσήγοντο διὰ στρατοπέδου μακροῦ, καὶ τοῦ βήματος οὐ προσεπέλαζον, ἀλλὰ περισχοίνισμα ἦν ἐν μέσῳ, οἱ δ’ ὕπατοι λέγειν αὐτοὺς ἐκέλευον ὅ τι χρῄζοιεν. καὶ οἱ πρέσβεις ἔλεγον ἐλεεινὰ πολλὰ καὶ ποικίλα, συνθηκῶν τε πέρι τῶν σφίσι πρὸς Ῥωμαίους γενομένων, καὶ Καρχηδόνος αὐτῆς χρόνου καὶ πλήθους καὶ δυνάμεως καὶ ἀρχῆς τῆς ἐς πολὺ μεγίστης ἐν γῇ καὶ θαλάσσῃ γενομένης. οὐκ ἐπὶ σεμνολογίᾳ δὲ ἔφασαν λέγειν· οὐ γὰρ εἶναι καιρὸν ἐν συμφοραῖς σεμνολογίας, “ἀλλ’ ἐς σωφρόνισμα ὑμῖν, ὦ Ῥωμαῖοι, καὶ μετριοπάθειαν ἡ τῆς ἡμετέρας μεταβολῆς ὀξύτης ἔστω. κράτιστοι δέ, ὅσοι τοὺς πταίσαντας ἐλεοῦντες τὸ σφέτερον εὔελπι ποιοῦνται τῷ μηδὲν ἐς ἄλλας τύχας ἁμαρτεῖν. καὶ τάδε μὲν ὑμῶν ἄξια καὶ τῆς ὑμετέρας εὐσεβείας, ἣν προσποιεῖσθε μάλιστα ἀνθρώπων·", "st": "9.78"}, {"sp": "N", "t": "“εἰ δὲ καὶ ἀνημέρων ἐτετυχήκειμεν ἐχθρῶν, κόρος ἐστὶν ἀτυχημάτων ὅσα πεπόνθαμεν, οἳ τὴν ἡγεμονίαν τῆς τε γῆς καὶ θαλάσσης ἀφῃρήμεθα, καὶ τὰς ναῦς ὑμῖν παρεδώκαμεν, καὶ ἄλλας οὐκ ἐπικτώμεθα, καὶ θήρας καὶ κτήσεως ἐλεφάντων ἀπέστημεν, καὶ ὅμηρα τὰ κράτιστα καὶ πάλαι καὶ νῦν παρεδώκαμεν, καὶ φόρους τελοῦμεν εὐτάκτως οἱ παρ’ ἑτέρων ἀεὶ λαμβάνοντες. καὶ τάδε ἤρκεσε τοῖς πατράσιν ὑμῶν, οἷς ἐπολεμήσαμεν· καὶ συνθήκας ἐπ’ αὐτοῖς ἐγράψαντο ἡμῖν ὡς φίλοις τε καὶ συμμάχοις, καὶ ὅρκος ἔστιν ἐν ταῖς συνθήκαις ἀμφοῖν ὅμοιος. κἀκεῖνοι μὲν ἡμῖν, οἷς ἐπολεμήσαμεν, πιστοὶ μετὰ ταῦτα ἐγένοντο· ὑμεῖς δέ, οἷς οὐδ’ ἐς χεῖρας ἤλθομεν, τί τῶνδε τῶν συνθηκῶν αἰτιώμενοι παραβεβάσθαι, τὸν πόλεμον τόνδε ὀξέως οὕτως ἐψηφίσασθέ τε καὶ ἀκηρύκτως ἐπηγάγετε ἡμῖν; πότερον οὐ δίδομεν τοὺς φόρους; ἢ ναῦς ἔχομεν, ἢ τοὺς ἐπιφθόνους ἐλέφαντας; ἢ οὐ πιστοὶ τὰ πρὸς ὑμᾶς ἐξ ἐκείνου γεγόναμεν; ἢ οὐκ ἐλεεινοὶ τῶν πέντε μυριάδων τῶν χθὲς ἀπολομένων ὑπὸ λιμοῦ; ἀλλὰ Μασσανάσσῃ πεπολεμήκαμεν· πολλά γε πλεονεκτοῦντι· καὶ πάντα δι’ ὑμᾶς ἐφέρομεν. ἀπαύστως δ’ ἔχων καὶ ἀθεμίστως ἐς ἡμᾶς καὶ τὸ ἔδαφος ἐν ᾧ καὶ ἐτράφη καὶ ἐπαιδεύθη, γῆν ἄλλην ἡμῶν ἀπέσπα περὶ τὸ Ἐμπόριον· καὶ λαβὼν καὶ τήνδε ἐπέβαινεν ἑτέρας, μέχρι τὰς συνθήκας ἡμῖν τὰς πρὸς ὑμᾶς συνέχεεν· εἰ τοῦτ’ ἐστὶν ἡ τοῦδε τοῦ πολέμου πρόφασις, ἡμεῖς δὲ καὶ τοὺς ἀμυναμένους αὐτὸν ἐξεκηρύξαμεν, καὶ πρὸς ὑμᾶς πρέσβεις ἐπέμψαμεν οἳ περὶ τούτων ἀπελογοῦντο, καὶ ἑτέρους αὐτοκράτορας ὅπῃ θέλετε συνθέσθαι. τί οὖν ἔδει νεῶν καὶ στόλου καὶ στρατοῦ πρὸς ἄνδρας οὐχ ὁμολογοῦντας μὲν ἁμαρτεῖν, ἑαυτοὺς δὲ ὑμῖν ἐπιτρέποντας; ὅτι δὲ οὐκ ἀπατῶντες ὑμᾶς, οὐδὲ μικρολογούμενοι παθεῖν ὅ τι ἂν ζημιῶτε, ταῦτα προυτείνομε ν, ἐπιδέδεικται σαφῶς. ὅτε τοὺς ἀρίστους παῖδας ἐς ὁμηρείαν αἰτοῦσιν ὑμῖν εὐθύς, ὡς τὸ δόγμα ἐκέλευε, τὰς τριάκοντα προλαβόντες ἡμέρας, ἀπεστείλαμεν. τοῦ δ’ αὐτοῦ δόγματός ἐστιν, ἢν παράσχωμεν ὑμῖν τὰ ὅμηρα, τὴν Καρχηδόνα ἐλευθέραν ἐᾶν καὶ αὐτόνομον, κεκτημένην ἃ ἔχομεν.”", "st": "9.79"}, {"sp": "N", "t": "οἱ μὲν δὴ πρέσβεις τοσαῦτα εἶπον, Κηνσωρῖνος δ’ ὑπαναστὰς ἀντέλεξεν ὧδε· “τὰς μὲν αἰτίας τοῦ πολέμου τί δεῖ λέγειν ὑμῖν, ὦ Καρχηδόνιοι, πρεσβεύσασιν ἐς Ῥώμην καὶ παρὰ τῆς συγκλήτου μαθοῦσιν; ὃ δὲ ἐψεύσασθε περὶ ἡμῶν, τοῦθ’ ὑμᾶς ἐλέγξω. καὶ γὰρ τὸ δόγμα δηλοῖ, καὶ ἡμεῖς ὑμῖν ἐν Σικελίᾳ προείπομεν τὰ ὅμηρα παραλαμβάνοντες, τὰ λοιπὰ τῶν δοξαντων ἐπικελεύσειν ἐν Ἰτύκῃ. τῶν μὲν οὖν ὁμήρων τῆς τε ταχυτῆτος καὶ τῆς ἐπιλέξεως ἐπαινοῦμεν ὑμᾶς· τί δὲ ὅπλων δεῖ τοῖς εἰρηνεύουσι καθαρῶς; φέρετε· πάντα ὅσα δημόσιά τε καὶ ἴδια ἕκαστος ὑμῶν ἔχει, βέλη τε καὶ καταπέλτας, ἡμῖν παράδοτε.” ὁ μὲν οὕτως εἶπεν, οἱ δὲ πρέσβεις ἔφασαν ἐθέλειν μὲν καὶ τοῖσδε ὑπακοῦσαι, ἀπορεῖν δὲ ὅπως Ἀσδρούβαν, ᾧ θάνατον ἐπεκήρυξαν, δύο μυριάδας ἀνδρῶν ἤδη συναγαγόντα καὶ αὐτῇ Καρχηδόνι παραστρατοπεδεύοντα ἀμυνοῦνται. εἰπόντων δὲ τῶν ὑπάτων ὅτι Ῥωμαῖοι τούτων ἐπιμελήσονται, οἱ μὲν καὶ ταῦτα δώσειν ὑπέσχοντο. καὶ συμπεμφθέντες αὐτοῖς Κορνήλιός τε Σκιπίων ὁ Νασικᾶς καὶ Γναῖος Κορνήλιος ὁ Ἱσπανὸς ἐπίκλησιν παρελάμβανον εἴκοσι μυριάδας πανοπλιῶν, καὶ βελῶν καὶ ἀκοντίων πλῆθος ἄπειρον, καὶ καταπέλτας ὀξυβελεῖς τε καὶ λιθοβόλους ἐς δισχιλίους· καὶ φερομένων αὐτῶν ἡ μὲν ὄψις ἦν λαμπρὰ καὶ παράλογος, ἀμαξῶν τοσῶνδε ὑπ’ αὐτῶν τῶν πολεμίων ἀγομένων, οἱ δὲ πρέσβεις εἵποντο αὐτοῖς, καὶ ὅσοι τῆς γερουσίας ἢ τῆς ἄλλης πόλεως ἄριστοι ἢ ἱερεῖς ἢ ἄλλως ἐπιφανεῖς ἔμελλον τοὺς ὑπάτους ἐς ἐντροπὴν ἢ ἔλεον ἄξειν. ἐσαχθέντες δὲ αὐτῷ κόσμῳ τοῖς ὑπάτοις παρέστησαν. καὶ ὁ Κηνσωρῖνος (ἦν γὰρ εἰπεῖν ἱκανώτερος τοῦ συνάρχου) ἀναστὰς καὶ τότε, καὶ σκυθρωπάσας ἐπὶ πολύ, ἔλεξεν ὧδε.", "st": "9.80"}, {"sp": "N", "t": "“τῆς μὲν εὐπειθείας ὑμᾶς, ὦ Καρχηδόνιοι, καὶ προθυμίας τῆς μέχρι νῦν ἔς τε τὰ ὅμηρα καὶ τὰ ὅπλα ἐπαινοῦμεν, χρὴ δ’ ἐν τοῖς ἀναγκαίοις βραχυλογεῖν. ὑπόστητε γενναίως τὸ λοιπὸν τῆς συγκλήτου κέλευσμα· ἔκστητε τῆς Καρχηδόνος ἡμῖν, καὶ ἀνοικίσασθε ὅπῃ θέλετε τῆς ὑμετέρας, ὀγδοήκοντα σταδίους ἀπὸ θαλάσσης· τήνδε γὰρ ἡμῖν ἔγνωσται κατασκάψαι.” οἱ δ’ ἔτι λέγοντος αὐτοῦ τὰς χεῖρας ἐς τὸν οὐρανὸν ἀνέσχον μετὰ βοῆς, καὶ τοὺς θεοὺς ὡς ἠπατημένοι κατεκάλουν, πολλά τε καὶ δυσχερῆ κατὰ Ῥωμαίων ἐβλασφήμουν, ἢ θανατῶντες ἢ ἔκφρονες ὄντες, ἢ τοὺς Ῥωμαίους ἐς μύσος πρέσβεων διερεθίζοντες. ἔς τε τὴν γῆν σφᾶς ἐρρίπτουν, καὶ χερσὶ καὶ κεφαλαῖς αὐτὴν ἔτυπτον· οἱ δὲ καὶ τὰς ἐσθῆτας ἐπερρήγνυντο, καὶ τοῖς σώμασι τοῖς ἑαυτῶν ἐνύβριζον ὡς ὑπὸ ἀνοίας ἐνηδρευμένοι. ἐπεὶ δέ ποτε αὐτοῖς ὁ οἶστρος ἔληξε, σιωπὴ πολλὴ καὶ κατήφεια ἦν οἷα νεκρῶν κειμένων. Ῥωμαῖοι δ’ ἐξεπλήσσοντο, καὶ οἱ ὕπατοι φέρειν αὐτοὺς ἐγνώκεσαν ὡς ἐπὶ ἀλλοκότῳ κελεύσματι, μέχρι παύσαιντο ἀγανακτοῦντες, καλῶς εἰδότες ὅτι τὰ μέγιστα δεινὰ αὐτίκα μὲν ἐς θρασύτητα ἐκπλήσσει, σὺν χρόνῳ δὲ καταδουλοῖ τὴν τόλμαν ἡ ἀνάγκη. ὃ καὶ τότε ἔπαθον οἱ Καρχηδόνιοι· παρὰ γὰρ τὴν σιωπὴν ἁπτομένου σφῶν τοῦ κακοῦ μᾶλλον, ἀγανακτεῖν μὲν ἔτι ἐπαύσαντο, ἀνέκλαιον δὲ καὶ κατεθρήνουν ἑαυτούς τε καὶ παῖδας καὶ γυναῖκας ἐξ ὀνομάτων, καὶ τὴν πατρίδα αὐτήν, ὡς ἐς ἄνθρωπον ἀκούουσαν λέγοντες οἰκτρὰ καὶ πολλά. οἱ δὲ ἱερεῖς καὶ τὰ τῶν ἱερῶν ὀνόματα καὶ τοὺς ἐν αὐτοῖς θεοὺς ἀνεκάλουν, ὡς παροῦσι κἀκείνοις προφέροντες τὴν ἀπώλειαν. ἦν τε παμμιγὴς καὶ ἐλεεινὸς οἶκτος οἰμωζόντων ὁμοῦ τά τε κοινὰ καὶ τὰ ἴδια, μέχρι καὶ Ῥωμαίους αὐτοῖς ἐπιδακρῦσαι.", "st": "9.81"}, {"sp": "N", "t": "τοὺς δὲ ὑπάτους ἐσῄει μὲν οἶκτος ἀνθρωπίνης μεταβολῆς, σκυθρωποὶ δ’ ἀνέμενον καὶ τούτων κόρον αὐτοῖς ἐγγενέσθαι. ὡς δὲ καὶ ὀδυρμῶν ἔληξαν, αὖθις ἦν σιωπή. καὶ λόγον αὑτοῖς διδόντες ὡς ἡ μὲν πόλις ἐστὶν ἄνοπλος ἔρημος, οὐ ναῦν, οὐ καταπέλτην, οὐ βέλος, οὐ ξίφος ἔχουσα, οὐκ ἄνδρας οἰκείους ἱκανοὺς ἀπομάχεσθαι πέντε μυριάδων ἔναγχος διεφθαρμένων, ξενικὸν δὲ οὐδὲν ἔστιν ἢ φίλος ἢ σύμμαχος ἢ καιρὸς ἐς ταῦτα, ἔχουσι δ’ αὐτοῖς οἱ πολέμιοι καὶ τὰ τέκνα καὶ τὰ ὅπλα καὶ τὴν χώραν, καὶ περικάθηνται τὸ ἄστυ ἔνοπλοι ναυσὶ καὶ πεζῷ καὶ μηχανήμασι καὶ ἵπποις, Μασσανάσσης δ’ ἐχθρὸς ἕτερος ἐν πλευραῖς, θορύβου μὲν ἔτι καὶ ἀγανακτήσεως ἐπέσχον ὡς οὐδὲν ἐν ταῖς συμφοραῖς ὠφελούντων, ἐς δὲ λόγους αὖθις ἐτράποντο. καὶ Βάννων, ᾧ Τιγίλλας ἐπώνυμον ἦν, ἐπιφανέστατος ὢν ἐν τοῖς τότε παροῦσιν, αἰτήσας εἰπεῖν ἔλεξεν·", "st": "9.82"}, {"sp": "N", "t": "“εἰ μὲν ἔστι καὶ τῶν πρότερον εἰρημένων ἔτι πρὸς ὑμᾶς, ὦ Ῥωμαῖοι, λόγος, ἐροῦμεν, οὐχ ὡς δίκαια προφέροντες (οὐ γάρ ἐστιν ἐν καιρῷ τοῖς ἀτυχοῦσιν ἀντιλογία), ἀλλ’ ἵνα μάθητε ὡς οὐκ ἀπροφάσιστός ἐστιν ὑμῖν ὁ ἔλεος ὁ ἐφ’ ἡμῖν, οὐδὲ ἄλογος. ἡμεῖς γὰρ Λιβύης ἄρχοντες καὶ θαλάσσης ὅτι πλείστης, περὶ ἡγεμονίας ὑμῖν ἐπολεμήσαμεν· καὶ ταύτης ἀπέστημεν ἐπὶ Σκιπίωνος, ὅτε τὰς ναῦς ὑμῖν παρέδομεν καὶ ἐλέφαντας ὅσους εἴχομεν, καὶ φόρους ἐταξάμεθα δώσειν καὶ δίδομεν ἐν καιρῷ. πρὸς οὖν θεῶν τῶν τότε ὀμωμοσμένων, φείδεσθε μὲν ἡμῶν, φείδεσθε δὲ τῶν Σκιπίωνος ὅρκων, ὀμόσαντος ἔσεσθαι Ῥωμαίους Καρχηδονίοις συμμάχους καὶ φίλους. οὐδ’ ἔστιν ἐς ταυθ’ ὅ τι ἡμάρτομεν. οὐ ναῦς ἔχομεν, οὐκ ἐλέφαντας, οὐ τοὺς φόρους ἐκλείπομεν, ἀλλὰ καὶ συνεμαχήσαμεν ὑμῖν ἐπὶ τρεῖς βασιλέας. μηδέ τῳ παραστῇ καταγιγνώσκειν, εἰ ταῦτα καὶ πρῴην εἴπομεν, ὅτε τὰ ὅπλα ᾐτεῖτε· αἵ τε γὰρ συμφοραὶ ποιοῦσι μακρολόγους, καὶ ἅμα συνθηκῶν οὐδὲν ἐν ταῖς ἱκεσίαις δυνατώτερον, οὐδ’ ἔχομεν ἐν οὐδὲν ἕτερον ἀντὶ λόγων καταφυγεῖν, οἳ τὴν δύναμιν ὑμῖν ἅπασαν ἐξέδομεν. τὰ μὲν δὴ πρότερα τοιαῦτα, ὧν ὁ Σκιπίων ἐστὶν ἡμῖν, ὦ Ῥωμαῖοι, βεβαιωτής· τῶν δὲ παρόντων ὑμεῖς, ὦ ὕπατοι, δημιουργοὶ καὶ μάρτυρές ἐστε ἡμῖν. ὅμηρα ᾐτήσατε, καὶ τὰ κράτιστα ἠγάγομεν ὑμῖν. ὅπλα ᾐτήσατε, καὶ πάντα ἐλάβετε, ὧν οὐδὲ οἱ ληφθέντες ἐν ταῖς πολιορκίαις ἑκόντες μεθίενται. ἐπιστεύσαμεν δὲ ἡμεῖς τῷ Ῥωμαίων ἤθει καὶ τρόπῳ· καὶ γὰρ ἡ σύγκλητος ἡμῖν ἐπέστειλε, καὶ ὑμεῖς, τὰ ὅμηρα αἰτοῦντες, ἔφατε τὴν Καρχηδόνα αὐτόνομον ἐάσειν, εἰ λάβοιτε. εἰ δὲ προσέκειτο καὶ τὰ λοιπὰ ὑμῶν ἀνέξεσθαι κελευόντων, οὐκ εἰκὸς ἦν ὑμᾶς ἐπὶ μὲν τοῖς ὁμήροις, αἰτήματι σοφεῖ, τὴν πόλιν αὐτόνομον ἔσεσθα ι προαγορεῦσαι, ἐν δὲ προσθήκῃ τῶν ὁμήρων ποιεῖσθαι τὴν Καρχηδόνος αὐτῆς κατασκαφήν, ἣν εἰ θέμις ὑμῖν ἐστὶν ἀνελεῖν, πῶς ἐλευθέραν ἔτι ἀφήσετε ἢ αὐτόνομον, ὡς ἐλέγετε;", "st": "9.83"}, {"sp": "N", "t": "“τάδε μὲν εἴχομεν εἰπεῖν καὶ περὶ τῶν προτέρων συνθηκῶν καὶ περὶ τῶν πρὸς ὑμᾶς γενομένων. εἰ δὲ καὶ τούτων οὐκ ἀνέξεσθε, παρίεμεν ἅπαντα, καὶ ὃ τοῖς ἀτυχοῦσίν ἐστι λοιπόν, ὀδυρόμεθα καὶ δεόμεθα. πολλὴ δ’ ἡ ἱκεσία δι’ ἀφθονίαν κακῶν· ὑπέρ τε γὰρ πόλεως παρακαλοῦμεν ἀρχαίας, χρησμοῖς μετὰ θεῶν συνῳκισμένης, καὶ ὑπὲρ δόξης ἐπὶ μέγα προελθούσης, καὶ ὀνόματος ἐπιφοιτήσαντος ἐπὶ τὴν γῆν ὅλην, ὑπέρ τε ἱερῶν τῶν ἐν αὐτῇ τοσῶνδε καὶ θεῶν οὐδὲν ἀδικούντων, οὓς μὴ πανηγύρεις ἀφέλησθε καὶ πομπὰς καὶ ἑορτάς, μηδὲ τοὺς τάφους τὰ ἐναγίσματα, οὐδὲν ὑμῖν ἔτι τῶν νεκρῶν ἐπιζημίων ὄντων. εἰ δὲ καὶ ἡμῶν ἔστιν ἔλεος (φατὲ δὲ καὶ ἡμᾶς ἐλεεῖν οἳ συγχωρεῖτε μετοικίσασθαι), φείσασθε πολιτικῆς ἑστίας, φείσασθε ἀγορᾶς, φείσασθε βουλαίας θεοῦ, πάντων τε τῶν ἄλλων ὅσα τοῖς ἔτι ζῶσι τερπνὰ καὶ τίμια. τί γὰρ δὴ καὶ δέος ἔστιν ὑμῖν ἔτι Καρχηδόνος, οἳ καὶ τὰς ναῦς ἔχετε ἡμῶν καὶ τὰ ὅπλα καὶ τοὺς ἐπιφθόνους ἐλέφαντας; περὶ δὲ τῆς ἀνοικίσεως, εἴ τῳ δοκεῖ τοῦτο ἐς παρηγορίαν ἡμῖν προτίθεσθαι, ἔστι καὶ τόδε ἀμήχανον, ἀνδράσιν ἐς ἤπειρον ἀνοικίσασθαι θαλασσοβιώτοις, ὧν ἄπειρον πλῆθος ἐργάζεται τὴν θάλασσαν. δίδομεν δ’ ὑμῖν ἀντίδοσιν αἱρετωτέραν ἡμῖν καὶ εὐκλεεστέραν ὑμῖν. τὴν μὲν πόλιν ἐᾶτε τὴν οὐδενὸς ὑμῖν αἰτίαν, αὐτοὺς δὲ ἡμᾶς οὓς ἀνοικίζετε, εἰ θέλετε, διαχρήσασθε. οὕτω γὰρ ἀνθρώποις δόξετε χαλεπαίνειν, οὐχ ἱεροῖς καὶ θεοῖς καὶ τάφοις καὶ πόλει μηδὲν ἀδικούσῃ.", "st": "9.84"}, {"sp": "N", "t": "“δόξης δ’ ἀγαθῆς καὶ εὐσεβοῦς ἐφίεσθε, ὦ Ῥωμαῖοι, παρὰ πάντα ἔργα, καὶ μετριοπάθειαν ἐν τοῖς εὐτυχήμασιν ἐπαγγέλλεσθε, καὶ τοῦθ’ οἷς ἂν ἀεὶ λάβητε καταλογίζεσθε· μὴ δή, πρὸς Διὸς καὶ θεῶν, τῶν τε ἄλλων καὶ ὅσοι Καρχηδόνα ἔτι ἔχουσί τε καὶ μή ποτε μνησικακήσαιεν ὑμῖν μηδὲ παισὶν ὑμετέροις, μὴ ἀγαθὴν δόξαν ὑμῶν αὐτῶν ἐν ἡμῖν πρώτοις διαβάλητε, μηδὲ τοιῷδε ἔργῳ τὴν εὔκλειαν ὑμῶν καταμιάνητε, χαλεπῷ μὲν ἐργασθῆναι χαλεπῷ δὲ ἀκουσθῆναι, παρά τε πρώτοις ὑμῖν ἐξ ἅπαντος τοῦ βίου γενησομένῳ. πόλεμοι γὰρ πολλοὶ μὲν Ἕλλησιν ἐγένοντο καὶ βαρβάροις, πολλοὶ δὲ ὑμῖν, ὦ Ῥωμαῖοι, πρὸς ἑτέρους· καὶ οὐδείς πω κατέσκαψε πόλιν χεῖράς τε πρὸ μάχης καθεῖσαν καὶ ὅπλα καὶ τέκνα παραδοῦσαν. καὶ εἴ τις ἔστιν ἐς ἀνθρώπους ἄλλη ζημία, καὶ ταύτην παθεῖν ὑπομένουσαν. προφέροντες δ’ ὑμῖν ὁρκίους θεοὺς καὶ τύχην ἀνθρωπείαν καὶ τὴν φοβερωτάτην τοῖς εὐτυχοῦσι Νέμεσιν, δεόμεθα μήτε ἐς τὴν ὑμετέραν εὐπραγίαν ὑμᾶς ὑβρίσαι, μήτε τὰς ἡμετέρας συμφορὰς ἐς ἀνήκεστον προαγαγεῖν, συγχωρῆσαι δ’, εἰ μὴ δίδοτε τὴν πόλιν ἔχειν, ἔς γε τὴν σύγκλητον ἔτι πρεσβεῦσαι περὶ αὐτῆς καὶ δεηθῆναι. βραχὺ δ’ ὁρᾶτε τὸ διάστημα τοῦ χρόνου, βάσανον μὲν ἡμῖν φέρον μακρὰν ἐν ὀλίγῳ διὰ τὴν τῶν ἐσομένων ἀμφιβολίαν· ὑμῖν δὲ τὸ μὲν ἀσφαλὲς ἴσον, ἢ νῦν ἢ μετ’ ὀλίγον τὰ δοκοῦντα δρᾶν, τὸ δ’ εὐσεβὲς καὶ φιλάνθρωπον ἐπιγίγεται.”", "st": "9.85"}, {"sp": "N", "t": "τοιαῦτα μὲν εἶπεν ὁ Βάννων, οἱ δὲ ὕπατοι δῆλοι μὲν ἦσαν ἐσκυθρωπακότες παρὰ πάντα τὸν λόγον ὅτι μηδὲν ἐνδώσουσιν αὐτοῖς, παυσαμένου δὲ ὁ Κηνσωρῖνος ἔλεξε· “περὶ μὲν ὧν ἡ σύγκλητος προσέταξε, τί δεῖ πολλάκις λέγειν; προσέταξε γάρ, καὶ χρὴ γενέσθαι· οὐδὲ ἀναθέσθαι δυνάμεθα τὰ ἤδη κεκελευσμένα γενέσθαι. ταῦτα δὲ εἰ μὲν ὡς ἐχθροῖς ἐπεκελεύομεν, ἔδει μόνον εἰπεῖν καὶ ποιεῖν ἀναγκάζειν· ἐπεὶ δὲ ἐπ’ ὠφελείᾳ κοινῇ, τάχα μέν τι καὶ ἡμῶν, τὸ δὲ πλέον ὑμῶν, ὦ Καρχηδόνιοι, γίγνεται, οὐκ ὀκνήσω καὶ τοὺς λογισμοὺς ὑμῖν εἰπεῖν, ἢν δύνησθε πεισθῆναι μᾶλλον ἢ βιασθῆναι. ἡ θάλασσα ὑμᾶς ἥδε, μεμνημένους τῆς ἐν αὐτῇ ποτὲ ἀρχῆς καὶ δυνάμεως, ἀδικεῖν ἐπαίρει, καὶ ἀπὸ τοῦδε ἐς συμφορὰς περιφέρει. Σικελίᾳ τε γὰρ δι’ αὐτὴν ἐπεχειρήσατε, καὶ Σικελίαν ἀπωλέσατε· ἔς τε Ἰβηρίαν διεπλεύσατε, καὶ Ἰβηρίαν ἀφῄρησθε. ἔν τε ταῖς συνθήκαις ἐλῄζεσθε τοὺς ἐμπόρους, καὶ τοὺς ἡμετέρους μάλιστα, ἵνα λανθάνοιτε, κατεποντοῦτε, ἕως ἁλόντες ποινὴν ἡμῖν ἔδοτε Σαρδώ. οὕτω καὶ Σαρδοῦς ἀφῃρέθητε διὰ τὴν θάλασσαν, ἣ πέφυκε πείθειν ἅπαντας ἀεὶ τοῦ πλέονος ὀρέγεσθαι διὰ τὴν ἐν αὐτῇ ταχυεργίαν.", "st": "9.86"}, {"sp": "N", "t": "“ὃ καὶ Ἀθηναίους, ὅτε ἐγένοντο ναυτικοί, μάλιστα ηὔξησέ τε καὶ καθεῖλεν· ἔοικε γὰρ τὰ θαλάσσια τοῖς ἐμπορικοῖς κέρδεσιν, ἃ καὶ τὴν αὔξησιν ἔχει καὶ τὴν ἀπώλειαν ἀθρόαν. ἴστε γοῦν αὐτοὺς ἐκείνους ὧν ἐπεμνήσθην, ὅτι τὴν ἀρχὴν ἐπὶ τὸν Ἰόνιον ἐκτείνοντες ἐς Σικελίαν οὐ πρὶν ἀπέστησαν τῆς πλεονεξίας, πρὶν τὴν ἀρχὴν ἅπασαν ἀφαιρεθῆναι, καὶ λιμένας καὶ ναῦς παραδοῦναι τοῖς πολεμίοις, καὶ φρουρὰν ἐνδέξασθαι τῇ πόλει, καὶ τὰ τείχη σφῶν αὐτοὶ τὰ μακρὰ καθελεῖν, καὶ σχεδὸν ἠπειρῶται τότε κἀκεῖνοι γενέσθαι. ὃ καὶ διέσωσεν ἐπὶ πλεῖστον αὐτούς. εὐσταθέστερος γάρ, ὦ Καρχηδόνιοι, ὁ ἐν ἠπείρῳ βίος, γεωργίᾳ καὶ ἠρεμίᾳ προσπονῶν· καὶ σμικρότερα μὲν ἴσως τὰ κέρδη, βεβαιότερα δὲ καὶ ἀκινδυνότερα καθάπαξ τὰ τῆς γεωργίας τῶν ἐμπόρων. ὅλως τέ μοι δοκεῖ πόλις ἡ μὲν ἐν τῇ θαλάσσῃ ναῦς τις εἶναι μᾶλλον ἣ γῆ, πολὺν τὸν σάλον τῶν πραγμάτων ἔχουσα καὶ τὰς μεταβολάς, ἡ δὲ ἐν τῷ μεσογείῳ καρποῦσθαι τὸ ἀκίνδυνον ὡς ἐν γῇ. διὰ τοῦτ’ ἄρα καὶ τὰ πάλαι βασίλεια ὡς ἐπίπαν ἦν ἐν μέσῳ, καὶ ἀπὸ τοῦδε μέγιστα ἐγένοντο τὰ Μήδων καὶ Ἀσσυρίων καὶ Περσῶν καὶ ἑτέρων.", "st": "9.87"}, {"sp": "N", "t": "“ἀλλὰ βασιλικῶν μὲν ὑποδειγμάτων παύομαι, οὐδὲν ὑμῖν ἔτι διαφερόντων· ἐς δὲ τὴν ὑμετέραν Λιβύην ἀπίδετε, ὅσαι μεσόγειοι πόλεις ἀκινδύνως βιοῦσιν. ὧν ἧς ἂν ἐθέλητε, γείτονες ἔσεσθε, ἵνα τὴν ἐρεθίζουσαν ὑμᾶς ὄψιν τε καὶ μνήμην ἀφῆτε τῶν νῦν ἐνοχλούντων κακῶν, ὅταν ἐς τὴν θάλασσαν κενὴν σκαφῶν ἀφορῶντες ἀναμιμνήσκησθε τοῦ πλήθους ὧν εἴχετε νεῶν, καὶ λαφύρων ὅσων ἐφέρετε, καὶ ἐς οἵους γε τοὺς λιμένας κατήγεσθε σοβαροί, καὶ τὰ νεώρια καὶ τὰ τῶν σκευῶν ταμιεῖα ἐνεπίμπλατε. τί δὲ αἱ ἐν τοῖς τείχεσιν ὑποδοχαὶ στρατοπέδων τε καὶ ἵππων καὶ ἐλεφάντων; τί δὲ θησαυροὶ τούτοις παρῳκοδομημένοι; τί ταῦτα μνημεῖα ὑμῖν ἐστίν; ἢ τί ἄλλο πλὴν ὀδύνη, καὶ ἐρέθισμα ἐπανελθεῖν ἐς αὐτά, εἴ ποτε δύναισθε; πάθος ἐστίν ἀνθρώπειον τοῖς μεμνημένοις τῆς ποτὲ τύχης, ἐλπίζειν τὴν τύχην ἐπανελεύσεσθαι, φάρμακον δὲ κακῶν ἀκεστήριον λήθη, ἧς οὐκ ἔνι μετασχεῖν ὑμῖν, ἢν μὴ τὴν ὄψιν ἀπόθησθε. καὶ τούτου σαφέστατος ἔλεγχος, ὅτι πολλάκις συγγνώμης καὶ συνθηκῶν τυχόντες παρεσπονδήσατε. εἰ μὲν οὖν ἔτι τῆς ἀρχῆς ἐφίεσθε καὶ δυσμεναίνετε ἡμῖν ὡς ἀφῃρημένοι καὶ καιροφυλακεῖτε, δεῖ τῆσδε τῆς πόλεως ὑμῖν καὶ λιμένων τοιῶνδε καὶ νεωρίων καὶ τειχῶν ἐς στρατοπέδου τρόπον εἰργασμένων. καὶ τί ἔτι φειδόμεθα ἐχθρῶν εἰλημμένων; εἰ δὲ τῆς μὲν ἀρχῆς ἀπέστητε καθαρῶς, οὐ λόγῳ μᾶλλον ἢ γνώμῃ, μόνα δ’ ἐξῄρησθε Λιβύης ἃ ἔχετε, καὶ τάδε ἀπροφασίστως συνέθεσθε ἡμῖν, φέρετε, καὶ ἔργῳ ταῦτα ἐπιδείξατε, ἐς μὲν Λιβύην, ἣν ἔχετε, ἀνοικισάμενοι, τῆς δὲ θαλάσσης ἐκστάντες, ἧς ἀπέστητε.", "st": "9.88"}, {"sp": "N", "t": "“μηδ’ ὑποκρίνεσθε ἐλεεῖν ἱερὰ καὶ ἑστίας καὶ ἀγορὰς καὶ τάφους· ὧν τάφοι μὲν ἔστων ἀκίνητοι, καὶ ἐναγίζετε αὐτοῖς ἐπερχόμενοι καὶ τοῖς ἱεροῖς θύειν εἰ θέλετε ἐπιόντες, τὰ δὲ λοιπὰ καθέλωμεν. οὐ γὰρ καὶ νεωρίοις θύετε, οὐδὲ ἐναγίζετε τείχεσιν. ἑστίας δὲ καὶ ἱερὰ ἄλλα καὶ ἀγορὰς ἔνι καὶ μετελθόντας ἐργάσασθαι, καὶ ταχὺ κἀκεῖνα ὑμῖν ἔσται πάτρια, ᾧ λόγῳ καὶ τὰ ἐν Τύρῳ καταλιπόντες ἠλλάξασθε Λιβύην, τά τε ἐπίκτητα ὑμῖν τότε γενόμενα νῦν πάτρια τίθεσθε. βραχεῖ τε λόγῳ μάθοιτε ἂν ὡς οὐχ ὑπὸ δυσμενείας ἀλλ’ ἐπὶ βεβαίῳ τε ὁμονοίᾳ καὶ ἀμεριμνίᾳ κοινῇ τάδε προστάσσομεν, εἰ ἀναμνησθείητε ὅτι καὶ Ἄλβην ἡμεῖς, οὐκ ἐχθρὰν ἀλλὰ μητρόπολιν οὖσαν, οὐδὲ δυσμεναίνοντες ἀλλ’ ὡς ἄποικοι προτιμῶντες, ἐπὶ συμφέροντι κοινῷ μετῳκίσαμεν ἐς Ῥώμην, καὶ ἐλυσιτέλησεν ἀμφοτέροις. ἀλλ’ εἰσὶ γὰρ ὑμῖν ἔτι χειρώνακτες πολλοὶ θαλασσοβίωτοι. καὶ τούτου πεφροντικαμεν, ὡς ἂν εὐκόλως ἐπιμιγνύοισθε τῇ θαλάσσῃ, καὶ τὴν τῶν ὡραίων διάθεσίν τε καὶ ἀντίληψιν ἔχοιτε εὐμαρῆ· οὐ γὰρ μακρὰν ὑμᾶς ἀπὸ θαλάσσης, ἀλλ’ ὀγδοήκοντα σταδίους ἀναδραμεῖν κελεύομεν. ἡμεῖς δ’ ταῦτα προστάσσοντες ὑμῖν ἑκατὸν τῆς θαλάσσης ἀπέχομεν. χωρίον δὲ ὑμῖν δίδομεν, ὃ θέλετε, ἐπιλέξασθαι, καὶ μετελθοῦσιν αὐτονόμοις εἶναι. τοῦτο δ’ ἐστὶν ὃ προυλέγομεν, αὐτόνομον ἐάσειν Καρχηδόνα, εἰ πείθοιτο ἡμῖν· Καρχηδόνα γὰρ ὑμᾶς, οὐ τὸ ἔδαφος ἡγούμεθα.”", "st": "9.89"}, {"sp": "N", "t": "τοσαῦτα εἰπὼν ὁ Κηνσωρῖνος ἡσύχασεν. καὶ τῶν Καρχηδονίων ὑπ’ ἐκπλήξεως οὐδὲν ἀποκριναμένων ἐπεῖπεν· “ἃ μὲν ἔδειπείθοντα καὶ παρηγοροῦντα εἰπεῖν, εἴρηται· τὸ δὲ πρόσταγμα τῆς βουλῆς δεῖ γενέσθαι καὶ αὐτίκα γενέσθαι. ἄπιτε οὖν· ἐστὲ γὰρ ἔτι πρέσβεις.” ὃ μὲν εἶπεν οὕτως, οἱ δ’ ἐξωθούμενοι πρὸς τῶν ὑπηρετῶν, καὶ τὸ μέλλον ὑπὸ Καρχηδονίων ἔσεσθαι προορῶντες, ᾔτησαν αὖθις εἰπεῖν. καὶ ἐσαχθέντες ἔφασαν “τὸ μὲν ἀπαραίτητον τοῦ κελεύσματος ὁρῶμεν· οὐ γὰρ οὐδὲ πρεσβεῦσαι δίδοτε ἐς Ῥώμην. ἡμεῖς δ’ ἐπανελεύσεσθαι μὲν πρὸς ὑμᾶς οὐκ ἐλπίζομεν, ἀλλ’ ὑπὸ Καρχηδονίων ἔτι λέγοντες ἀπολεῖσθαι· δεόμεθα δ’ ὑμῶν, οὐχ ὑπὲρ ἑαυτῶν (ἐσμὲν γὰρ πάντα παθεῖν ἕτοιμοι) ἀλλ’ ὑπὲρ αὐτῆς ἔτι Καρχηδόνος, εἰ δύναιτο καταπλαγεῖσα τὰς συμφορὰς ὑποστῆναι. περιστήσατε αὐτῇ τὰς ναῦς ἕως ὁδεύοντες ἄπιμεν, ἵνα καὶ θεωροῦντες καὶ ἀκούοντες ὧν προσετάξατε ἐνέγκωσιν, ἂν ἄρα δύνωνται. ἐς τοῦτο δ’ ἡμῖν ἀνάγκης ἀφῖκται καὶ τύχης ὡς αὐτοὶ παρακαλεῖν ὑμᾶς τὰς ναῦς ἐπάγειν ἐπὶ τὴν πατρίδα.” οἱ μὲν δὴ τοσαῦτα εἰπόντες ἀπῄεσαν, καὶ ὁ Κηνσωρῖνος πεντήρεσιν εἴκοσι παραπλεύσας ἀνεκώχευε παρὰ τὴν πόλιν· τῶν δὲ πρέσβεων οἱ μὲν ἐκ τῆς ὁδοῦ διεδίδρασκον, οἱ δὲ πλέονες ἐπορεύοντο σιγῇ.", "st": "9.90"}, {"sp": "N", "t": "Καρχηδόνιοι δ’ οἱ μὲν ἀπὸ τῶν τειχῶν ἐς τοὺς πρέσβεις, ὁπότε ἥξουσιν, ἀφεώρων καὶ βραδύνουσιν αὐτοῖς ἤχθοντο, καὶ τὰς κόμας ἐτίλλοντο· οἱ δ’ ὑπήντων ἔτι προσιοῦσιν, οὐκ ἀναμένοντες ἀλλ’ ἐπειγόμενοι μαθεῖν. σκυθρωποὺς δὲ ὁρῶντες ἐτύπτοντο τὰ μέτωπα, καὶ διηρώτων, οἱ μὲν ὁμοῦ πάντας οἱ δ’ ἕκαστον, ὡς εἶχέ τις φιλίας ἢ γνώσεως ἐς αὐτόν, ἐπιστρέφων τε καὶ πυνθανόμενος. ὡς δὲ οὐδεὶς ἀπεκρίνετο, ἀνῴμωζον ὡς ἐπ’ ὀλέθρῳ σαφεῖ. καὶ οἱ ἐπὶ τοῦ τείχους ἀκούοντες συνανῴμωζον αὐτοῖς, οὐκ εἰδότες μὲν οὐδέν, ὡς δ’ ἐπὶ σαφεῖ καὶ μεγάλῳ κακῷ. περὶ δὲ τὰς πύλας ὀλίγου μὲν αὐτοὺς καὶ συνεπάτουν, ἐπιπίπτοντες ἀθρόοι, ὀλίγου δὲ καὶ διέσπασαν, εἰ μὴ τοσόνδε ἔφασαν, ὅτι χρὴ τῇ γερουσίᾳ πρότερον ἐντυχεῖν. τότε γὰρ οἱ μὲν διίσταντο αὐτοῖς, οἱ δὲ καὶ ὡδοποίουν ἐπιθυμίᾳ τοῦ θᾶσσον μαθεῖν. ὡς δὲ ἐς τὸ βουλευτήριον ἐσῆλθον, ἡ μὲν γερουσία τοὺς ἄλλους μετεστήσατο, καὶ μόνοι συνήδρευον ἐφ’ ἑαυτῶν, τὸ δὲ πλῆθος ἔξω περιειστήκεσαν. οἱ δὲ πρέσβεις ἀπήγγελλον πρῶτα μὲν τὸ κέλευσμα τῶν ὑπάτων· καὶ εὐθὺς ἦν βοὴ τῆς γερουσίας, καὶ ὁ δῆμος ἔξω συνεβόα. ὡς δὲ ἐπῆγον οἱ πρέσβεις ὅσα ἀντέλεξαν δικαιολογούμενοι καὶ δεόμενοι καὶ ἐς Ῥώμην πρεσβεῦσαι παραιτούμενοι, αὖθις ἦν τῆς βουλῆς σιγὴ βαθεῖα, τὸ τέλος μαθεῖν περιμενούσης, καὶ ὁ δῆμος αὐτῇ συνεσιώπα. ὡς δ’ ἔμαθον ὅτι μηδὲ πρεσβεύειν ἐπέτρεψαν, ἠλάλαξαν ἐξαίσιον ὀδυρόμενοι, καὶ ὁ δῆμος ἐσέδραμεν ἐς αὐτούς.", "st": "9.91"}, {"sp": "N", "t": "καὶ ἀπὸ τοῦδε ἦν οἶστρος ἄλογός τε καὶ μανιώδης, οἷον ἐν τοῖς βακχείοις πάθεσί φασι τὰς μαινάδας ἀλλόκοτα καινουργεῖν. οἱ μὲν τῶν βουλευτῶν τοὺς περὶ τῶν ὁμήρων ἐσηγησαμένους ὡς ἐξάρχους τῆς ἐνέδρας ᾐκίζοντο καὶ διέσπων, οἱ δὲ τοὺς συμβουλεύσαντας περὶ τῶν ὅπλων. οἱ δὲ τοὺς πρέσβεις κατέλευον ὡς κακῶν ἀγγέλους, οἱ δὲ καὶ περιέσυρον ἀνὰ τὴν πόλιν. ἕτεροι δὲ τοὺς Ἰταλούς, οἳ ἔτι παρ’ αὐτοῖς ὡς ἐν αἰφνιδίῳ καὶ ἀκηρύκτῳ κακῷ ἦσαν, ἐλυμαίνοντο ποικίλως, ἐπιλέγοντες ὁμήρων πέρι καὶ ὅπλων καὶ ἀπάτης ἀμύνεσθαι. οἰμωγῆς τε ἅμα παὶ ὀργῆς καὶ δέους καὶ ἀπειλῆς ἡ πόλις ἐνεπέπληστο, καὶ ἐν ταῖς ὁδοῖς ἀνεκάλουν τὰ φίλτατα, καὶ ἐς τὰ ἱερὰ ὡς ἄσυλα κατέφευγον, καὶ τοὺς θεοὺς ὠνείδιζον ὡς οὐδὲ σφίσιν αὐτοῖς ἐπικουρῆσαι δυναμένους. ἕτεροι δὲ ἐς τὰς ὁπλοθήκας ἰόντες ἔκλαιον, ὁρῶντες κενάς· οἱ δ’ ἐς τὰ νεώρια καταθέοντες ὠδύροντο τὰς ναῦς ὡς ἀπίστοις ἀνδράσιν ἐκδεδομένας. καὶ τὰ ὀνόματά τινες τῶν ἐλεφάντων ἀνεκάλουν ὡς ἔτι παρόντων, τούς τε προγόνους καὶ σφᾶς αὐτοὺς ἐλοιδόρουν, ὡς δέον μήτε ναῦς μήτε ἐλέφαντας μήτε φόρους μήτε τὰ ὅπλα παραδόντας ἀποθανεῖν σὺν τῇ πατρίδι ὡπλισμένῃ. μάλιστα δ’ αὐτοὺς ἐς ὀργὴν ἀνέκαιον αἱ μητέρες αἱ τῶν ὁμήρων, οἷά τινες ἐκ τραγῳδίας ἐρινύες ἐντυγχάνουσαι μετ’ ὀλολυγῆς ἑκάστῳ, καὶ τὴν ἔκδοσιν τῶν παίδων προφέρουσαι καὶ τὴν ἑαυτῶν ἀπόρρησιν· ἐπεγέλων τε αὐτοῖς ὡς θεῶν ἀμυνομένων αὐτοὺς ἀντὶ τῶν παίδων. ὀλίγον δ’ ὅσον ἐσωφρόνει, τὰς πύλας ἀπέκλειε, καὶ τὸ τεῖχος λίθων ἀντὶ καταπελτῶν ἐπλήρουν.", "st": "9.92"}, {"sp": "N", "t": "ἡ δὲ βουλὴ πολεμεῖν μὲν ἐψηφισατο αὐτῆς ἡμέρας, καὶ τοὺς δούλους ἐκήρυξεν ἐλευθέρους εἶναι, στρατηγοὺς δὲ εἵλοντο τῶν μὲν ἔξω πράξεων Ἀσδρούβαν, ᾧ θάνατος ἐπικήρυκτος ἦν, ἔχοντα δισμυρίων ἤδη σύνοδον ἀνδρῶν· καί τις ἐξέτρεχεν αὐτοῦ δεησόμενος μὴ μνησικακῆσαι τῇ πατρίδι ἐνἐς χάτῳ κινδύνου, μηδέ, ὧν ὑπ’ ἀνάγκης ἠδικήθη Ῥωμαίων δέει, νῦν ἀναφέρειν. ἐντὸς δὲ τειχῶν ᾑρέθη στρατηγὸς ἕτερος Ἀσδρούβας, θυγατριδοῦς Μασσανάσσου. ἔπεμψαν δὲ καὶ ἐς τοὺς ὑπάτους, αἰτοῦντες αὖθις ἡμερῶν τριάκοντα ἀνοχάς, ἵνα πρεσβεύσειαν ἐς Ῥώμην. ἀποτυχόντες δὲ καὶ τότε, ἐπὶ θαυμαστῆς ἐγίγνοντο μεταβολῆς τε καὶ τόλμης ὁτιοῦν παθεῖν μᾶλλον ἢ τὴν πόλιν ἐκλιπεῖν. ταχὺ δὲ καὶ θάρσους ἐκ τῆς μεταβολῆς ἐπίμπλαντο. καὶ δημιουργεῖα μὲν τὰ δημόσια τεμένη καὶ ἱερὰ πάντα, καὶ εἴ τι ἄλλο εὐρύχωρον ἦν, ἐγένετο· εἰργάζοντο δὲ ὁμοῦ ἄνδρες τε καὶ γυναῖκες ἡμέρας τε καὶ νυκτός, μὴ ἀναπαυόμενοι καὶ σῖτον αἱρούμενοι παρὰ μέρος, ἐπὶ ὅρῳ τακτῷ, θυρεοὺς ἑκατὸν ἡμέρας ἑκάστης καὶ ξίφη τριακόσια καὶ καταπελτικὰ βέλη χίλια, σαυνία δὲ καὶ λόγχας πενκακοσίας, καὶ καταπέλτας ὅσους δυνηθεῖεν. ἐς δὲ τὰς ἐπιτάσεις αὐτῶν ἀπέκειραν τὰς γυναῖκας, τριχῶν ἑτέρων ἀπορία.", "st": "9.93"}, {"sp": "N", "t": "καὶ οἱ μὲν ἐν τούτῳ σπουδῆς καὶ παρασκευῆς ἦσαν, οἱ δ’ ὕπατοι τάχα μέν τι καὶ ὄκνῳ, μὴ εὐθὺς ἐπιχειρεῖν ἐς ἔργον ἀλλόκοτον, ἅμα δὲ καὶ τὴν πόλιν ἄνοπλον οὖσαν λήψεσθαι κατὰ κράτος, ὅτε θέλοιεν, ἡγούμενοι, διέμελλον ἔτι καὶ ἐνδώσειν αὐτοὺς ἐνόμιζον ἐκ τῆς ἀπορίας, οἷον ἐν τοῖς δυσχερέσι γίγνεσθαι φιλεῖ, εὐθὺς μὲν ἀντιλέγειν, προϊόντος δὲ χρόνου καὶ λογισμοῦ φόβον ἅπτεσθαι τῶν ἀπειθούντων. ἃ καὶ τῶν Καρχηδονίων τις αὐτῶν, εἰκάσας σφῶν ἤδη τὸ δέος ἅπτεσθαι, ἐτόλμησεν ὡς ἐπὶ δή τι ἄλλο παρελθὼν ἐς τὸ μέσον εἰπεῖν, ὅτι χρὴ τῶν κακῶν ἐπιλέγεσθαι τὰ μετριώτερα, ὄντας ἀνόπλους, οὕτω σαφῶς εἰπὼν τὰ τῆς γνώμης. Μασσανάσσης δὲ ἤχθετο Ῥωμαίοις, καὶ ἔφερε βαρέως ὅτι τὴν Καρχηδονίων δύναμιν αὐτὸς ἐς γόνυ βαλὼν ἄλλους ἑώρα τῷ ἐπιγράμματι αὐτῆς ἐπιτρέχοντάς τε καὶ οὐ κοινώσαντας αὐτῷ πρὶν ἐπελθεῖν, ὡς ἐν τοῖς πάλαι πολέμοις ἐποίουν. ὅμως δ’ αὐτοῦ τῶν ὑπάτων ἀποπειρωμένων καὶ καλούντων ἐπὶ συμμαχίαν, ἔφη τὴν συμμαχίαν πέμψειν, ὅταν αἴσθηται δεομένων. καὶ μετ’ οὐ πολὺ πέμψας ἤρετο εἴ τινος ἤδη δέονται. οἱ δὲ οὐ φέροντες αὐτοῦ τὸ σοβαρόν, ἤδη δέ τι καὶ ἀπιστοῦντες ὡς δυσμεναίνοντι, ἀπεκριναντο προσπέμψειν ὅτε δεηθεῖεν. περὶ δὲ ἀγορᾶς τῷ στρατῷ καὶ πάνυ ἐφρόντιζον, ἐκ μόνης ἔχοντες Ἀδρυμητοῦ καὶ Λέπτεως καὶ Θάψου καὶ Ἰτύκης καὶ Ἀχόλλης· τὰ γὰρ δὴ λοιπὰ Λιβύης ἦν ἔτι πάντα ὑπὸ Ἀσδρούβᾳ, ὅθεν ἐκεῖνος ἀγορὰν ἐς Καρχηδόνα ἔπεμπεν. ὀλίγων δ’ ἐς ταῦτα διατριφθεισῶν ἡμερῶν, οἱ μὲν ὕπατοι προσῄεσαν ἄμφω τῇ πόλει τῶν Καρχηδονίων ἐς μάχην ἐσκευασμένοι, καὶ ἐπεχείρουν.", "st": "9.94"}, {"sp": "N", "t": "ἦν δὲ ἡ πόλις ἐν μυχῷ κόλπου μεγίστου, χερρονήσῳ τι μάλιστα προσεοικυῖα. αὐχὴν γὰρ αὐτὴν ἀπὸ τῆς ἠπείρου διεῖργεν, εὖρος ὢν πέντε καὶ εἴκοσι σταδίων· ἀπὸ δὲ τοῦ αὐχένος ταινία στενὴ καὶ ἐπιμήκης, ἡμισταδίου μάλιστα τὸ πλάτος, ἐπὶ δυσμὰς ἐχώρει, μέση λίμνης τε καὶ τῆς θαλάσσης … ἁπλῷ τείχει περίκρημνα ὄντα, τὰ δὲ πρὸς μεσημβρίαν ἐς ἤπειρον, ἔνθα καὶ ἡ Βύρσα ἦν ἐπὶ τοῦ αὐχένος, τριπλῷ τείχει. τούτων δ’ ἕκαστον ἦν ὕψος μὲν πηχῶν τριάκοντα, χωρὶς ἐπάλξεών τε καὶ πύργων, οἳ ἐκ διπλέθρου διαστήματος αὐτοῖς τετρώροφοι περιέκειντο, βάθος δὲ ποδῶν τριάκοντα, διώροφον δ’ ἦν ἑκάστου τείχους τὸ ὕψος, καὶ ἐν αὐτῷ κοίλῳ τε ὄντι καὶ στεγανῷ κάτω μὲν ἐστάθμευον ἐλέφαντες τριακόσιοι, καὶ θησαυροὶ παρέκειντο αὐτοῖς τῶν τροφῶν, ἱπποστάσια δ’ ὑπὲρ αὐτοὺς ἦν τετρακισχιλίοις ἵπποις, καὶ ταμιεῖα χιλοῦ τε καὶ κριθῆς, ἀνδράσι τε καταγωγαὶ πεζοῖς μὲν ἐς δισμυρίους, ἱππεῦσι δὲ ἐς τετρακισχιλίους. τοσήδε παρασκευὴ πολέμου διετέτακτο σταθμεύειν ἐν τοῖς τείχεσι μόνοις. γωνία δ’ ἣ παρὰ τὴν γλῶσσαν ἐκ τοῦδε τοῦ τείχους ἐπὶ τοὺς λιμένας περιέκαμπτεν, ἀσθενὴς ἦν μόνη καὶ ταπεινή, καὶ ἠμέλητο ἐξ ἀρχῆς.", "st": "9.95"}, {"sp": "N", "t": "οἱ δὲ λιμένες ἐς ἀλλήλους διεπλέοντο, καὶ ἔσπλους ἐκ πελάγους ἐς αὐτοὺς ἦν ἐς εὖρος ποδῶν ἑβδομήκοντα, ὃν ἁλύσεσιν ἀπέκλειον σιδηραῖς. ὁ μὲν δὴ πρῶτος ἐμπόροις ἀνεῖτο, καὶ πείσματα ἦν ἐν αὐτῷ πυκνὰ καὶ ποικίλα· τοῦ δ’ ἐντὸς ἐν μέσῳ νῆσος ἦν, καὶ κρηπῖσι μεγάλαις ἥ τε νῆσος καὶ ὁ λιμὴν διείληπτο. νεωρίων τε ἔγεμον αἱ κρηπῖδες αἵδε ἐς ναῦς διακοσίας καὶ εἴκοσι πεποιημένων, καὶ ταμιείων ἐπὶ τοῖς νεωρίοις ἐς τριηρετικὰ σκεύη. κίονες δ’ ἑκάστου νεωσοίκου προῦχον Ἰωνικοὶ δύο, ἐς εἰκόνα στοᾶς τὴν ὄψιν τοῦ τε λιμένος καὶ τῆς νήσου περιφέροντες. ἐπὶ δὲ τῆς νήσου σκηνὴ ἐπεποίητο τῷ ναυάρχῳ, ὅθεν ἔδει καὶ τὸν σαλπικτὴν σημαίνειν, καὶ τὸν κήρυκα προλέγειν, καὶ τὸν ναύαρχον ἐφορᾶν. ἔκειτο δ’ ἡ νῆσος κατὰ τὸν ἔσπλουν, καὶ ἀνετέτατο ἰσχυρῶς, ἵνα ὅ τε ναύαρχος τὰ ἐκ πελάγους πάντα ἐφορᾷ, καὶ τοῖς ἐπιπλέουσιν ἀφανὴς ἡ τῶν ἔνδον ᾖ ὄψις ἡ ἀκριβής. οὐ μὴν οὐδὲ τοῖς ἐσπλεύσασιν ἐμπόροις εὐθὺς ἦν τὰ νεώρια σύνοπτα· τεῖχός τε γὰρ αὐτοῖς διπλοῦν περιέκειτο, καὶ πύλαι, αἳ τοὺς ἐμπόρους ἀπὸ τοῦ πρώτου λιμένος ἐς τὴν πόλιν ἐσέφερον οὐ διερχομένους τὰ νεώρια.", "st": "9.96"}, {"sp": "N", "t": "οὕτω μὲν εἶχεν ἡ πόλις ἡ Καρχηδονίων ἡ τότε, οἱ δ’ ὕπατοι διελόμενοι τὸ ἔργον ᾔεσαν ἐπὶ τοὺς πολεμίους, Μανίλιος μὲν ἀπὸ τῆς ἠπείρου κατὰ τὸν αὐχένα, ἐγχώσων τε τὴν τάφρον καὶ βραχὺ ἐπιτείχισμα τὸ ἐπ’ αὐτῇ βιασόμενος, καὶ ἐπ’ ἐκείνῳ τὰ ὑψηλὰ τείχη· Κηνσωρῖνος δὲ κλίμακας ἔκ τε γῆς καὶ νεῶν ἐπέφερε κατὰ τὴν εὐτελῆ τοῦ τείχους γωνίαν. ἄμφω δ’ ὡς ἀνόπλων κατεφρόνουν, ἕως ἐντυχόντες ὅπλοις τε καινοῖς καὶ ἀνδρῶν προθυμίᾳ παραλόγῳ κατεπλάγησαν καὶ ὑπεχώρουν. καὶ εὐθὺς αὐτοῖς τοῦτο πρῶτον ἀντεκεκρούκει, ἐλπίσασιν ἀμαχὶ λήψεσθαι τὴν πόλιν. ὡς δὲ καὶ αὖθις ἐπεχείρουν καὶ αὖθις ἀπετύγχανον, τὰ μὲν τῶν Καρχηδονίων φρονήματα ἐπῇρτο, οἱ δ’ ὕπατοι δεδιότες Ἀσδρούβαν ὄπισθεν σφῶν ὑπὲρ τὴν λίμνην οὐκ ἐκ μακροῦ διαστήματος ἐστρατοπεδευμένον, ὠχύρουν καὶ αὐτοὶ δύο στρατόπεδα, Κηνσωρῖνος μὲν ἐπὶ τῆς λίμνης ὑπὸ τοῖς τείχεσι τῶν πολεμίων, Μανίλιος δ’ ἐν τῷ αὐχένι τῆς ἐς τὴν ἤπειρον ὁδοῦ. ὡς δὲ αὐτοῖς ἐγήγερτο τὰ στρατόπεδα, ὁ Κηνσωρῖνος ἐπὶ ὕλῃ ἐς μηχανὰς διέπλευσε διὰ τῆς λίμνης· καὶ ἀπέβαλεν ὑλοτόμων ἐς πεντακοσίους ἄνδρας ὅπλα τε πολλά, Ἱμίλκωνος αἰφνίδιον αὐτῷ, τοῦ Καρχηδονίων ἱππάρχου, προσπεσόντος, ᾧ Φαμέας ἐπώνυμον ἦν. κομίσας δ’ ὅμως τινὰ ὕλην, μηχανὰς ἐποίησε καὶ κλίμακας. καὶ πάλιν ἐπεχείρουν ἄμφω τῇ πόλει, καὶ ἀπετύγχανον ὁμοίως. Μανίλιος μὲν οὖν μικρὸν ἔτι προσκαμὼν καὶ μόλις τι τοῦ προτειχίσματος καταβαλών, ἀπέγνω μηδὲ ἐπιχειρεῖν ἔτι ταύτῃ·", "st": "9.97"}, {"sp": "N", "t": "Κηνσωρῖνος δὲ χώσας τι τῆς λίμνης παρὰ τὴν ταινίαν, ἵνα εὐρύτερον εἴη, δύο μηχανὰς κριοφόρους ἐπῆγε μεγάλας, τὴν μὲν ὠθουμένην ἑξακισχιλίοις πεζοῖς, ἡγουμένων τῶν χιλιάρχων, τὴν δὲ ὑπὸ τῶν ἐρετῶν, ἡγουμένων καὶ τοῖσδε ναυάρχων. φιλονεικίας δ’, ὡς ἐν ἴσῳ καὶ ὁμοιῳ ἔργῳ, τοῖς τε ὑπηρέταις καὶ τοῖς ἄρχουσιν αὐτῶν γενομένης, συνέπεσέ τι τοῦ τείχους, καὶ τὰ ἐντὸς ἤδη κατεφαίνετο. Καρχηδόνιοι δὲ καὶ ὣς αὐτοὺς ἀπωσάμενοι, τὰ πεσόντα νυκτὸς ᾠκοδόμουν. οὐκ ἀρκούσης δ’ ἐς τὸ ἔργον αὐτοῖς τῆς νυκτός, δεδιότες περὶ τῷ ἤδη γεγονότι, μὴ καὶ τοῦτο μεθ’ ἡμέραν αἱ Ῥωμαίων μηχαναὶ νεότευκτον καὶ ὑγρὸν ἔτι καταβάλοιεν, ἐξέδραμον ἐπὶ τὰ μηχανήματα τῶν πολεμίων, οἱ μὲν σὺν ὅπλοις, οἱ δὲ γυμνοὶ λαμπάδας ἡμμένας ἔχοντες, καὶ ἐνέπρησαν μὲν οὐχ ὅλα (οὐ γὰρ ἔφθασαν Ῥωμαίων ἐπιδραμόντων), ἀχρεῖα δ’ ὅλα ποιήσαντες ἀνεχώρουν. ἅμα δ’ ἡμέρᾳ Ῥωμαίοις ἐπέπεσεν ὁρμὴ διὰ τοῦ πεσόντος οὔπω τελέως ἐγηγερμένου βιάσασθαι καὶ ἐσδραμεῖν· καὶ γάρ τι πεδίον ἐντὸς ἐφαίνετο εὐφυὲς ἐς μάχην, ἐν ᾧ τοὺς ἐνόπλους ἔστησαν οἱ Καρχηδόνιοι κατὰ μετώπου, τοὺς δ’ ἀνόπλους αὐτοῖς ἐπέταξαν σὺν λίθοις ὀπίσω καὶ ξύλοις, ἑτέρους τε πολλοὺς διαθέντες ἐπὶ τῶν περικειμένων οἰκιῶν ἀνέμενον τοὺς ἐπερχομένους ἐσδραμεῖν. οἱ δ’ ἔτι μᾶλλον ἠρεθίζοντο ὡς ὑπὸ γυμνῶν ἀνδρῶν καταφρονούμενοι, καὶ θρασέως ἐπεπήδων. Σκιπίων δέ, ὃς μετ’ ὀλίγον εἷλε Καρχηδόνα καὶ παρὰ τοῦτο Ἀφρικανὸς ἐπεκλήθη, χιλιαρχῶν τότε ὤκνει, καὶ τοὺς ἑαυτοῦ λόχους ἐς πολλὰ διελών, καὶ στήσας ἐκ διαστήματος ἐπὶ τοῦ τειχίου, κατιέναι μὲν ἐς τὴν πόλιν οὐκ εἴα, τοὺς δὲ ἐσελθόντας ἐξωθουμένους ὑπὸ τῶν Καρχηδονίων πάντοθεν αὐτοῖς ἐπιπεσόντων ὑπεδέχετο καὶ περιέσωζεν. καὶ τοῦτο πρῶτον αὐτὸν ἐπὶ δόξης ἐποίησεν, εὐβουλότερον τοῦ στρατηγοῦ φανέντα.", "st": "9.98"}, {"sp": "N", "t": "κυνὸς δ’ ἦν ἐπιτολή, καὶ τὸ Κηνσωρίνου στρατόπεδον ἐνόσει, σταθμεῦον ἐπὶ λίμνῃ σταθεροῦ καὶ βαρέος ὕδατος καὶ ὑπὸ τείχεσι μεγίστοις, οὐ καταπνεόμενον ἐκ τῆς θαλάσσης. ὅθεν ὁ Κηνσωρῖνος ἐς τὴν θάλασσαν ἀπὸ τῆς λίμνης μετεστρατοπέδευσεν. καὶ οἱ Καρχηδόνιοι, ὅτε γίγνοιτο πνεῦμα ἐς τοὺς Ῥωμαίους ἐπίφορον, σκάφας φρυγάνων καὶ στυππίου εἷλκον ὑπὸ τοῖς τείχεσιν, οὐ καθορώμενοι τοῖς πολεμίοις, ἀπὸ κάλων· εἰ δὲ ἐπικάμπτοντες ἔμελλον γενήσεσθαι καταφανεῖς, θεῖον αὐταῖς καὶ πίσσαν ἐπιχέοντες ἀνέτεινον τὰ ἱστία, καὶ πλήσαντες ἀνέμου πῦρ ἐνέβαλον ἐς τὰ σκάφη. τὰ δὲ τῷ τε ἀνέμῳ καὶ τῇ ῥοπῇ τοῦ πυρὸς ἐς τὰς Ῥωμαίων ναῦς ἐωθεῖτο καὶ ἐλυμαίνετο καὶ ὀλίγου τὸν στόλον κατέφλεξεν. μετὰ δὲ οὐ πολὺ Κηνσωρῖνος μὲν ἐς Ῥώμην ᾤχετο ἀρχαιρεσιάσων, οἱ δὲ Καρχηδόνιοι τῷ Μανιλίῳ θρασύτερον ἐπέκειντο· καὶ νυκτός, οἱ μὲν ὅπλα ἔχοντες οἱ δὲ γυμνοί, σανίδας φέροντες ἐπετίθεσαν τῇ κατὰ σφᾶς τάφρῳ τοῦ Μανιλίου, καὶ τὸ χαράκωμα διέσπων. ἀπορουμένων δὲ ὡς ἐν νυκτὶ τῶν ἔνδον, ὁ Σκιπίων ἐξέδραμε σὺν ἱππεῦσιν ἐκ τοῦ στρατοπέδου κατὰ πύλας ἄλλας, ἔνθα οὐδεὶς πόλεμος, καὶ περιδραμὼν τοὺς Καρχηδονίους κατεφόβησεν. οἱ δὲ ἀνεχώρουν ἐς τὴν πόλιν. καὶ δεύτερον ὁ Σκιπίων ἐδόκει τῷδε τῷ ἔργῳ περισῶσαι Ῥωμαίους, ἐν νυκτὶ θορυβουμένους.", "st": "9.99"}, {"sp": "N", "t": "ὁ δὲ Μανίλιος τὸ μὲν στρατόπεδον ἔτι μᾶλλον ὠχύρου, τεῖχός τε ἀντὶ χάρακος αὐτῷ περιτιθεὶς καὶ ἐπίνειον φρούριον ἐγείρων ἐπὶ τῆς θαλάσσης διὰ τὴν καταπλέουσαν ἀγοράν· τραπεὶς δ’ ἐς τὰ μεσόγεια μυρίοις πεζοῖς καὶ ἱππεῦσι δισχιλίοις τὴν χώραν ἐπόρθει, ξυλευόμενός τε καὶ χορτολογῶν καὶ ἀγορὰν συλλέγων. ἡγεῖτο δ’ ἀεὶ τῶν προνομευόντων χιλίαρχος ἕτερος παρ’ ἕτερον. καὶ Φαμέας ὁ ἵππαρχος ὁ τῶν Λιβύων, νέος τε ὢν ἔτι καὶ θρασύτερος ἐς μάχας, καὶ ἵπποις χρώμενος μικροῖς καὶ ταχέσι, καὶ ποηφαγοῦσιν ὅτε μηδὲν εἴη, καὶ φέρουσι δίψος, εἰ δεήσειε, καὶ λιμόν, ὑποκρυπτόμενος ἐν λόχμαις ἢ φάραγξιν, ὅπῃ τι ἀμελούμενον ἴδοι, ἐφίπτατο ἐξ ἀφανοῦς ὥς τις ἀετός, καὶ λυμηνάμενος ἀπεπήδα· ὅτε δὲ Σκιπίων ἄρχοι, οὐδαμοῦ οὐδ’ ἐπεφαίνετο. ὁ γάρ τοι Σκιπίων ἀεὶ συντεταγμένους ἦγε τοὺς πεζούς, καὶ τοὺς ἱππέας τῶν ἵππων ἐπιβεβηκότας· ἔν τε ταῖς προνομαῖς οὐ πρὶν διέλυε τὴν σύνταξιν ἢ τὸ πεδίον, ὃ ἔμελλε θεριεῖν, ἱππεῦσι καὶ ὁπλίταις περιλάβοι· καὶ τότε κύκλῳ αὐτὸς ἑτέραις ἴλαις ἱππέων ἀεὶ περιῄει, καὶ τῶν θεριζόντων τὸν ἀποσκιδνάμενον ἢ ἐξιόντα τοῦ κύκλου πικρῶς ἐκόλαζεν.", "st": "9.100"}, {"sp": "N", "t": "ὅθεν οἷ Φαμέας οὐκ ἐπεχείρει μόνῳ. καὶ γιγνομένου τοῦδε συνεχῶς τὸ μὲν κλέος ηὔξετο τῷ Σκιπίωνι, οἱ δ’ ἕτεροι χιλίαρχοι κατὰ φθόνον ἐλογοποίουν ξενίαν ἐκ πατερων εἶναι Φαμέᾳ πρὸς Σκιπίωνα τὸν τοῦδε πάππον. Λιβύων δὲ τοῖς ἐς πύργους καὶ φρούρια, ἃ πολλὰ ἦν ἐν τῇ χώρᾳ, καταφυγοῦσιν οἱ μὲν ἄλλοι χιλίαρχοι σπενδόμενοι καὶ μεθιέντες ἐπετίθεντο ἀπιοῦσιν, ὁ δὲ Σκιπίων ἐς τὰ οἴκοι παρέπεμπε, καὶ ἀπὸ τοῦδε οὐ πρὶν ἢ Σκιπίωνα ἀφικέσθαι συνετίθετο οὐδείς. τοσαύτη δόξα αὐτοῦ ἀνδρείας τε πέρι καὶ πίστεως καὶ παρὰ τοῖς ἰδίοις δι’ ὀλίγου ἐγεγένητο καὶ παρὰ τοῖς πολεμίοις. ἐπανελθόντων δ’ αὐτῶν ἀπὸ τῆς προνομῆς ἐς τὸ στρατόπεδον, οἱ Καρχηδόνιοι νυκτὸς ἐπέθεντο τῷ ἐπινείῳ· καὶ θόρυβος ἦν ποικίλος, συνεπηχούντων ἐς ἔκπληξιν τῶν ἐν ἄστει Καρχηδονίων. ὁ μὲν οὖν Μανίλιος τὸν στρατὸν ἔνδον συνεῖχεν ὡς ἐν ἀγνοίᾳ τοῦ κακοῦ· ὁ δὲ Σκιπίων ἱππέων ἴλας δέκα λαβὼν ἐπῆγε μετὰ δᾴδων ἡμμένων, προειπὼν διὰ τὴν νύκτα μὴ συμπλέκεσθαι, περιτρέχειν δὲ σὺν τῷ πυρὶ καὶ τὸ πλῆθος ἐπιφαίνειν καὶ φόβον ἐμπεσουμένων παρέχειν ἀεί, μέχρι ταρασσόμενοι διχόθεν οἱ Καρχηδόνιοι κατεπλάγησαν καὶ ἐς τὴν πόλιν ἐσέφυγον. καὶ τόδε τοῖς Σκιπίωνος κατορθώμασι προσεγίγνετο. ἦν τε διὰ στόματος ἐπὶ πᾶσιν ἔργοις ὡς μόνος ἄξιος Παύλου τε τοῦ πατρὸς τοῦ Μακεδόνας ἑλόντος καὶ τῶν Σκιπιώνων, ἐς οὓς κατὰ θέσιν ἀνείληπτο.", "st": "9.101"}, {"sp": "N", "t": "Μανιλίου δὲ ἐς Νέφεριν ὁδεύοντος ἐπὶ Ασδρούβαν, ἐδυσχεραινεν ὁ Σκιπίων ὁρῶν πάντα ἀπόκρημνα καὶ φάραγγας καὶ λόχμας, καὶ τὰ ὑψηλὰ προειλημμένα. ὡς δ’ ἀπὸ σταδίων τριῶν ἐγεγένηντο τοῦ Ἀσδρούβα, καὶ ἔς τι ῥεῦμα καταβάντας ἐχρῆν ἀναβαίνειν ἐπὶ τὸν Ἀσδρούβαν, ἐνέκειτο δὴ τότε, καὶ συνεβούλευε στραφῆναι ὡς ἄλλου καιροῦ καὶ μηχανῆς ἄλλης ἐπὶ τὸν Ἀσδρουβαν δεομένους. ἀντιλεγόντων δὲ κατὰ ζῆλον αὐτοῦ τῶν ἑτέρων χιλιάρχων, καὶ μαλακίαν καὶ οὐκ εὐβουλίαν ἡγουμένων εἰ τοὺς πολεμίους ἰδόντες ἀναχωρήσουσιν, ἐν ᾧ καὶ καταφρονοῦντες φεύγουσιν ἐπικείσονται, δεύτερα τούτων ἠξίου στρατόπεδον πρὸ τοῦ ῥεύματος ἐγεῖραι, ἵν’ εἰ βιασθεῖεν, ἔχοιεν ἀναχώρησιν, οὐκ ὄντος αὐτοῖς νῦν οὐδ’ ὅποι καταφεύγοιεν. οἱ δὲ καὶ τοῦτο ἐγέλων, καὶ τὸ ξίφος τις ἠπείλησεν ἀπορρίψειν, εἰ μὴ Μανίλιος ἀλλὰ Σκιπίων ἄρχοι. διέβαινεν οὖν ὁ Μανίλιος, οὐδὲ τἄλλα ὢν ἐμπειροπόλεμος, καὶ αὐτῷ περάσαντι ὁ Ἀσδρούβας ἀπήντα, φόνος τε ἦν πολὺς ἐξ ἑκατέρων. καὶ ὁ Ἀσδρούβας ἀναδραμὼν ἐς τὸ φρούριον, ἔνθα μηδὲν παθεῖν ἐδύνατο, ἐφήδρευεν ἀπιοῦσιν ἐπιθέσθαι. οἱ δὲ σὺν μετανοίᾳ τῶν γεγονότων ἀπεχώρουν, ἄχρι μὲν ἐπὶ τὸ ῥεῦμα ἐν τάξει· δυσπόρου δ’ ὄντος τοῦ ποταμοῦ, καὶ διαβάσεων ὀλίγων τε καὶ δυσχερῶν, ἐς ἀταξίαν διῃροῦντο ὑπ’ ἀνάγκης. καὶ ὁ Ἀσδρούβας καθορῶν ἐπέκειτο λαμπρῶς τότε μάλιστα, καὶ πλῆθος ἔκτεινεν οὐδ’ ἀμυνομένων ἀλλὰ φευγόντων. ἔπεσον δὲ καὶ τῶν χιλιάρχων τρεῖς οἳ τὸν στρατηγὸν μάλιστα ἐπεπείκεσαν ἐς τὴν μάχην.", "st": "9.102"}, {"sp": "N", "t": "ὁ δὲ Σκιπίων τριακοσίους ἱππέας οὓς εἶχεν ἀμφ’ αὑτόν, καὶ ὅσους ἄλλους συναγαγεῖν ἔφθασε, διελὼν ἐς δύο τοῖς ἐχθροῖς ἐπῆγε σὺν δρόμῳ πολλῷ, παρὰ μέρος ἀκοντίζοντάς τε καὶ εὐθὺς ἀποχωροῦντας, εἶτ’ αὖθις ἐπιόντας καὶ πάλιν εὐθὺς ἀποπηδῶντας. οὕτω γὰρ εἴρητο αὐτοῖς, τοὺς ἡμίσεας ἀεὶ παρὰ μέρος ἐπιέναι καὶ ἀκοντίσαντας ἀπελαύνειν, ὥσπερ ἐν κύκλῳ περιιόντας. γιγνομένου δὲ τοῦδε πυκνοῦ, καὶ διαστήματος οὐδενὸς ὄντος, οἱ μὲν Λίβυες ἐβάλλοντο συνεχῶς, καὶ ἐπιστρέφοντες ἐς τὸν Σκιπίωνα ἧσσον τοῖς περῶσιν ἐπέκειντο, οἱ δ’ ἔφθασαν διελθεῖν τὸ ῥεῦμα. καὶ ὁ Σκιπίων ἐπ’ αὐτοῖς ἀφίππευσε βαλλόμενός τε καὶ χαλεπῶς. σπεῖραι δ’ ἐν ἀρχῇ τοῦδε τοῦ πόνου τέσσαρες ἀποσχισθεῖσαι τοῦ ῥεύματος ὑπὸ τῶν πολεμίων ἔς τινα λόφον ἀνέδραμον· καὶ αὐτὰς ὁ Ἀσδρούβας περιεκάθητο, ἀγνοούντων ἔτι Ῥωμαίων, ἕως ἐστάθμευσαν. ἐπεὶ δ’ ἔμαθον, ἠπόρουν, καὶ τοῖς μὲν ἐδόκει φεύγειν καὶ μὴ κινδυνεύειν ἅπασι δι’ ὀλίγους, ὁ δὲ Σκιπίων ἐδίδασκεν ἀρχομένων μὲν ἔργων εὐβουλίᾳ χρῆσθαι, κινδυνεύοντων δὲ ἀνδρῶν τοσῶνδε καὶ σημείων τόλμῃ παραβόλῳ. αὐτὸς δ’ ἐπιλεξάμενός τινας ἱππέων ἴλας, ἐπανοίσειν ἔφη ἐκείνους, ἢ χαίρων αὐτοῖς συναπολεῖσθαι. δύο τε ἡμερῶν σιτία φέρων εὐθὺς ὥδευε, δεδιότος πάνυ τοῦ στρατοῦ μὴ οὐδ’ αὐτὸς ἐπανέλθοι. ὡς δ’ ἧκεν ἐπὶ τὸν λόφον ἔνθα ἦσαν οἱ πολιορκούμενοι, τὸν μὲν ἄντικρυς αὐτοῦ δρόμῳ κατέλαβε, καὶ μία τοὺς δύο χαράδρα διεῖργεν, οἱ δὲ Λίβυες τότε μάλιστα ἐπέκειντο τοῖς πολιορκουμένοις καὶ πρὸς αὐτοὺς ἐνενεύκεσαν, ὡς οὔπω δυναμένου τοῦ Σκιπίωνος ἐπικουρεῖν ἐξ ὁδοιπορίας συντόνου. ὁ δὲ Σκιπίων ὡς εἶδε τὰς πέζας τῶν δύο λόφων τὴν χαράδραν περιιούσας, τὸν καιρὸν οὐ μεθῆκεν, ἀλλὰ περιέδραμε δι’ αὐτῶν ὑπὲρ τοὺς πολεμίους. οἱ δ’ ἤδη κυκλου?́μενοι διέφευγον ἀκόσμως, μεθιέντος αὐτοὺς ἀπιέναι τοῦ Σκιπίωνος ἀδεῶς, πολὺ πλείονας ὄντας.", "st": "9.103"}, {"sp": "N", "t": "οὕτω μὲν δὴ καὶ τούσδε ὁ Σκιπίων περιέσωσεν ἐν ἀπογνώσει γενομένους. καὶ αὐτὸν ἡ στρατιὰ μακρόθεν ἰδοῦσα ἐξ ἀέλπτου περισεσωσμένον τε καὶ περισώσαντα τοὺς ἑτέρους, μέγα ἠλάλαξαν ἡδόμενοι. καὶ δαιμόνιον αὐτῷ συλλαμβάνειν ἐδόξαζον, ὃ καὶ τῷ πάππῳ Σκιπίωνι προσημαίνειν ἐδόκει τὰ μέλλοντα. ὁ μὲν δὴ Μανίλιος ἀνεζεύγνυεν ἐς τὸ πρὸς τῇ πόλει στρατόπεδον, πολλὴν τίσιν ὑποσχὼν τοῦ μὴ πεισθῆναι Σκιπίωνι τῆς στρατείας ἀποτρέποντι· ἀχθομένων δὲ πάντων ἐπὶ τῇ τῶν πεσόντων ἀταφίᾳ, καὶ μάλιστα ἐπὶ τοῖς χιλιάρχοις, ὁ Σκιπίων τινὰ λύσας τῶν αἰχμαλώτων ἔπεμψε πρὸς Ἀσδρούβαν, καὶ παρῄνει θάψαι τοὺς χιλιάρχους. ὁ δ’ ἐρευνησάμενος τὰ νεκρά, καὶ ἀπὸ τῆς σφραγῖδος εὑρών (χρυσοφοροῦσι γὰρ τῶν στρατευομένων οἱ χιλίαρχοι, τῶν ἐλαττόνων σιδηροφορούντων), ἔθαψεν αὐτούς, εἴτε τὸ ἔργον ἀνθρώπειον καὶ κοινὸν ἐν τοῖς πολέμοις ἡγούμενος, εἴτε τὴν Σκιπίωνος δόξαν ἤδη δεδιώς τε καὶ θεραπεύων. Ῥωμαίοις δ’ ἀναζευγνύουσι μὲν ἀπὸ τοῦ Ἀσδρούβα ἐπέκειτο Φαμέας, διὰ τὸ πταῖσμα θορυβουμένοις· ἐσιοῦσι δὲ οἱ Καρχηδόνιοι τῆς πόλεως ἐκδραμόντες ὑπήντων, καί τινα καὶ τῶν σκευοφόρων διέφθειραν.", "st": "9.104"}, {"sp": "N", "t": "εν τούτῳ δὲ καὶ ἡ σύγκλητος ἐς τὸ στρατόπεδον ἔπεμπε τοὺς εἰσομένους καὶ μεταδώσοντας αὐτῇ τὰ ἀκριβέστατα, ἐφ’ ὧν ὅ τε Μανίλιος καὶ τὸ συνέδριον καὶ οἱ λοιποὶ τῶν χιλιάρχων, ἐσβεσμένου τοῦ φθόνου διὰ τὴν εὐπραγίαν, ἐμαρτύρουν τῷ Σκιπίωνι, καὶ ὁ στρατὸς ἅπας καὶ τὰ ἔργα ἐπ’ ἐκείνοις, ὥστ’ ἐπανελθόντες οἱ πρέσβεις διεθρόησαν ἐς ἅπαντας τὴν ἐμπειρίαν καὶ ἐπίτενξιν τοῦ Σκιπίωνος καὶ τῆς στρατιᾶς τὴν ἐς αὐτὸν ὁρμήν. ἡ δὲ βουλὴ τούτοις μὲν ἔχαιρε, πολλῶν δὲ γεγενημένων πταισμάτων ἐς Μασσανάσσην ἔπεμπε, καὶ παρεκάλει συμμαχεῖν αὐτὸν ἐρρωμένως ἐπὶ Καρχηδόνα. ὁ δ’ ὑπὸ μὲν τῶν πρέσβεων οὐ κατελήφθη, κάμνων δὲ γήρᾳ καὶ νόσῳ, καὶ παῖδας ἔχων νόθους μὲν πλείονας, οἷς ἐδεδώρητο πολλά, γνησίους δὲ τρεῖς οὐδὲν ἀλλήλοις τὰ ἔργα ἐοικότας, ἐκάλει τὸν Σκιπίωνα κατὰ φιλίαν αὐτοῦ τε καὶ τοῦ πάππου σύμβουλόν οἱ περὶ τῶν τέκνων καὶ τῆς ἀρχῆς ἐσόμενον. ὁ δὲ ᾔει μὲν αὐτίκα, μικρὸν δὲ πρὶν ἐλθεῖν ὁ Μασσανάσσης ἀποψύχων ἐπέσκηψε τοῖς παισὶ πείθεσθαι τοῦ Σκιπίωνος, ὡς ἂν αὐτοῖς διαιρῇ τὰ ὄντα.", "st": "9.105"}, {"sp": "N", "t": "καὶ ὁ μὲν τοῦτ’ εἰπὼν ἐτελεύτησεν, ἀνὴρ ἐς πάντα ἐπιτυχής, ᾧ τὴν μὲν ἀρχὴν τὴν πατρῴαν θεὸς ἔδωκεν, ἀφαιρεθέντι πρὸς Καρχηδονίων καὶ Σύφακος, ἀναλαβεῖν καὶ προαγαγεῖν ἐπὶ μέγιστον, ἀπὸ Μαυρουσίων τῶν παρ’ ὠκεανῷ μέχρι τῆς Κυρηναίων ἀρχῆς ἐς τὰ μεσόγεια, ἡμερῶσαι δὲ γῆν πολλήν, τὰ πολλὰ τῶν Νομάδων ποηφαγούντων διὰ τὸ ἀγεώργητον, θησαυρούς τε μεγάλους χρημάτων καταλιπεῖν καὶ στρατιὰν πολλὴν γεγυμνασμένην, τῶν δ’ ἐχθρῶν Σύφακα μὲν αἰχμάλωτον ἑλεῖν αὐτοχειρί, Καρχηδόνι δ’ αἴτιον τῆς ἀναστάσεως γενέσθαι, πάμπαν ἀσθενῆ Ῥωμαίοις ὑπολιπόντα. ἔφυ δὲ καὶ τὸ σῶμα μέγας τε καὶ εὔρωστος ἐς γῆρας πολύ, καὶ μάχης ἐπειρᾶτο μέχρι τοῦ θανάτου, ἵππου τε χωρὶς ἀναβολέως ἐπέβαινεν. καὶ μεγίστῳ δὴ τῷδ’ ἐτεκμηρίωσε μάλιστα τὴν εὐρωστίαν αὑτοῦ· πολλῶν γὰρ αὐτῷ παίδων γιγνομένων τε καὶ ἀποθνησκόντων, οὔποτε μὲν ἦσαν αὐτῷ μείους τῶν δέκα, τετραετὲς δὲ παιδίον ἐνενηκοντούτης ὢν ἀπέλιπεν. ὁ μὲν δὴ Μασσανάσσης ὧδε χρόνου τε καὶ σώματος ἔχων ἐτεθνήκει, Σκιπίων δὲ τοῖς μὲν νόθοις αὐτοῦ παισὶ προσέθηκεν ἑτέρας δωρεάς, τοῖς δὲ γνησίοις τοὺς μὲν θησαυροὺς καὶ φόρους καὶ τὸ ὄνομα τῆς βασιλείας κοινὸν ἀπέφηνε, τὰ δ’ ἄλλα διέκρινεν ὡς ἔμελλεν ἁρμόσειν πρὸς ὃ ἐβούλετο ἕκαστος, Μικίψῃ μέν, ὃς πρεσβύτατος ὢν εἰρηνικώτατος ἦν, Κίρτην ἐξαίρετον ἔχειν καὶ τὰ βασίλεια τὰ ἐν αὐτῇ, Γολόσσῃ δέ, στρατιωτικῷ τε ὄντι καὶ δευτέρῳ καθ’ ἡλικίαν, πολέμου τε καὶ εἰρήνης εἶναι κυρίῳ, Μαστανάβᾳ δέ, ὃς νεώτατος ὢν ἤσκει δικαιοσύνην, δικάζειν τοῖς ὑπηκόοις τὰ ἀμφίλογα.", "st": "9.106"}, {"sp": "N", "t": "οὕτω μὲν ὁ Σκιπίων τὴν ἀρχὴν καὶ περιουσίαν Μασσανάσσου διεῖλε τοῖς παισί, καὶ Γολόσσην εὐθὺς ἐς συμμαχίαν ἐπήγετο· ὁ δὲ τὰς Φαμέου μάλιστα ἐνέδρας, αἳ πολλὰ Ῥωμαίους ἐλύπουν, ἐρευνώμενος ἀνέστελλεν. ἐν δέ τινι χειμασίᾳ Σκιπίων καὶ Φαμέας ἀντιπαρώδευον ἀλλήλοις, μέσην ἔχοντες ἄβατον χαράδραν, καὶ οὐδὲν ἐς ἀλλήλους δυνάμενοι. δεδιὼς δ’ ὁ Σκιπίων μή τις ἐνέδρα κατὰ τὸ πρόσθεν εἴη, προϊὼν κατεσκέπτετο σὺν τρισὶ φίλοις. καὶ αὐτὸν ὁ Φαμέας ἰδὼν ἀντιπροῄει μεθ’ ἑνὸς φίλου. ἐλπίσας δ’ αὐτὸν ὁ Σκιπίων εἰπεῖν τι θέλειν, ἐξίππευσε μεθ’ ἑνὸς καὶ ὅδε φίλου. καὶ ὡς ἤδη κατακούειν ἐδύναντο ἀλλήλων, πρὸ Καρχηδονίων οἱ προελήλυθεν. “τί δὴ τῆς ἰδίας σωτηρίας οὐ προνοεῖς, εἰ μὴ τῆς κοινῆς δύνασαι;” ὁ δέ, “τίς ἐστιν,” ἔφη, “μοι σωτηρία, Καρχηδονίων μὲν οὕτως ἐχόντων, Ῥωμαίων δ’ ὑπ’ ἐμοῦ κακὰ πολλὰ πεπονθότων;” καὶ ὁ Σκιπίων, “ἐγγυῶμαί σοί,” φησιν, “εἰ πιστὸς ἐγὼ καὶ ἀξιόχρεως, καὶ σωτηρίαν καὶ συγγνώμην παρὰ Ῥωμαίων καὶ χάριν ἔσεσθαι.” ὁ δ’ ἐπῄνεσε μὲν ὡς ἀξιοπιστότατον ἐκ πάντων, “κρινῶ” δ’, ἔφη· “κἂν δυνατὸν ἡγῶμαι, φανερὸν ἔσται σοι.”", "st": "9.107"}, {"sp": "N", "t": "καὶ οἱ μὲν ἐπὶ τούτοις διεκρίθησαν, ὁ δὲ Μανίλιος αἰδούμενος τὴν δυσπραξίαν τὴν ἐς Ἀσδρούβαν αὐτῷ γενομένην, αὖθις ἐς Νέφεριν ἐστράτευε, πεντακαίδεκα ἡμερῶν τροφὰς ἐπαγόμενος. πλησιάσας δ’ ἔθετο χάρακα καὶ ὠχύρου καὶ ἐτάφρευε, καθὰ Σκιπίων ἐν τῇ προτέρᾳ στρατείᾳ παρήγγειλεν. οὐδὲν δὲ ἀνύων ἐν αἰδοῖ μείζονι ἐγίγνετο καὶ φόβῳ τοῦ πάλιν αὐτοῖς ἀπιοῦσι τὸν Ἀσδρούβαν ἐπιθέσθαι. καὶ ὁ μὲν ἐν τῷδε ἦν ἀπορίας, ἐπιστολὴν δέ τις ἐκ τοῦ Γολόσσου στρατοῦ ἔφερε τῷ Σκιπίωνι. ὁ δ’, ὡς εἶχε, σεσημασμένην ἐπέδειξε τῷ στρατηγῷ. καὶ λύσαντες ηὗρον· “ἐς τήνδε τὴν ἡμέραν ἐγὼ μὲν τόδε τὸ χωρίον καταλήψομαι· σὺ δ’ ἐλθὲ μεθ’ ὅσων βούλει, καὶ τοῖς προφύλαξιν εἰπὲ δέχεσθαι τὸν νυκτὸς ἀφικνούμενον.” ἡ μὲν ἐπιστολὴ χωρὶς ὀνομάτων τοιάδ’ ἐδήλου, συνῆκε δ’ ὁ Σκιπίων εἶναι παρὰ Φαμέου. καὶ ὁ Μανίλιος ἐδεδοίκει μὲν περὶ τῷ Σκιπίωνι, μή τις ἀπάτη παρ’ ἀνδρὸς γένοιτο πιθανωτάτου πάντων ἐς ἐνέδρας· εὔελπιν δ’ αὐτὸν ὁρῶν ἔπεμπεν, ἐπιτρέψας περὶ μὲν τῆς σωτηρίας δοῦναι πίστιν ἀσφαλῆ τῷ Φαμέᾳ, χάριν δὲ μὴ ὁρίζειν, ἀλλ’ ἐπαγγέλλεσθαι Ῥωμαίους τὰ πρέποντα ποιήσειν. οὐ μὴν ἐδέησεν οὐδ’ ἐπαγγελίας· ὁ γάρ τοι Φαμέας ὡς ἧκεν ἐς τὸ συγκείμενον, περὶ μὲν τῆς σωτηρίας ἔφη πιστεύειν δεξιουμένῳ Σκιπίωνι, τὰς δὲ χάριτας Ῥωμαίοις ἐπιτρέπειν. ταῦτα δ’ εἰπὼν ἐξέτασσε τῆς ἐπιούσης ἐς μάχην, καὶ προπηδήσας μὲτὰ τῶν ἰλαρχῶν ἐς τὸ μεταίχμιον ὡς ἐπί τινα σκέψιν ἑτέραν, εἶπεν· “εἰ μὲν ἔστιν ἔτι τῇ πατρίδι βοηθεῖν, ἕτοιμός εἰμι μεθ’ ὑμῶν· εἰ δ’ ἔχει τὰ ἐκείνης ὡς ἔχει, ἐμοὶ μὲν δοκεῖ τῆς ἰδίας σωτηρίας προνοεῖν, καὶ πίστιν ἔλαβον ἐπί τε ἐμαυτῷ καὶ ὅσους πείσαιμι ὑμῶν, καιρὸς δὲ καὶ ὑμᾶς ἐπιλέγεσθαι τὰ συνοίσοντα.” ὁ μὲν οὕτως εἶπε, τῶν δ’ ἰλαρχῶν οἱ μὲν σὺν τοῖς αὑτῶν ηὐτομόλησαν, καὶ ἐγένοντο πάντες ἐς διακοσίους καὶ δισχιλίους ἱππέας· τοὺς δ’ Ἄννων κατεκώλυσεν, ᾧ Λεῦκος ἦν ἐπίκλησις.", "st": "9.108"}, {"sp": "N", "t": "ἐπανιόντι δὲ τῷ Σκιπίωνι μετὰ τοῦ Φαμέου ὁ στρατὸς ἀπήντα, καὶ τὸν Σκιπίωνα ηὐφήμουν ὡς ἐπὶ θριάμβῳ. Μανίλιος δ’ ὑπερηδόμενός τε, καὶ οὐκέτι τὴν ἐπάνοδον αἰσχρὰν ἐπὶ τῷδε ἡγούμενος, οὐδ’ Ἀσδρούβαν ἕψεσθαι προσδοκῶν καταπεπληγμένον, ἀνεζεύγνυεν αὐτίκα δι’ ἔνδειαν, ἑπτακαιδεκάτην ἡμέραν ἀντὶ πεντεκαίδεκα ἔχων. τρισὶ δ’ ἄλλαις ἐχρῆν κακοπαθοῦντα ἐπανελθεῖν. ὁ οὖν Σκιπίων τόν τε Φαμέαν καὶ Γολόσσην καὶ τοὺς ὑφ’ ἑκατέρῳ λαβὼν ἱππέας, προσλαβὼν δέ τινας καὶ τῶν Ἰταλικῶν, ἐς πεδίον ἠπείχθη τὸ καλούμενον μέγα βάραθρον, καὶ πολλὴν ἐξ αὐτοῦ λείαν τε καὶ ἀγορὰν ἧκε φέρων τῷ στρατῷ περὶ νύκτα. Μανίλιος δὲ πυθόμενός οἱ διάδοχον ἐπιέναι Καλπούρνιον Πίσωνα, προέπεμπεν ἐς Ῥώμην Σκιπίωνα μετὰ Φαμέου· καὶ ὁ στρατὸς ἐπὶ τὴν ναῦν καταθέοντες ηὐφήμουν τὸν Σκιπίωνα, καὶ ηὔχοντο ὕπατον ἐς Λιβύην ἐπανελθεῖν ὡς μόνον αἱρήσοντα Καρχηδόνα. θεόληπτος γάρ τις αὐτοῖς ἥδε ἡ δόξα ἐνέπιπτε, Σκιπίωνα μόνον αἱρήσειν Καρχηδόνα· καὶ πολλοὶ ταῦτα τοῖς οἰκείοις ἐς Ῥώμην ἐπέστελλον. ἡ δὲ βουλὴ Σκιπίωνα μὲν ἐπῄνει, Φαμέαν δ’ ἐτίμησαν ἁλουργίδι καὶ ἐπιπορπήματι χρυσῷ καὶ ἵππῳ χρυσοφαλάρῳ καὶ πανοπλίᾳ καὶ ἀργυρίου δραχμαῖς μυρίαις, ἔδωκαν δὲ καὶ μνῶν ἑκατὸν ἀργύρωμα καὶ σκηνὴν καὶ κατασκευὴν ἐντελῆ. καὶ ἐπήλπισαν περὶ πλειόνων, εἰ τὰ λοιπὰ τοῦ πολέμου συνεκπονήσειεν αὑτοῖς. ὁ δ’ ὑποσχόμενος ἐς Λιβύην διέπλευσεν ἐς τὸ Ῥωμαιων στρατόπεδον.", "st": "9.109"}, {"sp": "N", "t": "ἧκε δὲ Καλπούρνιος Πίσων ὁ ὕπατος ἅμα ἦρι, καὶ σὺν αὐτῷ Λεύκιος Μαγκῖνος ἐπὶ τὴν ναυαρχίαν· οἳ Καρχηδονίοις μὲν οὐκ ἐπεχείρουν, οὐδὲ Ἀσδρούβᾳ, τὰς δὲ πόλεις ἐπιόντες Ἀσπίδος μὲν ἀπετύγχανον, ἐκ γῆς καὶ θαλάσσης ἀποπειράσαντες, ἑτέραν δ’ ἐγγὺς εἷλεν ὁ Πίσων, καὶ διήρπαζεν αἰτιωμένην ἐπὶ συνθήκαις αὐτῷ προσελθεῖν. ἀπὸ δὲ ταύτης ἐς Ἰππάγρετα μετῆλθεν, ἣ μεγάλη τε ἦν καὶ τείχεσι καὶ ἀκροπόλει καὶ λιμέσι καὶ νεωρίοις ὑπ’ Ἀγαθοκλέους τοῦ Σικελιωτῶν τυράννου κατεσκεύαστο καλῶς, μέση δ’ οὖσα Καρχηδόνος καὶ Ἰτύκης τὴν ἀγορὰν ἐλῄστευε τὴν Ῥωμαίοις διαπλέουσαν· ὅθεν καὶ πάνυ ἐπλούτουν. καὶ ὁ Καλπούρνιος ἀμύνασθαί τε αὐτοὺς ἐπενόει, καὶ τό γε κέρδος ἀφελέσθαι. ἀλλ’ ὁ μὲν τὸ θέρος ὅλον ἐφεδρεύων οὐκ ἤνυε, δὶς δ’ ἐκδραμόντες οἱ Ἱππαγρέτιοι, Καρχηδονίων αὐτοῖς συμμαχούντων, τὰς μηχανὰς αὐτοῦ κατέπρησαν. καὶ ὁ μὲν ἄπρακτος ἐς Ἰτύκην ἐπανελθὼν ἐχείμαζεν.", "st": "9.110"}, {"sp": "N", "t": "οἱ Καρχηδόνιοι δέ, ἐπειδή σφισι καὶ τὸ Ἀσδρούβα στρατόπεδον ἀπαθὲς ἦν, καὶ αὐτοὶ κρείττους ἐν τῇ μάχῃ ἐγεγένητο Πίσωνος ἀμφὶ τὰ Ἱππάγρετα, Βιθύας τε αὐτοῖς ὁ Νομὰς μετὰ ὀκτακοσίων ἱππέων ἀπὸ Γολόσσου προσεκεχωρήκει, καὶ Μικίψην καὶ Μαστανάβαν τοὺς Μασσανάσσου παῖδας ἑώρων ὑπισχνουμένους μὲν ἀεὶ Ῥωμαίοις ὅπλα καὶ χρήματα, βραδύνοντας δὲ καὶ περιορωμένους ἄρα τὸ μέλλον, ἐπῄρθησαν τοῖς φρονήμασι καὶ Λιβύην ἀδεῶς ἐπῄεσαν, κρατυνόμενοί τε τὴν χώραν καὶ πολλὰ ὑβριστικὰ ἐν ταῖς πόλεσι κατὰ Ῥωμαίων ἐκκλησιάζοντες. ἔς τε τὴν ἀνανδρίαν αὐτῶν προύφερον τὰ ἐς Νέφεριν αὐτοῖς δὶς γενόμενα, καὶ ὅσα ἔναγχος ἐς Ἱππάγρετα, καὶ τὸ αὐτῆς Καρχηδόνος ἀνόπλου τε οὔσης καὶ ἀφράκτου μὴ δεδυνῆσθαι κατασχεῖν. ἔπεμπον δὲ καὶ ἐς Μικίψην καὶ Μαστανάβαν καὶ ἐς τοὺς αὐτονόμους Μαυρουσίων, παρακαλοῦντες ὁμοῦ, καὶ διδάσκοντες ὅτι καὶ σφίσι μεθ’ αὑτοὺς ἐπιχειρήσουσι Ῥωμαῖοι. ἔστελλον δὲ καὶ ἐς Μακεδονίαν ἄλλους πρὸς τὸν νομιζόμενον υἱὸν εἶναι Περσέως, πολεμοῦντα Ῥωμαίοις, καὶ ἀνέπειθον ἔχεσθαι τοῦ πολέμου καρτερῶς ὡς οὐκ ἐλλειψόντων αὐτῷ χρημάτων καὶ νεῶν ἀπὸ Καρχηδόνος. ὅλως τε μικρὸν οὐδὲν ἔτι ἐφρόνουν ὁπλισάμενοι, ἀλλὰ θυμῷ καὶ τόλμῃ καὶ παρασκευῇ κατὰ μικρὸν ηὔξοντο. ἐπῇρτο δ’ ἐν μέρει καὶ Ἀσδρούβας ὁ κατὰ τὴν χώραν στρατηγὸς τῷ δὶς κρατῆσαι Μανιλίου· τήν τε τῆς πόλεως στρατηγίαν προσλαβεῖν ἐπειγόμενος, Ἀσδρούβαν τὸν ἄρχοντα αὐτῆς, ἀδελφιδοῦν ὄντα Γολόσσου, διέβαλλε τῇ βουλῇ τὰ Καρχηδονίων Γολόσσῃ προδιδόναι. καὶ τοῦ λόγου προτεθέντος ἐς μέσον, ὁ μὲν ἠπορεῖτο ὡς ἐπ’ ἀδοκήτῳ, οἱ δὲ τύπτοντες αὐτὸν τοῖς ὑποβάθροις κατέβαλον.", "st": "9.111"}, {"sp": "N", "t": "ἐς δὲ Ῥώμην ἐξαγγελλομενης τῆς τε Πίσωνος ἀπραξίας καὶ Καρχηδονίων παρασκευῆς, ὁ δῆμος ἤχθετο καὶ ἐδεδοίκει αὐξομένου πολέμου μεγάλου τε καὶ ἀδιαλλάκτου καὶ γείτονος· οὐ γάρ τινα διάλυσιν προσεδόκων, ἄπιστα πρότεροι κελεύσαντες. τῶν δ’ οὐ πρὸ πολλοῦ Σκιπίωνος ἔργων, ἐν Λιβύῃ χιλιαρχοῦντος ἔτι, μεμνημένοι, καὶ παραβάλλοντες αὐτὰ τοῖς παροῦσι, τῶν τε ἐπεσταλμένων σφίσιν ὑπὸ τῶν ἐκ στρατοπέδου φίλων καὶ οἰκείων ἀναφέροντες, ὥρμηντο ὕπατον ἐς Καρχηδόνα πέμπειν Σκιπίωνα. ἐνειστήκει δ’ ἀρχαιρέσια, καὶ ὁ Σκιπίων (οὐ γάρ πω δι’ ἡλικίαν αὐτῷ συνεχώρουν ὑπατεύειν οἱ νόμοι) ἀγορανομίαν μετῄει, καὶ ὁ δῆμος αὐτὸν ὕπατον ᾑρεῖτο. παρανόμου δ’ ὄντος καὶ τῶν ὑπάτων προφερόντων αὐτοῖς τὸν νόμον, ἐλιπάρουν καὶ ἐνέκειντο, καὶ ἐκεκράγεσαν ἐκ τῶν Τυλλίου καὶ Ῥωμύλου νόμων τὸν δῆμον εἶναι κύριον τῶν ἀρχαιρεσιῶν, καὶ τῶν περὶ αὐτῶν νόμων ἀκυροῦν ἢ κυροῦν ὃν ἐθέλοιεν. τέλος δὲ τῶν δημάρχων τις ἔφη τοὺς ὑπάτους ἀφαιρήσεσθαι τὴν χειροτονίαν, εἰ μὴ σύνθοιντο τῷ δήμῳ. καὶ ἡ βουλὴ τοῖς δημάρχοις ἐπείθετο λῦσαι τὸν νόμον τόνδε καὶ μετὰ ἔτος ἓν αὖθις ἀναγράψαι, οἷόν τι καὶ Λακεδαιμόνιοι, λύοντες ἐν χρείᾳ τὴν ἀτιμίαν τῶν ἁλόντων περὶ Πύλον, ἔφασαν· “κοιμάσθων οἱ νόμοι τήμερον.” οὕτω μὲν ὁ Σκιπίων ἀγορανομίαν μετιὼν ᾕρητο ὕπατος, καὶ αὐτὸν ὁ σύναρχος Δροῦσος περὶ Λιβύης πρὸς αὑτὸν ἐκέλευε διακληροῦσθαι, μέχρι τις τῶν δημάρχων ἐσηγήσατο τῆσδε τῆς στρατηγίας τὴν κρίσιν τοῦ δήμου γενέσθαι· καὶ ὁ δῆμος εἵλετο τὸν Σκιπίωνα. ἐδόθη δ’ αὐτῷ στρατὸς ἐκ μὲν καταλόγου, ὅσος ἦν ἀντὶ τῶν ἀπολωλότων, ἐθελοντὰς δ’ ἄγειν ὅσους πείσειε παρὰ τῶν συμμάχων, καὶ ἐς βασιλέας καὶ πόλεις, ὅσας δοκιμάσειε, πέμπειν, τὸν Ῥωμαίων δῆμον ταῖς ἐπιστολαῖς ἐπιγράφοντα. καὶ ἔστιν οὓς ἔλαβεν οὕτω παρά τε πόλεων καὶ βασιλέων.", "st": "9.112"}, {"sp": "N", "t": "ὁ μὲν δὴ τάδε διοικησάμενος ἐς Σικελίαν καὶ ἀπὸ Σικελίας ἐς Ἰτύκην ἔπλει· Καλπούρνιος δὲ Πίσων ἐπολιόρκει τὰ μεσόγεια, καὶ Μαγκῖνος ἐφορμῶν Καρχηδόνι, μέρος τι τοῦ τείχους ἀμελούμενον ἰδών, οὗ κρημνοὶ προύκειντο συνεχεῖς καὶ δύσβατοι, καὶ παρ’ αὐτὸ ἦν καὶ ἀμελούμενον, ἤλπισε λαθὼν κλίμακας ἐποίσειν ἐπὶ τὸ τεῖχος. καὶ προσέθηκε μέν, καί τινες τῶν στρατιωτῶν ἀνῆλθον εὐτόλμως· οἱ Καρχηδόνιοι δ’ ὀλίγων ἔτι ὄντων καταφρονήσαντες, ἀνέῳξαν πύλην ἐς τοὺς κρημνοὺς ἐκφέρουσαν, καὶ ἐπὶ τοὺς Ῥωμαίους ἐξέδραμον. καὶ αὐτοὺς οἱ Ῥωμαῖοι τρεψάμενοί τε καὶ διώκοντες ἐς τὴν πόλιν διὰ τῆς πύλης συνεσέδραμον. βοῆς δ’ ὡς ἐπὶ νίκῃ γενομένης, ὅ τε Μαγκῖνος ἐκφερόμενος ὑπὸ τῆς ἡδονῆς, καὶ τὰ ἄλλα ταχὺς ὢν καὶ κουφόνους, καὶ ὁ ἄλλος ὅμιλος ἅμα τῷ Μαγκίνῳ, τὰς ναῦς ἀφέντες ἐς τὸ τεῖχος ἐβοηδρόμουν ἄνοπλοί τε καὶ γυμνοί. ἤδη δὲ τοῦ θεοῦ περὶ δείλην ἑσπέραν ὄντος, ἐχυρόν τι πρὸς τῷ τείχει καταλαβόντες ἡσύχαζον, τροφῶν δ’ ἀπορῶν ὁ Μαγκῖνος ἐκάλει Πίσωνα καὶ τοὺς Ἰτυκαίων ἄρχοντας, ἐπικουρεῖν αὑτῷ κινδυνεύοντι καὶ τροφὰς φέρειν κατὰ σπουδήν. καὶ ὁ μὲν ἔμελλεν ἅμ’ ἕῳ πρὸς τῶν Καρχηδονίων ἐξωθούμενος ἐς τοὺς κρημνοὺς συντριβήσεσθαι.", "st": "9.113"}, {"sp": "N", "t": "Σκιπίων δ?̓ἑσπέρας ἐς Ἰτύκην κατήγετο, καὶ περὶ μέσας νύκτας ἐντυχὼν οἷς ὁ Μαγκῖνος ἔγραφε, τόν τε σαλπικτὴν ἐκέλευεν εὐθὺς ἐπὶ πόλεμον ἠχεῖν, καὶ τοὺς κήρυκας συγκαλεῖν ἐπὶ θάλασσαν ὅσοι συνεληλύθεσαν ἐξ Ἰταλίας αὐτῷ, καὶ τοὺς ἡβῶντας Ἰτυκαίων· ὅσοι δ’ ὑπερήλικες, ἀγορὰν ἐς τὰς τριήρεις καταφέρειν. αἰχμάλωτά τε Καρχηδονίων τινὰ λύσας, ἀφῆκεν ἐξαγγέλλειν αὐτοῖς ἐπιπλεῖν Σκιπίωνα. ἔς τε τὸν Πίσωνα ἱππέας ἄλλους ἐπ’ ἄλλοις ἔπεμπε, καλῶν αὐτὸν κατὰ τάχος. καὶ αὐτὸς ἐσχάτης φυλακῆς ἀνήγετο, κελεύσας, ὅταν πλησιάζωσιν, ὀρθοὺς ἐπὶ τῶν καταστρωμάτων ἑστάναι τοῦ πλέονα τὴν ὄψιν ἐμποιεῖν τοῖς πολεμίοις. ὁ μὲν δὴ τάδ’ ἔπρασσεν, ὁ δὲ Μαγκῖνος, ἅμ’ ἕῳ τῶν Καρχηδονίων αὐτῷ πανταχόθεν ἐπιπιπτόντων, πεντακοσίους μέν, οὓς μόνους εἶχεν ἐνόπλους, περιέστησε τοῖς γυμνοῖς τρισχιλίοις οὖσι, τιτρωσκόμενος δὲ δι’ ἐκείνων καὶ συνωθούμενος ἐπὶ τὸ τεῖχος ἤδη κατεκρημνίζετο, καὶ αἱ νῆες ὤφθησαν αἱ τοῦ Σκιπίωνος, ῥοθίῳ τε φοβερῷ καταπλέουσαι καὶ μεσταὶ πανταχόθεν ὁπλιτῶν ἐφεστώτων, Καρχηδονίοις μὲν ᾐσθημένοις διὰ τῶν αἰχμαλώτων οὐκ ἀνέλπιστοι, Ῥωμαίοις δ’ ἀγνοοῦσιν ἀδόκητον σωτηρίαν φέρουσαι· μικρὸν γὰρ ὑποχωρησάντων τῶν Καρχηδονίων, ὁ Σκιπίων τοὺς κινδυνεύοντας ἐς αὐτὰς ἀνέλαβεν. καὶ Μαγκῖνον μὲν ἐς Ῥώμην αὐτίκα ἔπεμψε (καὶ γὰρ ἧκεν αὐτῷ Σερρανὸς ἐπὶ τὴν ναυαρχίαν διάδοχος), αὐτὸς δ’ οὐ μακρὰν τῆς Καρχηδόνος ἐστρατοπέδευεν. οἱ δὲ Καρχηδόνιοι τῶν τειχῶν ἐς πέντε σταδίους προελθόντες ἀντήγειραν αὐτῷ χάρακα, καὶ αὐτοῖς ἐς τόνδε τὸν χάρακα ἀφίκοντο Ἀσδρούβας τε ὁ τῆς χώρας στρατηγὸς καὶ Βιθύας ὁ ἵππαρχος ἑξακισχιλίους πεζοὺς ἄγοντες καὶ ἱππέας ἐς χιλίους, χρόνῳ καὶ μελέτῃ γεγυμνασμένους.", "st": "9.114"}, {"sp": "N", "t": "ὁ δὲ Σκιπίων οὐδὲν εὔκοσμον ἐν τοῖς στρατιώταις ὁρῶν οὐδὲ τεταγμένον, ἀλλ’ ἐς ἀργίαν καὶ πλεονεξίαν καὶ ἁρπαγὰς ὑπὸ τοῦ Πίσωνος ἐπιτετραμμένους, ἄλλο τε πλῆθος αὐτοῖς συνόντας ἀγοραῖον, οἳ τῆς λείας χάριν ἑπόμενοι τοῖς θρασυτέροις συνεξέτρεχον ἐπὶ τὰς ἁρπαγὰς ἄνευ παραγγέλματος ἰοῦσι, τοῦ νόμου λιποστράτιον ἐν τοῖς πολέμοις ἡγουμένου τὸν ἀποχωρούντα πορρωτέρω σάλπιγγος ἀκοῆς, ὅσα τε πταίσειαν οὗτοι, πάντα ἐς τὸν στρατηγὸν ἀναφερόμενα, καὶ ὅσα διαρπάσειαν, ἑτέρας ἔριδος αὐτοῖς καὶ κακῶν γιγνόμενα ἀρχάς· πολλοὶ γὰρ καὶ συσκήνων κατεφρόνουν διὰ τὰ κέρδη, καὶ ἐς ἀνόμους πληγὰς καὶ τραύματα καὶ ἀνδροφονίας ἐχώρουν. ὧν αἰσθόμενος ὁ Σκιπίων, καὶ ἐλπίζων οὔποτε κρατήσειν τῶν πολεμίων εἰ μὴ τῶν ἰδίων κρατήσειε, συνήγαγεν ἐς ἐκκλησίαν αὐτούς, καὶ ἐπὶ βῆμα ὑψηλὸν ἀναβὰς ἐπέπληξεν ὧδε.", "st": "9.115"}, {"sp": "N", "t": "“ἐγὼ μεθ’ ὑμῶν, ὦ ἄνδρες, ὑπὸ Μανιλίῳ στρατηγῷ ταττόμενος, τῆς εὐπειθείας ἐν ὑμῖν μάρτυσιν ἔδωκα πεῖραν, ἣν νῦν ὑμᾶς αἰτῶ στρατηγῶν, κολάσαι μὲν ἐς ἔσχατον ἔχων ἐξουσίαν τοὺς ἀπειθοῦντας, ὠφέλιμον δ’ ἡγούμενος προαγορεῦσαι. ἴστε δὲ ἃ πράττετε· καὶ τί με δεῖ λέγειν ἃ αἰσχύνομαι; λῃστεύετε μᾶλλον ἢ πολεμεῖτε, καὶ διαδιδράσκετε, οὐ στρατοπεδεύετε· καὶ πανηγυρίζουσιν ὑπὸ τῶν κερδῶν, οὐ πολιορκοῦσιν ἐοίκατε· καὶ τρυφᾶν ἐθέλετε πολεμοῦντες ἔτι, οὐ νενικηκότες. τοιγάρτοι τὰ τῶν πολεμίων ἐξ ἀέλπτου καὶ βραχέος, οὗ κατέλιπον, ἐς τοσοῦτον ἐπῇρται δυνάμεως, καὶ ἡμῖν ὁ πόνος ἐκ τῆσδε τῆς ῥᾳστώνης γέγονε χαλεπώτερος. τὰς δ’ αἰτίας εἰ μὲν ἐν ὑμῖν οὔσας ἑώρων, εὐθὺς ἂν ἐκόλαζον· ἐπεὶ δ’ ἀνατίθημι ἑτέρῳ, νῦν μὲν ὑμᾶς ἀφίημι τῶν μέχρι νῦν γεγονότων. ἥκω δὲ οὐ λῃστεύσων ἔγωγε ἀλλὰ νικήσων, οὐδὲ χρηματιούμενος πρὸ τῆς νίκης, ἀλλὰ τοὺς ἐχθροὺς πρῶτον ἐξεργασόμενος. ἄπιτε πάντες ἐκ τοῦ στρατοπέδου τήμερον, ὅσοι μὴ στρατεύεσθε, χωρὶς τῶν ἐπιτραπησομένων ὑπ’ ἐμοῦ μένειν. τοῖς δ’ ἐξιοῦσιν οὐδ’ ἐπανελθεῖν δίδωμι, πλὴν εἴ τις ἀγορὰν φέροι, καὶ ταύτην στρατιωτικήν τε καὶ ψιλήν. ἔσται δὲ καὶ τούτοις χρόνος ὡρισμένος ἐν ᾧ τὰ ὄντα διαθήσονται, καὶ τῆς πράσεως αὐτῶν ἐγὼ καὶ ὁ ταμίας ἐπιμελησόμεθα. καὶ τάδε μὲν εἰρήσθω τοῖς περιττοῖς, ὑμῖν δὲ τοῖς ἐστρατευμένοις ἓν ἔστω παράγγελμα κοινὸν ἐπὶ πᾶσιν ἔργοις ὁ ἐμὸς τρόπος καὶ πόνος· πρὸς γὰρ τόδε κατευθεύνοντες αὑτοὺς οὔτε προθυμίας ἁμαρτήσεσθε οὔτε χάριτος ἀτυχήσετε. χρὴ δὲ νῦν μὲν πονεῖν, ἐν ᾧ κινδυνεύομεν, τὰ δὲ κέρδη καὶ τὴν τρυφὴν ἐς τὸν πρέποντα καιρὸν ἀναθέσθαι. ταῦτ’ ἐγὼ προστάσσω καὶ ὁ νόμος, καὶ τοῖς μὲν εὐπειθῶς ἔχουσιν οἴσει πολλὴν ἀγαθῶν ἀμοιβήν, τοῖς δ’ ἀπειθοῦσι μετάνοιαν.”", "st": "9.116"}, {"sp": "N", "t": "ὁ μὲν δὴ Σκιπίων ταῦτ’ εἶπε, καὶ εὐθὺς ἀπήλαυνε τὸ πλῆθος ἀνδρῶν ἀχρείων, καὶ σὺν αὐτοῖς ὅσα περιττὰ καὶ μάταια καὶ τρυφερὰ ἦν. καθαροῦ δὲ τοῦ στρατοῦ γενομένου καὶ περιδεοῦς καὶ ἐς τὰ παραγγελλόμενα ὀξέος, ἀπεπείραζε τῶν καλουμένων Μεγάρων νυκτὸς μιᾶς διχῇ λανθάνων. χωρίον δ’ ἐστὶν εὐμέγεθες ἐν τῇ πόλει τὰ Μέγαρα, τῷ τείχει παρεζευγμένον· ἐς ὃ τῇ μὲν ἑτέρους περιέπεμπε, τῇ δ’ αὐτὸς σὺν πελέκεσι καὶ κλίμαξι καὶ μοχλοῖς ἐβάδιζε σταδιους εἴκοσιν ἀψοφητί, μετὰ σιγῆς βαθυτάτης. αἰσθήσεως δ’ ἄνωθεν, ὅτε μάλιστ’ ἐπλησίαζε, καὶ βοῆς ἀπὸ τῶν τειχῶν γενομένης, ἀντεβόησεν αὐτός τε πρῶτος καὶ ὁ στρατὸς αὐτοῦ καὶ οἱ ἐπὶ θάτερα ἀπεσταλμένοι μέγιστον, ὡς τῷδε πρώτῳ τοὺς Καρχηδονίους καταπλαγῆναι, τοσούτων ἐχθρῶν ἐν πλευραῖς ἄφνω νυκτὸς ἐπιγενομένων. κατὰ μὲν οὖν τὸ τεῖχος οὐδέν, καίπερ ἐπιχειρῶν, ἤνυεν, ἐς δέ τινος ἰδιώτου πύργον ἔρημον, ἐκτὸς ὄντα τοῦ τείχους καὶ τὸ ὕψος ἴσον ὄντα τῷ τείχει, νεανίας ἀνεβίβασεν εὐτόλμους, οἳ τοὺς ἐπὶ τῶν τειχῶν ἀκοντίοις ἀνέστελλον, ξύλα τε καὶ σανίδας ἐς τὸ διάστημα ἐπιθέντες καὶ δι’ αὐτῶν ἐς τὰ τείχη διαδραμόντες καθήλαντο ἐς τὰ Μέγαρα, καὶ πυλίδα κόψαντες ἐδέχοντο τὸν Σκιπίωνα. ὁ δὲ ἐσῆλθε μὲν σὺν ἀνδράσι τετρακισχιλίοις, καὶ φυγη ταχεῖα τῶν Καρχηδονίων ἐς τὴν Βύρσαν ἦν ὡς τῆς ἄλλης πόλεως ἁλούσης. βοή τε ἐγίγνετο ποικίλη καὶ τινῶν αἰχμαλωσία καὶ θόρυβος, ὡς καὶ τοὺς ἔξω στρατοπεδεύοντας ἐκλιπεῖν τὸ χαράκωμα καὶ ἐς τὴν Βύρσαν ὁμοῦ τοῖς ἄλλοις ἀναδραμεῖν. ὁ δὲ Σκιπίων (τὸ γὰρ χωρίον, τὰ Μέγαρα, ἐλαχανεύετο καὶ φυτῶν ὡραίων ἔγεμεν, αἱμασιαῖς τε καὶ θριγκοῖς βάτου καὶ ἄλλης ἀκάνθης καὶ ὀχετοῖς βαθέος ὕδατος ποικίλοις τε καὶ σκολιοῖς κατάπλεων ἦν) ἔδεισε μὴ ἄβατον καὶ δυσχερὲς ᾖ στρ ατῷ διώκοντι ἐν ἀγνωσίᾳ μάλιστα διόδων, καί τις ἐν νυκτὶ ἐνέδρα γένοιτο. ἀνεζευγνυε δή.", "st": "9.117"}, {"sp": "N", "t": "καὶ γενομένης ἡμέρας ὁ Ἀσδρούβας, χαλεπῶς ἔχων τῆς ἐς τὰ Μέγαρα ἐπιχειρήσεως, ὅσα Ῥωμαίων εἶχεν αἰχμάλωτα, ἐπὶ τὸ τεῖχος ἀγαγών, ὅθεν εὐσύνοπτα Ῥωμαίοις ἔμελλε τὰ δρώμενα ἔσεσθαι, τῶν μὲν ὀφθαλμοὺς ἢ γλώττας ἢ νεῦρα ἢ αἰδοῖα σιδηρίοις ἐξεῖλκε καμπύλοις, τῶν δ’ ὑπέτεμνε τὰ πέλματα καὶ τοὺς δακτύλους ἐξέκοπτεν, ἢ τὸ δέρμα τοῦ λοιποῦ σώματος ἀπέσπα, καὶ πάντας ἔμπνους ἔτι κατεκρήμνιζεν, ἀδιάλλακτα τοῖς Καρχηδονίοις τὰ ἐς Ῥωμαίους ἐπινοῶν. καὶ ὁ μὲν αὐτοὺς οὕτως ἠρέθιζε τὴν σωτηρίαν ἔχειν ἐν μόνῃ τῇ μάχῃ, περιέστη δ’ αὐτῷ ἐς τὸ ἐναντίον ὧν ἐπενόει. ὑπὸ γὰρ συνειδότος οἱ Καρχηδόνιοι τῶνδε τῶν ἀθεμίστων ἔργων περιδεεῖς ἀντὶ προθύμων ἐγίγνοντο, καὶ τὸν Ἀσδρούβαν ὡς καὶ τὴν συγγνώμην σφῶν ἀφῃρημένον ἐμίσουν· καὶ μάλισθ’ ἡ βουλὴ αὐτοῦ κατεβόα ὡς ὠμὰ καὶ ὑπερήφανα δεδρακότος ἐν συμφοραῖς οἰκείαις τοσαῖσδε. ὁ δὲ καὶ τῶν βουλευτῶν τινὰς ἔκτεινε συλλαμβάνων, καὶ ἐς πάντα ὢν ἤδη περιδεὴς ἐς τυραννίδα μᾶλλον ἢ στρατηγίαν περιῆλθεν, ὡς ἐν τῷδε μόνῳ τὸ ἀσφαλὲς ἕξων, εἰ φοβερὸς αὐτοῖς εἴη καὶ δι’ αὐτὸ καὶ δυσεπιχείρητος.", "st": "9.118"}, {"sp": "N", "t": "ὁ δὲ Σκιπίων τὸν μὲν χάρακα τῶν ἐχθρῶν, ὃν τῇ προτέρᾳ κατελελοίπεσαν ἐς τὸ ἄστυ φεύγοντες, ἐνέπρησεν, ὅλου δὲ τοῦ ἰσθμοῦ κρατῶν διετάφρευεν αὐτὸν ἐκ θαλάσσης ἐπὶ θάλασσαν, ἀπέχων τῶν πολεμίων ὅσον ὁρμὴν βέλους. οἱ δὲ ἐπέκειντο, καὶ ἦν αὐτῷ ἔργον ἐπὶ σταδίους τοῦ μετώπου πέντε καὶ εἴκοσιν ἐργαζομένῳ τε ὁμοῦ καὶ μαχομένῳ. ὡς δὲ αὐτῷ τοῦτ’ ἐξετετέλεστο, ἑτέραν ὤρυσσε τάφρον ἴσην, οὐ πολὺ τῆς προτέρας διασχών, ἐς τὴν ἤπειρον ἀφορῶσαν. δύο τε ἐπικαρσίας αὐταῖς ἑτέρας περιθεὶς ὡς γενέσθαι τὸ ὅλον ὄρυγμα τετράγωνον, ἐσταύρωσε πάντα ξύλοις ὀξέσιν. καὶ ἐπὶ τοῖς σταυροῖς τὰς μὲν ἄλλας τάφρους ἐχαράκωσε, τῇ δ’ ἐς τὴν Καρχηδόνα ὁρώσῃ καὶ τεῖχος παρῳκοδόμησεν ἐπὶ τοὺς πέντε καὶ εἴκοσι σταδίους, ὕψος μὲν δυώδεκα ποδῶν χωρὶς ἐπάλξεών τε καὶ πύργων, οἳ ἐκ διαστήματος ἐπέκειντο τῷ τείχει, τὸ δὲ βάθος ἐφ’ ἥμισυ μάλιστα τοῦ ὕψους. ὁ δ’ ἐν μέσῳ πύργος ὑψηλότατός τε ἦν, καὶ ἐπ’ αὐτοῦ ξύλινος ἐπέκειτο τετρώροφος, ὅθεν καθεώρα τὰ γιγνόμενα ἐν τῇ πόλει. ταῦτα δ’ ἡμέραις εἴκοσι καὶ νυξὶν ἐργασάμενος ὅλῳ τῷ στρατῷ πονοῦντι, καὶ παραλλὰξ ἐργαζομένῳ τε καὶ πολεμοῦντι καὶ σῖτον ἢ ὕπνον αἱρουμένῳ, τὴν στρατιὰν ἐσήγαγεν ἐς τόδε τὸ χαράκωμα.", "st": "9.119"}, {"sp": "N", "t": "καὶ ἦν αὐτῷ τοῦτο στρατόπεδόν τε ὁμοῦ καὶ κατὰ τῶν ἐχθρῶν ἐπιτείχισμα ἐπίμηκες, ὅθεν ὁρμώνενος τὴν ἀγορὰν ἀφῃρεῖτο Καρχηδονίους, ὅση κατὰ γῆν αὐτοῖς ἐφέρετο· ὅτι γὰρ μὴ τῷδε τῷ αὐχένι μόνῳ, τὰ λοιπὰ ἡ Καρχηδὼν περίκλυστος ἦν. καὶ τοῦτο πρῶτον αὐτοῖς καὶ μάλιστα ἐγίγνετο λιμοῦ καὶ κακῶν αἴτιον· ἅτε γὰρ τοῦ πλήθους παντὸς ἐκ τῶν ἀγρῶν ἐς τὴν πόλιν ἀνοικισαμένου, οὔτε προϊόντες ποι διὰ τὴν πολιορκίαν, οὔτε ξένων ἐμπόρων διὰ τὸν πόλεμον θαμινὰ ἐπιόντων, μόνῃ τῇ τῆς Λιβύης ἀγορᾷ χρώμενοι, μικρὰ μέν ποτε καὶ διὰ θαλάσσης, ὅτε ὡραῖον εἴη, τὰ πλέονα δὲ κατὰ τὴν γῆν ἐπεκομίζοντο, ἀφῃρημένοι δὲ τότε τὴν ἐκ τῆς γῆς κομιδήν, ἐπιπόνως ᾔσθοντο τοῦ λιμοῦ. Βιθύας δέ, ὅσπερ ἵππαρχος ἦν αὐτοῖς καὶ ἐπέπεμπτο ἐπὶ σῖτον ἐκ πολλοῦ, προσελθεῖν μὲν ἢ βιάσασθαι τὸ χαράκωμα τοῦ Σκιπίωνος οὐκ ἐτόλμα, περιφέρων δὲ τὴν ἀγορὰν ἐς τὰ πόρρω διὰ μακροῦ ναυσὶν ἐσέπεμπεν, ἐφορμουσῶν μὲν τῇ Καρχηδόνι νεῶν τοῦ Σκιπίωνος· ἀλλ’ οὔτε διηνεκῶς οὔτε πυκναὶ συνειστήκεσαν ὡς ἐν ἀλιμένῳ καὶ περικρήμνῳ θαλάσσῃ, παρά τε τὴν πόλιν αὐτὴν οὐκ ἐδύναντο ἀνακωχεύειν, τῶν Καρχηδονίων τοῖς τείχεσιν ἐφεστώτων, καὶ τοῦ κύματος ἐκεῖ μάλιστα διὰ τὰς πέτρας ταρασσομένου. ὅθεν αἱ φορτίδες αἱ Βιθύου, καὶ εἴ τις ἄλλος ἔμπορος ὑπὸ κέρδους ἐθελοκινδύνως ἠπείγετο, φυλάσσοντες ἄνεμον ἐκ πόντου πολὺν πεπετασμένοις τοῖς ἱστίοις διέθεον, ἀδυνάτων οὐσῶν ἔτι τῶν τριήρων ὁλκάδας φερομένας ἱστίῳ καὶ πνεύματι διώκειν. σπανίως μὲν οὖν ἐγίγνετο καὶ μόνον ὅτε βίαιον εἴη πνεῦμα ἐκ πόντου· καὶ ταῦτα δ’, ὅσα φέροιεν αἱ νῆες, Ἀσδρούβας τρισμυρίοις ἀνδράσι μόνοις διένεμεν, οὓς ἐς μάχην ἐπείλεκτο, καὶ τοῦ ἄλλου πλήθους κατεφρόνει· ὅθεν ἐμόχθουν μάλιστα ὑπὸ τοῦ λιμοῦ.", "st": "9.120"}, {"sp": "N", "t": "καὶ ὁ Σκιπίων αἰσθανόμενος ἐπενόει τὸν ἔσπλουν αὐτοῖς τοῦ λιμένος, ἐς δύσιν τε ἀφορῶντα καὶ οὐ πάνυ πόρρω τῆς γῆς ὄντα, ἀποκλεῖσαι. χῶμα οὖν ἐς τὴν θάλασσαν ἔχου μακρόν, ἀρχόμενος μὲν ἀπὸ τῆς ταινίας ἣ μεταξὺ τῆς λίμνης οὖσα καὶ τῆς θαλάσσης γλῶσσα ἐκαλεῖτο, προϊὼν δ’ ἐς τὸ πέλαγος καὶ εὐθύνων ἐπὶ τὸν ἔσπλουν. ἔχου δὲ λίθοις μεγάλοις τε καὶ πυκνοῖς, ἵνα μὴ ὑπὸ τοῦ κλύδωνος διαφέροιντο. καὶ πλάτος τοῦ χώματος τὸ μὲν ἄνω τεσσάρων καὶ εἴκοσι ποδῶν, τὸ δ’ ἐς τὸν βυθὸν καὶ τετραπλάσιον ἦν. τοῖς δὲ Καρχηδονίοις ἀρχομένου μὲν τοῦδε τοῦ ἔργου καταφρόνησις ἦν ὡς χρονίου τε καὶ μακροῦ καὶ ἴσως ἀδυνάτου· προϊόντος δὲ σὺν ἐπείξει τοσοῦδε στρατοῦ, μήτε ἡμέραν ἐκλείποντος ἐπὶ τοῖς ἔργοις μήτε νύκτα, ἔδεισαν, καὶ στόμα ἕτερον ἐπὶ θάτερα τοῦ λιμένος ὤρυσσον ἐς μέσον τὸ πέλαγος, οἷ μηδὲν χῶμα προελθεῖν ἐδύνατο ὑπὸ βάθους τε καὶ πνευμάτων ἀγριωτέρων. διώρυσσον δ’ ἅμα γυναιξὶ καὶ παισίν, ἔνδοθεν ἀρχόμενοι καὶ πάνυ λανθάνοντες· ἅμα δὲ καὶ ναῦς ἐξ ὕλης παλαιᾶς ἐναυπήγουν, πεντήρεις τε καὶ τριήρεις, οὐδὲν ὑπολείποντες εὐψυχίας τε καὶ τόλμης. οὕτω δ’ ἅπαντα ἐπέκρυπτον ὡς μηδὲ τοὺς αἰχμαλώτους ἔχειν τι τῷ Σκιπίωνι σαφὲς εἰπεῖν, ἀλλὰ κτύπον μὲν ἐν τοῖς λιμέσιν ἡμέρας τε καὶ νυκτὸς εἶναι πολὺν ἀπαύστως, τὴν δὲ χρείαν οὐκ εἰδέναι, μέχρι γε δὴ πάντων ἑτοίμων γενομένων οἱ Καρχηδόνιοι τὸ στόμα ἀνέῳξαν περὶ ἕω, καὶ ναυσὶ πεντήκοντα μὲν τριηρετικαῖς, κερκούροις δὲ καὶ μυοπάρωσι καὶ ἄλλοις βραχυτέροις πολλοῖς ἐξέπλεον, ἐς κατάπληξιν ἐσκευασμένοι φοβερῶς.", "st": "9.121"}, {"sp": "N", "t": "Ῥωμαίους δὲ τό τε στόμα ἄφνω γενόμενον καὶ ὁ στόλος ἐπὶ τῷ στόματι ἐς τοσόνδε κατέπληξεν ὡς τοὺς Καρχηδονίους, εἰ αὐτίκα ταῖς ναυσὶ ταῖς Ῥωμαίων ἐπέθεντο, ἠμελημέναις τε ὡς ἐν τειχομαχίᾳ, καὶ οὐδενὸς ναύτου παρόντος οὐδ’ ἐρέτου, ὅλου ἂν τοῦ ναυστάθμου κρατῆσαι. νῦν οὖν (ἁλῶναι γὰρ ἔδει Καρχηδόνα) τότε μὲν ἐς μόνην ἐπίδειξιν ἐπέπλευσαν, καὶ σοβαρῶς ἐπιτωθάσαντες ἀνέστρεφον, τρίτῃ δ’ ἡμέρᾳ μετὰ τοῦτο ἐς ναυμαχίαν καθίσταντο· καὶ οἱ Ῥωμαῖοι τάς τε ναῦς καὶ τἄλλα εὐτρεπισάμενοι ἀντανήγοντο. βοῆς δὲ καὶ παρακελεύσεως ἑκατέρωθεν γενομένης καὶ προθυμίας ἐρετῶν τε καὶ κυβερνητῶν καὶ τῶν ἐπιβατῶν, ὡς ἐν τῷδε λοιπῷ Καρχηδονίοις μὲν τῆς σωτηρίας οὔσης Ῥωμαίοις δὲ τῆς νίκης ἐντελοῦς, πληγαί τε πολλαὶ καὶ τραύματα ποικίλα ἐγίγνετο παρ’ ἀμφοῖν μέχρι μέσης ἡμέρᾳς. ἐν δὲ τῷ πόνῳ τὰ σκάφη τῶν Λιβύων τὰ σμικρὰ ταῖς Ῥωμαϊκαῖς ναυσὶ μεγάλαις οὔσαις ἐς τοὺς ταρσοὺς ὑποτρέχοντα διετίτρη πρύμνας καὶ ἐξέκοπτε πηδάλια καὶ κώπας, καὶ ἄλλα πολλὰ καὶ ποικίλα ἐλύπει, εὐμαρῶς τε ὑποφεύγοντα καὶ εὐμαρῶς ἐπιπλέοντα. ἀκρίτου δ’ ἔτι τῆς ναυμαχίας οὔσης, και τῆς ἡμερας ἐς δειλην τρεπομενης, ἔδοξε τοῖς Καρχηδονίοις ὑποχωρεῖν, οὔ τι κατὰ ἧτταν ἀλλ’ ἐς τὴν ἐπιοῦσαν ὑπερτιθεμένοις.", "st": "9.122"}, {"sp": "N", "t": "καὶ αὐτῶν τὰ σκάφη τὰ βραχύτερα προύφευγε, καὶ τὸν ἔσπλουν προλαβόντα ἐς ἄλληλα ὠθεῖτο ὑπὸ τοῦ πλήθους, καὶ τὸ στόμα βύζην ἀπέκλειεν. ὅθεν αἱ μείζους ἐπανιοῦσαι τὸν ἔσπλουν ἀφῄρηντο, καὶ ἐς τὸ χῶμα κατέφυγον, ὃ πρὸ τοῦ τείχους εὐρύχωρον ἐμπόροις ἐς διάθεσιν φορτίων ἐγεγένητο ἐκ πολλοῦ· καὶ παρατείχισμα ἐπ’ αὐτοῦ βραχὺ ἐν τῷδε τῷ πολέμῳ ἐπεποίητο, ἵνα μὴ ὡς ἐν εὐρυχώρῳ στρατοπεδεύσειάν ποτε οἱ πολέμιοι. ἐς μὲν δὴ τόδε τὸ χῶμα αἱ νῆες αἱ τῶν Καρχηδονίων, ἀπορίᾳ λιμένος, καταφυγοῦσαι μετωπηδὸν ὡρμίσαντο· καὶ τοὺς ἐχθροὺς ἐπιπλέοντας οἱ μὲν ἀπ’ αὐτῶν τῶν νεῶν, οἱ δ’ ἀπὸ τοῦ χώματος, οἱ δ’ ἐκ τοῦ διατειχίσματος ἀπεμάχοντο. Ῥωμαίοις δὲ ὁ μὲν ἐπίπλους ἦν ῥᾴδιος καὶ τὸ μάχεσθαι ναυσὶν ἑστώσαις εὐμαρές, αἱ δ’ ἀναχωρήσεις δι’ ἀναστροφὴν τῶν νεῶν, μακρῶν οὐσῶν, βραδεῖαί τε καὶ δυσχερεῖς ἐπεγίγνοντο· ὅθεν ἀντέπασχον ἐν τῷδε τὰ ὅμοια (ὅτε γὰρ ἐπιστρέφοιεν, ἐπλήσσοντο ὑπὸ τῶν Καρχηδονίων ἐπιπλεόντων), μέχρι νῆες Σιδητῶν πέντε, αἳ φιλίᾳ Σκιπίωνος εἵποντο, τὰς μὲν ἀγκύρας καθῆκαν ἐκ πολλοῦ διαστήματος ἐς τὸ πέλαγος, ἁψάμεναι δ’ ἀπ’ αὐτῶν κάλους μακροὺς εἰρεσίᾳ τοῖς Καρχηδονίοις ἐπέπλεον, καὶ ὅτε ἐγχρίμψειαν, ὑπεχώρουν τοὺς κάλους ἐπισπώμεναι κατὰ πρύμναν, αὖθις τε ῥοθίῳ καταπλέουσαι πάλιν ἀνήγοντο κατὰ πρύμναν. τότε γὰρ ὁ στόλος ἅπας, τὸν νοῦν τῶν Σιδητῶν ὁρῶντές τε καὶ μιμούμενοι, πολλὰ τοὺς ἐχθροὺς ἔβλαπτον. καὶ τὸ ἔργον ἐς νύκτα ἐτελευτα, καὶ ἐς τὴν πόλιν διέφυγον αἱ τῶν Καρχηδονίων νῆες, ὅσαι γε ἔτι ἦσαν ὑπόλοιποι.", "st": "9.123"}, {"sp": "N", "t": "Σκιπίων δὲ γενομένης ἡμέρας ἐπεχειρει τῷ χώματι· καὶ γὰρ ἦν εὔκαιρον ἐπιτείχισμα τοῦ λιμένος. κριοῖς οὖν το παρατείχισμα τύπτων, καὶ μηχανήματα πολλὰ ἐπάγων, μέρος αὐτοῦ κατέβαλεν. οἱ δὲ Καρχηδόνιοι, καίπερ ὑπὸ λιμοῦ καὶ κακώσεως ποικίλης ἐνοχλούμενοι, νυκτὸς ἐξέδραμον ἐπὶ τὰ Ῥωμαίων μηχανήματα, οὐ κατὰ γῆν (οὐ γὰρ ἦν δίοδος) οὐδὲ ναυσὶν (ἁλιτενὴς γὰρ ἦν ἡ θάλασσα), ἀλλὰ γυμνοὶ δᾷδας ἔφερον, οὐχ ἡμμένας ἵνα μὴ μακρόθεν εἶεν καταφανεῖς· ἐς δὲ τὴν θάλασσαν ἐμβάντες ᾗ μή τις ἂν προσεδόκησεν, οἱ μὲν ἄχρι τῶν μαστῶν βρεχόμενοι διεβάδιζον, οἱ δὲ καὶ διένεον, ἕως ἐπὶ τὰ μηχανήματα ἐλθόντες ἐξῆψαν τὸ πῦρ, καὶ κατάφωροι γενόμενοι πολλὰ μὲν ἔπαθον, ἅτε γυμνοὶ τιτρωσκόμενοι, πολλὰ δ’ ἀντέδρασαν ὑπὸ τόλμης· οἳ καὶ τὰς ἀκίδας τῶν βελῶν καὶ τὰς αἰχμὰς ἐν στέρνοις καὶ ὄψεσι φέροντες οὐκ ἀνίεσαν, ὥσπερ θηρία ταῖς πληγαῖς ἐγκείμενοι, μέχρι τὰ μηχανήματα ἐνέπρησαν καὶ τοὺς Ῥωμαίους ἐτρέψαντο θορυβουμένους. ἔκπληξίς τε καὶ τάραχος ἦν ἀνὰ ὅλον τὸ στρατόπεδον, καὶ φόβος οἷος οὐ πρίν, ὑπὸ μανίας γυμνῶν πολεμίων, ὥστε δείσας ὁ Σκιπίων μετὰ ἱππέων ἔξω περιέθει, καὶ τοὺς οἰκείους, εἰ μὴ λήξαιεν τῆς φυγῆς, ἐκέλευε βάλλειν. ἔστι δὲ οὓς ἔβαλε καὶ ἀπέκτεινεν, ἕως οἱ πλείους συνεώσθησαν ἐς τὸ στρατόπεδον ὑπ’ ἀνάγκης, καὶ διενυκτέρευσαν ἔνοπλοι, τὴν ἀπόγνωσιν τῶν ἐχθρῶν δεδιότες. οἱ δὲ τὰς μηχανὰς ἐμπρήσαντες ἐξένεον αὖθις ἐς τὰ οἰκεῖα.", "st": "9.124"}, {"sp": "N", "t": "ἅμα δ’ ἡμέρᾳ Καρχηδόνιοι μέν, οὐκ ἐνοχλουσῶν σφᾶς ἔτι μηχανῶν πολεμίων, τὸ διαπεπτωκὸς τοῦ διατειχίσματος ᾠκοδόμουν, καὶ πύργους ἐν αὐτῷ πολλοὺς ἐποίουν ἐκ διαστήματος, Ῥωμαῖοι δ’ ἑτέρας ἐργασάμενοι μηχανὰς χώματα ἤγειρον ἀντιμέτωπα τοῖς πύργοις, δᾷδά τε συγκεκομμένην καὶ θεῖον ἐν κώθωσι καὶ πίσσαν ἐπ’ αὐτοὺς ἐσφενδόνων, καὶ ἔστιν οὓς τῶν πύργων ἐνεπίμπρασαν, καὶ τοὺς Καρχηδονίους φεύγοντας ἐδίωκον. ὀλισθηρὸς δ’ ἦν ὁ δρόμος ὑφ’ αἵματος πεπηγότος ὑπογύου τε καὶ πολλοῦ, ὥστε τῶν φευγόντων ἀπελίποντο ἄκοντες. ὁ δὲ Σκιπίων τοῦ χώματος ὅλου κατασχὼν ἀπετάφρευεν αὐτό, καὶ τεῖχος ἤγειρεν ἐκ πλίνθων, οὔτε κολοβώτερον τοῦ τῶν πολεμίων οὔτ’ ἐκ μακροῦ διαστήματος ἀπ’ αὐτῶν. ὡς δ’ ἐξείργαστο αὐτῷ καὶ τὸ τεῖχος, τετρακισχιλίους ἐς αὐτὸ ἔπεμψεν, ἐπαφίεναι τοῖς ἐχθροῖς βέλη τε καὶ ἀκόντια σὺν καταφρονήσει. οἱ δὲ ἰσομέτωποι γενόμενοι ἔβαλλον αὐτοὺς ἐπιτυχῶς. καὶ τὸ θέρος ἐς ταῦτα ἀναλώθη.", "st": "9.125"}, {"sp": "N", "t": "χειμῶνος δ’ ἀρχομένου τὴν ἐν τῇ χώρᾳ τῶν Καρχηδονίων δύναμίν τε καὶ συμμάχους ὁ Σκιπίων ἔγνω προκαθελεῖν, ὅθεν αὐτοῖς ἀγορὰ διεπέμπετο. περιπέμψας οὖν ἑτέρωσε ἑτέρους, αὐτὸς ἐς Νέφεριν ἐπὶ Διογένη τὸν μετ’ Ἀσδρούβαν φρουροῦντα τὴν Νέφεριν ἠπείγετο διὰ τῆς λίμνης, καὶ Γάιον Λαίλιον κατὰ γῆν περιέπεμπεν. ὡς δὲ ἀφίκετο, δύο σταδίους ἀποσχὼν τοῦ Διογένους ἐστρατοπέδευε, καὶ Γολόσσην καταλιπὼν ἐγχειρεῖν ἀπαύστως τῷ Διογένει αὐτὸς ἐπὶ Καρχηδόνος ἠπείγετο· ὅθεν ἐς Νέφερίν τε καὶ Καρχηδόνα διετρόχαζεν, ἀεὶ τὰ γιγνόμενα ἐφορῶν. δύο δὲ τοῦ Διογένους μεσοπυργίων καταπεσόντων ἧκεν ὁ͂ Σκιπίων, καὶ χιλίους ἐπιλέκτους ὄπισθεν τοῦ Διογένους ἐνεδρεύσας, ἑτέροις ἐκ μετώπου τρισχιλίοις, ἀριστίνδην καὶ τοῖσδε ἐπιλεγομένοις, ἐπέβαινεν ἐπὶ τὰ πεπτωκότα τῶν μεσοπυργίων, οὐκ ἀθρόους ἀναβιβάζων, ἀλλὰ κατὰ μέρη πυκνοὺς ἐπ’ ἀλλήλοις, ἵνα μηδὲ βιασθέντες οἱ πρῶτοι φυγεῖν δύναιντο διὰ τοὺς ἑπομένους. πολλῆς δὲ βοῆς οὔσης καὶ πόνου, καὶ τῶν Λιβύων ἐς ταῦτα ἐπεστραμμένων, οἱ χίλιοι, καθάπερ αὐτοῖς προείρητο, οὐδενὸς ἐς αὐτοὺς ἀποβλέποντος οὐδ’ ὑπονοοῦντος ἐνέπεσον ἐς τὸ χαράκωμα εὐτόλμως, καὶ διέσπων αὐτὸ καὶ ὑπερέβαινον. καὶ τῶν πρώτων ἔνδον γενομένων αἴσθησις ἐγίγνετο ταχεῖα, καὶ ἔφευγον οἱ Λίβυες, οὐχ ὅσους ἑώρων, ἀλλὰ πολὺ πλέονας ἡγούμενοι τοὺς ἐσελθόντας εἶναι. Γολόσσης δ’ αὐτοῖς ἐπιτρέχων σὺν Νομάσι πολλοῖς καὶ ἐλέφασι πολὺν εἰργάζετο φόνον, ὡς ἀπολέσθαι μὲν ἐς ἑπτακισμυρίους σὺν τοῖς ἀχρείοις, ἁλῶναι δ’ ἐς μυρίους, διαφυγεῖν δ’ ἀμφὶ τοὺς τετρακισχιλίους. ἑάλω δὲ καὶ ἡ πόλις ἡ Νέφερις ἐπὶ τῷ στρατοπέδῳ, δύο καὶ εἴκοσιν ἡμέραις ἄλλαις πολιορκηθεῖσα πρὸς τοῦ Σκιπίωνος πάνυ κακοπαθῶς ἐν χειμῶνι καὶ ψυχρῷ χωρίῳ. τὸ δὲ ἔργον τόδε μάλιστα συνη?́νεγκεν ἐς τὴν τῆς Καρχηδόνος ἅλωσιν. ἥδε γὰρ ἡ στρατιὰ τὴν ἀγορὰν αὐτοῖς διεπόρθμευε, καὶ ἐς τόδε τὸ στρατόπεδον οἱ Λίβυες ἀφορῶντες ἐθάρρουν. τότε δ’ αὐτοῦ ληφθέντος καὶ τὰ λοιπὰ τῆς Λιβύης χωρία τοῖς στρατηγοῖς Σκιπίωνος προσεχώρει ἢ οὐ δυσχερῶς ἐλαμβάνετο. ἥ τε ἀγορὰ τοὺς Καρχηδονίους ἐπέλιπε, καὶ οὐδὲν οὔτ’ ἐκ Λιβύης ἀλλοτρίας ἤδη γενομένης οὔτ’ ἀλλαχόθεν αὐτοῖς καταπλεῖν ἐδύνατο, διά τε τὸν πόλεμον αὐτὸν καὶ τὴν ὥραν χειμέριον οὖσαν.", "st": "9.126"}, {"sp": "N", "t": "ἀρχομένου δ’ ἦρος ὁ μὲν Σκιπίων ἐπεχείρει τῇ τε Βύρσῃ καὶ τῶν λιμένων τῷ καλουμένῳ Κώθωνι, ὁ δὲ Ἀσδρούβας νυκτὸς ἐνεπίμπρη τὸ μέρος τοῦ Κώθωνος τὸ τετράγωνον. ἐλπίσας δ’ ἔτι τὸν Σκιπίωνα ἐπιθήσεσθαι, καὶ πρὸς τόδε τῶν Καρχηδονίων ἐπεστραμμένων, ἔλαθε Λαίλιος ἐπὶ θάτερα τοῦ Κώθωνος ἐς τὸ περιφερὲς αὐτοῦ μέρος ἀνελθών. βοῆς δ’ ὡς ἐπὶ νίκῃ γενομένης οἱ μὲν ἔδεισαν, οἱ δὲ πανταχόθεν ἤδη καταφρονοῦντες ἐβιάζοντο τὴν ἀνάβασιν, ξύλα καὶ μηχανήματα καὶ σανίδας ἐπὶ τὰ διαστήματα διατιθέντες, ἀσθενῶν τὰ σώματα τῶν φυλάκων ὑπὸ τοῦ λιμοῦ γεγονότων, καὶ ταῖς γνώμαις ἀπαγορευόντων. ληφθέντος δὲ τοῦ περὶ τὸν Κώθωνα τείχους, τὴν ἀγορὰν ἐγγὺς οὖσαν ὁ Σκιπίων κατέλαβεν. οὐδέν τε ὡς ἐν ἑσπέρᾳ πλέον ἔτι δυνάμενος, ἐν τοῖς ὅπλοις διενυκτέρευσε μεθ’ ἁπάντων. ἀρχομένης δὲ τῆς ἡμέρας ἑτέρους ἀκμῆτας ἐκάλει τετρακισχιλίους, οἳ ἐσιόντες ἱερὸν Ἀπόλλωνος, οὗ τό τε ἄγαλμα κατάχρυσον ἦν καὶ δῶμα αὐτῷ χρυσήλατον ἀπὸ χιλίων ταλάντων σταθμοῦ περιέκειτο, ἐσύλων καὶ ταῖς μαχαίραις ἔκοπτον, ἀμελήσαντες τῶν ἐφεστώτων, ἕως ἐμερίσαντο καὶ ἐπὶ τὸ ἔργον ἐτράποντο.", "st": "9.127"}, {"sp": "N", "t": "Σκιπίωνι δ’ ἦν μὲν ἐπὶ τὴν Βύρσαν ἡ σπουδή· τὸ γὰρ ὀχυρώτατον τῆς πόλεως ἦν, καὶ οἱ πλέονες ἐς αὐτὴν συνεπεφεύγεσαν. τριῶν δ’ οὐσῶν ἀπὸ τῆς ἀγορᾶς ἀνόδων ἐς αὐτήν, οἰκίαι πυκναὶ καὶ ἑξώροφοι πανταχόθεν ἦσαν, ὅθεν οἱ Ῥωμαῖοι βαλλόμενοι τὰς πρώτας τῶν οἰκιῶν κατέλαβον, καὶ ἀπ’ αὐτῶν ἠμύνοντο τοὺς ἐπὶ τῶν πλησίον. ὅτε δ’ αὐτῶν κρατήσειαν, ξύλα καὶ σανίδας τοῖς διαστήμασι τῶν στενωπῶν ἐπιτιθέντες διέβαινον ὡς ἐπὶ γεφυρῶν. καὶ ὅδε μὲν ὁ πόλεμος ἦν ἐπὶ τῶν τεγῶν ἄνω, ἕτερος δ’ ἐν τοῖς στενωποῖς κατὰ τοὺς ἀπαντῶντας. στόνου δὲ καὶ οἰμωγῆς καὶ βοῆς πάντα καὶ ποικίλων παθῶν ἐνεπίμπλατο, κτεινομένων τε ἐν χερσί, καὶ ζώντων ἔτι ῥιπτουμένων ἄνωθεν ἀπὸ τῶν τεγῶν ἐς τὸ ἔδαφος, καὶ φερομένων ἐνίων ἐπὶ δόρατα ὀρθὰ ἢ αἰχμὰς ἄλλας ἢ ξίφη. ἐνεπίμπρη δ’ οὐδὲν οὐδείς πω διὰ τοὺς ἐπὶ τῶν τεγῶν, ἕως ἐπὶ τὴν Βύρσαν ἧκεν ὁ Σκιπίων· καὶ τότε τοὺς τρεῖς ὁμοῦ στενωποὺς ἐνεπίμπρη, καὶ τὸ ἀεὶ πιμπράμενον ἑτέροις ὁδοποιεῖν ἐκέλευεν, ἵν’ εὐμαρῶς ὁ στρατὸς ἀλλασσόμενος διαθέοι.", "st": "9.128"}, {"sp": "N", "t": "ἄλλη δ’ ἦν ἐκ τοῦδε ὄψις ἑτέρων κακῶν, τοῦ μὲν πυρὸς ἐπιφλέγοντος πάντα καὶ καταφέροντος, τῶν δε ἀνδρῶν τὰ οἰκοδομηματα οὐ διαιρούντων ἐς ὀλίγον, ἀλλ’ ἀθρόα βιαζομένων ἀνατρέπειν. ὅ τε γὰρ κτύπος ἐκ τοῦδε πολὺ πλείων ἐγίγνετο, καὶ μετὰ τῶν λίθων ἐξέπιπτον ἐς τὸ μέσον ἀθρόοι νεκροί. ζῶντές τε ἕτεροι, πρεσβῦται μάλιστα καὶ παιδία καὶ γύναια, ὅσα τοῖς μυχοῖς τῶν οἰκιῶν ἐκέκρυπτο, οἱ μὲν καὶ τραύματα φέροντες οἱ δ’ ἡμίφλεκτοι, φωνὰς ἀηδεῖς ἀφιέντες. ἕτεροι δ’, ὡς ἀπὸ τοσοῦδε ὕψους μετὰ λίθων καὶ ξύλων καὶ πυρὸς ὠθούμενοι καὶ καταπίπτοντες, ἐς πολλὰ σχήματα κακῶν διεσπῶντο ῥηγνύμενοί τε καὶ κατασπασσόμενοι. καὶ οὐδ’ ἐς τέλος αὐτοῖς ταῦτα ἀπέχρη· λιθολόγοι γὰρ ὅσοι πελέκεσι καὶ ἀξίναις καὶ κοντοῖς τὰ πίπτοντα μετέβαλλόν τε καὶ ὡδοποίουν τοῖς διαθέουσιν, οἱ μὲν τοῖς πελέκεσι καὶ ταῖς ἀξίναις, οἱ δὲ ταῖς χηλαῖς τῶν κοντῶν, τούς τε νεκροὺς καὶ τοὺς ἔτι ζῶντας ἐς τὰ τῆς γῆς κοῖλα μετέβαλλον ὡς ξύλα καὶ λίθους ἐπισύροντες ἢ ἀνατρέποντες τῷ σιδήρῳ, ἦν τε ἄνθρωπος ἀναπλήρωμα βόθρου. μεταβαλλόμενοι δ’ οἱ μὲν ἐς κεφαλὰς ἐφέροντο, καὶ τὰ σκέλη σφῶν ὑπερίσχοντα τῆς γῆς ἤσπαιρον ἐπὶ πλεῖστον· οἱ δ’ ἐς μὲν τοὺς πόδας ἔπιπτον κάτω, καὶ ταῖς κεφαλαῖς ὑπερεῖχον ὑπὲρ τὸ ἔδαφος, ἵπποι δ’ αὐτοὺς διαθέοντες ἐς τὰς ὄψεις ἢ τὸν ἐγκέφαλον ἐκόλαπτον, οὐχ ἑκόντων τῶν ἐποχουμένων ἀλλ’ ὑπὸ σπουδῆς, ἐπεὶ οὐδ’ οἱ λιθολόγοι ταῦτ’ ἔδρων ἑκόντες· ἀλλ’ ὁ τοῦ πολέμου πόνος καὶ ἡ δόξα τῆς νίκης ἐγγὺς καὶ ἡ τοῦ στρατοῦ σπουδή, καὶ κήρυκες ὁμοῦ καὶ σαλπικταὶ πάντα θορυβοῦντες, χιλίαρχοί τε καὶ λοχαγοὶ μετὰ τῶν τάξεων ἐναλλασσόμενοι καὶ διαθέοντες, ἔνθους ἅπαντας ἐποίουν καὶ ἀμελεῖς τῶν ὁρωμένων ὑπὸ σπουδῆς.", "st": "9.129"}, {"sp": "N", "t": "καὶ ταῦτα πονουμένων ἐδαπανήθησαν ἓξ ἡμέραι τε καὶ νύκτες, τῆς μὲν στρατιᾶς ἐναλλασσομένης, ἵνα μὴ κάμοιεν ὑπ’ ἀγρυπνίας καὶ κόπου καὶ φόνου καὶ ὄψεως ἀηδοῦς, Σκιπίωνος δ’ ἀπαύστως ἐφεστῶτος ἢ διαθέοντος ἀύπνου, καὶ σῖτον οὕτως ἐπὶ τῶν ἔργων αἱρουμένου, μέχρι κάμνων καὶ παρειμένος ἐκαθέζετο ἐφ’ ὑψηλοῦ, τὰ γιγνόμενα ἐφορῶν. πολλῶν δ’ ἔτι πορθουμένων, καὶ τοῦ κακοῦ μακροτάτου δοκοῦντος ἔσεσθαι, προσέφυγον ἐβδόμης ἡμέρας αὐτῷ τινες ἐστεμμένοι στέμματα Ἀσκληπίεια· τόδε γὰρ ἦν τὸ ἱερὸν ἐν ἀκροπόλει μάλιστα τῶν ἄλλων ἐπιφανὲς καὶ πλούσιον, ὅθεν οἵδε τὰς ἱκετηρίας λαβόντες ἐδέοντο τοῦ Σκιπίωνος περὶ μόνης συνθέσθαι σωτηρίας τοῖς ἐθέλουσιν ἐπὶ τῷδε τῆς Βύρσης ἐξιέναι, ὁ δὲ ἐδίδου, χωρὶς αὐτομόλων. καὶ ἐξῄεσαν αὐτικα μυριάδες πέντε ἀνδρῶν ἅμα καὶ γυναικῶν, ἀνοιχθέντος αὐτοῖς στενοῦ διατειχίσματος. καὶ οὗτοι μὲν ἐφυλάσσοντο, ὅσοι δ’ αὐτόμολοι Ῥωμαίων ἦσαν, ἀμφὶ τοὺς ἐνακοσίους μάλιστα, ἀπογνόντες αὑτῶν ἐς τὸ Ἀσκληπιεῖον ἀνέδραμον μετ’ Ἀσδρούβα καὶ τῆς γυναικὸς τῆς Ἀσδρούβα καὶ δύο παίδων ἀρρένων. ὅθεν εὐμαρῶς ἀεὶ ἐμάχοντο, καίπερ ὄντες ὀλίγοι, διὰ τὸ ὕψος τοῦ τεμένους καὶ τὸ ἀπόκρημνον, ἐς ὃ καὶ παρὰ τὴν εἰρήνην διὰ βαθρῶν ἑξήκοντα ἀνέβαινον. ὡς δὲ ὅ τε λιμὸς αὐτοὺς καθῄρει καὶ ἡ ἀγρυπνία καὶ ὁ φόβος καὶ ὁ πόνος, τοῦ κακοῦ προσπελάζοντος, τὸ μὲν τέμενος ἐξέλιπον, ἐς δὲ τὸν νεὼν αὐτοῦ καὶ τὸ τέγος ἀνέτρεχον.", "st": "9.130"}, {"sp": "N", "t": "κἀν τούτῳ λαθὼν ὁ Ἀσδρούβας ἔφυγε πρὸς τὸν Σκιπίωνα μετὰ θαλλῶν· καὶ αὐτὸν ὁ Σκιπίων ἐκάθισε πρὸ ποδῶν ἑαυτοῦ, καὶ τοῖς αὐτομόλοις ἐπεδείκνυεν. οἱ δ’ ὡς εἶδον, ᾔτησαν ἡσυχίαν σφίσι γενέσθαι, καὶ γενομένης Ἀσδρούβᾳ μὲν ἐλοιδορήσαντο πολλὰ καὶ ποικίλα, τὸν δὲ νεὼν ἐνέπρησάν τε καὶ κατεκαύθησαν. τὴν δὲ γυναῖκα τοῦ Ἀσδρούβα λέγουσιν, ἀπτομένου τοῦ πυρὸς ἀντικρὺ τοῦ Σκιπίωνος γενομένην, κατακοσμήσασθαί τε ὡς ἐν συμφοραῖς ἐδύνατο, καὶ παραστησαμένην τὰ τέκνα εἰπεῖν ἐς ἐπήκοον τοῦ Σκιπίωνος· “σοὶ μὲν οὐ νέμεσις ἐκ θεῶν, ὦ Ῥωμαῖε· ἐπὶ γὰρ πολεμίαν ἐστράτευσας· Ἀσδρούβαν δὲ τόνδε πατρίδος τε καὶ ἱερῶν καὶ ἐμοῦ καὶ τέκνων προδότην γενόμενον οἵ τε Καρχηδόνος δαίμονες ἀμύναιντο, καὶ σὺ μετὰ τῶν δαιμόνων.” εἶτ’ ἐς τὸν Ἀσδρούβαν ἐπιστρέψασα εἶπεν· “ὦ μιαρὲ καὶ ἄπιστε καὶ μαλακώτατε ἀνδρῶν, ἐμὲ μὲν καὶ τοὺς ἐμοὺς παῖδας τόδε τὸ πῦρ θάψει· σὺ δὲ τίνα κοσμήσεις θρίαμβον ὁ τῆς μεγάλης Καρχηδόνος ἡγεμών; τίνα δ’ οὐ δώσεις δίκην τῷδε ᾧ παρακαθέζῃ;” τοσαῦτ’ ὀνειδίσασα κατέσφαξε τοὺς παῖδας, καὶ ἐς τὸ πῦρ αὐτούς τε καὶ ἑαυτὴν ἐπέρριψεν.", "st": "9.131"}, {"sp": "N", "t": "ὧδε μέν φασι τὴν Ἀσδρούβα γυναῖκα, ὡς αὐτὸν ἐχρῆν Ἀσδρούβαν, εἰποῦσαν ἀποθανεῖν· ὁ δὲ Σκιπίων πόλιν ὁρῶν ἑπτακοσίοις ἔτεσιν ἀνθήσασαν ἀπὸ τοῦ συνοικισμοῦ, καὶ γῆς τοσῆσδε καὶ νήσων καὶ θαλάσσης ἐπάρξασαν, ὅπλων τε καὶ νεῶν καὶ ἐλεφάντων καὶ χρημάτων εὐπορήσασαν ἴσα ταῖς ἀρχαῖς ταῖς μεγίσταις, τόλμῃ δὲ καὶ προθυμίᾳ πολὺ διασχοῦσαν, ἥ γε καὶ ναῦς καὶ ὅπλα πάντα περιῃρημένη τρισὶν ὅμως ἔτεσιν ἀντέσχε πολέμῳ τοσῷδε καὶ λιμῷ, τότε ἄρδην τελευτῶσαν ἐς πανωλεθρίαν ἐσχάτην, λέγεται μὲν δακρῦσαι καὶ φανερὸς γενέσθαι κλαίων ὑπὲρ πολεμίων, ἐπὶ πολὺ δ’ ἔννους ἐφ’ ἑαυτοῦ γενόμενός τε, καὶ συνιδὼν ὅτι καὶ πόλεις καὶ ἔθνη καὶ ἀρχὰς ἁπάσας δεῖ μεταβαλεῖν ὥσπερ ἀνθρώπους δαίμονα, καὶ τοῦτ’ ἔπαθε μὲν Ἴλιον, εὐτυχής ποτε πόλις, ἔπαθε δὲ ἡ Ἀσσυρίων καὶ Μήδων καὶ Περσῶν ἐπ’ ἐκείνοις ἀρχὴ μεγίστη γενομένη, καὶ ἡ μάλιστα ἔναγχος ἐκλάμψασα ἡ Μακεδόνων, εἴτε ἑκὼν εἴτε προφυγόντος αὐτὸν τοῦδε τοῦ ἔπους, ἔσσεται ἦμαρ ὅταν ποτ’ ὀλώλῃ Ἴλιος ἱρὴ καὶ Πρίαμος καὶ λαὸς ἐϋμμελίω Πριάμοιο.", "st": "9.132"}, {"sp": "N", "t": "Πολυβίου δ’ αὐτοῦ ἐρομένου σὺν παρρησίᾳ (καὶ γὰρ ἦν αὐτοῦ καὶ διδάσκαλος) ὅ τι βούλοιτο ὁ λόγος, φασὶν οὐ φυλαξάμενον ὀνομάσαι τὴν πατρίδα σαφῶς, ὑπὲρ ἧς ἄρα, ἐς τἀνθρώπεια ἀφορῶν, ἐδεδίει.", "st": "9.132"}, {"sp": "N", "t": "καὶ τάδε μὲν Πολύβιος αὐτὸς ἀκούσας συγγράφει· Σκιπίων δ’, ἐπεὶ κατέσκαπτο Καρχηδών, ἐπὶ μέν τινα ἡμερῶν ἀριθμὸν ἐπέτρεψε τῇ στρατιᾷ διαρπάζειν ὅσα μὴ χρυσὸς ἢ ἄργυρος ἢ ἀναθήματα ἦν, μετὰ δὲ τοῦτ’ ἀριστεῖα πολλὰ διαδοὺς ἅπασι, χωρὶς τῶν ἐς τὸ Ἀπολλώνιον ἁμαρτόντων, ναῦν ὀξυτάτην κοσμήσας λαφύροις ἄγγελον τῆς νίκης ἔστειλεν ἐς Ῥώμην, ἐς δὲ Σικελίαν περιέπεμπεν, ὅσα Καρχηδόνιοι σφῶν ἀναθήματα κοινὰ πολεμοῦντες ἔλαβον, ἐλθόντας ἐπιγιγνώσκειν καὶ κομίζεσθαι· ὃ καὶ μάλιστα αὐτὸν ἐδημαγώγησεν ὡς μετὰ τοῦ δυνατοῦ φιλάνθρωπον. ἀποδόμενος δὲ τὴν λείαν τὴν περισσήν, ὅπλα καὶ μηχανήματα καὶ ναῦς ἀχρήστους Ἄρει καὶ Ἀθηνᾷ διαζωσάμενος αὐτὸς ἔκαιε κατὰ τὰ πάτρια.", "st": "9.133"}, {"sp": "N", "t": "οἱ δ’ ἐν ἄστει ὡσαύτως τὴν ναῦν ἰδόντες καὶ τῆς νίκης περὶ δείλην ἑσπέραν πυθόμενοι ἐς τὰς ὁδοὺς ἐξεπήδων καὶ διενυκτέρευον μετ’ ἀλλήλων, ἡδόμενοι καὶ συμπλεκόμενοι ὡς ἄρτι μὲν ἐλεύθεροι φόβων γεγονότες, ἄρτι δ’ ἄρχοντες ἑτέρων ἀσφαλῶς, ἄρτι δὲ βέβαιον τὴν πόλιν ἔχοντες, καὶ νενικηκότες οἵαν οὔτινα πρότερον ἄλλην νικην. πολλὰ μὲν γὰρ αὑτοῖς συνῄδεσαν ἔργα λαμπρά, πολλὰ δε τοῖς πατρασιν ἔς τε Μακεδόνας καὶ Ἴβηρας καὶ ἐς Ἀντίοχον τὸν μέγαν ἔναγχος καὶ περὶ αὐτὴν Ἰταλίαν· πόλεμον δ’ οὐδένα ἄλλον οὕτως ἐπὶ θύραις ἐπίφοβον αὑτοῖς ᾔδεσαν, διά τε ἀνδρείαν καὶ φρόνημα καὶ τόλμαν ἐχθρῶν καὶ ἀπιστίαν ἐν σφίσιν ἐπικίνδυνον γενόμενον. ἀνέφερον δὲ καὶ ὧν ἔπαθον ὑπὸ Καρχηδονίων ἔν τε Σικελίᾳ καὶ Ἰβηρίᾳ καὶ περὶ αὐτὴν Ἰταλίαν ἑκκαίδεκα ἔτεσιν, Ἀννίβου τετρακόσια ἐμπρήσαντος ἄστη καὶ μυριάδας ἀνδρῶν τριάκοντα ἐν μόναις μάχαις ἀνελόντος, ἐπί τε τὴν Ῥώμην πολλάκις ἐλάσαντος καὶ ἐς ἔσχατον κινδύνου συναγαγόντος. ὧν ἐνθυμούμενοι μάλιστα ἐξίσταντο περὶ τῆς νίκης ἐς ἀπιστίαν αὐτῆς, καὶ αὖθις ἀνεπυνθάνοντο ἀλλήλων εἰ τῷ ὄντι Καρχηδὼν κατέσκαπται· ἐλεσχήνευόν τε δι’ ὅλης νυκτὸς ὅπως μὲν αὐτῶν τὰ ὅπλα περιῃρέθη καὶ ὅπως αὐτίκα παρὰ δόξαν ἐτεκτήναντο ἕτερα, ὅπως δὲ τὰς ναῦς ἀφῃρέθησαν καὶ στόλον ἐπήξαντο πάλιν ἐξ ὕλης παλαιᾶς, τό τε στόμα τοῦ λιμένος ὡς ἀπεκλείσθη, καὶ στόμα ὡς ὠρύξαντο ἕτερον ὀλίγαις ἡμέραις. καὶ τὸ τῶν τειχῶν ὕψος αὐτοῖς διὰ στόματος ἦν, καὶ τὰ τῶν λίθων μεγέθη, καὶ τὸ πῦρ ὃ πολλάκις ταῖς μηχαναῖς ἐπήνεγκαν. ὅλως τε τὸν πόλεμον ὡς ὁρῶντες ἄρτι γιγνόμενον ἀλλήλοις διετύπουν, καὶ ἐς τὰς φαντασίας τῶν λεγομένων τῷ σχήματι τοῦ σώματος συνεφέροντο. καὶ τὸν Σκιπίωνα ὁρᾶν ἐδόκουν ἐπὶ κλιμάκων, ἐπὶ νεῶν, ἐν π ύλαις, ἐν μάχαις, πανταχοῦ διαθεοντα. οὕτω μὲν οι Ῥωμαῖοι διενυκτέρευσαν,", "st": "9.134"}, {"sp": "N", "t": "ἅμα δ’ ἡμέρᾳ θυσίαι τε καὶ πομπαὶ τοῖς θεοῖς ἐγίγνοντο κατὰ φυλήν, καὶ ἀγῶνες ἐπὶ τούτοις καὶ θέαι ποικίλαι.", "st": "9.135"}, {"sp": "N", "t": "δέκα δὲ σφῶν αὐτῶν ἡ βουλὴ τοὺς ἀριστους ἔπεμπε διαθησομένους Λιβύην μέτα Σκιπίωνος ἐς τὸ Ῥωμαίων συμφέρον· οἳ Καρχηδόνος μὲν εἴ τι περίλοιπον ἔτι ἦν, ἔκριναν κατασκάψαι Σκιπίωνα, καὶ οἰκεῖν αὐτὴν ἀπεῖπον ἅπασι, καὶ ἐπηράσαντο, μάλιστα περὶ τῆς Βύρσης, εἴ τις οἰκήσειεν αὐτὴν ἢ τὰ καλούμενα Μέγαρα· ἐπιβαίνειν δ’ οὐκ ἀπεῖπον. ὅσαι δὲ πόλεις συνεμεμαχήκεσαν τοῖς πολεμίοις ἐπιμόνως, ἔδοξε καθελεῖν ἁπάσας· καὶ ὅσαι Ῥωμαίοις ἐβεβοηθήκεσαν, χώραν ἔδωκαν ἑκάστῃ τῆς δορικτήτου, καὶ πρῶτον μάλιστα Ἰτυκαίοις τὴν μέχρι Καρχηδόνος αὐτῆς καὶ Ἱππῶνος ἐπὶ θάτερα. τοῖς δὲ λοιποῖς φόρον ὥρισαν ἐπὶ τῇ γῇ καὶ ἐπὶ τοῖς σώμασιν, ἀνδρὶ καὶ γυναικὶ ὁμοίως. καὶ στρατηγὸν ἐτήσιον αὐτοῖς ἐκ Ῥώμης ἐπιπέμπειν ἔκριναν. οἱ μὲν δὴ ταῦτα προστάξαντες ἀπέπλεον ἐς Ῥώμην, ὁ δὲ Σκιπίων ἐποίει τὰ δόξαντα, καὶ θυσίας ἐτέλει καὶ ἀγῶνας ἐπὶ τῇ νίκῃ. ὡς δὲ αὐτῷ πάντα ἐξετετέλεστο, διαπλεύσας ἐπιφανέστατα δὴ πάντων διεθριάμβευε πολύχρυσον θρίαμβον, ἀγαλμάτων τε γέμοντα καὶ ἀναθημάτων, ὅσα Καρχηδόνιοι χρόνῳ πολλῷ και συνεχέσι νίκαις ἐκ πάσης γῆς συνενηνόχεσαν ἐς Λιβύην. τότε δ’ ἦν ὅτε καὶ κατὰ Μακεδόνων, ἁλόντος Ἀνδρισκου τοῦ ψευδοφιλίππου, τρίτος ἤγετο θρίαμβος, καὶ κατὰ τῆς Ἑλλάδος πρῶτος ὑπὸ Μομμίου. καὶ ἦν ταῦτα ἀμφὶ τὰς ἑξήκοντα καὶ ἑκατὸν ὀλυμπιάδας.", "st": "9.135"}, {"sp": "N", "t": "χρόνῳ δ’ ὕστερον, Γαΐου Γράκχου δημαρχοῦντος ἐν Ῥώμῃ καὶ στάσεων οὐσῶν ἐξ ἀπορίας, ἔδοξε κληρούχους ἐς Λιβύην πέμπειν ἑξακισχιλίους, διαγραφομένων δ’ ἀμφὶ τὴν Καρχηδόνα τῶν θεμελίων λύκοι τὰ θεμέλια ἀθρόα διέσπασαν καὶ συνέχεαν. καὶ τότε μὲν ἀνέσχεν ἡ βουλὴ τοῦ συνοικισμοῦ· χρόνῳ δὲ αὖθις, ὁπότε Γάιος Καῖσαρ ὁ καὶ δικτάτωρ ὕστερον αὐτοῖς διηνεκὴς γενόμενος Πομπήιον ἐς Αἴγυπτον ἐδίωκε καὶ τοὺς Πομπηίου φίλους ἐς Λιβύην ἀπ’ Αἰγύπτου, λέγεται, τῇ Καρχηδόνι παραστρατοπεδεύων, ὑπ’ ἐνυπνίου στρατὸν πολὺν ἰδὼν κλαίοντα ἐνοχληθῆναι, καὶ αὐτίκα ἑαυτῷ ἐς μνήμην ὑπογράψασθαι Καρχηδόνα συνοικίζειν. καὶ μετ’ οὐ πολὺ τῶν ἀπόρων αὐτὸν ἐς Ῥώμην ἐπανελθόντα περὶ γῆς παρακαλούντων, συνέτασσεν ὡς πέμψων τοὺς μὲν ἐς τὴν Καρχηδόνα τοὺς δ’ ἐς Κόρινθον. ἀλλ’ ὅδε μὲν θᾶσσον ἀνῃρέθη πρὸς τῶν ἐχθρῶν ἐν τῷ Ῥωμαίων βουλευτηρίῳ, ὁ δ’ ἐκείνου παῖς Ἰούλιος Καῖσαρ, ὁ Σεβαστὸς ἐπίκλησιν, ἐντυχὼν ἄρα ταῖς ὑπογραφαῖς τοῦ πατρὸς συνῴκισε τὴν νῦν Καρχηδόνα, ἀγχοτατω μάλιστα ἐκείνης, φυλαξάμενος τῆς πάλαι τὸ ἐπάρατον. οἰκήτοράς τε Ῥωμαίους μὲν αὐτὸν τρισχιλίους μάλιστα πυνθάνομαι, τοὺς δὲ λοιποὺς ἐκ τῶν περιοίκων συναγαγεῖν. ὧδε μὲν Λιβύης τῆς ὑπὸ Καρχηδονίοις Ῥωμαῖοι κατέσχον, καὶ Καρχηδόνα κατέσκαψάν τε καὶ συνῴκισαν αὖθις μετὰ ἔτη τῆς κατασκαφῆς ἑκατὸν καὶ δύο.", "st": "9.136"}], []);})();
